# ══════════════════════════════════════════════════════════════════════════════
# 🗄️  МИГРАЦИЯ БД
# ══════════════════════════════════════════════════════════════════════════════

def freeze_run_sync_migration(conn: sqlite3.Connection, cur: sqlite3.Cursor) -> None:
    """
    Вызывается из run_sync_migration() в frog_bot.py.
    Создаёт 4 таблицы фриз-ивента если их нет, добавляет недостающие
    колонки в frogs (freeze-специфичные поля).
    """
    # ── 1. freeze_state — одна строка, глобальное состояние ────────────────────
    cur.executescript("""
        CREATE TABLE IF NOT EXISTS freeze_state (
            id              INTEGER PRIMARY KEY CHECK (id = 1),
            status          TEXT    NOT NULL DEFAULT 'INACTIVE',
            started_at      REAL    DEFAULT 0,
            ends_at         REAL    DEFAULT 0,
            total_nft       INTEGER DEFAULT 10,
            remaining_nft   INTEGER DEFAULT 10,
            heat            INTEGER DEFAULT 0,
            daily_throws    INTEGER DEFAULT 0,
            pool_throws     INTEGER DEFAULT 0
        );
        INSERT OR IGNORE INTO freeze_state(id) VALUES(1);

        -- 2. freeze_throws — каждый бросок кубика
        CREATE TABLE IF NOT EXISTS freeze_throws (
            id      INTEGER PRIMARY KEY AUTOINCREMENT,
            uid     INTEGER NOT NULL,
            ts      REAL    NOT NULL,
            roll    INTEGER NOT NULL,
            won     INTEGER DEFAULT 0,
            pool    TEXT    DEFAULT 'main',
            source  TEXT    DEFAULT ''
        );
        CREATE INDEX IF NOT EXISTS idx_fz_throws_uid ON freeze_throws(uid);
        CREATE INDEX IF NOT EXISTS idx_fz_throws_ts  ON freeze_throws(ts);

        -- 3. freeze_payments — дедупликация по telegram_charge_id
        CREATE TABLE IF NOT EXISTS freeze_payments (
            charge_id  TEXT    PRIMARY KEY,
            uid        INTEGER NOT NULL,
            pkg        INTEGER NOT NULL,
            stars      INTEGER NOT NULL,
            cubes      INTEGER NOT NULL,
            ts         REAL    NOT NULL
        );

        -- 4. freeze_heat_log — история шкалы (для аналитики)
        CREATE TABLE IF NOT EXISTS freeze_heat_log (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            ts          REAL    NOT NULL,
            heat_before INTEGER NOT NULL,
            heat_after  INTEGER NOT NULL,
            delta       INTEGER NOT NULL,
            reason      TEXT    DEFAULT ''
        );

        -- 5. freeze_quiz — ответы игроков на квиз
        CREATE TABLE IF NOT EXISTS freeze_quiz (
            uid    INTEGER PRIMARY KEY,
            answer TEXT    NOT NULL,
            ts     REAL    NOT NULL,
            cubes_awarded INTEGER DEFAULT 0
        );

        -- 6. freeze_repost — верификация репостов (1 на uid)
        CREATE TABLE IF NOT EXISTS freeze_repost (
            uid INTEGER PRIMARY KEY,
            ts  REAL    NOT NULL
        );

        -- 7. freeze_refs — рефералы засчитанные за ивент
        CREATE TABLE IF NOT EXISTS freeze_refs (
            referrer_id  INTEGER NOT NULL,
            referred_id  INTEGER NOT NULL,
            ts           REAL    NOT NULL,
            PRIMARY KEY (referrer_id, referred_id)
        );

        -- 8. freeze_remind — подписчики напоминалки за 6ч
        CREATE TABLE IF NOT EXISTS freeze_remind (
            uid INTEGER PRIMARY KEY,
            ts  REAL    NOT NULL
        );
    """)
    conn.commit()

    # ── Дополнительные колонки в frogs ─────────────────────────────────────────
    try:
        cur.execute("PRAGMA table_info(frogs)")
        existing = {row[1] for row in cur.fetchall()}
    except Exception:
        existing = set()

    fz_cols = [
        ("fz_daily_cube_ts",  "REAL    DEFAULT 0"),   # таймштамп выданного daily кубика
        ("fz_total_throws",   "INTEGER DEFAULT 0"),   # всего бросков основного пула
        ("fz_pool_throws",    "INTEGER DEFAULT 0"),   # бросков в sold-out пуле
        ("fz_wins",           "INTEGER DEFAULT 0"),   # побед (дропов NFT)
        ("fz_stars_spent",    "INTEGER DEFAULT 0"),   # Stars потрачено на ивент
        ("fz_ref_count",      "INTEGER DEFAULT 0"),   # рефералов засчитано
        ("fz_title_king",     "INTEGER DEFAULT 0"),   # 1 = Ледяной Король
        ("fz_remind",         "INTEGER DEFAULT 0"),   # 1 = подписан на напоминалку
        ("last_friz_word",    "TEXT    DEFAULT ''"),  # последнее слово-триггер (ква/фриз)
    ]
    for col, typedef in fz_cols:
        if col not in existing:
            try:
                cur.execute(f"ALTER TABLE frogs ADD COLUMN {col} {typedef}")
                conn.commit()
                logger.info("Миграция frogs: добавлена колонка %s", col)
            except Exception as e:
                logger.warning("Миграция frogs.%s: %s", col, e)

    # Миграция freeze_state: добавляем total_nft если её нет
    try:
        cur.execute("ALTER TABLE freeze_state ADD COLUMN total_nft INTEGER DEFAULT 10")
        # Выставляем total_nft = remaining_nft для уже запущенных событий
        cur.execute("UPDATE freeze_state SET total_nft = remaining_nft WHERE total_nft = 0 OR total_nft IS NULL")
        conn.commit()
        logger.info("Миграция freeze_state: добавлена колонка total_nft")
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)
        pass  # Колонка уже существует


async def freeze_init_db(db: aiosqlite.Connection) -> None:
    """
    Вызывается из async init_db() в frog_bot.py.
    Гарантирует, что строка состояния существует.
    """
    await db.execute("INSERT OR IGNORE INTO freeze_state(id) VALUES(1)")
    await db.commit()


