# 🔧  ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
# ══════════════════════════════════════════════════════════════════════════════

async def _fz_state() -> dict:
    """Возвращает текущее состояние ивента из БД."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM freeze_state WHERE id=1") as c:
            row = await c.fetchone()
    return dict(row) if row else {}


async def _fz_set_state(**kwargs) -> None:
    """Обновляет поля freeze_state."""
    if not kwargs:
        return
    cols = ", ".join(f"{k}=?" for k in kwargs)
    vals = list(kwargs.values())
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(f"UPDATE freeze_state SET {cols} WHERE id=1", vals)
        await db.commit()


async def _fz_remaining() -> int:
    """Возвращает количество оставшихся NFT."""
    s = await _fz_state()
    return s.get("remaining_nft", 0)


async def _fz_active() -> bool:
    """True если ивент в статусе ACTIVE, SOLD_OUT или FINALE."""
    s = await _fz_state()
    return s.get("status") in (FZ_ACTIVE, FZ_SOLD_OUT, FZ_FINALE)


def _fz_heat_info(heat: int) -> tuple[str, str, float]:
    """
    Возвращает (emoji, label, coin_mult) для заданного значения шкалы.
    """
    if heat >= 100:
        return "💀", "Эстивация", 0.0
    if heat >= 81:
        return "🚨", "Критическая жара", 0.5
    if heat >= 61:
        return "🔴", "Сильный перегрев", 0.70
    if heat >= 41:
        return "⚠️", "Нагревается", 0.85
    if heat >= 21:
        return "🌡", "Норма", 1.00
    return "❄️", "Прохладно", 1.10


def _fz_heat_bar(heat: int, width: int = 10) -> str:
    """Рисует ASCII-прогресс-бар шкалы жары."""
    filled = round(heat / 100 * width)
    bar = "🟥" * filled + "⬜" * (width - filled)
    return f"{bar} {heat}%"


async def _fz_log_heat(db: aiosqlite.Connection, before: int, after: int,
                        delta: int, reason: str) -> None:
    """Пишет запись в freeze_heat_log."""
    await db.execute(
        "INSERT INTO freeze_heat_log(ts, heat_before, heat_after, delta, reason) VALUES(?,?,?,?,?)",
        (time.time(), before, after, delta, reason),
    )


async def _fz_apply_heat_delta(delta: int, reason: str) -> tuple[int, int]:
    """
    Применяет дельту к шкале (зажим 0..100).
    Возвращает (before, after).
    """
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT heat FROM freeze_state WHERE id=1") as c:
            row = await c.fetchone()
        before = row[0] if row else 0
        after  = max(0, min(100, before + delta))
        await db.execute("UPDATE freeze_state SET heat=? WHERE id=1", (after,))
        await _fz_log_heat(db, before, after, after - before, reason)
        await db.commit()
    return before, after


# ══════════════════════════════════════════════════════════════════════════════
# 🎲  ЯДРО: БРОСОК КУБИКА
# ══════════════════════════════════════════════════════════════════════════════

async def _fz_throw(uid: int, source: str, bot) -> dict:
    """
    Один бросок кубика льда.

    source: 'pkg_15' | 'pkg_50' | 'pkg_120' | 'pkg_250' | 'pkg_500'
            | 'free_daily' | 'free_mosquito' | 'free_care'
            | 'free_quiz' | 'free_repost' | 'free_ref'

    Возвращает: {'roll': int, 'won': bool, 'pool': 'main'|'sold_out'}
    Победа при roll == FZ_DROP_CHANCE (1000/1000).
    """
    roll = random.randint(1, FZ_DROP_CHANCE)
    won  = (roll == FZ_DROP_CHANCE)  # победа при 1000/1000
    pool = "main"

    async with aiosqlite.connect(DB_PATH) as db:
        if won:
            # Атомарная декрементация — защита от race-condition (§9.4)
            cur = await db.execute(
                "UPDATE freeze_state "
                "SET remaining_nft = remaining_nft - 1, daily_throws = daily_throws + 1 "
                "WHERE id = 1 AND remaining_nft > 0 AND status IN ('ACTIVE','FINALE')"
            )
            await db.commit()
            if cur.rowcount == 0:
                # NFT уже разобраны ИЛИ статус не тот — уходим в sold-out
                won  = False
                pool = "sold_out"
                await db.execute(
                    "UPDATE freeze_state "
                    "SET pool_throws = pool_throws + 1, daily_throws = daily_throws + 1 "
                    "WHERE id = 1"
                )
                await db.commit()
        else:
            # Проверяем пул
            async with db.execute(
                "SELECT status FROM freeze_state WHERE id=1"
            ) as c:
                st_row = await c.fetchone()
            status = st_row[0] if st_row else FZ_INACTIVE
            if status in (FZ_SOLD_OUT, FZ_FINISHED):
                pool = "sold_out"
                await db.execute(
                    "UPDATE freeze_state "
                    "SET pool_throws = pool_throws + 1, daily_throws = daily_throws + 1 "
                    "WHERE id = 1"
                )
            else:
                await db.execute(
                    "UPDATE freeze_state SET daily_throws = daily_throws + 1 WHERE id = 1"
                )
            await db.commit()

        # Записываем бросок
        await db.execute(
            "INSERT INTO freeze_throws(uid, ts, roll, won, pool, source) VALUES(?,?,?,?,?,?)",
            (uid, time.time(), roll, int(won), pool, source),
        )
        # Охлаждение: −1% за каждые 3 суммарных броска (любой источник)
        async with db.execute("SELECT daily_throws FROM freeze_state WHERE id=1") as _dtc:
            _dt_row = await _dtc.fetchone()
        _dt_now = (_dt_row[0] if _dt_row else 0)
        if _dt_now > 0 and _dt_now % 3 == 0:
            asyncio.create_task(_fz_apply_heat_delta(-1, f"cube_cool_3x_{_dt_now}"))

        # Обновляем счётчики пользователя
        if pool == "sold_out":
            await db.execute(
                "UPDATE frogs SET fz_pool_throws = fz_pool_throws + 1, "
                "fz_total_throws = fz_total_throws + 1 WHERE user_id=?", (uid,)
            )
        else:
            await db.execute(
                "UPDATE frogs SET fz_total_throws = fz_total_throws + 1 WHERE user_id=?", (uid,)
            )
        if won:
            await db.execute(
                "UPDATE frogs SET fz_wins = fz_wins + 1 WHERE user_id=?", (uid,)
            )
        await db.commit()

    if won:
        # Публичный анонс + ЛС победителю
        asyncio.create_task(_fz_announce_drop(uid, bot))
        # Праздничное охлаждение шкалы (§5.3)
        asyncio.create_task(_fz_apply_heat_delta(-5, "drop"))
        # Проверяем: не выбиты ли все NFT
        remaining = await _fz_remaining()
        if remaining == 0:
            asyncio.create_task(_fz_set_status(FZ_SOLD_OUT, bot))
    elif pool == "sold_out":
        # Начисляем монеты-утешение (§5.5)
        asyncio.create_task(_fz_pool_rewards(uid, bot))

    return {"roll": roll, "won": won, "pool": pool}


async def _fz_pool_rewards(uid: int, bot) -> None:
    """
    Начисляет вознаграждения при броске в sold-out пуле (§5.5):
    - 5 монет за каждый бросок
    - guaranteed skin при 50 бросках
    - титул Ледяного Короля при 200 бросках
    """
    f = await db_get(uid)
    if not f:
        return
    f["coins"] = f.get("coins", 0) + FZ_POOL_COINS_PER_THROW
    await db_save(f)

    pool_throws = f.get("fz_pool_throws", 0)

    # Титул
    if pool_throws >= FZ_POOL_KING_THRESH and not f.get("fz_title_king", 0):
        f["fz_title_king"] = 1
        await db_save(f)
        try:
            await bot.send_message(
                uid,
                f"{_E_CROWN} <b>Поздравляем, Ледяной Король!</b>\n\n"
                "Ты бросил 200+ кубиков в Sold-Out пул — "
                f"получаешь вечный титул <b>{_E_ICE} Ледяной Король</b>!\n"
                "Он будет отображаться в /freeze.",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass


async def _fz_announce_drop(uid: int, bot) -> None:
    """Публичный анонс дропа в общий чат + детальное уведомление всем админам."""
    f = await db_get(uid)
    name = _html.escape(fname(f)) if f else "Игрок"
    state = await _fz_state()
    remaining = state.get("remaining_nft", 0)
    total_nft  = state.get("total_nft", FZ_TOTAL_NFT)

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT COUNT(*) FROM freeze_throws") as c:
            total_throws = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT COUNT(*) FROM freeze_throws WHERE uid=?", (uid,)
        ) as c:
            user_throws = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT SUM(stars) FROM freeze_payments WHERE uid=?", (uid,)
        ) as c:
            user_stars = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT source, ts FROM freeze_throws WHERE uid=? AND won=1 ORDER BY ts DESC LIMIT 1",
            (uid,)
        ) as c:
            win_row = await c.fetchone()

    win_source = win_row[0] if win_row else "—"
    win_ts_str = datetime.fromtimestamp(win_row[1], tz=timezone.utc).strftime("%d.%m.%Y %H:%M UTC") if win_row else "—"

    text = FZ_MSG_DROP.format(
        name=name,
        total_throws=total_throws,
        remaining=remaining,
        total_nft=total_nft,
    )
    await _fz_announce_confirm(bot, text, delete_after=0, announce_level="major")

    # ── Подробное уведомление каждому админу ─────────────────────────────────
    username_str = f"@{f['username']}" if f and f.get("username") else "—"
    level_str    = str(f.get("level", "?")) if f else "?"
    coins_str    = str(f.get("coins", "?")) if f else "?"
    total_spent_str = str(f.get("fz_stars_spent", 0)) if f else "?"
    admin_text = (
        f"🍦 <b>NFT ViceCream ВЫБИТ!</b>\n"
        "\n"
        f"👤 Игрок: <a href='tg://user?id={uid}'>{name}</a>\n"
        f"🆔 ID: <code>{uid}</code>\n"
        f"📎 Username: {username_str}\n"
        f"{_E_LEVEL} Уровень: {level_str} · 🪙 Монет: {coins_str}\n"
        "\n"
        f"🎲 Источник броска: <code>{win_source}</code>\n"
        f"🕐 Время победы: {win_ts_str}\n"
        f"🧊 Всего бросков игрока: <b>{user_throws}</b>\n"
        f"{_E_STARS} Stars потрачено игроком: <b>{user_stars}</b>\n"
        "\n"
        f"🍦 Осталось NFT в пуле: <b>{remaining} / {total_nft}</b>\n"
        f"{_E_CHART} Всего бросков в ивенте: <b>{total_throws:,}</b>\n"
        "\n"
        f"<i>Выдай NFT вручную: /fznft_drop {uid}</i>"
    )
    for _adm in ADMIN_IDS:
        try:
            await bot.send_message(_adm, admin_text, parse_mode=ParseMode.HTML)
        except Exception as _e:
            logger.warning("_fz_announce_drop admin notify uid=%s adm=%s err=%s", uid, _adm, _e)


async def _fz_dm_winner(uid: int, bot) -> None:
    """ЛС победителю — инструкция получить NFT."""
    try:
        await bot.send_message(
            uid,
            "🍦 <b>Поздравляем — ты выбил NFT ViceCream!</b>\n\n"
            "Напиши администратору (@frog_holder) для получения NFT-мороженого.\n"
            "Не забудь указать: свой Telegram юзернейм и никнейм в игре.\n\n"
            f"<i>Болото благодарит тебя за заморозку! {_E_ICE}</i>",
            parse_mode=ParseMode.HTML,
        )
    except Exception as e:
        logger.warning("_fz_dm_winner uid=%s err=%s", uid, e)


async def _fz_set_status(new_status: str, bot) -> None:
    """Переводит ивент в новый статус и уведомляет админов."""
    old = (await _fz_state()).get("status", FZ_INACTIVE)
    await _fz_set_state(status=new_status)
    logger.info("Freeze status: %s → %s", old, new_status)

    if new_status == FZ_SOLD_OUT:
        text = FZ_MSG_SOLD_OUT.format(
            pool_skin_every=FZ_POOL_SKIN_EVERY,
            pool_coins=FZ_POOL_COINS_PER_THROW,
        )
        await _fz_announce_confirm(bot, text, delete_after=0)
        await announce(bot, "Freeze: SOLD_OUT — все NFT выбиты!", admin_only=True)

    elif new_status == FZ_FINALE:
        _fin_state = await _fz_state()
        text = FZ_MSG_FINALE.format(
            remaining=_fin_state.get("remaining_nft", 0),
            total_nft=_fin_state.get("total_nft", FZ_TOTAL_NFT),
        )
        await _fz_announce_confirm(bot, text, delete_after=0)

    elif new_status == FZ_FINISHED:
        await announce(bot, "Freeze: FINISHED — ивент завершён, итоги подводятся.", admin_only=True)


