# 💳  ПЛАТЁЖНЫЙ ХЕНДЛЕР (вызывается из successful_payment в frog_bot.py)
# ══════════════════════════════════════════════════════════════════════════════

async def _fz_register_payment(charge_id: str, uid: int,
                                pkg_idx: int, stars: int, cubes: int) -> bool:
    """
    Идемпотентная регистрация платежа по charge_id (§5.2).
    True — новый платёж, кубики начислять.
    False — дубликат (Telegram retry), игнорируем.
    """
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "INSERT INTO freeze_payments(charge_id, uid, pkg, stars, cubes, ts) "
                "VALUES(?,?,?,?,?,?)",
                (charge_id, uid, pkg_idx, stars, cubes, time.time()),
            )
            await db.commit()
        return True
    except Exception as e:
        if "UNIQUE" in str(e) or "PRIMARY" in str(e):
            logger.warning("freeze_payment dedup: charge_id=%s", charge_id)
            return False
        raise


async def _fz_handle_payment(update, ctx) -> None:
    """
    Точка входа из successful_payment() в frog_bot.py.
    Вызывать так:
        if payload.startswith("fz_pkg_"):
            return await _fz_handle_payment(update, ctx)
    """
    user = update.effective_user
    uid  = user.id
    pay  = update.message.successful_payment
    stars_paid  = pay.total_amount
    charge_id   = pay.telegram_payment_charge_id
    payload     = pay.invoice_payload  # "fz_pkg_{idx}"

    try:
        pkg_idx = int(payload.split("_")[2])
        pkg     = FREEZE_PACKAGES[pkg_idx]
    except (IndexError, ValueError):
        logger.error("_fz_handle_payment: bad payload=%s", payload)
        return

    # Ограничение one_time (пакет 🐣 Крошка): 1 покупка на ивент
    if pkg.get("one_time"):
        async with aiosqlite.connect(DB_PATH) as _db:
            async with _db.execute(
                "SELECT 1 FROM freeze_payments WHERE uid=? AND pkg_idx=?", (uid, pkg_idx)
            ) as _c:
                already = await _c.fetchone()
        if already:
            await update.message.reply_text(
                "🐣 <i>Этот пакет можно получить только 1 раз за ивент. "
                "Возврат обрабатывается через поддержку Telegram.</i>",
                parse_mode="HTML",
            )
            return

    # Дедупликация
    cubes = pkg["cubes"]
    if not await _fz_register_payment(charge_id, uid, pkg_idx, stars_paid, cubes):
        await update.message.reply_text(
            f"{_E_CHECK} <i>Платёж уже был зачислен ранее. Кубики были брошены.</i>",
            parse_mode=ParseMode.HTML,
        )
        return

    # Обновляем stars_spent игрока
    f = await db_get(uid)
    if f:
        f["stars_spent"]    = f.get("stars_spent", 0) + stars_paid
        f["fz_stars_spent"] = f.get("fz_stars_spent", 0) + stars_paid
        await db_save(f)

    # Реферальная комиссия (используем внутреннюю копию логики)
    await _fz_ref_commission(uid, stars_paid, ctx)

    # Бонус к шкале болота от крупных пакетов
    heat_bonus = pkg.get("heat_bonus", 0)
    if heat_bonus < 0:
        reason = f"pkg_{pkg['stars']}"
        _, after = await _fz_apply_heat_delta(heat_bonus, reason)
        heat_bonus_str = f"Шкала болота: {after}% (охладили на {abs(heat_bonus)}%) ❄️\n"
    else:
        heat_bonus_str = ""

    # Бросаем кубики и собираем результаты
    results = []
    wins    = 0
    for _ in range(cubes):
        res = await _fz_throw(uid, f"pkg_{pkg['stars']}", ctx.bot)
        results.append(res)
        if res["won"]:
            wins += 1
            asyncio.create_task(_fz_dm_winner(uid, ctx.bot))

    # Итоговое ЛС (одно сообщение на пакет)
    remaining = await _fz_remaining()
    state = await _fz_state()
    total_nft = state.get("total_nft", FZ_TOTAL_NFT)

    if wins > 0:
        win_text = f"<b>Выбил {wins} NFT ViceCream! 🍦</b>\n"
    else:
        win_text = "❌ Не повезло.\n"

    in_pool = sum(1 for r in results if r["pool"] == "sold_out")
    pool_note = ""
    if in_pool > 0:
        pool_note = (
            f"\n<i>{in_pool} бросков ушли в Sold-Out пул — "
            f"все NFT выбиты, броски идут в финальный розыгрыш.</i>"
        )

    # Броски из сессии, отсортированные от ближайших к 1000
    rolls_sorted = sorted([r["roll"] for r in results], reverse=True)[:20]
    rolls_lines = []
    for rv in rolls_sorted:
        diff = FZ_DROP_CHANCE - rv
        if rv == FZ_DROP_CHANCE:
            rolls_lines.append(f"{_E_TROPHY} <b>{rv}/1000</b> (−{diff})")
        else:
            rolls_lines.append(f"🧊 {rv}/1000 (−{diff})")
    rolls_text = "\n".join(rolls_lines)

    # Суммарные броски за всё время — читаем напрямую из freeze_throws (не из кеша)
    async with aiosqlite.connect(DB_PATH) as _tdb:
        async with _tdb.execute(
            "SELECT COUNT(*) FROM freeze_throws WHERE uid=?", (uid,)
        ) as _tc:
            total_throws_ever = (await _tc.fetchone() or [0])[0]

    await update.message.reply_text(
        f"🧊 <b>Бросил {cubes} кубик(ов)!</b>\n\n"
        + win_text
        + "\n"
        + f"🌡 Болото: {_fz_heat_bar(state.get('heat', 0))}\n"
        + heat_bonus_str
        + f"🍦 Осталось NFT: {remaining} из {total_nft}\n"
        + f"🧊 Бросков за ивент: <b>{total_throws_ever}</b>"
        + pool_note
        + f"\n\n🎯 <b>Твои броски:</b>\n"
        + rolls_text
        + f"\n\n<i>Нужно выбить 1000/1000 — удачи! /icecube {_E_ICE}</i>",
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[
            btn("🧊 Ещё кубики", callback_data="fz_menu", style="primary"),
            btn("📊 Мои броски", callback_data="fz_mythrows"),
        ]]),
    )

    # Уведомление администраторам о покупке
    uname = f"@{user.username}" if user.username else f"<a href='tg://user?id={uid}'>{user.first_name}</a>"
    await _fz_admin_notify(ctx.bot,
        f"💳 <b>Покупка пакета кубиков</b>\n\n"
        f"👤 {uname} <code>[{uid}]</code>\n"
        f"📦 {pkg['label']} — {stars_paid}{_E_STARS} ({cubes} кубиков)\n"
        f"{_E_TROPHY} побед {wins} · 🍦 NFT {remaining}\n"
        f"{_E_STARS} Итого Stars за ивент: {f.get('fz_stars_spent', stars_paid) if f else stars_paid}"
    )


async def _fz_ref_commission(buyer_id: int, stars: int, ctx) -> None:
    """Реферальная комиссия 10% от Stars, аналогично _pay_ref_commission."""
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT referrer_id FROM referrals WHERE referred_id=?", (buyer_id,)
            ) as c:
                row = await c.fetchone()
        if not row:
            return
        referrer_id = row[0]
        commission = max(1, stars // 10)
        ref_f = await db_get(referrer_id)
        if not ref_f:
            return
        ref_f["ref_stars_balance"] = ref_f.get("ref_stars_balance", 0) + commission
        await db_save(ref_f)
    except Exception as e:
        logger.warning("_fz_ref_commission: %s", e)


