# 🆓  FREE-КУБИКИ
# ══════════════════════════════════════════════════════════════════════════════

async def _fz_free_cube(uid: int, source: str, bot) -> None:
    """
    Выдаёт один free-кубик льда если ивент активен и лимиты не превышены.
    source: 'free_daily' | 'free_mosquito' | 'free_care' | 'free_ref' | 'free_repost'

    Вызывается как asyncio.create_task(…) из соответствующих мест в frog_bot.py.
    """
    if not await _fz_active():
        return

    state = await _fz_state()
    heat  = state.get("heat", 0)

    # При heat ≥ 81% free-кубики заблокированы (§5.3, уровень 81–99%)
    if heat >= 81:
        # Ежедневный кубик тоже заблокирован
        try:
            await bot.send_message(
                uid,
                "🌡 <b>Болото слишком горячее!</b> (+{heat}°C)\n"
                "Free-кубик заморожен — температура критическая.\n"
                f"<i>Помоги охладить болото: /icecube {_E_ICE}</i>",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # Ежедневный кубик: только 1 раз в сутки
    if source == "free_daily":
        f = await db_get(uid)
        if not f:
            return
        today_midnight = int(time.time() // 86400) * 86400
        if f.get("fz_daily_cube_ts", 0) >= today_midnight:
            return  # уже выдан сегодня
        f["fz_daily_cube_ts"] = time.time()
        await db_save(f)

    # Кидаем кубик
    result = await _fz_throw(uid, source, bot)
    logger.info("_fz_free_cube: uid=%s source=%s roll=%s won=%s",
                uid, source, result["roll"], result["won"])

    # Уведомляем игрока о результате броска в ЛС
    source_labels = {
        "free_daily":    "📅 Ежедневный вход",
        "free_mosquito": "🦟 Поимка комара",
        "free_care":     "💚 Идеальный уход",
        "free_ref":      "👥 Активный реферал",
        "free_repost":   "📣 Репост анонса",
    }
    label = source_labels.get(source, "🎁 Бесплатный кубик")

    if result["won"]:
        msg = (
            f"🧊 <b>{label}</b>\n"
            f"🎲 Бросок: <b>{result['roll']}/{FZ_DROP_CHANCE}</b>\n\n"
            f"🍦 <b>НЕВЕРОЯТНО! Ты выбил NFT ViceCream!</b>"
        )
    else:
        msg = (
            f"🧊 <b>{label}</b>\n"
            f"🎲 Бросок: <b>{result['roll']}/{FZ_DROP_CHANCE}</b>"
        )
    try:
        await bot.send_message(uid, msg, parse_mode=ParseMode.HTML)
    except (BadRequest, Forbidden, TimedOut):
        pass


async def _fz_award_quiz_cubes(uid: int, bot) -> None:
    """
    Выдаёт 5 free-кубиков за правильный ответ на квиз (§8.6).
    Вызывать из обработчика fzquiz_B.
    """
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT cubes_awarded FROM freeze_quiz WHERE uid=?", (uid,)
        ) as c:
            row = await c.fetchone()
        if row and row[0] > 0:
            return  # уже выдали
        await db.execute(
            "UPDATE freeze_quiz SET cubes_awarded=1 WHERE uid=? AND answer='B'", (uid,)
        )
        await db.commit()

    wins = 0
    for _ in range(FZ_QUIZ_CUBES):
        res = await _fz_throw(uid, "free_quiz", bot)
        if res["won"]:
            wins += 1

    if wins:
        msg = (
            f"🧊 <b>Квиз — +{FZ_QUIZ_CUBES} кубиков</b>\n"
            f"🍦 <b>НЕВЕРОЯТНО! Ты выбил NFT ViceCream!</b>"
        )
    else:
        msg = f"🧊 <b>Квиз — +{FZ_QUIZ_CUBES} кубиков брошено!</b>\nРезультаты: /freeze"
    try:
        await bot.send_message(uid, msg, parse_mode=ParseMode.HTML)
    except (BadRequest, Forbidden, TimedOut):
        pass


# ══════════════════════════════════════════════════════════════════════════════
# 📅  ЕЖЕДНЕВНЫЙ ДЖОБ: ШКАЛА БОЛОТА
# ══════════════════════════════════════════════════════════════════════════════

async def _fz_daily_heat_job(bot) -> None:
    """
    Запускается раз в сутки в 00:00 UTC (§9.3).
    1. Считает daily_throws.
    2. Обновляет heat.
    3. Публикует ежедневный пост шкалы (§8.5).
    4. Сбрасывает daily_throws.
    """
    if not await _fz_active():
        return

    state = await _fz_state()
    heat_before  = state.get("heat", 0)
    daily_throws = state.get("daily_throws", 0)

    # Определяем дельту по таблице §5.3
    delta = +15  # default: мало бросков
    for lo, hi, d in FZ_HEAT_DAILY_RULES:
        if hi is None:
            if daily_throws >= lo:
                delta = d
                break
        elif lo <= daily_throws <= hi:
            delta = d
            break

    _, heat_after = await _fz_apply_heat_delta(delta, "daily_job")
    await _fz_set_state(daily_throws=0)  # сброс дневного счётчика

    # Сброс при 100% после 24ч эстивации (§5.3)
    if heat_after >= 100:
        await _fz_apply_heat_delta(-30, "estivation_reset")  # 100→70
        heat_after = max(0, heat_after - 30)

    # День ивента
    started_at = state.get("started_at", time.time())
    day_n = int((time.time() - started_at) // 86400) + 1

    # Топ-3 по очкам и по броскам
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT uid, SUM(CASE WHEN won=1 THEN 100 ELSE 1 END) as pts "
            "FROM freeze_throws WHERE pool='main' GROUP BY uid ORDER BY pts DESC LIMIT 3"
        ) as c:
            top_pts = await c.fetchall()
        async with db.execute(
            "SELECT uid, COUNT(*) as cnt "
            "FROM freeze_throws GROUP BY uid ORDER BY cnt DESC LIMIT 3"
        ) as c:
            top_throws = await c.fetchall()

        async with db.execute(
            "SELECT COUNT(*) FROM freeze_throws"
        ) as c:
            total_throws = (await c.fetchone())[0] or 0

    async def _name(row_uid: int) -> str:
        f = await db_get(row_uid)
        return _html.escape(fname(f)) if f else str(row_uid)

    def _medal(i: int) -> str:
        return ["🥇", "🥈", "🥉"][i] if i < 3 else f"{i+1}."

    pts_lines   = "\n".join(
        f"{_medal(i)} <b>{await _name(r[0])}</b> — {r[1]} очков"
        for i, r in enumerate(top_pts)
    ) or "—"
    throw_lines = "\n".join(
        f"{_medal(i)} <b>{await _name(r[0])}</b> — {r[1]} бросков"
        for i, r in enumerate(top_throws)
    ) or "—"

    heat_emoji, heat_label, _ = _fz_heat_info(heat_after)
    bar   = _fz_heat_bar(heat_after)

    if heat_after <= 40:
        heat_comment = "Болото под контролем. Спасибо всем, кто бросает 💪"
    elif heat_after <= 60:
        heat_comment = "⚠️ Болото нагревается. Квак уже даёт меньше монет — пора бросать кубики."
    elif heat_after <= 80:
        heat_comment = "🔴 Лягушки уходят в эстивацию. Free-кубики на грани заморозки."
    elif heat_after < 100:
        heat_comment = "🚨 Критическая температура. Болото на грани отключения наград."
    else:
        heat_comment = "💀 ЭСТИВАЦИЯ. Free-кубики заморожены на 24 часа. Спасают только Stars-броски."

    text = FZ_MSG_DAILY.format(
        day_n=day_n,
        bar=bar,
        heat_emoji=heat_emoji,
        heat_label=heat_label,
        daily_throws=daily_throws,
        total_throws=total_throws,
        remaining=state.get("remaining_nft", 0),
        total_nft=state.get("total_nft", FZ_TOTAL_NFT),
        pts_lines=pts_lines,
        throw_lines=throw_lines,
        heat_comment=heat_comment,
    )

    await _fz_announce_confirm(bot, text, delete_after=0, announce_level="all",
                   reply_markup=InlineKeyboardMarkup([[
                       btn("Бросить кубики", callback_data="fz_menu", style="primary"),
                       btn("Моя статистика", callback_data="fz_mythrows"),
                   ]]))
    logger.info("Freeze daily job done: heat %d→%d, daily=%d", heat_before, heat_after, daily_throws)


# ══════════════════════════════════════════════════════════════════════════════
# ⏱️  SCHEDULED JOBS: ФИНАЛ, АВТО-ПЕРЕХОДЫ
# ══════════════════════════════════════════════════════════════════════════════

async def _fz_check_auto_finale(bot) -> None:
    """Каждые 5 мин: если ACTIVE/SOLD_OUT и до конца ≤ 6ч → FINALE (§9.3)."""
    state = await _fz_state()
    status   = state.get("status")
    ends_at  = state.get("ends_at", 0)
    if status in (FZ_ACTIVE, FZ_SOLD_OUT) and ends_at > 0:
        time_left = ends_at - time.time()
        if 0 < time_left <= FZ_FINALE_SECS:
            await _fz_set_status(FZ_FINALE, bot)


async def _fz_check_auto_finish(bot) -> None:
    """Каждые 5 мин: если ends_at пройден → запускаем результаты (§9.3)."""
    state = await _fz_state()
    status   = state.get("status")
    ends_at  = state.get("ends_at", 0)
    if status in (FZ_FINALE, FZ_SOLD_OUT) and ends_at > 0:
        if time.time() >= ends_at:
            await _fz_run_results(bot)


# Хранилище message_id таймера для edit_message
_fz_timer_msg_id: int | None = None
_fz_timer_chat_id: int | None = None


async def _fz_finale_timer_job(bot) -> None:
    """Обновляет таймер-сообщение каждые 10/2 мин в FINALE (§9.3)."""
    global _fz_timer_msg_id, _fz_timer_chat_id

    state = await _fz_state()
    if state.get("status") != FZ_FINALE:
        return

    ends_at   = state.get("ends_at", 0)
    time_left = max(0, int(ends_at - time.time()))
    remaining = state.get("remaining_nft", 0)

    hours   = time_left // 3600
    minutes = (time_left % 3600) // 60
    seconds = time_left % 60

    timer_str = f"{hours:02d}:{minutes:02d}:{seconds:02d}"

    text = (
        f"⚡ <b>Финальный рывок</b>\n\n"
        f"⏳ До конца: <b>{timer_str}</b>\n"
        f"🍦 Осталось NFT: <b>{remaining} из {state.get('total_nft', FZ_TOTAL_NFT)}</b>\n\n"
        f"<i>Каждый бросок — шанс выбить 1000/1000 и получить NFT</i>"
    )
    markup = InlineKeyboardMarkup([[
        btn("⚡ Мой статус",     callback_data="fz_mythrows"),
        btn("🧊 Бросить кубики", callback_data="fz_menu", style="primary"),
    ]])

    if _fz_timer_msg_id and _fz_timer_chat_id:
        try:
            await bot.edit_message_text(
                text,
                chat_id=_fz_timer_chat_id,
                message_id=_fz_timer_msg_id,
                parse_mode=ParseMode.HTML,
                reply_markup=markup,
            )
        except Exception:
            _fz_timer_msg_id = None
    else:
        try:
            msg = await bot.send_message(
                CHAT_ID, text, parse_mode=ParseMode.HTML, reply_markup=markup
            )
            _fz_timer_msg_id  = msg.message_id
            _fz_timer_chat_id = CHAT_ID
        except Exception as e:
            logger.warning("_fz_finale_timer_job send error: %s", e)


async def _fz_start_jobs(bot) -> None:
    """Запускает все cron-задачи ивента в фоне (§9.3)."""
    while True:
        try:
            state = await _fz_state()
            status   = state.get("status", FZ_INACTIVE)
            ends_at  = state.get("ends_at", 0)

            # ── Ежедневный джоб в 00:00 UTC ─────────────────────────────────
            now_utc = datetime.now(timezone.utc)
            if now_utc.hour == 0 and now_utc.minute == 0:
                if status not in (FZ_INACTIVE, FZ_FINISHED):
                    asyncio.create_task(_fz_daily_heat_job(bot))

            # ── Авто-финал и авто-завершение ─────────────────────────────────
            if status not in (FZ_INACTIVE, FZ_FINISHED):
                await _fz_check_auto_finale(bot)
                await _fz_check_auto_finish(bot)

            # ── Таймер финала ─────────────────────────────────────────────────
            if status == FZ_FINALE:
                await _fz_finale_timer_job(bot)
                time_left = ends_at - time.time() if ends_at else 9999
                # Последний час: каждые 2 мин; иначе каждые 10 мин
                sleep = 120 if time_left <= 3600 else 600
            else:
                sleep = 300  # 5 минут для остальных проверок

        except Exception as e:
            logger.error("_fz_start_jobs error: %s", e)
            sleep = 60

        await asyncio.sleep(sleep)


# ══════════════════════════════════════════════════════════════════════════════
# 🎰  ЗАПАСНОЙ РОЗЫГРЫШ
# ══════════════════════════════════════════════════════════════════════════════

def _fz_lottery_pick(participants: list[dict], n: int) -> list[int]:
    """
    Выбирает n победителей взвешенно по числу бросков (§5.6).
    Без повторений: один игрок — максимум 1 NFT.
    """
    eligible = [p for p in participants if p["throws"] >= FZ_LOTTERY_MIN_THROWS]
    if not eligible:
        return []
    if len(eligible) <= n:
        return [p["uid"] for p in eligible]
    winners = []
    pool    = eligible[:]
    for _ in range(n):
        weights = [p["throws"] for p in pool]
        idx = random.choices(range(len(pool)), weights=weights, k=1)[0]
        winners.append(pool[idx]["uid"])
        pool.pop(idx)
    return winners


async def _fz_run_results(bot) -> None:
    """
    Запасной розыгрыш + sold-out пул + итоговый пост (§12.7, §8.9).
    Переводит ивент в FINISHED.
    """
    state = await _fz_state()
    if state.get("status") == FZ_FINISHED:
        return  # уже завершён

    await _fz_set_status(FZ_FINISHED, bot)

    remaining_nft = state.get("remaining_nft", 0)
    pool_throws   = state.get("pool_throws", 0)

    # Запасной розыгрыш
    lottery_winners: list[int] = []
    if remaining_nft > 0:
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT uid, COUNT(*) as throws FROM freeze_throws "
                "WHERE pool='main' GROUP BY uid"
            ) as c:
                rows = await c.fetchall()
        participants = [{"uid": r[0], "throws": r[1]} for r in rows]
        lottery_winners = _fz_lottery_pick(participants, remaining_nft)

        for w_uid in lottery_winners:
            asyncio.create_task(_fz_dm_winner(w_uid, bot))

    # Sold-out топ-1
    pool_winner_uid: int | None = None
    if pool_throws > 0:
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT uid, COUNT(*) as cnt FROM freeze_throws "
                "WHERE pool='sold_out' GROUP BY uid ORDER BY cnt DESC LIMIT 1"
            ) as c:
                row = await c.fetchone()
        if row:
            pool_winner_uid = row[0]
            asyncio.create_task(_fz_dm_winner(pool_winner_uid, bot))

    # Commemorative skins
    pool_skins = pool_throws // FZ_POOL_SKIN_EVERY

    # Статистика для итогового поста
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(DISTINCT uid) FROM freeze_throws"
        ) as c:
            total_players = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT COUNT(*) FROM freeze_throws"
        ) as c:
            total_throws = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT SUM(cubes) FROM freeze_payments"
        ) as c:
            _r = await c.fetchone()
            total_cubes_bought = (_r[0] or 0) if _r else 0
        async with db.execute(
            "SELECT uid, ts FROM freeze_throws WHERE won=1 AND pool='main' ORDER BY ts"
        ) as c:
            drops = await c.fetchall()
        async with db.execute(
            "SELECT SUM(stars) FROM freeze_payments"
        ) as c:
            _rs = await c.fetchone()
            total_stars = (_rs[0] or 0) if _rs else 0
        async with db.execute(
            "SELECT MAX(heat_after) FROM freeze_heat_log"
        ) as c:
            _rh = await c.fetchone()
            max_heat = (_rh[0] or 0) if _rh else 0

    # Список дропов
    drop_lines = []
    for drop_uid, drop_ts in drops:
        f = await db_get(drop_uid)
        dname = _html.escape(fname(f)) if f else str(drop_uid)
        drop_lines.append(f"🍦 {dname}")
    drop_text = "\n".join(drop_lines) or "<i>Дропов не было</i>"

    # Список победителей запасного розыгрыша
    lottery_lines = []
    for i, w_uid in enumerate(lottery_winners[:10]):
        f = await db_get(w_uid)
        wname = _html.escape(fname(f)) if f else str(w_uid)
        lottery_lines.append(f"{['🥇','🥈','🥉'][i] if i<3 else '•'} {wname}")
    lottery_text = ("\n".join(lottery_lines) or "<i>Все NFT были выбиты дропом</i>") if remaining_nft > 0 else "<i>—</i>"

    pool_winner_name = "—"
    if pool_winner_uid:
        f = await db_get(pool_winner_uid)
        pool_winner_name = _html.escape(fname(f)) if f else str(pool_winner_uid)

    text = FZ_MSG_RESULTS.format(
        drop_text=drop_text,
        lottery_text=lottery_text,
        pool_throws=pool_throws,
        pool_skins=pool_skins,
        pool_winner=pool_winner_name,
        total_players=total_players,
        total_throws=total_throws,
        max_heat=max_heat,
    )

    await _fz_announce_confirm(bot, text, delete_after=0, announce_level="all")
    logger.info("Freeze event FINISHED: drops=%d, lottery=%d, pool=%d",
                len(drops), len(lottery_winners), pool_throws)


