# 🛠️  ВСПОМОГАТЕЛЬНОЕ: ADMIN NOTIFY
# ══════════════════════════════════════════════════════════════════════════════

async def _fz_admin_notify(bot, text: str) -> None:
    """Отправляет уведомление: в ADMIN_CHAT_ID (если задан) + в ЛС каждому из ADMIN_IDS."""
    full_text = f"🧊 {text}"
    sent_to: set[int] = set()

    # Сначала в групповой чат администраторов
    if ADMIN_CHAT_ID:
        try:
            await bot.send_message(ADMIN_CHAT_ID, full_text, parse_mode=ParseMode.HTML)
            sent_to.add(ADMIN_CHAT_ID)
        except Exception as e:
            logger.warning("_fz_admin_notify ADMIN_CHAT_ID=%s: %s", ADMIN_CHAT_ID, e)

    # Затем в ЛС каждому администратору (дедупликация: не слать дважды в один чат)
    for admin_id in ADMIN_IDS:
        if admin_id in sent_to:
            continue
        try:
            await bot.send_message(admin_id, full_text, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.warning("_fz_admin_notify admin_id=%s: %s", admin_id, e)


def _fz_is_admin(uid: int) -> bool:
    return uid in ADMIN_IDS


