async def cmd_fzstart(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzstart — запуск ивента INACTIVE → ACTIVE (§10.2)."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return

    state = await _fz_state()
    if state.get("status") != FZ_INACTIVE:
        await update.message.reply_text(
            f"⚠️ Ивент уже запущен: <b>{state.get('status')}</b>",
            parse_mode=ParseMode.HTML,
        )
        return

    now = time.time()
    await _fz_set_state(
        status="ACTIVE",
        started_at=now,
        ends_at=now + FZ_DURATION_SECS,
        total_nft=FZ_TOTAL_NFT,
        remaining_nft=FZ_TOTAL_NFT,
        heat=50,  # стартуем с 50%
        daily_throws=0,
        pool_throws=0,
    )

    ends_str = datetime.fromtimestamp(now + FZ_DURATION_SECS, tz=timezone.utc).strftime("%d.%m.%Y %H:%M UTC")
    await update.message.reply_text(
        f"{_E_CHECK} <b>Фриз-ивент ЗАПУЩЕН!</b>\n\n"
        f"Статус: ACTIVE\n"
        f"NFT в пуле: {FZ_TOTAL_NFT}\n"
        f"Завершение: {ends_str}\n\n"
        f"Публикуй анонс командой /fzannounce или отправь текст из §8.2.",
        parse_mode=ParseMode.HTML,
    )
    logger.info("Freeze event STARTED by uid=%s", uid)


async def cmd_fzextend(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzextend <часы> — сдвинуть окончание ивента.
    Положительное число — продлить, отрицательное — сократить.
    Примеры: /fzextend 24  /fzextend -6  /fzextend 0.5"""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    state = await _fz_state()
    if state.get("status") not in (FZ_ACTIVE, FZ_SOLD_OUT, FZ_FINALE):
        await update.message.reply_text("❌ Ивент не активен.")
        return
    if not ctx.args:
        ends_at   = state.get("ends_at", 0)
        time_left = max(0, int(ends_at - time.time()))
        h, m = divmod(time_left // 60, 60)
        await update.message.reply_text(
            f"Использование: /fzextend &lt;часы&gt;\n\n"
            f"До конца ивента: <b>{h}ч {m}м</b>\n"
            f"Примеры:\n"
            f"  /fzextend 24 — продлить на сутки\n"
            f"  /fzextend -6 — сократить на 6 часов\n"
            f"  /fzextend 0.5 — продлить на 30 минут",
            parse_mode=ParseMode.HTML,
        )
        return
    try:
        delta_hours = float(ctx.args[0].lstrip("+"))
    except ValueError:
        await update.message.reply_text("❌ Укажи число часов, например: 24 или -6")
        return

    delta_secs  = int(delta_hours * 3600)
    old_ends_at = state.get("ends_at", time.time())
    new_ends_at = max(time.time() + 60, old_ends_at + delta_secs)  # минимум 1 мин

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("UPDATE freeze_state SET ends_at=? WHERE id=1", (new_ends_at,))
        await db.commit()

    old_str = datetime.fromtimestamp(old_ends_at, tz=timezone.utc).strftime("%d.%m %H:%M UTC")
    new_str = datetime.fromtimestamp(new_ends_at, tz=timezone.utc).strftime("%d.%m %H:%M UTC")
    arrow   = "+" if delta_hours >= 0 else ""
    await update.message.reply_text(
        f"⏱ Окончание ивента перенесено\n\n"
        f"Было: <b>{old_str}</b>\n"
        f"Стало: <b>{new_str}</b>\n"
        f"Изменение: <b>{arrow}{delta_hours}ч</b>",
        parse_mode=ParseMode.HTML,
    )
    logger.info("fzextend: admin=%s delta=%.1fh new_ends=%s", uid, delta_hours, new_str)


async def cmd_fzsimulate(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzsimulate — симуляция финальных результатов без реального завершения ивента.
    Показывает как выглядели бы итоги прямо сейчас — только тебе в ЛС."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return

    await update.message.reply_text("⏳ Считаю симуляцию...")

    state = await _fz_state()
    remaining_nft = state.get("remaining_nft", 0)
    pool_throws   = state.get("pool_throws", 0)

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(DISTINCT uid) FROM freeze_throws"
        ) as c:
            total_players = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT COUNT(*) FROM freeze_throws"
        ) as c:
            total_throws = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT SUM(cubes) FROM freeze_payments"
        ) as c:
            total_cubes = ((await c.fetchone())[0] or 0)
        async with db.execute(
            "SELECT SUM(stars) FROM freeze_payments"
        ) as c:
            total_stars = ((await c.fetchone())[0] or 0)
        async with db.execute(
            "SELECT uid, ts FROM freeze_throws WHERE won=1 AND pool='main' ORDER BY ts"
        ) as c:
            drops = await c.fetchall()
        # Топ-10 по броскам
        async with db.execute(
            "SELECT uid, COUNT(*) as cnt FROM freeze_throws "
            "WHERE pool='main' GROUP BY uid ORDER BY cnt DESC LIMIT 10"
        ) as c:
            top_rows = await c.fetchall()
        # Пул sold_out топ-1
        async with db.execute(
            "SELECT uid, COUNT(*) as cnt FROM freeze_throws "
            "WHERE pool='sold_out' GROUP BY uid ORDER BY cnt DESC LIMIT 1"
        ) as c:
            pool_top = await c.fetchone()
        async with db.execute(
            "SELECT MAX(heat_after) FROM freeze_heat_log"
        ) as c:
            max_heat = ((await c.fetchone())[0] or 0)

    # Симулируем запасной розыгрыш
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT uid, COUNT(*) as throws FROM freeze_throws "
            "WHERE pool='main' GROUP BY uid"
        ) as c:
            participants_rows = await c.fetchall()
    participants = [{"uid": r[0], "throws": r[1]} for r in participants_rows]
    sim_lottery  = _fz_lottery_pick(participants, remaining_nft) if remaining_nft > 0 else []

    # Формируем дропы
    drop_lines = []
    for drop_uid, drop_ts in drops:
        f = await db_get(drop_uid)
        drop_lines.append(f"  🍦 {_html.escape(fname(f) if f else str(drop_uid))}")
    drop_text = "\n".join(drop_lines) or "  <i>дропов не было</i>"

    # Топ бросков
    top_lines = []
    medals = ["🥇", "🥈", "🥉"] + ["▪️"] * 7
    for i, (t_uid, cnt) in enumerate(top_rows):
        f = await db_get(t_uid)
        top_lines.append(f"  {medals[i]} {_html.escape(fname(f) if f else str(t_uid))} — {cnt} бр.")
    top_text = "\n".join(top_lines) or "  <i>нет данных</i>"

    # Запасной розыгрыш
    lottery_lines = []
    for i, w_uid in enumerate(sim_lottery[:10]):
        f = await db_get(w_uid)
        lottery_lines.append(f"  {medals[i]} {_html.escape(fname(f) if f else str(w_uid))}")
    lottery_text = "\n".join(lottery_lines) or "  <i>все NFT выбиты дропом</i>"

    # Sold-out победитель
    pool_winner_str = "—"
    if pool_top:
        f = await db_get(pool_top[0])
        pool_winner_str = f"{_html.escape(fname(f) if f else str(pool_top[0]))} ({pool_top[1]} бр.)"

    ends_at   = state.get("ends_at", 0)
    time_left = max(0, int(ends_at - time.time()))
    h, m_left = divmod(time_left // 60, 60)

    text = (
        f"🔮 <b>Симуляция финала</b> (не реальное завершение)\n"
        "\n"
        f"До конца: <b>{h}ч {m_left}м</b> · NFT в пуле: <b>{remaining_nft}</b>\n"
        f"Игроков: <b>{total_players}</b> · Бросков: <b>{total_throws:,}</b>\n"
        f"Stars: <b>{total_stars:,}{_E_STARS}</b> · Кубиков куплено: <b>{total_cubes:,}</b>\n"
        f"Макс. нагрев: <b>{max_heat}%</b>\n"
        "\n"
        f"🍦 <b>Дропы (уже выбиты):</b>\n{drop_text}\n"
        "\n"
        f"{_E_CASINO} <b>Запасной розыгрыш</b> (если финал сейчас, {remaining_nft} NFT):\n{lottery_text}\n"
        "\n"
        f"{_E_TROPHY} <b>Топ по броскам:</b>\n{top_text}\n"
        "\n"
        f"🌀 <b>Sold-out лидер:</b> {pool_winner_str}\n"
        "\n"
        f"<i>Это только симуляция. Ивент продолжается.</i>"
    )

    try:
        await ctx.bot.send_message(uid, text, parse_mode=ParseMode.HTML)
    except Exception:
        await update.message.reply_text(text, parse_mode=ParseMode.HTML)


