# Хранилище черновиков рассылки: admin_uid → {"text": str, "uids": list}
_fz_pending_broadcasts: dict[int, dict] = {}


async def cmd_fzbroadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzbroadcast <текст> — рассылка в ЛС всем бросавшим ≥ 1 кубик.
    Сначала показывает превью с числом получателей и ждёт подтверждения администратора.
    """
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    text = " ".join(ctx.args) if ctx.args else ""
    if not text:
        await update.message.reply_text(
            "Использование: /fzbroadcast <текст>\n\n"
            "Поддерживается HTML-разметка. После команды покажу превью и попрошу подтверждение."
        )
        return

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT DISTINCT uid FROM freeze_throws") as c:
            uids = [r[0] for r in await c.fetchall()]

    count = len(uids)
    _fz_pending_broadcasts[uid] = {"text": text, "uids": uids}

    preview_text = (
        f"📋 <b>Превью рассылки</b>\n\n"
        f"{_E_USERS} Получателей: <b>{count}</b>\n"
        "\n"
        f"🧊 {text}\n\n"
        "\n"
        f"<i>Что хочешь сделать?</i>"
    )
    markup = InlineKeyboardMarkup([
        [btn("✅ Отправить всем", callback_data=f"fz_bc_confirm_{uid}", style="success")],
        [btn("✏️ Изменить текст",  callback_data=f"fz_bc_edit_{uid}")],
        [btn("❌ Отменить",        callback_data=f"fz_bc_cancel_{uid}", style="danger")],
    ])
    await update.message.reply_text(preview_text, parse_mode=ParseMode.HTML, reply_markup=markup)


async def _fz_do_broadcast(bot, admin_uid: int, text: str, uids: list[int]) -> tuple[int, int]:
    """Выполняет реальную рассылку. Возвращает (ok, fail)."""
    ok = fail = 0
    for target_uid in uids:
        try:
            await bot.send_message(target_uid, f"🧊 {text}", parse_mode=ParseMode.HTML)
            ok += 1
        except Exception:
            fail += 1
        await asyncio.sleep(0.04)  # ~25 msg/s
    return ok, fail


