async def cmd_fzgrant(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzgrant @user <N> — начислить N бросков (с RNG) (§10.2)."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    if not ctx.args or len(ctx.args) < 2:
        await update.message.reply_text("Использование: /fzgrant <uid> <кубиков>")
        return
    try:
        target_uid = int(ctx.args[0])
        n          = int(ctx.args[1])
    except ValueError:
        await update.message.reply_text("❌ Неверные параметры.")
        return

    wins = 0
    for _ in range(n):
        res = await _fz_throw(target_uid, "admin_grant", ctx.bot)
        if res["won"]:
            wins += 1
    await update.message.reply_text(
        f"✅ Начислено {n} бросков для {target_uid}. Побед: {wins}."
    )


async def cmd_fzsetheat(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzsetheat <N> — принудительно выставить шкалу (§10.2)."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    if not ctx.args:
        await update.message.reply_text("Использование: /fzsetheat <0-100>")
        return
    try:
        new_heat = max(0, min(100, int(ctx.args[0])))
    except ValueError:
        await update.message.reply_text("❌ Число от 0 до 100.")
        return

    state  = await _fz_state()
    before = state.get("heat", 0)
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("UPDATE freeze_state SET heat=? WHERE id=1", (new_heat,))
        await _fz_log_heat(db, before, new_heat, new_heat - before, "manual")
        await db.commit()

    await update.message.reply_text(
        f"✅ Шкала: {before}% → {new_heat}%"
    )


async def cmd_fzaddheat(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzaddheat <+N или -N> — добавить/убрать нагрев относительно текущего значения."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    if not ctx.args:
        state = await _fz_state()
        await update.message.reply_text(
            f"Использование: /fzaddheat <+N или -N>\n\n"
            f"Текущий нагрев: <b>{state.get('heat', 0)}%</b>\n"
            f"Примеры:\n"
            f"  /fzaddheat +10 — добавить 10%\n"
            f"  /fzaddheat -20 — убрать 20%\n"
            f"  /fzaddheat 5 — добавить 5%\n\n"
            f"<i>Для точного выставления: /fzsetheat &lt;0-100&gt;</i>",
            parse_mode=ParseMode.HTML,
        )
        return
    try:
        delta = int(ctx.args[0].lstrip("+"))
    except ValueError:
        await update.message.reply_text("❌ Укажи число, например: +10 или -15")
        return

    state  = await _fz_state()
    before = state.get("heat", 0)
    new_heat = max(0, min(100, before + delta))
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("UPDATE freeze_state SET heat=? WHERE id=1", (new_heat,))
        await _fz_log_heat(db, before, new_heat, delta, "manual_delta")
        await db.commit()

    arrow = "↑" if delta > 0 else "↓"
    await update.message.reply_text(
        f"🌡 Нагрев: <b>{before}%</b> {arrow} <b>{new_heat}%</b> ({delta:+d}%)",
        parse_mode=ParseMode.HTML,
    )


async def cmd_fznft_drop(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fznft_drop <uid> — вручную выдать NFT (обходит RNG) (§10.2)."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    if not ctx.args:
        await update.message.reply_text("Использование: /fznft_drop <uid>")
        return
    try:
        target_uid = int(ctx.args[0])
    except ValueError:
        await update.message.reply_text("❌ Неверный uid.")
        return

    async with aiosqlite.connect(DB_PATH) as db:
        cur = await db.execute(
            "UPDATE freeze_state SET remaining_nft = remaining_nft - 1 "
            "WHERE id=1 AND remaining_nft > 0"
        )
        await db.commit()
        if cur.rowcount == 0:
            await update.message.reply_text("⚠️ NFT кончились (remaining=0).")
            return
        await db.execute(
            "INSERT INTO freeze_throws(uid, ts, roll, won, pool, source) VALUES(?,?,1,1,'main','admin_manual')",
            (target_uid, time.time()),
        )
        await db.execute(
            "UPDATE frogs SET fz_wins=fz_wins+1 WHERE user_id=?", (target_uid,)
        )
        await db.commit()

    asyncio.create_task(_fz_announce_drop(target_uid, ctx.bot))
    asyncio.create_task(_fz_dm_winner(target_uid, ctx.bot))
    asyncio.create_task(_fz_apply_heat_delta(-5, "drop"))

    remaining = await _fz_remaining()
    if remaining == 0:
        asyncio.create_task(_fz_set_status(FZ_SOLD_OUT, ctx.bot))

    await update.message.reply_text(
        f"✅ NFT вручную выдан пользователю {target_uid}. Осталось NFT: {remaining}."
    )


async def cmd_fzheatlog(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzheatlog [N] — последние N изменений шкалы (§10.2)."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    try:
        limit = int(ctx.args[0]) if ctx.args else 20
    except ValueError:
        limit = 20
    limit = min(limit, 50)

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT ts, heat_before, heat_after, delta, reason "
            "FROM freeze_heat_log ORDER BY id DESC LIMIT ?", (limit,)
        ) as c:
            rows = await c.fetchall()

    if not rows:
        await update.message.reply_text("🌡 Лог шкалы пуст.")
        return

    lines = []
    for ts, before, after, delta, reason in reversed(rows):
        dt = datetime.fromtimestamp(ts, tz=timezone.utc).strftime("%d.%m %H:%M")
        sign = "+" if delta >= 0 else ""
        lines.append(f"  {dt} {before}%→{after}% ({sign}{delta}) <i>{reason}</i>")

    await update.message.reply_text(
        f"🌡 <b>Лог шкалы болота (последние {limit}):</b>\n\n" + "\n".join(lines),
        parse_mode=ParseMode.HTML,
    )


async def cmd_fzexport(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzexport — CSV-выгрузка статистики игроков (§10.2)."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            """SELECT t.uid,
                      COUNT(t.id)                       AS total_throws,
                      SUM(CASE WHEN t.won=1 THEN 1 ELSE 0 END) AS wins,
                      SUM(CASE WHEN t.pool='sold_out' THEN 1 ELSE 0 END) AS pool_throws,
                      COALESCE(p.total_stars, 0)        AS stars_spent
               FROM freeze_throws t
               LEFT JOIN (
                   SELECT uid, SUM(stars) as total_stars FROM freeze_payments GROUP BY uid
               ) p ON p.uid = t.uid
               GROUP BY t.uid
               ORDER BY total_throws DESC""",
        ) as c:
            rows = await c.fetchall()

    # Строим CSV
    lines = ["uid,total_throws,wins,pool_throws,stars_spent"]
    for row in rows:
        lines.append(",".join(str(v) for v in row))
    csv_text = "\n".join(lines)

    buf = io.BytesIO(csv_text.encode("utf-8"))
    buf.name = "freeze_export.csv"

    await ctx.bot.send_document(
        uid,
        document=buf,
        caption=f"🧊 Freeze export{SEP}{ui_plural(len(rows), 'игрок', 'игрока', 'игроков')}",
    )


# ══════════════════════════════════════════════════════════════════════════════
# 🔘  CALLBACK-ХЕНДЛЕР (вызывается из on_callback в frog_bot.py)
# ══════════════════════════════════════════════════════════════════════════════

async def _fz_on_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Точка входа из on_callback() в frog_bot.py.
    Вызывать так:
        if d.startswith("fz_") or d.startswith("fzquiz_"):
            return await _fz_on_callback(update, ctx)
    """
    q   = update.callback_query
    uid = q.from_user.id
    d   = q.data

    await q.answer()

    # ── Кнопки панели управления /fzpanel ────────────────────────────────────
    if d.startswith("fzadm_"):
        if not _fz_is_admin(uid):
            await q.answer("Нет прав.", show_alert=True)
            return
        if d == "fzadm_refresh":
            state     = await _fz_state()
            status    = state.get("status", FZ_INACTIVE)
            heat      = state.get("heat", 0)
            remaining = state.get("remaining_nft", 0)
            total_nft = state.get("total_nft", FZ_TOTAL_NFT)
            ends_at   = state.get("ends_at", 0)
            time_left = max(0, int(ends_at - time.time()))
            h, m = divmod(time_left // 60, 60)
            async with aiosqlite.connect(DB_PATH) as _pdb:
                async with _pdb.execute("SELECT COUNT(*) FROM freeze_throws") as _pc:
                    total_throws = (await _pc.fetchone())[0] or 0
                async with _pdb.execute("SELECT COUNT(DISTINCT uid) FROM freeze_throws") as _pc:
                    total_players = (await _pc.fetchone())[0] or 0
                async with _pdb.execute("SELECT SUM(stars) FROM freeze_payments") as _pc:
                    total_stars = (await _pc.fetchone())[0] or 0
            status_emoji = {
                FZ_INACTIVE: "⚫", FZ_ACTIVE: "🟢", FZ_SOLD_OUT: "🟡",
                FZ_FINALE: "🔴", FZ_FINISHED: "🏁"
            }.get(status, "❓")
            text = (
                f"🧊 <b>Фриз-ивент — панель управления</b>\n"
                "\n"
                f"Статус: {status_emoji} <b>{status}</b> До конца: <b>{h}ч {m}м</b>\n"
                f"🍦 NFT: <b>{remaining}/{total_nft}</b> 🌡 Жара: <b>{heat}%</b>\n"
                f"{_E_CHART} Бросков: <b>{total_throws:,}</b> {_E_USERS} Игроков: <b>{total_players:,}</b> {_E_STARS} Stars: <b>{total_stars or 0:,}</b>\n"
                "\n"
                f"<b>Быстрые команды:</b>\n"
                f"<code>/fzaddnft &lt;N&gt;</code> — пополнить пул NFT\n"
                f"<code>/fzgrant &lt;uid&gt; &lt;N&gt;</code> — выдать N кубиков игроку\n"
                f"<code>/fznft_drop &lt;uid&gt;</code> — выдать NFT вручную\n"
                f"<code>/fzsetheat &lt;0-100&gt;</code> — выставить шкалу жары\n"
                f"<code>/fzsetdrop &lt;N&gt;</code> — изменить шанс дропа (сейчас 1/{FZ_DROP_CHANCE})\n"
                f"<code>/fzsetpkg &lt;idx&gt; &lt;stars&gt; &lt;cubes&gt;</code> — изменить пакет\n"
                f"<code>/fzpkglist</code> — список пакетов"
            )
            kb = InlineKeyboardMarkup([
                [btn("▶️ Запустить", callback_data="fzadm_start"),
                 btn("⏹ Остановить", callback_data="fzadm_stop")],
                [btn("🔄 Обновить", callback_data="fzadm_refresh"),
                 btn("📊 Статус", callback_data="fz_dashboard")],
            ])
            try:
                await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
            except (BadRequest, Forbidden, TimedOut):
                pass
            return
        if d == "fzadm_start":
            state = await _fz_state()
            if state.get("status") != FZ_INACTIVE:
                await q.answer((f"Ивент уже запущен: {state.get('status')}")[:200], show_alert=True)
                return
            now = time.time()
            await _fz_set_state(
                status="ACTIVE", started_at=now, ends_at=now + FZ_DURATION_SECS,
                total_nft=FZ_TOTAL_NFT, remaining_nft=FZ_TOTAL_NFT,
                heat=50, daily_throws=0, pool_throws=0,
            )
            await q.answer("✅ Ивент запущен", show_alert=True)
            return
        if d == "fzadm_stop":
            state = await _fz_state()
            if state.get("status") in (FZ_INACTIVE, FZ_FINISHED):
                await q.answer("Ивент не активен.", show_alert=True)
                return
            asyncio.create_task(_fz_run_results(ctx.bot))
            await q.answer("⏹ Остановка запущена...", show_alert=True)
            return
        return

    # ── Подтверждение / отмена анонса ────────────────────────────────────────
    if d.startswith("fz_pub_ok_") or d.startswith("fz_pub_no_"):
        token = d.split("_")[-1]
        if not _fz_is_admin(uid):
            await q.answer("Нет прав.", show_alert=True)
            return

        if d.startswith("fz_pub_ok_"):
            pending = _fz_pending_announces.pop(token, None)
            if not pending:
                await q.answer("Анонс уже опубликован или отменён.", show_alert=True)
                try:
                    await q.edit_message_reply_markup(reply_markup=None)
                except (BadRequest, Forbidden, TimedOut):
                    pass
                return
            await q.answer("Публикую...")
            try:
                await q.edit_message_text(
                    q.message.text + f"\n\n<i>{_E_CHECK} Опубликовано</i>",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
            await announce(ctx.bot, pending["text"], **pending["kwargs"])
        else:  # fz_pub_no_
            _fz_pending_announces.pop(token, None)
            await q.answer("Анонс отменён.")
            try:
                await q.edit_message_text(
                    q.message.text + f"\n\n<i>{_E_CROSS} Отменено</i>",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
        return

    # ── Главный дашборд ивента (из главного меню) ────────────────────────────
    if d == "fz_dashboard":
        state  = await _fz_state()
        status = state.get("status", FZ_INACTIVE)
        if status == FZ_INACTIVE:
            await q.edit_message_text(
                f"{_E_ICE} <b>Фриз-ивент</b>\n\n<i>Ивент пока не запущен. Следи за анонсами</i>",
                parse_mode=ParseMode.HTML,
            )
            return
        f = await db_get(uid)
        heat      = state.get("heat", 0)
        remaining = state.get("remaining_nft", 0)
        heat_emoji, heat_label, _ = _fz_heat_info(heat)
        total_throws = f.get("fz_total_throws", 0) if f else 0
        wins         = f.get("fz_wins",          0) if f else 0
        stars_spent  = f.get("fz_stars_spent",   0) if f else 0
        p_at_least_one = round((1 - (1 - 1/FZ_DROP_CHANCE) ** max(total_throws, 1)) * 100, 2)
        ends_at  = state.get("ends_at", 0)
        time_left = max(0, int(ends_at - time.time()))
        h, m = divmod(time_left // 60, 60)
        time_str = f"{h//24}д {h%24}ч" if h > 24 else f"{h}ч {m}мин"
        status_labels = {
            FZ_ACTIVE:   "🟢 Активен",
            FZ_SOLD_OUT: "🍦 Sold-Out пул",
            FZ_FINALE:   "⚡ Финальный рывок!",
            FZ_FINISHED: "🏁 Завершён",
        }
        try:
            await q.edit_message_text(
                f"🧊 <b>Фриз-ивент</b> {status_labels.get(status, status)}\n"
                f"⏳ До конца: <b>{time_str}</b>\n"
                f"🍦 Осталось NFT: <b>{remaining} / {state.get('total_nft', FZ_TOTAL_NFT)}</b>\n\n"
                f"🌡 Болото: {_fz_heat_bar(heat)}\n"
                f"Состояние: {heat_emoji} {heat_label}\n\n"
                f"<b>Твои результаты:</b>\n"
                f"  🧊 Кубиков брошено: <b>{total_throws}</b>\n"
                f"  {_E_TROPHY} NFT дропов: <b>{wins}</b>\n"
                f"  {_E_STARS} Stars потрачено: <b>{stars_spent}</b>\n"
                f"  🎯 Шанс победы: <b>{p_at_least_one}%</b> <i>(дроп + топ + розыгрыш)</i>\n"
                f"  <i>Подробно: {_E_CHART} Мои броски</i>",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [btn("🧊 Купить кубики", callback_data="fz_menu", style="primary")],
                    [btn("🌡 Шкала болота",  callback_data="fz_swamp"),
                     btn("🏆 Топ",           callback_data="fz_topthrows")],
                    [btn("◀️ Главное меню", callback_data="refresh")],
                ]),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Меню покупки кубиков ──────────────────────────────────────────────────
    if d == "fz_menu":
        state = await _fz_state()
        remaining = state.get("remaining_nft", 0)
        heat      = state.get("heat", 0)
        status    = state.get("status", FZ_INACTIVE)

        if status not in (FZ_ACTIVE, FZ_SOLD_OUT, FZ_FINALE):
            try:
                await q.edit_message_text("🧊 Ивент не активен.", parse_mode=ParseMode.HTML)
            except (BadRequest, Forbidden, TimedOut):
                pass
            return

        sold_note = ""
        if status == FZ_SOLD_OUT:
            sold_note = (
                f"\n\n⚠️ <b>Sold-Out пул активен.</b> "
                f"Каждый бросок: +{FZ_POOL_COINS_PER_THROW}{_E_COIN}"
            )

        pkg_rows = []
        for pkg in FREEZE_PACKAGES:
            cool = f"  −{abs(pkg['heat_bonus'])}% жары" if pkg["heat_bonus"] < 0 else ""
            pkg_rows.append([btn(
                f"{pkg['label']}{SEP}{pkg['stars']}{_E_STARS}{SEP}{pkg['cubes']} куб.{cool}",
                callback_data=f"fz_buy_{pkg['idx']}",
            )])
        pkg_rows.append([
            btn("📊 Мои броски",  callback_data="fz_mythrows"),
            btn("◀️ Назад",    callback_data="fz_dashboard"),
        ])

        try:
            await q.edit_message_text(
                f"<b>Кубики льда</b>\n\n"
                f"Победный бросок: <b>{FZ_DROP_CHANCE}/{FZ_DROP_CHANCE}</b>\n"
                f"Осталось NFT: <b>{remaining} / {state.get('total_nft', FZ_TOTAL_NFT)}</b>\n"
                f"Болото: {_fz_heat_bar(heat)}"
                + sold_note,
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup(pkg_rows),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Кнопки покупки конкретного пакета → инвойс Stars ─────────────────────
    if d.startswith("fz_buy_"):
        try:
            pkg_idx = int(d.split("_")[2])
            pkg     = FREEZE_PACKAGES[pkg_idx]
        except (IndexError, ValueError):
            return

        state = await _fz_state()
        if state.get("status") not in (FZ_ACTIVE, FZ_SOLD_OUT, FZ_FINALE):
            await q.answer("Ивент не активен", show_alert=True)
            return

        # Проверка one_time: пакет за 1⭐ — только раз на ивент
        if pkg.get("one_time"):
            async with aiosqlite.connect(DB_PATH) as _db:
                async with _db.execute(
                    "SELECT 1 FROM freeze_payments WHERE uid=? AND pkg_idx=?", (uid, pkg_idx)
                ) as _c:
                    if await _c.fetchone():
                        await q.answer(
                            "🐣 Этот пакет можно купить только 1 раз за ивент!",
                            show_alert=True,
                        )
                        return

        try:
            await ctx.bot.send_invoice(
                chat_id=uid,
                title=f"🧊 {pkg['label']}",
                description=pkg["desc"],
                payload=f"fz_pkg_{pkg_idx}",
                currency="XTR",
                prices=[{"label": pkg["label"], "amount": pkg["stars"]}],
            )
        except Exception as e:
            logger.error("fz_buy_%s invoice error: uid=%s err=%s", pkg_idx, uid, e)
            await q.answer("Ошибка создания инвойса, попробуй ещё раз.", show_alert=True)
        return

    # ── Мои броски ────────────────────────────────────────────────────────────
    if d == "fz_mythrows":
        f = await db_get(uid)
        if not f:
            await q.answer("Профиль не найден.", show_alert=True)
            return

        total  = f.get("fz_total_throws", 0)
        wins   = f.get("fz_wins", 0)
        stars  = f.get("fz_stars_spent", 0)

        # Шанс учитывает: дроп (1/1000) + топ-3 по кубикам + 2 рандомных (≥5)
        async with aiosqlite.connect(DB_PATH) as _mdb:
            async with _mdb.execute(
                "SELECT COUNT(*) FROM freeze_throws GROUP BY uid ORDER BY COUNT(*) DESC LIMIT 1"
            ) as _mc:
                _rows_top = await _mdb.execute(
                    "SELECT uid, COUNT(*) as cnt FROM freeze_throws GROUP BY uid ORDER BY cnt DESC LIMIT ?",
                    (FZ_FINAL_TOP_CUBES,)
                )
                _top_uids = [r[0] for r in await _rows_top.fetchall()]
            async with _mdb.execute(
                "SELECT COUNT(DISTINCT uid) FROM freeze_throws"
            ) as _ec:
                _total_players = (await _ec.fetchone() or [0])[0]
            async with _mdb.execute(
                "SELECT COUNT(*) FROM (SELECT uid FROM freeze_throws GROUP BY uid HAVING COUNT(*)>=5)"
            ) as _elc:
                _eligible = (await _elc.fetchone() or [0])[0]

        _p_drop   = round((1 - (1 - 1/FZ_DROP_CHANCE) ** max(total, 1)) * 100, 2)
        _in_top3  = uid in _top_uids
        _p_random = round(min(FZ_FINAL_RANDOM / max(_eligible, 1) * 100, 100), 1) if total >= 5 else 0.0
        # Суммарный шанс: P(дроп) + P(топ-3) + P(рандомный розыгрыш), без двойного счёта
        _p_drop_dec   = _p_drop / 100
        _p_top3_dec   = 1.0 if _in_top3 else 0.0
        _p_random_dec = _p_random / 100
        _p_any = round(min(
            (1 - (1 - _p_drop_dec) * (1 - _p_top3_dec) * (1 - _p_random_dec)) * 100,
            100
        ), 1)
        _top3_str = " 🏅 В топ-3 по кубикам!" if _in_top3 else ""

        try:
            await q.edit_message_text(
                f"<b>Твои броски — Фриз-ивент</b>\n\n"
                f"Кубиков брошено: <b>{total}</b>\n"
                f"NFT дропов: <b>{wins}</b>\n"
                f"Stars потрачено: <b>{stars}</b>\n\n"
                f"<b>Шанс получить NFT:</b>\n"
                f"  Дроп (1000/1000): <b>{_p_drop}%</b>\n"
                f"  Топ-3 по кубикам: <b>{f'да {_E_CHECK}' if _in_top3 else 'нет'}</b>{_top3_str}\n"
                f"  Розыгрыш (≥5 кубиков): <b>{_p_random}%</b>\n"
                f"  ─────────────────────────\n"
                f"  Суммарный шанс: <b>{_p_any}%</b>",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [btn("🧊 Купить кубики", callback_data="fz_menu", style="primary")],
                    [btn("◀️ Назад", callback_data="fz_menu"),
                     btn("📊 Дашборд", callback_data="fz_dashboard")],
                ]),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Шкала болота (инлайн) ─────────────────────────────────────────────────
    if d == "fz_swamp":
        state = await _fz_state()
        heat  = state.get("heat", 0)
        heat_emoji, heat_label, coin_mult = _fz_heat_info(heat)
        try:
            await q.edit_message_text(
                f"<b>Шкала болота</b>\n\n"
                f"{_fz_heat_bar(heat)}\n"
                f"{heat_emoji} {heat_label}\n\n"
                f"Монеты от ква: ×{coin_mult:.2f}\n"
                f"Шанс 1/1000 не зависит от жары {_E_CHECK}\n\n"
                f"<i>Охлади болото: /icecube</i>",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[
                    btn("◀️ Назад", callback_data="fz_menu"),
                    btn("📊 Дашборд", callback_data="fz_dashboard"),
                ]]),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Топ по броскам ────────────────────────────────────────────────────────
    if d == "fz_topthrows":
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT uid, COUNT(*) as cnt FROM freeze_throws "
                "GROUP BY uid ORDER BY cnt DESC LIMIT 5"
            ) as c:
                rows = await c.fetchall()
        lines = []
        for i, (row_uid, cnt) in enumerate(rows):
            f = await db_get(row_uid)
            n = _html.escape(fname(f)) if f else str(row_uid)
            medal = ["🥇","🥈","🥉","4️⃣","5️⃣"][i]
            lines.append(f"{medal} <b>{n}</b> — {cnt}")
        try:
            await q.edit_message_text(
                "<b>Топ-5 по броскам</b>\n\n" + ("\n".join(lines) or "—"),
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[
                    btn("◀️ Назад", callback_data="fz_menu"),
                    btn("📊 Дашборд", callback_data="fz_dashboard"),
                ]]),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Подписка на напоминалку ───────────────────────────────────────────────
    if d == "fz_remind":
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "INSERT OR IGNORE INTO freeze_remind(uid, ts) VALUES(?,?)",
                (uid, time.time()),
            )
            await db.commit()
        await q.answer("🔔 Напомним за 6 часов до конца ивента", show_alert=True)
        return

    # ── Квиз ─────────────────────────────────────────────────────────────────
    if d.startswith("fzquiz_"):
        answer = d[-1].upper()  # A/B/C/D

        async with aiosqlite.connect(DB_PATH) as db:
            # Проверяем, не отвечал ли уже
            async with db.execute(
                "SELECT answer FROM freeze_quiz WHERE uid=?", (uid,)
            ) as c:
                existing = await c.fetchone()
            if existing:
                await q.answer(
                    f"Ты уже ответил: 🅷 {existing[0]}. Ответ не изменить!",
                    show_alert=True,
                )
                return
            await db.execute(
                "INSERT INTO freeze_quiz(uid, answer, ts) VALUES(?,?,?)",
                (uid, answer, time.time()),
            )
            await db.commit()

        if answer == "B":  # Правильный ответ — Эстивация
            await q.answer(
                "✅ Правильно! Эстивация — летняя спячка лягушек.\n"
                f"+{FZ_QUIZ_CUBES} кубиков льда! 🧊",
                show_alert=True,
            )
            asyncio.create_task(_fz_award_quiz_cubes(uid, ctx.bot))
        else:
            labels = {"A": "Гибернация", "C": "Диапауза", "D": "Анабиоз"}
            await q.answer(
                f"{_E_CROSS} Неверно. Ты выбрал: {labels.get(answer, answer)}.\n"
                "Правильный ответ: 🅑 Эстивация — летняя спячка лягушек.",
                show_alert=True,
            )
        return


