async def cmd_fzpanel(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzpanel — интерактивная панель управления фриз-ивентом."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    state = await _fz_state()
    status    = state.get("status", FZ_INACTIVE)
    heat      = state.get("heat", 0)
    remaining = state.get("remaining_nft", 0)
    total_nft = state.get("total_nft", FZ_TOTAL_NFT)
    ends_at   = state.get("ends_at", 0)
    time_left = max(0, int(ends_at - time.time()))
    h, m = divmod(time_left // 60, 60)

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT COUNT(*) FROM freeze_throws") as c:
            total_throws = (await c.fetchone())[0] or 0
        async with db.execute("SELECT COUNT(DISTINCT uid) FROM freeze_throws") as c:
            total_players = (await c.fetchone())[0] or 0
        async with db.execute("SELECT SUM(stars) FROM freeze_payments") as c:
            total_stars = (await c.fetchone())[0] or 0

    status_emoji = {
        FZ_INACTIVE: "⚫", FZ_ACTIVE: "🟢", FZ_SOLD_OUT: "🟡",
        FZ_FINALE: "🔴", FZ_FINISHED: "🏁"
    }.get(status, "❓")

    text = (
        f"🧊 <b>Фриз-ивент — панель управления</b>\n"
        "\n"
        f"Статус: {status_emoji} <b>{status}</b> До конца: <b>{h}ч {m}м</b>\n"
        f"🍦 NFT: <b>{remaining}/{total_nft}</b> 🌡 Жара: <b>{heat}%</b>\n"
        f"{_E_CHART} Бросков: <b>{total_throws:,}</b> {_E_USERS} Игроков: <b>{total_players:,}</b> {_E_STARS} Stars: <b>{total_stars or 0:,}</b>\n"
        "\n"
        f"<b>Быстрые команды:</b>\n"
        f"<code>/fzaddnft &lt;N&gt;</code> — пополнить пул NFT\n"
        f"<code>/fzgrant &lt;uid&gt; &lt;N&gt;</code> — выдать N кубиков игроку\n"
        f"<code>/fznft_drop &lt;uid&gt;</code> — выдать NFT вручную\n"
        f"<code>/fzsetheat &lt;0-100&gt;</code> — выставить шкалу жары\n"
        f"<code>/fzsetdrop &lt;N&gt;</code> — изменить шанс дропа (сейчас 1/{FZ_DROP_CHANCE})\n"
        f"<code>/fzsetpkg &lt;idx&gt; &lt;stars&gt; &lt;cubes&gt;</code> — изменить пакет\n"
        f"<code>/fzpkglist</code> — список пакетов\n"
        f"<code>/fzheatlog</code> — лог шкалы\n"
        f"<code>/fzexport</code> — CSV выгрузка\n"
        f"<code>/fzstatus</code> — полная статистика"
    )
    kb = InlineKeyboardMarkup([
        [btn("▶️ Запустить", callback_data="fzadm_start"),
         btn("⏹ Остановить", callback_data="fzadm_stop")],
        [btn("🔄 Обновить", callback_data="fzadm_refresh"),
         btn("📊 Статус", callback_data="fz_dashboard")],
    ])
    await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)


async def cmd_fzaddnft(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzaddnft <N> — пополнить пул NFT на N штук."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    if not ctx.args:
        state = await _fz_state()
        await update.message.reply_text(
            f"Использование: <code>/fzaddnft N</code>\n\n"
            f"Текущий пул: <b>{state.get('remaining_nft',0)} / {state.get('total_nft', FZ_TOTAL_NFT)}</b>",
            parse_mode=ParseMode.HTML,
        )
        return
    try:
        n = int(ctx.args[0])
        if n <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Укажи положительное число.")
        return

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE freeze_state SET remaining_nft=remaining_nft+?, total_nft=total_nft+? WHERE id=1",
            (n, n),
        )
        await db.commit()
        async with db.execute("SELECT remaining_nft, total_nft, status FROM freeze_state WHERE id=1") as c:
            row = await c.fetchone()

    remaining, total, status = row
    # Если статус был SOLD_OUT — автоматически возвращаем в ACTIVE
    if status == FZ_SOLD_OUT:
        await _fz_set_state(status=FZ_ACTIVE)
        status_note = "\n⚡ Статус SOLD_OUT → ACTIVE (NFT снова есть)"
    else:
        status_note = ""

    await update.message.reply_text(
        f"{_E_CHECK} Пул пополнен на <b>+{n} NFT</b>\n"
        f"🍦 Теперь: <b>{remaining} / {total}</b>{status_note}",
        parse_mode=ParseMode.HTML,
    )
    logger.info("fzaddnft: admin=%s added %s NFT, pool=%s/%s", uid, n, remaining, total)


async def cmd_fzsetdrop(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzsetdrop <N> — изменить шанс дропа на 1/N (в рамках текущей сессии бота)."""
    global FZ_DROP_CHANCE
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    if not ctx.args:
        await update.message.reply_text(
            f"Использование: <code>/fzsetdrop N</code>\n\n"
            f"Текущий шанс: <b>1/{FZ_DROP_CHANCE}</b>\n"
            f"Пример: /fzsetdrop 500 → шанс 1/500\n\n"
            f"<i>⚠️ Изменение действует до перезапуска бота. "
            f"Для постоянного изменения правь константу FZ_DROP_CHANCE в коде.</i>",
            parse_mode=ParseMode.HTML,
        )
        return
    try:
        n = int(ctx.args[0])
        if n < 1:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Укажи целое число ≥ 1.")
        return

    old = FZ_DROP_CHANCE
    FZ_DROP_CHANCE = n
    await update.message.reply_text(
        f"{_E_CHECK} Шанс дропа изменён: <b>1/{old}</b> → <b>1/{n}</b>\n"
        f"<i>Действует до перезапуска бота.</i>",
        parse_mode=ParseMode.HTML,
    )
    logger.info("fzsetdrop: admin=%s changed drop chance %s→%s", uid, old, n)


async def cmd_fzpkglist(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzpkglist — показать все пакеты кубиков с индексами."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    lines = ["<b>Пакеты кубиков льда:</b>\n"]
    for pkg in FREEZE_PACKAGES:
        heat_note = f"  (жара {pkg['heat_bonus']:+d}%)" if pkg["heat_bonus"] else ""
        lines.append(
            f"<b>idx {pkg['idx']}</b>: {pkg['label']}\n"
            f"   {pkg['stars']}{_E_STARS} → {pkg['cubes']} куб.{heat_note}\n"
            f"   <i>{pkg['desc']}</i>"
        )
    lines.append(
        f"\n{_E_PENCIL} Изменить: <code>/fzsetpkg &lt;idx&gt; &lt;stars&gt; &lt;cubes&gt;</code>\n"
        f"Пример: <code>/fzsetpkg 1 20 30</code> → idx 1 = 20{_E_STARS} за 30 кубиков"
    )
    await update.message.reply_text("\n\n".join(lines), parse_mode=ParseMode.HTML)


async def cmd_fzsetpkg(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/fzsetpkg <idx> <stars> <cubes> — изменить параметры пакета кубиков."""
    uid = update.effective_user.id
    if not _fz_is_admin(uid):
        await update.message.reply_text("⛔ Нет прав.")
        return
    if not ctx.args or len(ctx.args) < 3:
        await update.message.reply_text(
            "Использование: /fzsetpkg <idx> <stars> <cubes>\n\n"
            "Пример: /fzsetpkg 2 60 90\n"
            "Список пакетов: /fzpkglist",
        )
        return
    try:
        idx   = int(ctx.args[0])
        stars = int(ctx.args[1])
        cubes = int(ctx.args[2])
        if stars < 1 or cubes < 1:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ idx, stars и cubes — целые числа ≥ 1.")
        return

    pkg = next((p for p in FREEZE_PACKAGES if p["idx"] == idx), None)
    if pkg is None:
        await update.message.reply_text(f"{_E_CROSS} Пакет с idx={he(idx)} не найден. /fzpkglist", parse_mode=ParseMode.HTML)
        return

    old_stars, old_cubes = pkg["stars"], pkg["cubes"]
    pkg["stars"] = stars
    pkg["cubes"] = cubes
    # Обновляем desc
    ev = round(stars / cubes * FZ_DROP_CHANCE, 0) if cubes else 0
    # Обычный ⭐, а не премиум: этот desc уходит в send_invoice(description=...),
    # где Telegram HTML не разбирает и тег показался бы сырой разметкой.
    pkg["desc"] = f"{cubes} кубиков · {stars} Stars (EV {int(ev)}⭐)"

    await update.message.reply_text(
        f"{_E_CHECK} Пакет <b>idx {idx}</b> ({pkg['label']}) обновлён:\n"
        f"   {old_stars}{_E_STARS} / {old_cubes} куб. → <b>{stars}{_E_STARS} / {cubes} куб.</b>\n"
        f"<i>Действует до перезапуска. Для постоянного изменения — правь FREEZE_PACKAGES в коде.</i>",
        parse_mode=ParseMode.HTML,
    )
    logger.info("fzsetpkg: admin=%s idx=%s %s⭐/%scubes→%s⭐/%scubes", uid, idx, old_stars, old_cubes, stars, cubes)


async def cmd_resetwar(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/resetwar — принудительно завершить все зависшие набеги и стычки."""
    uid = update.effective_user.id
    if uid not in ADMIN_IDS:
        return

    now = time.time()
    raids_closed = 0
    skirmishes_closed = 0
    members_notified = 0

    async with aiosqlite.connect(DB_PATH) as db:
        # Закрываем все активные/pending набеги
        async with db.execute(
            "SELECT id, attacker_uid, participants FROM staya_raids "
            "WHERE phase NOT IN ('finished') AND status NOT IN ('success','failed')"
        ) as c:
            active_raids = await c.fetchall()

        for raid_id, att_uid, participants_json in active_raids:
            await db.execute(
                "UPDATE staya_raids SET phase='finished', status='cancelled' WHERE id=?",
                (raid_id,),
            )
            raids_closed += 1
            try:
                participants = json.loads(participants_json or "[]")
            except Exception:
                participants = [att_uid]
            for p_uid in (participants or [att_uid]):
                try:
                    await ctx.bot.send_message(
                        p_uid,
                        "⚔️ <b>Набег принудительно завершён администратором.</b>\n"
                        "Взносы не возвращаются. Теперь можешь начать новый.",
                        parse_mode=ParseMode.HTML,
                    )
                    members_notified += 1
                except (BadRequest, Forbidden, TimedOut):
                    pass

        # Закрываем ВСЕ стычки не в статусе finished (включая фантомные)
        async with db.execute(
            "SELECT id FROM staya_skirmishes WHERE status != 'finished' "
            "OR (status='finished' AND winner='cancelled' AND finished_at > ?)",
            (now - 300,),  # и недавно отменённые тоже — на случай незавершённых дуэлей
        ) as c:
            active_sk = [r[0] for r in await c.fetchall()]

        for sk_id in active_sk:
            await db.execute(
                "UPDATE staya_skirmishes SET status='finished', winner='cancelled', finished_at=? WHERE id=?",
                (now, sk_id),
            )
            await db.execute(
                "UPDATE skirmish_duels SET status='finished' "
                "WHERE skirmish_id=? AND status NOT IN ('finished')",
                (sk_id,),
            )
            skirmishes_closed += 1
            # Уведомляем участников
            async with db.execute(
                "SELECT user_id FROM skirmish_members WHERE skirmish_id=?", (sk_id,)
            ) as mc:
                sk_members = [r[0] for r in await mc.fetchall()]
            for m_uid in sk_members:
                try:
                    await ctx.bot.send_message(
                        m_uid,
                        "⚔️ <b>Стычка принудительно завершена администратором.</b>\n"
                        "Теперь можешь участвовать в новой.",
                        parse_mode=ParseMode.HTML,
                    )
                    members_notified += 1
                except (BadRequest, Forbidden, TimedOut):
                    pass

        await db.commit()

    await update.message.reply_text(
        f"{_E_CHECK} <b>Сброс войны выполнен</b>\n"
        "\n"
        f"🏹 Набегов закрыто: <b>{raids_closed}</b>\n"
        f"{_E_SWORDS} Стычек закрыто: <b>{skirmishes_closed}</b>\n"
        f"📨 Уведомлений отправлено: <b>{members_notified}</b>",
        parse_mode=ParseMode.HTML,
    )


