    app.add_handler(CommandHandler("fzquiz",     cmd_fzquiz))
    app.add_handler(CommandHandler("fzfinale",   cmd_fzfinale))
    app.add_handler(CommandHandler("fzresults",  cmd_fzresults))
    app.add_handler(CommandHandler("fzgrant",    cmd_fzgrant))
    app.add_handler(CommandHandler("fzsetheat",  cmd_fzsetheat))
    app.add_handler(CommandHandler("fzaddheat",  cmd_fzaddheat))
    app.add_handler(CommandHandler("fznft_drop", cmd_fznft_drop))
    app.add_handler(CommandHandler("fzheatlog",  cmd_fzheatlog))
    app.add_handler(CommandHandler("fzexport",   cmd_fzexport))
    app.add_handler(CommandHandler("fzpanel",    cmd_fzpanel))
    app.add_handler(CommandHandler("fzaddnft",   cmd_fzaddnft))
    app.add_handler(CommandHandler("fzsetdrop",  cmd_fzsetdrop))
    app.add_handler(CommandHandler("fzpkglist",  cmd_fzpkglist))
    app.add_handler(CommandHandler("fzsetpkg",   cmd_fzsetpkg))
    app.add_handler(CommandHandler("resetwar",   cmd_resetwar))

    app.add_handler(CommandHandler("newsdigest",  cmd_newsdigest))

    # Хендлер форвардов для верификации репостов
    # Добавляем только для личных чатов, чтобы не конфликтовать с on_message
    app.add_handler(MessageHandler(
        filters.ChatType.PRIVATE & filters.FORWARDED,
        _fz_handle_forward,
    ))

    logger.info("🧊 Фриз-ивент хендлеры зарегистрированы (%d user + %d admin команд + репост)",
                6, 10)


