# ══════════════════════════════════════════════════════════════════════════════
# ⚙️  КОНФИГУРАЦИЯ ИЗ .env
# ══════════════════════════════════════════════════════════════════════════════
# Ни один секрет не хранится в коде. Файл .env лежит рядом с bot.py, в git не
# попадает (см. .gitignore), образец — в .env.example.
#
# Приоритет: переменная окружения → значение из .env → значение по умолчанию.
# Уже выставленное окружение сильнее файла, поэтому в докере и systemd можно
# переопределять, не трогая .env.
#
# Помимо явных настроек ниже, ЛЮБУЮ константу модуля можно переопределить
# переменной FROG_<ИМЯ> — см. apply_env_overrides() в конце файла.

ENV_FILE = os.getenv("ENV_FILE", ".env")


def _load_dotenv(path: str = ENV_FILE) -> int:
    """
    Читает .env: строки KEY=VALUE, комментарии с #, значения в кавычках.
    Уже заданные переменные окружения не перетирает.
    """
    if not os.path.isfile(path):
        return 0
    loaded = 0
    with open(path, encoding="utf-8") as fh:
        for raw in fh:
            line = raw.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, _, val = line.partition("=")
            key = key.strip()
            val = val.strip()
            # export KEY=VALUE тоже принимаем
            if key.startswith("export "):
                key = key[7:].strip()
            if len(val) >= 2 and val[0] == val[-1] and val[0] in "\"'":
                val = val[1:-1]
            if key and key not in os.environ:
                os.environ[key] = val
                loaded += 1
    return loaded


_ENV_LOADED = _load_dotenv()

# Секреты, которых не хватает. Проверяются в main(), а не при импорте, чтобы
# файл оставался импортируемым для тестов и утилит.
_MISSING_REQUIRED: list[str] = []


def env_str(key: str, default: str = "", *, required: bool = False) -> str:
    val = os.getenv(key, "").strip()
    if not val:
        if required:
            _MISSING_REQUIRED.append(key)
        return default
    return val


def env_int(key: str, default: int) -> int:
    raw = os.getenv(key, "").strip()
    if not raw:
        return default
    try:
        return int(raw)
    except ValueError:
        logger.warning("ENV %s=%r — не число, взято значение по умолчанию %s",
                       key, raw, default)
        return default


def env_float(key: str, default: float) -> float:
    raw = os.getenv(key, "").strip()
    if not raw:
        return default
    try:
        return float(raw)
    except ValueError:
        logger.warning("ENV %s=%r — не число, взято %s", key, raw, default)
        return default


def env_bool(key: str, default: bool) -> bool:
    raw = os.getenv(key, "").strip().lower()
    if not raw:
        return default
    return raw in ("1", "true", "yes", "on", "да")


def env_ids(key: str, default: str = "") -> list[int]:
    """Список числовых id через запятую: ADMIN_IDS=111,222,333"""
    raw = os.getenv(key, default).strip()
    out = []
    for part in raw.replace(";", ",").split(","):
        part = part.strip()
        if not part:
            continue
        try:
            out.append(int(part))
        except ValueError:
            logger.warning("ENV %s: %r — не число, пропущено", key, part)
    return out


# ══════════════════════════════════════════════════════════════════════════════
# 📋  СИСТЕМА ЛОГИРОВАНИЯ
#
#  Все print() / WARNING / ERROR / CRITICAL пишутся одновременно:
#    - в консоль (как было)
#    - в файл bot.log  (ротация: 5 МБ × 3 файла = макс 15 МБ на диске)
#
#  Скачать последние логи: /adminlogs [N]  — отправит файл в ЛС
#  Уровень логов: задаётся переменной окружения LOG_LEVEL (DEBUG/INFO/WARNING/ERROR)
#  По умолчанию: INFO
# ══════════════════════════════════════════════════════════════════════════════

LOG_FILE = os.getenv("LOG_FILE", "bot.log")
LOG_LEVEL = getattr(logging, os.getenv("LOG_LEVEL", "INFO").upper(), logging.INFO)

# Формат: время | уровень | сообщение
_log_formatter = logging.Formatter(
    fmt="%(asctime)s | %(levelname)-8s | %(message)s",
    datefmt="%Y-%m-%d %H:%M:%S",
)

# Консольный хендлер
_console_handler = logging.StreamHandler()
_console_handler.setFormatter(_log_formatter)

# Файловый хендлер с ротацией (5 МБ, 3 резервных файла)
_file_handler = logging.handlers.RotatingFileHandler(
    LOG_FILE, maxBytes=5 * 1024 * 1024, backupCount=3, encoding="utf-8"
)
_file_handler.setFormatter(_log_formatter)

# Корневой логгер
logging.basicConfig(level=LOG_LEVEL, handlers=[_console_handler, _file_handler])
logger = logging.getLogger("frog_bot")

# Подавляем шумные сетевые и фреймворк-логгеры
for _noisy in (
    "httpx", "httpcore", "httpcore.http11", "httpcore.http2",
    "httpcore.connection", "httpcore.proxy",
    "aiohttp", "aiohttp.access", "aiohttp.client", "aiohttp.connector",
    "urllib3", "urllib3.connectionpool",
    "telegram", "telegram.ext", "telegram.bot",
    "apscheduler", "apscheduler.scheduler", "apscheduler.executors",
    "hpack", "h2", "h11",
    "charset_normalizer",
    "asyncio",
):
    logging.getLogger(_noisy).setLevel(logging.WARNING)

# Перехватчик необработанных исключений asyncio
def _asyncio_exception_handler(loop, context):
    exc = context.get("exception")
    msg = context.get("message", "неизвестная ошибка asyncio")
    if exc:
        logger.error("asyncio unhandled: %s — %s", msg, exc, exc_info=exc)
    else:
        logger.error("asyncio unhandled: %s", msg)

# Патч стандартного print → дублирование в лог (опционально — не ломает ничего)
_builtin_print = print
def print(*args, **kwargs):  # noqa: A001
    _builtin_print(*args, **kwargs)
    try:
        text = " ".join(str(a) for a in args)
        if any(kw in text.lower() for kw in ("error", "ошибка", "exception", "traceback")):
            logger.error(text)
        elif any(kw in text.lower() for kw in ("warn", "предупреждение", "⚠")):
            logger.warning(text)
        else:
            logger.info(text)
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)

logger.info("=" * 60)
logger.info("🐸 Frog Bot запускается, LOG_FILE=%s, LOG_LEVEL=%s", LOG_FILE, logging.getLevelName(LOG_LEVEL))
logger.info("=" * 60)



# ══════════════════════════════════════════════════════════════════════════════
# 🎨  Bot API 9.4 — Цветные кнопки и иконки (совместимо с PTB 20.x и 22.x)
#
#  PTB не поддерживает поля `style` и `icon_custom_emoji_id` нативно.
#  PTB 22.x использует __slots__ в TelegramObject, поэтому monkey-patch
#  через setattr не работает. Решение — подкласс с собственными __slots__
#  и переопределённым to_dict().
#
#  Значения style:
#    "primary" — синяя   (главные действия)
#    "success" — зелёная (подтвердить, принять, присоединиться)
#    "danger"  — красная (отмена, сдаться, бан, удалить)
# ══════════════════════════════════════════════════════════════════════════════

class _StyledButton(InlineKeyboardButton):
    """
    Подкласс InlineKeyboardButton с поддержкой Bot API 9.4:
    добавляет поля `style` и `icon_custom_emoji_id` в сериализованный dict.
    Совместим с PTB 20.x и 22.x (обходит ограничения __slots__).
    """
    __slots__ = ("_btn_style", "_btn_icon_id")

    def __init__(self, *args, _style: str = None, _icon_id: str = None, **kwargs):
        super().__init__(*args, **kwargs)
        # Используем object.__setattr__ чтобы обойти __slots__ родителя
        object.__setattr__(self, "_btn_style", _style)
        object.__setattr__(self, "_btn_icon_id", _icon_id)

    def to_dict(self, recursive: bool = True) -> dict:
        d = super().to_dict(recursive=recursive)
        s = object.__getattribute__(self, "_btn_style")
        i = object.__getattribute__(self, "_btn_icon_id")
        if s:
            d["style"] = s
        if i:
            d["icon_custom_emoji_id"] = i
        return d


