# ── Per-user asyncio.Lock ─────────────────────────────────────────────────────
# Главная причина откатов монет/обликов: два callback от одного юзера приходят
# одновременно, оба делают db_get → получают одни и те же данные → оба меняют
# монеты → второй db_save перезаписывает первый. Лок гарантирует очерёдность.
_USER_WRITE_LOCKS: dict[int, asyncio.Lock] = {}

def _get_user_lock(uid: int) -> asyncio.Lock:
    if uid not in _USER_WRITE_LOCKS:
        _USER_WRITE_LOCKS[uid] = asyncio.Lock()
    return _USER_WRITE_LOCKS[uid]


