def lang(f_or_str) -> str:
    """Получить код языка из словаря игрока или вернуть переданную строку."""
    if isinstance(f_or_str, dict):
        return f_or_str.get("lang", "ru") or "ru"
    if isinstance(f_or_str, str) and f_or_str in _LANGS:
        return f_or_str
    return "ru"

def t(key: str, f_or_lang="ru", **kwargs) -> str:
    """
    Перевести ключ на язык игрока.
    t("care_feed", f)           → "🍎 Покормить" / "🍎 Feed"
    t("levelup", f, level=5, coins=50)  → с подстановкой
    """
    lg = lang(f_or_lang)
    val = _LANGS.get(lg, _LANGS["ru"]).get(key) or _LANGS["ru"].get(key) or key
    if kwargs and isinstance(val, str):
        try:
            val = val.format(**kwargs)
        except (KeyError, ValueError):
            pass
    return val

def t_mood(mood: str, f_or_lang="ru") -> str:
    """Случайная фраза настроения на языке игрока."""
    lg = lang(f_or_lang)
    phrases = _LANGS.get(lg, _LANGS["ru"]).get(f"mood_{mood}") or _LANGS["ru"].get(f"mood_{mood}", ["..."])
    return random.choice(phrases)

