# ══════════════════════════════════════════════════════════════════════════════
# 🤖  АНТИБОТ: детект подозрительной активности + капча
#
#  Принцип работы:
#   1. _action_log[uid] — скользящее окно: список timestamp действий за 60 сек.
#   2. Если за 60 сек игрок делает ≥ ANTIBOT_THRESHOLD одинаковых действий —
#      бот уводит его в капчу: блокирует все игровые команды до ответа.
#   3. Капча = случайный пример (a + b), ответ хранится в _captcha_pending.
#   4. Уведомление летит первому из ADMIN_IDS.
#   5. Отдельный лимит: /feed не чаще 1 разной лягушки в 60 секунд (глобально
#      на кормящего, а не только per-target).
# ══════════════════════════════════════════════════════════════════════════════

# ─── Настройки ──────────────────────────────────────────────────────────────
ANTIBOT_WINDOW      = 60        # секунд — размер скользящего окна
ANTIBOT_THRESHOLD   = 15        # действий в окне → подозрение
ANTIBOT_SAME_ACTION = 10        # одинаковых действий в окне → тоже подозрение
CAPTCHA_TTL         = 300       # секунд — на сколько выдаётся капча
FEED_GLOBAL_CD      = 60        # секунд — глобальный КД между кормлениями разных лягушек

# ─── In-memory хранилища ─────────────────────────────────────────────────────
# {uid: [(ts, action_key), ...]}  — лог действий за ANTIBOT_WINDOW сек
_action_log: dict[int, list[tuple[float, str]]] = {}

# {uid: {"answer": int, "expires": float, "a": int, "b": int}}
_captcha_pending: dict[int, dict] = {}

# {uid: float}  — когда пользователь последний раз кормил ЛЮБУЮ чужую лягушку
_feed_global_cd: dict[int, float] = {}

# ─── Функции ─────────────────────────────────────────────────────────────────

def _antibot_record(uid: int, action: str) -> tuple[int, int]:
    """
    Записывает действие в скользящее окно.
    Возвращает (total_in_window, same_action_in_window).
    """
    now = time.time()
    log = _action_log.get(uid, [])
    # Удаляем устаревшие записи
    cutoff = now - ANTIBOT_WINDOW
    log = [(t, a) for t, a in log if t >= cutoff]
    log.append((now, action))
    _action_log[uid] = log
    total = len(log)
    same  = sum(1 for _, a in log if a == action)
    return total, same


def _issue_captcha(uid: int) -> dict:
    """Генерирует капчу и сохраняет в _captcha_pending. Возвращает dict с параметрами."""
    a = random.randint(10, 99)
    b = random.randint(10, 99)
    entry = {"answer": a + b, "a": a, "b": b, "expires": time.time() + CAPTCHA_TTL}
    _captcha_pending[uid] = entry
    return entry


def is_captcha_pending(uid: int) -> bool:
    """Проверяет, есть ли у пользователя активная незакрытая капча."""
    entry = _captcha_pending.get(uid)
    if not entry:
        return False
    if time.time() > entry["expires"]:
        _captcha_pending.pop(uid, None)
        return False
    return True


async def antibot_check(uid: int, action: str, bot) -> bool:
    """Антибот-проверка отключена вручную — всегда разрешаем."""
    return True


async def _check_feed_global_cd(uid: int) -> float:
    """
    Проверяет глобальный КД кормления.
    Возвращает 0 если разрешено, иначе — оставшиеся секунды.
    """
    last = _feed_global_cd.get(uid, 0.0)
    remaining = FEED_GLOBAL_CD - (time.time() - last)
    return max(0.0, remaining)


def _record_feed_global(uid: int) -> None:
    """Фиксирует время последнего кормления любой лягушки."""
    _feed_global_cd[uid] = time.time()


