# ── 🐸 NFT KissedFrog — каталог для продажи в магазине ─────────────────────
# Данные обновляются вручную. Отсортированы по цене (дешевле сначала).
# Поля: num, url, stars, model, model_doc, rarity(‰), pattern, pattern_doc, backdrop
# ── KissedFrog NFT каталог — динамический (обновляется каждые 3 часа) ────────
import os as _os
_NFT_CATALOG_FILE = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "kissed_frog_on_sale.json")

def _load_nft_catalog() -> list:
    """Загружает каталог NFT из файла. Если файл не найден — возвращает пустой список."""
    try:
        with open(_NFT_CATALOG_FILE, "r", encoding="utf-8") as _f:
            _raw = json.load(_f)
        # Конвертируем формат pars.py → формат бота
        result = []
        for item in _raw:
            m = item.get("model") or {}
            p = item.get("pattern") or {}
            b = item.get("backdrop") or {}
            # Цена бывает в звёздах, в тонах или сразу в обеих. Раньше сюда шло
            # одно поле price без учёта валюты: лот за 12.5 TON превращался в
            # «12⭐», а лот за 5000 звёзд — в «0⭐».
            _stars = int(item.get("price_stars") or 0)
            _ton   = float(item.get("price_ton") or 0)
            if not _stars and not _ton:
                # Старый формат парсера: одно поле price плюс currency
                _cur = str(item.get("currency") or "").lower()
                _val = item.get("price") or 0
                if _cur == "ton":
                    _ton = float(_val)
                else:
                    _stars = int(_val)
            entry = {
                "num":         item.get("num", 0),
                "url":         item.get("marketplace_url") or item.get("url", ""),
                "stars":       _stars,
                "ton":         _ton,
                "model":       m.get("name", "") if isinstance(m, dict) else str(m),
                "model_doc":   m.get("document_id", 0) if isinstance(m, dict) else 0,
                "rarity":      m.get("rarity_permille", 0) if isinstance(m, dict) else 0,
                "pattern":     p.get("name", "") if isinstance(p, dict) else str(p),
                "pattern_doc": p.get("document_id", 0) if isinstance(p, dict) else 0,
                "backdrop":    b.get("name", "") if isinstance(b, dict) else str(b),
            }
            result.append(entry)
        return result
    except FileNotFoundError:
        return []
    except Exception as _e:
        logger.warning("Ошибка загрузки NFT каталога: %s", _e)
        return []

NFT_CATALOG: list = _load_nft_catalog()

def get_nft_catalog() -> list:
    """Возвращает актуальный NFT каталог (всегда читает из памяти, обновляется job'ом)."""
    return NFT_CATALOG



