# ── Вспомогательные функции работы ────────────────────────────────────────────

def _pick_profession() -> dict:
    """Выбирает профессию с взвешенной вероятностью (редкие — реже)."""
    weights = [1 if "редко" in s["profession"].lower() else 10 for s in WORK_SCENARIOS]
    return random.choices(WORK_SCENARIOS, weights=weights, k=1)[0]


def build_work_report(frog_name: str) -> tuple[str, dict]:
    """
    Генерирует уникальный отчёт о рабочем дне.
    Возвращает (текст_сообщения, dict_изменений_статов).
    Ключи dict: coins, xp, hunger, happiness, health.
    """
    prof  = _pick_profession()
    scene = random.choice(prof["scenes"])

    base   = random.randint(prof.get("base_coins_min", WORK_BASE_MIN), prof.get("base_coins_max", WORK_BASE_MAX))
    mult   = scene.get("mult", 1.0)
    earned = int(base * mult)
    earned = max(200, min(earned, 1200))
    earned += scene.get("bonus_coins", 0)

    story   = scene["story"].format(name=frog_name)
    event   = scene["event"].format(name=frog_name)
    outcome = scene["outcome"].format(name=frog_name, earned=earned)

    bonus_parts = []
    if scene.get("bonus_hunger",    0) != 0: bonus_parts.append(f"{_E_FOOD}{scene['bonus_hunger']:+d}")
    if scene.get("bonus_happiness", 0) != 0: bonus_parts.append(f"😄{scene['bonus_happiness']:+d}")
    if scene.get("bonus_health",    0) != 0: bonus_parts.append(f"{_E_HEART}{scene['bonus_health']:+d}")
    if scene.get("bonus_xp",        0) != 0: bonus_parts.append(f"{_E_XP}{scene['bonus_xp']:+d}")
    bonus_line = ("  " + "  ".join(bonus_parts)) if bonus_parts else ""

    text = (
        f"{prof['emoji']} <b>{frog_name} вернулась с работы!</b>\n"
        f"<i>Профессия: {prof['profession']}</i>\n\n"
        f"{story}\n\n"
        f"{event}\n\n"
        f"{outcome}\n\n"
        f"Принесла домой: <b>+{earned}{_E_COIN}</b>{bonus_line}\n\n"
        f"<i>«Ква! Устала, но довольна!» 🐸</i>"
    )
    stats = {
        "coins":     earned,
        "xp":        scene.get("bonus_xp",        0),
        "hunger":    scene.get("bonus_hunger",     0),
        "happiness": scene.get("bonus_happiness",  0),
        "health":    scene.get("bonus_health",     0),
    }
    return text, stats


