def build_interactive_event_message(frog: dict, event: dict) -> tuple[str, InlineKeyboardMarkup]:
    """Формирует текст + клавиатуру для интерактивного события."""
    name = fname(frog)  # используем fname() бота (HTML-safe)
    text = f"🎲 <b>Случайное событие!</b>\n\n{event['text'].format(name=name)}"
    uid  = frog["user_id"]
    buttons = [
        [btn(c["label"], callback_data=f"iev|{event['id']}|{c['key']}|{uid}")]
        for c in event["choices"]
    ]
    return text, InlineKeyboardMarkup(buttons)


def _apply_choice_rewards(frog: dict, choice: dict) -> dict:
    """Применяет награды выбора к словарю лягушки."""
    def clamp(val, lo, hi): return max(lo, min(hi, val))
    frog["coins"]     = clamp(frog.get("coins",     0)   + choice.get("coins",     0), 0, 9_999_999)
    frog["xp"]        = clamp(frog.get("xp",        0)   + choice.get("xp",        0), 0, 9_999_999)
    frog["hunger"]    = clamp(frog.get("hunger",    50)   + choice.get("hunger",    0), 0, 100)
    frog["happiness"] = clamp(frog.get("happiness", 50)   + choice.get("happiness", 0), 0, 100)
    frog["health"]    = clamp(frog.get("health",   100)   + choice.get("health",    0), 0, 100)
    return frog


def _build_reward_summary(choice: dict) -> str:
    """Строка с итогами награды для вывода игроку."""
    parts = []
    if choice.get("coins",     0) > 0: parts.append(f"{_E_COIN} +{choice['coins']}")
    if choice.get("coins",     0) < 0: parts.append(f"{_E_COIN} {choice['coins']}")
    if choice.get("xp",        0) > 0: parts.append(f"{_E_XP} +{choice['xp']} XP")
    if choice.get("hunger",    0) != 0: parts.append(f"{_E_FOOD} {choice['hunger']:+d}")
    if choice.get("happiness", 0) != 0: parts.append(f"😄 {choice['happiness']:+d}")
    if choice.get("health",    0) != 0: parts.append(f"{_E_HEART} {choice['health']:+d}")
    return " | ".join(parts) if parts else "ничего особенного"


async def handle_interactive_event_choice(query, uid: int, event_id: str, choice_key: str, bot):
    """Обрабатывает нажатие кнопки интерактивного события (вызывается из on_callback)."""
    event = next((e for e in INTERACTIVE_EVENTS if e["id"] == event_id), None)
    if not event:
        await query.answer("Событие устарело.", show_alert=True)
        return
    choice = next((c for c in event["choices"] if c["key"] == choice_key), None)
    if not choice:
        await query.answer("Неизвестный выбор.", show_alert=True)
        return

    # ── Защита от двойного нажатия (плохой интернет) ─────────────────────────
    now_iev = time.time()
    last_iev = _IEV_PROCESSING.get(uid, 0)
    if now_iev - last_iev < 3.0:  # 3 секунды — достаточно чтобы обработать один выбор
        await query.answer("⏳ Уже обрабатывается...", show_alert=False)
        return
    _IEV_PROCESSING[uid] = now_iev

    frog = await db_get(uid)
    if not frog:
        await query.answer("Лягушка не найдена.", show_alert=True)
        return

    # Дополнительная проверка — если last_interactive_event очень свежий (< 5 сек),
    # значит кнопку нажали дважды и первый запрос уже сохранился
    if now_iev - frog.get("last_interactive_event", 0) < 5.0:
        await query.answer("Выбор уже засчитан", show_alert=True)
        return

    # Применяем награды и сохраняем — всегда, независимо от edit_text
    # Неуклюжая: +15% шанс что сработает is_lucky вариант если выбрала не-lucky
    _pers_clumsy = PERSONALITIES.get(frog.get("personality", ""), {})
    _lucky_bonus  = _pers_clumsy.get("lucky_event_bonus", 0.0)
    if not choice.get("is_lucky") and _lucky_bonus > 0 and random.random() < _lucky_bonus:
        # Переключаемся на lucky-вариант если он есть
        lucky_choice = next((c for c in event["choices"] if c.get("is_lucky")), None)
        if lucky_choice:
            choice = lucky_choice
    frog = _apply_choice_rewards(frog, choice)
    if choice.get("is_lucky"):
        frog["total_iev_lucky"] = frog.get("total_iev_lucky", 0) + 1
    if frog.get("health", 100) <= 0:
        frog["alive"] = 0
    frog["last_interactive_event"] = time.time()
    await levelup(frog, bot)
    await db_save(frog)

    name        = fname(frog)
    reward_line = _build_reward_summary(choice)
    result_text = choice["resolve"].format(name=name)

    result_msg = (
        f"{event['emoji']} <b>Результат события!</b>\n\n"
        f"{result_text}\n\n"
        f"<b>Награда:</b> {reward_line}"
    )
    if not frog.get("alive"):
        result_msg += f"\n\n{_E_SKULL} <b>Лягушка погибла!</b> Используй /revive"

    # answer() вызываем безусловно — иначе кнопка «крутится» вечно
    await query.answer()

    # edit_text отдельно — если упадёт, награды уже начислены
    try:
        await query.message.edit_text(result_msg, parse_mode=ParseMode.HTML)
    except Exception as _e:
        # Сообщение могло устареть — отправляем новым
        try:
            await bot.send_message(uid, result_msg, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass
        logger.warning("iev edit_text uid=%s: %s", uid, _e)

    logger.info("iev choice uid=%s event=%s choice=%s reward=%s", uid, event_id, choice_key, reward_line)




