def _staya_bar(current: int, target: int, width: int = 12) -> str:
    """Моноширный прогресс-бар для котла стаи."""
    pct = min(1.0, current / target) if target > 0 else 1.0
    filled = int(pct * width)
    pct_int = int(pct * 100)
    return f"<code>[{'▓' * filled}{'░' * (width - filled)}] {pct_int}%</code>"


