# ── DB-хелперы стай ───────────────────────────────────────────────────────────

async def staya_get(staya_id: int) -> dict | None:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM stayas WHERE id=?", (staya_id,)) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def staya_get_members(staya_id: int) -> list[dict]:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT sm.*, f.frog_name, f.first_name, f.username, f.level, f.alive "
            "FROM staya_members sm JOIN frogs f ON f.user_id=sm.user_id "
            "WHERE sm.staya_id=? ORDER BY sm.role DESC, sm.joined_at",
            (staya_id,),
        ) as c:
            rows = await c.fetchall()
    return [dict(r) for r in rows]


async def staya_of_user(uid: int) -> dict | None:
    f = await db_get(uid)
    if not f:
        return None
    if f.get("staya_id"):
        return await staya_get(f["staya_id"])
    # Fallback: check if user is still in staya_members despite staya_id=0
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT staya_id FROM staya_members WHERE user_id=? LIMIT 1", (uid,)
        ) as c:
            row = await c.fetchone()
    if row:
        staya_id = row["staya_id"]
        # Restore staya_id in frogs table
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE frogs SET staya_id=? WHERE user_id=?", (staya_id, uid))
            await db.commit()
        return await staya_get(staya_id)
    return None


async def get_user_bonds(uid: int) -> list[dict]:
    """Return all bonds for a user from user_bonds table, migrating legacy bond_with if needed."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM user_bonds WHERE user_id=? ORDER BY started_at", (uid,)
        ) as c:
            rows = [dict(r) for r in await c.fetchall()]

    f = None  # всегда инициализируем до первого использования

    # Migrate legacy bond_with if user_bonds is empty
    if not rows:
        f = await db_get(uid)
        if f and f.get("bond_with"):
            partner_id = f["bond_with"]
            now_b = time.time()
            real_streak = f.get("bond_streak", 0)
            async with aiosqlite.connect(DB_PATH) as db:
                await db.execute(
                    "INSERT OR IGNORE INTO user_bonds (user_id, partner_id, streak, bond_last, started_at) VALUES (?,?,?,?,?)",
                    (uid, partner_id, real_streak, f.get("bond_last", now_b), now_b)
                )
                await db.commit()
            rows = [{"user_id": uid, "partner_id": partner_id,
                     "streak": real_streak, "bond_last": f.get("bond_last", now_b), "started_at": now_b}]
        return rows

    # Sync streak from frogs table for rows where user_bonds.streak=0
    # Check both own frogs.bond_streak AND partner's frogs.bond_streak
    needs_refresh = False
    for b in rows:
        if b.get("streak", 0) > 0:
            continue  # already has real streak
        partner_id_check = b["partner_id"]
        # Lazy-load own frogs record once
        if f is None:
            f = await db_get(uid)
        own_streak = 0
        if f and f.get("bond_with") == partner_id_check:
            own_streak = f.get("bond_streak", 0)
        # Check partner's frogs record
        partner_f = await db_get(partner_id_check)
        partner_streak = 0
        if partner_f and partner_f.get("bond_with") == uid:
            partner_streak = partner_f.get("bond_streak", 0)
        # Use the higher value
        real_streak = max(own_streak, partner_streak)
        if real_streak > 0:
            async with aiosqlite.connect(DB_PATH) as db:
                await db.execute(
                    "UPDATE user_bonds SET streak=?, bond_last=? WHERE user_id=? AND partner_id=? AND streak < ?",
                    (real_streak, time.time(), uid, partner_id_check, real_streak)
                )
                await db.commit()
            needs_refresh = True

    if needs_refresh:
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            async with db.execute(
                "SELECT * FROM user_bonds WHERE user_id=? ORDER BY started_at", (uid,)
            ) as c:
                rows = [dict(r) for r in await c.fetchall()]

    return rows


async def add_bond(uid: int, partner_id: int):
    """Add a bond between two users in user_bonds table (bidirectional)."""
    now_b = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT OR IGNORE INTO user_bonds (user_id, partner_id, streak, bond_last, started_at) VALUES (?,?,0,?,?)",
            (uid, partner_id, now_b, now_b)
        )
        await db.execute(
            "INSERT OR IGNORE INTO user_bonds (user_id, partner_id, streak, bond_last, started_at) VALUES (?,?,0,?,?)",
            (partner_id, uid, now_b, now_b)
        )
        await db.commit()
    # Keep bond_with for backward compat (set to this bond if not set)
    for a, b in [(uid, partner_id), (partner_id, uid)]:
        frog = await db_get(a)
        if frog and not frog.get("bond_with"):
            frog["bond_with"] = b
            frog["bond_streak"] = 0
            frog["bond_last"] = now_b
            await db_save(frog)


async def remove_bond(uid: int, partner_id: int):
    """Remove a specific bond between two users."""
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "DELETE FROM user_bonds WHERE (user_id=? AND partner_id=?) OR (user_id=? AND partner_id=?)",
            (uid, partner_id, partner_id, uid)
        )
        await db.commit()
    # Update bond_with legacy field for both users
    for a, b in [(uid, partner_id), (partner_id, uid)]:
        frog = await db_get(a)
        if frog and frog.get("bond_with") == b:
            remaining = await get_user_bonds(a)
            frog["bond_with"] = remaining[0]["partner_id"] if remaining else 0
            if not remaining:
                frog["bond_streak"] = 0
            await db_save(frog)


