async def staya_boost_activate(staya_id: int, boost_type: str, mult: float,
                                duration_h: int, cost: int, activated_by: int) -> bool:
    """Активирует бустер, списывая из котла."""
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT cauldron FROM stayas WHERE id=?", (staya_id,)) as c:
            row = await c.fetchone()
        if not row or row[0] < cost:
            return False
        await db.execute("UPDATE stayas SET cauldron=cauldron-? WHERE id=?", (cost, staya_id))
        await db.execute(
            "INSERT INTO staya_boosts(staya_id, boost_type, mult, duration_h, cost, ends_at, activated_at, activated_by) "
            "VALUES(?,?,?,?,?,?,?,?)",
            (staya_id, boost_type, mult, duration_h, cost, now + duration_h * 3600, now, activated_by),
        )
        await db.commit()
    return True


