async def staya_add_cauldron(staya_id: int, amount: int):
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE stayas SET cauldron=MAX(0, cauldron+?) WHERE id=?",
            (amount, staya_id),
        )
        await db.commit()
    # После пополнения — проверяем автоапгрейд
    if amount > 0:
        await staya_check_upgrade(staya_id)


async def staya_check_upgrade(staya_id: int, bot=None):
    """Проверяет и применяет апгрейд стаи если котёл достаточно накоплен."""
    staya = await staya_get(staya_id)
    if not staya:
        return
    current_level = staya.get("level", 0)
    upgrade = STAYA_UPGRADES.get(current_level + 1)
    if not upgrade:
        return  # максимальный уровень
    if staya["cauldron"] < upgrade["cost"]:
        return  # недостаточно

    # Апгрейд! Списываем из котла, повышаем уровень
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE stayas SET level=level+1, cauldron=cauldron-? WHERE id=? AND cauldron>=?",
            (upgrade["cost"], staya_id, upgrade["cost"]),
        )
        await db.commit()

    # Проверяем что апгрейд прошёл (атомарно)
    new_staya = await staya_get(staya_id)
    if not new_staya or new_staya["level"] <= current_level:
        return  # кто-то успел раньше (race condition защита)

    new_level = new_staya["level"]
    next_up   = STAYA_UPGRADES.get(new_level + 1)
    next_line = f"\n\n⬆️ Следующее: <b>{next_up['name']}</b> — {next_up['cost']}🪙" if next_up else "\n\n🏆 Максимальный уровень болота достигнут!"

    announce_text = (
        f"🎉 <b>Болото «{he(staya['name'])}» выросло!</b>\n\n"
        f"🏔️ Уровень болота: <b>{new_level}</b>\n"
        f"🔓 Открыто: <b>{upgrade['name']}</b>\n"
        f"✨ Бонус: <i>{upgrade['bonus']}</i>"
        f"{next_line}"
    )

    # Летопись
    await letopis_add(staya["creator_id"], "staya_win",
                      f"🏔️ Стая «{staya['name']}» достигла уровня болота {new_level}!")

    # Уведомление всем участникам
    members = await staya_get_members(staya_id)
    for m in members:
        try:
            if bot:
                await bot.send_message(m["user_id"], announce_text, parse_mode=ParseMode.HTML)
            await asyncio.sleep(0.15)
        except (BadRequest, Forbidden, TimedOut):
            pass

    logger.info("staya_upgrade: id=%s level=%s upgrade=%s", staya_id, new_level, upgrade["name"])


def staya_get_level_bonus(staya_level: int) -> dict:
    """Возвращает бонусы стаи по текущему уровню болота (уровни 1–5)."""
    b = {
        "hunger_decay_mult":    1.0,
        "health_regen":         0,
        "worker_coins_mult":    1.0,
        "xp_mult":              1.0,
        "event_penalty_reduce": False,
    }
    if staya_level >= 1: b["hunger_decay_mult"]    = 0.95
    if staya_level >= 2: b["health_regen"]          = 3
    if staya_level >= 3: b["worker_coins_mult"]     = 1.10
    if staya_level >= 4: b["xp_mult"]               = 1.15
    if staya_level >= 5: b["event_penalty_reduce"]  = True
    return b



