# ── НАБЕГ ─────────────────────────────────────────────────────────────────────

async def raid_cooldown_left(attacker_uid: int, target_staya_id: int,
                              attacker_staya_id: int = 0) -> tuple[float, str]:
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT MAX(ts) FROM staya_raids WHERE attacker_uid=?", (attacker_uid,)
        ) as c:
            row = await c.fetchone()
        player_left = max(0.0, RAID_COOLDOWN_PLAYER - (now - (row[0] or 0)))
        if target_staya_id:
            async with db.execute(
                "SELECT MAX(ts) FROM staya_raids WHERE attacker_uid=? AND target_staya=?",
                (attacker_uid, target_staya_id),
            ) as c:
                row = await c.fetchone()
            target_left = max(0.0, RAID_COOLDOWN_TARGET - (now - (row[0] or 0)))
        else:
            target_left = 0.0
        staya_left = 0.0
        if attacker_staya_id:
            async with db.execute(
                "SELECT MAX(ts) FROM staya_raids WHERE attacker_staya=?",
                (attacker_staya_id,),
            ) as c:
                row = await c.fetchone()
            staya_left = max(0.0, RAID_COOLDOWN_STAYA - (now - (row[0] or 0)))
    if staya_left > 0:
        return staya_left, "staya"
    if player_left > 0:
        return player_left, "player"
    if target_left > 0:
        return target_left, "target"
    return 0.0, ""

# Обратная совместимость — старый код использует raid_get_cooldown
async def raid_get_cooldown(attacker_uid: int, target_staya_id: int,
                             attacker_staya_id: int = 0) -> float:
    cd, _ = await raid_cooldown_left(attacker_uid, target_staya_id, attacker_staya_id)
    return cd


async def raid_get_active_guard(staya_id: int) -> int | None:
    data = await canteen_get(staya_id)
    g_uid = data.get("guard_uid", 0)
    if not g_uid:
        return None
    f = await db_get(g_uid)
    if not f:
        return None
    if time.time() - (f.get("last_seen") or 0) > GUARD_ONLINE_WINDOW:
        return None
    return g_uid


def _raid_calc_steal(target_cauldron: int, has_citadel: bool, has_ancient_bor: bool) -> int:
    pct = RAID_MAX_STEAL_PCT
    if has_ancient_bor:
        pct *= 0.85
    steal = int(target_cauldron * pct)
    if has_citadel:
        steal = min(steal, int(target_cauldron * 0.30))
    return min(steal, RAID_CAULDRON_MAX_ABS)


def _fmt_cd(secs: float) -> str:
    h, m = int(secs // 3600), int((secs % 3600) // 60)
    return f"{h}ч {m}м" if h > 0 else f"{m}м {int(secs % 60)}с"


async def _raid_get(raid_id: int) -> dict | None:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM staya_raids WHERE id=?", (raid_id,)) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def war_migrate(db: aiosqlite.Connection) -> None:
    """Добавляет новые колонки и таблицы для войны v2, не трогая существующие данные."""
    new_raid_cols = [
        ("phase",         "TEXT    DEFAULT 'pending'"),
        ("participants",  "TEXT    DEFAULT '[]'"),
        ("votes",         "TEXT    DEFAULT '{}'"),
        ("guard_reacted", "INTEGER DEFAULT 0"),
        ("scout_until",   "REAL    DEFAULT 0"),
        ("vote_until",    "REAL    DEFAULT 0"),
        ("self_share",    "INTEGER DEFAULT 0"),
        ("staya_share",   "INTEGER DEFAULT 0"),
    ]
    for col, typedef in new_raid_cols:
        try:
            await db.execute(f"ALTER TABLE staya_raids ADD COLUMN {col} {typedef}")
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)

    new_sk_cols = [
        ("mode",           "TEXT    DEFAULT 'rps'"),
        ("current_duel",   "INTEGER DEFAULT 0"),
        ("duel_order",     "TEXT    DEFAULT '[]'"),
        ("duel_index",     "INTEGER DEFAULT 0"),
        ("gather_msg_ids", "TEXT    DEFAULT '{}'"),  # {user_id: message_id}
    ]
    for col, typedef in new_sk_cols:
        try:
            await db.execute(f"ALTER TABLE staya_skirmishes ADD COLUMN {col} {typedef}")
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)

    try:
        await db.execute("ALTER TABLE hideseek_events ADD COLUMN prize_text TEXT DEFAULT ''")
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)
    try:
        await db.execute("ALTER TABLE skirmish_members ADD COLUMN is_spectator INTEGER DEFAULT 0")
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)

    await db.execute("""
        CREATE TABLE IF NOT EXISTS war_stats (
            uid          INTEGER PRIMARY KEY,
            raids_att    INTEGER DEFAULT 0,
            raids_won    INTEGER DEFAULT 0,
            raids_def    INTEGER DEFAULT 0,
            raids_saved  INTEGER DEFAULT 0,
            duels_won    INTEGER DEFAULT 0,
            duels_lost   INTEGER DEFAULT 0,
            coins_stolen INTEGER DEFAULT 0,
            coins_lost   INTEGER DEFAULT 0
        )
    """)

    # Ставки на дуэли
    await db.execute("""
        CREATE TABLE IF NOT EXISTS duel_bets (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            skirmish_id INTEGER NOT NULL,
            duel_id     INTEGER NOT NULL,
            uid         INTEGER NOT NULL,
            side        TEXT NOT NULL,   -- 'attacker' | 'defender'
            amount      INTEGER NOT NULL,
            paid_out    INTEGER DEFAULT 0,
            ts          REAL DEFAULT 0,
            UNIQUE(duel_id, uid)
        )
    """)
    await db.execute("CREATE INDEX IF NOT EXISTS idx_duel_bets_duel ON duel_bets(duel_id)")

    # Колонка для хранения message_id боевого сообщения (для редактирования)
    try:
        await db.execute("ALTER TABLE skirmish_duels ADD COLUMN live_msg_ids TEXT DEFAULT '{}'")
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)
    try:
        await db.execute("ALTER TABLE skirmish_duels ADD COLUMN att_rounds_won INTEGER DEFAULT 0")
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)
    try:
        await db.execute("ALTER TABLE skirmish_duels ADD COLUMN def_rounds_won INTEGER DEFAULT 0")
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)
    try:
        await db.execute("ALTER TABLE skirmish_duels ADD COLUMN game_state TEXT DEFAULT '{}'")
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)

    await db.commit()
    print("✅ Миграция war_stats / staya_raids / staya_skirmishes / duel_bets v2 применена")


async def war_stat_add(uid: int, **kwargs):
    if not kwargs:
        return
    cols = ", ".join(kwargs.keys())
    placeholders = ", ".join("?" for _ in kwargs)
    updates = ", ".join(f"{k}={k}+?" for k in kwargs)
    vals = list(kwargs.values())
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            f"INSERT INTO war_stats(uid,{cols}) VALUES(?,{placeholders}) "
            f"ON CONFLICT(uid) DO UPDATE SET {updates}",
            [uid] + vals + vals,
        )
        await db.commit()


async def _raid_notify_staya(bot, staya_id: int, text: str,
                              reply_markup=None, exclude_uid: int = 0):
    members = await staya_get_members(staya_id)
    for m in members:
        if m["user_id"] == exclude_uid:
            continue
        mf = await db_get(m["user_id"])
        if mf and not mf.get("war_notify", 1):
            continue
        try:
            await bot.send_message(
                m["user_id"], text,
                parse_mode=ParseMode.HTML,
                reply_markup=reply_markup,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass


async def _raid_build_vote_text(raid: dict, target: dict, att_staya: dict,
                                 steal_max: int) -> str:
    votes        = json.loads(raid.get("votes") or "{}")
    participants = json.loads(raid.get("participants") or "[]")
    tally = {}
    for v in votes.values():
        tally[v] = tally.get(v, 0) + 1
    total_votes = len(votes)

    pot_lines = ""
    for i in range(3):
        cnt = tally.get(i, 0)
        pct = int(cnt / total_votes * 100) if total_votes else 0
        bar_fill = int(pct / 10)
        bar = "█" * bar_fill + "░" * (10 - bar_fill)
        pot_lines += f"\n  🏺 {i+1} {bar} {cnt} ({pct}%)"

    return (
        f"🏹 {he(att_staya['name'])} → {he(target['name'])}\n"
        f"котёл цели {target['cauldron']}{_E_COIN}\nунести до {steal_max}{_E_COIN}\n"
        f"\n"
        f"Где монеты? Голосуйте вместе.{pot_lines}\n"
        f"\n"
        f"проголосовало {len(votes)} из {len(participants)}"
    )


def _raid_vote_keyboard(raid_id: int, voted: bool,
                         tally: dict = None, total: int = 0) -> InlineKeyboardMarkup:
    """Клавиатура голосования. Если voted=True — показываем счёт вместо выбора."""
    pot_names = ["Котёл 1", "Котёл 2", "Котёл 3"]
    if voted and tally is not None and total > 0:
        # Показываем результаты с процентами
        rows = []
        for i in range(3):
            cnt = tally.get(i, 0)
            pct = int(cnt / total * 100) if total else 0
            bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
            rows.append([btn(
                f"🏺 {pot_names[i]}: {cnt} гол. ({pct}%) {bar}",
                callback_data="raid_voted_already",
            )])
        return InlineKeyboardMarkup(rows)
    elif voted:
        return InlineKeyboardMarkup([[
            btn("✅ Ты проголосовал", callback_data="raid_voted_already"),
        ]])
    # Не голосовал — обычные кнопки
    tally = tally or {}
    total = total or 0
    rows = []
    for i in range(3):
        cnt = tally.get(i, 0)
        pct = int(cnt / total * 100) if total > 0 else 0
        count_str = f" · {cnt} ({pct}%)" if total > 0 else ""
        rows.append([btn(
            f"🏺 {pot_names[i]}{count_str}",
            callback_data=f"raid_vote_{raid_id}_{i}",
        )])
    return InlineKeyboardMarkup(rows)


async def _raid_scout_phase(bot, raid_id: int, att_staya: dict, target: dict,
                             steal_max: int, guard_uid: int | None):
    members_att = await staya_get_members(att_staya["id"])
    guard_note = (
        "\n⚠️ охранник на посту — добыча упадёт вдвое если среагирует"
    ) if guard_uid else "\n🔓 охранника нет"

    scout_text = (
        f"🏹 НАБЕГ\n"
        f"\n"
        f"{he(att_staya['name'])} → {he(target['name'])}\n"
        f"котёл цели {target['cauldron']}🪙\nунести до {steal_max}🪙{guard_note}\n"
        f"\n"
        f"⏳ минута на разведку — потом голосование"
    )
    for m in members_att:
        mf = await db_get(m["user_id"])
        if not mf or not mf.get("war_notify", 1):
            continue
        try:
            await bot.send_message(m["user_id"], scout_text, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass

    if guard_uid:
        try:
            await bot.send_message(
                guard_uid,
                f"🚨 тревога — {he(att_staya['name'])} идут на котёл\n"
                f"\n"
                f"у тебя {RAID_GUARD_REACT_SEC} секунд встать на защиту\n"
                f"среагируешь — добыча врага упадёт вдвое",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[
                    btn("🛡️ Защищать котёл", callback_data=f"raid_guard_{raid_id}", style="success"),
                ]]),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass

    await asyncio.sleep(RAID_SCOUT_PHASE_SEC)
    await _raid_vote_phase(bot, raid_id, att_staya, target, steal_max)


async def _raid_vote_phase(bot, raid_id: int, att_staya: dict, target: dict,
                            steal_max: int):
    raid = await _raid_get(raid_id)
    if not raid or raid.get("phase") == "finished":
        return
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE staya_raids SET phase='voting', vote_until=? WHERE id=?",
            (time.time() + RAID_VOTE_PHASE_SEC, raid_id),
        )
        await db.commit()
    raid = await _raid_get(raid_id)
    participants = json.loads(raid.get("participants") or "[]")
    vote_text = await _raid_build_vote_text(raid, target, att_staya, steal_max)
    for uid_p in participants:
        try:
            await bot.send_message(
                uid_p, vote_text,
                parse_mode=ParseMode.HTML,
                reply_markup=_raid_vote_keyboard(raid_id, False, {}, 0),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
    await asyncio.sleep(RAID_VOTE_PHASE_SEC)
    raid = await _raid_get(raid_id)
    if not raid or raid.get("phase") == "finished":
        return
    votes = json.loads(raid.get("votes") or "{}")
    chosen = max(
        {int(v): votes.values().count if False else 0 for v in set(votes.values())},
        key=lambda k: sum(1 for vv in votes.values() if vv == k),
        default=random.randint(0, 2),
    ) if votes else random.randint(0, 2)
    await _raid_resolve(bot, raid_id, chosen, att_staya, target, steal_max)


async def _raid_resolve(bot, raid_id: int, chosen: int,
                         att_staya: dict, target: dict, steal_max: int):
    raid = await _raid_get(raid_id)
    if not raid or raid.get("phase") == "finished":
        return
    correct = raid["correct_pot"]
    guard_reacted = bool(raid.get("guard_reacted", 0))
    participants = json.loads(raid.get("participants") or "[]")
    attacker_uid = raid["attacker_uid"]
    success = (chosen == correct)

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE staya_raids SET phase='finished', status=?, choice=? WHERE id=?",
            ("success" if success else "failed", str(chosen), raid_id),
        )
        await db.commit()

    chosen_name = ["Котёл 1", "Котёл 2", "Котёл 3"][chosen]

    if success:
        stolen = steal_max
        if guard_reacted:
            stolen = stolen // 2
        stolen = max(0, min(stolen, target.get("cauldron", 0)))
        self_share  = int(stolen * RAID_WIN_SELF_PCT)
        staya_share = stolen - self_share
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE stayas SET cauldron=MAX(0,cauldron-?) WHERE id=?",
                (stolen, target["id"]),
            )
            await db.execute(
                "UPDATE stayas SET cauldron=cauldron+? WHERE id=?",
                (staya_share, att_staya["id"]),
            )
            await db.commit()
        att_f = await db_get(attacker_uid)
        if att_f:
            att_f["coins"] = att_f.get("coins", 0) + self_share
            await db_save(att_f)
        guard_line = "\nохранник среагировал — добыча вдвое" if guard_reacted else ""
        result_text = (
            f"✅ набег удался{guard_line}\n"
            f"\n"
            f"{chosen_name} — там были монеты\n"
            f"\n"
            f"украдено {stolen}🪙\n"
            f"  лично тебе {self_share}🪙\n"
            f"  в котёл стаи {staya_share}🪙"
        )
        await war_stat_add(attacker_uid, raids_att=1, raids_won=1, coins_stolen=stolen)
        victim_text = (
            f"{_E_SWORDS} {he(att_staya['name'])} угадали котёл\n"
            f"потеряно {stolen}🪙"
        )
        if guard_reacted:
            victim_text += "\n🛡 охранник среагировал — без него было бы вдвое хуже"
        await _raid_notify_staya(bot, target["id"], victim_text)
    else:
        await staya_add_cauldron(target["id"], RAID_PENALTY_ON_FAIL)
        result_text = (
            f"💥 набег провалился\n"
            f"\n"
            f"{chosen_name} — там была ловушка\n"
            f"стая-жертва получила {RAID_PENALTY_ON_FAIL}🪙"
        )
        await war_stat_add(attacker_uid, raids_att=1)
        await _raid_notify_staya(
            bot, target["id"],
            f"🎉 набег отбит\n"
            f"{he(att_staya['name'])} ошиблись котлом\n"
            f"в ваш котёл +{RAID_PENALTY_ON_FAIL}🪙",
        )

    for uid_p in participants:
        try:
            await bot.send_message(uid_p, result_text, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass


