async def sk_cooldown_left(staya_a: int, staya_b: int) -> float:
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT MAX(started_at) FROM staya_skirmishes "
            "WHERE (attacker_staya=? AND defender_staya=?) "
            "   OR (attacker_staya=? AND defender_staya=?)",
            (staya_a, staya_b, staya_b, staya_a),
        ) as c:
            row = await c.fetchone()
    return max(0.0, SKIRMISH_COOLDOWN - (now - ((row[0] or 0) if row else 0)))


async def sk_get_user_active(uid: int) -> dict | None:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT ss.* FROM staya_skirmishes ss "
            "JOIN skirmish_members sm ON sm.skirmish_id=ss.id "
            "WHERE sm.user_id=? AND ss.status IN ('gathering','active') "
            "ORDER BY ss.started_at DESC LIMIT 1",
            (uid,),
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None

