async def _sk_scoreboard(sk: dict, members: list[dict]) -> str:
    att_staya = await staya_get(sk["attacker_staya"])
    def_staya = await staya_get(sk["defender_staya"])
    att_sname = (att_staya["name"] if att_staya else "?")[:12]
    def_sname = (def_staya["name"] if def_staya else "?")[:12]
    att_wins  = sk.get("att_wins", 0)
    def_wins  = sk.get("def_wins", 0)

    att_m = [m for m in members if m["side"] == "attacker"]
    def_m = [m for m in members if m["side"] == "defender"]

    def _status(m):
        if m.get("fled"):   return "🏃"
        if m.get("is_spectator"): return "👁"
        dw = m.get("duels_won", 0)
        dl = m.get("duels_lost", 0)
        if dw == 0 and dl == 0: return "·"
        if dw > dl:  return "✓"
        if dl > dw:  return "✗"
        return "·"

    rows = []
    for i in range(max(len(att_m), len(def_m))):
        am = att_m[i] if i < len(att_m) else None
        dm = def_m[i] if i < len(def_m) else None
        a_name  = (am.get("frog_name") or am.get("first_name") or "?")[:10] if am else ""
        d_name  = (dm.get("frog_name") or dm.get("first_name") or "?")[:10] if dm else ""
        a_st    = _status(am) if am else ""
        d_st    = _status(dm) if dm else ""
        rows.append(f"  {a_st} {he(a_name):<10} {d_st} {he(d_name)}")

    body = "\n".join(rows)
    return (
        f"  {he(att_sname):<12} {he(def_sname)}\n"
        f"  {'─'*12} {'─'*12}\n"
        f"{body}\n"
        f"\n  итог {att_wins} · {def_wins}"
    )


def _hp_bar(hp: int, max_hp: int = 10) -> str:
    filled = max(0, min(hp, max_hp))
    return "🟩" * filled + "⬛" * (max_hp - filled)


