# КОНСТАНТЫ
# ─────────────────────────────────────────────────────────────────────────────

ROUNDS_TO_WIN = 2       # побед для выигрыша дуэли (best of 3)
REACTION_SHOW_MIN = 3   # мин. задержка появления кнопки реакции (сек)
REACTION_SHOW_MAX = 7   # макс. задержка
REACTION_WINDOW   = 5   # окно на нажатие после появления кнопки

# Паттерны: (последовательность, пропуск на позиции, варианты ответов, правильный)
# Используем эмодзи-кружки разных цветов
_PATTERN_CIRCLES  = ["🔴", "🔵", "🟢", "🟡", "🟣", "🟠", "⚪", "⚫"]
_PATTERN_SHAPES   = ["🔴", "🔵", "🟢", "🟡", "🟣", "🟠"]

def _gen_patterns() -> list[dict]:
    """Генерирует библиотеку паттернов."""
    patterns = []
    c = _PATTERN_SHAPES

    # Тип 1: чередование двух цветов ABABAB?
    for i in range(len(c)):
        for j in range(len(c)):
            if i == j:
                continue
            seq = [c[i], c[j]] * 4        # 8 элементов
            gap = 7                        # последний
            wrong = [x for x in c if x not in (c[i], c[j])][:2] + [c[i if gap % 2 == 1 else j]]
            patterns.append({
                "seq": seq[:gap],
                "answer": seq[gap],
                "wrong": wrong[:3],
                "hint": "чередование"
            })

    # Тип 2: три подряд одинаковых, потом смена AAABBB?
    for i in range(len(c)):
        for j in range(len(c)):
            if i == j:
                continue
            seq = [c[i]]*3 + [c[j]]*3 + [c[i]]*2   # 8 элементов
            gap = 7
            wrong = [x for x in c if x not in (c[i], c[j])][:2] + [c[j]]
            patterns.append({
                "seq": seq[:gap],
                "answer": seq[gap],
                "wrong": wrong[:3],
                "hint": "блоки"
            })

    # Тип 3: три цвета по кругу ABCABC?
    for i in range(len(c)-2):
        a, b, cc = c[i], c[i+1], c[i+2]
        seq = [a, b, cc, a, b, cc, a]   # 7 эл, ответ b
        gap = 7
        wrong = [x for x in c if x not in (a, b, cc)][:2] + [a]
        patterns.append({
            "seq": seq,
            "answer": b,
            "wrong": wrong[:3],
            "hint": "тройное чередование"
        })

    return patterns

_PATTERNS = _gen_patterns()

# Карты лотереи
_LOTTERY_CARDS = {
    "💀": {"name": "Болотная топь",   "value": 0, "special": "lose"},   # 1 шт
    "🍄": {"name": "Поганка",          "value": 1},   # 2 шт
    "🦟": {"name": "Комар",            "value": 2},   # 3 шт
    "🌿": {"name": "Осока",            "value": 3},   # 2 шт
    "🌸": {"name": "Кувшинка",         "value": 4},   # 1 шт
    "✨": {"name": "Золотая кувшинка", "value": 99, "special": "win"},  # 1 шт
}
