# ОБЩИЙ ДВИЖОК РАУНДОВ (без HP)
# ─────────────────────────────────────────────────────────────────────────────

async def _duel_round_result(bot, sk_id: int, duel_id: int,
                              att_name: str, def_name: str,
                              round_winner: str,   # "attacker" | "defender" | "draw"
                              round_text: str) -> str | None:
    """
    Записывает результат раунда, возвращает победителя дуэли если решено
    или None если продолжаем.
    Использует att_rounds_won / def_rounds_won.
    """
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM skirmish_duels WHERE id=?", (duel_id,)) as c:
            row = await c.fetchone()
    if not row:
        return "attacker"  # fallback
    duel = dict(row)

    att_rw = duel.get("att_rounds_won", 0)
    def_rw = duel.get("def_rounds_won", 0)
    rn     = duel.get("round_num", 1)

    if round_winner == "attacker":
        att_rw += 1
    elif round_winner == "defender":
        def_rw += 1
    # draw — никому не добавляем

    new_round = rn + 1

    duel_over = att_rw >= ROUNDS_TO_WIN or def_rw >= ROUNDS_TO_WIN or new_round > 5

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET att_rounds_won=?,def_rounds_won=?,"
            "round_num=?,att_choice=NULL,def_choice=NULL,game_state='{}',"
            "status=? WHERE id=? AND status='waiting'",
            (att_rw, def_rw, new_round,
             "finished" if duel_over else "waiting", duel_id),
        )
        await db.commit()

    score_line = f"Счёт раундов: {_E_SWORDS}{att_rw} — 🛡️{def_rw}"

    if duel_over:
        if att_rw > def_rw:
            winner = "attacker"
        elif def_rw > att_rw:
            winner = "defender"
        else:
            winner = random.choice(["attacker", "defender"])
        return winner
    return None   # продолжаем


def _round_score_text(duel: dict, att_name: str, def_name: str) -> str:
    att_rw = duel.get("att_rounds_won", 0)
    def_rw = duel.get("def_rounds_won", 0)
    dots_att = "●" * att_rw + "○" * (ROUNDS_TO_WIN - att_rw)
    dots_def = "●" * def_rw + "○" * (ROUNDS_TO_WIN - def_rw)
    return f"{_E_SWORDS} {he(att_name)} {dots_att} — {dots_def} {he(def_name)} 🛡️"


