def reaction_fire_keyboard(duel_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[
        btn("💥 ОГОНЬ", callback_data=f"react_{duel_id}_fire"),
    ]])


async def reaction_run_round(bot, sk_id: int, duel_id: int,
                               att_uid: int, def_uid: int,
                               att_name: str, def_name: str,
                               live_msg_ids: dict[int, int],
                               duel: dict, round_num: int) -> None:
    """Запускает раунд реакции: ждёт случайное время, показывает кнопку."""
    wait_secs = random.uniform(REACTION_SHOW_MIN, REACTION_SHOW_MAX)
    await asyncio.sleep(wait_secs)

    # Проверяем что дуэль ещё активна
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT status FROM skirmish_duels WHERE id=?", (duel_id,)
        ) as c:
            row = await c.fetchone()
    if not row or row[0] != "waiting":
        return

    # Сохраняем timestamp показа кнопки
    fire_ts = time.time()
    gs = json.loads(duel.get("game_state") or "{}")
    gs["fire_ts"] = fire_ts
    gs["first_uid"] = None
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET game_state=? WHERE id=?",
            (json.dumps(gs), duel_id)
        )
        await db.commit()

    # Редактируем сообщения бойцов — показываем кнопку
    fire_kb = reaction_fire_keyboard(duel_id)
    fire_text = (
        f"🏹 <b>Раунд {round_num} — ОГОНЬ!</b>\n"
        "\n"
        f"⚡ Нажми как можно быстрее!"
    )
    for f_uid in (att_uid, def_uid):
        mid = live_msg_ids.get(f_uid)
        try:
            if mid:
                await bot.edit_message_text(
                    fire_text, chat_id=f_uid, message_id=mid,
                    parse_mode=ParseMode.HTML, reply_markup=fire_kb,
                )
            else:
                await bot.send_message(
                    f_uid, fire_text, parse_mode=ParseMode.HTML, reply_markup=fire_kb,
                )
        except (BadRequest, Forbidden, TimedOut):
            pass

    # Таймаут реакции
    await asyncio.sleep(REACTION_WINDOW)

    # Перечитываем game_state — кто нажал?
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM skirmish_duels WHERE id=?", (duel_id,)) as c:
            row = await c.fetchone()
    if not row or row["status"] != "waiting":
        return
    duel_fresh = dict(row)
    gs = json.loads(duel_fresh.get("game_state") or "{}")
    first_uid = gs.get("first_uid")

    if first_uid == att_uid:
        round_winner = "attacker"
        result_text = f"🏹 <b>Раунд {round_num}!</b>\n{_E_SWORDS} <b>{he(att_name)}</b> нажал первым! {_E_TROPHY}"
    elif first_uid == def_uid:
        round_winner = "defender"
        result_text = f"🏹 <b>Раунд {round_num}!</b>\n🛡️ <b>{he(def_name)}</b> нажал первым! {_E_TROPHY}"
    else:
        round_winner = "draw"
        result_text = f"🏹 <b>Раунд {round_num}!</b>\n⚖️ Никто не нажал — ничья, переигровка!"

    duel_fresh["att_rounds_won"] = duel_fresh.get("att_rounds_won", 0)
    duel_fresh["def_rounds_won"] = duel_fresh.get("def_rounds_won", 0)
    score = _round_score_text(duel_fresh, att_name, def_name)
    await _send_duel_result(bot, sk_id, duel_fresh, result_text + f"\n{score}",
                             round_winner, att_name, def_name, "reaction")


