def lottery_deal() -> list[str]:
    """Тасует колоду, возвращает 10 карт рубашкой вниз."""
    deck = _LOTTERY_DECK.copy()
    random.shuffle(deck)
    return deck


def lottery_keyboard(duel_id: int, role: str, flipped: list[int]) -> InlineKeyboardMarkup:
    """10 кнопок-карт. Уже перевёрнутые показывают эмодзи карты (неактивны)."""
    rows = []
    for row_start in range(0, 10, 5):
        row = []
        for i in range(row_start, row_start + 5):
            if i in flipped:
                # Уже выбрана этим игроком — показываем что выбрал (будет раскрыто вместе)
                row.append(btn("✅", callback_data="lottery_done"))
            else:
                row.append(btn(
                    f"🃏", callback_data=f"lottery_{duel_id}_{role}_{i}"
                ))
        rows.append(row)
    rows.append([btn("🏃 Сдаться", callback_data=f"skd_flee_{duel_id}_{role}")])
    return InlineKeyboardMarkup(rows)


def lottery_start_text(att_name: str, def_name: str, duel: dict, round_num: int) -> str:
    return (
        f"🐸 <b>Болотная лотерея — Раунд {round_num}</b>\n"
        f"{_round_score_text(duel, att_name, def_name)}\n"
        "\n"
        f"10 карт рубашкой вниз. Выбери одну!\n"
        f"✨ Золотая кувшинка — мгновенная победа раунда\n"
        f"💀 Болотная топь — мгновенное поражение раунда\n"
        f"Остальные: сравниваем ценность карт.\n"
        f"⏳ {SKIRMISH_ROUND_SEC} секунд"
    )


async def lottery_resolve(bot, sk_id: int, duel: dict,
                           att_card_idx: int, def_card_idx: int,
                           att_name: str, def_name: str) -> None:
    gs     = json.loads(duel.get("game_state") or "{}")
    deck   = gs.get("deck", _LOTTERY_DECK)
    att_em = deck[att_card_idx]
    def_em = deck[def_card_idx]
    att_cd = _LOTTERY_CARDS.get(att_em, {"value": 0})
    def_cd = _LOTTERY_CARDS.get(def_em, {"value": 0})

    att_name_card = att_cd.get("name", att_em)
    def_name_card = def_cd.get("name", def_em)

    reveal = (
        f"🐸 <b>Карты открыты!</b>\n"
        f"{_E_SWORDS} {he(att_name)}: {att_em} <b>{att_name_card}</b>\n"
        f"🛡️ {he(def_name)}: {def_em} <b>{def_name_card}</b>\n"
    )

    if att_cd.get("special") == "win" or def_cd.get("special") == "lose":
        if att_cd.get("special") == "win":
            round_winner = "attacker"
            reveal += f"\n✨ <b>{he(att_name)}</b> нашёл Золотую кувшинку! {_E_TROPHY}"
        else:
            round_winner = "attacker"
            reveal += f"\n💀 <b>{he(def_name)}</b> попал в топь! {_E_TROPHY} {he(att_name)}"
    elif def_cd.get("special") == "win" or att_cd.get("special") == "lose":
        if def_cd.get("special") == "win":
            round_winner = "defender"
            reveal += f"\n✨ <b>{he(def_name)}</b> нашёл Золотую кувшинку! {_E_TROPHY}"
        else:
            round_winner = "defender"
            reveal += f"\n💀 <b>{he(att_name)}</b> попал в топь! {_E_TROPHY} {he(def_name)}"
    elif att_cd["value"] > def_cd["value"]:
        round_winner = "attacker"
        reveal += f"\n{_E_TROPHY} Победа <b>{he(att_name)}</b> — карта ценнее!"
    elif def_cd["value"] > att_cd["value"]:
        round_winner = "defender"
        reveal += f"\n{_E_TROPHY} Победа <b>{he(def_name)}</b> — карта ценнее!"
    else:
        round_winner = "draw"
        reveal += f"\n⚖️ Ничья! Карты равны — раунд переигрывается."

    duel["att_rounds_won"] = duel.get("att_rounds_won", 0)
    duel["def_rounds_won"] = duel.get("def_rounds_won", 0)
    score = _round_score_text(duel, att_name, def_name)
    await _send_duel_result(bot, sk_id, duel, reveal + f"\n{score}",
                             round_winner, att_name, def_name, "lottery")


