def bluff_waiting_text(att_name: str, def_name: str, declarer: str) -> str:
    return (
        f"⚡ <b>Блеф</b>\n"
        f"<b>{he(declarer)}</b> сделал заявление...\n"
        f"Ждём второго игрока."
    )


async def bluff_resolve(bot, sk_id: int, duel: dict,
                         att_name: str, def_name: str) -> None:
    gs = json.loads(duel.get("game_state") or "{}")
    att_decl = gs.get("att_decl")  # "truth" | "bluff"
    def_decl = gs.get("def_decl")
    att_resp = gs.get("att_resp")  # "believe" | "doubt" (реакция на заявление def)
    def_resp = gs.get("def_resp")  # реакция на заявление att

    # Результат для att: att блефовал, def_resp = реакция соперника
    def _result_one(my_decl, opp_resp):
        if my_decl == "bluff" and opp_resp == "believe":
            return "win"
        if my_decl == "bluff" and opp_resp == "doubt":
            return "lose"
        if my_decl == "truth" and opp_resp == "doubt":
            return "win"
        return "draw"  # truth + believe

    att_result = _result_one(att_decl, def_resp)
    def_result = _result_one(def_decl, att_resp)

    att_decl_ru = "Правда ✅" if att_decl == "truth" else "Блеф 🤥"
    def_decl_ru = "Правда ✅" if def_decl == "truth" else "Блеф 🤥"
    att_resp_ru = "Верю 👍"    if att_resp == "believe" else "Не верю 👎"
    def_resp_ru = "Верю 👍"    if def_resp == "believe" else "Не верю 👎"

    reveal = (
        f"⚡ <b>Раскрытие!</b>\n"
        f"{_E_SWORDS} {he(att_name)}: {att_decl_ru} → {he(def_name)} говорит: {def_resp_ru}\n"
        f"🛡️ {he(def_name)}: {def_decl_ru} → {he(att_name)} говорит: {att_resp_ru}\n"
    )

    if att_result == "win" and def_result != "win":
        round_winner = "attacker"
        reveal += f"\n{_E_TROPHY} Победа <b>{he(att_name)}</b>!"
    elif def_result == "win" and att_result != "win":
        round_winner = "defender"
        reveal += f"\n{_E_TROPHY} Победа <b>{he(def_name)}</b>!"
    elif att_result == "win" and def_result == "win":
        round_winner = "draw"
        reveal += "\n⚖️ Оба обманули — ничья!"
    else:
        round_winner = "draw"
        reveal += "\n⚖️ Оба честны — ничья!"

    duel["att_rounds_won"] = duel.get("att_rounds_won", 0)
    duel["def_rounds_won"] = duel.get("def_rounds_won", 0)
    score = _round_score_text(duel, att_name, def_name)
    await _send_duel_result(bot, sk_id, duel, reveal + f"\n{score}",
                             round_winner, att_name, def_name, "bluff")


