# 9. 💣 РУССКАЯ РУЛЕТКА
# ─────────────────────────────────────────────────────────────────────────────

def roulette_init() -> dict:
    """Создаёт барабан: случайная позиция пули среди 6."""
    bullet = random.randint(0, 5)
    return {"bullet": bullet, "pos": 0, "turn": "attacker"}


def roulette_keyboard(duel_id: int, role: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[
        btn("🔫 Выстрел", callback_data=f"roulette_{duel_id}_{role}_shoot"),
    ], [
        btn("🏃 Сдаться", callback_data=f"skd_flee_{duel_id}_{role}"),
    ]])


def roulette_wait_keyboard() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[
        btn("⏳ Ждём соперника...", callback_data="noop"),
    ]])


def roulette_start_text(att_name: str, def_name: str, duel: dict,
                         gs: dict, round_num: int) -> str:
    pos   = gs.get("pos", 0)
    turn  = gs.get("turn", "attacker")
    whose = att_name if turn == "attacker" else def_name
    chambers = "🟢" * pos + "🔫" + "⬜" * (5 - pos)
    return (
        f"💣 <b>Русская рулетка — Раунд {round_num}</b>\n"
        f"{_round_score_text(duel, att_name, def_name)}\n"
        "\n"
        f"Барабан: {chambers}\n"
        f"Позиция: <b>{pos+1}/6</b>\n"
        "\n"
        f"🎯 Ход: <b>{he(whose)}</b>\n"
        f"Нажми кнопку — или сдайся."
    )


async def roulette_shoot(bot, sk_id: int, duel: dict, shooter_uid: int,
                          att_uid: int, def_uid: int,
                          att_name: str, def_name: str,
                          live_msg_ids: dict[int, int]) -> None:
    """Обрабатывает выстрел в рулетке."""
    gs = json.loads(duel.get("game_state") or "{}")
    pos    = gs.get("pos", 0)
    bullet = gs.get("bullet", 0)
    turn   = gs.get("turn", "attacker")

    # Проверяем чья очередь
    expected_uid = att_uid if turn == "attacker" else def_uid
    if shooter_uid != expected_uid:
        return  # не твой ход

    pos += 1
    if pos - 1 == bullet:
        # Попал!
        round_winner = "defender" if turn == "attacker" else "attacker"
        loser_name   = att_name if turn == "attacker" else def_name
        result_text  = (
            f"💥 <b>Выстрел!</b>\n"
            f"<b>{he(loser_name)}</b> проиграл раунд!\n"
        )
        duel["att_rounds_won"] = duel.get("att_rounds_won", 0)
        duel["def_rounds_won"] = duel.get("def_rounds_won", 0)
        score = _round_score_text(duel, att_name, def_name)

        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE skirmish_duels SET game_state='{}',att_choice=NULL,def_choice=NULL WHERE id=?",
                (duel["id"],)
            )
            await db.commit()

        await _send_duel_result(bot, sk_id, duel, result_text + score,
                                 round_winner, att_name, def_name, "roulette")
        return

    # Пусто — передаём ход
    if pos >= 6:
        # Все 6 позиций пройдены без выстрела — перезаряжаем
        gs = roulette_init()
        gs["pos"] = 0
    else:
        next_turn = "defender" if turn == "attacker" else "attacker"
        gs["pos"]  = pos
        gs["turn"] = next_turn

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET game_state=? WHERE id=?",
            (json.dumps(gs), duel["id"])
        )
        await db.commit()

    # Обновляем duel для текста
    duel["game_state"] = json.dumps(gs)
    next_turn  = gs.get("turn", "attacker")
    whose_name = att_name if next_turn == "attacker" else def_name
    next_uid   = att_uid if next_turn == "attacker" else def_uid
    chambers   = "🟢" * gs["pos"] + "🔫" + "⬜" * (5 - gs["pos"])

    click_text = (
        f"💣 <b>Щёлк... пусто!</b>\n"
        f"Барабан: {chambers}\n"
        f"Позиция: <b>{gs['pos']+1}/6</b>\n"
        "\n"
        f"🎯 Ход переходит к <b>{he(whose_name)}</b>"
    )
    next_role = "att" if next_turn == "attacker" else "def"
    wait_role = "def" if next_turn == "attacker" else "att"

    # Обновляем сообщения
    for f_uid, role_d in ((att_uid, "att"), (def_uid, "def")):
        mid = live_msg_ids.get(f_uid)
        if f_uid == next_uid:
            kb = roulette_keyboard(duel["id"], role_d)
        else:
            kb = roulette_wait_keyboard()
        try:
            if mid:
                await bot.edit_message_text(
                    click_text, chat_id=f_uid, message_id=mid,
                    parse_mode=ParseMode.HTML, reply_markup=kb,
                )
        except Exception:
            try:
                await bot.send_message(f_uid, click_text, parse_mode=ParseMode.HTML, reply_markup=kb)
            except (BadRequest, Forbidden, TimedOut):
                pass


# ─────────────────────────────────────────────────────────────────────────────
# 10. 🧩 ПАТТЕРН
# ─────────────────────────────────────────────────────────────────────────────

def pattern_pick() -> dict:
    """Выбирает случайный паттерн из библиотеки."""
    return random.choice(_PATTERNS)


def pattern_display(p: dict) -> str:
    """Отображает последовательность с пропуском на последней позиции."""
    return " ".join(p["seq"]) + " ❓"


def pattern_keyboard(duel_id: int, role: str, p: dict) -> InlineKeyboardMarkup:
    options = [p["answer"]] + p["wrong"][:3]
    random.shuffle(options)
    return InlineKeyboardMarkup([[
        btn(o, callback_data=f"pattern_{duel_id}_{role}_{o}")
        for o in options
    ], [
        btn("🏃 Сдаться", callback_data=f"skd_flee_{duel_id}_{role}"),
    ]])


def pattern_start_text(att_name: str, def_name: str, duel: dict,
                        p: dict, round_num: int) -> str:
    seq_display = pattern_display(p)
    return (
        f"🧩 <b>Паттерн — Раунд {round_num}</b>\n"
        f"{_round_score_text(duel, att_name, def_name)}\n"
        "\n"
        f"Что стоит на месте ❓\n\n"
        f"<b>{seq_display}</b>\n\n"
        f"<i>Подсказка: {p['hint']}</i>\n"
        f"⏳ {SKIRMISH_ROUND_SEC} секунд"
    )


async def pattern_resolve(bot, sk_id: int, duel: dict,
                           att_answer: str, def_answer: str,
                           att_name: str, def_name: str) -> None:
    gs     = json.loads(duel.get("game_state") or "{}")
    p_idx  = gs.get("pattern_idx", 0)
    p      = _PATTERNS[p_idx % len(_PATTERNS)]
    correct = p["answer"]

    att_ok = att_answer == correct
    def_ok = def_answer == correct

    att_ts = gs.get("att_ts", 9999)
    def_ts = gs.get("def_ts", 9999)

    seq_display = pattern_display(p)

    reveal = (
        f"🧩 <b>Раскрытие!</b>\n"
        f"Паттерн: {seq_display}\n"
        f"Правильный ответ: <b>{correct}</b>\n"
        "\n"
        f"{_E_SWORDS} {he(att_name)}: {att_answer} {_E_CHECK if att_ok else _E_CROSS}\n"
        f"🛡️ {he(def_name)}: {def_answer} {_E_CHECK if def_ok else _E_CROSS}\n"
    )

    if att_ok and def_ok:
        # Оба правы — кто быстрее?
        if att_ts < def_ts - 0.1:
            round_winner = "attacker"
            reveal += f"\n{_E_TROPHY} <b>{he(att_name)}</b> ответил быстрее!"
        elif def_ts < att_ts - 0.1:
            round_winner = "defender"
            reveal += f"\n{_E_TROPHY} <b>{he(def_name)}</b> ответил быстрее!"
        else:
            round_winner = "draw"
            reveal += "\n⚖️ Одновременно — ничья!"
    elif att_ok:
        round_winner = "attacker"
        reveal += f"\n{_E_TROPHY} Победа <b>{he(att_name)}</b>!"
    elif def_ok:
        round_winner = "defender"
        reveal += f"\n{_E_TROPHY} Победа <b>{he(def_name)}</b>!"
    else:
        round_winner = "draw"
        reveal += "\n⚖️ Оба ошиблись — ничья, новый паттерн!"

    duel["att_rounds_won"] = duel.get("att_rounds_won", 0)
    duel["def_rounds_won"] = duel.get("def_rounds_won", 0)
    score = _round_score_text(duel, att_name, def_name)
    await _send_duel_result(bot, sk_id, duel, reveal + f"\n{score}",
                             round_winner, att_name, def_name, "pattern")


# ─────────────────────────────────────────────────────────────────────────────
# ОБЩИЙ ДИСПЕТЧЕР — запуск нового раунда для любого режима
# ─────────────────────────────────────────────────────────────────────────────

async def start_game_round(bot, sk_id: int, duel_id: int,
                            att_uid: int, def_uid: int,
                            att_name: str, def_name: str,
                            mode: str, live_msg_ids: dict[int, int],
                            duel: dict, round_num: int) -> None:
    """Отправляет/редактирует сообщения для начала нового раунда."""

    if mode == "guess":
        txt = guess_start_text(duel_id, att_name, def_name, duel, round_num)
        for uid_d, role_d in ((att_uid, "att"), (def_uid, "def")):
            kb  = guess_keyboard(duel_id, role_d)
            mid = live_msg_ids.get(uid_d)
            await _edit_or_send(bot, uid_d, mid, txt, kb)

    elif mode == "reaction":
        txt = reaction_wait_text(att_name, def_name, duel, round_num)
        for uid_d in (att_uid, def_uid):
            mid = live_msg_ids.get(uid_d)
            await _edit_or_send(bot, uid_d, mid, txt, None)
        asyncio.create_task(reaction_run_round(
            bot, sk_id, duel_id, att_uid, def_uid,
            att_name, def_name, live_msg_ids, duel, round_num
        ))
        return  # таймаут управляет раундом, не внешний

    elif mode == "lottery":
        deck = lottery_deal()
        gs   = {"deck": deck, "att_card": None, "def_card": None}
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE skirmish_duels SET game_state=? WHERE id=?",
                (json.dumps(gs), duel_id)
            )
            await db.commit()
        duel["game_state"] = json.dumps(gs)
        txt = lottery_start_text(att_name, def_name, duel, round_num)
        for uid_d, role_d in ((att_uid, "att"), (def_uid, "def")):
            kb  = lottery_keyboard(duel_id, role_d, [])
            mid = live_msg_ids.get(uid_d)
            await _edit_or_send(bot, uid_d, mid, txt, kb)

    elif mode == "bluff":
        gs = {"att_decl": None, "def_decl": None, "att_resp": None, "def_resp": None}
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE skirmish_duels SET game_state=? WHERE id=?",
                (json.dumps(gs), duel_id)
            )
            await db.commit()
        txt = bluff_start_text(att_name, def_name, duel, round_num)
        for uid_d, role_d in ((att_uid, "att"), (def_uid, "def")):
            kb  = bluff_declare_keyboard(duel_id, role_d)
            mid = live_msg_ids.get(uid_d)
            await _edit_or_send(bot, uid_d, mid, txt, kb)

    elif mode == "roulette":
        gs = roulette_init()
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE skirmish_duels SET game_state=? WHERE id=?",
                (json.dumps(gs), duel_id)
            )
            await db.commit()
        duel["game_state"] = json.dumps(gs)
        txt = roulette_start_text(att_name, def_name, duel, gs, round_num)
        # Первый ход всегда у атакующего
        mid_att = live_msg_ids.get(att_uid)
        mid_def = live_msg_ids.get(def_uid)
        await _edit_or_send(bot, att_uid, mid_att, txt, roulette_keyboard(duel_id, "att"))
        await _edit_or_send(bot, def_uid, mid_def, txt, roulette_wait_keyboard())

    elif mode == "pattern":
        p     = pattern_pick()
        p_idx = _PATTERNS.index(p)
        gs    = {"pattern_idx": p_idx, "att_ts": None, "def_ts": None}
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE skirmish_duels SET game_state=? WHERE id=?",
                (json.dumps(gs), duel_id)
            )
            await db.commit()
        duel["game_state"] = json.dumps(gs)
        txt = pattern_start_text(att_name, def_name, duel, p, round_num)
        for uid_d, role_d in ((att_uid, "att"), (def_uid, "def")):
            kb  = pattern_keyboard(duel_id, role_d, p)
            mid = live_msg_ids.get(uid_d)
            await _edit_or_send(bot, uid_d, mid, txt, kb)


async def _edit_or_send(bot, uid: int, msg_id: int | None, text: str,
                         kb: InlineKeyboardMarkup | None) -> None:
    try:
        if msg_id:
            await bot.edit_message_text(
                text, chat_id=uid, message_id=msg_id,
                parse_mode=ParseMode.HTML, reply_markup=kb,
            )
            return
    except (BadRequest, Forbidden, TimedOut):
        pass
    try:
        await bot.send_message(uid, text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except (BadRequest, Forbidden, TimedOut):
        pass


async def _send_duel_result(bot, sk_id: int, duel: dict,
                             result_text: str, round_winner: str,
                             att_name: str, def_name: str, mode: str) -> None:
    """Отправляет итог раунда и либо запускает следующий, либо завершает дуэль."""
    duel_id = duel["id"]
    att_uid = duel["att_uid"]
    def_uid = duel["def_uid"]

    # Загружаем live_msg_ids
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT live_msg_ids FROM skirmish_duels WHERE id=?", (duel_id,)
        ) as c:
            row = await c.fetchone()
    try:
        live_msg_ids = {int(k): v for k, v in json.loads(row[0] or "{}").items()}
    except Exception:
        live_msg_ids = {}

    # Записываем результат раунда
    duel_winner = await _duel_round_result(
        bot, sk_id, duel_id, att_name, def_name, round_winner, result_text
    )

    # Перечитываем свежий duel
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM skirmish_duels WHERE id=?", (duel_id,)) as c:
            fresh_row = await c.fetchone()
    fresh_duel = dict(fresh_row) if fresh_row else duel

    members = await sk_get_members(sk_id)

    if duel_winner:
        # Дуэль завершена — финальное сообщение всем
        winner_name = att_name if duel_winner == "attacker" else def_name
        final_text  = (
            f"{result_text}\n"
            f"\n"
            f"{he(winner_name)} побеждает {_E_TROPHY}"
        )
        for m in members:
            mid = live_msg_ids.get(m["user_id"])
            await _edit_or_send(bot, m["user_id"], mid, final_text, None)

        await asyncio.sleep(1)
        await _sk_finish_duel(
            bot, sk_id, duel_id, att_uid, def_uid, att_name, def_name, duel_winner
        )
    else:
        # Показываем итог раунда, запускаем следующий
        for m in members:
            mid = live_msg_ids.get(m["user_id"])
            await _edit_or_send(bot, m["user_id"], mid, result_text, None)

        await asyncio.sleep(2)

        # Следующий раунд
        new_round = fresh_duel.get("round_num", 2)
        await start_game_round(
            bot, sk_id, duel_id, att_uid, def_uid,
            att_name, def_name, mode, live_msg_ids, fresh_duel, new_round
        )
        # Таймаут на новый раунд (кроме реакции — она управляет собой)
        if mode != "reaction":
            asyncio.create_task(
                _sk_duel_timeout(bot, sk_id, duel_id, time.time() + SKIRMISH_ROUND_SEC)
            )



BET_PHASE_SEC     = 15     # секунд на ставки
BET_HOUSE_EDGE    = 0.05   # 5% комиссия дома
BET_QUICK_OPTIONS = [50, 100, 250, 500]   # быстрые кнопки


async def _bet_get_pool(duel_id: int) -> dict:
    """Возвращает {'attacker': сумма, 'defender': сумма, 'count': N}."""
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT side, SUM(amount), COUNT(*) FROM duel_bets WHERE duel_id=? GROUP BY side",
            (duel_id,),
        ) as c:
            rows = await c.fetchall()
    pool = {"attacker": 0, "defender": 0, "count": 0}
    for side, total, cnt in rows:
        pool[side] = total or 0
        pool["count"] += cnt
    return pool


def _bet_calc_odds(pool: dict, side: str) -> float:
    """Текущий коэффициент для стороны (сколько получишь за 1 поставленный)."""
    my_pool    = pool.get(side, 0)
    total_pool = pool.get("attacker", 0) + pool.get("defender", 0)
    if my_pool == 0 or total_pool == 0:
        return 2.0   # нет ставок — показываем 2x как стартовый
    return round(total_pool * (1 - BET_HOUSE_EDGE) / my_pool, 2)


def _bet_text(duel_id: int, att_name: str, def_name: str,
              pool: dict, my_bet: dict | None, seconds_left: int) -> str:
    att_pool = pool.get("attacker", 0)
    def_pool = pool.get("defender", 0)
    total    = att_pool + def_pool
    att_odds = _bet_calc_odds(pool, "attacker")
    def_odds = _bet_calc_odds(pool, "defender")

    # Визуальный баланс ставок
    if total > 0:
        att_w = int(att_pool / total * 10)
        def_w = 10 - att_w
        bar = "⚔️" * att_w + "🛡" * def_w
    else:
        bar = "⚔️" * 5 + "🛡" * 5

    my_line = ""
    if my_bet:
        side_ru = "⚔️ нападение" if my_bet["side"] == "attacker" else "🛡 защиту"
        odds    = att_odds if my_bet["side"] == "attacker" else def_odds
        win     = int(my_bet["amount"] * odds)
        my_line = f"\n✅ Твоя ставка: <b>{my_bet['amount']}🪙</b> на {side_ru} → выигрыш до <b>{win}🪙</b>"

    return (
        f"{_E_CASINO} <b>Ставки — бой</b>\n"
        f"{_E_SWORDS} <b>{he(att_name)}</b> vs 🛡️ <b>{he(def_name)}</b>\n"
        "\n"
        f"{bar}\n"
        f"{_E_SWORDS} Нападение: <b>{att_pool}🪙</b> ×{att_odds} ({pool.get('count',0)} ставок)\n"
        f"🛡 Защита: <b>{def_pool}🪙</b> ×{def_odds}\n"
        "\n"
        f"⏳ Ставки закрываются через <b>{seconds_left}с</b>"
        f"{my_line}"
    )


def _bet_keyboard(duel_id: int, side: str, has_bet: bool) -> InlineKeyboardMarkup:
    if has_bet:
        return InlineKeyboardMarkup([[
            btn("✅ Ставка принята", callback_data="bet_already"),
        ]])
    quick = [
        btn(f"{a}🪙", callback_data=f"bet_{duel_id}_{side}_{a}")
        for a in BET_QUICK_OPTIONS
    ]
    return InlineKeyboardMarkup([
        [btn(
            f"{_E_SWORDS} На нападение", callback_data=f"bet_side_{duel_id}_attacker",
        ), btn(
            f"🛡️ На защиту",   callback_data=f"bet_side_{duel_id}_defender",
        )],
        quick[:2],
        quick[2:],
        [btn("✏️ Своя сумма", callback_data=f"bet_custom_{duel_id}_{side}")],
    ])


def _bet_side_keyboard(duel_id: int) -> InlineKeyboardMarkup:
    """Первый шаг — выбор стороны."""
    return InlineKeyboardMarkup([[
        btn("⚔️ На нападение", callback_data=f"bet_side_{duel_id}_attacker"),
        btn("🛡️ На защиту",   callback_data=f"bet_side_{duel_id}_defender"),
    ]])


def _bet_amount_keyboard(duel_id: int, side: str) -> InlineKeyboardMarkup:
    quick = [
        btn(f"{a}🪙", callback_data=f"bet_{duel_id}_{side}_{a}")
        for a in BET_QUICK_OPTIONS
    ]
    return InlineKeyboardMarkup([
        quick[:2],
        quick[2:],
        [btn("✏️ Своя сумма", callback_data=f"bet_custom_{duel_id}_{side}")],
        [btn("◀️ Назад",       callback_data=f"bet_side_{duel_id}_back")],
    ])


async def _bet_get_my(duel_id: int, uid: int) -> dict | None:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM duel_bets WHERE duel_id=? AND uid=?", (duel_id, uid)
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def _bet_place(duel_id: int, sk_id: int, uid: int, side: str, amount: int) -> str:
    """Размещает ставку. Возвращает 'ok'|'already'|'no_coins'|'closed'."""
    # Проверяем дуэль ещё идёт
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT status FROM skirmish_duels WHERE id=?", (duel_id,)
        ) as c:
            row = await c.fetchone()
    if not row or row[0] != "betting":
        return "closed"

    f = await db_get(uid)
    if not f or f.get("coins", 0) < amount:
        return "no_coins"

    # Атомарная вставка — UNIQUE(duel_id, uid) защищает от дублей
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "INSERT INTO duel_bets(skirmish_id,duel_id,uid,side,amount,ts)"
                " VALUES(?,?,?,?,?,?)",
                (sk_id, duel_id, uid, side, amount, time.time()),
            )
            await db.commit()
    except Exception:
        return "already"

    f["coins"] -= amount
    await db_save(f)
    return "ok"


async def _bet_payout(bot, duel_id: int, winner_side: str):
    """Выплачивает выигрыши после дуэли."""
    pool = await _bet_get_pool(duel_id)
    total = pool["attacker"] + pool["defender"]
    win_pool = pool.get(winner_side, 0)
    if win_pool == 0:
        return   # никто не поставил на победителя — монеты сгорают

    prize_pool = int(total * (1 - BET_HOUSE_EDGE))

    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM duel_bets WHERE duel_id=? AND side=? AND paid_out=0",
            (duel_id, winner_side),
        ) as c:
            winners = [dict(r) for r in await c.fetchall()]

    for w in winners:
        payout = int(w["amount"] / win_pool * prize_pool)
        wf = await db_get(w["uid"])
        if wf:
            wf["coins"] = wf.get("coins", 0) + payout
            await db_save(wf)
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE duel_bets SET paid_out=? WHERE id=?", (payout, w["id"])
            )
            await db.commit()
        profit = payout - w["amount"]
        try:
            await bot.send_message(
                w["uid"],
                f"{_E_CASINO} <b>Ставка выиграла!</b>\n"
                f"Поставил: <b>{w['amount']}{_E_COIN}</b>\n"
                f"Получил: <b>{payout}{_E_COIN}</b> "
                f"({'<b>+' + str(profit) + _E_COIN + '</b>' if profit >= 0 else '<b>' + str(profit) + _E_COIN + '</b>'})",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass

    # Уведомляем проигравших
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        loser_side = "defender" if winner_side == "attacker" else "attacker"
        async with db.execute(
            "SELECT * FROM duel_bets WHERE duel_id=? AND side=? AND paid_out=0",
            (duel_id, loser_side),
        ) as c:
            losers = [dict(r) for r in await c.fetchall()]
        if losers:
            await db.execute(
                "UPDATE duel_bets SET paid_out=-1 WHERE duel_id=? AND side=?",
                (duel_id, loser_side),
            )
            await db.commit()

    for lo in losers:
        try:
            await bot.send_message(
                lo["uid"],
                f"{_E_CASINO} Ставка проиграла — <b>−{lo['amount']}{_E_COIN}</b>",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass


# ─────────────────────────────────────────────────────────────────────────────
async def _sk_start_duel(bot, sk: dict, att_m: dict, def_m: dict,
                          duel_index: int, total_duels: int) -> int:
    sk_id   = sk["id"]
    mode    = sk.get("mode", "rps")
    now     = time.time()
    att_uid = att_m["user_id"]
    def_uid = def_m["user_id"]

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_members SET supported=0 WHERE skirmish_id=?", (sk_id,)
        )
        cur = await db.execute(
            "INSERT INTO skirmish_duels"
            "(skirmish_id,att_uid,def_uid,round_num,att_hp,def_hp,status,mode,ts,live_msg_ids)"
            " VALUES(?,?,?,1,10,10,'betting',?,?,'{}')",
            (sk_id, att_uid, def_uid, mode, now),
        )
        duel_id = cur.lastrowid
        await db.execute(
            "UPDATE staya_skirmishes SET current_duel=?,duel_index=? WHERE id=?",
            (duel_id, duel_index, sk_id),
        )
        await db.commit()

    att_f = await db_get(att_uid)
    def_f = await db_get(def_uid)
    att_name = fname(att_f) if att_f else "?"
    def_name = fname(def_f) if def_f else "?"
    mode_name = SKIRMISH_MODE_NAMES.get(mode, mode)
    members   = await sk_get_members(sk_id)

    # ── Объявление боя + фаза ставок ──────────────────────────────────────────
    live_msg_ids: dict[int, int] = {}

    ann_text = (
        f"{_E_SWORDS} {he(att_name)} vs {he(def_name)}\n"
        f"бой {duel_index+1} из {total_duels} · {mode_name}\n"
        f"\n"
        f"{_E_CASINO} ставки открыты — {BET_PHASE_SEC} секунд"
    )

    for m in members:
        m_uid      = m["user_id"]
        is_fighter = m_uid in (att_uid, def_uid)
        try:
            msg = await bot.send_message(
                m_uid, ann_text, parse_mode=ParseMode.HTML,
                reply_markup=None if is_fighter else _bet_side_keyboard(duel_id),
            )
            live_msg_ids[m_uid] = msg.message_id
        except (BadRequest, Forbidden, TimedOut):
            pass

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET live_msg_ids=? WHERE id=?",
            (json.dumps({str(k): v for k, v in live_msg_ids.items()}), duel_id),
        )
        await db.commit()

    # Тик обновления ставок
    async def _bet_tick():
        for elapsed in (5, 10):
            await asyncio.sleep(5)
            left = BET_PHASE_SEC - elapsed
            pool = await _bet_get_pool(duel_id)
            for m in members:
                m_uid = m["user_id"]
                if m_uid in (att_uid, def_uid):
                    continue
                mid = live_msg_ids.get(m_uid)
                if not mid:
                    continue
                my_bet = await _bet_get_my(duel_id, m_uid)
                txt = _bet_text(duel_id, att_name, def_name, pool, my_bet, left)
                try:
                    await bot.edit_message_text(
                        txt, chat_id=m_uid, message_id=mid,
                        parse_mode=ParseMode.HTML,
                        reply_markup=None if my_bet else _bet_side_keyboard(duel_id),
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass

    asyncio.create_task(_bet_tick())

    # Ждём фазу ставок
    await asyncio.sleep(BET_PHASE_SEC)

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET status='waiting' WHERE id=? AND status='betting'",
            (duel_id,),
        )
        await db.commit()

    pool = await _bet_get_pool(duel_id)
    att_pool = pool.get("attacker", 0)
    def_pool = pool.get("defender", 0)
    total_p  = att_pool + def_pool
    att_odds = _bet_calc_odds(pool, "attacker")
    def_odds = _bet_calc_odds(pool, "defender")
    bet_line = (
        f"{_E_CASINO} Ставок: <b>{pool['count']}</b> · пул <b>{total_p}🪙</b> "
        f"({_E_SWORDS}{att_pool} ×{att_odds} / 🛡{def_pool} ×{def_odds})"
    )

    # Читаем свежую запись дуэли для передачи в start_game_round
    async with aiosqlite.connect(DB_PATH) as _fdi_db:
        _fdi_db.row_factory = aiosqlite.Row
        async with _fdi_db.execute("SELECT * FROM skirmish_duels WHERE id=?", (duel_id,)) as _c:
            _fdi_row = await _c.fetchone()
    fresh_duel_init = dict(_fdi_row) if _fdi_row else {}

    # Используем start_game_round для всех режимов кроме rps/evenodd
    if mode not in ("rps", "evenodd"):
        await start_game_round(
            bot, sk_id, duel_id, att_uid, def_uid,
            att_name, def_name, mode, live_msg_ids, fresh_duel_init, 1
        )
        if mode != "reaction":
            asyncio.create_task(_sk_duel_timeout(bot, sk_id, duel_id, now + BET_PHASE_SEC + SKIRMISH_ROUND_SEC))
        return duel_id

    if mode == "rps":
        fight_hint = "⏳ Делай ход!"
    else:
        fight_hint = "Выбери число 1–10, затем поставь на чётность суммы.\n⏳ Делай ход!"

    # Редактируем сообщения: бойцам — с кнопками, зрителям — с итогом ставок
    for uid_d, role_d in ((att_uid, "att"), (def_uid, "def")):
        mid = live_msg_ids.get(uid_d)
        kb  = _sk_rps_keyboard(duel_id, role_d) if mode == "rps" else _sk_eo_keyboard(duel_id, role_d)
        txt = (
            f"{_E_SWORDS} {he(att_name)} vs {he(def_name)}\n"
            f"бой {duel_index+1} из {total_duels}\n"
            f"\n"
            f"{fight_hint}"
        )
        try:
            if mid:
                await bot.edit_message_text(
                    txt, chat_id=uid_d, message_id=mid,
                    parse_mode=ParseMode.HTML, reply_markup=kb,
                )
            else:
                msg = await bot.send_message(uid_d, txt, parse_mode=ParseMode.HTML, reply_markup=kb)
                live_msg_ids[uid_d] = msg.message_id
        except Exception:
            try:
                msg = await bot.send_message(uid_d, txt, parse_mode=ParseMode.HTML, reply_markup=kb)
                live_msg_ids[uid_d] = msg.message_id
            except (BadRequest, Forbidden, TimedOut):
                pass

    for m in members:
        m_uid = m["user_id"]
        if m_uid in (att_uid, def_uid):
            continue
        mid    = live_msg_ids.get(m_uid)
        my_bet = await _bet_get_my(duel_id, m_uid)
        if my_bet:
            odds = att_odds if my_bet["side"] == "attacker" else def_odds
            win  = int(my_bet["amount"] * odds)
            side_ru = "⚔️ нападение" if my_bet["side"] == "attacker" else "🛡 защиту"
            my_line = f"\n✅ Твоя ставка: <b>{my_bet['amount']}🪙</b> на {side_ru} → до <b>{win}🪙</b>"
        else:
            my_line = "\n☑️ Ты не ставил"

        txt = (
            f"{_E_SWORDS} {he(att_name)} vs {he(def_name)}\n"
            f"бой {duel_index+1} из {total_duels} · {mode_name}\n"
            f"\n"
            f"{bet_line}{my_line}\n"
            f"\n"
            f"💪 поддержи своего бойца"
        )
        sup_kb = _sk_support_keyboard(sk_id, m["side"])
        try:
            if mid:
                await bot.edit_message_text(
                    txt, chat_id=m_uid, message_id=mid,
                    parse_mode=ParseMode.HTML, reply_markup=sup_kb,
                )
            else:
                msg = await bot.send_message(
                    m_uid, txt, parse_mode=ParseMode.HTML, reply_markup=sup_kb,
                )
                live_msg_ids[m_uid] = msg.message_id
        except Exception:
            try:
                msg = await bot.send_message(
                    m_uid, txt, parse_mode=ParseMode.HTML, reply_markup=sup_kb,
                )
                live_msg_ids[m_uid] = msg.message_id
            except (BadRequest, Forbidden, TimedOut):
                pass

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET live_msg_ids=? WHERE id=?",
            (json.dumps({str(k): v for k, v in live_msg_ids.items()}), duel_id),
        )
        await db.commit()

    asyncio.create_task(_sk_duel_timeout(bot, sk_id, duel_id, now + BET_PHASE_SEC + SKIRMISH_ROUND_SEC))
    return duel_id


async def _sk_duel_timeout(bot, sk_id: int, duel_id: int, deadline: float):
    await asyncio.sleep(max(0, deadline - time.time()))
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM skirmish_duels WHERE id=? AND status='waiting'", (duel_id,)
        ) as c:
            row = await c.fetchone()
    if not row:
        return
    duel = dict(row)
    mode = duel.get("mode", "rps")

    if mode == "rps":
        att_c = duel["att_choice"] or random.choice(list(_RPS_BEATS.keys()))
        def_c = duel["def_choice"] or random.choice(list(_RPS_BEATS.keys()))
        for uid_d, col in ((duel["att_uid"], "att_choice"), (duel["def_uid"], "def_choice")):
            if not duel[col]:
                try:
                    await bot.send_message(uid_d, "⏳ <b>Время вышло.</b> Ход сделан автоматически.",
                                           parse_mode=ParseMode.HTML)
                except (BadRequest, Forbidden, TimedOut):
                    pass
        await _sk_resolve_rps(bot, sk_id, duel, att_c, def_c)
    else:
        att_c = duel["att_choice"] or ""
        def_c = duel["def_choice"] or ""
        if not att_c or "?" in att_c:
            att_c = f"{random.randint(1,10)}:{random.choice(['even','odd'])}"
        if not def_c or "?" in def_c:
            def_c = f"{random.randint(1,10)}:{random.choice(['even','odd'])}"
        for uid_d, col in ((duel["att_uid"], "att_choice"), (duel["def_uid"], "def_choice")):
            if not duel[col] or "?" in (duel[col] or ""):
                try:
                    await bot.send_message(uid_d, "⏳ <b>Время вышло.</b> Ход сделан автоматически.",
                                           parse_mode=ParseMode.HTML)
                except (BadRequest, Forbidden, TimedOut):
                    pass
        await _sk_resolve_eo(bot, sk_id, duel, att_c, def_c)


async def _sk_send_round_result(bot, sk_id: int, duel: dict, att_name: str, def_name: str,
                                 round_result: str, att_hp: int, def_hp: int,
                                 round_num: int, mode: str, duel_id: int, next_round: bool):
    """Редактирует живое сообщение у всех участников."""
    att_uid = duel["att_uid"]
    def_uid = duel["def_uid"]

    # Загружаем live_msg_ids из БД
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT live_msg_ids FROM skirmish_duels WHERE id=?", (duel_id,)
        ) as c:
            row = await c.fetchone()
    try:
        live_msg_ids = json.loads(row[0]) if row and row[0] else {}
        live_msg_ids = {int(k): v for k, v in live_msg_ids.items()}
    except Exception:
        live_msg_ids = {}

    members = await sk_get_members(sk_id)

    if not next_round:
        # Финальный раунд — редактируем у всех, кнопки убираем
        summary = (
            f"{_E_SWORDS} {he(att_name)} vs {he(def_name)}\n"
            f"раунд {round_num}\n"
            f"\n"
            f"{round_result}"
        )
        for m in members:
            m_uid = m["user_id"]
            mid   = live_msg_ids.get(m_uid)
            try:
                if mid:
                    await bot.edit_message_text(
                        summary, chat_id=m_uid, message_id=mid,
                        parse_mode=ParseMode.HTML, reply_markup=None,
                    )
                else:
                    await bot.send_message(m_uid, summary, parse_mode=ParseMode.HTML)
            except Exception:
                try:
                    await bot.send_message(m_uid, summary, parse_mode=ParseMode.HTML)
                except (BadRequest, Forbidden, TimedOut):
                    pass
    else:
        # Не финальный — бойцам с кнопками, зрителям с поддержкой
        summary_base = (
            f"{_E_SWORDS} {he(att_name)} vs {he(def_name)}\n"
            f"раунд {round_num}\n"
            f"\n"
            f"{round_result}"
        )
        summary_fighters = (
            f"{_E_SWORDS} {he(att_name)} vs {he(def_name)}\n"
            f"раунд {round_num}\n"
            f"\n"
            f"{round_result}\n"
            f"\n"
            f"раунд {round_num + 1} — твой ход\n"
            f"⏳ {SKIRMISH_ROUND_SEC} секунд"
        )

        for uid_d, role_d in ((att_uid, "att"), (def_uid, "def")):
            mid = live_msg_ids.get(uid_d)
            kb  = _sk_rps_keyboard(duel_id, role_d) if mode == "rps" else _sk_eo_keyboard(duel_id, role_d)
            try:
                if mid:
                    await bot.edit_message_text(
                        summary_fighters, chat_id=uid_d, message_id=mid,
                        parse_mode=ParseMode.HTML, reply_markup=kb,
                    )
                else:
                    msg = await bot.send_message(
                        uid_d, summary_fighters, parse_mode=ParseMode.HTML, reply_markup=kb,
                    )
                    live_msg_ids[uid_d] = msg.message_id
            except Exception:
                try:
                    msg = await bot.send_message(
                        uid_d, summary_fighters, parse_mode=ParseMode.HTML, reply_markup=kb,
                    )
                    live_msg_ids[uid_d] = msg.message_id
                except (BadRequest, Forbidden, TimedOut):
                    pass

        for m in members:
            m_uid = m["user_id"]
            if m_uid in (att_uid, def_uid):
                continue
            mid    = live_msg_ids.get(m_uid)
            sup_kb = _sk_support_keyboard(sk_id, m["side"])
            try:
                if mid:
                    await bot.edit_message_text(
                        summary_base, chat_id=m_uid, message_id=mid,
                        parse_mode=ParseMode.HTML, reply_markup=sup_kb,
                    )
                else:
                    await bot.send_message(
                        m_uid, summary_base, parse_mode=ParseMode.HTML, reply_markup=sup_kb,
                    )
            except Exception:
                try:
                    await bot.send_message(
                        m_uid, summary_base, parse_mode=ParseMode.HTML, reply_markup=sup_kb,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass


async def _sk_apply_support(bot, sk_id: int) -> dict[int, int]:
    """Возвращает {uid: bonus_hp} для бойцов текущего боя."""
    members = await sk_get_members(sk_id)
    return {
        "attacker": sum(1 for m in members if m["side"] == "attacker" and m.get("supported", 0) == 2),
        "defender": sum(1 for m in members if m["side"] == "defender" and m.get("supported", 0) == 2),
    }


async def _sk_resolve_rps(bot, sk_id: int, duel: dict, att_c: str, def_c: str):
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM skirmish_duels WHERE id=? AND status='waiting'", (duel["id"],)
        ) as c:
            fresh = await c.fetchone()
    if not fresh:
        return
    duel = dict(fresh)

    att_f = await db_get(duel["att_uid"])
    def_f = await db_get(duel["def_uid"])
    att_name = fname(att_f) if att_f else "?"
    def_name = fname(def_f) if def_f else "?"
    att_hp = duel["att_hp"]
    def_hp = duel["def_hp"]
    round_num = duel["round_num"]

    support = await _sk_apply_support(bot, sk_id)
    att_hp = min(10, att_hp + support.get("attacker", 0))
    def_hp = min(10, def_hp + support.get("defender", 0))

    if att_c == def_c:
        att_hp -= 1; def_hp -= 1
        round_result = f"⚖️ <b>Ничья!</b> {_RPS_EMOJI[att_c]} vs {_RPS_EMOJI[def_c]} — оба −1 HP"
        result = "draw"
    elif _RPS_BEATS.get(att_c) == def_c:
        def_hp -= 4
        round_result = (
            f"{_E_TROPHY} <b>{he(att_name)}</b> побеждает раунд!\n"
            f"{_RPS_EMOJI[att_c]} {_RPS_NAME[att_c]} бьёт {_RPS_EMOJI[def_c]} {_RPS_NAME[def_c]}\n"
            f"<b>{he(def_name)}</b> −4 HP"
        )
        result = "attacker"
    else:
        att_hp -= 4
        round_result = (
            f"{_E_TROPHY} <b>{he(def_name)}</b> побеждает раунд!\n"
            f"{_RPS_EMOJI[def_c]} {_RPS_NAME[def_c]} бьёт {_RPS_EMOJI[att_c]} {_RPS_NAME[att_c]}\n"
            f"<b>{he(att_name)}</b> −4 HP"
        )
        result = "defender"

    att_hp = max(0, att_hp)
    def_hp = max(0, def_hp)
    new_round = round_num + 1
    duel_over = att_hp <= 0 or def_hp <= 0 or round_num >= 3

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET att_hp=?,def_hp=?,"
            # Сбрасываем выборы в NULL — иначе на след. раунде бот думает что уже выбрали
            "att_choice=NULL,def_choice=NULL,"
            "round_num=?,status=? WHERE id=? AND status='waiting'",
            (att_hp, def_hp, new_round,
             "finished" if duel_over else "waiting", duel["id"]),
        )
        await db.commit()

    # Обновляем duel для передачи в _sk_send_round_result (нужен att_uid/def_uid)
    duel["att_hp"] = att_hp
    duel["def_hp"] = def_hp
    duel["round_num"] = new_round

    if duel_over:
        winner = ("attacker" if att_hp > def_hp else
                  "defender" if def_hp > att_hp else
                  ("attacker" if result != "draw" else random.choice(["attacker", "defender"])))
        await _sk_send_round_result(bot, sk_id, duel, att_name, def_name, round_result,
                                     att_hp, def_hp, round_num, "rps", duel["id"], False)
        await asyncio.sleep(1)
        await _sk_finish_duel(bot, sk_id, duel["id"], duel["att_uid"], duel["def_uid"],
                               att_name, def_name, winner)
    else:
        await _sk_send_round_result(bot, sk_id, duel, att_name, def_name, round_result,
                                     att_hp, def_hp, round_num, "rps", duel["id"], True)
        asyncio.create_task(_sk_duel_timeout(bot, sk_id, duel["id"], time.time() + SKIRMISH_ROUND_SEC))


async def _sk_resolve_eo(bot, sk_id: int, duel: dict, att_choice: str, def_choice: str):
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM skirmish_duels WHERE id=? AND status='waiting'", (duel["id"],)
        ) as c:
            fresh = await c.fetchone()
    if not fresh:
        return
    duel = dict(fresh)

    att_f = await db_get(duel["att_uid"])
    def_f = await db_get(duel["def_uid"])
    att_name = fname(att_f) if att_f else "?"
    def_name = fname(def_f) if def_f else "?"
    att_hp = duel["att_hp"]
    def_hp = duel["def_hp"]
    round_num = duel["round_num"]

    support = await _sk_apply_support(bot, sk_id)
    att_hp = min(10, att_hp + support.get("attacker", 0))
    def_hp = min(10, def_hp + support.get("defender", 0))

    def parse_eo(s: str) -> tuple[int, str]:
        try:
            num_s, parity = s.split(":", 1)
            return int(num_s), parity
        except Exception:
            return random.randint(1, 10), random.choice(["even", "odd"])

    att_num, att_parity = parse_eo(att_choice)
    def_num, def_parity = parse_eo(def_choice)
    total   = att_num + def_num
    actual  = "even" if total % 2 == 0 else "odd"
    act_ru  = "Чёт" if actual == "even" else "Нечет"
    att_ok  = att_parity == actual
    def_ok  = def_parity == actual
    att_p_ru = "Чёт" if att_parity == "even" else "Нечет"
    def_p_ru = "Чёт" if def_parity == "even" else "Нечет"

    detail = (
        f"Числа: <b>{he(att_name)}</b> загадал {att_num}, <b>{he(def_name)}</b> загадал {def_num}\n"
        f"Сумма: {att_num}+{def_num}={total} → <b>{act_ru}</b>\n"
        f"{he(att_name)}: {att_p_ru} {_E_CHECK if att_ok else _E_CROSS}  "
        f"{he(def_name)}: {def_p_ru} {_E_CHECK if def_ok else _E_CROSS}"
    )

    if att_ok and not def_ok:
        def_hp -= 4; result = "attacker"
        round_result = f"{_E_TROPHY} <b>{he(att_name)}</b> угадал! <b>{he(def_name)}</b> −4 HP\n{detail}"
    elif def_ok and not att_ok:
        att_hp -= 4; result = "defender"
        round_result = f"{_E_TROPHY} <b>{he(def_name)}</b> угадал! <b>{he(att_name)}</b> −4 HP\n{detail}"
    else:
        att_hp -= 1; def_hp -= 1; result = "draw"
        verb = "угадали" if att_ok else "промахнулись"
        round_result = f"⚖️ Оба {verb}! Оба −1 HP\n{detail}"

    att_hp = max(0, att_hp)
    def_hp = max(0, def_hp)
    duel_over = att_hp <= 0 or def_hp <= 0 or round_num >= 3

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET att_hp=?,def_hp=?,"
            "att_choice=NULL,def_choice=NULL,"
            "round_num=?,status=? WHERE id=? AND status='waiting'",
            (att_hp, def_hp, round_num+1,
             "finished" if duel_over else "waiting", duel["id"]),
        )
        await db.commit()

    duel["att_hp"] = att_hp
    duel["def_hp"] = def_hp
    duel["round_num"] = round_num + 1

    if duel_over:
        winner = ("attacker" if att_hp > def_hp else
                  "defender" if def_hp > att_hp else
                  ("attacker" if result != "draw" else random.choice(["attacker", "defender"])))
        await _sk_send_round_result(bot, sk_id, duel, att_name, def_name, round_result,
                                     att_hp, def_hp, round_num, "evenodd", duel["id"], False)
        await asyncio.sleep(1)
        await _sk_finish_duel(bot, sk_id, duel["id"], duel["att_uid"], duel["def_uid"],
                               att_name, def_name, winner)
    else:
        await _sk_send_round_result(bot, sk_id, duel, att_name, def_name, round_result,
                                     att_hp, def_hp, round_num, "evenodd", duel["id"], True)
        asyncio.create_task(_sk_duel_timeout(bot, sk_id, duel["id"], time.time() + SKIRMISH_ROUND_SEC))


async def _sk_finish_duel(bot, sk_id: int, duel_id: int,
                           att_uid: int, def_uid: int,
                           att_name: str, def_name: str, winner: str):
    winner_uid = att_uid if winner == "attacker" else def_uid
    loser_uid  = def_uid if winner == "attacker" else att_uid
    winner_name = att_name if winner == "attacker" else def_name
    col_win = "att_wins" if winner == "attacker" else "def_wins"

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("UPDATE skirmish_duels SET winner=?,status='finished' WHERE id=?",
                         (winner, duel_id))
        await db.execute(
            "UPDATE skirmish_members SET duels_won=duels_won+1 WHERE skirmish_id=? AND user_id=?",
            (sk_id, winner_uid))
        await db.execute(
            "UPDATE skirmish_members SET duels_lost=duels_lost+1 WHERE skirmish_id=? AND user_id=?",
            (sk_id, loser_uid))
        await db.execute(f"UPDATE staya_skirmishes SET {col_win}={col_win}+1 WHERE id=?", (sk_id,))
        await db.commit()

    winner_f = await db_get(winner_uid)
    if winner_f:
        winner_f["coins"] = winner_f.get("coins", 0) + SKIRMISH_DUEL_REWARD
        await db_save(winner_f)

    await war_stat_add(winner_uid, duels_won=1)
    await war_stat_add(loser_uid,  duels_lost=1)

    # Выплачиваем ставки
    asyncio.create_task(_bet_payout(bot, duel_id, winner))

    sk = await sk_get(sk_id)
    if not sk:
        return
    members = await sk_get_members(sk_id)

    # Одно сообщение: результат дуэли + счёт
    scoreboard = await _sk_scoreboard(sk, members)
    duel_result = (
        f"{he(winner_name)} побеждает дуэль {_E_TROPHY}\n"
        f"+{SKIRMISH_DUEL_REWARD}🪙\n"
        f"\n"
        f"{scoreboard}"
    )
    await _sk_broadcast(bot, sk_id, duel_result)

    duel_order = json.loads(sk.get("duel_order") or "[]")
    next_index = sk.get("duel_index", 0) + 1

    if next_index < len(duel_order):
        # Атомарно обновляем duel_index ДО загрузки пары
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE staya_skirmishes SET duel_index=? WHERE id=? AND duel_index=?",
                (next_index, sk_id, sk.get("duel_index", 0)),
            )
            await db.commit()
        # Перечитываем sk — убеждаемся что именно мы обновили (защита от гонки)
        sk_fresh = await sk_get(sk_id)
        if not sk_fresh or sk_fresh.get("duel_index", 0) != next_index:
            return  # другой таск уже взял управление

        members = await sk_get_members(sk_id)
        pair = duel_order[next_index]
        next_att_m = next((m for m in members if m["user_id"] == pair[0]), None)
        next_def_m = next((m for m in members if m["user_id"] == pair[1]), None)
        if next_att_m and next_def_m:
            await asyncio.sleep(3)
            await _sk_broadcast(bot, sk_id, "· · ·")
            await asyncio.sleep(2)
            await _sk_start_duel(bot, sk_fresh, next_att_m, next_def_m, next_index, len(duel_order))
            return

    await _sk_finish(bot, sk_id)


async def _sk_finish(bot, sk_id: int):
    sk = await sk_get(sk_id)
    if not sk or sk["status"] == "finished":
        return

    att_wins = sk.get("att_wins", 0)
    def_wins = sk.get("def_wins", 0)
    members  = await sk_get_members(sk_id)
    att_hp   = sum(m.get("hp_left", 0) for m in members if m["side"] == "attacker" and not m.get("fled"))
    def_hp   = sum(m.get("hp_left", 0) for m in members if m["side"] == "defender" and not m.get("fled"))

    winner_side = (
        "attacker" if att_wins > def_wins else
        "defender" if def_wins > att_wins else
        "attacker" if att_hp >= def_hp else "defender"
    )

    att_staya = await staya_get(sk["attacker_staya"])
    def_staya = await staya_get(sk["defender_staya"])
    att_name  = att_staya["name"] if att_staya else "?"
    def_name  = def_staya["name"] if def_staya else "?"
    winner_name = att_name if winner_side == "attacker" else def_name

    cauldron_taken = 0
    if winner_side == "attacker" and def_staya:
        steal = min(int(def_staya["cauldron"] * SKIRMISH_WIN_PCT), SKIRMISH_WIN_MAX)
        cauldron_taken = steal
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE stayas SET cauldron=MAX(0,cauldron-?) WHERE id=?",
                             (steal, def_staya["id"]))
            await db.execute("UPDATE stayas SET cauldron=cauldron+? WHERE id=?",
                             (steal, att_staya["id"]))
            await db.commit()
    elif winner_side == "defender" and att_staya:
        comp = SKIRMISH_ENTRY_COINS // 2
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE stayas SET cauldron=cauldron+? WHERE id=?",
                             (comp, def_staya["id"]))
            await db.commit()
        cauldron_taken = -comp

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE staya_skirmishes SET status='finished',winner=?,cauldron_taken=?,finished_at=? WHERE id=?",
            (winner_side, cauldron_taken, time.time(), sk_id),
        )
        await db.commit()

    for m in members:
        mf = await db_get(m["user_id"])
        if not mf:
            continue
        won = m["side"] == winner_side
        add_xp(mf, 200 if won else 120)
        mf["hunger"]      = max(0, mf.get("hunger", 50) - 20)
        mf["energy"]      = max(0, mf.get("energy", 70) - 25)
        mf["cleanliness"] = max(0, mf.get("cleanliness", 70) - 10)
        if not won:
            mf["happiness"] = max(0, mf.get("happiness", 70) - 10)
        await db_save(mf)

    scoreboard_fin = await _sk_scoreboard(sk, members)
    cauldron_line = ""
    if cauldron_taken > 0:
        cauldron_line = f"\n💰 {he(att_name if winner_side == 'attacker' else def_name)} забирают {cauldron_taken}🪙 из котла"
    elif cauldron_taken < 0:
        cauldron_line = f"\n🛡 компенсация защитникам +{abs(cauldron_taken)}🪙"

    final_text = (
        f"🏁 {he(winner_name)} побеждают{cauldron_line}\n"
        f"\n"
        f"{scoreboard_fin}"
    )
    await _sk_broadcast(bot, sk_id, final_text)


async def _sk_gather_timeout(bot, sk_id: int, deadline: float):
    await asyncio.sleep(max(0, deadline - time.time()))
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE staya_skirmishes SET status='active' WHERE id=? AND status='gathering'",
            (sk_id,),
        )
        await db.commit()
    sk = await sk_get(sk_id)
    if not sk or sk["status"] != "active":
        return
    await _sk_launch(bot, sk_id)


async def _sk_launch(bot, sk_id: int):
    sk = await sk_get(sk_id)
    if not sk:
        return
    members = await sk_get_members(sk_id)
    att = sorted([m for m in members if m["side"] == "attacker" and not m.get("fled") and not m.get("is_spectator")],
                 key=lambda m: m.get("level", 1), reverse=True)
    dfn = sorted([m for m in members if m["side"] == "defender" and not m.get("fled") and not m.get("is_spectator")],
                 key=lambda m: m.get("level", 1), reverse=True)

    if not att:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE staya_skirmishes SET status='finished',winner='defender',finished_at=? WHERE id=?",
                             (time.time(), sk_id))
            await db.commit()
        await _sk_broadcast(bot, sk_id, "⚔️ Стычка отменена: нападающие не явились.\n🏆 Победа защитников!")
        return
    if not dfn:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE staya_skirmishes SET status='finished',winner='attacker',finished_at=? WHERE id=?",
                             (time.time(), sk_id))
            await db.commit()
        await _sk_broadcast(bot, sk_id, "⚔️ Стычка отменена: защитники не явились.\n🏆 Победа нападающих!")
        return

    pairs = list(zip(att, dfn))
    duel_order = [[p[0]["user_id"], p[1]["user_id"]] for p in pairs]
    mode = random.choice(SKIRMISH_MODES)
    mode_name = SKIRMISH_MODE_NAMES[mode]

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE staya_skirmishes SET mode=?,duel_order=?,status='active' WHERE id=?",
            (mode, json.dumps(duel_order), sk_id),
        )
        await db.commit()

    sk = await sk_get(sk_id)
    att_staya = await staya_get(sk["attacker_staya"])
    def_staya = await staya_get(sk["defender_staya"])

    _att_sn = (att_staya["name"] if att_staya else "?")
    _def_sn = (def_staya["name"] if def_staya else "?")
    launch_text = (
        f"🐸 БОЙ НАЧИНАЕТСЯ\n"
        f"\n"
        f"{he(_att_sn)} {_E_SWORDS} {he(_def_sn)}\n"
        f"режим — {mode_name}\n"
        f"\n"
        f"Бои идут один за другим.\n"
        f"Не дерёшься — болей за своих."
    )
    await _sk_broadcast(bot, sk_id, launch_text)
    await asyncio.sleep(5)
    await _sk_start_duel(bot, sk, pairs[0][0], pairs[0][1], 0, len(pairs))






