async def cmd_newsdigest(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/newsdigest — дайджест последних событий болота для газеты."""
    uid = update.effective_user.id
    if uid not in ADMIN_IDS:
        return

    hours = 24
    if ctx.args:
        try:
            hours = int(ctx.args[0])
        except ValueError:
            pass

    since = time.time() - hours * 3600
    now   = time.time()

    sections: list[str] = []

    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row

        # ── Смерти ────────────────────────────────────────────────────────────
        async with db.execute(
            "SELECT user_id, frog_name, username, first_name, level, death_reason "
            "FROM frogs WHERE alive=0 AND last_decay >= ? ORDER BY last_decay DESC LIMIT 5",
            (since,)
        ) as c:
            deaths = [dict(r) for r in await c.fetchall()]

        # ── Воскрешения ───────────────────────────────────────────────────────
        async with db.execute(
            "SELECT user_id, details, ts FROM player_action_log "
            "WHERE action='revive' AND ts >= ? ORDER BY ts DESC LIMIT 5",
            (since,)
        ) as c:
            revives = [dict(r) for r in await c.fetchall()]

        # ── Уровни (новые высокие уровни) ─────────────────────────────────────
        async with db.execute(
            "SELECT user_id, frog_name, username, first_name, level "
            "FROM frogs WHERE alive=1 AND level >= 5 "
            "ORDER BY level DESC LIMIT 10",
            ()
        ) as c:
            top_levels = [dict(r) for r in await c.fetchall()]

        # ── Набеги ────────────────────────────────────────────────────────────
        async with db.execute(
            "SELECT r.*, "
            "  a_st.name as att_name, t_st.name as tgt_name, "
            "  r.stolen_coins, r.status "
            "FROM staya_raids r "
            "LEFT JOIN stayas a_st ON a_st.id = r.attacker_staya "
            "LEFT JOIN stayas t_st ON t_st.id = r.target_staya "
            "WHERE r.ts >= ? ORDER BY r.ts DESC LIMIT 5",
            (since,)
        ) as c:
            raids = [dict(r) for r in await c.fetchall()]

        # ── Стычки ────────────────────────────────────────────────────────────
        async with db.execute(
            "SELECT s.*, "
            "  a_st.name as att_name, d_st.name as def_name, "
            "  s.att_wins, s.def_wins, s.cauldron_taken, s.winner "
            "FROM staya_skirmishes s "
            "LEFT JOIN stayas a_st ON a_st.id = s.attacker_staya "
            "LEFT JOIN stayas d_st ON d_st.id = s.defender_staya "
            "WHERE s.status='finished' AND s.finished_at >= ? "
            "ORDER BY s.finished_at DESC LIMIT 5",
            (since,)
        ) as c:
            skirmishes = [dict(r) for r in await c.fetchall()]

        # ── Дуэли в стычках (личные победы) ──────────────────────────────────
        async with db.execute(
            "SELECT d.att_uid, d.def_uid, d.winner, d.mode, d.ts, "
            "  f1.frog_name as att_fname, f1.username as att_uname, "
            "  f2.frog_name as def_fname, f2.username as def_uname "
            "FROM skirmish_duels d "
            "LEFT JOIN frogs f1 ON f1.user_id = d.att_uid "
            "LEFT JOIN frogs f2 ON f2.user_id = d.def_uid "
            "WHERE d.status='finished' AND d.ts >= ? "
            "ORDER BY d.ts DESC LIMIT 8",
            (since,)
        ) as c:
            duels = [dict(r) for r in await c.fetchall()]

        # ── Турниры ───────────────────────────────────────────────────────────
        async with db.execute(
            "SELECT t.*, f.frog_name, f.username "
            "FROM tournaments t "
            "LEFT JOIN frogs f ON f.user_id = t.winner_id "
            "WHERE t.status='finished' AND t.created_at >= ? "
            "ORDER BY t.created_at DESC LIMIT 3",
            (since,)
        ) as c:
            tournaments = [dict(r) for r in await c.fetchall()]

        # ── Подарки ───────────────────────────────────────────────────────────
        async with db.execute(
            "SELECT g.*, "
            "  f1.frog_name as from_name, f1.username as from_uname, "
            "  f2.frog_name as to_name, f2.username as to_uname "
            "FROM gift_log g "
            "LEFT JOIN frogs f1 ON f1.user_id = g.from_id "
            "LEFT JOIN frogs f2 ON f2.user_id = g.to_id "
            "WHERE g.ts >= ? ORDER BY g.amount DESC LIMIT 5",
            (since,)
        ) as c:
            gifts = [dict(r) for r in await c.fetchall()]

        # ── Новые игроки ──────────────────────────────────────────────────────
        async with db.execute(
            "SELECT user_id, frog_name, username, first_name, born_at "
            "FROM frogs WHERE born_at >= ? ORDER BY born_at DESC LIMIT 10",
            (since,)
        ) as c:
            newbies = [dict(r) for r in await c.fetchall()]

        # ── Богатейшие лягушки ────────────────────────────────────────────────
        async with db.execute(
            "SELECT user_id, frog_name, username, first_name, coins, level "
            "FROM frogs WHERE alive=1 ORDER BY coins DESC LIMIT 5"
        ) as c:
            richest = [dict(r) for r in await c.fetchall()]

        # ── Котлы стай ───────────────────────────────────────────────────────
        async with db.execute(
            "SELECT name, cauldron, level FROM stayas ORDER BY cauldron DESC LIMIT 5"
        ) as c:
            top_cauldrons = [dict(r) for r in await c.fetchall()]

    def _n(row, name_key="frog_name", user_key="username", alt_key="first_name"):
        name = row.get(name_key) or row.get(alt_key) or "?"
        uname = row.get(user_key)
        return f"@{uname}" if uname else name

    lines = [
        f"📰 <b>Дайджест болота</b> · последние {hours}ч\n"
        f"Сгенерировано: {datetime.now().strftime('%d.%m %H:%M')}\n"
    ]

    # СМЕРТИ
    if deaths:
        lines.append(f"\n<b>{_E_SKULL} НЕКРОЛОГИ</b>")
        for d in deaths:
            reason_map = {
                "hunger":   "умер от голода",
                "health":   "скончался от ран",
                "overfeed": "переел",
                "":         "покинул болото",
            }
            reason = reason_map.get(d.get("death_reason", ""), "погиб при невыясненных обстоятельствах")
            lines.append(f"  · {_n(d)} (ур.{d['level']}) — {reason}")

    # ВОСКРЕШЕНИЯ
    if revives:
        lines.append(f"\n<b>{_E_LEAF} ВОСКРЕШЕНИЯ</b>")
        for r in revives:
            f_r = await db_get(r["user_id"])
            lines.append(f"  · {_n(f_r) if f_r else str(r['user_id'])} вернулся в болото")

    # НОВЫЕ ИГРОКИ
    if newbies:
        lines.append(f"\n<b>🐣 НОВЫЕ ЖИТЕЛИ</b> ({len(newbies)} шт.)")
        for nb in newbies[:5]:
            lines.append(f"  · {_n(nb)}")
        if len(newbies) > 5:
            lines.append(f"  · ... и ещё {len(newbies) - 5}")

    # НАБЕГИ
    if raids:
        lines.append("\n<b>🏹 НАБЕГИ</b>")
        for r in raids:
            att  = r.get("att_name") or "?"
            tgt  = r.get("tgt_name") or "?"
            if r["status"] == "success":
                stolen = r.get("stolen_coins") or 0
                lines.append(f"  · «{att}» ограбила «{tgt}» — унесено {stolen}{_E_COIN}")
            else:
                lines.append(f"  · «{att}» нападала на «{tgt}» — ловушка!")

    # СТЫЧКИ
    if skirmishes:
        lines.append(f"\n<b>{_E_SWORDS} СТЫЧКИ</b>")
        for s in skirmishes:
            att   = s.get("att_name") or "?"
            dfn   = s.get("def_name") or "?"
            aw    = s.get("att_wins", 0)
            dw    = s.get("def_wins", 0)
            taken = s.get("cauldron_taken", 0)
            winner_name = att if s.get("winner") == "attacker" else dfn
            loser_name  = dfn if s.get("winner") == "attacker" else att
            result = f"«{winner_name}» победила «{loser_name}» ({aw}:{dw})"
            if taken and taken > 0:
                result += f" — захвачено {taken}🪙"
            lines.append(f"  · {result}")

    # ДУЭЛИ
    if duels:
        lines.append("\n<b>🥊 ДУЭЛИ</b>")
        mode_names = {
            "rps": "КНБ", "evenodd": "Чёт-нечет",
            "guess": "Угадай число", "reaction": "Реакция",
            "lottery": "Лотерея", "bluff": "Блеф",
            "roulette": "Рулетка", "pattern": "Паттерн",
        }
        for d in duels[:5]:
            winner_uid = d["att_uid"] if d["winner"] == "attacker" else d["def_uid"]
            loser_uid  = d["def_uid"] if d["winner"] == "attacker" else d["att_uid"]
            wname = (f"@{d['att_uname']}" if d["winner"] == "attacker" and d.get("att_uname")
                     else d.get("att_fname") or "?") if d["winner"] == "attacker" else (
                     f"@{d['def_uname']}" if d.get("def_uname") else d.get("def_fname") or "?")
            lname = (f"@{d['def_uname']}" if d.get("def_uname") else d.get("def_fname") or "?") if d["winner"] == "attacker" else (
                     f"@{d['att_uname']}" if d.get("att_uname") else d.get("att_fname") or "?")
            mode  = mode_names.get(d.get("mode", ""), d.get("mode", ""))
            lines.append(f"  · {wname} победил {lname} ({mode})")

    # ТУРНИРЫ
    if tournaments:
        lines.append(f"\n<b>{_E_TROPHY} ТУРНИРЫ</b>")
        for t in tournaments:
            wname = t.get("frog_name") or (f"@{t['username']}" if t.get("username") else "?")
            try:
                parts = json.loads(t.get("participants") or "[]")
                cnt = len(parts)
            except Exception:
                cnt = "?"
            lines.append(f"  · {wname} · {cnt} уч. · {t['stake']}{_E_COIN}")

    # ПОДАРКИ
    if gifts:
        lines.append(f"\n<b>{_E_GIFT} КРУПНЫЕ ПОДАРКИ</b>")
        for g in gifts[:3]:
            fn = g.get("from_name") or (f"@{g['from_uname']}" if g.get("from_uname") else "?")
            tn = g.get("to_name")   or (f"@{g['to_uname']}"   if g.get("to_uname")   else "?")
            lines.append(f"  · {fn} подарил {tn} — {g['amount']}{_E_COIN}")

    # ТОП УРОВНЕЙ
    if top_levels:
        lines.append(f"\n<b>{_E_CHART} ТОП УРОВНЕЙ</b>")
        medals = ["🥇", "🥈", "🥉"] + ["·"] * 10
        for i, f in enumerate(top_levels[:5]):
            lines.append(f"  {medals[i]} {_n(f)} — ур.{f['level']}")

    # БОГАТЕЙШИЕ
    if richest:
        lines.append(f"\n<b>{_E_MONEYBAG} БОГАТЕЙШИЕ</b>")
        for i, f in enumerate(richest):
            lines.append(f"  {['🥇','🥈','🥉','·','·'][i]} {_n(f)} — {f['coins']}{_E_COIN}")

    # КОТЛЫ СТАЙ
    if top_cauldrons:
        lines.append("\n<b>🫕 КОТЛЫ СТАЙ</b>")
        for s in top_cauldrons:
            lines.append(f"  · «{s['name']}» (ур.{s['level']}) — {s['cauldron']}{_E_COIN}")

    lines.append(f"\n<i>Данные за последние {hours} часов.</i>")

    text = "\n".join(lines)

    # Если слишком длинное — режем
    if len(text) > 4000:
        text = text[:3900] + "\n\n<i>... (обрезано)</i>"

    await update.message.reply_text(text, parse_mode=ParseMode.HTML)







