# ── DB-хелперы дружбы ─────────────────────────────────────────────────────────

async def friend_get(uid: int, fid: int) -> dict | None:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM friendships WHERE user_id=? AND friend_id=?",
            (uid, fid),
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None




async def _skirmish_status_text(sk_id: int) -> str:
    """Текущий счёт и статус всех дуэлей в стычке."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT sd.*, "
            "fa.frog_name as att_fn, fa.first_name as att_na, "
            "fd.frog_name as def_fn, fd.first_name as def_na "
            "FROM skirmish_duels sd "
            "LEFT JOIN frogs fa ON fa.user_id=sd.att_uid "
            "LEFT JOIN frogs fd ON fd.user_id=sd.def_uid "
            "WHERE sd.skirmish_id=? ORDER BY sd.id",
            (sk_id,),
        ) as c:
            duels = [dict(r) for r in await c.fetchall()]
    sk = await skirmish_get(sk_id)
    att_w = sk["att_wins"] if sk else 0
    def_w = sk["def_wins"] if sk else 0
    lines = [f"<b>Счёт: {att_w} : {def_w}</b>", ""]
    for d in duels:
        an = d.get("att_fn") or d.get("att_na") or "?"
        dn = d.get("def_fn") or d.get("def_na") or "?"
        if d["status"] == "finished":
            w = d.get("winner", "")
            wn = an if w == "attacker" else dn
            lines.append(f"  {he(an)} vs {he(dn)} — {he(wn)} победил")
        else:
            lines.append(f"  {he(an)} vs {he(dn)} — идёт бой")
    return "\n".join(lines)


async def _skirmish_check_all_done(bot, sk_id: int):
    """Если все дуэли завершены — запускаем финал."""
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(*) FROM skirmish_duels WHERE skirmish_id=? AND status='waiting'",
            (sk_id,),
        ) as c:
            waiting = (await c.fetchone())[0]
    if waiting == 0:
        await skirmish_finish(bot, sk_id)


async def _skirmish_do_start(bot, sk_id: int):
    """Общий запуск стычки — из таймаута и из авто-старта по заполнению."""
    sk = await skirmish_get(sk_id)
    if not sk:
        return
    members = await skirmish_get_members(sk_id)
    att = [m for m in members if m["side"] == "attacker"]
    dfn = [m for m in members if m["side"] == "defender"]

    if len(dfn) == 0:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE staya_skirmishes SET status='finished', winner='attacker', finished_at=? WHERE id=?",
                (time.time(), sk_id),
            )
            await db.commit()
        await skirmish_broadcast(bot, sk_id,
            "Стычка отменена: защитники не явились. Победа атакующей стаи.")
        return

    if len(att) == 0:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE staya_skirmishes SET status='finished', winner='defender', finished_at=? WHERE id=?",
                (time.time(), sk_id),
            )
            await db.commit()
        await skirmish_broadcast(bot, sk_id,
            "Стычка отменена: нападающие не явились. Победа защитников.")
        return

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE staya_skirmishes SET status='active' WHERE id=? AND status='gathering'",
            (sk_id,),
        )
        await db.commit()

    await skirmish_broadcast(bot, sk_id,
        f"Стычка началась: {len(att)} vs {len(dfn)}.\n"
        f"Все бои идут одновременно. Жди сообщения со своей дуэлью.")
    await asyncio.sleep(2)
    await skirmish_start_all_duels(bot, sk_id)


async def skirmish_start_all_duels(bot, sk_id: int):
    """Запускает ВСЕ пары одновременно."""
    sk = await skirmish_get(sk_id)
    if not sk or sk["status"] != "active":
        return

    members = await skirmish_get_members(sk_id)
    att_members = sorted(
        [m for m in members if m["side"] == "attacker" and not m.get("fled")],
        key=lambda m: m.get("level", 1), reverse=True,
    )
    def_members = sorted(
        [m for m in members if m["side"] == "defender" and not m.get("fled")],
        key=lambda m: m.get("level", 1), reverse=True,
    )
    pairs = list(zip(att_members[:sk["size"]], def_members[:sk["size"]]))
    if not pairs:
        await skirmish_finish(bot, sk_id)
        return

    total = len(pairs)
    now = time.time()

    for i, (att_m, def_m) in enumerate(pairs):
        att_uid = att_m["user_id"]
        def_uid = def_m["user_id"]
        mode = skirmish_random_mode()

        async with aiosqlite.connect(DB_PATH) as db:
            cur = await db.execute(
                "INSERT INTO skirmish_duels(skirmish_id,att_uid,def_uid,round_num,att_hp,def_hp,status,mode,ts)"
                " VALUES(?,?,?,1,10,10,'waiting',?,?)",
                (sk_id, att_uid, def_uid, mode, now),
            )
            duel_id = cur.lastrowid
            await db.commit()

        att_f = await db_get(att_uid)
        def_f = await db_get(def_uid)
        att_name = fname(att_f) if att_f else "?"
        def_name = fname(def_f) if def_f else "?"
        mode_name = SKIRMISH_MODE_NAMES.get(mode, mode)
        instructions = SKIRMISH_MODE_INSTRUCTIONS.get(mode, "")

        for uid_d, role_d, opp_name in (
            (att_uid, "att", def_name),
            (def_uid, "def", att_name),
        ):
            text = (
                f"Бой {i + 1}/{total}: против тебя <b>{he(opp_name)}</b>\n"
                f"Режим: {mode_name}\n\n"
                f"{instructions}\n\n"
                f"/s — чат со своей стаей"
            )
            kb = _skirmish_duel_keyboard(mode, duel_id, role_d)
            try:
                await bot.send_message(uid_d, text, parse_mode=ParseMode.HTML, reply_markup=kb)
            except (BadRequest, Forbidden, TimedOut):
                pass

        asyncio.create_task(
            _skirmish_duel_timeout(bot, sk_id, duel_id, now + SKIRMISH_ROUND_SEC)
        )


async def skirmish_get_active_duel(skirmish_id: int) -> dict | None:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM skirmish_duels WHERE skirmish_id=? AND status='waiting' ORDER BY id LIMIT 1",
            (skirmish_id,),
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def skirmish_cooldown_left(staya_a: int, staya_b: int) -> float:
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT MAX(started_at) FROM staya_skirmishes"
            " WHERE (attacker_staya=? AND defender_staya=?)"
            "    OR (attacker_staya=? AND defender_staya=?)",
            (staya_a, staya_b, staya_b, staya_a),
        ) as c:
            row = await c.fetchone()
    last = (row[0] or 0.0) if row else 0.0
    return max(0.0, SKIRMISH_COOLDOWN - (now - last))


