def skirmish_random_mode() -> str:
    return random.choice(SKIRMISH_MODES)


async def skirmish_get_user_active_duel(uid: int) -> dict | None:
    """Возвращает активную дуэль игрока (статус waiting) если есть."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM skirmish_duels WHERE status='waiting' AND (att_uid=? OR def_uid=?)",
            (uid, uid),
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None



def rps_resolve(att_choice: str, def_choice: str) -> str:
    """Возвращает 'attacker', 'defender' или 'draw'."""
    if att_choice == def_choice:
        return "draw"
    if _RPS_BEATS.get(att_choice) == def_choice:
        return "attacker"
    return "defender"


def _skirmish_duel_keyboard(mode: str, duel_id: int, role: str):
    """Строит клавиатуру для дуэли в зависимости от режима."""
    flee_row = [btn("🏃 Сбежать", callback_data=f"skd_flee_{duel_id}_{role}", style="danger")]
    if mode == "rps":
        return InlineKeyboardMarkup([[
            btn("🪨 Камень",   callback_data=f"skd_choice_{duel_id}_{role}_rock"),
            btn("✂️ Ножницы", callback_data=f"skd_choice_{duel_id}_{role}_scissors"),
            btn("📄 Бумага",  callback_data=f"skd_choice_{duel_id}_{role}_paper"),
        ], flee_row])
    elif mode == "dice":
        # Кубик бросают через эмодзи 🎲, кнопок для выбора нет
        return InlineKeyboardMarkup([flee_row])
    elif mode == "evenodd":
        # Сначала выбор числа 1–10
        return InlineKeyboardMarkup([
            [btn(str(n), callback_data=f"skd_eo_num_{duel_id}_{role}_{n}") for n in range(1, 6)],
            [btn(str(n), callback_data=f"skd_eo_num_{duel_id}_{role}_{n}") for n in range(6, 11)],
            flee_row,
        ])
    return InlineKeyboardMarkup([flee_row])




async def skirmish_resolve_duel(bot, skirmish_id: int, duel: dict, winner: str):
    """Завершить одну дуэль, обновить счёт, показать статус-борд ждущим."""
    sk = await skirmish_get(skirmish_id)
    if not sk:
        return

    att_f = await db_get(duel["att_uid"])
    def_f = await db_get(duel["def_uid"])
    att_name = fname(att_f) if att_f else "?"
    def_name = fname(def_f) if def_f else "?"
    winner_uid = duel["att_uid"] if winner == "attacker" else duel["def_uid"]
    loser_uid  = duel["def_uid"] if winner == "attacker" else duel["att_uid"]
    winner_name = att_name if winner == "attacker" else def_name

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET winner=?, status='finished' WHERE id=?",
            (winner, duel["id"]),
        )
        await db.execute(
            "UPDATE skirmish_members SET duels_won=duels_won+1 WHERE skirmish_id=? AND user_id=?",
            (skirmish_id, winner_uid),
        )
        await db.execute(
            "UPDATE skirmish_members SET duels_lost=duels_lost+1, hp_left=? WHERE skirmish_id=? AND user_id=?",
            (duel["def_hp"] if winner == "attacker" else duel["att_hp"], skirmish_id, loser_uid),
        )
        col = "att_wins" if winner == "attacker" else "def_wins"
        await db.execute(f"UPDATE staya_skirmishes SET {col}={col}+1 WHERE id=?", (skirmish_id,))
        await db.commit()

    result_text = (
        f"<b>{he(att_name)}</b> против <b>{he(def_name)}</b>\n"
        f"Сильнее оказался: <b>{he(winner_name)}</b>"
    )
    # Результат — всем участникам стычки (они параллельно в своих дуэлях)
    await skirmish_broadcast(bot, skirmish_id, result_text)

    # Статус-борд — только тем, чья дуэль уже закончилась (att_uid / def_uid этой дуэли)
    await asyncio.sleep(1)
    status_text = await _skirmish_status_text(skirmish_id)
    for uid_d in (duel["att_uid"], duel["def_uid"]):
        try:
            await bot.send_message(uid_d, status_text, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass

    await _skirmish_check_all_done(bot, skirmish_id)





async def _skirmish_duel_timeout(bot, skirmish_id: int, duel_id: int, deadline: float):
    await asyncio.sleep(max(0, deadline - time.time()))
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM skirmish_duels WHERE id=? AND status='waiting'", (duel_id,)
        ) as c:
            duel = await c.fetchone()
    if not duel:
        return  # уже завершена
    duel = dict(duel)
    mode = duel.get("mode", "rps")

    if mode == "dice":
        att_c = duel["att_choice"] or str(random.randint(1, 6))
        def_c = duel["def_choice"] or str(random.randint(1, 6))
        # Уведомляем тех, кто не успел
        for uid_d, col in ((duel["att_uid"], "att_choice"), (duel["def_uid"], "def_choice")):
            if not duel[col]:
                try:
                    await bot.send_message(uid_d, "⏳ Время вышло — кубик брошен автоматически! ⚠️ AFK")
                except (BadRequest, Forbidden, TimedOut):
                    pass
        await _skirmish_duel_resolve_dice(bot, skirmish_id, duel, int(att_c), int(def_c))

    elif mode == "evenodd":
        # Подставляем случайные значения за тех кто не ответил
        att_num = duel.get("att_number") or random.randint(1, 10)
        def_num = duel.get("def_number") or random.randint(1, 10)
        att_c = duel["att_choice"] or random.choice(["even", "odd"])
        def_c = duel["def_choice"] or random.choice(["even", "odd"])
        for uid_d, num_col, ch_col in (
            (duel["att_uid"], "att_number", "att_choice"),
            (duel["def_uid"], "def_number", "def_choice"),
        ):
            if not duel[ch_col] or not duel.get(num_col):
                try:
                    await bot.send_message(uid_d, "⏳ Время вышло — выбор сделан автоматически! ⚠️ AFK")
                except (BadRequest, Forbidden, TimedOut):
                    pass
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE skirmish_duels SET att_number=?, def_number=? WHERE id=?",
                (att_num, def_num, duel_id),
            )
            await db.commit()
        duel["att_number"] = att_num
        duel["def_number"] = def_num
        await _skirmish_duel_resolve_choices(bot, skirmish_id, duel, att_c, def_c)

    else:  # rps
        att_c = duel["att_choice"] or random.choice(["rock", "scissors", "paper"])
        def_c = duel["def_choice"] or random.choice(["rock", "scissors", "paper"])
        for uid_d, col in ((duel["att_uid"], "att_choice"), (duel["def_uid"], "def_choice")):
            if not duel[col]:
                try:
                    await bot.send_message(uid_d, "⏳ Время вышло — выбор сделан автоматически! ⚠️ AFK")
                except (BadRequest, Forbidden, TimedOut):
                    pass
        await _skirmish_duel_resolve_choices(bot, skirmish_id, duel, att_c, def_c)


async def _skirmish_duel_resolve_choices(bot, skirmish_id: int, duel: dict,
                                          att_choice: str, def_choice: str):
    """Применить выборы обоих игроков к дуэли (режим rps или evenodd)."""
    mode = duel.get("mode", "rps")

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET att_choice=?, def_choice=? WHERE id=?",
            (att_choice, def_choice, duel["id"]),
        )
        await db.commit()

    att_hp = duel["att_hp"]
    def_hp = duel["def_hp"]
    round_num = duel["round_num"]

    att_f = await db_get(duel["att_uid"])
    def_f = await db_get(duel["def_uid"])
    att_name = fname(att_f) if att_f else "?"
    def_name = fname(def_f) if def_f else "?"

    if mode == "rps":
        result = rps_resolve(att_choice, def_choice)
        if result == "draw":
            att_hp -= 1
            def_hp -= 1
            round_result = "⚖️ Ничья! Оба теряют 1 HP."
        elif result == "attacker":
            def_hp -= 4
            round_result = (
                f"{_RPS_EMOJI[att_choice]} <b>{_RPS_NAME[att_choice]}</b> бьёт "
                f"{_RPS_EMOJI[def_choice]} {_RPS_NAME[def_choice]}! Защитник −4 HP."
            )
        else:
            att_hp -= 4
            round_result = (
                f"{_RPS_EMOJI[def_choice]} <b>{_RPS_NAME[def_choice]}</b> бьёт "
                f"{_RPS_EMOJI[att_choice]} {_RPS_NAME[att_choice]}! Атакующий −4 HP."
            )

    elif mode == "evenodd":
        # att_choice = "even"/"odd", def_choice = "even"/"odd"
        # att_number / def_number уже записаны в БД
        att_num = duel.get("att_number", 0)
        def_num = duel.get("def_number", 0)
        total = att_num + def_num
        actual = "even" if total % 2 == 0 else "odd"
        parity_ru = "Чёт" if actual == "even" else "Нечет"
        att_correct = (att_choice == actual)
        def_correct = (def_choice == actual)
        att_choice_ru = "Чёт" if att_choice == "even" else "Нечет"
        def_choice_ru = "Чёт" if def_choice == "even" else "Нечет"
        detail = (
            f"Числа: {att_name} загадал <b>{att_num}</b>, {def_name} загадал <b>{def_num}</b>\n"
            f"Сумма: {att_num}+{def_num}={total} → <b>{parity_ru}</b>\n"
            f"{he(att_name)}: {att_choice_ru} {_E_CHECK if att_correct else _E_CROSS}\n"
            f"{he(def_name)}: {def_choice_ru} {_E_CHECK if def_correct else _E_CROSS}"
        )
        if att_correct and not def_correct:
            result = "attacker"; def_hp -= 4
            round_result = f"{_E_TROPHY} {he(att_name)} угадал! Защитник −4 HP.\n{detail}"
        elif def_correct and not att_correct:
            result = "defender"; att_hp -= 4
            round_result = f"{_E_TROPHY} {he(def_name)} угадал! Атакующий −4 HP.\n{detail}"
        else:
            result = "draw"; att_hp -= 1; def_hp -= 1
            round_result = f"⚖️ Оба {'угадали' if att_correct else 'промахнулись'}! Оба теряют 1 HP.\n{detail}"

    else:
        result = "draw"
        round_result = "⚖️ Ничья."

    att_hp = max(0, att_hp)
    def_hp = max(0, def_hp)

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET att_hp=?, def_hp=?, round_num=round_num+1 WHERE id=?",
            (att_hp, def_hp, duel["id"]),
        )
        await db.commit()

    summary = (
        f"Раунд {round_num}\n"
        f"{round_result}\n"
        f"{he(att_name)}: <b>{att_hp} HP</b> · {he(def_name)}: <b>{def_hp} HP</b>"
    )
    for uid_d in (duel["att_uid"], duel["def_uid"]):
        try:
            await bot.send_message(uid_d, summary, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass

    if att_hp <= 0 or def_hp <= 0 or round_num >= 3:
        if att_hp > def_hp:
            winner = "attacker"
        elif def_hp > att_hp:
            winner = "defender"
        else:
            winner = "attacker" if result != "draw" else random.choice(["attacker", "defender"])
        duel_upd = dict(duel)
        duel_upd["att_hp"] = att_hp
        duel_upd["def_hp"] = def_hp
        await skirmish_resolve_duel(bot, skirmish_id, duel_upd, winner)
    else:
        await asyncio.sleep(2)
        # Сбрасываем выборы для следующего раунда
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE skirmish_duels SET att_choice='', def_choice='', "
                "att_number=0, def_number=0, status='waiting' WHERE id=?",
                (duel["id"],),
            )
            await db.commit()
        duel_next = dict(duel)
        duel_next["att_hp"] = att_hp
        duel_next["def_hp"] = def_hp
        duel_next["round_num"] = round_num + 1
        duel_next["att_choice"] = ""
        duel_next["def_choice"] = ""
        duel_next["att_number"] = 0
        duel_next["def_number"] = 0
        next_text = (
            f"Раунд {round_num + 1}/3 — {he(att_name)}: <b>{att_hp} HP</b> | {he(def_name)}: <b>{def_hp} HP</b>"
        )
        for uid_d, role_d in ((duel["att_uid"], "att"), (duel["def_uid"], "def")):
            kb = _skirmish_duel_keyboard(mode, duel["id"], role_d)
            try:
                await bot.send_message(uid_d, next_text, parse_mode=ParseMode.HTML, reply_markup=kb)
            except (BadRequest, Forbidden, TimedOut):
                pass


async def _skirmish_duel_resolve_dice(bot, skirmish_id: int, duel: dict,
                                       att_val: int, def_val: int):
    """Разрешить дуэль в режиме кубика."""
    att_f = await db_get(duel["att_uid"])
    def_f = await db_get(duel["def_uid"])
    att_name = fname(att_f) if att_f else "?"
    def_name = fname(def_f) if def_f else "?"
    round_num = duel["round_num"]

    att_hp = duel["att_hp"]
    def_hp = duel["def_hp"]

    if att_val > def_val:
        result = "attacker"; def_hp -= 4
        round_result = f"🎲 {he(att_name)}: <b>{att_val}</b> > {he(def_name)}: <b>{def_val}</b>\nАтакующий побеждает! Защитник −4 HP."
    elif def_val > att_val:
        result = "defender"; att_hp -= 4
        round_result = f"🎲 {he(def_name)}: <b>{def_val}</b> > {he(att_name)}: <b>{att_val}</b>\nЗащитник побеждает! Атакующий −4 HP."
    else:
        result = "draw"; att_hp -= 1; def_hp -= 1
        round_result = f"🎲 Ничья! Оба выбросили <b>{att_val}</b>. Оба теряют 1 HP. Кидайте ещё раз!"

    att_hp = max(0, att_hp)
    def_hp = max(0, def_hp)

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE skirmish_duels SET att_hp=?, def_hp=?, att_choice=?, def_choice=?, round_num=round_num+1 WHERE id=?",
            (att_hp, def_hp, str(att_val), str(def_val), duel["id"]),
        )
        await db.commit()

    summary = (
        f"Раунд {round_num}\n"
        f"{round_result}\n"
        f"{he(att_name)}: <b>{att_hp} HP</b> · {he(def_name)}: <b>{def_hp} HP</b>"
    )
    for uid_d in (duel["att_uid"], duel["def_uid"]):
        try:
            await bot.send_message(uid_d, summary, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass

    if result == "draw":
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE skirmish_duels SET att_choice='', def_choice='', status='waiting' WHERE id=?",
                (duel["id"],),
            )
            await db.commit()
        retry_text = (
            f"Ничья! Кидайте кубики ещё раз. "
            f"{he(att_name)}: <b>{att_hp} HP</b> | {he(def_name)}: <b>{def_hp} HP</b>"
        )
        for uid_d, role_d in ((duel["att_uid"], "att"), (duel["def_uid"], "def")):
            kb = _skirmish_duel_keyboard("dice", duel["id"], role_d)
            try:
                await bot.send_message(uid_d, retry_text, parse_mode=ParseMode.HTML, reply_markup=kb)
            except (BadRequest, Forbidden, TimedOut):
                pass
        return

    if att_hp <= 0 or def_hp <= 0 or round_num >= 3:
        if att_hp > def_hp:
            winner = "attacker"
        elif def_hp > att_hp:
            winner = "defender"
        else:
            winner = random.choice(["attacker", "defender"])
        duel_upd = dict(duel); duel_upd["att_hp"] = att_hp; duel_upd["def_hp"] = def_hp
        await skirmish_resolve_duel(bot, skirmish_id, duel_upd, winner)
    else:
        await asyncio.sleep(2)
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE skirmish_duels SET att_choice='', def_choice='', status='waiting' WHERE id=?",
                (duel["id"],),
            )
            await db.commit()
        next_text = (
            f"Раунд {round_num + 1}/3 — {he(att_name)}: <b>{att_hp} HP</b> | {he(def_name)}: <b>{def_hp} HP</b>"
        )
        for uid_d, role_d in ((duel["att_uid"], "att"), (duel["def_uid"], "def")):
            kb = _skirmish_duel_keyboard("dice", duel["id"], role_d)
            try:
                await bot.send_message(uid_d, next_text, parse_mode=ParseMode.HTML, reply_markup=kb)
            except (BadRequest, Forbidden, TimedOut):
                pass


async def skirmish_finish(bot, skirmish_id: int):
    """Подвести итоги стычки."""
    sk = await skirmish_get(skirmish_id)
    if not sk or sk["status"] == "finished":
        return

    att_wins = sk["att_wins"]
    def_wins = sk["def_wins"]

    # Тай-брейк по суммарному HP
    members = await skirmish_get_members(skirmish_id)
    att_hp_sum = sum(m.get("hp_left", 0) for m in members if m["side"] == "attacker")
    def_hp_sum = sum(m.get("hp_left", 0) for m in members if m["side"] == "defender")

    if att_wins > def_wins or (att_wins == def_wins and att_hp_sum >= def_hp_sum):
        winner_side = "attacker"
    else:
        winner_side = "defender"

    att_staya = await staya_get(sk["attacker_staya"])
    def_staya = await staya_get(sk["defender_staya"])

    cauldron_taken = 0
    if winner_side == "attacker" and def_staya:
        steal = int(def_staya["cauldron"] * SKIRMISH_WIN_PCT)
        steal = min(steal, SKIRMISH_WIN_MAX)
        cauldron_taken = steal
        # Переводим монеты
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE stayas SET cauldron=MAX(0, cauldron-?) WHERE id=?",
                (steal, sk["defender_staya"]),
            )
            await db.execute(
                "UPDATE stayas SET cauldron=cauldron+? WHERE id=?",
                (steal, sk["attacker_staya"]),
            )
            await db.commit()
    elif winner_side == "defender" and att_staya:
        # Защитник получает компенсацию из ставки
        compensation = 1000
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE stayas SET cauldron=MAX(0, cauldron-?) WHERE id=?",
                (compensation, sk["attacker_staya"]),
            )
            await db.execute(
                "UPDATE stayas SET cauldron=cauldron+? WHERE id=?",
                (compensation, sk["defender_staya"]),
            )
            await db.commit()

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE staya_skirmishes SET status='finished', winner=?, cauldron_taken=?, finished_at=? WHERE id=?",
            (winner_side, cauldron_taken, time.time(), skirmish_id),
        )
        await db.commit()

    # XP участникам
    for m in members:
        mf = await db_get(m["user_id"])
        if mf:
            xp_gain = 150 if (m["side"] == winner_side) else 100
            add_xp(mf, xp_gain)
            # Штрафы на параметры
            mf["hunger"]    = max(0, mf.get("hunger", 50) - 15)
            mf["energy"]    = max(0, mf.get("energy", 70) - 20)
            mf["cleanliness"] = max(0, mf.get("cleanliness", 70) - 10)
            if m["side"] != winner_side:
                mf["happiness"] = max(0, mf.get("happiness", 70) - 5)
            await db_save(mf)

    att_name = att_staya["name"] if att_staya else "?"
    def_name = def_staya["name"] if def_staya else "?"
    winner_name = att_name if winner_side == "attacker" else def_name
    loser_name  = def_name if winner_side == "attacker" else att_name

    result_text = (
        f"{_E_SWORDS} <b>Стычка окончена</b>\n"
        f"Верх взяли: <b>{he(winner_name)}</b>\n"
        f"Счёт: <b>{att_wins} : {def_wins}</b>"
        + (f"\nИз котла унесли: <b>{cauldron_taken}</b>{_E_COIN}" if cauldron_taken else "") +
        f"\n\nXP получили все."
    )
    await skirmish_broadcast(bot, skirmish_id, result_text)


# ── DB-хелперы дружбы ─────────────────────────────────────────────────────────



async def friend_list(uid: int, accepted_only: bool = True) -> list[dict]:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cond = "AND pending=0" if accepted_only else ""
        async with db.execute(
            f"SELECT f2.*, fr.level as fr_level, fr.pending "
            f"FROM friendships fr JOIN frogs f2 ON f2.user_id=fr.friend_id "
            f"WHERE fr.user_id=? {cond}",
            (uid,),
        ) as c:
            rows = await c.fetchall()
    return [dict(r) for r in rows]


async def friend_add_xp(uid: int, fid: int, xp: int):
    """Добавляет XP дружбе и при достижении порога повышает уровень."""
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT level, xp FROM friendships WHERE user_id=? AND friend_id=?",
            (uid, fid),
        ) as c:
            row = await c.fetchone()
        if not row:
            return
        cur_lvl, cur_xp = row
        new_xp = cur_xp + xp
        new_lvl = cur_lvl
        while new_lvl < 3 and new_xp >= FRIEND_LEVEL_XP[new_lvl + 1]:
            new_lvl += 1
        await db.execute(
            "UPDATE friendships SET xp=?, level=? WHERE user_id=? AND friend_id=?",
            (new_xp, new_lvl, uid, fid),
        )
        await db.commit()
    return new_lvl > cur_lvl, new_lvl  # (повысился?, новый уровень)


# ── DB-хелперы летописи ───────────────────────────────────────────────────────

async def letopis_add(uid: int, event_type: str, text: str):
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT INTO letopis(user_id, event_type, text, created_at) VALUES(?,?,?,?)",
            (uid, event_type, text, time.time()),
        )
        # Держим не больше 500 записей
        await db.execute(
            "DELETE FROM letopis WHERE id NOT IN "
            "(SELECT id FROM letopis ORDER BY created_at DESC LIMIT 500)"
        )
        await db.commit()


async def letopis_recent(limit: int = 20) -> list[dict]:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT l.*, f.frog_name, f.first_name, f.username, "
            "(SELECT COUNT(*) FROM letopis_likes WHERE letopis_id=l.id) as like_count "
            "FROM letopis l JOIN frogs f ON f.user_id=l.user_id "
            "ORDER BY l.created_at DESC LIMIT ?",
            (limit,),
        ) as c:
            rows = await c.fetchall()
    return [dict(r) for r in rows]


