# ── DB-хелперы приключений ────────────────────────────────────────────────────

async def adv_get(adv_id: int) -> dict | None:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM adventures WHERE id=?", (adv_id,)) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def adv_get_active(uid: int) -> dict | None:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM adventures WHERE (user1_id=? OR user2_id=?) AND finished=0",
            (uid, uid),
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def adv_add_log(adv_id: int, text: str):
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT log_json FROM adventures WHERE id=?", (adv_id,)) as c:
            row = await c.fetchone()
        if not row:
            return
        logs = json.loads(row[0] or "[]")
        logs.append({"t": int(time.time()), "text": text})
        if len(logs) > 50:
            logs = logs[-50:]
        await db.execute(
            "UPDATE adventures SET log_json=?, last_log_at=? WHERE id=?",
            (json.dumps(logs, ensure_ascii=False), time.time(), adv_id),
        )
        await db.commit()


