def _get_feed_text(frog: dict) -> str:
    name = fname(frog)
    hunger = frog.get("hunger", 50)
    happiness = frog.get("happiness", 50)
    if hunger < 30:       pool = FEED_TEXTS["hungry"]
    elif hunger > 70:     pool = FEED_TEXTS["full"]
    elif happiness > 80:  pool = FEED_TEXTS["happy"]
    elif happiness < 30:  pool = FEED_TEXTS["sad"]
    else:                 pool = FEED_TEXTS["normal"]
    return random.choice(pool).format(name=name)

