def _get_epitaph(frog: dict) -> str:
    name   = fname(frog)
    reason = frog.get("death_reason", "default")
    pool   = DEATH_EPITAPHS.get(reason, DEATH_EPITAPHS["default"])
    return random.choice(pool).format(name=name)

