async def send_random_interactive_event(frog: dict, bot) -> bool:
    """Отправляет случайное интерактивное событие лягушке. Возвращает True если отправлено."""
    if time.time() - frog.get("last_interactive_event", 0) < INTERACTIVE_EVENT_COOLDOWN:
        return False
    event = random.choice(INTERACTIVE_EVENTS)
    text, markup = build_interactive_event_message(frog, event)
    try:
        await bot.send_message(frog["user_id"], text, parse_mode=ParseMode.HTML, reply_markup=markup)
        return True
    except (Forbidden, BadRequest):
        return False
    except Exception as _e:
        logger.warning("send_random_interactive_event uid=%s: %s", frog["user_id"], _e)
        return False

