async def _build_diary(uid: int, f: dict) -> str:
    """
    Строит дневник за последние 7 дней на основе статистики и временных меток.
    """
    name = fname(f)
    now  = time.time()
    days_alive = int((now - f.get("born_at", now)) / 86400)

    # Собираем факты о лягушке
    facts = []

    # Работа
    last_report = f.get("last_worker_report", 0)
    if last_report and now - last_report < 7 * 86400:
        phase = f.get("worker_phase", 0)
        scene_raw = f.get("worker_scene_json", "")
        if scene_raw:
            try:
                scene = json.loads(scene_raw)
                prof = scene.get("prof_name", "на болотном рынке")
                facts.append(f"{_E_STORE} Работала как <i>{prof}</i> и {random.choice(_DIARY_WORK_PHRASES)}")
            except Exception:
                facts.append(f"{_E_STORE} {random.choice(_DIARY_WORK_PHRASES).capitalize()}")
        else:
            facts.append(f"{_E_STORE} {random.choice(_DIARY_WORK_PHRASES).capitalize()}")

    # Активность за 7 дней
    feeds_7  = f.get("total_feeds",     0)
    plays_7  = f.get("total_plays",     0)
    washes_7 = f.get("total_washes",    0)
    sleeps_7 = f.get("total_sleeps",    0)
    casino_7 = f.get("total_casino",    0)
    duels_7  = f.get("total_duel_wins", 0)

    if f.get("last_feed", 0) and now - f.get("last_feed", 0) < 7 * 86400:
        facts.append(f"🍎 {random.choice(_DIARY_FEED_PHRASES).capitalize()} (всего кормёжек: {feeds_7})")
    if f.get("last_play", 0) and now - f.get("last_play", 0) < 7 * 86400:
        facts.append(f"{_E_GAMES} {random.choice(_DIARY_PLAY_PHRASES).capitalize()}")
    if f.get("last_wash", 0) and now - f.get("last_wash", 0) < 7 * 86400:
        facts.append(f"🛁 {random.choice(_DIARY_WASH_PHRASES).capitalize()}")
    if f.get("last_sleep", 0) and now - f.get("last_sleep", 0) < 7 * 86400:
        facts.append(f"😴 {random.choice(_DIARY_SLEEP_PHRASES).capitalize()}")
    if f.get("last_event", 0) and now - f.get("last_event", 0) < 7 * 86400:
        facts.append(f"{_E_DICE} {random.choice(_DIARY_EVENT_PHRASES).capitalize()}")
    if f.get("last_casino", 0) and now - f.get("last_casino", 0) < 7 * 86400:
        facts.append(f"{_E_CASINO} {random.choice(_DIARY_CASINO_PHRASES).capitalize()}")
    if duels_7 > 0:
        facts.append(f"{_E_SWORDS} {random.choice(_DIARY_DUEL_PHRASES).capitalize()} ({duels_7} побед)")

    # Текущее состояние
    mood = "в хорошем настроении 😄" if f.get("happiness", 50) > 70 \
        else "немного грустит 😔" if f.get("happiness", 50) < 30 \
        else "в обычном настроении 😐"

    health_note = ""
    if f.get("health", 100) < 40:
        health_note = " Здоровье на исходе — надо лечиться!"
    elif f.get("health", 100) >= 90:
        health_note = " Здоровье отличное!"

    # Streak
    streak = f.get("streak", 0)
    streak_note = ""
    if streak >= 7:
        streak_note = f"\n🔥 Стрик: <b>{streak} дней</b> подряд!"

    if not facts:
        facts = ["💤 Провела тихую неделю. Отдыхала и копила силы."]

    random.shuffle(facts)
    facts_text = "\n".join(f"• {fact}" for fact in facts[:6])  # максимум 6 фактов

    personality = f.get("personality", "")
    pers_line = ""
    if personality and personality in PERSONALITIES:
        p = PERSONALITIES[personality]
        pers_line = f"\n{p['emoji']} Характер: <b>{p['name']}</b>"

    zodiac = _get_zodiac(f.get("born_at", now))
    zodiac_line = f"\n{zodiac['name']} по знаку болотного зодиака"

    return (
        f"📖 <b>Дневник {name}</b>\n"
        f"<i>{days_alive} дней на болоте</i>{pers_line}{zodiac_line}\n"
        f"{streak_note}\n"
        f"<b>Последние дни:</b>\n"
        f"{facts_text}\n\n"
        f"<b>Сейчас:</b> {mood}{health_note}"
    )


