async def db_remove_skin(uid: int, skin: str):
    """Уменьшить количество облика на 1. Если qty=0 — удалить запись."""
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT qty FROM collections WHERE user_id=? AND skin=?", (uid, skin)
        ) as c:
            row = await c.fetchone()
        if not row:
            return
        if row[0] is None or row[0] <= 1:
            await db.execute(
                "DELETE FROM collections WHERE user_id=? AND skin=?", (uid, skin)
            )
        else:
            await db.execute(
                "UPDATE collections SET qty = qty - 1 WHERE user_id=? AND skin=?",
                (uid, skin),
            )
        await db.commit()


