async def db_get_rank_league(user_id: int, league_id: int) -> tuple[int, int]:
    """Позиция игрока внутри своей лиги + общее кол-во в лиге."""
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(*)+1 FROM frogs "
            "WHERE league=? AND is_bot=0 AND banned=0 AND xp_week > "
            "(SELECT xp_week FROM frogs WHERE user_id=?)",
            (league_id, user_id),
        ) as c:
            rank = (await c.fetchone())[0]
        async with db.execute(
            "SELECT COUNT(*) FROM frogs WHERE league=? AND is_bot=0 AND banned=0",
            (league_id,),
        ) as c:
            total = (await c.fetchone())[0]
    return rank, total

async def db_get_rank_global(user_id: int) -> tuple:
    """Возвращает (rank, total) пользователя в глобальном топе по уровню/xp."""
    loop = asyncio.get_event_loop()
    def _read():
        conn = _db_pool.acquire()
        try:
            row = conn.execute(
                "SELECT COUNT(*)+1 FROM frogs "
                "WHERE is_bot=0 AND banned=0 AND (level > (SELECT level FROM frogs WHERE user_id=?) "
                "OR (level = (SELECT level FROM frogs WHERE user_id=?) AND xp > (SELECT xp FROM frogs WHERE user_id=?)))",
                (user_id, user_id, user_id)
            ).fetchone()
            total = conn.execute("SELECT COUNT(*) FROM frogs WHERE is_bot=0 AND banned=0").fetchone()[0]
            return (row[0] if row else 0, total)
        finally:
            _db_pool.release(conn)
    return await loop.run_in_executor(None, _read)

async def db_get_rank_weekly(user_id: int) -> tuple:
    """Возвращает (rank, total) пользователя в недельном топе."""
