_settings_cache: dict[str, tuple[str, float]] = {}
_settings_cache_ttl = 30  # секунд

# ── Пиковый онлайн ──────────────────────────────────────────────────────────
# Хранится в памяти, периодически сохраняется в settings таблицу.
# Структура: {"day": (count, ts), "week": (count, ts), "month": (count, ts)}
_peak_online: dict[str, tuple[int, float]] = {
    "day":   (0, 0.0),
    "week":  (0, 0.0),
    "month": (0, 0.0),
}
_peak_last_save = 0.0   # когда последний раз сохраняли в БД
_PEAK_SAVE_INTERVAL = 60  # раз в минуту


def _update_peak_online(current_count: int):
    """Обновляет пиковый онлайн в памяти. Вызывать при каждом подсчёте онлайна."""
    global _peak_online
    now = time.time()
    day_start  = now - 86400
    week_start = now - 7 * 86400
    month_start = now - 30 * 86400

    new_peak = {}
    for period, start in (("day", day_start), ("week", week_start), ("month", month_start)):
        old_count, old_ts = _peak_online[period]
        if old_ts < start:
            # Пик устарел — сбрасываем
            new_peak[period] = (current_count, now)
        elif current_count > old_count:
            new_peak[period] = (current_count, now)
        else:
            new_peak[period] = (old_count, old_ts)
    _peak_online = new_peak


async def _load_peak_online():
    """Загружает пиковый онлайн из БД при старте."""
    global _peak_online
    for period in ("day", "week", "month"):
        raw = await db_setting(f"peak_online_{period}")
        if raw:
            try:
                parts = raw.split(":")
                _peak_online[period] = (int(parts[0]), float(parts[1]))
            except Exception as _e:
                logger.exception("подавлено исключение: %s", _e)


async def _save_peak_online():
    """Сохраняет пиковый онлайн в БД."""
    global _peak_last_save
    _peak_last_save = time.time()
    for period, (count, ts) in _peak_online.items():
        await db_setting(f"peak_online_{period}", f"{count}:{ts}")

async def db_setting(key: str, val: str = None) -> str | None:
    global _settings_cache
    if val is not None:
        _settings_cache.pop(key, None)
        loop = asyncio.get_event_loop()
        def _write():
            conn = _db_pool.acquire()
            temporary = False
            try:
                conn.execute("INSERT OR REPLACE INTO settings VALUES(?,?)", (key, val))
                conn.commit()
            except Exception:
                temporary = True
                raise
            finally:
                _db_pool.release(conn, temporary=temporary)
        await loop.run_in_executor(None, _write)
        _settings_cache[key] = (val, time.time())
        return val
    cached = _settings_cache.get(key)
    if cached and (time.time() - cached[1]) < _settings_cache_ttl:
        return cached[0]
    loop = asyncio.get_event_loop()
    def _read():
        conn = _db_pool.acquire()
        temporary = False
        try:
            row = conn.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
            return row[0] if row else None
        except Exception:
            temporary = True
            raise
        finally:
            _db_pool.release(conn, temporary=temporary)
    result = await loop.run_in_executor(None, _read)
    if result is not None:
        _settings_cache[key] = (result, time.time())
    return result


