BOOST_DEFAULT_MULT = {"stars": 1.5, "legendary": 2.0, "mythic": 2.0}


async def boost_clear():
    """Деактивировать буст."""
    await db_setting("boost_active", "0")


async def boost_set(duration_hours: int, mult: dict = None):
    """Активировать буст на duration_hours часов."""
    if mult is None:
        mult = BOOST_DEFAULT_MULT
    end = time.time() + duration_hours * 3600
    await db_setting("boost_active", "1")
    await db_setting("boost_end", str(end))
    await db_setting("boost_mult", json.dumps(mult))


async def boost_is_active() -> bool:
    """True если буст активен и не истёк."""
    val = await db_setting("boost_active")
    if val != "1":
        return False
    end_str = await db_setting("boost_end")
    if end_str and time.time() > float(end_str):
        await boost_clear()
        return False
    return True


async def boost_get_mult() -> dict | None:
    """Вернуть словарь множителей или None если буста нет."""
    if not await boost_is_active():
        return None
    raw = await db_setting("boost_mult")
    if not raw:
        return BOOST_DEFAULT_MULT
    try:
        return json.loads(raw)
    except Exception:
        return BOOST_DEFAULT_MULT


async def boost_remaining_secs() -> float:
    """Секунды до конца буста (0 если не активен)."""
    end_str = await db_setting("boost_end")
    if not end_str:
        return 0
    return max(0.0, float(end_str) - time.time())


async def job_boost_check(ctx: ContextTypes.DEFAULT_TYPE):
    """Фоновая задача: проверяет окончание буста каждые 60 секунд."""
    val = await db_setting("boost_active")
    if val != "1":
        return
    end_str = await db_setting("boost_end")
    if not end_str:
        return
    if time.time() < float(end_str):
        # За час до конца — напоминание (отправляем ровно один раз)
        remaining = float(end_str) - time.time()
        reminded = await db_setting("boost_reminded")
        if 3540 <= remaining <= 3660 and reminded != "1":
            await db_setting("boost_reminded", "1")
            try:
                await ctx.bot.send_message(
                    CHAT_ID,
                    "⏰ <b>«Золотая лягушка» заканчивается через 1 час!</b>\n\n"
                    "🎰 Успей покрутить гачу — шансы на легенду повышены!\n"
                    "💫 Успей пополнить КваКоины — курс Stars выгоднее!",
                    parse_mode="HTML",
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
        return
    # Буст истёк
    await boost_clear()
    await db_setting("boost_reminded", "0")
    try:
        await ctx.bot.send_message(
            CHAT_ID,
            f"{_E_MOON} <b>Событие «Золотая лягушка» завершилось.</b>\n\n"
            f"Спасибо всем участникам! Курсы и шансы вернулись в норму. {_E_FROG}",
            parse_mode="HTML",
        )
    except (BadRequest, Forbidden, TimedOut):
        pass

async def inv_get(uid: int) -> dict:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT item_id,qty FROM shop_inventory WHERE user_id=? AND qty>0", (uid,)
        ) as c:
            return {r["item_id"]: r["qty"] for r in await c.fetchall()}


async def inv_add(uid: int, item_id: str, qty=1):
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT INTO shop_inventory(user_id,item_id,qty) VALUES(?,?,?) "
            "ON CONFLICT(user_id,item_id) DO UPDATE SET qty=qty+?",
            (uid, item_id, qty, qty),
        )
        await db.commit()


async def inv_use(uid: int, item_id: str) -> bool:
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT qty FROM shop_inventory WHERE user_id=? AND item_id=?",
            (uid, item_id),
        ) as c:
            r = await c.fetchone()
        if not r or r[0] < 1:
            return False
        await db.execute(
            "UPDATE shop_inventory SET qty=qty-1 WHERE user_id=? AND item_id=?",
            (uid, item_id),
        )
        await db.commit()
    return True


