def today_str() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d")


async def quest_get(uid: int) -> dict:
    today = today_str()
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM daily_quests WHERE user_id=? AND quest_date=?", (uid, today)
        ) as c:
            row = await c.fetchone()
        if row:
            return dict(row)
        ids = [q["id"] for q in random.sample(QUEST_POOL, 3)]
        prog = {qid: 0 for qid in ids}
        await db.execute(
            "INSERT INTO daily_quests(user_id,quest_date,quest_ids,progress,claimed) VALUES(?,?,?,?,?)",
            (uid, today, json.dumps(ids), json.dumps(prog), json.dumps([])),
        )
        await db.commit()
        async with db.execute(
            "SELECT * FROM daily_quests WHERE user_id=? AND quest_date=?", (uid, today)
        ) as c:
            return dict(await c.fetchone())


async def quest_update(uid: int, quest_type: str, amount=1):
    today = today_str()
    row = await quest_get(uid)
    ids = json.loads(row["quest_ids"] or "[]")
    prog = json.loads(row["progress"] or "{}")
    claimed = json.loads(row["claimed"] or "[]")
    changed = False
    for qid in ids:
        if qid in claimed:
            continue
        qd = next((q for q in QUEST_POOL if q["id"] == qid), None)
        if qd and qd["type"] == quest_type:
            old = prog.get(qid, 0)
            if old < qd["goal"]:
                prog[qid] = min(old + amount, qd["goal"])
                changed = True
    if changed:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE daily_quests SET progress=? WHERE user_id=? AND quest_date=?",
                (json.dumps(prog), uid, today),
            )
            await db.commit()


