async def ach_grant(uid: int, ach_id: str, bot=None) -> bool:
    """Устаревший интерфейс — оставлен для совместимости с другими вызовами."""
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT 1 FROM achievements WHERE user_id=? AND ach_id=?", (uid, ach_id)
        ) as c:
            if await c.fetchone():
                return False
        await db.execute(
            "INSERT INTO achievements VALUES(?,?,?)", (uid, ach_id, time.time())
        )
        await db.commit()
    if bot and ach_id in ACHIEVEMENTS:
        a = ACHIEVEMENTS[ach_id]
        try:
            await bot.send_message(
                uid,
                f"{_E_TROPHY} <b>Достижение!</b>\n\n{a['emoji']} <b>{a['name']}</b>\n<i>{a['desc']}</i>",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
    return True


async def ach_check(f: dict, bot=None):
    """
    Оптимизированная проверка достижений — 2 DB-запроса вместо 24.
    Было: каждый ach_grant открывал отдельное соединение (23 шт).
    Стало: один SELECT всех earned + один batch INSERT новых.
    """
    uid = f["user_id"]
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT skin FROM collections WHERE user_id=? AND qty > 0", (uid,)
        ) as c:
            coll = [r[0] for r in await c.fetchall()]
        async with db.execute(
            "SELECT ach_id FROM achievements WHERE user_id=?", (uid,)
        ) as c:
            already_earned = {r[0] for r in await c.fetchall()}
        # Рефералы и подарки живут в своих таблицах. Условия смотрели на поля
        # лягушки total_referrals и total_gifts_sent, которых в frogs нет и
        # никогда не было, — поэтому пять социальных достижений не выдавались.
        # Заводить дублирующие счётчики незачем, данные уже есть: считаем их.
        async with db.execute(
            "SELECT COUNT(*) FROM referrals WHERE referrer_id=?", (uid,)
        ) as c:
            referrals_cnt = (await c.fetchone())[0]
        async with db.execute(
            "SELECT COUNT(*) FROM gift_log WHERE from_id=?", (uid,)
        ) as c:
            gifts_sent_cnt = (await c.fetchone())[0]

        leg = sum(1 for s in coll if SKINS.get(s, {}).get("rarity") == "legendary")
        has_mythic = any(SKINS.get(s, {}).get("rarity") == "mythic" for s in coll)
        days_alive = int((time.time() - f.get("born_at", time.time())) / 86400)
        coins_spent = f.get("coins_spent", 0)
        total_heals  = f.get("total_heals",  0)
        total_crafts = f.get("total_crafts", 0)
        total_gacha  = f.get("total_gacha",  0)

        # full_care: все параметры одновременно 100
        is_full_care = (
            f.get("hunger", 0) >= 100 and f.get("happiness", 0) >= 100 and
            f.get("health", 0) >= 100 and f.get("cleanliness", 0) >= 100 and
            f.get("energy", 0) >= 100
        )
        # full_care_7: дни подряд с идеальным уходом. Стрик никто не считал —
        # условие смотрело на full_care_streak, которого в таблице не было.
        # Засчитываем не чаще раза в сутки; пропущенный день обнуляет счёт.
        # Пишем сразу и в базу: ach_check зовут уже ПОСЛЕ db_save, так что
        # правка одного словаря до диска бы не доехала.
        if is_full_care:
            today_num = int(time.time() // 86400)
            last_num  = f.get("full_care_day", 0)
            if last_num != today_num:
                f["full_care_streak"] = (f.get("full_care_streak", 0) + 1
                                         if last_num == today_num - 1 else 1)
                f["full_care_day"] = today_num
                await db.execute(
                    "UPDATE frogs SET full_care_streak=?, full_care_day=? WHERE user_id=?",
                    (f["full_care_streak"], today_num, uid),
                )
                await db.commit()                   # ниже коммит только если есть новые
                if f.get("_orig") is not None:      # снимок для db_save не должен разойтись
                    f["_orig"]["full_care_streak"] = f["full_care_streak"]
                    f["_orig"]["full_care_day"] = today_num
                # UPDATE идёт мимо db_save, а значит и мимо кэша на 60 секунд —
                # обновляем его вручную, иначе db_get вернёт старый стрик.
                _cached = _user_cache.get(uid)
                if _cached is not None:
                    _cached["full_care_streak"] = f["full_care_streak"]
                    _cached["full_care_day"] = today_num
                    _user_cache.set(uid, _cached)

        # all_care_master: все достижения по уходу открыты
        care_ach_ids = {aid for aid, a in ACHIEVEMENTS.items() if a.get("cat") == "care" and not a.get("secret")}
        all_care = care_ach_ids.issubset(already_earned)

        checks = [
            # Уход
            ("first_feed",    f["total_feeds"] >= 1),
            ("feeder_10",     f["total_feeds"] >= 10),
            ("feeder_100",    f["total_feeds"] >= 100),
            ("feeder_500",    f["total_feeds"] >= 500),
            ("feeder_1000",   f["total_feeds"] >= 1000),
            ("feeder_2500",   f["total_feeds"] >= 2500),
            ("washed_10",     f["total_washes"] >= 10),
            ("washed_50",     f["total_washes"] >= 50),
            ("washed_200",    f["total_washes"] >= 200),
            ("slept_10",      f["total_sleeps"] >= 10),
            ("slept_50",      f["total_sleeps"] >= 50),
            ("slept_200",     f["total_sleeps"] >= 200),
            ("healed_10",     total_heals >= 10),
            ("healed_50",     total_heals >= 50),
            ("healed_200",    total_heals >= 200),
            ("full_care",     is_full_care),
            ("full_care_7",   f.get("full_care_streak", 0) >= 7),
            # Игры
            ("player_10",     f["total_plays"] >= 10),
            ("player_50",     f["total_plays"] >= 50),
            ("player_200",    f["total_plays"] >= 200),
            ("player_500",    f["total_plays"] >= 500),
            ("duel_win_1",    f["total_duel_wins"] >= 1),
            ("duel_win_10",   f["total_duel_wins"] >= 10),
            ("duel_win_50",   f["total_duel_wins"] >= 50),
            ("duel_win_100",  f["total_duel_wins"] >= 100),
            ("casino_10",     f["total_casino"] >= 10),
            ("casino_50",     f["total_casino"] >= 50),
            ("casino_200",    f["total_casino"] >= 200),
            ("casino_win_5",  f.get("casino_win_streak", 0) >= 5),
            ("guess_win_5",   f.get("total_guess_wins", 0) >= 5),
            ("guess_win_20",  f.get("total_guess_wins", 0) >= 20),
            ("guess_win_50",  f.get("total_guess_wins", 0) >= 50),
            ("mosquito_5",    f.get("total_mosquitoes", 0) >= 5),
            ("mosquito_20",   f.get("total_mosquitoes", 0) >= 20),
            ("mosquito_50",   f.get("total_mosquitoes", 0) >= 50),
            ("ttt_win_5",     f.get("total_ttt_wins", 0) >= 5),
            ("ttt_win_20",    f.get("total_ttt_wins", 0) >= 20),
            ("hangman_10",    f.get("total_hangman_wins", 0) >= 10),
            ("battle_win_5",  f.get("total_battle_wins", 0) >= 5),
            # Экономика
            ("rich_500",      f["coins"] >= 500),
            ("rich_2000",     f["coins"] >= 2000),
            ("rich_10000",    f["coins"] >= 10000),
            ("rich_50000",    f["coins"] >= 50000),
            ("rich_200000",   f["coins"] >= 200000),
            ("spender_1000",  coins_spent >= 1000),
            ("spender_10000", coins_spent >= 10000),
            ("spender_50000", coins_spent >= 50000),
            ("social_10",     f["total_social"] >= 10),
            ("social_50",     f["total_social"] >= 50),
            ("social_200",    f["total_social"] >= 200),
            ("worker_30days", f.get("last_worker_report", 0) > 0 and f.get("total_worker_days", 0) >= 30),
            ("worker_100days",f.get("total_worker_days", 0) >= 100),
            # Коллекция
            ("collector_10",  len(coll) >= 10),
            ("collector_25",  len(coll) >= 25),
            ("collector_50",  len(coll) >= 50),
            ("collector_all", len(coll) >= len(SKINS)),
            ("legendary_3",   leg >= 3),
            ("legendary_10",  leg >= 10),
            ("mythic_owner",  has_mythic),
            ("gacha_10",      total_gacha >= 10),
            ("gacha_50",      total_gacha >= 50),
            ("gacha_200",     total_gacha >= 200),
            # Прогресс
            ("level_10",      f["level"] >= 10),
            ("level_25",      f["level"] >= 25),
            ("level_50",      f["level"] >= 50),
            ("level_100",     f["level"] >= 100),
            ("level_200",     f["level"] >= 200),
            ("streak_7",      f["streak"] >= 7),
            ("streak_30",     f["streak"] >= 30),
            ("streak_100",    f["streak"] >= 100),
            ("streak_365",    f["streak"] >= 365),
            ("days_30",       days_alive >= 30),
            ("days_180",      days_alive >= 180),
            ("days_365",      days_alive >= 365),
            ("days_730",      days_alive >= 730),
            ("revived",       f.get("total_revives", 0) >= 1),
            ("revived_5",     f.get("total_revives", 0) >= 5),
            # Стрик ежедневного бонуса лежит в streak. Поля daily_streak в
            # frogs нет — условие всегда было ложным.
            ("daily_30",      f["streak"] >= 30),
            # Социальные — считаются по таблицам referrals и gift_log
            ("first_referral",referrals_cnt >= 1),
            ("referral_5",    referrals_cnt >= 5),
            ("referral_20",   referrals_cnt >= 20),
            ("gift_sent_10",  gifts_sent_cnt >= 10),
            ("gift_sent_50",  gifts_sent_cnt >= 50),
            # Особые (частичные — остальные выдаются вручную через ach_grant)
            ("all_care_master",  care_ach_ids.issubset(already_earned)),
            ("all_games_master", {aid for aid, a in ACHIEVEMENTS.items() if a.get("cat") == "games" and not a.get("secret")}.issubset(already_earned)),
            ("half_collection",  len(already_earned) >= len(ACHIEVEMENTS) // 2),
            ("all_achiever",     {aid for aid, a in ACHIEVEMENTS.items() if not a.get("secret")}.issubset(already_earned)),
            # Коллекция — крафт
            ("crafter_10",  total_crafts >= 10),
            ("crafter_50",  total_crafts >= 50),
            # Особые — ивенты, легенда, работа, время суток
            ("iev_lucky",        f.get("total_iev_lucky",    0) >= 1),
            ("iev_lucky_5",      f.get("total_iev_lucky",    0) >= 5),
            ("legend_win",       f.get("total_legend_wins",  0) >= 1),
            ("legend_5wins",     f.get("total_legend_wins",  0) >= 5),
            ("worker_week",      f.get("worker_consec_days", 0) >= 7),
            ("worker_streak_30", f.get("worker_consec_days", 0) >= 30),
            ("night_owl",        f.get("night_visits",  0) >= 10),
            ("early_bird",       f.get("early_visits",  0) >= 10),
        ]
        now_ts = time.time()
        newly_earned = [
            aid for aid, cond in checks
            if cond and aid not in already_earned
        ]
        if newly_earned:
            await db.executemany(
                "INSERT OR IGNORE INTO achievements VALUES(?,?,?)",
                [(uid, aid, now_ts) for aid in newly_earned],
            )
            await db.commit()

    # Уведомления — вне транзакции, чтобы не держать соединение открытым
    if bot:
        for aid in newly_earned:
            if aid not in ACHIEVEMENTS:
                continue
            a = ACHIEVEMENTS[aid]
            # Фриз-ивент: free-кубик за идеальный уход
            if aid == "full_care":
                asyncio.create_task(_fz_free_cube(uid, "free_care", bot))
            try:
                await bot.send_message(
                    uid,
                    f"{_E_TROPHY} <b>Достижение!</b>\n\n{a['emoji']} <b>{a['name']}</b>\n<i>{a['desc']}</i>",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass


