# 🎮 ИГРОВАЯ ЛОГИКА
# ══════════════════════════════════════════
def xp_need(lvl: int) -> int:
    return int(50 * lvl**1.4)


def slink(skin: str, use_static=False, user_nft_url: str = "") -> str:
    """Ссылка на стикер с премиум-эмодзи (Markdown)."""
    s = SKINS.get(skin, {})
    # Используем user_nft_url только если он явно передан (NFT конкретного игрока).
    # Глобальный nft_url из SKINS НЕ используется — он может принадлежать другому игроку!
    # Для NFT-only обликов (KissedFrog #N) nft_url хранится в SKINS и user_nft_url будет передан явно.
    url = user_nft_url or ""
    if not url:
        sid = s.get("sid", 0)
        # Для обликов без sid (NFT-only) используем nft_url из SKINS — они уникальны для своего ключа
        if sid == 0 and s.get("nft_url"):
            url = s["nft_url"]
        else:
            sid = sid + STATIC_OFFSET if use_static else sid
            url = f"{STICKER_BASE}/{sid}"
    emoji = s.get("emoji", "🪸")
    return f"[{emoji} {skin}]({url})"


def slink_html(skin: str, use_static=False, user_nft_url: str = "") -> str:
    """HTML-версия ссылки на стикер: премиум-эмодзи + ссылка только на название."""
    s = SKINS.get(skin, {})
    premium_id = SKIN_PREMIUM_EMOJI.get(skin)
    # Используем user_nft_url только если он явно передан (NFT конкретного игрока).
    # Глобальный nft_url из SKINS НЕ используется — он может принадлежать другому игроку!
    url = user_nft_url or ""
    if not url:
        sid = s.get("sid", 0)
        # Для обликов без sid (NFT-only) используем nft_url из SKINS — они уникальны для своего ключа
        if sid == 0 and s.get("nft_url"):
            url = s["nft_url"]
        else:
            sid = sid + STATIC_OFFSET if use_static else sid
            url = f"{STICKER_BASE}/{sid}"
    if premium_id:
        emoji_tag = f'<tg-emoji emoji-id="{premium_id}">{s.get("emoji", "🪸")}</tg-emoji>'
    else:
        emoji_tag = s.get("emoji", "🪸")
    return f'{emoji_tag} <a href="{url}">{he(skin)}</a>'


def display_skin(skin: str, use_static: bool = False, user_nft_url: str = "") -> str:
    """HTML-представление облика с премиум-эмодзи и ссылкой на стикер."""
    return slink_html(skin, use_static, user_nft_url=user_nft_url)


def pemoji(skin: str) -> str:
    """Возвращает <tg-emoji> тег для облика (или обычный эмодзи как fallback)."""
    s = SKINS.get(skin, {})
    plain = s.get("emoji", "🐸")
    premium_id = SKIN_PREMIUM_EMOJI.get(skin)
    if premium_id:
        return f'<tg-emoji emoji-id="{premium_id}">{plain}</tg-emoji>'
    return plain


def coin_emoji() -> str:
    """Премиум-иконка КваКоина для HTML-текстов. Для кнопок — coin_plain()."""
    return _E_COIN


def coin_plain() -> str:
    """Всегда возвращает plain 🪙 — для кнопок и алертов, где HTML не работает."""
    return "🪙"


def coin_btn_kwargs() -> dict:
    """Устарело — оставлено для обратной совместимости. Возвращает пустой dict.
    icon_custom_emoji_id для кнопок теперь передаётся через btn(..., icon_id=...).
    """
    return {}


def coin_btn(text: str, callback_data: str, **extra) -> InlineKeyboardButton:
    """
    Кнопка с монетой. Иконку ставит btn(): ведущий 🪙 переезжает в поле
    icon_custom_emoji_id (Bot API 9.4). В самой подписи HTML не разбирается,
    поэтому <tg-emoji> туда вставлять по-прежнему нельзя.
    """
    return btn(text, callback_data=callback_data, **extra)


def skin_btn(label: str, skin: str, callback_data: str) -> InlineKeyboardButton:
    """
    Создаёт InlineKeyboardButton с иконкой облика через Bot API 9.4
    (icon_custom_emoji_id внутри объекта кнопки через _StyledButton.to_dict).

    Эмодзи и 👕 из текста убраны — иконка отображается отдельно слева от текста
    через icon_custom_emoji_id (Bot API 9.4, требует Premium у владельца бота).
    """
    premium_id = SKIN_PREMIUM_EMOJI.get(skin)
    if premium_id:
        return btn(label, callback_data=callback_data, icon_id=str(premium_id))
    return btn(label, callback_data=callback_data)


def nft_link(nft_url: str, number: str) -> str:
    return f"[🪸 KissedFrog #{number}]({nft_url})"


def roll(rarity_filter=None, boost_mult: dict | None = None) -> str:
    items = [
        (k, v)
        for k, v in SKINS.items()
        if (rarity_filter is None or v["rarity"] == rarity_filter)
        and v.get("chance", 0) > 0  # исключаем NFT с chance == 0
    ]
    if not items:
        items = [(k, v) for k, v in SKINS.items() if v.get("chance", 0) > 0]
    if boost_mult:
        weights = []
        for _, v in items:
            w = v["chance"]
            if v["rarity"] == "legendary":
                w *= boost_mult.get("legendary", 1.0)
            elif v["rarity"] == "mythic":
                w *= boost_mult.get("mythic", 1.0)
            weights.append(w)
    else:
        weights = [s["chance"] for _, s in items]
    return random.choices(items, weights=weights, k=1)[0][0]


PITY_THRESHOLD = 50  # при 50 крутках без легенды — гарантия


async def roll_pity(f: dict) -> tuple[str, bool]:
    """
    Крутит гачу с учётом питти и буста «Золотая лягушка».
    Возвращает (skin_name, pity_triggered).
    Обновляет f['gacha_pity'] на месте.
    """
    boost_mult = await boost_get_mult()
    pity = f.get("gacha_pity", 0)
    if pity >= PITY_THRESHOLD:
        # Гарантированная легенда
        legendary_items = [
            (k, v) for k, v in SKINS.items()
            if v["rarity"] == "legendary" and v.get("chance", 0) > 0
        ]
        if not legendary_items:
            legendary_items = [(k, v) for k, v in SKINS.items() if v["rarity"] == "legendary"]
        skin = random.choice(legendary_items)[0]
        f["gacha_pity"] = 0
        return skin, True
    skin = roll(boost_mult=boost_mult)
    s = SKINS[skin]
    if s["rarity"] in ("legendary", "mythic", "secret"):
        f["gacha_pity"] = 0
    else:
        f["gacha_pity"] = pity + 1
    return skin, False


# Кэш бонусов стаи для синхронного decay (обновляется в job_staya_resolve каждый час)
_STAYA_BONUS_CACHE: dict[int, dict] = {}
# Кэш активных бустеров стай {staya_id: {"mult": float, "ends_at": float}}
_STAYA_BOOST_CACHE: dict[int, dict] = {}


# Скорость затухания в единицах за час при множителе 1.0. Раньше эти числа
# были размазаны по decay() как «int(d * 0.4)», где d — целые единицы за вызов.
# На частых вызовах d равнялось единице, int(1 * 0.4) давал ноль, а last_decay
# всё равно сдвигался на now — прошедшее время просто выбрасывалось. Показатель
# с множителем меньше единицы не падал вообще: чистота и энергия у активного
# игрока стояли на 100 вечно.
DECAY_RATES = {
    "hunger":      7.0,
    "happiness":   7.0,
    "cleanliness": 7.0 * 0.4,
    "energy":      7.0 * 0.3,
    "health":      7.0 * 0.5,      # только при нулевом голоде
}


def _decay_frac_load(f: dict) -> dict:
    """Недосписанные доли единиц. Хранятся строкой JSON в колонке decay_frac."""
    raw = f.get("decay_frac") or ""
    if not raw:
        return {}
    try:
        data = json.loads(raw)
    except (ValueError, TypeError):
        return {}
    if not isinstance(data, dict):
        return {}
    # Доля по определению меньше единицы; всё прочее — мусор, и копить его
    # нельзя: подпорченное значение иначе списало бы показатель разом.
    return {k: v for k, v in data.items()
            if k in DECAY_RATES and isinstance(v, (int, float)) and 0 <= v < 1}


def _decay_frac_store(f: dict, frac: dict) -> None:
    kept = {k: round(v, 4) for k, v in frac.items() if v > 0}
    f["decay_frac"] = json.dumps(kept, separators=(",", ":")) if kept else ""


def decay(f: dict) -> dict:
    now = time.time()
    # ── Анабиоз: пропускаем деградацию ──────────────────
    if f.get("hibernation_until", 0) > now:
        f["last_decay"] = now
        return f
    # ── Онбординг: отключаем деградацию для новичков ────
    if f.get("onboard_step", 0) > 0:
        f["last_decay"] = now
        return f
    if not f["last_decay"]:
        f["last_decay"] = now
        return f

    hours = (now - f["last_decay"]) / 3600
    if hours <= 0:
        return f

    # ── Погода: применяем множители ──────────────────────
    weather = _get_today_weather()
    hunger_mult  = weather.get("hunger_decay_mult",  1.0)
    energy_mult  = weather.get("energy_decay_mult",  1.0)
    health_mult  = weather.get("health_decay_mult",  1.0)

    # ── Характер: применяем бонусы ────────────────────────
    pers_key = f.get("personality", "")
    pers     = PERSONALITIES.get(pers_key, {})

    # Весёлая — счастье падает медленнее
    happy_mult = pers.get("happiness_decay_mult", 1.0)

    # ── Бонус стаи: замедление голода (уровень 1+) ───────
    staya_id_d = f.get("staya_id") or 0
    if staya_id_d and staya_id_d in _STAYA_BONUS_CACHE:
        hunger_mult *= _STAYA_BONUS_CACHE[staya_id_d].get("hunger_decay_mult", 1.0)
    # Бонус стаи ур.7: чистота падает медленнее
    _clean_mult_d = _STAYA_BONUS_CACHE.get(staya_id_d, {}).get("clean_decay_mult", 1.0)

    # Недосписанный остаток с прошлых вызовов — без него показатель замирает.
    frac = _decay_frac_load(f)

    def _take(stat: str, mult: float) -> int:
        """Целые единицы к списанию; дробный хвост остаётся на следующий раз."""
        due = frac.get(stat, 0.0) + hours * DECAY_RATES[stat] * mult
        whole = int(due)
        frac[stat] = due - whole
        return whole

    f["hunger"]      = max(0, f["hunger"]               - _take("hunger", hunger_mult))
    f["happiness"]   = max(0, f["happiness"]            - _take("happiness", happy_mult))
    f["cleanliness"] = max(0, f.get("cleanliness", 100) - _take("cleanliness", _clean_mult_d))
    f["energy"]      = max(0, f.get("energy", 100)      - _take("energy", energy_mult))
    if f["hunger"] == 0:
        f["health"] = max(0, f["health"] - _take("health", health_mult))
    else:
        frac.pop("health", None)      # сыта — счётчик голодного урона обнуляем
    _decay_frac_store(f, frac)
    f["last_decay"] = now

    # ── Предупреждение о низком здоровье (< 20%) ──
    if f["alive"] and 0 < f["health"] < 20:
        if now - f.get("last_warning", 0) > 6 * 3600:
            f["last_warning"] = now
            f["_need_warning"] = True
    # ── Смерть ────────────────────────────────────
    if f["health"] <= 0 and f["alive"]:
        f["alive"] = 0
        f["_just_died"] = True
        # Питти сбрасывается при смерти — стимул не давать лягушке умирать
        f["gacha_pity"] = 0
        asyncio.create_task(plog(f["user_id"], "death", "health=0 от голода/HP", hp_delta=-100))
    return f


async def levelup(f: dict, bot=None) -> list[tuple]:
    gained = []
    while f["xp"] >= xp_need(f["level"]):
        f["xp"] -= xp_need(f["level"])
        f["level"] += 1
        f["coins"] += f["level"] * 10
        reward = LEVEL_REWARDS.get(f["level"])
        if reward:
            await db_add_skin(f["user_id"], reward)
            gained.append((f["level"], reward))
        # XP в котёл стаи теперь начисляется через add_xp (10% от каждого XP)
        # 🏪 Пробник Трудяги на 10-м уровне
        if f["level"] == 10 and bot:
            asyncio.create_task(grant_trial(
                f["user_id"], 2, 2, bot=bot,
                reason="Квакуся выросла и хочет попробовать себя на Болотном Рынке! 2 дня бесплатно 🏪"
            ))
    # Проверяем реферальные этапы при апгрейде уровня
    if bot:
        await check_referral_stages(f, bot)
    return gained


def get_mood(f: dict) -> str:
    if not f["alive"]:
        return "dead"
    if f["health"] < 25:
        return "sick"
    avg = (f["hunger"] + f["happiness"] + f["health"]) / 3
    if avg >= 70:
        return "happy"
    if avg >= 40:
        return "neutral"
    return "sad"


M_ICON = {"happy": "😊", "neutral": "😐", "sad": "😢", "sick": "🤒", "dead": "💀"}


def he(s) -> str:
    """Экранирует строку для безопасного использования в HTML-сообщениях."""
    return _html.escape(str(s))


# Голос питомца: первое лицо, женский род, три речевые фишки —
#   «Квак.» вместо точки (редко, не в каждой строке),
#   рубленый ритм «утверждение. уточнение.»,
#   лягушка констатирует, а не жалуется.
M_SAY = {
    "happy":   ["Хорошо мне. Квак.", "Сегодня болото удачное.",
                "Довольна. Редкий случай."],
    "neutral": ["Нормально. Бывало лучше.", "Сижу. Думаю.", "Квак. Без новостей."],
    "sad":     ["Живот бурчит.", "Поиграл бы со мной кто.", "Скучно мне."],
    "sick":    ["Кхе. Плохо мне.", "Кажется, приболела.", "Болит. Даже лапки."],
    "dead":    ["...", "💀"],
}

# Банков фраз настроения было два, и они разошлись: M_SAY читает только экран
# соседей, а карточка лягушки — главный экран игры — берёт фразу из _LANGS
# через t_mood(). Русский язык теперь один источник, M_SAY; en и zh остаются
# при своих переводах.
_LANGS["ru"].update({f"mood_{mood}": say for mood, say in M_SAY.items()})


def bar(v: int) -> str:
    """
    Полоса прогресса без HTML-обёртки.

    Все места вызова оборачивают результат в <code> сами, поэтому тег здесь
    добавлять нельзя — иначе получается вложенный <code><code>…</code></code>.
    """
    v = max(0, min(100, v))
    filled = round(v / 10)
    return "█" * filled + "░" * (10 - filled)


def fname(f: dict) -> str:
    """Имя лягушки, всегда HTML-экранированное для безопасной вставки в сообщения."""
    frog_name = f.get("frog_name") or ""
    first_name = f.get("first_name") or ""
    if frog_name:
        return he(frog_name)
    if first_name:
        return he(f"{t('stat_frog_default', f)} {first_name}")
    return he(t("stat_frog_default", f) or "Лягушка")


def censor_frog_name(name: str) -> str:
    """
    Проверяет игровой ник на наличие мата.
    Если мат найден — оставляет первые 2 символа, остальное заменяет на *.
    Пример: «Хуёплёт» → «Ху*****»
    """
    if not name:
        return name
    # Используем упрощённый список корней (без нормализации — ники обычно читаемые)
    _BAD_ROOTS_NICK = [
        "хуй","хую","хуя","хуе","хуи","нахуй","похуй","захуй",
        "пизд","пиздец","пиздит","пиздюк",
        "ебат","ебёт","ебут","ебал","ёбат","ёбут","ёбал","заебал","выебал",
        "блядь","бляди","блядс","шлюха",
        "сука","суки","сучк",
        "мудак","мудил","мудозв",
        "пидор","пидар","педик",
        "ублюдок","тварь",
        "хуесос","еблан","ебло","залупа",
    ]
    name_lower = name.lower().replace("ё", "е")
    # Нормализуем латиницу → кириллицу
    lat_map = {'a':'а','e':'е','o':'о','p':'р','c':'с','x':'х','y':'у','k':'к','h':'н','m':'м','b':'б','t':'т','i':'и'}
    name_norm = "".join(lat_map.get(ch, ch) for ch in name_lower)

    for root in _BAD_ROOTS_NICK:
        if root in name_norm:
            # Оставляем первые 2 символа, остальное — звёздочки
            visible = name[:2]
            stars = "*" * max(1, len(name) - 2)
            return visible + stars
    return name


def status_text(f: dict) -> str:
    lg = f  # передаём весь f для t()
    # ── Режим испытания ───────────────────────────
    if f.get("trial_active"):
        quests = json.loads(f.get("trial_quests", "[]"))
        prog = json.loads(f.get("trial_progress", "{}"))
        done = sum(1 for tq in quests if prog.get(tq["id"], 0) >= tq["goal"])
        total = len(quests)
        tasks = "\n".join(
            f"{'✅' if prog.get(tq['id'], 0) >= tq['goal'] else '🔲'} {tq['desc']}"
            f"{SEP}<b>{prog.get(tq['id'], 0)}/{tq['goal']}</b>"
            for tq in quests
        )
        return ui_card(
            f"{_E_SKULL} <b>{t('stat_trial', lg)}</b>{SEP}{done}/{total}",
            tasks,
            ui_money(f.get("coins", 0)),
            hint=t("stat_trial_done", lg),
        )

    # ── Анабиоз ──────────────────────────────────────────
    hiber_until = f.get("hibernation_until", 0) or 0
    if hiber_until > time.time():
        rem_h = int((hiber_until - time.time()) / 3600)
        rem_m = int(((hiber_until - time.time()) % 3600) / 60)
        _sk = f["skin"]
        _s_use_st = bool(f.get("use_static", 0))
        _nft = f.get("equipped_nft_url", "") or ""
        frozen_stats = "\n".join(
            f"{icon} <code>{bar(val)}</code> {val}%"
            for icon, val in (
                (_E_FOOD,  f["hunger"]),
                (_E_HAPPY, f["happiness"]),
                (_E_HEART, f["health"]),
            )
        )
        return ui_card(
            f"❄️ <b>{fname(f)}</b>{SEP}{display_skin(_sk, _s_use_st, user_nft_url=_nft)}",
            t("stat_frozen", lg),
            frozen_stats,
            ui_kv(f"{t('stat_thaws_in', lg)}:", f"{rem_h}ч {rem_m}м"),
            ui_money(f.get("coins", 0)),
        )

    skin   = f["skin"]
    m      = get_mood(f)
    phrase = t_mood(m, lg)
    need   = xp_need(f["level"])
    xp_pct = min(100, int(f["xp"] / need * 100))
    name   = fname(f)
    use_st = bool(f.get("use_static", 0))
    clean  = f.get("cleanliness", 100)
    energy = f.get("energy", 100)
    nft_url = f.get("equipped_nft_url", "") or ""

    # Иконка вместо подписи: сами эмодзи одинаковой ширины, поэтому колонка
    # выравнивается без хрупких пробельных отступов, а строка короче.
    stats = "\n".join(
        f"{icon} <code>{bar(val)}</code> {val}%"
        for icon, val in (
            (_E_FOOD,  f["hunger"]),
            (_E_HAPPY, f["happiness"]),
            (_E_HEART, f["health"]),
            (_E_SOAP,  clean),
            (_E_BOLT,  energy),
        )
    )

    wallet = ui_line(
        ui_money(f["coins"]),
        f"{_E_FIRE}{f['streak']}д" if f["streak"] > 1 else "",
    )

    return ui_card(
        f"{_E_FROG} <b>{name}</b>{SEP}{display_skin(skin, use_st, user_nft_url=nft_url)}",
        # Гифт игрока — второй строкой, сразу под именем: это его статус
        nft_status_line(f),
        f"{_E_STAR} {ui_kv('Уровень', f['level'])}\n"
        f"{_E_XP} <code>{bar(xp_pct)}</code> {f['xp']}/{need}",
        stats,
        wallet,
        t("stat_boost", lg) if f.get("_boost_active") else "",
        hint=phrase,
    )


