# ⏳  ЭКРАН КУЛДАУНА
# ══════════════════════════════════════════════════════════════════════════════
# Единственная позиция магазина, которую реально покупают, — доп. слот
# экспедиции. Работает она не из-за цены, а из-за момента: кнопка появляется
# ровно там, где игра сказала «нельзя». Ускорение ухода сделано по тому же
# правилу, поэтому отказ по кулдауну — это экран, а не всплывашка: во
# всплывашку кнопку положить нельзя.
#
# Цена растёт вместе с длиной кулдауна: пропустить двадцать минут и пропустить
# сутки — разные вещи.
SPEEDUP_ACTIONS = {
    #  ключ:  (поле времени,     кулдаун,   ⭐, иконка, что ускоряем)
    "play":  ("last_play",       20 * 60,    2, "🎮", "Игра"),
    "heal":  ("last_heal",       3600,       3, "❤️", "Лечение"),
    "wash":  ("last_wash",       2 * 3600,   3, "🧼", "Купание"),
    "sleep": ("last_sleep",      3 * 3600,   4, "😴", "Сон"),
    "feed":  ("last_fly_feed",   86400,      8, "🍖", "Муха"),
}


def speedup_left(f: dict, action: str) -> int:
    """Сколько секунд ещё ждать. 0 — можно прямо сейчас."""
    field, cd, *_ = SPEEDUP_ACTIONS[action]
    return max(0, int(cd - (time.time() - (f.get(field) or 0))))


def cooldown_screen(f: dict, action: str, reason: str) -> tuple[str, InlineKeyboardMarkup]:
    """Экран «ещё рано» с кнопкой пропустить ожидание за звёзды."""
    _, _, stars, icon, name = SPEEDUP_ACTIONS[action]
    left = speedup_left(f, action)
    if left >= 3600:
        when = f"{left // 3600} ч {left % 3600 // 60} мин"
    elif left >= 60:
        when = f"{left // 60} мин"
    else:
        when = f"{left} сек"
    text = ui_card(
        ui_title(icon, name),
        ui_kv("Готово через", when),
        hint=reason,
    )
    kb = InlineKeyboardMarkup([
        [btn(f"⭐ Не ждать · {stars}", callback_data=f"speedup_{action}", style="primary")],
        [btn("◀️ Назад", callback_data="refresh")],
    ])
    return text, kb


async def show_cooldown(q, f: dict, action: str, reason: str) -> None:
    """Показать экран кулдауна вместо прежнего alert'а."""
    await q.answer()
    asyncio.create_task(offer_shown(f"speedup_{action}"))
    text, kb = cooldown_screen(f, action, reason)
    try:
        await q.message.edit_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except (BadRequest, Forbidden, TimedOut):
        pass


def settings_screen(f: dict) -> tuple[str, InlineKeyboardMarkup]:
    """
    Экран настроек — единственный источник правды.

    Раньше он был скопирован в каждый обработчик переключателя, копии
    разошлись, и, например, смена режима стикеров стирала с экрана все
    остальные пункты. Теперь любой toggle перерисовывает экран отсюда.
    """
    use_st = bool(f.get("use_static", 0))
    # Шаблон пункта: «иконка Категория · состояние».
    mode_state = "статичные" if use_st else "анимированные"
    feed_state = "выкл" if f.get("no_feed_notify", 0) else "вкл"
    mosq_state = "вкл" if f.get("mosquito_notify", 1) else "выкл"
    gift_state = "только соседи" if f.get("gift_notify", 0) == 1 else "все"
    war_state  = "вкл" if f.get("war_notify", 1) else "выкл"

    kb = InlineKeyboardMarkup([
        [btn(f"🎨 Стикеры{SEP}{mode_state}", callback_data="toggle_static")],
        [btn(f"🍽 Кормление{SEP}{feed_state}", callback_data="toggle_feed_notify")],
        [btn(f"🦟 Комар{SEP}{mosq_state}", callback_data="toggle_mosquito_notify")],
        [btn(f"🎁 Переводы{SEP}{gift_state}", callback_data="toggle_gift_notify")],
        [btn(f"⚔️ Набеги{SEP}{war_state}", callback_data="toggle_war_notify")],
        [btn("🚫 Блокировки кормления", callback_data="feed_blocks_menu")],
        [
            btn(t("btn_lang", f),      callback_data="lang_set_menu"),
            btn(t("btn_hibernate", f), callback_data="hibernation_menu"),
        ],
        [
            btn("📋 Правила", callback_data="game_rules"),
            btn(t("btn_feedback", f), callback_data="feedback_start"),
        ],
        [btn(t("btn_back", f), callback_data="menu_more")],
    ])

    text = ui_card(
        ui_title("⚙️", "Настройки"),
        ui_kv("👕 Облик:", display_skin(f["skin"], use_st)),
        hint="Нажми на пункт, чтобы переключить.",
    )
    return text, kb


async def show_settings(q, f: dict) -> None:
    """Перерисовывает экран настроек в текущем сообщении."""
    text, kb = settings_screen(f)
    try:
        await q.message.edit_text(
            text, parse_mode=ParseMode.HTML, reply_markup=kb,
            link_preview_options=LinkPreviewOptions(),
        )
    except (BadRequest, Forbidden, TimedOut):
        pass


def main_kb(f: dict, is_group: bool = False, sacrifice_active: bool = False,
            contest_active: bool = False, legend_pct: int | None = None,
            legend_emoji: str = "📜",
            nft_contest_active: bool = False,
            freeze_active: bool = False) -> InlineKeyboardMarkup:
    care_ready = _care_ready(f)
    care_key = "menu_care_ready" if care_ready else "menu_care"
    care_lbl = t(care_key, f) + ("" if care_ready else " ⏳")

    # Временные события. Порядок фиксирован: сначала то, что закончится
    # раньше и требует действия, потом фоновое — чтобы кнопки не прыгали.
    event_btns = []
    if freeze_active:
        event_btns.append(btn("Фриз-ивент", callback_data="fz_dashboard", style="primary"))
    if sacrifice_active:
        event_btns.append(btn(t("menu_event", f), callback_data="sacrifice_menu"))
    if contest_active:
        event_btns.append(btn("Конкурс", callback_data="contest_my_stats"))
    if nft_contest_active and f.get("league", 0) in NFT_CONTEST_TARGET_LEAGUES:
        event_btns.append(btn("NFT-конкурс", callback_data="nft_contest_menu"))
    if legend_pct is not None:
        event_btns.append(btn(
            f"{legend_emoji} Легенда{SEP}{legend_pct}%", callback_data="legend_status"
        ))

    if is_group:
        rows = [
            [btn(care_lbl, callback_data="menu_care", style="primary", icon_id=ICON_CARE),
             btn(t("menu_games", f), callback_data="menu_games", icon_id=ICON_GAMES)],
            [btn(t("menu_gacha", f), callback_data="gacha", icon_id=ICON_GACHA),
             btn(t("menu_more", f), callback_data="menu_more", icon_id=ICON_MORE)],
            *([[btn("Площадь", callback_data="plaza", icon_id=ICON_PLAZA)]] if f.get("level", 1) >= 3 else []),
        ]
    else:
        rows = [
            [btn(care_lbl, callback_data="menu_care", style="primary", icon_id=ICON_CARE),
             btn(t("menu_games", f), callback_data="menu_games", icon_id=ICON_GAMES)],
            [btn(t("menu_gacha", f), callback_data="gacha", icon_id=ICON_GACHA),
             btn(t("menu_shop", f), callback_data="menu_shop", icon_id=ICON_SHOP)],
            [btn(t("menu_more", f), callback_data="menu_more", icon_id=ICON_MORE),
             *([btn("Площадь", callback_data="plaza", icon_id=ICON_PLAZA)] if f.get("level", 1) >= 3 else [])],
        ]

    # Строим ряды с событиями (без кнопки площади — она теперь в основных рядах)
    event_rows = []
    for i in range(0, len(event_btns), 2):
        event_rows.append(event_btns[i:i+2])

    # Вставляем перед основными рядами
    rows = event_rows + rows

    return InlineKeyboardMarkup(rows)


async def main_kb_live(f: dict, is_group: bool = False) -> InlineKeyboardMarkup:
    """Строит главное меню с автопроверкой активных ивентов."""
    ev      = await _sacrifice_active_event()
    contest = await _get_active_contest()
    leg     = await legend_active()
    nft_c   = await _get_active_nft_contest()
    freeze_on = await _fz_active()  # фриз-ивент активен?

    leg_pct   = None
    leg_emoji = "📜"
    if leg:
        goals    = leg["goals"]
        progress = leg["progress"]
        leg_pct  = int(sum(min(progress.get(a, 0) / g, 1.0)
                          for a, g in goals.items()) / len(goals) * 100)
        leg_emoji = leg.get("emoji", "📜")

    return main_kb(
        f, is_group=is_group,
        sacrifice_active=bool(ev),
        contest_active=bool(contest),
        legend_pct=leg_pct,
        legend_emoji=leg_emoji,
        nft_contest_active=bool(nft_c),
        freeze_active=freeze_on,
    )




def care_kb(f: dict) -> InlineKeyboardMarkup:
    """Подменю раздела Уход."""
    now = time.time()
    feed_lbl  = _cd_label(t("care_feed",  f), f, "last_fly_feed", 86400)
    play_lbl  = _cd_label(t("care_play",  f), f, "last_play",  20 * 60)
    heal_lbl  = _cd_label(t("care_heal",  f), f, "last_heal",  3600)
    wash_lbl  = _cd_label(t("care_wash",  f), f, "last_wash",  2 * 3600)
    sleep_lbl = _cd_label(t("care_sleep", f), f, "last_sleep", 3 * 3600)
    today_start = (
        datetime.now(timezone.utc)
        .replace(hour=0, minute=0, second=0, microsecond=0)
        .timestamp()
    )
    if f.get("last_daily", 0) < today_start:
        daily_lbl = f"{t('care_daily', f)} ✅"
    else:
        _left = int(today_start + 86400 - now)
        daily_lbl = f"{t('care_daily', f)} ⏳{_left//3600}h" if _left >= 3600 else f"{t('care_daily', f)} ⏳{_left//60}m"
    return InlineKeyboardMarkup(
        [
            [
                btn(feed_lbl,  callback_data="menu_feed"),
                btn(play_lbl,  callback_data="menu_play"),
            ],
            [
                btn(heal_lbl,  callback_data="heal"),
                btn(wash_lbl,  callback_data="wash"),
            ],
            [
                btn(sleep_lbl, callback_data="sleep"),
                btn(daily_lbl, callback_data="daily"),
            ],
            [btn(t("back", f), callback_data="refresh")],
        ]
    )


def back_to_main(f: dict = None) -> InlineKeyboardMarkup:
    lbl = t("back", f) if f else "◀️ Назад"
    return InlineKeyboardMarkup([[btn(lbl, callback_data="refresh")]])


