async def _is_chat_admin(bot, chat_id: int, user_id: int) -> bool:
    """
    Проверяет, является ли пользователь администратором или создателем Telegram-чата.
    Безопасно возвращает False при любых ошибках API (нет прав у бота, чат недоступен и т.д.)
    """
    try:
        member = await bot.get_chat_member(chat_id, user_id)
        return member.status in ("administrator", "creator")
    except Exception:
        return False


async def is_chat_banned(chat_id: int, user_id: int) -> bool:
    """Проверяет, забанен ли пользователь в данном чате (локальный бан)."""
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT expires_at FROM chat_bans WHERE chat_id=? AND user_id=?",
            (chat_id, user_id)
        ) as c:
            row = await c.fetchone()
    if not row:
        return False
    expires = row[0]
    if expires and 0 < expires < now:
        # Бан истёк — удаляем
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("DELETE FROM chat_bans WHERE chat_id=? AND user_id=?", (chat_id, user_id))
            await db.commit()
        return False
    return True


async def log_chat_activity(chat_id: int, user_id: int, username: str, action: str, amount: int = 0):
    """Записывает действие игрока в лог активности чата."""
    if not chat_id or chat_id > 0:  # логируем только группы (отрицательные chat_id)
        return
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT INTO chat_activity_log(chat_id, user_id, username, action, amount, ts) VALUES(?,?,?,?,?,?)",
            (chat_id, user_id, username or "", action, amount, time.time())
        )
        await db.commit()
        # Чистим старые записи (>30 дней)
        await db.execute(
            "DELETE FROM chat_activity_log WHERE chat_id=? AND ts < ?",
            (chat_id, time.time() - 30 * 86400)
        )
        await db.commit()


async def apply_chat_tax(chat_id: int, winner_uid: int, prize: int, ctx=None) -> int:
    """
    Вычитает налог из приза и зачисляет в фонд чата.
    Возвращает приз ПОСЛЕ налога.
    Если фонд достиг порога авторозыгрыша — запускает его.
    """
    if not chat_id or chat_id > 0:
        return prize  # не в группе — налога нет
    s = await get_chat_settings(chat_id)
    rate = s.get("tax_rate", 0)
    if not rate:
        return prize
    tax = max(1, int(prize * rate / 100))
    net_prize = prize - tax
    new_fund = s.get("local_fund", 0) + tax
    await save_chat_settings(chat_id, local_fund=new_fund)

    # Проверяем авторозыгрыш
    threshold = s.get("auto_giveaway_threshold", 0)
    if threshold > 0 and new_fund >= threshold and ctx:
        asyncio.create_task(_run_chat_auto_giveaway(chat_id, new_fund, ctx))

    return net_prize


async def _run_chat_auto_giveaway(chat_id: int, fund: int, ctx):
    """Автоматический розыгрыш средств фонда чата среди активных игроков.
    Участвуют все игроки у которых есть лягушка и которые состоят в чате,
    независимо от того, через какой чат они зарегистрировались.
    """
    try:
        now = time.time()
        week_ago = now - 7 * 86400
        # Берём всех активных живых игроков (не только из source_chat_id)
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                """SELECT user_id, first_name FROM frogs
                   WHERE alive=1 AND banned=0
                   AND (last_feed>? OR last_play>?)
                   ORDER BY RANDOM() LIMIT 200""",
                (week_ago, week_ago)
            ) as c:
                candidates = await c.fetchall()
        if not candidates:
            return
        # Проверяем членство в чате — берём первого кто состоит в нём
        random.shuffle(candidates)
        winner = None
        for row in candidates:
            try:
                member = await ctx.bot.get_chat_member(chat_id, row[0])
                if member.status not in ("left", "kicked", "banned"):
                    winner = row
                    break
            except Exception:
                continue
        if not winner:
            # Запасной вариант: берём из source_chat_id как раньше
            async with aiosqlite.connect(DB_PATH) as db:
                async with db.execute(
                    """SELECT user_id, first_name FROM frogs
                       WHERE source_chat_id=? AND alive=1 AND banned=0
                       ORDER BY RANDOM() LIMIT 1""",
                    (chat_id,)
                ) as c:
                    row = await c.fetchone()
            if row:
                winner = row
            else:
                return
        w_uid, w_name = winner[0], winner[1]
        w_f = await db_get(w_uid)
        if w_f:
            w_f["coins"] += fund
            await db_save(w_f)
        await save_chat_settings(chat_id, local_fund=0)
        try:
            await ctx.bot.send_message(
                chat_id,
                f"🎉 <b>Авторозыгрыш фонда чата!</b>\n\n"
                f"Накоплено: <b>{fund}{_E_COIN}</b>\n"
                f"Победитель: <b>{he(w_name)}</b> {_E_TROPHY}\n"
                f"Приз: <b>+{fund}{_E_COIN}</b>",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
    except Exception as e:
        print(f"⚠️ Auto-giveaway error: {e}")


async def schedule_delete(
    bot, chat_id: int, message_id: int, delay: int = GROUP_AUTO_DELETE_SEC
):
    """Удаляет сообщение бота через delay секунд (только в группах)."""
    await asyncio.sleep(delay)
    try:
        await bot.delete_message(chat_id=chat_id, message_id=message_id)
    except (BadRequest, Forbidden, TimedOut):
        pass


