CHAT_MODE_LABELS = {
    "full":     "🐸 Полный",
    "lite":     "⚡ Лёгкий",
    "vanilla":  "🤫 Ваниль",
    "readonly": "📖 Читатель",
}

ANNOUNCE_LEVEL_LABELS = {
    "all":   "📢 Все",
    "major": "⭐ Важные",
    "none":  "🔇 Нет",
}

WELCOME_MODE_LABELS = {
    "full":    "🎉 Полное",
    "minimal": "📝 Минимал",
    "silent":  "🤫 Тихо",
}

# Порог активности: при >N сообщ/мин — анонсы откладываются
_ANNOUNCE_DEFER_MSG_RATE = 5
# Задержка анонса после затихания чата (сек)
_ANNOUNCE_DEFER_SEC = 120
# Очередь отложенных анонсов: chat_id → [(text, markup, ts)]
_deferred_announces: dict[int, list] = {}


async def get_chat_mode(chat_id: int) -> str:
    """Быстро возвращает режим чата (full/lite/vanilla/readonly)."""
    s = await get_chat_settings(chat_id)
    return s.get("mode", "full")


async def chat_allows_announce(chat_id: int, level: str = "all") -> bool:
    """
    Проверяет, можно ли сейчас отправить анонс в чат с учётом:
    - режима чата
    - уровня анонсов настроенного админом
    - текущей активности (горячее обсуждение)
    - тишины (мёртвый чат > 6ч)
    """
    s = await get_chat_settings(chat_id)
    mode = s.get("mode", "full")
    al   = s.get("announce_level", "all")
    susp = s.get("announce_suspended", 0)

    if mode in ("vanilla", "readonly"):
        return False
    if al == "none":
        return False
    if al == "major" and level == "all":
        return False
    if susp:
        return False
    return True


async def update_chat_activity(chat_id: int):
    """
    Обновляет трекер активности чата.
    Вызывается из on_message для каждого сообщения в группе.
    Автоматически обновляет msg_rate_1min и suspend/resume анонсов.
    """
    now = time.time()
    s = await get_chat_settings(chat_id)

    rate_ts = s.get("msg_rate_ts", 0.0) or 0.0
    rate    = s.get("msg_rate_1min", 0) or 0
    last_ts = s.get("last_msg_ts", 0.0) or 0.0

    # Пересчёт rate раз в 60 сек
    if now - rate_ts > 60:
        rate    = 1
        rate_ts = now
    else:
        rate += 1

    # Определяем нужно ли suspend/resume анонсов
    hours_silent = (now - last_ts) / 3600 if last_ts else 999
    was_susp = s.get("announce_suspended", 0)

    if rate >= _ANNOUNCE_DEFER_MSG_RATE:
        new_susp = 1  # горячее обсуждение — молчим
    elif hours_silent > 6:
        new_susp = 1  # мёртвый чат — не спамим
    else:
        new_susp = 0

    # Сохраняем только если что-то изменилось (не на каждое сообщение)
    if new_susp != was_susp or (now - last_ts) > 30:
        await save_chat_settings(
            chat_id,
            last_msg_ts=now,
            msg_rate_1min=rate,
            msg_rate_ts=rate_ts,
            announce_suspended=new_susp,
        )


async def vanilla_reply(
    update: Update,
    ctx: ContextTypes.DEFAULT_TYPE,
    text: str,
    delay: int = 8,
    reply_markup=None,
    parse_mode=ParseMode.HTML,
):
    """
    Vanilla-режим: отправляет ответ и удаляет его + команду через delay сек.
    Используется вместо обычного reply_text когда mode=vanilla.
    """
    try:
        msg = await update.message.reply_text(
            text, parse_mode=parse_mode, reply_markup=reply_markup
        )
        # Удаляем команду пользователя
        try:
            await update.message.delete()
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
        # Планируем удаление ответа
        asyncio.create_task(schedule_delete(ctx.bot, msg.chat_id, msg.message_id, delay))
    except (BadRequest, Forbidden, TimedOut):
        pass


async def vanilla_redirect(
    update: Update,
    ctx: ContextTypes.DEFAULT_TYPE,
    feature: str,
    label: str = "🐸 Открыть в личке",
):
    """
    Vanilla-режим: вместо ответа в чат показывает кнопку перехода в ЛС.
    Само сообщение с кнопкой удаляется через 15 сек.
    """
    try:
        bot_me = await ctx.bot.get_me()
        deep_link = f"https://t.me/{bot_me.username}?start={feature}"
        kb = InlineKeyboardMarkup([[btn(label, url=deep_link)]])
        msg = await update.message.reply_text("👇", reply_markup=kb)
        try:
            await update.message.delete()
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
        asyncio.create_task(schedule_delete(ctx.bot, msg.chat_id, msg.message_id, 15))
    except (BadRequest, Forbidden, TimedOut):
        pass


async def mode_aware_reply(
    update: Update,
    ctx: ContextTypes.DEFAULT_TYPE,
    text_full: str,
    text_lite: str = None,
    feature_key: str = "frog",
    delay_vanilla: int = 8,
    reply_markup=None,
    parse_mode=ParseMode.HTML,
) -> bool:
    """
    Умный reply с учётом режима чата.
    - full/lite: отправляет text_full (или text_lite в lite)
    - vanilla: показывает кнопку в ЛС
    - readonly: молчит
    Возвращает True если сообщение было отправлено, False если readonly/пропущено.
    """
    chat_id = update.effective_chat.id
    mode = await get_chat_mode(chat_id)

    if mode == "readonly":
        return False
    if mode == "vanilla":
        await vanilla_redirect(update, ctx, feature_key)
        return True

    text = (text_lite or text_full) if mode == "lite" and text_lite else text_full
    await update.message.reply_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
    return True


async def _delete_casino_dice(bot, chat_id: int, message_id: int, chat_type: str):
    """Удаляет сообщение с эмодзи казино если чат — группа и настройка включена."""
    if chat_type not in ("group", "supergroup"):
        return
    settings = await get_chat_settings(chat_id)
    if not settings.get("auto_delete_casino_dice", 1):
        return
    # Небольшая задержка чтобы пользователь увидел результат анимации
    await asyncio.sleep(5)
    try:
        await bot.delete_message(chat_id=chat_id, message_id=message_id)
    except (BadRequest, Forbidden, TimedOut):
        pass


async def _auto_delete(bot, chat_id: int, message_id: int, importance: str = MSG_MEDIUM):
    """
    Планирует удаление с учётом настроек конкретного чата.
    importance = MSG_LOW | MSG_MEDIUM | MSG_HIGH | MSG_PERMANENT
    """
    if importance == MSG_PERMANENT:
        return
    settings = await get_chat_settings(chat_id)
    if not settings.get("auto_delete_enabled", 1):
        return
    delay_map = {
        MSG_LOW:    settings.get("delay_low",    20),
        MSG_MEDIUM: settings.get("delay_medium", 120),
        MSG_HIGH:   settings.get("delay_high",   300),
    }
    delay = delay_map.get(importance, settings.get("delay_medium", 120))
    await asyncio.sleep(delay)
    try:
        await bot.delete_message(chat_id=chat_id, message_id=message_id)
    except (BadRequest, Forbidden, TimedOut):
        pass


async def send_group_msg(
    update: Update,
    text: str,
    importance: str = MSG_MEDIUM,
    reply_markup=None,
    **kwargs,
):
    """
    Единая точка отправки сообщений в групповые чаты.
    Автоматически применяет политику автоудаления в соответствии с
    настройками чата и уровнем importance.
    В ЛС — просто отправляет без планирования удаления.
    Возвращает отправленное сообщение.
    """
    msg = await update.message.reply_text(text, reply_markup=reply_markup, **kwargs)
    if msg and update.effective_chat.type in ("group", "supergroup"):
        asyncio.create_task(
            _auto_delete(update.get_bot(), msg.chat.id, msg.message_id, importance)
        )
    return msg


async def group_reply(update: Update, text: str, **kwargs) -> None:
    """
    Обратная совместимость — вызывает send_group_msg с уровнем MSG_MEDIUM.
    Отвечает на сообщение и автоматически планирует удаление ответа
    если чат является группой/супергруппой.
    """
    return await send_group_msg(update, text, importance=MSG_MEDIUM, **kwargs)




