async def announce(bot, text: str, reply_markup=None, admin_only=False, delete_after: int = 300,
                   announce_level: str = "all", target_chat_id: int = None):
    """
    admin_only=True → отправляет в ADMIN_CHAT_ID (для уведомлений администратору).
    admin_only=False → отправляет в CHAT_ID (публичный игровой чат).
    delete_after — секунд до удаления сообщения из чата (0 = не удалять).
    announce_level — "all" | "major" | "none" (проверяется против настроек чата).
    target_chat_id — если задан, отправляет в этот конкретный чат (иначе CHAT_ID).
    """
    cid = ADMIN_CHAT_ID if admin_only else (target_chat_id or CHAT_ID or await db_setting("chat_id"))
    if not cid:
        cid = ADMIN_CHAT_ID or await db_setting("chat_id")

    # Проверяем режим чата перед отправкой публичного анонса
    if not admin_only and cid:
        if not await chat_allows_announce(int(cid), level=announce_level):
            return  # чат в vanilla/readonly/none — молчим

    if cid:
        try:
            sent = await bot.send_message(
                int(cid),
                text,
                parse_mode=ParseMode.HTML,
                link_preview_options=LinkPreviewOptions(),
                reply_markup=reply_markup,
            )
            # Авто-удаление только в игровом чате (не в адм-чате), если задан таймер
            if not admin_only and delete_after > 0 and sent:
                asyncio.create_task(schedule_delete(bot, int(cid), sent.message_id, delete_after))
        except Exception as e:
            print(f"❌ Ошибка отправки в чат {cid}: {e}")
    else:
        print("⚠️ announce: не задан ID чата для уведомлений")


