# 🎁 XGIFT API — вспомогательные функции
# API: https://app-api.xgift.tg  (открытый, без авторизации, эмуляция браузера)
# ══════════════════════════════════════════════════════════════════════════════

# Заголовки браузера — xgift.tg требует Origin/Referer как в браузере
_XGIFT_HEADERS = {
    "Accept": "application/json, text/plain, */*",
    "Accept-Language": "en-US,en;q=0.9",
    "Referer": "https://xgift.tg/",
    "Origin": "https://xgift.tg",
    "Sec-Fetch-Dest": "empty",
    "Sec-Fetch-Mode": "cors",
    "Sec-Fetch-Site": "same-site",
    "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1",
}


async def xgift_request(path: str, params: dict = None) -> dict | list | None:
    """GET-запрос к xgift API. Возвращает JSON или None при ошибке."""
    url = XGIFT_API_BASE + path
    try:
        async with aiohttp.ClientSession(headers=_XGIFT_HEADERS) as session:
            async with session.get(
                url, params=params, timeout=aiohttp.ClientTimeout(total=10)
            ) as resp:
                if resp.status == 200:
                    return await resp.json(content_type=None)
                print(f"⚠️ xgift_request {path} → HTTP {resp.status}")
                return None
    except Exception as e:
        print(f"⚠️ xgift_request {path}: {e}")
        return None


def _xgift_format_name(name: str) -> str:
    """KissedFrog → KissedFrog (xgift принимает имя без пробелов/апострофов/дефисов)."""
    return name.replace(" ", "").replace("'", "").replace("-", "")


async def xgift_gift_info(slug: str) -> dict | None:
    """
    Информация о конкретном гифте по slug вида 'kissedfrog-42'.
    GET /gifts/{slug}
    Возвращает: slug, collectionName, floorPrice, estimatedPriceTon,
                currentOwner (с telegram_id если есть), model, backdrop, pattern и др.
    """
    data = await xgift_request(f"/gifts/{slug}")
    return data if isinstance(data, dict) else None


async def xgift_collection_info(name: str) -> dict | None:
    """
    Инфо о коллекции: floorPrice, totalCount, floor история и др.
    GET /collections/{name}
    """
    data = await xgift_request(f"/collections/{_xgift_format_name(name)}")
    return data if isinstance(data, dict) else None


async def xgift_collection_gifts(name: str) -> dict | None:
    """
    Все гифты коллекции с моделями, бэкдропами и их флорами.
    GET /gifts/filters/{name}?collectionType=upgradable
    """
    data = await xgift_request(
        f"/gifts/filters/{_xgift_format_name(name)}",
        {"collectionType": "upgradable"},
    )
    return data if isinstance(data, dict) else None


async def xgift_floor_price(name: str) -> float | None:
    """Минимальная цена коллекции в TON."""
    data = await xgift_collection_info(name)
    if data:
        p = data.get("floorPrice")
        try:
            return float(p) if p is not None else None
        except (TypeError, ValueError):
            return None
    return None


async def xgift_models_floor(name: str) -> dict[str, float]:
    """
    Флоры по моделям: {'Aqua Plush': 9.5, 'Barcelona': 10.5, ...}
    """
    data = await xgift_collection_gifts(name)
    if not data:
        return {}
    result = {}
    for m in data.get("giftModel", []):
        n = m.get("model")
        p = m.get("floorPriceTon")
        if n and p is not None:
            try:
                result[n] = float(p)
            except (TypeError, ValueError):
                pass
    return result


