async def partner_chat_register(chat_id: int, chat_title: str, chat_username: str, added_by: int, bot_username: str):
    """Регистрирует партнёрский чат в БД."""
    now = time.time()
    bot_link = f"https://t.me/{bot_username}?start=chat_{chat_id}"
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            """INSERT INTO partner_chats(chat_id, chat_title, chat_username, added_at, added_by_uid, active, bot_link)
               VALUES(?, ?, ?, ?, ?, 1, ?)
               ON CONFLICT(chat_id) DO UPDATE SET active=1, chat_title=excluded.chat_title,
               chat_username=excluded.chat_username, bot_link=excluded.bot_link""",
            (chat_id, chat_title, chat_username, now, added_by, bot_link),
        )
        await db.commit()
    return bot_link


async def partner_chat_deactivate(chat_id: int):
    """Помечает чат как неактивный (бот удалён)."""
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("UPDATE partner_chats SET active=0 WHERE chat_id=?", (chat_id,))
        await db.commit()


async def partner_chat_get(chat_id: int) -> dict | None:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM partner_chats WHERE chat_id=?", (chat_id,)) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def db_top_chat(chat_id: int, n: int = 10) -> list[dict]:
    """Топ игроков конкретного чата (по уровню)."""
    loop = asyncio.get_event_loop()
    def _read():
        conn = _db_pool.acquire()
        temporary = False
        try:
            rows = conn.execute(
                "SELECT user_id,first_name,frog_name,skin,level,alive,streak,xp "
                "FROM frogs WHERE source_chat_id=? AND is_bot=0 AND banned=0 ORDER BY level DESC, xp DESC LIMIT ?",
                (chat_id, n),
            ).fetchall()
            return [dict(r) for r in rows]
        except Exception:
            temporary = True
            raise
        finally:
            _db_pool.release(conn, temporary=temporary)
    return await loop.run_in_executor(None, _read)


async def partner_chat_list_active() -> list[dict]:
    """Список активных партнёрских чатов."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM partner_chats WHERE active=1 ORDER BY added_at DESC"
        ) as c:
            rows = await c.fetchall()
    return [dict(r) for r in rows]


async def partner_chat_count_members(chat_id: int) -> int:
    """Считает игроков из данного чата."""
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(*) FROM frogs WHERE source_chat_id=?", (chat_id,)
        ) as c:
            return (await c.fetchone())[0] or 0


