async def on_my_chat_member(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Срабатывает когда бот добавлен или удалён из группы."""
    event: ChatMemberUpdated = update.my_chat_member
    if not event:
        return
    chat = event.chat
    if chat.type not in ("group", "supergroup"):
        return

    old_status = event.old_chat_member.status
    new_status = event.new_chat_member.status

    bot_me = await ctx.bot.get_me()
    chat_username = chat.username or ""
    chat_title = chat.title or str(chat.id)
    added_by = event.from_user.id if event.from_user else 0

    # Бот добавлен
    if old_status in ("left", "kicked") and new_status in ("member", "administrator"):
        await partner_chat_register(
            chat.id, chat_title, chat_username, added_by, bot_me.username
        )
        # Приветственное сообщение и уведомление администратору — отправляются
        # только после того, как администратор чата запустит команду /activate

    # Бот удалён
    elif old_status in ("member", "administrator") and new_status in ("left", "kicked"):
        await partner_chat_deactivate(chat.id)
        chat_mention = f"@{chat_username}" if chat_username else he(chat_title)
        await admin_notify(
            ctx.bot,
            f"Бот удалён из чата <b>{chat_mention}</b> (id: <code>{chat.id}</code>)",
            "👋",
        )


# ══════════════════════════════════════════
# /activate — активация бота в партнёрском чате
# ══════════════════════════════════════════

async def cmd_activate(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/activate — отправить приветственное сообщение в чат (только для администраторов чата)."""
    if not is_group(update):
        await update.message.reply_text("Эта команда работает только в группах.")
        return
    chat = update.effective_chat
    user = update.effective_user
    # Проверяем, что пользователь — администратор чата
    try:
        member = await ctx.bot.get_chat_member(chat.id, user.id)
        if member.status not in ("administrator", "creator"):
            await update.message.reply_text("⛔ Только администраторы чата могут активировать бота.")
            return
    except Exception:
        await update.message.reply_text("⛔ Не удалось проверить права.")
        return
    pc = await partner_chat_get(chat.id)
    if not pc:
        # Чат был добавлен до введения партнёрской системы — регистрируем сейчас
        try:
            bot_me = await ctx.bot.get_me()
            await partner_chat_register(
                chat.id,
                chat.title or str(chat.id),
                chat.username or "",
                user.id,
                bot_me.username or "",
            )
            pc = await partner_chat_get(chat.id)
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
    if not pc:
        await update.message.reply_text("⚠️ Не удалось зарегистрировать чат. Попробуйте удалить бота и добавить снова.")
        return
    bot_link = pc.get("bot_link", "")
    chat_title = he(chat.title or str(chat.id))

    # Определяем режим приветствия
    cs = await get_chat_settings(chat.id)
    welcome_mode = cs.get("welcome_mode", "full")
    chat_mode    = cs.get("mode", "full")

    if chat_mode == "vanilla" or welcome_mode == "silent":
        # Тихий режим — никаких сообщений в чат
        pass
    elif welcome_mode == "minimal":
        try:
            await ctx.bot.send_message(
                chat.id,
                f"<tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji> Frog Tamagotchi активирован! Напиши /frog чтобы начать.",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[
                    btn("🐸 Начать", url=bot_link),
                ]]) if bot_link else None,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
    else:
        # Полное приветствие
        try:
            await ctx.bot.send_message(
                chat.id,
                f"<tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji> <b>Привет, {chat_title}!</b>\n\n"
                f"Я — Frog Tamagotchi Bot! Каждый участник этого чата может завести свою лягушку прямо сейчас.\n\n"
                f"📌 <b>Как начать:</b> нажми кнопку ниже или напиши мне <code>/start</code> в личку.\n"
                f"Все игроки из этого чата автоматически попадут в <b>локальный топ чата</b>!\n\n"
                f"{_E_TROPHY} <b>Доступные команды в чате:</b>\n"
                f"• /top — глобальный топ\n"
                f"• /toplocal — топ игроков <b>этого чата</b>\n"
                f"• /duel — дуэль\n"
                f"• /ttt — крестики-нолики\n\n"
                f"<i>Твои прогресс, монеты и достижения сохраняются даже если выйдешь из чата</i>",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[
                    btn("🐸 Начать игру", url=bot_link),
                ]]) if bot_link else None,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
    # Уведомляем главного администратора бота
    chat_mention = f"@{chat.username}" if chat.username else chat_title
    adder_tag = f"@{user.username}" if user.username else he(user.first_name)
    await admin_notify(
        ctx.bot,
        f"Бот активирован в чате <b>{chat_mention}</b> (id: <code>{chat.id}</code>)\n"
        f"Активировал: {adder_tag}\n"
        f"Ссылка для игроков: {bot_link}",
        "✅",
    )




def _ca_emoji(val, invert=False) -> str:
    on = bool(val) if not invert else not bool(val)
    return "✅" if on else "❌"


def _chatadmin_main_kb(cid: int, trusted: bool = False, is_admin: bool = False) -> InlineKeyboardMarkup:
    rows = [
        [btn("🎭 Режим",      callback_data=f"ca_mode_{cid}",      style="primary"),
         btn("⚙️ Настройки",  callback_data=f"ca_settings_{cid}", style="primary")],
        [btn("🎮 Игры",       callback_data=f"ca_games_{cid}",     style="primary"),
         btn("💰 Экономика",  callback_data=f"ca_economy_{cid}",   style="success")],
        [btn("🛡 Модерация",  callback_data=f"ca_mod_{cid}",       style="danger"),
         btn("📊 Статистика", callback_data=f"ca_stats_{cid}",     style="primary")],
    ]
    if is_admin:
        trust_label = "❌ Снять доверие" if trusted else "✅ Выдать доверие (NFT)"
        trust_style = "danger" if trusted else "success"
        rows.append([btn(trust_label, callback_data=f"ca_trust_{cid}", style=trust_style)])
    rows.append([btn("❌ Закрыть", callback_data="ca_close", style="danger")])
    return InlineKeyboardMarkup(rows)


def _chatadmin_main_text(s: dict, chat_title: str) -> str:
    fund      = s.get("local_fund", 0)
    tax       = s.get("tax_rate", 0)
    threshold = s.get("auto_giveaway_threshold", 0)
    ad        = "вкл"  if s.get("auto_delete_enabled", 1)  else "выкл"
    duels     = "✅"   if s.get("allow_duels", 1)  else "❌"
    casino    = "✅"   if s.get("allow_casino", 1) else "❌"
    mode_lbl  = CHAT_MODE_LABELS.get(s.get("mode", "full"), "?")
    al_lbl    = ANNOUNCE_LEVEL_LABELS.get(s.get("announce_level", "all"), "?")
    susp      = " ⏸" if s.get("announce_suspended", 0) else ""
    return (
        f"🏘 <b>Панель чата: {he(chat_title)}</b>\n\n"
        f"🎭 Режим: <b>{mode_lbl}</b> · 📢 Анонсы: <b>{al_lbl}</b>{susp}\n"
        f"🗑 Автоудаление: <b>{ad}</b> · {_E_SWORDS} Дуэли: <b>{duels}</b> {_E_CASINO} Казино: <b>{casino}</b>\n"
        f"💰 Фонд: <b>{fund:,}🪙</b>"
        + (f"  (авторозыгрыш при {threshold:,}🪙)" if threshold else "") + "\n"
        f"{_E_CHART} Налог: <b>{tax}%</b>\n\n"
        f"<i>Выбери раздел:</i>"
    )


async def _chatadmin_list_chats(uid: int) -> list[dict]:
    """Список чатов, которыми может управлять пользователь (сортировка: новые первые)."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        if uid in ADMIN_IDS:
            async with db.execute(
                "SELECT chat_id, chat_title, trusted FROM partner_chats WHERE active=1 ORDER BY added_at DESC"
            ) as c:
                rows = await c.fetchall()
        else:
            async with db.execute(
                "SELECT chat_id, chat_title, trusted FROM partner_chats WHERE added_by_uid=? AND active=1 ORDER BY added_at DESC",
                (uid,)
            ) as c:
                rows = await c.fetchall()
    return [dict(r) for r in rows]


async def _chatadmin_check_access(uid: int, cid: int, bot) -> bool:
    """Проверяет право управлять чатом."""
    if uid in ADMIN_IDS:
        return True
    if await _is_chat_admin(bot, cid, uid):
        return True
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT added_by_uid FROM partner_chats WHERE chat_id=? AND active=1", (cid,)
        ) as c:
            row = await c.fetchone()
    return row is not None and (row[0] == uid)


