async def cmd_kvaadmin(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/kvaadmin — общая статистика NFT ивента для администратора."""
    if update.effective_user.id not in ADMIN_IDS:
        return

    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row

        # Общая статистика
        async with db.execute("""
            SELECT
                COUNT(*)                                        AS players,
                SUM(kva_count)                                  AS total_kva,
                SUM(retry_coins)                                AS total_retry_coins,
                SUM(retry_stars)                                AS total_retry_stars,
                SUM(kva_count + retry_coins + retry_stars)      AS total_tries,
                SUM(coins_spent)                                AS total_coins,
                SUM(stars_spent)                                AS total_stars,
                SUM(won_nft)                                    AS total_winners,
                MAX(best_roll)                                  AS top_roll,
                AVG(kva_count + retry_coins + retry_stars)      AS avg_tries
            FROM kva_event_stats
            WHERE (kva_count + retry_coins + retry_stars) > 0
        """) as c:
            s = await c.fetchone()

        # Топ-5 самых активных
        async with db.execute("""
            SELECT ks.user_id, ks.kva_count, ks.retry_coins, ks.retry_stars,
                   ks.coins_spent, ks.stars_spent, ks.best_roll, ks.won_nft,
                   f.first_name, f.username
            FROM kva_event_stats ks
            LEFT JOIN frogs f ON f.user_id = ks.user_id
            ORDER BY (ks.kva_count + ks.retry_coins + ks.retry_stars) DESC
            LIMIT 5
        """) as c:
            top = await c.fetchall()

    lines = [
        f"{_E_CHART} <b>Статистика NFT Chill Flame ивента</b>\n",
        f"{_E_USERS} Участников: <b>{s['players'] or 0}</b>",
        f"🎲 Всего бросков: <b>{s['total_tries'] or 0}</b>",
        f"🐸 ├ ква в доверенных: <b>{s['total_kva'] or 0}</b>",
        f"{_E_REFRESH} ├ повторов за монеты: <b>{s['total_retry_coins'] or 0}</b>",
        f"{_E_STARS} └ повторов за Stars: <b>{s['total_retry_stars'] or 0}</b>",
        f"🪙 Монет потрачено: <b>{s['total_coins'] or 0}</b>",
        f"{_E_STARS} Stars потрачено: <b>{(s['total_retry_stars'] or 0) * NFT_KVA_STARS}</b>",
        f"{_E_TROPHY} Победителей: <b>{s['total_winners'] or 0}</b>",
        f"🎯 Рекордный бросок: <b>{s['top_roll'] or 0}/{NFT_KVA_TOTAL}</b>",
        f"📈 Среднее бросков на игрока: <b>{int(s['avg_tries'] or 0)}</b>",
        f"\n<b>Топ-5 активных:</b>",
    ]

    for i, r in enumerate(top, 1):
        name = r['first_name'] or str(r['user_id'])
        uname = f" @{r['username']}" if r['username'] else ""
        nft_mark = " 🏆" if r['won_nft'] else ""
        total_tries = r['kva_count'] + r['retry_coins'] + r['retry_stars']
        lines.append(
            f"{i}. <b>{_html.escape(name)}</b>{uname}{nft_mark}\n"
            f"   {_E_FROG}{r['kva_count']} {_E_REFRESH}{r['retry_coins']} {_E_STARS}{r['retry_stars']} "
            f"({r['retry_stars'] * NFT_KVA_STARS}{_E_STARS} потрачено) "
            f"| 🎯{r['best_roll']}/{NFT_KVA_TOTAL} | всего: {total_tries}"
        )

    await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


async def cmd_trustchat(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/trustchat <chat_id> — выдать доверие чату (допускает к NFT-дропу через /ква)."""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return
    if not ctx.args:
        await update.message.reply_text(
            "Использование: <code>/trustchat -1001234567</code>\n"
            "или <code>/untrustchat -1001234567</code> для снятия.",
            parse_mode=ParseMode.HTML,
        )
        return
    try:
        cid = int(ctx.args[0])
    except ValueError:
        await update.message.reply_text("❌ Укажи числовой chat_id.")
        return
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT chat_title FROM partner_chats WHERE chat_id=? AND active=1", (cid,)) as c:
            row = await c.fetchone()
        if not row:
            await update.message.reply_text(f"{_E_CROSS} Чат <code>{cid}</code> не найден в партнёрских чатах.", parse_mode=ParseMode.HTML)
            return
        await db.execute(
            "UPDATE partner_chats SET trusted=1, trusted_at=?, trusted_by=? WHERE chat_id=?",
            (time.time(), user.id, cid),
        )
        await db.commit()
    await update.message.reply_text(
        f"{_E_CHECK} Чат <code>{cid}</code> (<b>{_html.escape(row[0] or '')}</b>) теперь <b>доверенный</b>.\n"
        f"Ква в нём участвуют в NFT-розыгрыше.",
        parse_mode=ParseMode.HTML,
    )


