            [btn(f"🤬 Фильтр мата: {pf}",                   callback_data=f"ca_toggle_prof_{cid}"),
             btn(f"⚠️ Реакция: {pw}",                        callback_data=f"ca_toggle_profwarn_{cid}")],
            [btn(f"🔕 /start в группе: {ig}",                callback_data=f"ca_toggle_start_{cid}")],
