# 🤝  /partnerinfo — информация о партнёрском статусе чата (только суперадмин)
# ══════════════════════════════════════════════════════════════════════════════

_PLAN_LABELS = {
    "free":       "🆓 Free",
    "basic":      "⭐ Basic",
    "pro":        "💎 Pro",
    "enterprise": "🏆 Enterprise",
}

_PLAN_FEATURES = {
    "free":       "Базовые режимы, стандартные скины",
    "basic":      "+ Кастомное приветствие, эксклюзивный скин",
    "pro":        "+ Revenue share, приоритетная поддержка, кастомная тема",
    "enterprise": "+ Белый лейбл, выделенный инстанс, API доступ",
}

async def cmd_partnerinfo(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/partnerinfo — просмотр и управление партнёрским статусом чата (суперадмин)."""
    user = update.effective_user
    msg  = update.message

    if user.id not in ADMIN_IDS:
        await msg.reply_text("⛔ Только суперадминистраторы.")
        return

    # Определяем целевой чат
    if ctx.args:
        try:
            cid = int(ctx.args[0])
        except ValueError:
            await msg.reply_text("❌ Укажи chat_id числом: /partnerinfo -100123456789")
            return
    elif is_group(update):
        cid = update.effective_chat.id
    else:
        # Показываем список всех партнёрских чатов
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            async with db.execute(
                "SELECT chat_id, chat_title, plan, status, added_at FROM partner_chats WHERE active=1 ORDER BY added_at DESC LIMIT 30"
            ) as c:
                rows = [dict(r) for r in await c.fetchall()]

        if not rows:
            await msg.reply_text("📋 Нет партнёрских чатов.")
            return

        lines = [f"{_E_HANDSHAKE} <b>Партнёрские чаты</b>\n"]
        for r in rows:
            plan_lbl = _PLAN_LABELS.get(r.get("plan", "free"), "?")
            added = datetime.fromtimestamp(r["added_at"]).strftime("%d.%m.%y") if r.get("added_at") else "?"
            lines.append(
                f"{plan_lbl} <b>{he(r['chat_title'] or str(r['chat_id']))}</b>\n"
                f"   <code>{r['chat_id']}</code> · {r.get('status','active')} · {added}\n"
                f"   /partnerinfo {r['chat_id']}"
            )

        await msg.reply_text("\n\n".join(lines), parse_mode=ParseMode.HTML)
        return

    # Детали конкретного чата
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM partner_chats WHERE chat_id=?", (cid,)) as c:
            pc = await c.fetchone()

    if not pc:
        await msg.reply_text(f"{_E_CROSS} Чат <code>{cid}</code> не найден в партнёрской базе.", parse_mode=ParseMode.HTML)
        return

    pc = dict(pc)
    cs = await get_chat_settings(cid)
    plan     = pc.get("plan", "free")
    plan_lbl = _PLAN_LABELS.get(plan, plan)
    plan_ft  = _PLAN_FEATURES.get(plan, "")
    mode_lbl = CHAT_MODE_LABELS.get(cs.get("mode", "full"), "?")
    al_lbl   = ANNOUNCE_LEVEL_LABELS.get(cs.get("announce_level", "all"), "?")
    wm_lbl   = WELCOME_MODE_LABELS.get(cs.get("welcome_mode", "full"), "?")
    rev      = pc.get("revenue_share", 0.0) or 0.0
    skin     = pc.get("custom_skin", "") or "—"
    notes    = pc.get("notes", "") or "—"
    added    = datetime.fromtimestamp(pc["added_at"]).strftime("%d.%m.%Y %H:%M") if pc.get("added_at") else "?"

    text = (
        f"🤝 <b>Партнёрский чат</b>\n"
        f"<b>{he(pc.get('chat_title','?'))}</b> <code>{cid}</code>\n\n"
        f"📦 План: <b>{plan_lbl}</b>\n"
        f"   <i>{plan_ft}</i>\n\n"
        f"🎭 Режим: <b>{mode_lbl}</b>\n"
        f"📢 Анонсы: <b>{al_lbl}</b>\n"
        f"👋 Приветствие: <b>{wm_lbl}</b>\n"
        f"💰 Revenue share: <b>{rev:.1f}%</b>\n"
        f"🎨 Кастомный скин: <b>{he(skin)}</b>\n\n"
        f"📝 Заметки: <i>{he(notes)}</i>\n"
        f"📅 Добавлен: {added}\n\n"
        f"<i>Кнопки ниже — управление планом и статусом.</i>"
    )

    kb = InlineKeyboardMarkup([
        [
            btn("🆓 Free",       callback_data=f"pi_plan_free_{cid}",       style="primary"),
            btn("⭐ Basic",      callback_data=f"pi_plan_basic_{cid}",      style="primary"),
        ],
        [
            btn("💎 Pro",        callback_data=f"pi_plan_pro_{cid}",        style="success"),
            btn("🏆 Enterprise", callback_data=f"pi_plan_enterprise_{cid}", style="success"),
        ],
        [btn("📝 Заметка", callback_data=f"pi_note_{cid}"), btn("🎨 Скин", callback_data=f"pi_skin_{cid}")],
        [
            btn("⏸ Приостановить", callback_data=f"pi_suspend_{cid}", style="danger"),
            btn("❌ Удалить",       callback_data=f"pi_remove_{cid}",  style="danger"),
        ],
    ])
    await msg.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)


async def _handle_partnerinfo_callback(q, uid: int, ctx):
    """Обработчик кнопок /partnerinfo."""
    if uid not in ADMIN_IDS:
        await q.answer("⛔ Нет прав.", show_alert=True)
        return

    d = q.data
    try:
        cid = int(d.split("_")[-1])
    except (ValueError, IndexError):
        await q.answer("❌ Ошибка.")
        return

    if d.startswith("pi_plan_"):
        parts   = d.split("_")
        new_plan = parts[2]  # free | basic | pro | enterprise
        if new_plan not in _PLAN_LABELS:
            await q.answer("❌ Неизвестный план.")
            return
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE partner_chats SET plan=? WHERE chat_id=?", (new_plan, cid))
            await db.commit()
        lbl = _PLAN_LABELS[new_plan]
        await q.answer(f"✅ План изменён: {lbl}")
        # Обновляем сообщение
        try:
            async with aiosqlite.connect(DB_PATH) as db:
                db.row_factory = aiosqlite.Row
                async with db.execute("SELECT * FROM partner_chats WHERE chat_id=?", (cid,)) as c:
                    pc = dict(await c.fetchone())
            cs = await get_chat_settings(cid)
            plan_lbl = _PLAN_LABELS.get(pc.get("plan","free"), "?")
            plan_ft  = _PLAN_FEATURES.get(pc.get("plan","free"), "")
            mode_lbl = CHAT_MODE_LABELS.get(cs.get("mode","full"), "?")
            al_lbl   = ANNOUNCE_LEVEL_LABELS.get(cs.get("announce_level","all"), "?")
            wm_lbl   = WELCOME_MODE_LABELS.get(cs.get("welcome_mode","full"), "?")
            rev      = pc.get("revenue_share", 0.0) or 0.0
            skin     = pc.get("custom_skin","") or "—"
            notes    = pc.get("notes","") or "—"
            added    = datetime.fromtimestamp(pc["added_at"]).strftime("%d.%m.%Y %H:%M") if pc.get("added_at") else "?"
            text = (
                f"🤝 <b>Партнёрский чат</b>\n"
                f"<b>{he(pc.get('chat_title','?'))}</b> <code>{cid}</code>\n\n"
                f"📦 План: <b>{plan_lbl}</b>\n <i>{plan_ft}</i>\n\n"
                f"🎭 Режим: <b>{mode_lbl}</b>\n"
                f"📢 Анонсы: <b>{al_lbl}</b>\n"
                f"👋 Приветствие: <b>{wm_lbl}</b>\n"
                f"💰 Revenue share: <b>{rev:.1f}%</b>\n"
                f"🎨 Кастомный скин: <b>{he(skin)}</b>\n\n"
                f"📝 Заметки: <i>{he(notes)}</i>\n"
                f"📅 Добавлен: {added}\n\n"
                f"<i>Кнопки ниже — управление планом и статусом.</i>"
            )
            kb = InlineKeyboardMarkup([
                [btn("🆓 Free", callback_data=f"pi_plan_free_{cid}", style="primary"),
                 btn("⭐ Basic", callback_data=f"pi_plan_basic_{cid}", style="primary")],
                [btn("💎 Pro", callback_data=f"pi_plan_pro_{cid}", style="success"),
                 btn("🏆 Enterprise", callback_data=f"pi_plan_enterprise_{cid}", style="success")],
                [btn("📝 Заметка", callback_data=f"pi_note_{cid}"), btn("🎨 Скин", callback_data=f"pi_skin_{cid}")],
                [btn("⏸ Приостановить", callback_data=f"pi_suspend_{cid}", style="danger"),
                 btn("❌ Удалить", callback_data=f"pi_remove_{cid}", style="danger")],
            ])
            await q.message.edit_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)

    elif d.startswith("pi_suspend_"):
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE partner_chats SET status='paused', active=0 WHERE chat_id=?", (cid,))
            await db.commit()
        await q.answer(f"⏸ Чат {cid} приостановлен.")
        try: await q.message.edit_reply_markup(None)
        except (BadRequest, Forbidden, TimedOut):
            pass

    elif d.startswith("pi_remove_"):
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE partner_chats SET active=0, status='suspended' WHERE chat_id=?", (cid,))
            await db.commit()
        await q.answer(f"❌ Чат {cid} удалён из партнёров.")
        try: await q.message.edit_reply_markup(None)
        except (BadRequest, Forbidden, TimedOut):
            pass

    elif d.startswith("pi_note_"):
        ctx.user_data[f"pi_input_{uid}"] = {"field": "notes", "cid": cid}
        await q.answer()
        await q.message.reply_text(
            f"📝 Введи заметку для чата <code>{cid}</code>:",
            parse_mode=ParseMode.HTML,
        )

    elif d.startswith("pi_skin_"):
        ctx.user_data[f"pi_input_{uid}"] = {"field": "custom_skin", "cid": cid}
        await q.answer()
        await q.message.reply_text(
            f"🎨 Введи ключ кастомного скина для чата <code>{cid}</code>:",
            parse_mode=ParseMode.HTML,
        )
    else:
        await q.answer()


async def cmd_toplocal(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/toplocal — топ игроков текущего/своего чата."""
    chat = update.effective_chat
    user = update.effective_user

    if is_group(update):
        source_cid = chat.id
        chat_label = he(chat.title or str(chat.id))
    else:
        f = await db_get(user.id)
        source_cid = f.get("source_chat_id", 0) if f else 0
        if not source_cid:
            await update.message.reply_text(
                "🏘 Ты пришёл напрямую, а не через партнёрский чат.\n"
                "Эта команда показывает топ игроков конкретного чата.\n"
                "Используй /top для глобального топа."
            )
            return
        pc = await partner_chat_get(source_cid)
        chat_label = he(pc["chat_title"]) if pc else f"Чат {source_cid}"

    rows = await db_top_chat(source_cid, 10)
    if not rows:
        await update.message.reply_text(
            f"🏘 Пока нет игроков из чата <b>{chat_label}</b>.\n"
            f"Пригласи друзей — нажмите кнопку «Начать игру» в чате!",
            parse_mode=ParseMode.HTML,
        )
        return

    medals = ["🥇", "🥈", "🥉"] + ["4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"]
    lines = [f"🏘 <b>Топ чата: {chat_label}</b>\n"]
    top_ids = set()
    for i, row in enumerate(rows):
        top_ids.add(row["user_id"])
        name = he(row.get("frog_name") or row.get("first_name", "?"))
        lvl = row.get("level", 1)
        alive_icon = "🐸" if row.get("alive") else "💀"
        medal = medals[i] if i < len(medals) else f"{i+1}."
        lines.append(f"{medal} {alive_icon} <b>{name}</b> — ур. {lvl}")

    # Показываем позицию пользователя если не в топ-10
    if user.id not in top_ids:
        rank, total = await db_get_rank_chat(user.id, source_cid)
        uf = await db_get(user.id)
        if uf and rank:
            uname = he(uf.get("frog_name") or f"Лягушка {uf.get('first_name','?')}")
            dead = "💀" if not uf.get("alive") else "<tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji>"
            lines.append(f"\n┄┄┄┄┄┄┄┄┄┄")
            lines.append(f"#{rank}/{total} {dead} <b>{uname}</b> — ур. {uf.get('level',1)}")

    total_members = await partner_chat_count_members(source_cid)
    lines.append(f"\n<i>Всего игроков из этого чата: {total_members}</i>")

    msg = await update.message.reply_text(
        "\n".join(lines),
        parse_mode=ParseMode.HTML,
    )
    if msg and is_group(update):
        asyncio.create_task(schedule_delete(update.get_bot(), msg.chat.id, msg.message_id))





def _detect_lang(user) -> str:
    """Автоопределение языка по Telegram locale пользователя."""
    try:
        lc = (user.language_code or "ru").lower()
        if lc.startswith("zh"):
            return "zh"
        if lc.startswith("en"):
            return "en"
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)
    return "ru"


