def is_group(update: Update) -> bool:
    return update.effective_chat.type in ("group", "supergroup")


async def group_cmd_guard(update: Update, cmd: str, ctx: ContextTypes.DEFAULT_TYPE = None) -> bool:
    """
    Возвращает True если команду можно выполнить.
    Если в группе и команда не разрешена — отправляет подсказку и возвращает False.
    Учитывает режим чата: vanilla → редирект в ЛС, readonly → тихое игнорирование.
    """
    if not is_group(update):
        return True

    chat_id = update.effective_chat.id
    mode = await get_chat_mode(chat_id)

    if mode == "readonly":
        # Тихо игнорируем все команды в readonly
        try:
            await update.message.delete()
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
        return False

    if mode == "vanilla" and ctx is not None:
        # В vanilla — редирект в ЛС вместо ответа в чат
        await vanilla_redirect(update, ctx, cmd)
        return False

    if cmd in GROUP_ALLOWED_CMDS:
        return True

    tip = await update.message.reply_text(
        f"📱 Команда <code>/{cmd}</code> доступна только в личных сообщениях с ботом.",
        parse_mode=ParseMode.HTML,
    )
    asyncio.create_task(
        schedule_delete(update.get_bot(), tip.chat.id, tip.message_id, 30)
    )
    return False


