# 🔗 РЕФЕРАЛЬНАЯ СИСТЕМА
# ══════════════════════════════════════════
# Этапы: (индекс_бита, описание, КваКоины, предмет или None, тип_условия, значение_условия)
REFERRAL_STAGES = [
    (0, "Реферал зарегистрировался", 50, None, "register", 1),
    (1, "Реферал покормил 5 раз", 100, "fly", "feeds", 5),
    (2, "Реферал достиг 5 уровня", 200, None, "level", 5),
    (3, "Реферал потратил 1500🪙", 300, None, "coins_spent", 1500),
]
MAX_REFERRAL_COINS = 650  # максимум КваКоинов с одного реферала


async def _referral_stage_reward(
    referrer_id: int, referred_id: int, stage_idx: int, bot
):
    """Проверяет и выдаёт награду за реферальный этап (если ещё не выдавалась)."""
    bit = 1 << stage_idx
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT stage_mask, rewarded_coins FROM referrals WHERE referrer_id=? AND referred_id=?",
            (referrer_id, referred_id),
        ) as c:
            row = await c.fetchone()
    if not row:
        return
    mask, already_coins = row
    if mask & bit:
        return  # уже выдано
    stage = REFERRAL_STAGES[stage_idx]
    coins = stage[2]
    item = stage[3]
    # Проверяем лимит КваКоинов
    if already_coins + coins > MAX_REFERRAL_COINS:
        coins = max(0, MAX_REFERRAL_COINS - already_coins)
    new_mask = mask | bit
    new_coins = already_coins + coins
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE referrals SET stage_mask=?, rewarded_coins=? WHERE referrer_id=? AND referred_id=?",
            (new_mask, new_coins, referrer_id, referred_id),
        )
        await db.commit()
    # Выдаём КваКоины рефереру
    if coins > 0:
        ref_f = await db_get(referrer_id)
        if ref_f:
            ref_f["coins"] += coins
            await db_save(ref_f)
    # Выдаём предмет
    if item:
        await inv_add(referrer_id, item)
    # Уведомляем реферера
    if bot:
        desc = stage[1]
        reward_txt = f"+{coins}{coin_emoji()}" if coins > 0 else ""
        item_txt = f"  +{item}" if item else ""
        try:
            await bot.send_message(
                referrer_id,
                f"🎉 <b>Реферальная награда!</b>\n\n"
                f"Этап: <i>{desc}</i>\n"
                f"{reward_txt}{item_txt}\n\n"
                f"Используй /referral чтобы видеть всех рефералов.",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass


async def check_referral_stages(referred_f: dict, bot):
    """Проверяет реферальные этапы после обновления прогресса реферала."""
    uid = referred_f["user_id"]
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT referrer_id, stage_mask FROM referrals WHERE referred_id=?", (uid,)
        ) as c:
            row = await c.fetchone()
    if not row:
        return
    referrer_id, mask = row
    # Этап 2: 5 кормлений
    if referred_f.get("total_feeds", 0) >= 5 and not (mask & 2):
        await _referral_stage_reward(referrer_id, uid, 1, bot)
    # Этап 3: уровень 5
    if referred_f.get("level", 1) >= 5 and not (mask & 4):
        await _referral_stage_reward(referrer_id, uid, 2, bot)
    # Этап 4: потрачено 1500 КваКоинов
    if referred_f.get("coins_spent", 0) >= 1500 and not (mask & 8):
        await _referral_stage_reward(referrer_id, uid, 3, bot)

    # ── Фриз-ивент: кубики за активного реферала (достиг уровня 3) ───────────
    if referred_f.get("level", 1) >= 3 and await _fz_active():
        async with aiosqlite.connect(DB_PATH) as db:
            # Проверяем лимит (FZ_REF_LIMIT) и что ещё не начисляли за этого реферала
            async with db.execute(
                "SELECT 1 FROM freeze_refs WHERE referrer_id=? AND referred_id=?",
                (referrer_id, uid),
            ) as c:
                already = await c.fetchone()
        if not already:
            ref_f = await db_get(referrer_id)
            if ref_f and ref_f.get("fz_ref_count", 0) < FZ_REF_LIMIT:
                async with aiosqlite.connect(DB_PATH) as db:
                    await db.execute(
                        "INSERT OR IGNORE INTO freeze_refs(referrer_id, referred_id, ts) VALUES(?,?,?)",
                        (referrer_id, uid, time.time()),
                    )
                    await db.commit()
                ref_f["fz_ref_count"] = ref_f.get("fz_ref_count", 0) + 1
                await db_save(ref_f)
                for _ in range(FZ_REF_CUBES):
                    asyncio.create_task(_fz_throw(referrer_id, "free_ref", bot))
                try:
                    await bot.send_message(
                        referrer_id,
                        f"🧊 <b>+{FZ_REF_CUBES} кубиков льда!</b>\n"
                        f"Твой реферал достиг 3 уровня — ты получаешь кубики Фриз-ивента!\n"
                        f"<i>Лимит: {FZ_REF_LIMIT} рефералов за ивент. "
                        f"Использовано: {ref_f['fz_ref_count']}/{FZ_REF_LIMIT}</i>",
                        parse_mode=ParseMode.HTML,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass

    # ── Конкурс: валидируем тикет при достижении 2-го уровня ─────────────────
    # Тикет засчитывается именно на 2-м уровне — достаточный порог активности
    if referred_f.get("level", 1) >= 2:
        await _try_validate_contest_ticket(uid)


async def cmd_referral(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/referral — реферальная программа"""
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return
    bot_username = (await ctx.bot.get_me()).username
    ref_link = f"https://t.me/{bot_username}?start=ref_{user.id}"

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT referred_id, stage_mask, rewarded_coins FROM referrals WHERE referrer_id=?",
            (user.id,),
        ) as c:
            refs = await c.fetchall()

    total = len(refs)
    total_stages = sum(bin(r[1]).count("1") for r in refs)
    total_earned = sum(r[2] for r in refs)

    # Описание этапов
    stage_lines = []
    icons = ["1️⃣", "2️⃣", "3️⃣", "4️⃣"]
    rewards_desc = [
        f"+{REFERRAL_STAGES[0][2]}{coin_emoji()}",
        f"+{REFERRAL_STAGES[1][2]}{coin_emoji()} + 🪰 Муха",
        f"+{REFERRAL_STAGES[2][2]}{coin_emoji()}",
        f"+{REFERRAL_STAGES[3][2]}{coin_emoji()}",
    ]
    conditions = [
        "Реферал создал лягушку",
        "Реферал покормил 5 раз",
        "Реферал достиг 5 уровня",
        f"Реферал потратил 1500{coin_emoji()}",
    ]
    for i, (icon, cond, rew) in enumerate(zip(icons, conditions, rewards_desc)):
        stage_lines.append(f"{icon} {cond} → <b>{rew}</b>")

    lines = [
        f"🔗 <b>Реферальная программа</b>\n",
        f"Твоя ссылка:",
        f"<code>{ref_link}</code>\n",
        f"<b>Этапы наград за каждого реферала:</b>",
        *stage_lines,
        f"\n<i>Максимум {MAX_REFERRAL_COINS}{coin_emoji()} с одного реферала. </i>\n",
        f"{_E_USERS} Приглашено: <b>{total}</b>",
        f"✅ Этапов выполнено: <b>{total_stages}</b>",
        f"{coin_emoji()}{_E_COIN} заработано: <b>{total_earned}</b>",
    ]
    if refs:
        lines.append("\n<b>Твои рефералы:</b>")
        ref_data = []
        for referred_id, mask, earned in refs:
            rf = await db_get(referred_id)
            if not rf:
                continue
            # Получаем актуальный username из Telegram
            tg_username = None
            try:
                tg_chat = await ctx.bot.get_chat(referred_id)
                tg_username = tg_chat.username or None
            except (BadRequest, Forbidden, TimedOut):
                pass
            ref_data.append((rf, mask, earned, tg_username))
        ref_data.sort(key=lambda x: x[0].get("level", 1), reverse=True)
        for rf, mask, earned, tg_username in ref_data[:20]:
            lvl = rf.get("level", 1)
            stage_icons = "".join("✅" if (mask & (1 << i)) else "🕓" for i in range(len(REFERRAL_STAGES)))
            if tg_username:
                name_str = f'<a href="https://t.me/{tg_username}">@{_html.escape(tg_username)}</a>'
            else:
                n = rf.get("frog_name") or rf.get("first_name") or "?"
                name_str = he(n)
            lines.append(f"{name_str} — ур.{lvl} {stage_icons}")
        if len(ref_data) > 20:
            lines.append(f"<i>...и ещё {len(ref_data)-20}</i>")
    lines.append(f"\n<i>Приглашай друзей — получай КваКоины и предметы</i>")
    await update.message.reply_text(
        "\n".join(lines),
        parse_mode=ParseMode.HTML,
        link_preview_options=LinkPreviewOptions(is_disabled=True),
    )


async def is_trusted_referrer(uid: int) -> bool:
    """Инфлюэнсер в whitelist → его рефералы не проверяются."""
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT 1 FROM trusted_referrers WHERE user_id=?", (uid,)) as c:
            return (await c.fetchone()) is not None


async def _antibot_check(referrer_id: int, referred_uid: int, user) -> tuple[bool, str]:
    """
    Проверяет нового реферала на признаки накрутки.
    Возвращает (suspect: bool, reason: str).
    Если referrer_id в trusted_referrers — всегда (False, "").
    """
    # Инфлюэнсеры — не проверяем
    if await is_trusted_referrer(referrer_id):
        return False, ""

    reasons = []

    # 1. Нет username и нет first_name (типичный фейк-аккаунт)
    if not user.username and not user.last_name:
        reasons.append("no_username_no_lastname")

    # 2. Telegram user_id подозрительно «свежий» (очень большой ID → новый аккаунт)
    # Боты-спамеры массово регают аккаунты. ID > 7_000_000_000 — созданы после 2023-06.
    # Настоящие игроки тоже бывают, поэтому это лишь сигнал, не блок.
    if referred_uid > 7_000_000_000:
        reasons.append("fresh_tg_account")

    # 3. Реферер уже имеет много рефералов за последний час
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(*) FROM referrals WHERE referrer_id=? AND joined_at > ?",
            (referrer_id, time.time() - 3600),
        ) as c:
            refs_last_hour = (await c.fetchone())[0]
        async with db.execute(
            "SELECT COUNT(*) FROM referrals WHERE referrer_id=? AND joined_at > ?",
            (referrer_id, time.time() - 86400),
        ) as c:
            refs_last_day = (await c.fetchone())[0]

    # > 30 рефералов за час или > 200 за сутки — подозрительно
    if refs_last_hour > 30:
        reasons.append(f"burst_hourly:{refs_last_hour}")
    if refs_last_day > 200:
        reasons.append(f"burst_daily:{refs_last_day}")

    # 4. Реферер уже помечен как накрутчик (есть неразобранные suspects)
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(*) FROM ref_fraud_suspects WHERE referrer_id=? AND verdict='pending'",
            (referrer_id,),
        ) as c:
            pending_flags = (await c.fetchone())[0]

    if pending_flags > 10:
        reasons.append(f"referrer_flagged:{pending_flags}")

    if reasons:
        return True, ",".join(reasons)
    return False, ""


async def _freeze_ref_reward(referrer_id: int, referred_id: int, reason: str) -> None:
    """Записывает подозрительный реферал — бот НЕ выдаёт награду немедленно."""
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT OR IGNORE INTO ref_fraud_suspects(referrer_id, referred_id, reason, detected_at) VALUES(?,?,?,?)",
            (referrer_id, referred_id, reason, time.time()),
        )
        await db.commit()


async def _unfreeze_ref_reward(referrer_id: int, referred_id: int, bot) -> None:
    """Выдаёт замороженную реф.награду (после ручного одобрения)."""
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE ref_fraud_suspects SET reviewed=1, verdict='approved' WHERE referrer_id=? AND referred_id=?",
            (referrer_id, referred_id),
        )
        await db.commit()
    await _referral_stage_reward(referrer_id, referred_id, 0, bot)


