# 💾  АВТОБЭКАП БД
# ══════════════════════════════════════════════════════════════════════════════

BACKUP_DIR = "db_backups"
BACKUP_KEEP = 7  # хранить последние N бэкапов


async def make_db_backup(bot=None, notify_admin: bool = False) -> str:
    """
    Создаёт копию frog_game.db → db_backups/frog_YYYY-MM-DD_HH-MM.db
    Удаляет старые бэкапы, оставляя BACKUP_KEEP последних.
    Возвращает путь к новому файлу.
    """
    import glob
    os.makedirs(BACKUP_DIR, exist_ok=True)
    ts = datetime.now().strftime("%Y-%m-%d_%H-%M")
    dest = os.path.join(BACKUP_DIR, f"frog_{ts}.db")
    # Безопасная копия через SQLite backup API
    src_conn = sqlite3.connect(DB_PATH)
    dst_conn = sqlite3.connect(dest)
    src_conn.backup(dst_conn)
    src_conn.close()
    dst_conn.close()
    # Ротация: удаляем лишние
    backups = sorted(glob.glob(os.path.join(BACKUP_DIR, "frog_*.db")))
    while len(backups) > BACKUP_KEEP:
        try:
            os.remove(backups.pop(0))
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
    size_kb = os.path.getsize(dest) // 1024
    if notify_admin and bot and ADMIN_IDS:
        for aid in ADMIN_IDS:
            try:
                await bot.send_document(
                    chat_id=aid,
                    document=open(dest, "rb"),
                    caption=f"💾 <b>Автобэкап БД</b>\n{ts}\nРазмер: {size_kb} KB",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
    return dest


async def auto_backup_loop(bot) -> None:
    """Запускается как фоновая задача. Бэкапит БД каждые 6 часов."""
    while True:
        await asyncio.sleep(6 * 3600)
        try:
            path = await make_db_backup(bot=bot, notify_admin=False)
            print(f"💾 Автобэкап: {path}")
        except Exception as e:
            print(f"⚠️ Ошибка автобэкапа: {e}")


async def cmd_backup(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/backup — ручной бэкап БД (только для админов)"""
    if update.effective_user.id not in ADMIN_IDS:
        return
    msg = await update.message.reply_text("💾 Создаю бэкап...")
    try:
        import gzip
        path = await make_db_backup(bot=ctx.bot, notify_admin=False)
        size_kb = os.path.getsize(path) // 1024
        gz_path = path + ".gz"
        with open(path, "rb") as f_in, gzip.open(gz_path, "wb") as f_out:
            f_out.write(f_in.read())
        gz_size_kb = os.path.getsize(gz_path) // 1024
        await msg.edit_text(
            f"{_E_CHECK} Бэкап создан: <code>{path}</code>\nРазмер: {size_kb} KB → сжато: {gz_size_kb} KB",
            parse_mode=ParseMode.HTML
        )
        await ctx.bot.send_document(
            chat_id=update.effective_user.id,
            document=open(gz_path, "rb"),
            filename=os.path.basename(gz_path),
            caption=f"💾 Бэкап БД · {size_kb} KB (сжато: {gz_size_kb} KB)",
        )
        try:
            os.remove(gz_path)
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
    except Exception as e:
        await msg.edit_text(f"{_E_CROSS} Ошибка бэкапа: {he(e)}", parse_mode=ParseMode.HTML)


