async def handle_antibot_callback(q, d, uid, ctx):
    if uid not in ADMIN_IDS:
        await q.answer("Нет доступа", show_alert=True); return

    if d == "aab_refresh":
        await show_antibot_panel(q.message, ctx, edit=True); return

    if d == "aab_backup":
        await q.answer("Создаю бэкап...")
        try:
            path = await make_db_backup(bot=ctx.bot, notify_admin=False)
            size_kb = os.path.getsize(path) // 1024
            await ctx.bot.send_document(
                chat_id=uid,
                document=open(path, "rb"),
                caption=f"💾 Бэкап БД · {size_kb} KB",
            )
        except Exception as e:
            await q.answer((f"Ошибка: {e}")[:200], show_alert=True)
        return

    if d.startswith("aab_pending_"):
        page = int(d.split("_")[-1])
        per = 5
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT referrer_id, referred_id, reason, detected_at FROM ref_fraud_suspects "
                "WHERE verdict='pending' ORDER BY detected_at DESC LIMIT ? OFFSET ?",
                (per, page * per),
            ) as c:
                rows = await c.fetchall()
            async with db.execute(
                "SELECT COUNT(*) FROM ref_fraud_suspects WHERE verdict='pending'"
            ) as c:
                total = (await c.fetchone())[0]
        if not rows:
            await q.answer("Нет подозрительных рефералов", show_alert=True); return
        lines = [f"⏳ <b>Подозрительные рефералы</b> (стр {page+1}, всего {total})\n"]
        for ref_er, ref_ed, reason, det_at in rows:
            dt = datetime.fromtimestamp(det_at).strftime("%d.%m %H:%M")
            lines.append(f"• Реферер <code>{ref_er}</code> → Игрок <code>{ref_ed}</code>\n Причина: <i>{reason}</i> [{dt}]")
        buttons = []
        for ref_er, ref_ed, *_ in rows:
            # Получаем кол-во ботов у этого реферера
            async with aiosqlite.connect(DB_PATH) as db2:
                async with db2.execute(
                    "SELECT COUNT(*) FROM ref_fraud_suspects WHERE referrer_id=? AND verdict='pending'",
                    (ref_er,),
                ) as c2:
                    bot_count = (await c2.fetchone())[0]
            buttons.append([
                btn(f"✅ Легит", callback_data=f"aab_ok_{ref_er}_{ref_ed}", style="success"),
                btn(f"🔍 Расследовать ({bot_count} подозр.)", callback_data=f"aab_investigate_{ref_er}", style="danger"),
            ])
        nav = []
