async def cmd_adminaddtrust(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminaddtrust [user_id] [заметка] — добавить инфлюэнсера в whitelist"""
    if update.effective_user.id not in ADMIN_IDS: return
    args = update.message.text.split(None, 2)
    if len(args) < 2:
        await update.message.reply_text("Использование: /adminaddtrust 123456789 Имя инфлюэнсера"); return
    try:
        target_id = int(args[1])
    except ValueError:
        await update.message.reply_text("ID должен быть числом"); return
    note = args[2] if len(args) > 2 else ""
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT OR REPLACE INTO trusted_referrers(user_id, added_by, note, added_at) VALUES(?,?,?,?)",
            (target_id, update.effective_user.id, note, time.time()),
        )
        await db.commit()
    tf = await db_get(target_id)
    name = tf.get("first_name", "?") if tf else "?"
    await update.message.reply_text(
        f"{_E_STARS} <b>{_html.escape(name)}</b> (<code>{target_id}</code>) добавлен в whitelist.\n"
        f"Его рефералы теперь не проверяются на накрутку.",
        parse_mode=ParseMode.HTML,
    )


async def cmd_adminremovetrust(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminremovetrust [user_id] — убрать из whitelist"""
    if update.effective_user.id not in ADMIN_IDS: return
    args = update.message.text.split()
    if len(args) < 2:
        await update.message.reply_text("Использование: /adminremovetrust 123456789"); return
    try:
        target_id = int(args[1])
    except ValueError:
        await update.message.reply_text("ID должен быть числом"); return
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("DELETE FROM trusted_referrers WHERE user_id=?", (target_id,))
        await db.commit()
    await update.message.reply_text(f"{_E_CHECK} <code>{target_id}</code> убран из whitelist.", parse_mode=ParseMode.HTML)


async def cmd_adminfraud(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminfraud [referrer_id] — показать подозрительные рефералы конкретного реферера"""
    if update.effective_user.id not in ADMIN_IDS: return
    args = update.message.text.split()
    if len(args) < 2:
        await update.message.reply_text("Использование: /adminfraud 123456789"); return
    try:
        ref_id = int(args[1])
    except ValueError:
        await update.message.reply_text("ID должен быть числом"); return
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT referred_id, reason, detected_at, verdict FROM ref_fraud_suspects WHERE referrer_id=? ORDER BY detected_at DESC LIMIT 50",
            (ref_id,),
        ) as c:
            rows = await c.fetchall()
        async with db.execute("SELECT COUNT(*) FROM referrals WHERE referrer_id=?", (ref_id,)) as c:
            total_refs = (await c.fetchone())[0]
    tf = await db_get(ref_id)
    name = tf.get("first_name", "?") if tf else "?"
    is_trusted = await is_trusted_referrer(ref_id)
    lines = [
        f"{_E_SEARCH} <b>Реферер {_html.escape(name)}</b> <code>{ref_id}</code>\n"
        f"Всего рефералов: {total_refs} · Whitelist: {f'{_E_STARS} ДА' if is_trusted else f'{_E_CROSS} Нет'}\n"
    ]
    for ref_ed, reason, det_at, verdict in rows:
        dt = datetime.fromtimestamp(det_at).strftime("%d.%m %H:%M")
        v_icon = {"pending": "⏳", "approved": "✅", "rejected": "🚫"}.get(verdict, "?")
        lines.append(f"  {v_icon} <code>{ref_ed}</code> <i>{reason}</i> [{dt}]")
    await update.message.reply_text("\n".join(lines) or "Подозрительных нет.", parse_mode=ParseMode.HTML)


async def cmd_adminapprove(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminapprove [referrer_id] — одобрить все pending рефералы реферера и выдать награды"""
    if update.effective_user.id not in ADMIN_IDS: return
    args = update.message.text.split()
    if len(args) < 2: await update.message.reply_text("Использование: /adminapprove 123456789"); return
    try: ref_id = int(args[1])
    except ValueError: await update.message.reply_text("ID числом"); return
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT referred_id FROM ref_fraud_suspects WHERE referrer_id=? AND verdict='pending'", (ref_id,)
        ) as c:
            rows = await c.fetchall()
    count = 0
    for (ref_ed,) in rows:
        await _unfreeze_ref_reward(ref_id, ref_ed, ctx.bot)
        count += 1
    await update.message.reply_text(f"{_E_CHECK} Одобрено {count} рефералов реферера <code>{ref_id}</code>. Награды выданы.", parse_mode=ParseMode.HTML)


async def cmd_adminreject(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminreject [referrer_id] — отклонить все pending и забанить реферера"""
    if update.effective_user.id not in ADMIN_IDS: return
    args = update.message.text.split()
    if len(args) < 2: await update.message.reply_text("Использование: /adminreject 123456789"); return
    try: ref_id = int(args[1])
    except ValueError: await update.message.reply_text("ID числом"); return
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT referred_id FROM ref_fraud_suspects WHERE referrer_id=? AND verdict='pending'", (ref_id,)
        ) as c:
            rows = await c.fetchall()
        await db.execute(
            "UPDATE ref_fraud_suspects SET reviewed=1, verdict='rejected' WHERE referrer_id=?", (ref_id,)
        )
        # Помечаем всех referred как боты
        for (ref_ed,) in rows:
            await db.execute("UPDATE frogs SET is_bot=1 WHERE user_id=?", (ref_ed,))
        await db.commit()
    f_r = await db_get(ref_id)
    if f_r:
        f_r["banned"] = 1; await db_save(f_r)
    await update.message.reply_text(
        f"{_E_BAN} Реферер <code>{ref_id}</code> забанен. {len(rows)} рефералов помечены как боты.",
        parse_mode=ParseMode.HTML,
    )


async def cmd_admintp(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/admintp [referrer_id] — показать статистику накрутки реферера"""
    await cmd_adminfraud(update, ctx)


async def cmd_adminbackup(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminbackup — алиас /backup"""
    await cmd_backup(update, ctx)


# ══════════════════════════════════════════════════════════════════════════════
# 📋  /adminlogs — скачать файл логов прямо в Telegram
# ══════════════════════════════════════════════════════════════════════════════

async def cmd_adminsales(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminsales [дней] — что покупают и с какой конверсией."""
    if update.effective_user.id not in ADMIN_IDS:
        return
    try:
        days = max(1, min(int(ctx.args[0]), 90)) if ctx.args else 7
    except (ValueError, IndexError):
        days = 7

    rows = await sales_report(days)
    if not rows:
        await update.message.reply_text(
            f"{_E_CHART} Продаж за {days} дн. нет.\n"
            f"<i>Счётчики пишутся с момента установки этой версии.</i>",
            parse_mode=ParseMode.HTML,
        )
        return

    total_stars = sum(r[3] for r in rows)
    total_buys = sum(r[2] for r in rows)
    lines = [
        ui_title(_E_CHART, f"Продажи за {days} дн."),
        ui_line(f"{total_buys} покупок", f"{total_stars}{_E_STARS}"),
        "",
    ]
    for sku, shown, bought, stars in rows:
        # Показы считаются не у всех позиций — конверсию пишем только там, где есть
        conv = f" · {bought * 100 // shown}%" if shown else ""
        lines.append(f"<code>{sku}</code>\n  {bought} × {stars}{_E_STARS}{conv}")
    await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


async def cmd_adminfunnel(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminfunnel [дней] — сколько новичков доходит до каждого шага знакомства."""
    if update.effective_user.id not in ADMIN_IDS:
        return
    try:
        days = max(1, min(int(ctx.args[0]), 90)) if ctx.args else 7
    except (ValueError, IndexError):
        days = 7

    data = await funnel_report(days)
    started = data.get("1", 0)
    if not started:
        await update.message.reply_text(
            f"{_E_CHART} Новичков за {days} дн. нет.\n"
            f"<i>Счётчик пишется с момента установки этой версии.</i>",
            parse_mode=ParseMode.HTML,
        )
        return

    names = {
        "1": "Открыл бота",
        "2": "Покормил",
        "3": "Поиграл",
        "4": "Искупал",
        "done": "Назвал и дошёл",
    }
    lines = [ui_title(_E_CHART, f"Знакомство за {days} дн."), ""]
    for key, label in names.items():
        n = data.get(key, 0)
        pct = n * 100 // started
        lines.append(f"<code>{bar(pct)}</code> {n} · {label}")
    lost = started - data.get("done", 0)
    lines.append(f"\n<i>Не дошло: {lost} из {started}</i>")
    await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


async def cmd_adminlogs(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /adminlogs [N] — прислать последние N строк лога в ЛС.

    Без аргумента: присылает весь файл bot.log как документ.
    С числом:       вырезает последние N строк и присылает как текстовый файл.

    Примеры:
      /adminlogs          — скачать полный bot.log
      /adminlogs 100      — последние 100 строк
      /adminlogs errors   — только строки с ERROR / CRITICAL
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("⛔ Нет прав.")
        return

    msg = update.message
    args = ctx.args or []

    log_path = LOG_FILE  # "bot.log" (задано в конфиге логов)

    # Проверяем что файл существует
    if not os.path.exists(log_path):
        await msg.reply_text(
            f"⚠️ Файл логов <code>{log_path}</code> не найден.\n"
            "Бот ещё не записал ни одной строки или LOG_FILE задан иначе.",
            parse_mode=ParseMode.HTML,
        )
        return

    file_size = os.path.getsize(log_path)
    size_kb = file_size / 1024

    # Режим: логи конкретного игрока — /adminlogs @username или /adminlogs 123456
    if args and (args[0].startswith("@") or args[0].isdigit()):
        lookup = args[0].lstrip("@")
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            if lookup.isdigit():
                async with db.execute("SELECT user_id, first_name, username FROM frogs WHERE user_id=?", (int(lookup),)) as c:
                    prow = await c.fetchone()
            else:
                async with db.execute("SELECT user_id, first_name, username FROM frogs WHERE username=?", (lookup,)) as c:
                    prow = await c.fetchone()
        if not prow:
            await msg.reply_text(f"{_E_CROSS} Игрок <code>{lookup}</code> не найден.", parse_mode=ParseMode.HTML)
            return
        target_uid_al = prow["user_id"]
        pname_al = prow["first_name"] or "?"

        import io as _io

        async with aiosqlite.connect(DB_PATH) as _dball:
            _dball.row_factory = aiosqlite.Row

            # Профиль игрока
            async with _dball.execute(
                "SELECT * FROM frogs WHERE user_id=?", (target_uid_al,)
            ) as _c:
                frow_al = await _c.fetchone()

            # Admin log (действия администраторов над игроком)
            async with _dball.execute(
                "SELECT * FROM admin_logs WHERE target_id=? ORDER BY ts DESC LIMIT 100",
                (target_uid_al,)
            ) as _c:
                log_rows_al = [dict(r) for r in await _c.fetchall()]

            # Coin log
            async with _dball.execute(
                "SELECT amount, reason, ts FROM coin_log WHERE user_id=? ORDER BY ts DESC LIMIT 500",
                (target_uid_al,)
            ) as _c:
                coin_rows_al = [dict(r) for r in await _c.fetchall()]

            # Дуэли
            async with _dball.execute(
                "SELECT * FROM duels WHERE (challenger_id=? OR target_id=?) ORDER BY created_at DESC LIMIT 50",
                (target_uid_al, target_uid_al)
            ) as _c:
                duel_rows_al = [dict(r) for r in await _c.fetchall()]

            # Походы (adventures)
            async with _dball.execute(
                "SELECT * FROM adventures WHERE (user1_id=? OR user2_id=?) ORDER BY started_at DESC LIMIT 30",
                (target_uid_al, target_uid_al)
            ) as _c:
                adv_rows_al = [dict(r) for r in await _c.fetchall()]

            # Экспедиции
            exp_rows_al = []
            try:
                async with _dball.execute(
                    """SELECT e.biome, e.status, e.started_at, e.finished_at,
                              em.coins_taken, em.coins_gained, em.coins_lost,
                              em.status as mem_status, em.contribution, em.betrayal_done
                       FROM expedition_members em
                       JOIN expeditions e ON e.id = em.expedition_id
                       WHERE em.user_id=? ORDER BY e.started_at DESC LIMIT 20""",
                    (target_uid_al,)
                ) as _c:
                    exp_rows_al = [dict(r) for r in await _c.fetchall()]
            except Exception as _e:
                logger.warning("adminlogs: expeditions query failed: %s", _e)

            # Подарки отправленные
            gifts_sent_al = []
            try:
                async with _dball.execute(
                    "SELECT to_id, amount, ts FROM gift_log WHERE from_id=? ORDER BY ts DESC LIMIT 50",
                    (target_uid_al,)
                ) as _c:
                    gifts_sent_al = [dict(r) for r in await _c.fetchall()]
            except Exception as _e:
                logger.warning("adminlogs: gift_log sent query failed: %s", _e)

            # Подарки полученные
            gifts_recv_al = []
            try:
                async with _dball.execute(
                    "SELECT from_id, amount, ts FROM gift_log WHERE to_id=? ORDER BY ts DESC LIMIT 50",
                    (target_uid_al,)
                ) as _c:
                    gifts_recv_al = [dict(r) for r in await _c.fetchall()]
            except Exception as _e:
                logger.warning("adminlogs: gift_log recv query failed: %s", _e)

            # Рефералы
            refs_al = []
            try:
                async with _dball.execute(
                    "SELECT referred_id, joined_at FROM referrals WHERE referrer_id=? ORDER BY joined_at DESC LIMIT 30",
                    (target_uid_al,)
                ) as _c:
                    refs_al = [dict(r) for r in await _c.fetchall()]
            except Exception as _e:
                logger.warning("adminlogs: referrals query failed: %s", _e)

        # ── Строим отчёт ────────────────────────────────────────────────────
        fr_al = dict(frow_al) if frow_al else {}
        uname_al = fr_al.get("username", "")
        uname_str = f"@{uname_al}" if uname_al else "—"
        alive_str = "✅ жива" if fr_al.get("alive") else "💀 мертва"
        sub_map = {0: "нет", 1: "🧑‍🍼 Няня", 2: "🏪 Трудяга"}
        sub_str = sub_map.get(fr_al.get("subscription_type", 0), "?")
        if fr_al.get("subscription_until", 0) > 0:
            sub_until_str = datetime.fromtimestamp(
                fr_al["subscription_until"], tz=timezone.utc
            ).strftime("%d.%m.%Y")
            sub_str += f" до {sub_until_str}"

        lines_al = [
            f"╔══ ДОСЬЕ ИГРОКА ══════════════════════════",
            f"║ Имя: {fr_al.get('frog_name') or fr_al.get('first_name', '?')}",
            f"║ Username: {uname_str}",
            f"║ ID: {target_uid_al}",
            f"║ Лягушка: {alive_str}",
            f"║ Уровень: {fr_al.get('level', '?')} · XP: {fr_al.get('xp', '?')}",
            f"║ Монеты: {fr_al.get('coins', '?')}🪙 · Потрачено: {fr_al.get('coins_spent', '?')}🪙",
            f"║ Подписка: {sub_str}",
            f"║ Бан: {'🔴 ДА' if fr_al.get('banned') else '🟢 нет'}",
            f"║ Зарегистр: {datetime.fromtimestamp(fr_al.get('born_at', 0), tz=timezone.utc).strftime('%d.%m.%Y %H:%M') if fr_al.get('born_at') else '—'}",
            f"║ Последн.: {datetime.fromtimestamp(fr_al.get('last_seen', 0), tz=timezone.utc).strftime('%d.%m.%Y %H:%M') if fr_al.get('last_seen') else '—'}",
            f"╚══════════════════════════════════════════",
            f"",
            f"Экспорт: {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M UTC')}",
            "",
        ]

        # Admin actions
        lines_al += [f"─── ДЕЙСТВИЯ АДМИНИСТРАТОРОВ ({len(log_rows_al)}) ───"]
        if log_rows_al:
            for r in log_rows_al:
                ts_str = datetime.fromtimestamp(r["ts"], tz=timezone.utc).strftime("%d.%m %H:%M:%S")
                lines_al.append(f"  [{ts_str}] adm={r['admin_id']} {r['action']} {r['details'] or ''}")
        else:
            lines_al.append("  (нет записей)")

        # Coins
        coin_income  = sum(r["amount"] for r in coin_rows_al if r["amount"] > 0)
        coin_outcome = sum(r["amount"] for r in coin_rows_al if r["amount"] < 0)
        lines_al += [
            "", f"─── ДВИЖЕНИЕ МОНЕТ ({len(coin_rows_al)} операций) ───",
            f"  Приход: +{coin_income}🪙 · Расход: {coin_outcome}🪙 · Итого: {coin_income + coin_outcome:+}🪙",
        ]
        for r in coin_rows_al[:200]:
            ts_str = datetime.fromtimestamp(r["ts"], tz=timezone.utc).strftime("%d.%m %H:%M:%S")
            sign = "+" if r["amount"] > 0 else ""
            lines_al.append(f"  [{ts_str}] {sign}{r['amount']:>6} {r['reason']}")
        if len(coin_rows_al) > 200:
            lines_al.append(f"  ... и ещё {len(coin_rows_al) - 200} операций")

        # Duels
        lines_al += ["", f"─── ДУЭЛИ ({len(duel_rows_al)}) ───"]
        if duel_rows_al:
            wins = sum(1 for r in duel_rows_al if r.get("winner_id") == target_uid_al)
            losses = sum(1 for r in duel_rows_al if r.get("winner_id") and r["winner_id"] != target_uid_al)
            lines_al.append(f"  Победы: {wins} · Поражения: {losses}")
            for r in duel_rows_al[:20]:
                ts_str = datetime.fromtimestamp(r.get("created_at", 0), tz=timezone.utc).strftime("%d.%m %H:%M")
                role = "вызвал" if r.get("challenger_id") == target_uid_al else "принял"
                result = ("✅ победа" if r.get("winner_id") == target_uid_al
                          else ("❌ пораж" if r.get("winner_id") else r.get("status","?")))
                opponent = r.get("target_id") if r.get("challenger_id") == target_uid_al else r.get("challenger_id")
                lines_al.append(f"  [{ts_str}] {role} vs uid={opponent} ставка={r.get('stake','?')} {result}")
        else:
            lines_al.append("  (нет записей)")

        # Adventures
        lines_al += ["", f"─── ПОХОДЫ ({len(adv_rows_al)}) ───"]
        if adv_rows_al:
            for r in adv_rows_al[:20]:
                ts_str = datetime.fromtimestamp(r.get("started_at", 0), tz=timezone.utc).strftime("%d.%m %H:%M")
                partner = r.get("user2_id") if r.get("user1_id") == target_uid_al else r.get("user1_id")
                fin = "✅" if r.get("finished") else "⏳"
                dur = r.get("duration_h", "?")
                lines_al.append(f"  [{ts_str}] {fin} {dur}ч партнёр=uid:{partner}")
        else:
            lines_al.append("  (нет записей)")

        # Expeditions
        lines_al += ["", f"─── ЭКСПЕДИЦИИ ({len(exp_rows_al)}) ───"]
        if exp_rows_al:
            for r in exp_rows_al[:20]:
                ts_str = datetime.fromtimestamp(r.get("started_at", 0), tz=timezone.utc).strftime("%d.%m %H:%M")
                alive_e = "✅" if r.get("mem_status") == "active" else "💀"
                net = (r.get("coins_gained", 0) or 0) - (r.get("coins_lost", 0) or 0)
                betray = " 🗡️предал" if r.get("betrayal_done") else ""
                lines_al.append(
                    f"  [{ts_str}] {alive_e} {r.get('biome','?')}  "
                    f"взял={r.get('coins_taken',0)}{_E_COIN} нетто={net:+}{_E_COIN} вклад={r.get('contribution',0)}{betray}"
                )
        else:
            lines_al.append("  (нет записей)")

        # Gifts
        lines_al += ["", f"─── ПЕРЕВОДЫ МОНЕТ ───",
                     f"  Отправлено ({len(gifts_sent_al)}):"]
        for r in list(gifts_sent_al)[:20]:
            ts_str = datetime.fromtimestamp(r.get("joined_at", 0) or r.get("ts", 0), tz=timezone.utc).strftime("%d.%m %H:%M")
            lines_al.append(f"    [{ts_str}] → uid:{r.get('to_id')} {r.get('amount','?')}{_E_COIN}")
        lines_al.append(f"  Получено ({len(gifts_recv_al)}):")
        for r in list(gifts_recv_al)[:20]:
            ts_str = datetime.fromtimestamp(r.get("joined_at", 0) or r.get("ts", 0), tz=timezone.utc).strftime("%d.%m %H:%M")
            lines_al.append(f"    [{ts_str}] ← uid:{r.get('from_id')} {r.get('amount','?')}{_E_COIN}")

        # Referrals
        lines_al += ["", f"─── РЕФЕРАЛЫ ({len(refs_al)}) ───"]
        for r in list(refs_al)[:20]:
            ts_str = datetime.fromtimestamp(r.get("joined_at", 0) or r.get("ts", 0), tz=timezone.utc).strftime("%d.%m %H:%M")
            lines_al.append(f"  [{ts_str}] привёл uid:{r.get('referred_id')}")

        lines_al.append("")
        lines_al.append(f"═══ конец отчёта ═══")

        content_al = "\n".join(lines_al)
        bio_al = _io.BytesIO(content_al.encode("utf-8"))
        bio_al.name = f"player_{target_uid_al}_report.txt"

        await msg.reply_document(
            document=bio_al,
            caption=(
                f"📋 <b>Досье: {he(fr_al.get('frog_name') or pname_al)}</b> "
                f"(ID <code>{target_uid_al}</code>)\n"
                f"Монеты: {fr_al.get('coins','?')}🪙 | "
                f"Ур.{fr_al.get('level','?')} | "
                f"Бан: {'🔴' if fr_al.get('banned') else '🟢'}\n"
                f"Дуэли: {len(duel_rows_al)} | "
                f"Походы: {len(adv_rows_al)} | "
                f"Монет-операций: {len(coin_rows_al)}"
            ),
            parse_mode=ParseMode.HTML,
        )
        return

    # Режим: только ошибки
    if args and args[0].lower() in ("error", "errors", "err", "ошибки"):
        try:
            with open(log_path, "r", encoding="utf-8", errors="replace") as f:
                lines = f.readlines()
            error_lines = [l for l in lines if " | ERROR |" in l or " | CRITICAL |" in l]
            if not error_lines:
                await msg.reply_text("✅ Ошибок в логах не найдено")
                return
            content = "".join(error_lines[-500:])  # не более 500 строк ошибок
            out_name = "bot_errors.txt"
            import io
            bio = io.BytesIO(content.encode("utf-8"))
            bio.name = out_name
            await msg.reply_document(
                document=bio,
                caption=f"🔴 <b>Ошибки из лога</b>\nНайдено строк: <b>{len(error_lines)}</b> (показано последние {min(len(error_lines),500)})",
                parse_mode=ParseMode.HTML,
            )
        except Exception as e:
            await msg.reply_text(f"{_E_CROSS} Ошибка чтения лога: {he(e)}", parse_mode=ParseMode.HTML)
        return

    # Режим: последние N строк
    if args:
        try:
            n = int(args[0])
        except ValueError:
            await msg.reply_text("❌ Укажи число строк или 'errors'.\nПример: /adminlogs 200")
            return

        try:
            with open(log_path, "r", encoding="utf-8", errors="replace") as f:
                lines = f.readlines()
            tail = lines[-n:] if len(lines) >= n else lines
            content = "".join(tail)
            import io
            # Сначала отправляем текст для быстрого просмотра (последние строки прямо в чат)
            preview = "".join(tail[-30:])
            await msg.reply_text(
                f"📋 <b>Последние {min(len(tail), 30)} строк из {len(tail)} (файл ниже):</b>\n\n"
                f"<pre>{he(preview[-3000:])}</pre>",
                parse_mode=ParseMode.HTML,
            )
            bio = io.BytesIO(content.encode("utf-8"))
            bio.name = f"bot_log_last{n}.txt"
            await msg.reply_document(
                document=bio,
                caption=(
                    f"📋 <b>Последние {len(tail)} строк лога</b>\n"
                    f"Всего в файле: <b>{len(lines)}</b> строк · <b>{size_kb:.1f} КБ</b>"
                ),
                parse_mode=ParseMode.HTML,
            )
        except Exception as e:
            await msg.reply_text(f"{_E_CROSS} Ошибка чтения лога: {he(e)}", parse_mode=ParseMode.HTML)
        return

    # Режим: весь файл (если < 50 МБ)
    MAX_SEND_MB = 50
    if file_size > MAX_SEND_MB * 1024 * 1024:
        await msg.reply_text(
            f"⚠️ Файл слишком большой: <b>{size_kb/1024:.1f} МБ</b> (лимит {MAX_SEND_MB} МБ).\n"
            f"Используй <code>/adminlogs 500</code> чтобы получить последние 500 строк.",
            parse_mode=ParseMode.HTML,
        )
        return

    try:
        with open(log_path, "r", encoding="utf-8", errors="replace") as _f:
            _all_lines = _f.readlines()
        # Сначала отправляем последние 30 строк текстом для быстрого просмотра
        _tail_preview = "".join(_all_lines[-30:]) if len(_all_lines) >= 30 else "".join(_all_lines)
        import io as _io_full
        await msg.reply_text(
            f"📋 <b>Последние строки лога (файл ниже):</b>\n\n"
            f"<pre>{he(_tail_preview[-3000:])}</pre>",
            parse_mode=ParseMode.HTML,
        )
        # Затем отправляем полный файл
        _bio_full = _io_full.BytesIO("".join(_all_lines).encode("utf-8"))
        _bio_full.name = "bot.log"
        await msg.reply_document(
            document=_bio_full,
            caption=(
                f"📋 <b>Полный лог бота</b>\n"
                f"Строк: <b>{len(_all_lines)}</b> · Размер: <b>{size_kb:.1f} КБ</b>\n\n"
                f"<i>Подсказки:</i>\n"
                f"<code>/adminlogs 200</code> — последние 200 строк\n"
                f"<code>/adminlogs errors</code> — только ошибки"
            ),
            parse_mode=ParseMode.HTML,
        )
    except Exception as e:
        await msg.reply_text(f"{_E_CROSS} Не удалось отправить файл: {he(e)}", parse_mode=ParseMode.HTML)


# ══════════════════════════════════════════════════════════════════════════════
# 🛡️  СИСТЕМА РИСКА — многоуровневая защита от ботоводов
#
#  Уровни:
#    0 — норма (без ограничений)
#    1 — подозрение (+50% кулдаун, лимит перевода 500/сутки, вход в розыгрыши 1/сутки)
#    2 — ограничен (переводы, розыгрыши, дуэли заблокированы; только уход за лягушкой)
#    3 — автобан (полная блокировка, эквивалент f["banned"])
#
#  Лимиты (суточные скользящие окна):
#    gift_out   — исходящие переводы: 10000 (lvl0) / 1000 (lvl1)
#    gift_in    — входящие переводы:   5000 (lvl0) /  500 (lvl1)
#    duels      — дуэли:                 30 (lvl0) /   10 (lvl1)
#    giveaway_create — создание розыгрышей: 5 / 1
#    giveaway_join   — участие в розыгрышах: без лимита / 1
#
#  Новые аккаунты (born_at):
#    < 3 суток → переводы, розыгрыши, турниры заблокированы полностью
#    < 7 суток → лимит исходящих переводов 100/сутки
# ══════════════════════════════════════════════════════════════════════════════

_RISK_LIMITS: dict[str, tuple[int, int]] = {
    # action: (limit_level0, limit_level1)
    "gift_out":        (10_000, 1_000),
    "gift_in":         ( 5_000,   500),
    "duels":           (    30,    10),
    "giveaway_create": (     5,     1),
    "giveaway_join":   (   999,     1),
}

# Действия, заблокированные для аккаунтов моложе 3 суток
_NEW_ACCOUNT_BLOCKED = {"gift_out", "giveaway_create", "tournament_create"}
_NEW_ACCOUNT_AGE_HARD = 3 * 86400   # 3 дня → полный блок
_NEW_ACCOUNT_AGE_SOFT = 7 * 86400   # 7 дней → мягкий лимит 100/сутки
_NEW_ACCOUNT_SOFT_LIMIT = 100


async def get_user_risk(uid: int) -> int:
    """Вернуть текущий уровень риска (0–3). 0 если запись отсутствует."""
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT risk_level FROM user_risk WHERE user_id=?", (uid,)
            ) as c:
                row = await c.fetchone()
        return row[0] if row else 0
    except Exception:
        return 0


async def get_user_risk_full(uid: int) -> dict:
    """Вернуть полную запись риска или дефолтный словарь."""
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            async with db.execute(
                "SELECT * FROM user_risk WHERE user_id=?", (uid,)
            ) as c:
                row = await c.fetchone()
        if row:
            return dict(row)
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)
    return {"user_id": uid, "risk_level": 0, "risk_reason": "", "risk_updated": 0, "flags": "{}"}


async def set_user_risk(uid: int, level: int, reason: str = "") -> None:
    """Установить уровень риска. level=3 → автоматический бан через f["banned"]."""
    level = max(0, min(3, level))
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                """INSERT INTO user_risk(user_id, risk_level, risk_reason, risk_updated)
                   VALUES(?,?,?,?)
                   ON CONFLICT(user_id) DO UPDATE SET
                     risk_level=excluded.risk_level,
                     risk_reason=excluded.risk_reason,
                     risk_updated=excluded.risk_updated""",
                (uid, level, reason[:500], time.time()),
            )
            await db.commit()
        # Если уровень 3 — выставляем banned=1 прямо в frogs
        if level >= 3:
            async with aiosqlite.connect(DB_PATH) as db2:
                await db2.execute(
                    "UPDATE frogs SET banned=1 WHERE user_id=?", (uid,)
                )
                await db2.commit()
            _user_cache.invalidate(uid)
        logger.info("set_user_risk: uid=%s level=%s reason=%r", uid, level, reason)
    except Exception as e:
        logger.error("set_user_risk error: %s", e)


async def check_rate_limit(uid: int, action: str, amount: int = 1) -> tuple[bool, str]:
    """
    Проверить суточный лимит для действия.
    Возвращает (ok: bool, reason: str).
    НЕ изменяет счётчики — только проверяет.
    Счётчик обновляется реальными INSERT в gift_log / дуэлях и т.д.
    """
    if action not in _RISK_LIMITS:
        return True, ""

    f = await db_get(uid)
    if not f:
        return True, ""

    risk = await get_user_risk(uid)
    born_at = f.get("born_at", 0) or 0
    age_sec = time.time() - born_at

    # ── Блокировка для новых аккаунтов ──────────────────────────────────────
    if action in _NEW_ACCOUNT_BLOCKED and age_sec < _NEW_ACCOUNT_AGE_HARD:
        days_left = int((_NEW_ACCOUNT_AGE_HARD - age_sec) / 86400) + 1
        return False, f"🐣 Новый аккаунт — переводы доступны через {days_left} д."

    # ── Мягкий лимит для аккаунтов 3–7 суток ────────────────────────────────
    if action == "gift_out" and age_sec < _NEW_ACCOUNT_AGE_SOFT:
        limit = _NEW_ACCOUNT_SOFT_LIMIT
    else:
        limit0, limit1 = _RISK_LIMITS[action]
        limit = limit1 if risk >= 1 else limit0

    # ── Считаем использованное за сегодня ────────────────────────────────────
    day_start = time.time() - (time.time() % 86400)  # UTC-полночь
    used = 0
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            if action == "gift_out":
                async with db.execute(
                    "SELECT COALESCE(SUM(amount),0) FROM gift_log WHERE from_id=? AND to_id!=0 AND amount>0 AND ts>=?",
                    (uid, day_start),
                ) as c:
                    used = (await c.fetchone())[0] or 0
            elif action == "gift_in":
                async with db.execute(
                    "SELECT COALESCE(SUM(amount),0) FROM gift_log WHERE to_id=? AND amount>0 AND ts>=?",
                    (uid, day_start),
                ) as c:
                    used = (await c.fetchone())[0] or 0
            elif action == "duels":
                async with db.execute(
                    "SELECT COUNT(*) FROM duels WHERE (challenger_id=? OR target_id=?) AND created_at>=?",
                    (uid, uid, day_start),
                ) as c:
                    used = (await c.fetchone())[0] or 0
            elif action == "giveaway_create":
                async with db.execute(
                    "SELECT COUNT(*) FROM giveaways WHERE creator_id=? AND created_at>=?",
                    (uid, day_start),
                ) as c:
                    used = (await c.fetchone())[0] or 0
            elif action == "giveaway_join":
                async with db.execute(
                    "SELECT COUNT(*) FROM giveaways WHERE participants LIKE ? AND created_at>=?",
                    (f"%{uid}%", day_start),
                ) as c:
                    used = (await c.fetchone())[0] or 0
    except Exception as e:
        logger.warning("check_rate_limit db error: %s", e)
        return True, ""

    if used + amount > limit:
        remaining = max(0, limit - used)
        return False, f"{_E_CHART} Суточный лимит: использовано {used}/{limit} (осталось {remaining})"
    return True, ""


async def risk_block_check(uid: int, action: str) -> tuple[bool, str]:
    """
    Проверить, заблокировано ли действие по уровню риска.
    action: "transfer" | "giveaway" | "duel" | "tournament" | "casino" | "lottery"
    Возвращает (blocked: bool, message: str).
    """
    risk = await get_user_risk(uid)
    if risk < 2:
        return False, ""
    blocked_at_2 = {"transfer", "giveaway", "duel", "tournament"}
    if action in blocked_at_2:
        return True, "⛔ Ваш аккаунт временно ограничен. Обратитесь к администратору."
    return False, ""


# ══════════════════════════════════════════════════════════════════════════════
# 🛡️  АДМИН-КОМАНДЫ РИСК-СИСТЕМЫ
#   /adminrisk [user_id|@username]        — показать уровень риска и флаги
#   /adminrisk_set [user_id] [0-3] [причина] — установить уровень вручную
#   /adminrisk_reset [user_id]            — сбросить риск до 0
# ══════════════════════════════════════════════════════════════════════════════

_RISK_LEVEL_LABELS = {
    0: "🟢 Норма",
    1: "🟡 Подозрение",
    2: "🔴 Ограничен",
    3: "⛔ Автобан",
}


async def _resolve_uid_from_arg(arg: str) -> int | None:
    """Вернуть user_id по числу или @username. None если не найден."""
    arg = arg.strip().lstrip("@")
    if arg.isdigit():
        return int(arg)
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT user_id FROM frogs WHERE username=?", (arg,)
            ) as c:
                row = await c.fetchone()
        return row[0] if row else None
    except Exception:
        return None


async def cmd_adminrisk(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/adminrisk [user_id|@username] — показать уровень риска игрока."""
    if update.effective_user.id not in ADMIN_IDS:
        return
    args = ctx.args
    if not args:
        await update.message.reply_text(
            "Использование: <code>/adminrisk user_id</code> или <code>/adminrisk @username</code>",
            parse_mode=ParseMode.HTML,
        )
        return

    uid = await _resolve_uid_from_arg(args[0])
    if not uid:
        await update.message.reply_text("❌ Игрок не найден.")
        return

    risk_data = await get_user_risk_full(uid)
    f = await db_get(uid)
    name = (f.get("first_name") or str(uid)) if f else str(uid)
    level = risk_data.get("risk_level", 0)
    label = _RISK_LEVEL_LABELS.get(level, str(level))
    reason = risk_data.get("risk_reason") or "—"
    updated = risk_data.get("risk_updated", 0)
    updated_str = datetime.fromtimestamp(updated, timezone.utc).strftime("%Y-%m-%d %H:%M UTC") if updated else "никогда"

    # Суточная статистика
    day_start = time.time() - 86400
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT COALESCE(SUM(amount),0), COUNT(DISTINCT to_id) FROM gift_log WHERE from_id=? AND to_id!=0 AND amount>0 AND ts>=?",
                (uid, day_start),
            ) as c:
                out_sum, out_cnt = await c.fetchone()
            async with db.execute(
                "SELECT COALESCE(SUM(amount),0), COUNT(DISTINCT from_id) FROM gift_log WHERE to_id=? AND amount>0 AND ts>=?",
                (uid, day_start),
            ) as c:
                in_sum, in_cnt = await c.fetchone()
            async with db.execute(
                "SELECT COUNT(*) FROM duels WHERE (challenger_id=? OR target_id=?) AND created_at>=?",
                (uid, uid, day_start),
            ) as c:
                duel_cnt = (await c.fetchone())[0] or 0
    except Exception:
        out_sum = out_cnt = in_sum = in_cnt = duel_cnt = "?"

    born_at = (f.get("born_at") or 0) if f else 0
    age_days = int((time.time() - born_at) / 86400) if born_at else "?"

    # Список кто переводил этому игроку за 24ч
    senders_list = []
    receivers_list = []
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT gl.from_id, f.first_name, f.username, SUM(gl.amount) "
                "FROM gift_log gl LEFT JOIN frogs f ON f.user_id=gl.from_id "
                "WHERE gl.to_id=? AND gl.amount>0 AND gl.ts>=? GROUP BY gl.from_id ORDER BY SUM(gl.amount) DESC LIMIT 30",
                (uid, day_start),
            ) as c:
                senders_list = await c.fetchall()
            async with db.execute(
                "SELECT gl.to_id, f.first_name, f.username, SUM(gl.amount) "
                "FROM gift_log gl LEFT JOIN frogs f ON f.user_id=gl.to_id "
                "WHERE gl.from_id=? AND gl.amount>0 AND gl.ts>=? GROUP BY gl.to_id ORDER BY SUM(gl.amount) DESC LIMIT 30",
                (uid, day_start),
            ) as c:
                receivers_list = await c.fetchall()
    except Exception as _e:
        logger.exception("подавлено исключение: %s", _e)

    def _fmt_user(uid2, fname2, uname2):
        n = fname2 or uname2 or str(uid2)
        return f"<code>{uid2}</code> {_html.escape(str(n))}"

    senders_txt = ""
    if senders_list:
        senders_txt = "\n\n<b>📥 Кто переводил (24ч):</b>\n" + "\n".join(
            f"  · {_fmt_user(r[0], r[1], r[2])} — {int(r[3])}🪙" for r in senders_list
        )

    receivers_txt = ""
    if receivers_list:
        receivers_txt = "\n\n<b>📤 Кому переводил (24ч):</b>\n" + "\n".join(
            f"  · {_fmt_user(r[0], r[1], r[2])} — {int(r[3])}🪙" for r in receivers_list
        )

    text = (
        f"🛡 <b>Риск-профиль</b>\n"
        f"👤 <code>{uid}</code> {_html.escape(name)}\n"
        f"📅 Возраст аккаунта: {age_days} дн.\n\n"
        f"Уровень: <b>{label}</b>\n"
        f"Причина: <i>{_html.escape(str(reason))}</i>\n"
        f"Обновлён: {updated_str}\n\n"
        f"<b>Статистика за 24ч:</b>\n"
        f"📤 Исходящих: {out_sum}{_E_COIN} → {out_cnt} игрокам\n"
        f"📥 Входящих: {in_sum}{_E_COIN} ← {in_cnt} игроков\n"
        f"{_E_SWORDS} Дуэлей: {duel_cnt}"
        f"{senders_txt}{receivers_txt}\n\n"
        f"🔧 <code>/adminrisk_set {uid} 0|1|2|3</code>\n"
        f"{_E_REFRESH} <code>/adminrisk_reset {uid}</code>\n"
        f"🔗 <code>/admingiftchain {uid} 72</code> — цепочка переводов\n"
        f"{_E_HAMMER} <code>/adminrollbackdry {uid} 72</code> — сухой откат"
    )
    kb = InlineKeyboardMarkup([
        [
            btn("🔴 Risk +1", callback_data=f"risk_bump_{uid}"),
            btn("🟢 Сбросить риск", callback_data=f"risk_reset_{uid}"),
        ],
        [btn("🤖 Пометить ботом", callback_data=f"risk_markbot_{uid}")],
        [btn("🔗 Цепочка переводов (72ч)", callback_data=f"risk_chain_{uid}")],
    ])
    await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)


async def _send_bot_contacts_page(bot, admin_id: int, bot_uid: int, bot_name: str, contacts: list, page: int) -> None:
    """
    Отправляет постраничный список контактов бота с кнопками:
    🚫 Забанить | 🤖 Пометить ботом | 🔗 Цепочка | 🔄 Откат
    """
    per = 5
    total = len(contacts)
    chunk = contacts[page * per:(page + 1) * per]

    if not chunk:
        await bot.send_message(admin_id, "Контактов не найдено.", parse_mode=ParseMode.HTML)
        return

    lines = [
        f"{_E_BOT} <b>Контакты бота</b> <code>{bot_uid}</code> {_html.escape(bot_name)}\n"
        f"Всего контактов: <b>{total}</b> (стр {page+1}/{(total-1)//per+1})\n"
    ]
    buttons = []

    for contact_uid, contact_name, desc, ctype in chunk:
        # Проверяем текущий статус
        cf = await db_get(contact_uid)
        is_banned = (cf.get("banned", 0) or 0) if cf else 0
        is_bot_f  = (cf.get("is_bot",  0) or 0) if cf else 0
        status = ""
        if is_banned: status += " 🚫"
        if is_bot_f:  status += " 🤖"

        lines.append(
            f"• <b>{_html.escape(str(contact_name))}</b>{status} <code>{contact_uid}</code>\n"
            f"  {desc}"
        )
        row = [
            btn(
                "🚫 Бан" if not is_banned else "🔓 Разбан",
                callback_data=f"bcp_ban_{bot_uid}_{contact_uid}_{page}" if not is_banned
                              else f"bcp_unban_{bot_uid}_{contact_uid}_{page}",
            ),
            btn("🤖 Бот", callback_data=f"bcp_markbot_{bot_uid}_{contact_uid}_{page}"),
            btn("🔗 Цепочка", callback_data=f"bcp_chain_{bot_uid}_{contact_uid}_{page}"),
        ]
        if not is_banned:
            row.append(btn("🔨 Откат", callback_data=f"bcp_rollback_{bot_uid}_{contact_uid}_{page}"))
        buttons.append(row)

    # Навигация
    nav = []
    if page > 0:
        nav.append(btn("◀️ Пред", callback_data=f"bcp_page_{bot_uid}_{page-1}"))
    if (page + 1) * per < total:
        nav.append(btn("▶️ След", callback_data=f"bcp_page_{bot_uid}_{page+1}"))
    if nav:
        buttons.append(nav)

    # Кнопка "Забанить всех на этой странице"
    buttons.append([
        btn("🚫 Забанить всех на странице", callback_data=f"bcp_banall_{bot_uid}_{page}"),
    ])
    buttons.append([
        btn(
            f"{_E_HAMMER} Откат ботовода (dry)",
            callback_data=f"bcp_dryrb_{bot_uid}_{page}",
        )
    ])

    await bot.send_message(
        admin_id,
        "\n".join(lines),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup(buttons),
    )


async def handle_bot_contacts_callback(q, d: str, uid: int, ctx) -> None:
    """Обработчик кнопок bcp_ (bot contacts page)"""
    if uid not in ADMIN_IDS:
        await q.answer("Нет доступа", show_alert=True)
        return

    parts = d.split("_")
    # Формат: bcp_{action}_{bot_uid}_{contact_uid}_{page}  или  bcp_page_{bot_uid}_{page}

    action = parts[1]

    # Навигация по страницам
    if action == "page":
        bot_uid = int(parts[2])
        page = int(parts[3])
        cache_key = f"botcontacts_{bot_uid}"
        contacts = ctx.bot_data.get(cache_key)
        if not contacts:
            await q.answer("Список устарел, запусти заново через /adminrisk", show_alert=True)
            return
        bf = await db_get(bot_uid)
        bname = (bf.get("first_name") or str(bot_uid)) if bf else str(bot_uid)
        await q.message.delete()
        await _send_bot_contacts_page(ctx.bot, uid, bot_uid, bname, contacts, page)
        return

    # banall / dryrb / fullrb не имеют contact_uid
    if action in ("banall", "dryrb", "fullrb"):
        bot_uid   = int(parts[2])
        page      = int(parts[3])
        cache_key = f"botcontacts_{bot_uid}"
        contacts  = ctx.bot_data.get(cache_key, [])
        bf        = await db_get(bot_uid)
        bname     = (bf.get("first_name") or str(bot_uid)) if bf else str(bot_uid)

        if action == "banall":
            per   = 5
            chunk = contacts[page * per:(page + 1) * per]
            banned_names = []
            for cuid2, cname2, *_ in chunk:
                f2 = await db_get(cuid2)
                if f2 and not f2.get("banned"):
                    f2["banned"] = 1
                    await db_save(f2)
                    await set_user_risk(cuid2, 2, f"Массовый бан как контакт бота {bot_uid}")
                    banned_names.append(cname2)
            await q.answer((f"🚫 Забанено: {len(banned_names)}")[:200], show_alert=True)
            try: await q.message.delete()
            except Exception as _e:
                logger.exception("подавлено исключение: %s", _e)
            await _send_bot_contacts_page(ctx.bot, uid, bot_uid, bname, contacts, page)
            return

        if action == "dryrb":
            await q.answer("⏳ Сухой откат ботовода...")
            report = await _do_rollback(bot_uid, 168, dry_run=True, bot=ctx.bot)
            kb = InlineKeyboardMarkup([[
                btn("🔨 Подтвердить откат ВСЕХ", callback_data=f"bcp_fullrb_{bot_uid}_{page}", style="danger"),
                btn("❌ Отмена", callback_data=f"bcp_page_{bot_uid}_{page}", style="primary"),
            ]])
            await ctx.bot.send_message(uid, f"{_E_SEARCH} <b>Сухой откат ботовода</b>\n{report}", parse_mode=ParseMode.HTML, reply_markup=kb)
            return

        if action == "fullrb":
            await q.answer("🔨 Откат ботовода...")
            report = await _do_rollback(bot_uid, 168, dry_run=False, bot=ctx.bot)
            await ctx.bot.send_message(uid, report, parse_mode=ParseMode.HTML)
            return

    bot_uid     = int(parts[2])
    contact_uid = int(parts[3])
    page        = int(parts[4])
    cache_key   = f"botcontacts_{bot_uid}"

    if action == "ban":
        f2 = await db_get(contact_uid)
        if f2:
            f2["banned"] = 1
            await db_save(f2)
        await set_user_risk(contact_uid, 2, f"Забанен как контакт бота {bot_uid}")
        cf = await db_get(contact_uid)
        nm = (cf.get("first_name") or str(contact_uid)) if cf else str(contact_uid)
        await q.answer((f"🚫 {nm} забанен")[:200], show_alert=True)
        # Обновляем страницу
        contacts = ctx.bot_data.get(cache_key, [])
        bf = await db_get(bot_uid)
        bname = (bf.get("first_name") or str(bot_uid)) if bf else str(bot_uid)
        try:
            await q.message.delete()
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
        await _send_bot_contacts_page(ctx.bot, uid, bot_uid, bname, contacts, page)
        return

    if action == "unban":
        f2 = await db_get(contact_uid)
        if f2:
            f2["banned"] = 0
            await db_save(f2)
        await set_user_risk(contact_uid, 0, "Разбанен администратором")
        await q.answer("🔓 Разбанен", show_alert=True)
        contacts = ctx.bot_data.get(cache_key, [])
        bf = await db_get(bot_uid)
        bname = (bf.get("first_name") or str(bot_uid)) if bf else str(bot_uid)
        try:
            await q.message.delete()
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
        await _send_bot_contacts_page(ctx.bot, uid, bot_uid, bname, contacts, page)
        return

    if action == "markbot":
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE frogs SET is_bot=1, banned=1 WHERE user_id=?", (contact_uid,))
            await db.commit()
        _user_cache.invalidate(contact_uid)
        await set_user_risk(contact_uid, 3, f"Помечен ботом (контакт {bot_uid})")
        cf = await db_get(contact_uid)
        nm = (cf.get("first_name") or str(contact_uid)) if cf else str(contact_uid)
        await q.answer((f"🤖 {nm} помечен ботом")[:200], show_alert=True)
        contacts = ctx.bot_data.get(cache_key, [])
        bf = await db_get(bot_uid)
        bname = (bf.get("first_name") or str(bot_uid)) if bf else str(bot_uid)
        try:
            await q.message.delete()
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
        await _send_bot_contacts_page(ctx.bot, uid, bot_uid, bname, contacts, page)
        return

    if action == "chain":
        await q.answer("⏳ Генерирую цепочку...")
        hours = 72
        since = time.time() - hours * 3600
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT to_id, SUM(amount), COUNT(*) FROM gift_log WHERE from_id=? AND ts>=? GROUP BY to_id ORDER BY SUM(amount) DESC",
                (contact_uid, since),
            ) as c:
                gifts_out = await c.fetchall()
            async with db.execute(
                "SELECT from_id, SUM(amount), COUNT(*) FROM gift_log WHERE to_id=? AND ts>=? GROUP BY from_id ORDER BY SUM(amount) DESC",
                (contact_uid, since),
            ) as c:
                gifts_in = await c.fetchall()
        cf = await db_get(contact_uid)
        cname = (cf.get("first_name") or str(contact_uid)) if cf else str(contact_uid)
        is_bot_f = (cf.get("is_bot", 0) or 0) if cf else 0
        lines = [
            f"🔗 <b>Цепочка</b> {_E_BOT if is_bot_f else '👤'} <b>{_html.escape(cname)}</b> <code>{contact_uid}</code>\n"
        ]
        if gifts_out:
            lines.append(f"📤 Отправил {int(sum(r[1] or 0 for r in gifts_out))}{_E_COIN} → {len(gifts_out)} игрокам:")
            for to_id, amt, cnt in gifts_out[:15]:
                vf = await db_get(to_id)
                vn = (vf.get("first_name") or str(to_id)) if vf else str(to_id)
                bm = " 🤖" if (vf and vf.get("is_bot")) else ""
                lines.append(f"  → <code>{to_id}</code> {_html.escape(str(vn))}{bm} {int(amt or 0)}{_E_COIN}")
        if gifts_in:
            lines.append(f"\n📥 Получил от {len(gifts_in)} игроков:")
            for from_id, amt, cnt in gifts_in[:15]:
                vf = await db_get(from_id)
                vn = (vf.get("first_name") or str(from_id)) if vf else str(from_id)
                bm = " 🤖" if (vf and vf.get("is_bot")) else ""
                lines.append(f"  ← <code>{from_id}</code> {_html.escape(str(vn))}{bm} {int(amt or 0)}{_E_COIN}")
        lines.append(f"\n/adminrollbackdry {contact_uid} {hours}")
        await ctx.bot.send_message(uid, "\n".join(lines), parse_mode=ParseMode.HTML)
        return

    if action == "rollback":
        await q.answer("⏳ Запускаю сухой откат...")
        report = await _do_rollback(contact_uid, 72, dry_run=True, bot=ctx.bot)
        kb = InlineKeyboardMarkup([[
            btn("🔨 Подтвердить откат", callback_data=f"bcp_rollbackconfirm_{bot_uid}_{contact_uid}_{page}", style="danger"),
            btn("❌ Отмена", callback_data=f"bcp_page_{bot_uid}_{page}", style="primary"),
        ]])
        await ctx.bot.send_message(uid, f"{_E_SEARCH} <b>Сухой откат</b>\n{report}", parse_mode=ParseMode.HTML, reply_markup=kb)
        return

    if action == "rollbackconfirm":
        await q.answer("🔨 Откатываю...")
        report = await _do_rollback(contact_uid, 72, dry_run=False, bot=ctx.bot)
        await ctx.bot.send_message(uid, report, parse_mode=ParseMode.HTML)
        return


async def handle_risk_callback(q, d: str, uid: int, ctx) -> None:
    """Обработчик кнопок из /adminrisk: risk_bump_, risk_reset_, risk_markbot_, risk_chain_"""
    if uid not in ADMIN_IDS:
        await q.answer("Нет доступа", show_alert=True)
        return

    # risk_bump_{target_uid} — поднять риск на 1
    if d.startswith("risk_bump_"):
        target = int(d[10:])
        cur = await get_user_risk(target)
        new_lvl = min(3, cur + 1)
        await set_user_risk(target, new_lvl, f"Повышен вручную администратором {uid}")
        label = _RISK_LEVEL_LABELS.get(new_lvl, str(new_lvl))
        await q.answer((f"Риск → {label}")[:200], show_alert=True)
        return

    # risk_reset_{target_uid} — сбросить риск
    if d.startswith("risk_reset_"):
        target = int(d[11:])
        await set_user_risk(target, 0, "Сброшено вручную")
        try:
            async with aiosqlite.connect(DB_PATH) as db:
                await db.execute("UPDATE frogs SET banned=0 WHERE user_id=? AND banned=1", (target,))
                await db.commit()
            _user_cache.invalidate(target)
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)
        await q.answer("✅ Риск сброшен до нормы", show_alert=True)
        return

    # risk_markbot_{target_uid} — пометить ботом и сразу показать контакты
    if d.startswith("risk_markbot_"):
        target = int(d[13:])
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE frogs SET is_bot=1, banned=1 WHERE user_id=?", (target,))
            await db.commit()
        _user_cache.invalidate(target)
        await set_user_risk(target, 3, f"Помечен ботом администратором {uid}")
        await q.answer("🤖 Помечен ботом. Генерирую отчёт по контактам...")

        # Собираем всех кто контактировал с этим ботом
        hours = 168
        since = time.time() - hours * 3600
        async with aiosqlite.connect(DB_PATH) as db:
            # Кто получал от него
            async with db.execute(
                "SELECT gl.to_id, f.first_name, f.username, SUM(gl.amount), COUNT(*) "
                "FROM gift_log gl LEFT JOIN frogs f ON f.user_id=gl.to_id "
                "WHERE gl.from_id=? AND gl.ts>=? GROUP BY gl.to_id ORDER BY SUM(gl.amount) DESC",
                (target, since),
            ) as c:
                received = await c.fetchall()
            # Кто переводил ему
            async with db.execute(
                "SELECT gl.from_id, f.first_name, f.username, SUM(gl.amount), COUNT(*) "
                "FROM gift_log gl LEFT JOIN frogs f ON f.user_id=gl.from_id "
                "WHERE gl.to_id=? AND gl.ts>=? GROUP BY gl.from_id ORDER BY SUM(gl.amount) DESC",
                (target, since),
            ) as c:
                sent = await c.fetchall()
            # Дуэли
            async with db.execute(
                "SELECT CASE WHEN challenger_id=? THEN target_id ELSE challenger_id END, COUNT(*) "
                "FROM duels WHERE (challenger_id=? OR target_id=?) AND created_at>=? "
                "GROUP BY 1 ORDER BY 2 DESC",
                (target, target, target, since),
            ) as c:
                duels = await c.fetchall()

        bf = await db_get(target)
        bname = (bf.get("first_name") or str(target)) if bf else str(target)

        # Собираем единый список контактов: (user_id, name, описание, тип)
        contacts = []
        if received:
            for to_id, fname2, uname2, amt, cnt in received:
                n = fname2 or uname2 or str(to_id)
                contacts.append((to_id, n, f"📤 получил {int(amt or 0)}{_E_COIN} ({cnt}×)", "recv"))
        if sent:
            for from_id, fname2, uname2, amt, cnt in sent:
                if from_id == target:
                    continue
                n = fname2 or uname2 or str(from_id)
                contacts.append((from_id, n, f"📥 переводил {int(amt or 0)}{_E_COIN}", "sent"))
        if duels:
            duel_ids = {c[0] for c in contacts}
            for partner_id, dcnt in duels:
                if partner_id == target or partner_id in duel_ids:
                    continue
                pf = await db_get(partner_id)
                pn = (pf.get("first_name") or str(partner_id)) if pf else str(partner_id)
                contacts.append((partner_id, pn, f"{_E_SWORDS} дуэлей: {dcnt}", "duel"))

        # Сохраняем список в ctx.bot_data для пагинации
        cache_key = f"botcontacts_{target}"
        ctx.bot_data[cache_key] = contacts

        await _send_bot_contacts_page(ctx.bot, uid, target, bname, contacts, page=0)
        return

    # risk_chain_{target_uid} — цепочка переводов (вызываем admingiftchain логику)
    if d.startswith("risk_chain_"):
        target = int(d[11:])
        await q.answer("⏳ Генерирую цепочку...")
        hours = 72
        since = time.time() - hours * 3600

        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT to_id, SUM(amount), COUNT(*) FROM gift_log WHERE from_id=? AND ts>=? GROUP BY to_id ORDER BY SUM(amount) DESC",
                (target, since),
            ) as c:
                gifts_out = await c.fetchall()
            async with db.execute(
                "SELECT from_id, SUM(amount), COUNT(*) FROM gift_log WHERE to_id=? AND ts>=? GROUP BY from_id ORDER BY SUM(amount) DESC",
                (target, since),
            ) as c:
                gifts_in = await c.fetchall()

        bf = await db_get(target)
        bname = (bf.get("first_name") or str(target)) if bf else str(target)
        is_bot_flag = (bf.get("is_bot", 0) or 0) if bf else 0

        lines = [
            f"🔗 <b>Цепочка переводов</b> ({hours}ч)\n"
            f"{_E_BOT if is_bot_flag else '👤'} <b>{_html.escape(bname)}</b> <code>{target}</code>\n"
        ]

        if gifts_out:
            total_out = sum(r[1] or 0 for r in gifts_out)
            lines.append(f"📤 <b>Отправил</b> {int(total_out)}{_E_COIN} → {len(gifts_out)} игрокам:")
            for to_id, amt, cnt in gifts_out[:20]:
                vf = await db_get(to_id)
                vn = (vf.get("first_name") or str(to_id)) if vf else str(to_id)
                is_b2 = (vf.get("is_bot", 0) or 0) if vf else 0
                mark = " 🤖" if is_b2 else ""
                lines.append(f"  → <code>{to_id}</code> {_html.escape(str(vn))}{mark} {int(amt or 0)}{_E_COIN} ({cnt}×)")
            if len(gifts_out) > 20:
                lines.append(f"  <i>...ещё {len(gifts_out)-20}</i>")
        else:
            lines.append("📤 Исходящих переводов нет")

        if gifts_in:
            total_in = sum(r[1] or 0 for r in gifts_in)
            lines.append(f"\n📥 <b>Получил</b> {int(total_in)}{_E_COIN} от {len(gifts_in)} игроков:")
            for from_id, amt, cnt in gifts_in[:20]:
                vf = await db_get(from_id)
                vn = (vf.get("first_name") or str(from_id)) if vf else str(from_id)
                is_b2 = (vf.get("is_bot", 0) or 0) if vf else 0
                mark = " 🤖" if is_b2 else ""
                lines.append(f"  ← <code>{from_id}</code> {_html.escape(str(vn))}{mark} {int(amt or 0)}{_E_COIN} ({cnt}×)")

        lines.append(f"\n/adminrollbackdry {target} {hours} — сухой откат\n/adminrollback {target} {hours} — реальный")
        await ctx.bot.send_message(uid, "\n".join(lines), parse_mode=ParseMode.HTML)
        return


async def cmd_adminrisk_set(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/adminrisk_set [user_id] [0-3] [причина] — установить уровень риска."""
    if update.effective_user.id not in ADMIN_IDS:
        return
    args = ctx.args
    if not args or len(args) < 2:
        await update.message.reply_text(
            "Использование: <code>/adminrisk_set user_id 0-3 [причина]</code>",
            parse_mode=ParseMode.HTML,
        )
        return

    uid = await _resolve_uid_from_arg(args[0])
    if not uid:
        await update.message.reply_text("❌ Игрок не найден.")
        return
    try:
        level = int(args[1])
        if level not in (0, 1, 2, 3):
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Уровень должен быть 0, 1, 2 или 3.")
        return

    reason = " ".join(args[2:]) if len(args) > 2 else f"Установлено администратором {update.effective_user.id}"
    await set_user_risk(uid, level, reason)

    label = _RISK_LEVEL_LABELS.get(level, str(level))
    f = await db_get(uid)
    name = (f.get("first_name") or str(uid)) if f else str(uid)
    await update.message.reply_text(
        f"{_E_CHECK} <code>{uid}</code> {_html.escape(name)}\n"
        f"Новый уровень риска: <b>{label}</b>\n"
        f"Причина: <i>{_html.escape(reason)}</i>",
        parse_mode=ParseMode.HTML,
    )


async def cmd_adminrisk_reset(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """/adminrisk_reset [user_id] — сбросить риск до 0."""
    if update.effective_user.id not in ADMIN_IDS:
        return
    args = ctx.args
    if not args:
        await update.message.reply_text(
            "Использование: <code>/adminrisk_reset user_id</code>",
            parse_mode=ParseMode.HTML,
        )
        return

    uid = await _resolve_uid_from_arg(args[0])
    if not uid:
        await update.message.reply_text("❌ Игрок не найден.")
        return

    await set_user_risk(uid, 0, "Сброшено администратором")
    # Если был автобан (уровень 3) — снимаем banned=1
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE frogs SET banned=0 WHERE user_id=? AND banned=1", (uid,))
            await db.commit()
        _user_cache.invalidate(uid)
    except Exception as e:
        logger.warning("adminrisk_reset unban error: %s", e)

    f = await db_get(uid)
    name = (f.get("first_name") or str(uid)) if f else str(uid)
    await update.message.reply_text(
        f"{_E_CHECK} Риск <code>{uid}</code> {_html.escape(name)} сброшен до {_E_DOT_GREEN} Норма.",
        parse_mode=ParseMode.HTML,
    )


# ══════════════════════════════════════════════════════════════════════════════
# 🔍  РАССЛЕДОВАНИЕ БОТОВОДА: /admingiftchain + /adminrollback
# ══════════════════════════════════════════════════════════════════════════════


async def cmd_admingiftchain(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/admingiftchain [user_id] [часов=72] — показать цепочку: ботовод→жертвы→гача-скины"""
    if update.effective_user.id not in ADMIN_IDS: return
    args = update.message.text.split()
    if len(args) < 2:
        await update.message.reply_text(
            "Использование:\n"
            "<code>/admingiftchain 123456789</code> — за последние 72 ч\n"
            "<code>/admingiftchain 123456789 168</code> — за последние N часов\n\n"
            "Показывает: кому раздал монеты, сколько, и что те выбили в гаче после.",
            parse_mode=ParseMode.HTML
        )
        return
    try:
        bot_uid = int(args[1])
    except ValueError:
        await update.message.reply_text("ID должен быть числом"); return
    hours = 72
    if len(args) > 2:
        try: hours = max(1, min(8760, int(args[2])))
        except ValueError: pass

    since = time.time() - hours * 3600

    async with aiosqlite.connect(DB_PATH) as db:
        # Все переводы от ботовода
        async with db.execute(
            "SELECT to_id, SUM(amount), COUNT(*), MIN(ts), MAX(ts) "
            "FROM gift_log WHERE from_id=? AND ts>=? GROUP BY to_id ORDER BY SUM(amount) DESC",
            (bot_uid, since),
        ) as c:
            gifts = await c.fetchall()

        # Суммарно подарил
        async with db.execute(
            "SELECT COALESCE(SUM(amount),0), COUNT(*) FROM gift_log WHERE from_id=? AND ts>=?",
            (bot_uid, since),
        ) as c:
            total_given, gift_count = await c.fetchone()

    bf = await db_get(bot_uid)
    bname = bf.get("first_name", "?") if bf else "?"
    is_banned = bf.get("banned", 0) if bf else 0

    if not gifts:
        await update.message.reply_text(
            f"{_E_SEARCH} <b>{_html.escape(bname)}</b> <code>{bot_uid}</code>\n"
            f"Нет переводов за последние {hours} ч.",
            parse_mode=ParseMode.HTML
        )
        return

    lines = [
        f"{_E_SEARCH} <b>Расследование ботовода</b>\n"
        f"Отправитель: <b>{_html.escape(bname)}</b> <code>{bot_uid}</code>"
        f"  {f'{_E_BAN} Забанен' if is_banned else '⚠️ Активен'}\n"
        f"Период: последние {hours} ч\n"
        f"Итого раздал: <b>{total_given}🪙</b> в {gift_count} переводах → "
        f"<b>{len(gifts)}</b> игрокам\n"
    ]

    victim_ids = [row[0] for row in gifts]

    # Для каждой жертвы — сколько потратили на гачу ПОСЛЕ получения подарка
    async with aiosqlite.connect(DB_PATH) as db:
        victim_gacha = {}
        for (to_id, amount, cnt, ts_min, ts_max) in gifts:
            # Находим момент первого получения подарка от ботовода
            async with db.execute(
                "SELECT MIN(ts) FROM gift_log WHERE from_id=? AND to_id=?",
                (bot_uid, to_id),
            ) as c:
                row = await c.fetchone()
            first_gift_ts = row[0] if row and row[0] else since

            # Пуллы после получения подарка
            async with db.execute(
                "SELECT skin, rarity, cost, ts FROM gacha_log WHERE user_id=? AND ts>=? ORDER BY ts",
                (to_id, first_gift_ts),
            ) as c:
                pulls = await c.fetchall()
            victim_gacha[to_id] = pulls

    # Вывод — компактно, по жертвам
    total_pulls = 0
    total_skins_to_remove = {}  # uid → [skin, ...]
    total_coins_to_remove = {}  # uid → coins

    for to_id, amount, cnt, ts_min, ts_max in gifts[:30]:  # максимум 30 жертв в отчёте
        vf = await db_get(to_id)
        vname = vf.get("first_name", "?") if vf else "?"
        pulls = victim_gacha.get(to_id, [])
        total_pulls += len(pulls)

        coins_spent_gacha = sum(p[2] for p in pulls)
        skins_by_rarity = {}
        for skin, rarity, cost, _ in pulls:
            skins_by_rarity.setdefault(rarity, []).append(skin)
        rare_skins = [s for s in skins_by_rarity.get("secret", []) + skins_by_rarity.get("mythic", []) + skins_by_rarity.get("legendary", []) + skins_by_rarity.get("epic", [])]

        total_skins_to_remove[to_id] = [p[0] for p in pulls]
        total_coins_to_remove[to_id] = amount  # забрать ровно то, что подарили

        rarity_txt = ""
        if pulls:
            r_counts = {}
            for _, r, _, _ in pulls:
                r_counts[r] = r_counts.get(r, 0) + 1
            r_icons = R_DOT   # локальная копия таблицы редкости больше не нужна
            rarity_txt = "  " + " ".join(f"{r_icons.get(r,'?')}{n}" for r, n in sorted(r_counts.items()))

        pull_txt = f"→ {len(pulls)} пуллов{rarity_txt}" if pulls else "→ не крутил"
        lines.append(
            f"• <b>{_html.escape(vname)}</b> <code>{to_id}</code>  "
            f"получил <b>{amount}{_E_COIN}</b> {pull_txt}"
        )

    if len(gifts) > 30:
        lines.append(f"<i>...и ещё {len(gifts)-30} получателей</i>")

    lines.append(
        f"\n{_E_CHART} Итого: <b>{total_pulls}</b> пуллов у жертв после получения монет.\n"
        f"Используй /adminrollback {bot_uid} {hours} чтобы откатить всё.\n"
        f"Или /adminrollbackdry {bot_uid} {hours} для сухого запуска (без изменений)."
    )

    await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


async def _do_rollback(bot_uid: int, hours: int, dry_run: bool, bot) -> str:
    """
    Откатывает последствия раздачи монет ботоводом:
    1. Забирает у каждой жертвы ровно столько монет, сколько получила от ботовода
       (не уходя в минус)
    2. Удаляет скины из гачи которые выбили ПОСЛЕ получения подарка
    3. Возвращает монеты в общий пул (списывает с ботовода если он не забанен,
       иначе просто уничтожает)
    Возвращает текстовый отчёт.
    """
    since = time.time() - hours * 3600
    dry = "[СУХОЙ ЗАПУСК] " if dry_run else ""

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT to_id, SUM(amount) FROM gift_log WHERE from_id=? AND ts>=? GROUP BY to_id",
            (bot_uid, since),
        ) as c:
            gifts = await c.fetchall()

    if not gifts:
        return f"Нет переводов от <code>{bot_uid}</code> за последние {hours} ч."

    report_lines = [
        f"{f'{_E_SEARCH} Сухой запуск — изменений нет' if dry_run else f'{_E_HAMMER} Откат выполнен'}\n"
        f"Ботовод: <code>{bot_uid}</code> Период: {hours} ч\n"
        f"Жертв: {len(gifts)}\n"
    ]

    total_coins_removed = 0
    total_skins_removed = 0
    total_victims_affected = 0

    for to_id, gifted_amount in gifts:
        vf = await db_get(to_id)
        if not vf:
            continue

        vname = vf.get("first_name", "?")

        # Момент первого подарка
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT MIN(ts) FROM gift_log WHERE from_id=? AND to_id=?",
                (bot_uid, to_id),
            ) as c:
                row = await c.fetchone()
        first_gift_ts = row[0] if row and row[0] else since

        # Все пуллы после подарка
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT id, skin, cost FROM gacha_log WHERE user_id=? AND ts>=? ORDER BY ts",
                (to_id, first_gift_ts),
            ) as c:
                pulls = await c.fetchall()

        # Удаляем скины (каждый пулл = 1 штука в коллекции)
        skins_removed = []
        if not dry_run:
            for pull_id, skin, cost in pulls:
                await db_remove_skin(to_id, skin)
                skins_removed.append(skin)
            # Удаляем записи из gacha_log (чтобы повторный откат не отработал)
            if pulls:
                pull_ids = [str(p[0]) for p in pulls]
                async with aiosqlite.connect(DB_PATH) as db:
                    await db.execute(
                        f"DELETE FROM gacha_log WHERE id IN ({','.join(pull_ids)})"
                    )
                    await db.commit()
        else:
            skins_removed = [p[1] for p in pulls]

        # Забираем монеты: не больше чем у игрока, не больше чем подарили
        coins_to_take = min(gifted_amount, vf.get("coins", 0))
        if not dry_run:
            vf["coins"] = max(0, vf["coins"] - coins_to_take)
            # Откатываем total_gacha и coins_spent
            vf["total_gacha"] = max(0, vf.get("total_gacha", 0) - len(pulls))
            vf["coins_spent"] = max(0, vf.get("coins_spent", 0) - sum(p[2] for p in pulls))
            await db_save(vf)

        total_coins_removed += coins_to_take
        total_skins_removed += len(skins_removed)
        if pulls or coins_to_take > 0:
            total_victims_affected += 1

        # Краткая строка по жертве
        r_counts = {}
        for _, skin, _ in pulls:
            r = SKINS.get(skin, {}).get("rarity", "common")
            r_counts[r] = r_counts.get(r, 0) + 1
        r_icons = R_DOT   # локальная копия таблицы редкости больше не нужна
        rarity_txt = " ".join(f"{r_icons.get(r,'?')}{n}" for r, n in sorted(r_counts.items())) if r_counts else "—"

        report_lines.append(
            f"{dry}• <code>{to_id}</code> {_html.escape(vname)}: "
            f"-{coins_to_take}{_E_COIN} -{len(skins_removed)} скинов [{rarity_txt}]"
        )

    report_lines.append(
        f"\n{f'{_E_CHART} Будет удалено' if dry_run else f'{_E_CHECK} Итого удалено'}:\n"
        f"  {_E_COIN} Монет: <b>{total_coins_removed}</b>\n"
        f"  🎨 Скинов: <b>{total_skins_removed}</b>\n"
        f"  👤 Затронуто игроков: <b>{total_victims_affected}</b>"
    )

    # Баним ботовода если ещё не забанен
    if not dry_run:
        bf = await db_get(bot_uid)
        if bf and not bf.get("banned", 0):
            bf["banned"] = 1
            bf["coins"] = 0  # обнуляем монеты ботовода
            await db_save(bf)
            report_lines.append(f"\n{_E_BAN} Ботовод <code>{bot_uid}</code> забанен, монеты обнулены.")
        if bot:
            for aid in ADMIN_IDS:
                try:
                    await bot.send_message(
                        aid,
                        f"{_E_HAMMER} <b>Откат ботовода завершён</b>\n"
                        f"Ботовод: <code>{bot_uid}</code>\n"
                        f"Удалено: {total_coins_removed}{_E_COIN} {total_skins_removed} скинов\n"
                        f"Затронуто: {total_victims_affected} игроков",
                        parse_mode=ParseMode.HTML,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass

    return "\n".join(report_lines)


async def cmd_adminrollbackdry(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminrollbackdry [user_id] [часов=72] — сухой запуск отката (без изменений)"""
    if update.effective_user.id not in ADMIN_IDS: return
    args = update.message.text.split()
    if len(args) < 2:
        await update.message.reply_text("Использование: /adminrollbackdry 123456789 [часов]"); return
    try: bot_uid = int(args[1])
    except ValueError: await update.message.reply_text("ID числом"); return
    hours = int(args[2]) if len(args) > 2 else 72
    msg = await update.message.reply_text("🔍 Анализирую (без изменений)...")
    report = await _do_rollback(bot_uid, hours, dry_run=True, bot=ctx.bot)
    await msg.edit_text(report, parse_mode=ParseMode.HTML)


async def cmd_adminrollback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminrollback [user_id] [часов=72] — реальный откат (необратимо!)"""
    if update.effective_user.id not in ADMIN_IDS: return
    args = update.message.text.split()
    if len(args) < 2:
        await update.message.reply_text("Использование: /adminrollback 123456789 [часов]\n⚠️ Действие необратимо!"); return
    try: bot_uid = int(args[1])
    except ValueError: await update.message.reply_text("ID числом"); return
    hours = int(args[2]) if len(args) > 2 else 72

    # Требуем подтверждение через кнопку
    kb = InlineKeyboardMarkup([[
        btn("✅ Подтвердить откат", callback_data=f"rollback_confirm|{bot_uid}|{hours}", style="danger"),
        btn("❌ Отмена", callback_data="rollback_cancel", style="primary"),
    ]])
    bf = await db_get(bot_uid)
    bname = bf.get("first_name", "?") if bf else "?"

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COALESCE(SUM(amount),0), COUNT(DISTINCT to_id) FROM gift_log WHERE from_id=? AND ts>=?",
            (bot_uid, time.time() - hours * 3600),
        ) as c:
            total_coins, victim_count = await c.fetchone()

    await update.message.reply_text(
        f"⚠️ <b>Подтверди откат</b>\n\n"
        f"Ботовод: <b>{_html.escape(bname)}</b> <code>{bot_uid}</code>\n"
        f"Период: {hours} ч\n"
        f"Жертв: ~{victim_count} Монет в раздаче: {total_coins}{_E_COIN}\n\n"
        f"Это удалит скины из гачи и заберёт монеты у всех получателей.\n"
        f"<b>Необратимо.</b> Сначала сделай /backup",
        parse_mode=ParseMode.HTML, reply_markup=kb,
    )



async def _resolve_staya(staya_arg: str) -> tuple[int | None, str]:
    """
    Принимает строку — либо числовой ID стаи, либо часть названия.
    Возвращает (staya_id, staya_name) или (None, "") если не найдено.
    """
    async with aiosqlite.connect(DB_PATH) as db:
        # Сначала пробуем как число
        try:
            staya_id = int(staya_arg)
            async with db.execute("SELECT id, name FROM stayas WHERE id=?", (staya_id,)) as c:
                row = await c.fetchone()
            if row:
                return row[0], row[1]
        except ValueError:
            pass
        # Иначе ищем по названию (регистронезависимо, частичное совпадение)
        async with db.execute(
            "SELECT id, name FROM stayas WHERE lower(name) LIKE lower(?) ORDER BY id LIMIT 5",
            (f"%{staya_arg}%",)
        ) as c:
            rows = await c.fetchall()
    if not rows:
        return None, ""
    if len(rows) == 1:
        return rows[0][0], rows[0][1]
    # Несколько совпадений — вернём первое но предупредим через None id и список в name
    matches = ", ".join(f"«{r[1]}» (id={r[0]})" for r in rows)
    return None, f"MULTIPLE:{matches}"


async def cmd_adminundo(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/adminundo — откатить разные действия в игре.
    staya_id можно заменить на название стаи (или его часть).
    """
    if update.effective_user.id not in ADMIN_IDS:
        return
    args = update.message.text.split()
    if len(args) < 3:
        await update.message.reply_text(
            f"{_E_LIST} <b>/adminundo — откат действий</b>\n\n"
            "<b>staya_id</b> — ID или <b>название стаи</b> (часть названия тоже работает)\n\n"
            "<code>/adminundo staya_kick &lt;uid&gt; &lt;staya_id/название&gt;</code>\n"
            "→ Вернуть игрока в стаю как Жителя\n\n"
            "<code>/adminundo staya_role &lt;uid&gt; &lt;staya_id/название&gt; chief|elder|member</code>\n"
            "→ Сменить роль игрока\n\n"
            "<code>/adminundo staya_chief &lt;uid&gt; &lt;staya_id/название&gt;</code>\n"
            "→ Назначить вожаком (старый вожак → Старейшина)\n\n"
            "<code>/adminundo coins &lt;uid&gt; &lt;+N или -N&gt;</code>\n"
            "→ Изменить монеты игрока\n\n"
            "<code>/adminundo pity &lt;uid&gt; &lt;N&gt;</code>\n"
            "→ Установить питти счётчик гачи\n\n"
            "<code>/adminundo staya_find &lt;название&gt;</code>\n"
            "→ Найти стаю по названию и узнать её ID",
            parse_mode=ParseMode.HTML,
        )
        return

    action = args[1]

    # ── Поиск стаи по названию ───────────────────────────────────────────────
    if action == "staya_find":
        query = " ".join(args[2:])
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT id, name, emoji, level FROM stayas WHERE lower(name) LIKE lower(?) ORDER BY id LIMIT 10",
                (f"%{query}%",)
            ) as c:
                rows = await c.fetchall()
        if not rows:
            await update.message.reply_text(f"{_E_CROSS} Стай с названием «{he(query)}» не найдено.", parse_mode=ParseMode.HTML)
            return
        lines = [f"{_E_SEARCH} Найдено стай: {len(rows)}\n"]
        for r in rows:
            lines.append(f"{r[2]} <b>{he(r[1])}</b> ID: <code>{r[0]}</code> Ур.{r[3]}")
        await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)
        return

    # ── Хелпер: разрешить staya из args[3] ──────────────────────────────────
    async def get_staya(idx: int) -> tuple[int | None, str]:
        if len(args) <= idx:
            return None, ""
        staya_arg = " ".join(args[idx:])  # название может содержать пробелы — берём всё после
        # Но для staya_role последний аргумент — роль, не часть названия
        # Поэтому caller должен передать правильный срез
        return await _resolve_staya(staya_arg)

    if action in ("staya_kick", "staya_chief", "staya_role"):
        if len(args) < 4:
            await update.message.reply_text(f"Использование: /adminundo {action} <uid> <staya_id или название>")
            return
        try:
            target_uid = int(args[2])
        except ValueError:
            await update.message.reply_text("❌ uid должен быть числом.")
            return
        tf = await db_get(target_uid)
        if not tf:
            await update.message.reply_text("❌ Игрок не найден.")
            return

        # Для staya_role роль — последний аргумент, staya — всё между uid и ролью
        if action == "staya_role":
            if len(args) < 5:
                await update.message.reply_text("Использование: /adminundo staya_role <uid> <staya> chief|elder|member")
                return
            new_role = args[-1]
            if new_role not in ("chief", "elder", "member"):
                await update.message.reply_text("❌ Роль: chief / elder / member")
                return
            staya_arg = " ".join(args[3:-1])
        else:
            staya_arg = " ".join(args[3:])

        staya_id, staya_name = await _resolve_staya(staya_arg)
        if staya_name.startswith("MULTIPLE:"):
            await update.message.reply_text(
                f"⚠️ Найдено несколько стай — уточни название или используй ID:\n{staya_name[9:]}",
                parse_mode=ParseMode.HTML,
            )
            return
        if not staya_id:
            await update.message.reply_text(
                f"{_E_CROSS} Стая «{he(staya_arg)}» не найдена\n"
                f"Поиск: <code>/adminundo staya_find название</code>", parse_mode=ParseMode.HTML
            )
            return

        if action == "staya_kick":
            async with aiosqlite.connect(DB_PATH) as db:
                async with db.execute("SELECT user_id FROM staya_members WHERE staya_id=? AND user_id=?", (staya_id, target_uid)) as c:
                    already = await c.fetchone()
                if already:
                    await update.message.reply_text(f"ℹ️ <b>{he(fname(tf))}</b> уже в стае «{he(staya_name)}».", parse_mode=ParseMode.HTML)
                    return
                await db.execute(
                    "INSERT OR IGNORE INTO staya_members(staya_id, user_id, role, joined_at) VALUES(?,?,'member',?)",
                    (staya_id, target_uid, time.time()),
                )
                await db.commit()
            tf["staya_id"] = staya_id
            await db_save(tf)
            await update.message.reply_text(
                f"{_E_CHECK} <b>{he(fname(tf))}</b> возвращён в стаю «{he(staya_name)}» как Житель.",
                parse_mode=ParseMode.HTML,
            )
            try:
                await ctx.bot.send_message(target_uid, f"✅ Администратор вернул тебя в стаю «{he(staya_name)}».", parse_mode=ParseMode.HTML)
            except (BadRequest, Forbidden, TimedOut):
                pass

        elif action == "staya_role":
            async with aiosqlite.connect(DB_PATH) as db:
                cur = await db.execute("UPDATE staya_members SET role=? WHERE staya_id=? AND user_id=?", (new_role, staya_id, target_uid))
                await db.commit()
            if cur.rowcount == 0:
                await update.message.reply_text(f"{_E_CROSS} <b>{he(fname(tf))}</b> не состоит в стае «{he(staya_name)}».", parse_mode=ParseMode.HTML)
                return
            role_names = {"chief": "🐸 Вожак", "elder": "🦎 Старейшина", "member": "🐟 Житель"}
            await update.message.reply_text(
                f"{_E_CHECK} <b>{he(fname(tf))}</b> в стае «{he(staya_name)}» → {role_names[new_role]}",
                parse_mode=ParseMode.HTML,
            )

        elif action == "staya_chief":
            async with aiosqlite.connect(DB_PATH) as db:
                await db.execute("UPDATE staya_members SET role='elder' WHERE staya_id=? AND role='chief'", (staya_id,))
                cur = await db.execute("UPDATE staya_members SET role='chief' WHERE staya_id=? AND user_id=?", (staya_id, target_uid))
                await db.commit()
            if cur.rowcount == 0:
                await update.message.reply_text(f"{_E_CROSS} <b>{he(fname(tf))}</b> не состоит в стае «{he(staya_name)}».", parse_mode=ParseMode.HTML)
                return
            await update.message.reply_text(
                f"{_E_CHECK} <b>{he(fname(tf))}</b> назначен {_E_FROG} Вожаком стаи «{he(staya_name)}».\nСтарый вожак понижен до 🦎 Старейшины.",
                parse_mode=ParseMode.HTML,
            )

    elif action == "coins":
        if len(args) < 4:
            await update.message.reply_text("Использование: /adminundo coins <uid> <+N или -N>"); return
        try:
            target_uid, delta = int(args[2]), int(args[3])
        except ValueError:
            await update.message.reply_text("❌ Числа."); return
        tf = await db_get(target_uid)
        if not tf: await update.message.reply_text("❌ Игрок не найден."); return
        old_coins = tf["coins"]
        tf["coins"] = max(0, tf["coins"] + delta)
        await db_save(tf)
        await update.message.reply_text(
            f"{_E_CHECK} <b>{he(fname(tf))}</b> монеты: {old_coins} → <b>{tf['coins']}</b> ({delta:+d})",
            parse_mode=ParseMode.HTML,
        )

    elif action == "pity":
        if len(args) < 4:
            await update.message.reply_text("Использование: /adminundo pity <uid> <N>"); return
        try:
            target_uid, new_pity = int(args[2]), int(args[3])
        except ValueError:
            await update.message.reply_text("❌ Числа."); return
        tf = await db_get(target_uid)
        if not tf: await update.message.reply_text("❌ Игрок не найден."); return
        old_pity = tf.get("gacha_pity", 0)
        tf["gacha_pity"] = max(0, min(new_pity, PITY_THRESHOLD))
        await db_save(tf)
        await update.message.reply_text(
            f"{_E_CHECK} <b>{he(fname(tf))}</b> питти: {old_pity} → <b>{tf['gacha_pity']}</b>",
            parse_mode=ParseMode.HTML,
        )

    elif action == "staya_restore":
        # /adminundo staya_restore <creator_uid> <название> [emoji]
        # Восстанавливает удалённую стаю. Участников нужно добавлять через staya_kick отдельно.
        if len(args) < 4:
            await update.message.reply_text(
                "Использование: /adminundo staya_restore <creator_uid> <название> [emoji]\n"
                "Пример: /adminundo staya_restore 123456789 Болотные🐸\n\n"
                "После восстановления добавь участников:\n"
                "/adminundo staya_kick <uid> <staya_id>",
            )
            return
        try:
            creator_uid = int(args[2])
        except ValueError:
            await update.message.reply_text("❌ creator_uid должен быть числом."); return

        staya_name  = args[3]
        staya_emoji = args[4] if len(args) >= 5 else "🌿"

        creator_f = await db_get(creator_uid)
        if not creator_f:
            await update.message.reply_text("❌ Создатель не найден."); return

        # Проверяем не состоит ли создатель уже в стае
        existing = await staya_of_user(creator_uid)
        if existing:
            await update.message.reply_text(
                f"⚠️ Игрок уже состоит в стае «{existing['name']}» (id={existing['id']}).\n"
                f"Сначала выйди оттуда или используй другой uid."
            )
            return

        async with aiosqlite.connect(DB_PATH) as db:
            cur = await db.execute(
                "INSERT INTO stayas(name, emoji, creator_id, level, xp, cauldron, created_at) "
                "VALUES (?, ?, ?, 1, 0, 0, ?)",
                (staya_name, staya_emoji, creator_uid, time.time()),
            )
            new_staya_id = cur.lastrowid
            await db.execute(
                "INSERT INTO staya_members(staya_id, user_id, role, joined_at) VALUES (?,?,'chief',?)",
                (new_staya_id, creator_uid, time.time()),
            )
            await db.commit()

        creator_f["staya_id"] = new_staya_id
        await db_save(creator_f)

        await update.message.reply_text(
            f"{_E_CHECK} <b>Стая восстановлена!</b>\n\n"
            f"{staya_emoji} <b>{he(staya_name)}</b> (id={new_staya_id})\n"
            f"Вожак: <b>{he(fname(creator_f))}</b>\n\n"
            f"Чтобы добавить участников:\n"
            f"<code>/adminundo staya_kick &lt;uid&gt; {new_staya_id}</code>",
            parse_mode=ParseMode.HTML,
        )
        try:
            await ctx.bot.send_message(
                creator_uid,
                f"✅ <b>Твоя стая «{he(staya_name)}» восстановлена!</b>\n\n"
                f"Зайди в /staya чтобы увидеть её.",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass

    else:
        await update.message.reply_text(f"{_E_CROSS} Неизвестное действие: <code>{action}</code>\nНапиши /adminundo для справки.", parse_mode=ParseMode.HTML)


async def handle_rollback_callback(q, d, uid, ctx):
    if uid not in ADMIN_IDS: await q.answer("Нет доступа", show_alert=True); return

    if d == "rollback_cancel":
        try: await q.message.edit_text("❌ Откат отменён.")
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    if d.startswith("rollback_confirm|"):
        parts = d.split("|")
        bot_uid, hours = int(parts[1]), int(parts[2])
        try: await q.message.edit_text("🔨 Выполняю откат... Это может занять несколько секунд.")
        except (BadRequest, Forbidden, TimedOut):
            pass
        report = await _do_rollback(bot_uid, hours, dry_run=False, bot=ctx.bot)
        # Отчёт может быть длинным — отправляем новым сообщением
        try:
            await q.message.reply_text(report, parse_mode=ParseMode.HTML)
        except Exception:
            # Если слишком длинный — обрезаем
            await q.message.reply_text(report[:3900] + "\n<i>...обрезано</i>", parse_mode=ParseMode.HTML)
        return


async def cmd_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    # Защита от конфликта команд: если в группе настроен ignore_start — молчим
    if is_group(update):
        cs = await get_chat_settings(update.effective_chat.id)
        if cs.get("ignore_start", 0):
            return  # не реагируем на /start в этом чате

    user = update.effective_user
    f = await db_get(user.id)
    is_new = f is None

    # ── Обработка deep-link аргументов ───────────────
    referrer_id = None
    start_source_chat_id = 0  # чат откуда пришёл через deep link

    if ctx.args:
        arg = ctx.args[0]

        # ── Повтор ква (диплинк из кнопки "Ещё раз") ─────────────────────────
        if arg == "kva_retry":
            if not f:
                await update.message.reply_text("Сначала /start 🐸")
                return
            _stars_cost = NFT_KVA_STARS
            _coins_cost = NFT_KVA_COINS
            await update.message.reply_text(
                f"{_E_FROG} <b>Квакнуть ещё раз?</b>\n\n"
                f"Каждый бросок — шанс 1/{NFT_KVA_TOTAL} на Chill Flame NFT.\n\n"
                f"Выбери способ:",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [btn(
                        f"{_stars_cost} Stars",
                        callback_data="kva_retry_stars",
                        icon_id="6028338546736107668"
                    ),
                    btn(
                        f"{_stars_cost * 10} Stars ×10",
                        callback_data="kva_retry_stars_10",
                        icon_id="6028338546736107668"
                    )],
                    [btn(
                        f"{_coins_cost}{_E_COIN}",
                        callback_data="kva_retry_coins"
                    )],
                    [btn("❌ Закрыть", callback_data="kva_retry_cancel")],
                ]),
            )
            return

        # ── Диплинк на покупку кубиков льда (/start icecube) ─────────────────
        if arg == "icecube":
            if not f:
                await update.message.reply_text("Сначала /start 🐸")
                return
            await cmd_icecube(update, ctx)
            return

        # ── Приглашение в соседи: ?start=addneighbor_123456 ───────────────────
        # Доступно и новым, и существующим игрокам.
        if arg.startswith("addneighbor_"):
            try:
                neighbor_id = int(arg.removeprefix("addneighbor_"))
                if neighbor_id != user.id and await db_get(neighbor_id):
                    await add_bond(user.id, neighbor_id)
                    try:
                        await ctx.bot.send_message(
                            neighbor_id,
                            f"🏘 <b>{he(user.first_name)}</b> принял приглашение и стал соседом.",
                            parse_mode=ParseMode.HTML,
                        )
                    except (BadRequest, Forbidden, TimedOut):
                        pass
            except (ValueError, TypeError):
                pass

        # Партнёрский чат: ?start=chat_-1001234567
        if arg.startswith("chat_"):
            try:
                start_source_chat_id = int(arg[5:])
            except Exception as _e:
                logger.exception("подавлено исключение: %s", _e)
        # Реферал: ?start=ref_123456
        elif is_new and arg.startswith("ref_"):
            try:
                ref_id = int(arg[4:])
                if ref_id != user.id:
                    referrer = await db_get(ref_id)
                    if referrer:
                        async with aiosqlite.connect(DB_PATH) as db:
                            async with db.execute(
                                "SELECT COUNT(*) FROM referrals WHERE referrer_id=?",
                                (ref_id,),
                            ) as c:
                                ref_count = (await c.fetchone())[0]
                        if ref_count < 50000:
                            referrer_id = ref_id
            except Exception as _e:
                logger.exception("подавлено исключение: %s", _e)

    # ── Если /start написан прямо в партнёрском чате — владелец чата становится реферером ──
    if is_new and not referrer_id and is_group(update):
        group_chat_id = update.effective_chat.id
        if not start_source_chat_id:
            start_source_chat_id = group_chat_id
        try:
            pc = await partner_chat_get(group_chat_id)
            if pc and pc.get("added_by_uid"):
                chat_owner_id = pc["added_by_uid"]
                if chat_owner_id != user.id:
                    referrer_owner = await db_get(chat_owner_id)
                    if referrer_owner:
                        async with aiosqlite.connect(DB_PATH) as db:
                            async with db.execute(
                                "SELECT COUNT(*) FROM referrals WHERE referrer_id=?",
                                (chat_owner_id,),
                            ) as c:
                                ref_count = (await c.fetchone())[0]
                        if ref_count < 50000:
                            referrer_id = chat_owner_id
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)

    # Устанавливаем source_chat_id если ещё не задан (при первом входе или новом источнике)
    if start_source_chat_id and not is_new and f:
        if not f.get("source_chat_id", 0):
            f["source_chat_id"] = start_source_chat_id
            await db_save(f)

    if is_new:
        f = await new_frog(user)
        # 🧑‍🍼 Стартовый пробник отключён — не выдаём подписку автоматически
        # asyncio.create_task(grant_trial(
        #     user.id, 1, 3, bot=ctx.bot,
        #     reason="Добро пожаловать! Тётя Жаба присмотрит за твоей лягушкой первые 3 дня 🐸"
        # ))
        if start_source_chat_id:
            f["source_chat_id"] = start_source_chat_id
            await db_save(f)
            # Приветственное сообщение чата (если задано администратором)
            try:
                _wcs = await get_chat_settings(start_source_chat_id)
                _wmsg = _wcs.get("welcome_message", "")
                if _wmsg:
                    await update.message.reply_text(
                        f"👋 <b>Привет от сообщества!</b>\n\n{he(_wmsg)}",
                        parse_mode=ParseMode.HTML,
                        link_preview_options=LinkPreviewOptions(is_disabled=True),
                    )
            except (BadRequest, Forbidden, TimedOut):
                pass
        # Создаём реферальную запись
        if referrer_id:
            async with aiosqlite.connect(DB_PATH) as db:
                try:
                    await db.execute(
                        "INSERT OR IGNORE INTO referrals(referrer_id, referred_id, joined_at, stage_mask) VALUES(?,?,?,0)",
                        (referrer_id, user.id, time.time()),
                    )
                    await db.commit()
                except Exception as _e:
                    logger.exception("подавлено исключение: %s", _e)
            # ── Конкурс: записываем реферала ─────────────────────────────────
            _active_contest = await _get_active_contest()
            if _active_contest:
                # fraud_flag пока 0 — антинакрут проверим ниже
                await _record_contest_referral(referrer_id, user.id, _active_contest["id"], fraud_flag=0)

            # ── Антинакрут-проверка ──────────────────────────────────────────
            suspect, reason = await _antibot_check(referrer_id, user.id, user)
            if suspect:
                # Замораживаем — не выдаём награду немедленно
                await _freeze_ref_reward(referrer_id, user.id, reason)
                # Помечаем тикет конкурса как подозрительный
                async with aiosqlite.connect(DB_PATH) as _cdb:
                    await _cdb.execute(
                        "UPDATE contest_referrals SET fraud_flag=1 WHERE referrer_id=? AND referred_id=? AND ticket_valid=0",
                        (referrer_id, user.id),
                    )
                    await _cdb.commit()
                throttle_key = f"aab_notified_{referrer_id}"
                if not ctx.bot_data.get(throttle_key) or time.time() - ctx.bot_data[throttle_key] > 1800:
                    ctx.bot_data[throttle_key] = time.time()
                    for aid in ADMIN_IDS:
                        try:
                            rf = await db_get(referrer_id)
                            rn = rf.get("first_name", "?") if rf else "?"
                            await ctx.bot.send_message(
                                aid,
                                f"⚠️ <b>Антинакрут</b>\n"
                                f"Реферер: <b>{_html.escape(rn)}</b> <code>{referrer_id}</code>\n"
                                f"Реферал: <code>{user.id}</code> @{user.username or '—'}\n"
                                f"Причина: <i>{reason}</i>\n\n"
                                f"Награда заморожена. /adminantibot для проверки.",
                                parse_mode=ParseMode.HTML,
                            )
                        except Exception as _e:
                            logger.exception("подавлено исключение: %s", _e)
            else:
                # Чисто → выдаём +50 монет рефереру сразу
                await _referral_stage_reward(referrer_id, user.id, 0, ctx.bot)

        # ── ЗНАКОМСТВО — шаг 1: одна кнопка, ноль чтения ──────────────────────
        f["onboard_step"] = 1
        await db_save(f)
        await funnel_bump(1)
        _ob_extra = ""
        if referrer_id:
            _ref_f = await db_get(referrer_id)
            if _ref_f:
                _ob_extra = f"{_E_USERS} Тебя позвал {he(fname(_ref_f))}."
        _ob_text, _ob_kb = onboard_screen(f, 1, extra=_ob_extra)
        await update.message.reply_text(
            _ob_text, parse_mode=ParseMode.HTML, reply_markup=_ob_kb,
        )
        return
    else:
        f = decay(f)
        f["first_name"] = user.first_name or f["first_name"]
        f["username"] = user.username or f["username"]
        await db_save(f)

        # Если пришёл по deep-link ивента — сразу показываем кнопку участия
        if ctx.args and ctx.args[0] == "sacrifice":
            ev = await _sacrifice_active_event()
            if ev:
                sac_kb = InlineKeyboardMarkup([
                    [btn(
                        "🔥 Участвовать в жертвоприношении!",
                        callback_data=f"sacrifice_join_{ev['id']}",
                    )],
                    [btn("◀️ Моя лягушка", callback_data="refresh")],
                ])
                await group_reply(
                    update,
                    f"{_E_FIRE} <b>Ивент «{SACRIFICE_EVENT_NAME}»</b>\n\n"
                    f"💰 Банк: <b>{ev['total_bank']}{coin_emoji()}</b>\n"
                    f"⏳ Заканчивается: <b>{int((ev['end_time'] - time.time()) // 3600)}ч "
                    f"{int(((ev['end_time'] - time.time()) % 3600) // 60)}м</b>\n\n"
                    f"Сожги эпические облики — и побори за главный приз!",
                    parse_mode=ParseMode.HTML,
                    reply_markup=sac_kb,
                )
                return

        # Воронка deep-link: ?start=funnel
        if ctx.args and ctx.args[0] == "funnel":
            ev_f = await _funnel_active_event()
            if ev_f:
                await update.message.reply_text(
                    f"{_E_FIRE} Нажми кнопку, чтобы перейти в ивент:",
                    reply_markup=InlineKeyboardMarkup([[
                        btn("🔥 Воронка", callback_data=f"funnel_menu_{ev_f['id']}")
                    ]]), parse_mode=ParseMode.HTML
                )
                return

        # Deep-link для вступления в экспедицию: ?start=exp_join_<id>
        if ctx.args and ctx.args[0].startswith("exp_join_"):
            try:
                _exp_join_id = int(ctx.args[0].removeprefix("exp_join_"))
                _exp_to_join = await _exp_get(_exp_join_id)
                if _exp_to_join and _exp_to_join["status"] == "lobby" and time.time() < _exp_to_join["gather_until"]:
                    # Сразу открываем экран снаряжения для вступления
                    ctx.user_data["exp_joining"] = _exp_join_id
                    ctx.user_data["exp_joining_id"] = _exp_join_id
                    ctx.user_data["exp_gear_join"] = {"food": 0, "potion": 0, "torch": 0, "amulet": 0}
                    ctx.user_data["exp_coins"] = 0
                    ctx.user_data["exp_coins_join"] = 0
                    f = decay(f)
                    sent_msg = await update.message.reply_text("🗺️ Загружаем экспедицию...", parse_mode=ParseMode.HTML)
                    # Create a fake CallbackQuery-like object using a workaround
                    # Instead send the gear setup as a new message
                    bc = EXP_BIOMES[_exp_to_join["biome"]]
                    gear = {"food": 0, "potion": 0, "torch": 0, "amulet": 0}
                    inv = (json.loads(f["inventory"]) if isinstance(f.get("inventory"), str) else f.get("inventory")) or {}
                    max_coins = min(bc["max_coins"], f.get("coins", 0))
                    exp_id_j = _exp_to_join["id"]
                    biome_j = _exp_to_join["biome"]
                    lines = [
                        f"🗺️ <b>{bc['emoji']} {bc['name']}</b>\n"
                        f"Вступаешь в экспедицию!\n"
                        "\n"
                        f"<i>Максимум {EXP_MAX_SUPPLY_TOTAL} припасов.</i>\n"
                    ]
                    for k, info in SUPPLY_TYPES.items():
                        if "emoji" not in info:
                            continue
                        lines.append(f"{info['emoji']} <b>{info['name']}</b>: 0 <i>(в инв: {inv.get(k,0)})</i>")
                    lines.append(f"\n{_E_MONEYBAG} Монет взять: 0{_E_COIN}")
                    buttons = []
                    for k, info in SUPPLY_TYPES.items():
                        if "emoji" not in info:
                            continue
                        buttons.append([
                            btn(f"{info['emoji']} -1", callback_data=f"exp_gear_adj_{biome_j}_0_0_{k}_-1"),
                            btn(f"{info['name']} (0)", callback_data="noop"),
                            btn(f"{info['emoji']} +1", callback_data=f"exp_gear_adj_{biome_j}_0_0_{k}_1"),
                        ])
                    buttons.append([
                        btn("💰 -100", callback_data=f"exp_coins_join_{exp_id_j}_{max(0, 0-100)}"),
                        btn("0🪙", callback_data="noop"),
                        btn("💰 +100", callback_data=f"exp_coins_join_{exp_id_j}_100"),
                    ])
                    buttons.append([
                        btn("💰 MAX", callback_data=f"exp_coins_join_{exp_id_j}_{max_coins}"),
                        btn("💰 0",   callback_data=f"exp_coins_join_{exp_id_j}_0"),
                    ])
                    buttons.append([btn("✅ Вступить", callback_data=f"exp_confirm_join_{exp_id_j}", style="success")])
                    buttons.append([btn("🏪 Магазин экспедиций", callback_data="exp_shop")])
                    try:
                        await sent_msg.edit_text("\n".join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(buttons))
                    except Exception:
                        await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(buttons))
                    return
            except (BadRequest, Forbidden, TimedOut):
                pass

        # Deep-link для вступления в ИДУЩУЮ экспедицию: ?start=exp_mid_join_<id>
        if ctx.args and ctx.args[0].startswith("exp_mid_join_"):
            try:
                _mid_exp_id = int(ctx.args[0].removeprefix("exp_mid_join_"))
                _mid_exp = await _exp_get(_mid_exp_id)
                if _mid_exp and _mid_exp["status"] == "active":
                    _mid_members = await _exp_get_members(_mid_exp_id)
                    _active_count = sum(1 for _mm in _mid_members if _mm["status"] == "active")
                    f = decay(f)
                    if not f.get("alive"):
                        await update.message.reply_text(f"{_E_SKULL} Мёртвая лягушка не может присоединиться к экспедиции.", parse_mode=ParseMode.HTML)
                        return
                    _already_active = await _exp_get_user_active(user.id)
                    if _already_active:
                        await update.message.reply_text(f"{_E_CROSS} Ты уже участвуешь в другой экспедиции!", parse_mode=ParseMode.HTML)
                        return
                    if len(_mid_members) >= _mid_exp["max_players"]:
                        await update.message.reply_text("😔 Команда уже заполнена — места не осталось.", parse_mode=ParseMode.HTML)
                        return
                    if any(_mm["user_id"] == user.id for _mm in _mid_members):
                        await update.message.reply_text("Ты уже в этой экспедиции", parse_mode=ParseMode.HTML)
                        return
                    _mid_bc = EXP_BIOMES[_mid_exp["biome"]]
                    if f.get("level", 1) < _mid_bc["min_level"]:
                        await update.message.reply_text(f"🔒 Нужен уровень {_mid_bc['min_level']} для этого биома.", parse_mode=ParseMode.HTML)
                        return
                    ctx.user_data["exp_mid_joining"] = _mid_exp_id
                    ctx.user_data["exp_joining_id"] = _mid_exp_id
                    ctx.user_data["exp_gear_join"] = {"food": 0, "potion": 0, "torch": 0, "amulet": 0}
                    ctx.user_data["exp_coins_join"] = 0
                    inv = (json.loads(f["inventory"]) if isinstance(f.get("inventory"), str) else f.get("inventory")) or {}
                    max_coins = min(_mid_bc["max_coins"], f.get("coins", 0))
                    # Сколько примерно осталось
                    left_s = max(0, int(_mid_exp["ends_at"] - time.time()))
                    left_h, left_rem = divmod(left_s, 3600)
                    left_m = left_rem // 60
                    _mid_lines = [
                        f"🤝 <b>Случайная встреча в пути!</b>\n"
                        f"Путник попросил присоединиться к вашей экспедиции...\n\n"
                        f"{_mid_bc['emoji']} <b>{_mid_bc['name']}</b>\n"
                        f"{_E_USERS} Участники: {_active_count}/{_mid_exp['max_players']}\n"
                        f"⏱ До конца: <b>{left_h}ч {left_m}м</b>\n\n"
                        f"<i>Максимум {EXP_MAX_SUPPLY_TOTAL} припасов.</i>\n"
                    ]
                    for k, info in SUPPLY_TYPES.items():
                        if "emoji" not in info:
                            continue
                        _mid_lines.append(f"{info['emoji']} <b>{info['name']}</b>: 0 <i>(в инв: {inv.get(k,0)})</i>")
                    _mid_lines.append(f"\n{_E_MONEYBAG} Монет взять: 0{_E_COIN}")
                    _mid_buttons = []
                    for k, info in SUPPLY_TYPES.items():
                        if "emoji" not in info:
                            continue
                        _mid_buttons.append([
                            btn(f"{info['emoji']} -1", callback_data=f"exp_gear_adj_{_mid_exp['biome']}_0_0_{k}_-1"),
                            btn(f"{info['name']} (0)", callback_data="noop"),
                            btn(f"{info['emoji']} +1", callback_data=f"exp_gear_adj_{_mid_exp['biome']}_0_0_{k}_1"),
                        ])
                    _mid_buttons.append([
                        btn("💰 -100", callback_data=f"exp_coins_join_{_mid_exp_id}_{max(0, 0-100)}"),
                        btn("0🪙", callback_data="noop"),
                        btn("💰 +100", callback_data=f"exp_coins_join_{_mid_exp_id}_100"),
                    ])
                    _mid_buttons.append([
                        btn("💰 MAX", callback_data=f"exp_coins_join_{_mid_exp_id}_{max_coins}"),
                        btn("💰 0",   callback_data=f"exp_coins_join_{_mid_exp_id}_0"),
                    ])
                    _mid_buttons.append([btn("✅ Присоединиться к экспедиции", callback_data=f"exp_confirm_mid_join_{_mid_exp_id}", style="success")])
                    _mid_buttons.append([btn("🏪 Магазин экспедиций", callback_data="exp_shop")])
                    await update.message.reply_text("\n".join(_mid_lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(_mid_buttons))
                    return
            except Exception as _emj:
                logger.warning("exp_mid_join deep-link error: %s", _emj)

        _is_group_start = update.effective_chat.type in ("group", "supergroup")
        kb = await main_kb_live(f, is_group=_is_group_start)
        text = status_text(f)
        await group_reply(update, text, parse_mode=ParseMode.HTML, reply_markup=kb)


async def cmd_frog(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not await group_cmd_guard(update, "frog", ctx):
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await group_reply(update, "У тебя нет лягушки! Напиши /start 🐸")
        return

    # ── Возврат монет если незавершённая double-игра осталась в памяти ──
    lost_game = ctx.user_data.pop(f"double_{user.id}", None)
    if lost_game:
        refund = lost_game["bank"]  # возвращаем текущий банк (уже включает выигрыши)
        f["coins"] += refund
        await db_save(f)
        try:
            await update.message.reply_text(
                f"⚠️ Твоя незавершённая игра «Double or Nothing» была отменена.\n"
                f"{_E_MONEYBAG} Тебе возвращено: <b>{refund}{coin_emoji()}</b>",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass

    f = decay(f)
    await db_save(f)
    # ── Фриз-ивент: ежедневный бесплатный кубик при первом входе за день ──────
    asyncio.create_task(_fz_free_cube(user.id, "free_daily", ctx.bot))
    text = status_text(f)
    _frog_group = update.effective_chat.type in ("group", "supergroup")
    kb = await main_kb_live(f, is_group=_frog_group)
    try:
        msg = await update.message.reply_text(
            text,
            parse_mode=ParseMode.HTML,
            reply_markup=kb,
            link_preview_options=LinkPreviewOptions(),
        )
        # Сохраняем владельца сообщения для защиты кнопок в группах
        if msg:
            msg_key = f"{msg.chat.id}_{msg.message_id}"
            ctx.bot_data.setdefault("msg_owner", {})[msg_key] = user.id
    except (BadRequest, Forbidden):
        pass


def _build_top_lines(rows: list[dict], mode: str = "all", user_row: dict = None,
                     user_rank: int = None, user_total: int = None,
                     badges: dict[int, str] = None) -> str:
    """
    badges — значки владельцев гифтов из nft_badges(). Не передали — топ
    рисуется как раньше, без них.
    """
    badges = badges or {}
    medals = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]
    if mode == "week":
        l_id = user_row.get("league", 0) if user_row else 0
        l_emoji, l_name, *_ = league_info(l_id)
        title = f"📅 <b>Топ недели — {l_emoji} {l_name}</b>"
        xp_key = "xp_week"
    elif mode == "month":
        title = "📆 <b>Топ месяца — по XP</b>"
        xp_key = "xp_month"
    elif mode == "league":
        l_id = user_row.get("league", 0) if user_row else 0
        l_emoji, l_name, l_min, _ = league_info(l_id)
        next_league = next(((e, n, m) for lid, e, n, m, _ in LEAGUES if lid == l_id + 1), None)
        next_line = (f"\n<i>До {next_league[0]} {next_league[1]}: {next_league[2]:,} XP/нед</i>" if next_league else "")
        title = f"{l_emoji} <b>Лига «{l_name}»</b>{next_line}"
        xp_key = "xp_week"
    else:
        title = "🏆 <b>Таблица лидеров</b>"
        xp_key = None
    lines = [title + "\n"]
    top_ids = set()
    now_top = time.time()
    for i, r in enumerate(rows):
        if i >= len(medals):
            break
        top_ids.add(r["user_id"])
        name = he(r["frog_name"] if r["frog_name"] else r["first_name"] or "?")
        s = SKINS.get(r["skin"], SKINS["Brownie"])
        dead = " 💀" if not r["alive"] else ""
        # Значок лиги
        l_badge = league_badge(r.get("league", 0)) if not xp_key else ""
        # Значок подписки
        sub_badge = ""
        if r.get("subscription_until", 0) > now_top and r.get("subscription_type", 0) >= 2:
            sub_badge = " 👑"
        elif r.get("subscription_until", 0) > now_top and r.get("subscription_type", 0) == 1:
            sub_badge = " 🌿"
        if xp_key:
            xp_val = r.get(xp_key, 0)
            lines.append(
                f"{medals[i]} <b>{name}</b>{sub_badge}{badges.get(r['user_id'], '')} — "
                f"<b>+{xp_val:,} XP</b> {pemoji(r['skin'])}"
            )
        else:
            lines.append(
                f"{medals[i]} {l_badge}<b>{name}</b>{dead}{sub_badge}{badges.get(r['user_id'], '')} — "
                f"ур.{r['level']} {R_DOT[s['rarity']]} {pemoji(r['skin'])}"
            )
    if not lines[1:]:
        return title + "\n\nЕщё никто не играет!"
    # Показываем позицию пользователя если он не в топ-10
    if user_row and user_rank and user_row.get("user_id") not in top_ids:
        name = he(user_row.get("frog_name") or user_row.get("first_name", "?"))
        s = SKINS.get(user_row.get("skin", "Brownie"), SKINS["Brownie"])
        dead = " 💀" if not user_row.get("alive") else ""
        total_str = f"/{user_total}" if user_total else ""
        lines.append(f"\n┄┄┄┄┄┄┄┄┄┄")
        if xp_key:
            xp_val = user_row.get(xp_key, 0)
            lines.append(f"#{user_rank}{total_str} <b>{name}</b> — <b>+{xp_val:,} XP</b> {pemoji(user_row.get('skin','Brownie'))}")
        else:
            lines.append(f"#{user_rank}{total_str} <b>{name}</b>{dead} — ур.{user_row.get('level',1)} {R_DOT[s['rarity']]} {pemoji(user_row.get('skin','Brownie'))}")
    # Кружки владельцев гифтов в топе стояли без пояснения: игрок видел
    # значок у чужого имени и не понимал, откуда он берётся и как получить свой.
    if badges and any(badges.get(r["user_id"]) for r in rows[:len(medals)]):
        lines.append("\n<i>Кружок у имени — редкость KissedFrog игрока.</i>")
    return "\n".join(lines)



async def cmd_topsponsors(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/topsponsors — топ щедрых спонсоров чата (не считая /gift)"""
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала напиши /start")
        return

    # Определяем чат для фильтрации (в группе — текущий, в ЛС — source_chat_id игрока)
    if is_group(update):
        filter_cid = update.effective_chat.id
        chat_label = he(update.effective_chat.title or str(filter_cid))
        # Топ по source_chat_id этого чата
        cid_filter = "AND source_chat_id = ?"
        params = (filter_cid, 20)
    else:
        cid_filter = ""
        params = (20,)
        chat_label = "всего бота"

    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        query = (
            "SELECT user_id, first_name, username, chat_sponsor_coins, level "
            "FROM frogs WHERE is_bot=0 AND banned=0 AND chat_sponsor_coins > 0 "
            f"{cid_filter} "
            "ORDER BY chat_sponsor_coins DESC LIMIT ?"
        )
        async with db.execute(query, params) as c:
            rows = await c.fetchall()
        # Позиция текущего игрока
        pos_query = (
            "SELECT COUNT(*)+1 FROM frogs "
            "WHERE chat_sponsor_coins > (SELECT chat_sponsor_coins FROM frogs WHERE user_id=?) "
            f"AND is_bot=0 AND banned=0 {cid_filter}"
        )
        pos_params = (user.id, filter_cid) if is_group(update) else (user.id,)
        async with db.execute(pos_query, pos_params) as c:
            my_pos = (await c.fetchone())[0]
        async with db.execute(
            "SELECT chat_sponsor_coins FROM frogs WHERE user_id=?", (user.id,)
        ) as c:
            my_row = await c.fetchone()
        my_donated = my_row["chat_sponsor_coins"] if my_row else 0

    if not rows:
        text = (
            f"💝 <b>Топ спонсоров — {chat_label}</b>\n\n"
            f"Пока никто не спонсировал активности чата.\n"
            f"Запусти розыгрыш: <code>/giveaway 100</code>"
        )
        kb = InlineKeyboardMarkup([
            [btn("🔄 Обновить", callback_data="topsponsors_refresh")]
        ])
    else:
        medals = ["🥇", "🥈", "🥉"] + ["💝"] * 17
        lines = [f"💝 <b>Топ спонсоров — {chat_label}</b>\n<i>Учитываются /giveaway и прочие активности</i>\n"]
        for i, r in enumerate(rows):
            tag = f"@{r['username']}" if r["username"] else f"id{r['user_id']}"
            lines.append(
                f"{medals[i]} <b>{he(r['first_name'])}</b> ({tag})\n"
                f"   💝 {r['chat_sponsor_coins']:,}{_E_COIN} · ур.{r['level']}"
            )
        lines.append(f"\n<i>Твоя позиция: #{my_pos} · Ты задонатил: {my_donated:,}{_E_COIN}</i>")
        text = "\n".join(lines)
        kb = InlineKeyboardMarkup([
            [btn("🔄 Обновить", callback_data="topsponsors_refresh")]
        ])

    msg = await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
    if msg and is_group(update):
        asyncio.create_task(schedule_delete(update.get_bot(), msg.chat.id, msg.message_id))


async def _build_forbes_text(viewer_uid: int) -> tuple[str, InlineKeyboardMarkup]:
    """
    Строит текст и клавиатуру Форбса.
    Топ-20 по монетам. По умолчанию все анонимны (🕵️ Аноним #N).
    Игрок, у которого forbes_public=1, виден всем.
    Кнопка под списком позволяет переключить свою видимость.
    """
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT user_id, first_name, username, coins, level, skin, forbes_public "
            "FROM frogs WHERE is_bot=0 AND banned=0 AND alive=1 "
            "ORDER BY coins DESC LIMIT 20"
        ) as c:
            rows = await c.fetchall()

    medals = ["🥇","🥈","🥉"] + ["💰"] * 17
    lines = [f"{_E_GEM} <b>Forbes — Топ богачей</b>\n"]
    viewer_pos = None

    for i, r in enumerate(rows):
        is_public = r["forbes_public"] == 1
        is_viewer = r["user_id"] == viewer_uid
        if is_viewer:
            viewer_pos = i + 1

        if is_public:
            name = he(r["first_name"] or "?")
            tag = f"@{r['username']}" if r["username"] else f"id{r['user_id']}"
            label = f"<b>{name}</b> ({tag})"
        else:
            # Анонимная строка — показываем только позицию и монеты
            # Но сам игрок видит свой псевдоним с пометкой (ты)
            label = f"🕵️ Аноним #{i+1}"
            if is_viewer:
                label += " <i>(это ты)</i>"

        lines.append(
            f"{medals[i]} {label}\n"
            f"   {_E_COIN} {r['coins']:,} · ур.{r['level']}"
        )

    # Позиция смотрящего если его нет в топ-20
    if viewer_pos is None:
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT COUNT(*)+1 FROM frogs "
                "WHERE coins > (SELECT coins FROM frogs WHERE user_id=?) "
                "AND is_bot=0 AND banned=0 AND alive=1",
                (viewer_uid,)
            ) as c:
                r_pos = await c.fetchone()
            viewer_pos_global = r_pos[0] if r_pos else "?"
        lines.append(f"\n<i>Твоя позиция: #{viewer_pos_global}</i>")

    # Кнопка переключения публичности для просматривающего
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT forbes_public FROM frogs WHERE user_id=?", (viewer_uid,)
        ) as c:
            vrow = await c.fetchone()
    is_my_public = vrow["forbes_public"] == 1 if vrow else False

    toggle_label = "🙈 Скрыть себя из Forbes" if is_my_public else "👁 Показать себя в Forbes"
    toggle_cb = "forbes_hide" if is_my_public else "forbes_show"

    kb = InlineKeyboardMarkup([
        [btn(toggle_label, callback_data=toggle_cb)],
        [btn("🔄 Обновить", callback_data="forbes_refresh")],
    ])
    return "\n".join(lines), kb


async def cmd_forbes(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/forbes — топ богатейших игроков (анонимно по умолчанию)"""
    user = update.effective_user
