async def cmd_heal(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/heal — вылечить лягушку (15🪙, кд 1 час)."""
    if not await group_cmd_guard(update, "heal", ctx):
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text(f"Сначала напиши /start {_E_FROG}", parse_mode=ParseMode.HTML)
        return
    if not f["alive"]:
        await update.message.reply_text(f"{_E_SKULL} Лягушка мертва! Используй /revive", parse_mode=ParseMode.HTML)
        return
    cost = 15
    if f["coins"] < cost:
        await update.message.reply_text(
            f"💸 Нужно {cost}{coin_emoji()}, у тебя {f['coins']}.",
            parse_mode=ParseMode.HTML,
        )
        return
    now = time.time()
    cd = 3600
    if now - f.get("last_heal", 0) < cd:
        rem = int(cd - (now - f["last_heal"]))
        await update.message.reply_text(f"⏳ Ещё {rem//60} мин {rem%60} сек.")
        return
    f["health"] = min(100, f["health"] + 40)
    f["coins"] -= cost
    f["coins_spent"] = f.get("coins_spent", 0) + cost
    f["last_heal"] = now
    add_xp(f, 5)
    add_power(f, 0.1)
    rewards = await levelup(f, ctx.bot)
    await db_save(f)
    await quest_update(user.id, "heals")
    await legend_track(user.id, "heals", bot=ctx.bot)
    f["total_heals"] = f.get("total_heals", 0) + 1
    await db_save(f)
    result = f"💊 <b>Вылечена!</b> <i>Чувствует себя лучше {_E_HEART}</i>\n{_E_HEART}+40 -{cost}{coin_emoji()}"
    for lvl, skin in rewards:
        result += f"\n🎉 <b>Уровень {lvl}!</b> Облик: {display_skin(skin)}"
    await update.message.reply_text(
        result + f"\n\n{status_text(f)}",
        parse_mode=ParseMode.HTML,
        reply_markup=care_kb(f),
    )


async def cmd_revive(update: Update, ctx: ContextTypes.DEFAULT_TYPE):  # plog inserted below
    if not await group_cmd_guard(update, "revive", ctx):
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return
    if f["alive"]:
        await update.message.reply_text("Лягушка жива! 🐸")
        return
    is_overfeed = f.get("death_reason", "") == "overfeed"
    cost = OVERFEED_REVIVE_COST if is_overfeed else 100
    has_coins = f["coins"] >= cost
    coins_txt = (
        f"У тебя: <b>{f['coins']}🪙</b>" if has_coins
        else f"⚠️ Нехватает монет: {f['coins']}🪙 из {cost}🪙"
    )

    # Если идёт испытание — показываем прогресс
    if f.get("trial_active", 0):
        quests = json.loads(f.get("trial_quests", "[]"))
        prog   = json.loads(f.get("trial_progress", "{}"))
        done   = sum(1 for tq in quests if prog.get(tq["id"], 0) >= tq["goal"])
        total  = len(quests)
        lines  = [f"{_E_SWORDS} <b>Испытание идёт!</b> Прогресс: <b>{done}/{total}</b>\n"]
        for i, tq in enumerate(quests, 1):
            cur  = prog.get(tq["id"], 0)
            mark = "✅" if cur >= tq["goal"] else "🔲"
            lines.append(f"{mark} {i}. {tq['desc']} — {cur}/{tq['goal']}")
        lines.append(f"\n{coins_txt}")
        await update.message.reply_text(
            "\n".join(lines),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [btn(f"💀 Воскресить ({cost}🪙)", callback_data="revive_confirm", style="success")],
                [btn("📊 Прогресс", callback_data="trial_status"),
                 btn("🎲 Игры", callback_data="menu_games")],
            ]),
        )
        return

    if is_overfeed:
        await update.message.reply_text(
            f"🤢 <b>{fname(f)} объелась и лопнула!</b>\n\n"
            f"Накоплено сытости: <b>{f.get('overfeed_total', 0)} / {OVERFEED_DEATH_THRESHOLD}</b>\n\n"
            f"• Воскресить за <b>{cost}{_E_COIN}</b> — желудок промывается, счётчик сбрасывается\n"
            f"  {coins_txt}",
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [btn(f"🤢 Воскресить ({cost}🪙)", callback_data="revive_confirm", style="success")],
                [btn("⭐ Мгновенно (15 Stars)", callback_data="revive_stars", style="primary", icon_id="6028338546736107668")],
            ]),
        )
        return

    # ── История лягушки ──────────────────────────────────────────────
    now_rv     = time.time()
    days_lived = max(0, int((now_rv - f.get("born_at", now_rv)) / 86400))
    feeds      = f.get("total_feeds", 0)
    mosquitoes = f.get("total_mosquitoes", 0)
    duel_wins  = f.get("total_duel_wins", 0)
    casino_w   = f.get("total_casino_wins", 0)
    gacha_n    = f.get("total_gacha", 0)
    level      = f.get("level", 1)
    skin_name  = f.get("skin", "Brownie")
    skin_d     = SKINS.get(skin_name, {})
    skin_line  = f"{pemoji(skin_name)} {skin_name} ({R_NAME.get(skin_d.get('rarity', 'common'), '?')})"

    history_lines = []
    if days_lived == 0:   history_lines.append("Прожила меньше суток")
    elif days_lived == 1: history_lines.append("Прожила 1 день")
    else:                 history_lines.append(f"Прожила <b>{days_lived}</b> дн.")
    if feeds:      history_lines.append(f"Съела <b>{feeds}</b> порций")
    if mosquitoes: history_lines.append(f"Поймала <b>{mosquitoes}</b> комаров")
    if duel_wins:  history_lines.append(f"Выиграла <b>{duel_wins}</b> дуэлей")
    if casino_w:   history_lines.append(f"Победила в казино <b>{casino_w}</b> раз")
    if gacha_n:    history_lines.append(f"Крутила гачу <b>{gacha_n}</b> раз")

    history_text = " · ".join(history_lines)

    text = (
        f"💀 <b>{fname(f)} погибла.</b>\n\n"
        f"<i>{history_text}</i>\n"
        f"Уровень: <b>{level}</b> · Облик: {skin_line}\n\n"
        f"<b>Выбери способ воскрешения:</b>\n\n"
        f"За <b>{cost}{_E_COIN}</b> — лягушка ожьёт с 50% показателей\n"
        f"  {coins_txt}\n\n"
        f"{_E_STARS} За <b>15 Stars</b> — мгновенно, 100% показателей\n\n"
        f"{_E_SWORDS} <b>Испытание</b> — бесплатно, выполни 3 задания→ полные показатели + бонусы"
    )
    kb = InlineKeyboardMarkup([
        [btn(f"🪙 Воскресить ({cost}🪙)", callback_data="revive_confirm",
             style="success" if has_coins else None)],
        [btn("⭐ Мгновенно (15 Stars)", callback_data="revive_stars", style="primary", icon_id="6028338546736107668")],
        [btn("⚔️ Начать испытание (бесплатно)", callback_data="trial_start")],
        [btn("🔄 Обновить испытание", callback_data="trial_reset")],
    ])
    await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)


async def cmd_gift(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    # Пересланное сообщение с /gift — чужая команда, выполненная от лица игрока.
    if (
        getattr(update.message, "forward_origin", None) is not None
        or getattr(update.message, "forward_from", None) is not None
        or getattr(update.message, "forward_date", None) is not None
    ):
        await update.message.reply_text(
            f"{_E_CROSS} Команду нельзя переслать", parse_mode=ParseMode.HTML
        )
        return
    if not await group_cmd_guard(update, "gift", ctx):
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return
    if f.get("banned", 0):
        await update.message.reply_text("🚫 Ваш аккаунт заблокирован администрацией.")
        return

    reply = update.message.reply_to_message
    target = None
    amount_arg = None
    comment = None

    if reply and reply.from_user and not reply.from_user.is_bot:
        # Режим ответа: /gift 50 [комментарий] в ответ на сообщение
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            async with db.execute("SELECT * FROM frogs WHERE user_id=?", (reply.from_user.id,)) as c:
                row = await c.fetchone()
        if not row:
            await update.message.reply_text(f"😕 {he(reply.from_user.first_name)} ещё не завёл лягушку")
            return
        target = dict(row)
        amount_arg = ctx.args[0] if ctx.args else None
        comment = " ".join(ctx.args[1:]) if len(ctx.args) > 1 else None
    elif ctx.args and ctx.args[0].startswith("@"):
        # Классический режим: /gift @username 50 [комментарий]
        mention = ctx.args[0].lstrip("@")
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            async with db.execute("SELECT * FROM frogs WHERE username=?", (mention,)) as c:
                row = await c.fetchone()
        if not row:
            await update.message.reply_text(f"@{mention} ещё не завёл лягушку 😕")
            return
        target = dict(row)
        amount_arg = ctx.args[1] if len(ctx.args) > 1 else None
        comment = " ".join(ctx.args[2:]) if len(ctx.args) > 2 else None
    else:
        await update.message.reply_text(
            "Пример: <code>/gift @username 50</code>\n"
            "С комментарием: <code>/gift @username 50 Спасибо за дуэль!</code>\n"
            "Или ответь на сообщение: <code>/gift 50 Держи!</code>",
            parse_mode=ParseMode.HTML
        )
        return

    try:
        amount = int(amount_arg) if amount_arg else 0
    except ValueError:
        await update.message.reply_text("❌ Укажи сумму числом!")
        return
    if amount <= 0:
        await update.message.reply_text("❌ Укажи сумму > 0!")
        return
    if amount > f["coins"]:
        await update.message.reply_text(f"💸 У тебя {f['coins']}{coin_emoji()}!", parse_mode=ParseMode.HTML)
        return
    if target["user_id"] == user.id:
        await update.message.reply_text("❌ Нельзя подарить себе")
        return

    # ── Проверка риска отправителя ────────────────────────────────────────────
    _blocked, _block_msg = await risk_block_check(user.id, "transfer")
    if _blocked:
        await update.message.reply_text(_block_msg)
        return
    # rate_limit переводов отключён вручную
    # _ok_out/_ok_in всегда True

    # ── Заморозка переводов ───────────────────────────────────────────────────
    # Заморозку ставит либо автоматика ниже, либо админ кнопкой «Продлить».
    # Проверка работает всегда, даже когда автоматика выключена.
    _now_gift = time.time()
    _freeze_key = (user.id, target["user_id"])
    if _GIFT_FROZEN.get(_freeze_key, 0) > _now_gift:
        _left = int(_GIFT_FROZEN[_freeze_key] - _now_gift)
        await update.message.reply_text(
            f"{_E_BAN} Переводы заморожены\n"
            f"Осталось: {_left // 60} мин {_left % 60} сек",
            parse_mode=ParseMode.HTML,
        )
        return

    # Всплеск одинаковых сумм от разных отправителей — почерк накрутки:
    # десятки ботов переводят по N монет. Ключ — только сумма, получатели разные.
    if GIFT_ANTISPAM:
        _tracker = [
            rec for rec in _GIFT_SPAM_TRACKER.get(amount, [])
            if _now_gift - rec[0] < 60
        ]
        _GIFT_SPAM_TRACKER[amount] = _tracker
        _senders = {sid for _, sid, _ in _tracker} | {user.id}
        if len(_senders) >= GIFT_ANTISPAM_SENDERS:
            _until = _now_gift + GIFT_ANTISPAM_FREEZE
            for _, _sid, _tid in _tracker:
                _GIFT_FROZEN[(_sid, _tid)] = _until
            _GIFT_FROZEN[_freeze_key] = _until
            _review_id = f"gift_spam_{int(_now_gift)}_{amount}"
            _GIFT_PENDING_REVIEW[_review_id] = {
                "senders": sorted(_senders),
                "target_id": target["user_id"],
                "amount": amount,
                "freeze_until": _until,
            }
            if ADMIN_IDS:
                try:
                    await ctx.bot.send_message(
                        ADMIN_IDS[0],
                        f"{_E_BAN} <b>Всплеск переводов</b>\n"
                        f"Сумма: <b>{amount}</b>{_E_COIN}\n"
                        f"Отправителей за минуту: <b>{len(_senders)}</b>\n"
                        f"{', '.join(f'<code>{s}</code>' for s in sorted(_senders)[:10])}\n\n"
                        f"Переводы заморожены на {GIFT_ANTISPAM_FREEZE // 3600} ч.",
                        parse_mode=ParseMode.HTML,
                        reply_markup=InlineKeyboardMarkup([[
                            btn("✅ Разморозить", callback_data=f"gift_unfreeze_{_review_id}"),
                            btn("🚫 Продлить 24ч", callback_data=f"gift_keepfreeze_{_review_id}"),
                        ]]),
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass
            await update.message.reply_text(
                f"{_E_BAN} Похоже на накрутку.\nПереводы заморожены.",
                parse_mode=ParseMode.HTML,
            )
            return
        _tracker.append((_now_gift, user.id, target["user_id"]))

    # ── Лок на списание монет — защита от race condition с on_callback ───────
    _gift_lock = _get_user_lock(user.id)
    if _gift_lock.locked():
        await update.message.reply_text("⏳ Подожди, предыдущая операция ещё обрабатывается.")
        return
    await _gift_lock.acquire()
    _gift_task = asyncio.current_task()
    if _gift_task:
        def _release_gift_lock(t, _lk=_gift_lock):
            try:
                if _lk.locked(): _lk.release()
            except RuntimeError:
                pass
        _gift_task.add_done_callback(_release_gift_lock)

    # Атомарная проверка и списание через SQL UPDATE с WHERE — единственная защита
    # от параллельных операций: если между db_get и db_save кто-то уже потратил монеты,
    # UPDATE вернёт 0 затронутых строк и мы откатимся.
    async with aiosqlite.connect(DB_PATH) as _atomic_db:
        cur = await _atomic_db.execute(
            "UPDATE frogs SET coins = coins - ? WHERE user_id = ? AND coins >= ?",
            (amount, user.id, amount)
        )
        await _atomic_db.commit()
        if cur.rowcount == 0:
            # Не хватило монет в момент списания (параллельная операция успела раньше)
            await update.message.reply_text(f"💸 Недостаточно монет для перевода!")
            return

    # Списание прошло атомарно — инвалидируем кэш отправителя
    _user_cache.invalidate(user.id)
    f = await db_get(user.id)  # свежий баланс после SQL UPDATE
    if not f:
        await update.message.reply_text("Не вышло. Попробуй ещё раз.")
        return

    # Атомарно начисляем получателю через SQL — НЕ через db_save (перезапишет кэш)
    target_uid = target["user_id"]
    async with aiosqlite.connect(DB_PATH) as _credit_db:
        cur2 = await _credit_db.execute(
            "UPDATE frogs SET coins = coins + ? WHERE user_id = ?",
            (amount, target_uid)
        )
        await _credit_db.commit()
        if cur2.rowcount == 0:
            # Получатель не найден в БД — откат
            async with aiosqlite.connect(DB_PATH) as _rb:
                await _rb.execute("UPDATE frogs SET coins = coins + ? WHERE user_id = ?", (amount, user.id))
                await _rb.commit()
            await update.message.reply_text("❌ Ошибка перевода, монеты возвращены.")
            return

    # Инвалидируем кэш получателя чтобы следующий db_get вернул актуальный баланс
    _user_cache.invalidate(target_uid)
    target_fresh = await db_get(target_uid)
    if not target_fresh:
        target_fresh = target  # fallback для имени
    # Логируем перевод
    async with aiosqlite.connect(DB_PATH) as _gdb:
        await _gdb.execute(
            "INSERT INTO gift_log(from_id, to_id, amount, ts) VALUES(?,?,?,?)",
            (user.id, target["user_id"], amount, time.time()),
        )
        await _gdb.commit()
    t_disp = f"@{target['username']}" if target.get("username") else he(target.get("first_name", ""))
    comment_line = f"\n💬 <i>{_html.escape(comment[:100])}</i>" if comment else ""
    await update.message.reply_text(
        f"{_E_GIFT} <b>{he(user.first_name)}</b> подарил <b>{amount}{coin_emoji()}</b> игроку {t_disp}!{comment_line}\n"
        f"Лягушка говорит: <i>Квак! Спасибо!</i> 💚\n"
        f"У тебя осталось: {f['coins']}{coin_emoji()}",
        parse_mode=ParseMode.HTML,
    )
    try:
        # Проверяем настройку уведомлений о переводах у получателя
        _gift_notify = target_fresh.get("gift_notify", 0)
        _send_notif = True
        if _gift_notify == 1:
            # Только от соседей по стае
            _sender_staya = f.get("staya_id") or 0
            _target_staya = target_fresh.get("staya_id") or 0
            if not (_sender_staya and _sender_staya == _target_staya):
                _send_notif = False
        if _send_notif:
            await ctx.bot.send_message(
                target["user_id"],
                f"{_E_GIFT} <b>{he(user.first_name)}</b> подарил тебе <b>{he(amount)}{coin_emoji()}</b>!{comment_line}\n"
                f"Теперь у тебя: {target_fresh['coins']}{coin_emoji()}",
                parse_mode=ParseMode.HTML,
            )
    except (BadRequest, Forbidden, TimedOut):
        pass
    # ── Обновляем квесты и испытание после воскрешения ────────────────────
    await quest_update(user.id, "gift")
    asyncio.create_task(update_trial_progress(user.id, "gift", 1, ctx.bot))


async def cmd_tournament(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/tournament [ставка] — создать турнир в чате"""
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return
    if f.get("banned", 0):
        await update.message.reply_text("🚫 Ваш аккаунт заблокирован администрацией.")
        return
    _tn_blocked, _tn_msg = await risk_block_check(user.id, "tournament")
    if _tn_blocked:
        await update.message.reply_text(_tn_msg)
        return
    # Блок для совсем новых аккаунтов
    _tn_ok, _tn_reason = True, ""  # rate_limit розыгрышей отключён
    _age = time.time() - (f.get("born_at") or 0)
    if _age < _NEW_ACCOUNT_AGE_HARD and "tournament_create" in _NEW_ACCOUNT_BLOCKED:
        days_left = int((_NEW_ACCOUNT_AGE_HARD - _age) / 86400) + 1
        await update.message.reply_text(f"🐣 Турниры доступны после {days_left} д. с регистрации.")
        return
    if not f["alive"]:
        await update.message.reply_text("💀 Твоя лягушка мертва! Используй /revive")
        return
    stake = 50
    if ctx.args:
        try:
            arg_stake = int(ctx.args[0])
            if arg_stake < 10:
                await update.message.reply_text("❌ Минимальная ставка: 10🪙")
                return
            if arg_stake > 5000:
                await update.message.reply_text(f"{_E_CROSS} Максимальная ставка: 5000{_E_COIN}", parse_mode=ParseMode.HTML)
                return
            stake = arg_stake
        except ValueError:
            await update.message.reply_text("❌ Укажи число: /tournament 100")
            return
    if f["coins"] < stake:
        await update.message.reply_text(
            f"Нужно {stake}{coin_emoji()} для создания турнира!",
            parse_mode=ParseMode.HTML,
        )
        return
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT INTO tournaments(creator_id,stake,status,created_at,chat_id,participants) VALUES(?,?,?,?,?,?)",
            (
                user.id,
                stake,
                "waiting",
                now,
                update.effective_chat.id,
                json.dumps([user.id]),
            ),
        )
        await db.commit()
        async with db.execute("SELECT last_insert_rowid()") as c:
            tid = (await c.fetchone())[0]
    kb = InlineKeyboardMarkup(
        [
            [
                btn(
                    "⚔️ Вступить!", callback_data=f"tournament_join_{tid}"
                ),
                btn(
                    "🚀 Начать", callback_data=f"tournament_start_{tid}"
                ),
            ]
        ]
    )
    tourn_msg = await update.message.reply_text(
        f"{_E_TROPHY} <b>Турнир #{tid} открыт!</b>\n\n"
        f"Создатель: <b>{user.first_name}</b>\n"
        f"Ставка входа: <b>{stake}{coin_emoji()}</b>\n"
        f"Участников: <b>1</b>\n\n"
        f"<i>Жми «Вступить»! Нужно минимум 3 участника.</i>",
        parse_mode=ParseMode.HTML,
        reply_markup=kb,
    )
    if tourn_msg and is_group(update):
        asyncio.create_task(
            schedule_delete(
                update.get_bot(), tourn_msg.chat.id, tourn_msg.message_id, 300
            )
        )


