    if not target["alive"]:
        t_display = f"@{target['username']}" if target.get("username") else he(target.get("first_name", ""))
        await update.message.reply_text(f"{_E_SKULL} Лягушка {t_display} умерла.", parse_mode=ParseMode.HTML)
