async def cmd_removeskin(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Забрать облик: /removeskin @username НазваниеОблика"""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return
    if len(ctx.args) < 2:
        await update.message.reply_text(
            "Использование: /removeskin @username НазваниеОблика"
        )
        return
    mention = ctx.args[0].lstrip("@")
    skin_name = " ".join(ctx.args[1:])
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM frogs WHERE username=?", (mention,)) as c:
            row = await c.fetchone()
    if not row:
        await update.message.reply_text(f"{_E_CROSS} @{he(mention)} не найден", parse_mode=ParseMode.HTML)
        return
    target = dict(row)
    # Проверяем коллекцию из таблицы collections (не устаревшее поле skins)
    coll = await db_coll(target["user_id"])
    matched_skin = next((s for s in coll if s.lower() == skin_name.lower()), None)
    if not matched_skin:
        await update.message.reply_text(
            f"{_E_CROSS} У @{he(mention)} нет облика «{he(skin_name)}».\n"
            f"Всего обликов в коллекции: {he(len(coll))}.", parse_mode=ParseMode.HTML
        )
        return
    await db_remove_skin(target["user_id"], matched_skin)
    # Если это активный облик — сбрасываем на Brownie
    if target.get("skin") == matched_skin:
        target["skin"] = "Brownie"
        await db_save(target)
    _user_cache.invalidate(target["user_id"])
    await update.message.reply_text(
        f"{_E_CHECK} Облик <b>{_html.escape(matched_skin)}</b> забран у @{mention}!",
        parse_mode=ParseMode.HTML,
    )
    try:
        await ctx.bot.send_message(
            target["user_id"],
            f"⚠️ Администратор забрал у вас облик <b>{_html.escape(matched_skin)}</b>.",
            parse_mode=ParseMode.HTML,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass


async def cmd_adminlookup(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Поиск игрока: /adminlookup @username, ID или игровое имя лягушки"""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return
    if not ctx.args:
        await update.message.reply_text(
            "Использование: /adminlookup @username, ID или игровое имя лягушки"
        )
        return
    query = " ".join(ctx.args).lstrip("@")
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        if query.isdigit():
            async with db.execute("SELECT * FROM frogs WHERE user_id=?", (int(query),)) as c:
                row = await c.fetchone()
        else:
            # Сначала ищем по username (точное совпадение)
            async with db.execute("SELECT * FROM frogs WHERE username=?", (query,)) as c:
                row = await c.fetchone()
            if not row:
                # Потом по игровому имени лягушки (частичное)
                async with db.execute(
                    "SELECT * FROM frogs WHERE frog_name LIKE ? ORDER BY level DESC LIMIT 1",
                    (f"%{query}%",)
                ) as c:
                    row = await c.fetchone()
            if not row:
                # Потом по реальному имени (частичное)
                async with db.execute(
                    "SELECT * FROM frogs WHERE first_name LIKE ? ORDER BY level DESC LIMIT 1",
                    (f"%{query}%",)
                ) as c:
                    row = await c.fetchone()
    if not row:
        await update.message.reply_text(f"{_E_CROSS} Игрок не найден: {he(query)}", parse_mode=ParseMode.HTML)
        return
    target_uid = dict(row)["user_id"]
    await show_player_card(update.message, target_uid, edit=False, back_cb="admin_players_0")



