# 🔍 ADMIN: ЛОГИ ДЕЙСТВИЙ ИГРОКА
# ══════════════════════════════════════════════════════════════════════════════

async def cmd_adminplayerlogs(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /adminplayerlogs @username|ID [дней=3]
    Отправляет текстовый файл с логами игрока за последние N дней.
    Ищет все действия: казино, дуэли, подарки, смерти, воскрешения и т.д.
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return

    if not ctx.args:
        await update.message.reply_text(
            "Использование: <code>/adminplayerlogs @username|ID [дней=3]</code>\n\n"
            "Примеры:\n"
            "<code>/adminplayerlogs @vasya</code> — последние 3 дня\n"
            "<code>/adminplayerlogs 123456789 7</code> — последние 7 дней",
            parse_mode=ParseMode.HTML,
        )
        return

    query = ctx.args[0].lstrip("@")
    days = 3
    if len(ctx.args) >= 2:
        try:
            days = max(1, min(30, int(ctx.args[1])))
        except ValueError:
            pass

    # Ищем игрока
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        if query.isdigit():
            async with db.execute("SELECT user_id, first_name, frog_name, username FROM frogs WHERE user_id=?", (int(query),)) as c:
                frow = await c.fetchone()
        else:
            async with db.execute("SELECT user_id, first_name, frog_name, username FROM frogs WHERE username=?", (query,)) as c:
                frow = await c.fetchone()
            if not frow:
                async with db.execute(
                    "SELECT user_id, first_name, frog_name, username FROM frogs WHERE frog_name LIKE ? ORDER BY level DESC LIMIT 1",
                    (f"%{query}%",)
                ) as c:
                    frow = await c.fetchone()

    if not frow:
        await update.message.reply_text(f"{_E_CROSS} Игрок не найден: {he(query)}", parse_mode=ParseMode.HTML)
        return

    frow = dict(frow)
    target_uid = frow["user_id"]
    display_name = frow.get("frog_name") or frow.get("first_name") or str(target_uid)
    uname_str = f"@{frow['username']}" if frow.get("username") else f"ID:{target_uid}"

    logs = await plog_get(target_uid, days=days, limit=1000)

    if not logs:
        await update.message.reply_text(
            f"📭 Нет логов для <b>{_html.escape(display_name)}</b> ({uname_str}) за последние {days} дн.",
            parse_mode=ParseMode.HTML,
        )
        return

    # Формируем текстовый файл
    lines = [
        f"═══ ЛОГИ ИГРОКА ═══",
        f"Игрок: {display_name} ({uname_str})",
        f"ID: {target_uid}",
        f"Период: последние {days} дн. ({len(logs)} записей)",
        f"Дата выгрузки: {datetime.now(timezone.utc).strftime('%d.%m.%Y %H:%M')} UTC",
        f"═══════════════════════════════════════",
        "",
    ]

    # Группировка по дням
    from collections import defaultdict
    by_day: dict = defaultdict(list)
    for row in logs:
        dt_obj = datetime.fromtimestamp(row["ts"], tz=timezone.utc)
        day_key = dt_obj.strftime("%d.%m.%Y")
        by_day[day_key].append(row)

    total_coins_delta = 0
    action_counts: dict = defaultdict(int)

    for day_key in sorted(by_day.keys(), reverse=True):
        lines.append(f"── {day_key} ──────────────────────────────")
        for row in reversed(by_day[day_key]):  # хронологический порядок внутри дня
            dt_obj = datetime.fromtimestamp(row["ts"], tz=timezone.utc)
            ts_str = dt_obj.strftime("%H:%M:%S")
            cd = row["coins_delta"]
            hd = row["hp_delta"]
            coins_str = f"  [{'+' if cd >= 0 else ''}{cd}🪙]" if cd != 0 else ""
            hp_str = f"  [{'+' if hd >= 0 else ''}{hd}HP]" if hd != 0 else ""
            details = f"  — {row['details']}" if row["details"] else ""
            lines.append(f"  {ts_str} {row['action']}{coins_str}{hp_str}{details}")
            total_coins_delta += cd
            action_counts[row["action"]] += 1
        lines.append("")

    # Итоговая статистика
    lines.append("═══ ИТОГИ ═══════════════════════════════")
    lines.append(f"Всего действий: {len(logs)}")
    lines.append(f"Нетто монет: {total_coins_delta:+d}{_E_COIN}")
    lines.append("")
    lines.append("По типам:")
    for action, cnt in sorted(action_counts.items(), key=lambda x: -x[1]):
        lines.append(f"  {action}: {cnt}")

    file_text = "\n".join(lines)
    file_bytes = file_text.encode("utf-8")

    import io
    bio = io.BytesIO(file_bytes)
    bio.name = f"logs_{target_uid}_{days}d.txt"
    bio.seek(0)

    await update.message.reply_document(
        document=bio,
        filename=bio.name,
        caption=(
            f"📋 <b>Логи игрока</b> {_html.escape(display_name)} ({uname_str})\n"
            f"За {days} дн. — <b>{len(logs)}</b> записей\n"
            f"Нетто монет: <b>{total_coins_delta:+d}🪙</b>"
        ),
        parse_mode=ParseMode.HTML,
    )


