async def cmd_admintops(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /admintops — все топы для администратора:
      • Топ каждой лиги (по xp_week)
      • Глобальный топ по уровню (без разбивки по лигам)
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return

    await update.message.reply_text("⏳ Загружаю топы...", parse_mode=ParseMode.HTML)

    sections: list[str] = []

    # ── 1. Топ каждой лиги ──────────────────────────────────────────
    for lid, emoji, name, min_xp, coin_reward in LEAGUES:
        rows = await db_top_league(lid, 15)
        # Считаем сколько всего в лиге
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT COUNT(*) FROM frogs WHERE league=? AND is_bot=0 AND banned=0", (lid,)
            ) as c:
                total_in_league = (await c.fetchone())[0]

        if not rows:
            sections.append(f"{emoji} <b>{name}</b> (0 игроков)\n<i>Пусто</i>")
            continue

        lines = [f"{emoji} <b>{name}</b> ({total_in_league} игроков, мин. {min_xp:,} XP/нед)"]
        for i, r in enumerate(rows, 1):
            rname = r.get("frog_name") or r.get("first_name") or "—"
            xpw = r.get("xp_week", 0)
            lvl = r.get("level", 1)
            medal = "🥇" if i == 1 else ("🥈" if i == 2 else ("🥉" if i == 3 else f"{i}."))
            lines.append(f"  {medal} {_html.escape(rname)} Ур.{lvl} {xpw:,} XP")
        sections.append("\n".join(lines))

    # ── 2. Глобальный топ по уровню (без лиг) ───────────────────────
    global_rows = await db_top(20)
    if global_rows:
        lines = ["🌍 <b>Глобальный топ</b> (по уровню, без лиг)"]
        for i, r in enumerate(global_rows, 1):
            rname = r.get("frog_name") or r.get("first_name") or "—"
            lvl = r.get("level", 1)
            medal = "🥇" if i == 1 else ("🥈" if i == 2 else ("🥉" if i == 3 else f"{i:>2}."))
            alive_mark = "" if r.get("alive", 1) else " 💀"
            lines.append(f"  {medal} {_html.escape(rname)} Ур.{lvl}{alive_mark}")
        sections.append("\n".join(lines))

    # ── 3. Недельный топ (все лиги вместе) ──────────────────────────
    week_rows = await db_top_weekly(15)
    if week_rows:
        lines = [f"{_E_CALENDAR} <b>Недельный XP топ</b> (все лиги)"]
        for i, r in enumerate(week_rows, 1):
            rname = r.get("frog_name") or r.get("first_name") or "—"
            xpw = r.get("xp_week", 0)
            medal = "🥇" if i == 1 else ("🥈" if i == 2 else ("🥉" if i == 3 else f"{i:>2}."))
            lines.append(f"  {medal} {_html.escape(rname)} {xpw:,} XP")
        sections.append("\n".join(lines))

    # Отправляем секциями (каждая секция — отдельное сообщение чтобы не упереться в лимит)
    for section in sections:
        try:
            await update.message.reply_text(section, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.warning("admintops section send error: %s", e)


async def cmd_setsticker(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/setsticker <action> <indices> — установить индексы стикеров для действия"""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return
    if len(ctx.args) < 2:
        actions_list = ", ".join(ACTION_STICKER_LABELS.keys())
        await update.message.reply_text(
            f"Использование: /setsticker <action> <indices>\n"
            f"Действия: {actions_list}\n"
            f"Пример: /setsticker feed 0,1,2,3"
        )
        return
    action = ctx.args[0].lower()
    if action not in ACTION_STICKER_LABELS:
        await update.message.reply_text(f"Неизвестное действие: {action}")
        return
    indices_str = ctx.args[1]
    try:
        indices = [
            int(x.strip()) for x in indices_str.split(",") if x.strip().isdigit()
        ]
        if not indices:
            raise ValueError("empty")
        invalid = [i for i in indices if i < 0 or i >= len(PREMIUM_STICKER_IDS)]
        if invalid:
            await update.message.reply_text(
                f"Ошибка: индексы {invalid} вне диапазона 0-{len(PREMIUM_STICKER_IDS)-1}"
            )
            return
    except Exception:
        await update.message.reply_text(
            "Ошибка: укажи индексы через запятую, например: 0,1,2,3"
        )
        return
    await db_setting(f"sticker_{action}", ",".join(str(i) for i in indices))
    label = ACTION_STICKER_LABELS[action]
    await update.message.reply_text(
        f"{_E_CHECK} Стикеры для <b>{label}</b> обновлены!\n"
        f"Индексы: <code>{indices_str}</code>",
        parse_mode=ParseMode.HTML,
    )


