async def cmd_setprice(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/setprice key value — изменить параметр экономики"""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return
    ALLOWED_KEYS = {
        "gacha_cost": "Стоимость гачи",
        "revive_cost": "Стоимость воскрешения",
        "heal_cost": "Стоимость лечения",
        "daily_base": "Базовый дневной бонус",
        "feed_reward": "Награда за кормление",
        "play_reward": "Награда за игру",
        "wash_reward": "Награда за купание",
    }
    if len(ctx.args) < 2:
        keys_list = "\n".join(f"• {k} — {v}" for k, v in ALLOWED_KEYS.items())
        await update.message.reply_text(
            f"{_E_GEAR} <b>Настройка экономики</b>\n\nИспользование: /setprice ключ значение\n\n<b>Доступные ключи:</b>\n{keys_list}\n\n"
            f"Пример: <code>/setprice gacha_cost 75</code>",
            parse_mode=ParseMode.HTML,
        )
        return
    key = ctx.args[0].lower()
    if key not in ALLOWED_KEYS:
        await update.message.reply_text(
            f"{_E_CROSS} Неизвестный ключ: {he(key)}\nДоступные: {he(', '.join(ALLOWED_KEYS.keys()))}", parse_mode=ParseMode.HTML
        )
        return
    try:
        value = int(ctx.args[1])
        if value < 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Значение должно быть положительным числом!")
        return
    old_val = await db_setting(key)
    await db_setting(key, str(value))
    await admin_log(user.id, f"setprice_{key}", details=f"{old_val}→{value}")
    await update.message.reply_text(
        f"{_E_CHECK} <b>{ALLOWED_KEYS[key]}</b> изменена\n"
        f"Было: <code>{old_val or 'не задано'}</code> → Стало: <code>{value}</code>",
        parse_mode=ParseMode.HTML,
    )


async def cmd_bowl_go(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/bowl_go_<game_id> — запустить броски в групповом боулинге"""
    user = update.effective_user
    text = (update.message.text or "").strip()
    # game_id = всё после /bowl_go_
    game_id_b = text.lstrip("/").replace("bowl_go_", "", 1).split("@")[0].strip()
    gdata_b = ctx.bot_data.get(f"bowl_group_{game_id_b}")
    if not gdata_b:
        await update.message.reply_text("Игра не найдена или уже завершена.")
        return
    if user.id != gdata_b["creator"]:
        await update.message.reply_text("Только создатель может запустить бросок")
        return
    if len(gdata_b["players"]) < 2:
        await update.message.reply_text("Нужно минимум 2 игрока!")
        return
    # Запрашиваем бросок у каждого игрока в порядке очереди
    gdata_b["phase"] = "throwing"
    gdata_b["order"] = list(gdata_b["players"].keys())
    gdata_b["current_idx"] = 0
    chat_id_b = gdata_b["chat_id"]
    first_uid = gdata_b["order"][0]
    first_f = await ctx.application.bot_data.get  # нет прямого доступа — просто спросим
    await ctx.bot.send_message(
        chat_id_b,
        f"🎳 <b>Боулинг начинается!</b> {len(gdata_b['players'])} игрока(ов)\n\n"
        f"Ставка: {gdata_b['stake']}{coin_emoji()} с каждого\n"
        f"Призовой фонд: {gdata_b['stake'] * len(gdata_b['players'])}{coin_emoji()}\n\n"
        f"Очерёдность броска:\n"
        + "\n".join(f"{i+1}. ID {uid}" for i, uid in enumerate(gdata_b["order"]))
        + f"\n\n➡️ Ход игрока ID {first_uid} — брось 🎳 в чат!",
        parse_mode=ParseMode.HTML,
    )


async def cmd_ref_approve(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/ref_approve_<uid> — одобрить заявку на вывод Stars (admin)"""
    if update.effective_user.id not in ADMIN_IDS:
        return
    text = update.message.text or ""
    try:
        target_uid = int(text.split("_")[-1])
    except Exception:
        await update.message.reply_text("Формат: /ref_approve_12345")
        return
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT id, amount FROM ref_withdraw_requests WHERE user_id=? AND status='pending' ORDER BY id DESC LIMIT 1",
            (target_uid,)
        ) as c:
            row = await c.fetchone()
        if not row:
            await update.message.reply_text("Ожидающей заявки не найдено")
            return
        req_id, amount = row
        await db.execute(
            "UPDATE ref_withdraw_requests SET status='approved', resolved_at=? WHERE id=?",
            (time.time(), req_id)
        )
        await db.commit()
    # Обнуляем баланс у пользователя
    target_f = await db_get(target_uid)
    if target_f:
        target_f["ref_stars_balance"] = 0
        await db_save(target_f)
    # Уведомляем пользователя
    try:
        await update.get_bot().send_message(
            target_uid,
            f"✅ <b>Заявка на вывод одобрена!</b>\n\n"
            f"Сумма: <b>{amount} ⭐</b>\n"
            f"Администратор свяжется с тобой для перевода Stars.",
            parse_mode=ParseMode.HTML,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass
    await update.message.reply_text(f"✅ Заявка #{req_id} одобрена. Пользователь уведомлён.")


