async def cmd_chatban(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/chatban @username [причина] — локальный бан пользователя в чате"""
    user = update.effective_user
    chat = update.effective_chat
    msg  = update.message

    if not is_group(update):
        await msg.reply_text("⛔ Команда работает только в группах.")
        return
    if not await _is_chat_admin(ctx.bot, chat.id, user.id) and user.id not in ADMIN_IDS:
        await msg.reply_text("⛔ Только администраторы чата могут банить.")
        return
    if not ctx.args:
        await msg.reply_text("Использование: /chatban @username [причина]")
        return

    mention = ctx.args[0].lstrip("@")
    reason  = " ".join(ctx.args[1:]) if len(ctx.args) > 1 else "нарушение правил"

    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM frogs WHERE username=?", (mention,)) as c:
            row = await c.fetchone()
    if not row:
        await msg.reply_text(f"{_E_CROSS} @{he(mention)} не найден в базе игроков", parse_mode=ParseMode.HTML)
        return
    target = dict(row)
    uid_target = target["user_id"]

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            """INSERT INTO chat_bans (chat_id, user_id, reason, banned_at, expires_at, banned_by)
               VALUES (?, ?, ?, ?, 0, ?)
               ON CONFLICT(chat_id, user_id) DO UPDATE SET reason=excluded.reason,
               banned_at=excluded.banned_at, expires_at=0, banned_by=excluded.banned_by""",
            (chat.id, uid_target, reason, time.time(), user.id),
        )
        await db.commit()

    await log_chat_activity(chat.id, uid_target, mention, f"{_E_BAN} бан: {reason}", 0)
    await msg.reply_text(
        f"{_E_BAN} @{mention} (ID {uid_target}) локально забанен в этом чате.\nПричина: {reason}",
        parse_mode=ParseMode.HTML,
    )
    try:
        await ctx.bot.send_message(
            uid_target,
            f"{_E_BAN} <b>Вы заблокированы в чате «{he(chat.title or '')}».</b>\nПричина: {reason}",
            parse_mode=ParseMode.HTML,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass


