async def is_chat_muted(chat_id: int, user_id: int) -> bool:
    """Проверяет, замьючен ли пользователь в данном чате."""
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT expires_at FROM chat_mutes WHERE chat_id=? AND user_id=?",
            (chat_id, user_id)
        ) as c:
            row = await c.fetchone()
    if not row:
        return False
    expires = row[0]
    if expires and 0 < expires < now:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("DELETE FROM chat_mutes WHERE chat_id=? AND user_id=?", (chat_id, user_id))
            await db.commit()
        return False
    return True


async def cmd_chatmute(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/chatmute @username [минуты] [причина] — замьютить игрока в чате бота"""
    user = update.effective_user
    chat = update.effective_chat
    msg  = update.message

    if not is_group(update):
        await msg.reply_text("⛔ Команда работает только в группах.")
        return
    if not await _is_chat_admin(ctx.bot, chat.id, user.id) and user.id not in ADMIN_IDS:
        await msg.reply_text("⛔ Только администраторы чата могут выдавать муты.")
        return
    if not ctx.args and not msg.reply_to_message:
        await msg.reply_text(
            "Использование: <code>/chatmute @username [минуты] [причина]</code>\n"
            "Пример: <code>/chatmute @vasya 60 спам</code>\n"
            "Или ответом на сообщение: <code>/chatmute 60 спам</code>\n"
            "Без минут — мут бессрочный.",
            parse_mode=ParseMode.HTML,
        )
        return

    # Определяем цель: reply или @username/ID
    uid_target = None
    mention_display = ""
    if msg.reply_to_message and msg.reply_to_message.from_user:
        ru = msg.reply_to_message.from_user
        uid_target = ru.id
        mention_display = f"@{ru.username}" if ru.username else he(ru.first_name)
        mute_minutes = 0
        reason_start = 0
        if ctx.args:
            try:
                mute_minutes = int(ctx.args[0])
                reason_start = 1
            except ValueError:
                pass
        reason = " ".join(ctx.args[reason_start:]) if len(ctx.args) > reason_start else "нарушение правил"
    else:
        mention = ctx.args[0].lstrip("@")
        mute_minutes = 0
        reason_start = 1
        if len(ctx.args) > 1:
            try:
                mute_minutes = int(ctx.args[1])
                reason_start = 2
            except ValueError:
                pass
        reason = " ".join(ctx.args[reason_start:]) if len(ctx.args) > reason_start else "нарушение правил"
        # Поиск по @username или числовому ID
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            if mention.isdigit():
                async with db.execute("SELECT * FROM frogs WHERE user_id=?", (int(mention),)) as c:
                    row = await c.fetchone()
            else:
                async with db.execute("SELECT * FROM frogs WHERE username=?", (mention,)) as c:
                    row = await c.fetchone()
        if not row:
            await msg.reply_text(f"{_E_CROSS} @{he(mention)} не найден в базе игроков", parse_mode=ParseMode.HTML)
            return
        target = dict(row)
        uid_target = target["user_id"]
        mention_display = f"@{target['username']}" if target.get("username") else f"ID:{uid_target}"

    expires_at = (time.time() + mute_minutes * 60) if mute_minutes > 0 else 0
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            """INSERT INTO chat_mutes(chat_id, user_id, reason, muted_at, expires_at, muted_by)
               VALUES(?,?,?,?,?,?)
               ON CONFLICT(chat_id, user_id) DO UPDATE SET
               reason=excluded.reason, muted_at=excluded.muted_at,
               expires_at=excluded.expires_at, muted_by=excluded.muted_by""",
            (chat.id, uid_target, reason, time.time(), expires_at, user.id),
        )
        await db.commit()

    duration_str = f"на {mute_minutes} мин." if mute_minutes else "бессрочно"
    await log_chat_activity(chat.id, uid_target, mention_display, f"🔇 мут {duration_str}: {reason}", 0)
    await msg.reply_text(
        f"🔇 {mention_display} (ID {uid_target}) замьючен в боте {duration_str}.\nПричина: {reason}",
        parse_mode=ParseMode.HTML,
    )
    try:
        await ctx.bot.send_message(
            uid_target,
            f"🔇 <b>Вам выдан мут в чате «{he(chat.title or '')}» {duration_str}.</b>\nПричина: {reason}\n"
            f"<i>В период мута вы не можете взаимодействовать с ботом в этом чате.</i>",
            parse_mode=ParseMode.HTML,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass


