async def cmd_chatwarn(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/chatwarn @username [причина] — выдать предупреждение в чате (3 варна = автобан)"""
    user = update.effective_user
    chat = update.effective_chat
    msg  = update.message

    if not is_group(update):
        await msg.reply_text("⛔ Команда работает только в группах.")
        return
    if not await _is_chat_admin(ctx.bot, chat.id, user.id) and user.id not in ADMIN_IDS:
        await msg.reply_text("⛔ Только администраторы чата могут выдавать предупреждения.")
        return

    # Поддержка reply: если нет аргументов, берём reply-пользователя
    target_user = None
    reason = ""
    if msg.reply_to_message and msg.reply_to_message.from_user:
        target_user = msg.reply_to_message.from_user
        reason = " ".join(ctx.args) if ctx.args else "нарушение правил"
    elif ctx.args:
        mention = ctx.args[0].lstrip("@")
        reason = " ".join(ctx.args[1:]) if len(ctx.args) > 1 else "нарушение правил"
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            if mention.isdigit():
                async with db.execute("SELECT user_id, first_name FROM frogs WHERE user_id=?", (int(mention),)) as c:
                    row = await c.fetchone()
            else:
                async with db.execute("SELECT user_id, first_name FROM frogs WHERE username=?", (mention,)) as c:
                    row = await c.fetchone()
        if not row:
            await msg.reply_text(f"{_E_CROSS} @{he(mention)} не найден в базе игроков", parse_mode=ParseMode.HTML)
            return
        target_user = type("U", (), {"id": row["user_id"], "first_name": row["first_name"], "mention_html": lambda s=None: f"<b>{he(row['first_name'])}</b>"})()
    else:
        await msg.reply_text("Использование: /chatwarn @username [причина] или ответом на сообщение")
        return

    uid_target = target_user.id
    if uid_target == user.id:
        await msg.reply_text("⛔ Нельзя предупредить самого себя.")
        return

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT INTO chat_warnings(chat_id, user_id, reason, warned_at, warned_by) VALUES(?,?,?,?,?)",
            (chat.id, uid_target, reason, time.time(), user.id),
        )
        await db.commit()
        async with db.execute(
            "SELECT COUNT(*) FROM chat_warnings WHERE chat_id=? AND user_id=?",
            (chat.id, uid_target)
        ) as c:
            warn_count = (await c.fetchone())[0]

    name = he(target_user.first_name)
    WARN_MUTE  = 3  # варна → мут 3 часа
    WARN_BAN   = 6  # варнов → бан
    uname_log = getattr(target_user, "username", None) or str(uid_target)

    if warn_count >= WARN_BAN:
        # Автобан после 6 варнов
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                """INSERT INTO chat_bans(chat_id, user_id, reason, banned_at, expires_at, banned_by)
                   VALUES(?,?,?,?,0,?)
                   ON CONFLICT(chat_id, user_id) DO UPDATE SET reason=excluded.reason,
                   banned_at=excluded.banned_at, expires_at=0, banned_by=excluded.banned_by""",
                (chat.id, uid_target, f"{warn_count} предупреждений ({reason})", time.time(), user.id),
            )
            await db.commit()
        await log_chat_activity(chat.id, uid_target, uname_log, f"⚠️ варн {warn_count}/{WARN_BAN} → {_E_BAN} автобан: {reason}", 0)
        await msg.reply_text(
            f"⚠️ <b>{name}</b> получил предупреждение {warn_count}/{WARN_BAN}.\n"
            f"{_E_BAN} <b>Автоматический бан</b> — превышен лимит предупреждений!",
            parse_mode=ParseMode.HTML,
        )
    elif warn_count >= WARN_MUTE:
        # Автомут 3 часа после 3 варнов
        mute_duration = 3 * 3600
        mute_expires = time.time() + mute_duration
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                """INSERT INTO chat_mutes(chat_id, user_id, reason, muted_at, expires_at, muted_by)
                   VALUES(?,?,?,?,?,?)
                   ON CONFLICT(chat_id, user_id) DO UPDATE SET
                   reason=excluded.reason, muted_at=excluded.muted_at,
                   expires_at=excluded.expires_at, muted_by=excluded.muted_by""",
                (chat.id, uid_target, f"3 предупреждения ({reason})", time.time(), mute_expires, user.id),
            )
            await db.commit()
        await log_chat_activity(chat.id, uid_target, uname_log, f"⚠️ варн {warn_count}/{WARN_BAN} → 🔇 автомут 3ч: {reason}", 0)
        await msg.reply_text(
            f"⚠️ <b>{name}</b> получил предупреждение <b>{warn_count}/{WARN_BAN}</b>.\n"
            f"🔇 <b>Автоматический мут на 3 часа</b> — 3 предупреждения накоплены!\n"
            f"Причина: {he(reason)}",
            parse_mode=ParseMode.HTML,
        )
    else:
        await log_chat_activity(chat.id, uid_target, uname_log, f"⚠️ варн {warn_count}/{WARN_BAN}: {reason}", 0)
        await msg.reply_text(
            f"⚠️ <b>{name}</b> получил предупреждение <b>{warn_count}/{WARN_BAN}</b>.\n"
            f"Причина: {he(reason)}\n"
            f"<i>При {WARN_MUTE} варнах — мут 3ч, при {WARN_BAN} — бан.</i>",
            parse_mode=ParseMode.HTML,
        )


async def cmd_chatwarnlist(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/warnlist [@username] — список предупреждений пользователя в чате"""
    user = update.effective_user
    chat = update.effective_chat
    msg  = update.message

    if not is_group(update):
        await msg.reply_text("⛔ Команда работает только в группах.")
        return
    if not await _is_chat_admin(ctx.bot, chat.id, user.id) and user.id not in ADMIN_IDS:
        await msg.reply_text("⛔ Только администраторы чата.")
        return

    if msg.reply_to_message and msg.reply_to_message.from_user:
        uid_target = msg.reply_to_message.from_user.id
        tname = he(msg.reply_to_message.from_user.first_name)
    elif ctx.args:
        mention = ctx.args[0].lstrip("@")
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            async with db.execute("SELECT user_id, first_name FROM frogs WHERE username=?", (mention,)) as c:
                row = await c.fetchone()
        if not row:
            await msg.reply_text(f"{_E_CROSS} @{he(mention)} не найден", parse_mode=ParseMode.HTML)
            return
        uid_target = row["user_id"]
        tname = he(row["first_name"])
    else:
        await msg.reply_text("Использование: /warnlist @username или ответом на сообщение")
        return

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT reason, warned_at FROM chat_warnings WHERE chat_id=? AND user_id=? ORDER BY warned_at DESC",
            (chat.id, uid_target)
        ) as c:
            warns = await c.fetchall()

    if not warns:
        await msg.reply_text(f"{_E_CHECK} У <b>{tname}</b> нет предупреждений в этом чате.", parse_mode=ParseMode.HTML)
        return

    lines = [f"⚠️ <b>Предупреждения {tname}</b> ({len(warns)}/3):\n"]
    for i, (reason, ts) in enumerate(warns, 1):
        dt = datetime.fromtimestamp(ts, timezone.utc).strftime("%d.%m %H:%M")
        lines.append(f"{i}. {he(reason or '—')} <i>({dt})</i>")
    await msg.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


