async def cmd_chatlogs(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/chatlogs [N] — последние N (по умолч. 20) действий в логе чата"""
    user = update.effective_user
    chat = update.effective_chat
    msg  = update.message

    if not is_group(update):
        await msg.reply_text("⛔ Команда работает только в группах.")
        return
    if not await _is_chat_admin(ctx.bot, chat.id, user.id) and user.id not in ADMIN_IDS:
        await msg.reply_text("⛔ Только администраторы чата.")
        return

    limit = 20
    if ctx.args:
        try:
            limit = max(1, min(50, int(ctx.args[0])))
        except ValueError:
            pass

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT username, action, amount, ts FROM chat_activity_log "
            "WHERE chat_id=? ORDER BY ts DESC LIMIT ?",
            (chat.id, limit)
        ) as c:
            rows = await c.fetchall()

    if not rows:
        await msg.reply_text("📋 Лог пуст — действий ещё не было.")
        return

    lines = [f"📋 <b>Последние {len(rows)} действий в чате</b>\n"]
    for username, action, amount, ts in rows:
        dt = datetime.fromtimestamp(ts, timezone.utc).strftime("%d.%m %H:%M")
        amt_str = f" +{amount}{_E_COIN}" if amount else ""
        lines.append(f"<i>{dt}</i> · {he(username or '?')} — {he(action)}{amt_str}")
    await msg.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


async def cmd_chatstats(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/chatstats — статистика игроков текущего чата"""
    user = update.effective_user
    chat = update.effective_chat
    msg  = update.message

    if is_group(update):
        cid = chat.id
        chat_title = chat.title or str(cid)
    else:
        f0 = await db_get(user.id)
        cid = f0.get("source_chat_id", 0) if f0 else 0
        if not cid:
            await msg.reply_text("⛔ Команда предназначена для использования в чате.")
            return
        pc = await partner_chat_get(cid)
        chat_title = pc["chat_title"] if pc else str(cid)

    now_st   = time.time()
    day_ago  = now_st - 86400
    week_ago = now_st - 7 * 86400
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT COUNT(*) FROM frogs WHERE source_chat_id=? AND banned=0", (cid,)) as c:
            total_m = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT COUNT(*) FROM frogs WHERE source_chat_id=? AND alive=1 AND (last_feed>? OR last_play>?)",
            (cid, day_ago, day_ago)
        ) as c:
            act24 = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT COUNT(*) FROM frogs WHERE source_chat_id=? AND alive=1 AND (last_feed>? OR last_play>?)",
            (cid, week_ago, week_ago)
        ) as c:
            act7d = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT first_name, frog_name, level, coins FROM frogs WHERE source_chat_id=? AND alive=1 "
            "ORDER BY level DESC, coins DESC LIMIT 5", (cid,)
        ) as c:
            top5 = await c.fetchall()
        async with db.execute("SELECT SUM(coins_spent) FROM frogs WHERE source_chat_id=?", (cid,)) as c:
            total_spent = (await c.fetchone())[0] or 0

    top_txt = "\n".join(
        f"  {i+1}. {he(r[1] or r[0])} — ур.{r[2]} · {r[3]}{_E_COIN}"
        for i, r in enumerate(top5)
    ) or "  —"
    reply = await msg.reply_text(
        f"{_E_CHART} <b>Статистика — {he(chat_title)}</b>\n\n"
        f"{_E_USERS} Всего игроков: <b>{total_m}</b>\n"
        f"{_E_DOT_GREEN} Активных 24ч: <b>{act24}</b> · 7д: <b>{act7d}</b>\n"
        f"💸 Потрачено всего: <b>{total_spent:,}{_E_COIN}</b>\n\n"
        f"<b>{_E_TROPHY} Топ-5:</b>\n{top_txt}",
        parse_mode=ParseMode.HTML,
    )
    if reply and is_group(update):
        asyncio.create_task(schedule_delete(update.get_bot(), reply.chat.id, reply.message_id))


