async def cmd_casino(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/casino — открыть меню казино"""
    # Mode guard
    if is_group(update):
        mode = await get_chat_mode(update.effective_chat.id)
        if mode == "readonly":
            try: await update.message.delete()
            except Exception as _e:
                logger.exception("подавлено исключение: %s", _e)
            return
        if mode == "vanilla":
            await vanilla_redirect(update, ctx, "casino")
            return
    uid = update.effective_user.id
    f = await db_get(uid)
    if not f:
        await update.message.reply_text("❌ Сначала создай лягушку командой /start")
        return
    if f.get("banned"):
        await update.message.reply_text("🚫 Ты заблокирован.")
        return
    # Проверяем глобальное отключение казино
    if await db_setting("casino_disabled") == "1":
        await update.message.reply_text(
            f"{_E_CASINO} <b>Казино временно недоступно.</b>\n"
            "<i>Чиним. Загляни через несколько минут.</i>",
            parse_mode=ParseMode.HTML,
        )
        return
    jp = await jackpot_get()
    kb = InlineKeyboardMarkup(
        [
            [
                btn(
                    f"{v['emoji']} {v['name']}",
                    callback_data=f"casino_pick_{k}",
                )
            ]
            for k, v in CASINO.items()
        ]
        + [
            [btn("🎯 Режим желания", callback_data="casino_wish_menu")],
            [
                btn(
                    "🎰 Джекпот", callback_data="menu_jackpot"
                )
            ],
        ]
    )
    await update.message.reply_text(
        ui_card(
            ui_title(f"{_E_CASINO}", "Казино"),
            ui_line(ui_money(f["coins"]), f"джекпот {jp:,}{coin_emoji()}"),
        ),
        parse_mode=ParseMode.HTML,
        reply_markup=kb,
    )


