async def cmd_reset_lottery(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/reset_lottery — очистить все билеты за сегодня (admin)"""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return
    today = lottery_today()
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(*) FROM lottery_tickets WHERE draw_date=?", (today,)
        ) as c:
            cnt = (await c.fetchone())[0] or 0
        await db.execute("DELETE FROM lottery_tickets WHERE draw_date=?", (today,))
        await db.commit()
    await admin_log(
        user.id, "reset_lottery", details=f"deleted {cnt} tickets for {today}"
    )
    await update.message.reply_text(
        f"✅ Лотерея сброшена. Удалено {cnt} билетов за {today}."
    )


