async def cmd_donate(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/donate [сумма] — пополнить банк чата своими КваКоинами"""
    if not await group_cmd_guard(update, "donate", ctx):
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return

    # Нет аргумента — показываем текущий банк и подсказку
    if not ctx.args:
        gid = update.effective_chat.id
        s = await get_chat_settings(gid)
        fund = s.get("local_fund", 0)
        threshold = s.get("auto_giveaway_threshold", 0)
        threshold_str = f"\n🎯 До авто-розыгрыша: <b>{threshold:,}{_E_COIN}</b>" if threshold > 0 else ""
        msg = await update.message.reply_text(
            f"{_E_MONEYBAG} <b>Банк чата</b>\n\n"
            f"Текущий фонд: <b>{fund:,}{coin_emoji()}</b>{threshold_str}\n\n"
            f"Используй <code>/donate &lt;сумма&gt;</code>, чтобы пополнить банк!\n"
            f"У тебя сейчас: <b>{f['coins']:,}{coin_emoji()}</b>",
            parse_mode=ParseMode.HTML,
        )
        if msg and is_group(update):
            asyncio.create_task(schedule_delete(update.get_bot(), msg.chat.id, msg.message_id))
        return

    try:
        amount = int(ctx.args[0])
        if amount <= 0:
            raise ValueError
    except ValueError:
        msg = await update.message.reply_text(
            f"{_E_CROSS} Укажи положительное число!\nПример: <code>/donate 100</code>",
            parse_mode=ParseMode.HTML,
        )
        if msg and is_group(update):
            asyncio.create_task(schedule_delete(update.get_bot(), msg.chat.id, msg.message_id))
        return

    if f["coins"] < amount:
        msg = await update.message.reply_text(
            f"💸 Недостаточно монет!\nНужно: <b>{amount}{coin_emoji()}</b> · У тебя: <b>{f['coins']}{coin_emoji()}</b>",
            parse_mode=ParseMode.HTML,
        )
        if msg and is_group(update):
            asyncio.create_task(schedule_delete(update.get_bot(), msg.chat.id, msg.message_id))
        return

    # Максимум 10 000 монет за раз
    MAX_DONATE = 10_000
    if amount > MAX_DONATE:
        msg = await update.message.reply_text(
            f"⚠️ Максимум <b>{MAX_DONATE:,}{coin_emoji()}</b> за один раз.",
            parse_mode=ParseMode.HTML,
        )
        if msg and is_group(update):
            asyncio.create_task(schedule_delete(update.get_bot(), msg.chat.id, msg.message_id))
        return

    # Списываем монеты и пополняем банк
    f["coins"] -= amount
    f["coins_spent"] = f.get("coins_spent", 0) + amount
    await db_save(f)

    gid = update.effective_chat.id
    s = await get_chat_settings(gid)
    new_fund = s.get("local_fund", 0) + amount
    await save_chat_settings(gid, local_fund=new_fund)

    threshold = s.get("auto_giveaway_threshold", 0)
    threshold_str = (
        f"\n🎯 До авто-розыгрыша: <b>{max(0, threshold - new_fund):,}{_E_COIN}</b>"
        if threshold > 0 else ""
    )

    donor_name = he(f.get("frog_name") or user.first_name or "Игрок")
    msg = await update.message.reply_text(
        f"💖 <b>{donor_name}</b> пожертвовал <b>{amount:,}{coin_emoji()}</b> в банк чата!\n"
        f"{_E_MONEYBAG} Банк чата: <b>{new_fund:,}{coin_emoji()}</b>{threshold_str}",
        parse_mode=ParseMode.HTML,
    )
    if msg and is_group(update):
        asyncio.create_task(schedule_delete(update.get_bot(), msg.chat.id, msg.message_id, delay=60))

    # Проверяем авто-розыгрыш
    if threshold > 0 and new_fund >= threshold and ctx:
        asyncio.create_task(_run_chat_auto_giveaway(gid, new_fund, ctx))


async def cmd_stats(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not await group_cmd_guard(update, "stats", ctx):
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return
    f = decay(f)
    coll = await db_coll(user.id)
    days = int((time.time() - f["born_at"]) / 86400)
    use_st = bool(f.get("use_static", 0))
    win_rate = 0
    if f.get("total_duels", 0) > 0:
        win_rate = int(f.get("total_duel_wins", 0) / f["total_duels"] * 100)
    casino_wr = 0
    if f.get("total_casino", 0) > 0:
        casino_wr = int(f.get("total_casino_wins", 0) / f["total_casino"] * 100)
    s = SKINS.get(f["skin"], SKINS["Brownie"])
    await update.message.reply_text(
        ui_card(
            f"{_E_CHART} <b>{fname(f)}</b>{SEP}{R_DOT[s['rarity']]} {pemoji(f['skin'])}",
            # Каждый показатель был отдельной строкой «подпись: значение» —
            # 17 строк подряд читались как таблица без границ. Группируем по
            # смыслу. Не больше трёх значений в строке: при крупных числах
            # четвёртое уводит строку за 21W и её рвёт переносом на телефоне
            # (проверяется tools/msgwidth.py).
            ui_line(f"{_E_LEVEL} ур. {f['level']}",
                    f"{_E_FIRE}{f['streak']} дн",
                    f"📅 {days} дн в игре"),
            ui_line(ui_money(f["coins"]),
                    f"потрачено {f.get('coins_spent', 0)}{coin_emoji()}"),
            ui_line(f"{_E_STARS}{f.get('stars_spent', 0)}",
                    f"🗂 {len(coll)}/50",
                    display_skin(f["skin"], use_st)),
            # Счётчики ухода — один блок из двух строк, а не два блока:
            # между строками одного смысла пустая строка не нужна.
            ui_line(f"{_E_FOOD} {f['total_feeds']}",
                    f"{_E_GAMES} {f['total_plays']}",
                    f"{_E_SOAP} {f['total_washes']}")
            + "\n"
            + ui_line(f"😴 {f['total_sleeps']}",
                      f"{_E_CASINO} {f['total_gacha']}",
                      f"🦟 {f.get('total_mosquitoes', 0)}"),
            # Процент в скобках, а не через SEP: иначе разделитель означает
            # и «следующая колонка», и «уточнение к числу».
            ui_line(f"{_E_SWORDS} {f.get('total_duel_wins', 0)}/{f.get('total_duels', 0)} ({win_rate}%)",
                    f"🃏 {f.get('total_casino_wins', 0)}/{f.get('total_casino', 0)} ({casino_wr}%)"),
        ),
        parse_mode=ParseMode.HTML,
        link_preview_options=LinkPreviewOptions(),
    )


