# ══════════════════════════════════════════════════════════════════════════════
# 🎁 НОВЫЕ КОМАНДЫ: интеграция See.tg API
# ══════════════════════════════════════════════════════════════════════════════

async def thinking(update) -> None:
    """
    Показать «печатает…» перед долгим ответом.

    Запросы в See.tg идут через сеть и занимают секунды. Без этого бот выглядит
    зависшим: игрок отправил команду и не понимает, дошла ли она.
    """
    try:
        await update.effective_chat.send_chat_action(ChatAction.TYPING)
    except (BadRequest, Forbidden, TimedOut):
        pass


async def cmd_portfolio(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /portfolio [@username | telegram_id] — стоимость портфеля гифтов через See.tg API.
    Без аргументов показывает свой портфель.
    """
    if not await group_cmd_guard(update, "portfolio", ctx):
        return
    await thinking(update)
    user = update.effective_user

    target_tg_id: int | None = None
    target_label = "Твой портфель"

    if ctx.args:
        arg = ctx.args[0].lstrip("@")
        if arg.lstrip("-").isdigit():
            target_tg_id = int(arg)
            target_label = f"Портфель <code>{arg}</code>"
        else:
            owner_data = await seetg_request("/api/owner", {"username": arg})
            if owner_data and owner_data.get("telegram_id"):
                target_tg_id = int(owner_data["telegram_id"])
                name = owner_data.get("name") or arg
                target_label = f"Портфель <b>{_html.escape(name)}</b>"
            else:
                await update.message.reply_text(
                    f"{_E_CROSS} Пользователь <code>{_html.escape(arg)}</code> не найден в See.tg.",
                    parse_mode=ParseMode.HTML,
                )
                return
    else:
        target_tg_id = user.id
        f = await db_get(user.id)
        if f:
            target_label = f"Портфель <b>{_html.escape(fname(f))}</b>"

    msg = await update.message.reply_text(
        f"{_E_SEARCH} <i>Загружаю данные See.tg...</i>", parse_mode=ParseMode.HTML
    )

    portfolio = await seetg_get_portfolio(target_tg_id)
    gifts_list = await seetg_get_gifts_by_owner(target_tg_id, limit=50)

    if not portfolio:
        try:
            await msg.edit_text(
                "😕 Данные о портфеле не найдены.\n<i>Пользователь не зарегистрирован в See.tg или у него нет гифтов.</i>",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    lines = [f"💎 {target_label}\n"]
    markets_emoji = {"telegram": "✈️", "portals": "🌀", "tonnel": "🚇", "getgems": "💎"}
    has_any = False
    for market, vals in portfolio.items():
        if market in ("average", "total") or not isinstance(vals, dict):
            continue
        ton = vals.get("ton", 0)
        usd = vals.get("usd", 0)
        if ton and float(ton) > 0:
            em = markets_emoji.get(market, "🔹")
            lines.append(
                f"{em} <b>{market.capitalize()}</b>: {float(ton):.2f} TON (~${float(usd):.0f})"
            )
            has_any = True

    total = portfolio.get("total") or portfolio.get("average") or {}
    if isinstance(total, dict) and total.get("ton"):
        tot_ton = float(total["ton"])
        tot_usd = float(total.get("usd", 0))
        lines.append(f"\n{_E_MONEYBAG} <b>Итого (лучший маркет):</b> {tot_ton:.2f} TON (~${tot_usd:.0f})")

    if not has_any:
        lines.append("📭 <i>Гифты на маркетах не найдены или цена не определена.</i>")

    if gifts_list:
        lines.append(f"\n{_E_GIFT} <b>Гифты ({len(gifts_list)}):</b>")
        r_icons = {"Common": _E_DOT_WHITE, "Rare": _E_DOT_BLUE, "Epic": _E_DOT_PURPLE,
                   "Legendary": _E_DOT_YELLOW, "Mythical": _E_DOT_RED}
        for g in gifts_list[:10]:
            gtitle = g.get("title") or g.get("slug") or "?"
            gnum = g.get("num") or "?"
            rarity = (g.get("model") or {}).get("rarity") or ""
            ri = r_icons.get(rarity, "⚫")
            lines.append(f"  {ri} {_html.escape(str(gtitle))} #{gnum}")
        if len(gifts_list) > 10:
            lines.append(f"  <i>...и ещё {len(gifts_list) - 10}</i>")

    try:
        await msg.edit_text("\n".join(lines), parse_mode=ParseMode.HTML)
    except (BadRequest, Forbidden, TimedOut):
        pass


async def cmd_giftcheck(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /giftcheck <https://t.me/nft/SLUG-NUM> или /giftcheck SLUG NUM
    Информация о гифте + история передач.
    """
    if not await group_cmd_guard(update, "giftcheck", ctx):
        return
    await thinking(update)

    slug, num_str = None, None
    if ctx.args:
        if len(ctx.args) == 1:
            raw = ctx.args[0].strip()
            m = re.match(r"https?://t\.me/nft/([A-Za-z]+)-(\d+)", raw)
            if m:
                slug, num_str = m.group(1), m.group(2)
        elif len(ctx.args) == 2:
            slug, num_str = ctx.args[0].strip(), ctx.args[1].strip()

    if not slug or not num_str or not num_str.isdigit():
        await update.message.reply_text(
            "<b>Проверка гифта</b>\n\n"
            "Использование:\n"
            "  <code>/giftcheck https://t.me/nft/KissedFrog-123</code>\n"
            "  <code>/giftcheck KissedFrog 123</code>",
            parse_mode=ParseMode.HTML,
        )
        return

    num = int(num_str)
    nft_url = f"https://t.me/nft/{slug}-{num}"

    msg = await update.message.reply_text(
        "<i>Загружаю...</i>", parse_mode=ParseMode.HTML
    )

    # Запрашиваем данные гифта + историю параллельно
    gift, _ = await asyncio.gather(
        seetg_get_gift(slug, num),
        asyncio.sleep(0),  # placeholder для gather
    )

    if not gift:
        # Фолбэк на xgift
        gift_xg = await xgift_gift_info(f"{slug.lower()}-{num}")
        if not gift_xg:
            try:
                await msg.edit_text(
                    f"Гифт <b>{_html.escape(slug)} #{num}</b> не найден.",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
            return
        owner_xg = gift_xg.get("currentOwner") or gift_xg.get("owner") or {}
        owner_name_xg = owner_xg.get("name") or owner_xg.get("username") or "неизвестно"
        owner_tg_xg = owner_xg.get("telegramId") or owner_xg.get("telegram_id")
        floor_xg = gift_xg.get("floorPrice")
        floor_str_xg = f"{float(floor_xg):.2f} TON" if floor_xg else "не выставлен"
        try:
            await msg.edit_text(
                f'<a href="{nft_url}"><b>{_html.escape(slug)} #{num}</b></a>\n\n'
                f"Модель: <b>{_html.escape(str(gift_xg.get('model') or '?'))}</b>\n"
                f"Бэкдроп: {_html.escape(str(gift_xg.get('backdrop') or '?'))}\n"
                f"Паттерн: {_html.escape(str(gift_xg.get('pattern') or '?'))}\n"
                f"Владелец: <b>{_html.escape(str(owner_name_xg))}</b>"
                + (f" [tg:{owner_tg_xg}]" if owner_tg_xg else "") + "\n"
                f"Цена: {floor_str_xg}",
                parse_mode=ParseMode.HTML,
                link_preview_options=LinkPreviewOptions(),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Данные гифта ──────────────────────────────────────────────────────────
    title      = gift.get("title") or slug
    model_name = gift.get("model_name") or "?"
    pattern    = gift.get("pattern_name") or "?"
    backdrop   = gift.get("backdrop_name") or "?"
    issued     = gift.get("availability_issued") or "?"
    total      = gift.get("availability_total") or "?"
    burned     = gift.get("burned", False)
    crafted    = gift.get("crafted", False)
    gift_id    = gift.get("id") or gift.get("gift_id") or ""

    def rare_pct(permille) -> str:
        if permille is None:
            return ""
        return f" ({permille / 10:.1f}%)"

    model_rare = gift.get("model_rarity_permille")
    pat_rare   = gift.get("pattern_rarity_permille")
    back_rare  = gift.get("backdrop_rarity_permille")

    # Цена
    resale_ton   = _seetg_nanoton_to_ton(gift.get("resale_ton_amount"))
    resale_stars = gift.get("resale_stars_amount")
    onsale_info  = gift.get("onsale") or {}
    onsale_market = onsale_info.get("market") or ""
    onsale_ton   = _seetg_nanoton_to_ton(onsale_info.get("amount")) if onsale_info.get("currency") == "ton" else None

    price_parts = []
    if resale_ton:
        price_parts.append(f"{resale_ton:.2f} TON")
    if resale_stars:
        try:
            price_parts.append(f"{int(resale_stars):,} Stars")
        except (TypeError, ValueError):
            price_parts.append(f"{resale_stars} Stars")
    price_str = " / ".join(price_parts) if price_parts else "не выставлен"

    if onsale_market:
        market_labels = {"telegram": "Telegram", "getgems": "GetGems", "portals": "Portals", "tonnel": "Tonnel"}
        mlabel = market_labels.get(onsale_market, onsale_market)
        if onsale_ton:
            price_str += f" ({mlabel}: {onsale_ton:.2f} TON)"
        else:
            price_str += f" (на {mlabel})"

    # Владелец
    owner       = gift.get("current_owner") or {}
    owner_name  = owner.get("name") or owner.get("username") or ""
    owner_uname = owner.get("username") or ""
    owner_tg    = owner.get("telegram_id")
    if owner_uname:
        owner_str = f'<a href="https://t.me/{owner_uname}">{_html.escape(owner_name or owner_uname)}</a>'
    elif owner_tg:
        owner_str = f'<a href="https://t.me/@id{owner_tg}">{_html.escape(owner_name or str(owner_tg))}</a>'
    elif owner_name:
        owner_str = _html.escape(owner_name)
    else:
        owner_str = "скрыт"

    lines = [
        f'<a href="{nft_url}"><b>{_html.escape(title)} #{num}</b></a>\n',
        f"Модель: <b>{_html.escape(model_name)}</b>{rare_pct(model_rare)}",
        f"Бэкдроп: {_html.escape(backdrop)}{rare_pct(back_rare)}",
        f"Паттерн: {_html.escape(pattern)}{rare_pct(pat_rare)}",
        f"Выпущено: {issued} / {total}",
        f"Владелец: {owner_str}",
        f"Цена: {price_str}",
    ]
    if burned:
        lines.append("Сожжён")
    if crafted:
        lines.append("Скрафчен")

    # ── История передач ───────────────────────────────────────────────────────
    if gift_id:
        history_raw = await seetg_request(
            "/api/history",
            {"gift_id": str(gift_id), "limit": "7", "order": "desc"},
        )
        history_items: list = []
        if isinstance(history_raw, list):
            history_items = history_raw
        elif isinstance(history_raw, dict):
            history_items = history_raw.get("results") or history_raw.get("items") or []

        if history_items:
            lines.append("\n<b>История:</b>")
            action_labels = {"transfer": "→", "hide": "скрыт", "unhide": "открыт"}
            for h in history_items[:7]:
                action = h.get("action", "transfer")
                a_label = action_labels.get(action, action)
                new_ow = h.get("owner") or {}
                new_uname = new_ow.get("username") or ""
                new_name  = new_ow.get("name") or new_uname or "?"
                if new_uname:
                    ow_link = f'<a href="https://t.me/{new_uname}">@{_html.escape(new_uname)}</a>'
                else:
                    new_tg = new_ow.get("telegram_id")
                    if new_tg:
                        ow_link = f'<a href="https://t.me/@id{new_tg}">{_html.escape(str(new_name))}</a>'
                    else:
                        ow_link = _html.escape(str(new_name))
                seen = h.get("seen_at") or ""
                if seen:
                    try:
                        dt = datetime.fromisoformat(seen.replace("Z", "+00:00"))
                        seen = dt.strftime("%d.%m.%y")
                    except Exception:
                        seen = seen[:10]
                lines.append(f"  {a_label} {ow_link} <i>{seen}</i>")

    try:
        await msg.edit_text(
            "\n".join(lines),
            parse_mode=ParseMode.HTML,
            link_preview_options=LinkPreviewOptions(),
        )
    except (BadRequest, Forbidden, TimedOut):
        pass

async def cmd_admin_nft_recheck(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /admin_nft_recheck — перепроверить все верифицированные НФТ через see.tg.
    Если профиль скрыт, НФТ помечается и Admin получает кнопки «Оставить» / «Забрать».
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return
    msg = await update.message.reply_text("🔄 Начинаю перепроверку всех НФТ... Это может занять минуту.")

    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT id, user_id, nft_number, nft_url, model_name, owner_name "
            "FROM nft_frogs WHERE verified=1"
        ) as c:
            nft_rows = [dict(r) for r in await c.fetchall()]

    hidden_found = []
    ok_count = 0
    error_count = 0

    for row in nft_rows:
        nft_num = row["nft_number"]
        nft_url = row["nft_url"] or f"https://t.me/nft/KissedFrog-{nft_num}"
        try:
            # Запрашиваем данные через see.tg (используем _by_url чтобы правильно разобрать slug+num)
            data = await seetg_get_gift_by_url(nft_url)
            if data is None:
                error_count += 1
                continue
            # По API: current_owner.owner_type == "hidden" означает скрытый профиль
            owner_info = data.get("current_owner") or data.get("owner") or {}
            owner_type = owner_info.get("owner_type", "")
            is_hidden = (owner_type == "hidden") or (
                not owner_info.get("username", "").strip() and
                not owner_info.get("telegram_id")
            )
            async with aiosqlite.connect(DB_PATH) as db:
                await db.execute(
                    "UPDATE nft_frogs SET profile_hidden=? WHERE id=?",
                    (1 if is_hidden else 0, row["id"])
                )
                await db.commit()
            if is_hidden:
                hidden_found.append(row)
            else:
                ok_count += 1
            await asyncio.sleep(0.5)  # не флудим API
        except Exception as e:
            logger.warning("nft_recheck: error checking %s: %s", nft_num, e)
            error_count += 1

    # Отправляем итог
    summary = (
        f"✅ Перепроверка завершена\n\n"
        f"Всего НФТ: {len(nft_rows)}\n"
        f"✅ Видимые: {ok_count}\n"
        f"🔒 Скрытый профиль: {len(hidden_found)}\n"
        f"⚠️ Ошибки API: {error_count}"
    )
    try:
        await msg.edit_text(summary)
    except Exception:
        await update.message.reply_text(summary)

    # Для каждого НФТ со скрытым профилем — отдельное сообщение с кнопками
    # Отправляем с задержкой чтобы не получить FloodWait от Telegram
    for i, row in enumerate(hidden_found):
        owner_f = await db_get(row["user_id"])
        owner_name  = ""
        owner_uname = ""
        if owner_f:
            owner_name  = owner_f.get("frog_name") or owner_f.get("first_name") or f"ID:{row['user_id']}"
            owner_uname = f"@{owner_f['username']}" if owner_f.get("username") else f"ID:{row['user_id']}"
        nft_disp  = row.get("model_name") or f"#{row['nft_number']}"
        nft_url   = row.get("nft_url") or f"https://t.me/nft/KissedFrog-{row['nft_number']}"
        seetg_url = f"https://see.tg/gifts/KissedFrog-{row['nft_number']}"

        kb = InlineKeyboardMarkup([
            [
                btn(
                    "\u2705 \u041e\u0441\u0442\u0430\u0432\u0438\u0442\u044c",
                    callback_data=f"nft_recheck_keep_{row['id']}"
                ),
                btn(
                    "\u274c \u0417\u0430\u0431\u0440\u0430\u0442\u044c \u0441\u043a\u0438\u043d",
                    callback_data=f"nft_recheck_revoke_{row['id']}_{row['user_id']}"
                ),
            ],
            [
                btn("\U0001f517 see.tg",   url=seetg_url),
                btn("\U0001f4ce t.me/nft", url=nft_url),
            ],
        ])

        header   = f"\U0001f512 <b>\u0421\u043a\u0440\u044b\u0442\u044b\u0439 \u043f\u0440\u043e\u0444\u0438\u043b\u044c</b> ({i+1}/{len(hidden_found)})"
        nft_line = f"\u041d\u0424\u0422: <b>{_html.escape(str(nft_disp))}</b> (#{row['nft_number']})"
        skin_line= f"\u041e\u0431\u043b\u0438\u043a: <i>{_html.escape(str(row.get('model_name') or '-'))}</i>"
        own_line = f"\u0412\u043b\u0430\u0434\u0435\u043b\u0435\u0446: <b>{_html.escape(str(owner_name))}</b> ({owner_uname})"
        pg_line  = f"\u0418\u043c\u044f \u043d\u0430 \u0441\u0442\u0440.: <i>{_html.escape(str(row.get('owner_name') or '-'))}</i>"
        footer   = "\u041f\u0440\u043e\u0444\u0438\u043b\u044c \u0441\u043a\u0440\u044b\u0442 \u2014 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c \u0432\u043b\u0430\u0434\u0435\u043d\u0438\u0435 \u0447\u0435\u0440\u0435\u0437 see.tg \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e."
        text = "\n\n".join([header, "\n".join([nft_line, skin_line, own_line, pg_line]), footer])

        sent_ok = False
        for attempt in range(3):
            try:
                await update.message.reply_text(
                    text,
                    parse_mode=ParseMode.HTML,
                    reply_markup=kb,
                    disable_web_page_preview=True,
                )
                sent_ok = True
                break
            except Exception as _ex:
                _err = str(_ex)
                if "retry after" in _err.lower() or "flood" in _err.lower():
                    try:
                        _wait = int(re.search(r"retry after (\d+)", _err, re.I).group(1)) + 1
                    except Exception:
                        _wait = 10
                    logger.warning("nft_recheck send: flood wait %ss (%d/%d)", _wait, i+1, len(hidden_found))
                    await asyncio.sleep(_wait)
                else:
                    logger.warning("nft_recheck send: failed %d: %s", i+1, _ex)
                    break

        if not sent_ok:
            logger.warning("nft_recheck: gave up on msg %d/%d", i+1, len(hidden_found))

        # Пауза между сообщениями (каждые 20 — подольше)
        await asyncio.sleep(1.5 if (i + 1) % 20 == 0 else 0.4)


async def cmd_admin_nft_invite(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /admin_nft_invite — найти всех у кого есть верифицированный NFT,
    но кто ещё не состоит в чате держателей, и отправить им приглашение.
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return

    HOLDERS_CHAT_ID   = -2610292022          # числовой ID чата
    HOLDERS_CHAT_LINK = "https://t.me/kissed_frog_holders"

    msg = await update.message.reply_text("⏳ Проверяю держателей NFT...")

    # Получаем всех у кого есть хотя бы 1 верифицированный NFT
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT DISTINCT user_id FROM nft_frogs WHERE verified=1"
        ) as c:
            nft_holders = [r["user_id"] for r in await c.fetchall()]

    total       = len(nft_holders)
    in_chat     = 0
    not_in_chat = 0
    invited     = 0
    failed      = 0
    to_invite   = []

    await msg.edit_text(
        f"⏳ Нашло {total} держателей NFT. Проверяю членство в чате..."
    )

    # Проверяем кто уже в чате
    for uid in nft_holders:
        try:
            member = await ctx.bot.get_chat_member(HOLDERS_CHAT_ID, uid)
            if member.status in ("member", "administrator", "creator", "restricted"):
                in_chat += 1
            else:
                not_in_chat += 1
                to_invite.append(uid)
        except Exception:
            not_in_chat += 1
            to_invite.append(uid)
        await asyncio.sleep(0.05)

    try:
        await msg.edit_text(
            f"{_E_CHECK} Уже в чате: <b>{in_chat}</b>\n"
            f"📨 Нужно пригласить: <b>{len(to_invite)}</b>\n\n"
            f"Отправляю приглашения...",
            parse_mode="HTML",
        )
    except (BadRequest, Forbidden, TimedOut):
        pass

    # Отправляем приглашения тем кто не в чате
    for i, uid in enumerate(to_invite):
        frog_f  = await db_get(uid)
        fname_u = frog_f.get("first_name", "Держатель") if frog_f else "Держатель"

        lines = [
            f"🐸 <b>Привет, {_html.escape(str(fname_u))}!</b>",
            "",
            "🔑 Ты владеешь Kissed Frog NFT — тебе открыт доступ в закрытый чат держателей!",
            "",
            "Там работает наш Тамагочи 🐸, царит дружелюбная атмосфера и обсуждают самые интересные новости мира.",
            "",
            "Присоединяйся ↓",
        ]
        invite_text = "\n".join(lines)

        kb = InlineKeyboardMarkup([[
            btn("🐸 Войти в чат", url=HOLDERS_CHAT_LINK)
        ]])

        sent_ok = False
        for attempt in range(3):
            try:
                await ctx.bot.send_message(
                    uid,
                    invite_text,
                    parse_mode="HTML",
                    reply_markup=kb,
                    disable_web_page_preview=True,
                )
                sent_ok = True
                invited += 1
                break
            except Exception as _ex:
                _err = str(_ex)
                if "retry after" in _err.lower() or "flood" in _err.lower():
                    try:
                        import re as _re
                        _wait = int(_re.search(r"retry after (\d+)", _err, _re.I).group(1)) + 1
                    except Exception:
                        _wait = 10
                    logger.warning("nft_invite: flood wait %ss (%d/%d)", _wait, i + 1, len(to_invite))
                    await asyncio.sleep(_wait)
                else:
                    logger.warning("nft_invite: uid=%s err=%s", uid, _ex)
                    failed += 1
                    break

        await asyncio.sleep(1.5 if (i + 1) % 20 == 0 else 0.4)

    # Финальный отчёт
    report_lines = [
        "✅ <b>Рассылка завершена</b>",
        "",
        f"{_E_CHART} Всего NFT-держателей: <b>{total}</b>",
        f"✅ Уже в чате: <b>{in_chat}</b>",
        f"📨 Приглашений отправлено: <b>{invited}</b>",
        f"{_E_BAN} Не доставлено (бот заблокирован): <b>{failed}</b>",
    ]
    try:
        await update.message.reply_text("\n".join(report_lines), parse_mode="HTML")
    except (BadRequest, Forbidden, TimedOut):
        pass

async def cmd_giftfloors(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /giftfloors [slug] — флор коллекции и флоры по моделям.
    По умолчанию — KissedFrog. Пример: /giftfloors PlushPepe
    """
    if not await group_cmd_guard(update, "giftfloors", ctx):
        return
    await thinking(update)

    slug = ctx.args[0].strip() if ctx.args else "KissedFrog"
    msg = await update.message.reply_text(
        f"<i>Загружаю флоры {_html.escape(slug)}...</i>",
        parse_mode=ParseMode.HTML,
    )

    # Запрашиваем флоры + курс параллельно
    # /api/market/floors возвращает {title: {market: nanoton_str}}
    # title = "Kissed Frog" (с пробелом!), а slug = "KissedFrog" — потому и не находило
    floors_data, rate_data = await asyncio.gather(
        seetg_request("/api/market/floors", {"slug": slug, "include_models": "true"}),
        seetg_request("/api/rate"),
    )

    # Курс TON→USD
    ton_usd: float | None = None
    if isinstance(rate_data, dict):
        try:
            ton_usd = float(rate_data.get("usd") or rate_data.get("rate") or 0) or None
        except (TypeError, ValueError):
            pass

    def _best_ton(d: dict) -> float | None:
        """Минимальный флор из {market: nanoton} или {model: {market: nanoton}}."""
        best = None
        for k, v in d.items():
            if isinstance(v, (int, str)):
                t = _seetg_nanoton_to_ton(v)
                if t and (best is None or t < best):
                    best = t
            elif isinstance(v, dict):
                for _, v2 in v.items():
                    t = _seetg_nanoton_to_ton(v2)
                    if t and (best is None or t < best):
                        best = t
        return best

    # Определяем запись коллекции — ключ может быть title с пробелами ("Kissed Frog")
    # или slug ("KissedFrog"). Ищем нечётко.
    collection_entry: dict | None = None
    found_title: str = slug
    if isinstance(floors_data, dict):
        slug_norm = slug.lower().replace(" ", "").replace("-", "")
        for title_key, v in floors_data.items():
            key_norm = title_key.lower().replace(" ", "").replace("-", "")
            if key_norm == slug_norm:
                collection_entry = v
                found_title = title_key
                break
        if collection_entry is None and floors_data:
            # Берём единственную/первую запись
            found_title, collection_entry = next(iter(floors_data.items()))

    if not collection_entry:
        # Фолбэк на xgift
        coll_data, models_data = await asyncio.gather(
            xgift_collection_info(slug),
            xgift_models_floor(slug),
        )
        if not coll_data and not models_data:
            try:
                await msg.edit_text(
                    f"Коллекция <b>{_html.escape(slug)}</b> не найдена.",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
            return
        lines = [f"<b>Флоры · {_html.escape(slug)}</b>\n"]
        if coll_data:
            floor = coll_data.get("floorPrice")
            if floor:
                try:
                    lines.append(f"Флор: <b>{float(floor):.2f} TON</b>")
                except (TypeError, ValueError):
                    pass
        if models_data:
            lines.append("\n<b>Флоры по моделям:</b>")
            for model, price in sorted(models_data.items(), key=lambda x: x[1])[:15]:
                lines.append(f"  {_html.escape(str(model))}: <b>{price:.2f} TON</b>")
        try:
            await msg.edit_text("\n".join(lines), parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Разбираем ответ ────────────────────────────────────────────────────────
    market_labels = {"telegram": "Telegram", "getgems": "GetGems", "portals": "Portals", "tonnel": "Tonnel"}

    global_floor = _best_ton(collection_entry)
    lines = [f"<b>Флоры · {_html.escape(found_title)}</b>\n"]

    if global_floor:
        usd_part = f" (≈${global_floor * ton_usd:.0f})" if ton_usd else ""
        lines.append(f"Лучший флор: <b>{global_floor:.2f} TON{usd_part}</b>")

    # Флоры по маркетам (прямые значения nanoton)
    market_floors: dict[str, float] = {}
    model_floors: dict[str, float] = {}

    for key, val in collection_entry.items():
        if isinstance(val, (int, str)):
            t = _seetg_nanoton_to_ton(val)
            if t:
                market_floors[key] = t
        elif isinstance(val, dict):
            # include_models=true: {model_name: {market: nanoton}}
            # или {market: {model_name: nanoton}} — разбираем оба варианта
            first_inner_key = next(iter(val), None)
            if first_inner_key and isinstance(val.get(first_inner_key), (int, str)):
                # {market: nanoton} внутри модели — это модель
                best_model = _best_ton(val)
                if best_model:
                    if key not in model_floors or best_model < model_floors[key]:
                        model_floors[key] = best_model
            else:
                # {model_name: nanoton_or_dict} — модели сгруппированы под маркетом
                for inner_k, inner_v in val.items():
                    t = _seetg_nanoton_to_ton(inner_v) if isinstance(inner_v, (int, str)) else _best_ton(inner_v) if isinstance(inner_v, dict) else None
                    if t:
                        if inner_k not in model_floors or t < model_floors[inner_k]:
                            model_floors[inner_k] = t

    if market_floors:
        lines.append("")
        lines.append("<b>По маркетам:</b>")
        for market, price in sorted(market_floors.items(), key=lambda x: x[1]):
            mlabel = market_labels.get(market, market)
            lines.append(f"  {mlabel}: <b>{price:.2f} TON</b>")

    if model_floors:
        lines.append("")
        lines.append("<b>Флоры по моделям:</b>")
        for model, price in sorted(model_floors.items(), key=lambda x: x[1])[:20]:
            lines.append(f"  {_html.escape(str(model))}: <b>{price:.2f} TON</b>")
        if len(model_floors) > 20:
            lines.append(f"  <i>...и ещё {len(model_floors) - 20} моделей</i>")

    if not ctx.args:
        lines.append("\n<i>Другая коллекция: /giftfloors PlushPepe</i>")

    try:
        await msg.edit_text("\n".join(lines), parse_mode=ParseMode.HTML)
    except (BadRequest, Forbidden, TimedOut):
        pass


# ══════════════════════════════════════════════════════════════════════════════
# 🔔 JOB: МОНИТОРИНГ РЕДКИХ ГИФТОВ УЧАСТНИКОВ ЧАТА (xgift API)
# Проверяет зарегистрированные KissedFrog NFT игроков — если появились новые
# редкие гифты в коллекции — анонсирует в чат.
# (Поиск по владельцу недоступен в xgift — мониторим изменения флоров коллекции)
# ══════════════════════════════════════════════════════════════════════════════

_seetg_last_floor: dict[str, float] = {}  # collection_name → последний известный флор


async def job_seetg_gift_monitor(ctx: ContextTypes.DEFAULT_TYPE):
    """
    Запускается раз в 2 часа.
    Отслеживает изменения флора KissedFrog через see.tg API.
    При изменении флора на ≥10% — анонсирует в чат.
    """
    bot = ctx.bot
    collections_to_monitor = ["KissedFrog"]

    for coll_name in collections_to_monitor:
        try:
            data = await seetg_get_floors(coll_name)
            if not data:
                continue

            # Ищем запись с нашей коллекцией
            floor_ton: float | None = None
            for title_key, v in data.items():
                if title_key.lower() == coll_name.lower():
                    if isinstance(v, dict):
                        # Берём минимальный флор из всех маркетов
                        for _market, nanoton in v.items():
                            if isinstance(nanoton, (int, str)):
                                t = _seetg_nanoton_to_ton(nanoton)
                                if t and (floor_ton is None or t < floor_ton):
                                    floor_ton = t
                    break

            if floor_ton is None:
                continue

            prev = _seetg_last_floor.get(coll_name)
            _seetg_last_floor[coll_name] = floor_ton

            if prev is None:
                continue  # первый запуск — просто запоминаем

            change_pct = (floor_ton - prev) / prev * 100 if prev > 0 else 0
            if abs(change_pct) >= 10:
                arrow = "📈" if change_pct > 0 else "📉"
                sign = "+" if change_pct > 0 else ""
                text = (
                    f"{arrow} <b>Флор {_html.escape(coll_name)} изменился!</b>\n"
                    f"Было: {prev:.2f} TON → Стало: <b>{floor_ton:.2f} TON</b> "
                    f"({sign}{change_pct:.1f}%)"
                )
                await announce(bot, text, announce_level="major")

        except Exception as e:
            print(f"⚠️ job_seetg_gift_monitor {coll_name}: {e}")
        await asyncio.sleep(1)


async def cmd_checkgroup(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /checkgroup [chat_id] [slug]
    Проверяет участников группы на актуальное владение гифтом.
    По умолчанию slug = KissedFrog, группа = NFT_CLUB_CHAT_ID.
    Только для администраторов.
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("⛔ Только для администраторов.")
        return

    # Парсим аргументы
    target_chat_id: int | None = None
    slug = "KissedFrog"
    if ctx.args:
        for arg in ctx.args:
            if arg.lstrip("-").isdigit():
                target_chat_id = int(arg)
            else:
                slug = arg.strip()
    if target_chat_id is None:
        target_chat_id = NFT_CLUB_CHAT_ID

    msg = await update.message.reply_text(
        f"{_E_SEARCH} <i>Начинаю проверку участников чата {target_chat_id} "
        f"на владение <b>{_html.escape(slug)}</b>...</i>\n"
        f"Это может занять несколько минут.",
        parse_mode=ParseMode.HTML,
    )

    # Берём ВСЕ строки верифицированных NFT — группируем по user_id,
    # сохраняя все NFT каждого пользователя (для показа нескольких гифтов)
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT user_id, nft_number, model_name, nft_url "
            "FROM nft_frogs WHERE verified=1 ORDER BY user_id, nft_number",
        ) as c:
            db_rows = await c.fetchall()

    if not db_rows:
        try:
            await msg.edit_text(
                f"{_E_CROSS} В базе нет верифицированных владельцев NFT.",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # Группируем все NFT по user_id: {uid: [(number, model, url), ...]}
    from collections import defaultdict
    user_nfts: dict[int, list[tuple]] = defaultdict(list)
    for row in db_rows:
        uid, nft_number, model_name, nft_url = row
        user_nfts[int(uid)].append((str(nft_number), model_name or "?", nft_url or ""))

    unique_holders = list(user_nfts.items())  # [(uid, [(num, model, url), ...]), ...]

    # Категории результатов
    # sold_nft: [(user_label, [(num_link, new_owner), ...])]  — в группе, но NFT продан
    # no_nft_in_group: [(user_label, [])]                     — в группе, нет ни одного валидного NFT
    # still_holding_count: int
    # left_group_count: int
    # error_count: int

    still_holding_count = 0
    left_group_count    = 0
    error_count         = 0
    # Для «нет NFT»: список строк вида "username/ссылка — #num → owner, #num2 → owner2"
    no_nft_entries: list[str] = []

    checked = 0

    def _user_link(uid: int, username: str | None) -> str:
        """Ссылка на пользователя: @username или https://t.me/@id..."""
        if username:
            return f'<a href="https://t.me/{username}">@{_html.escape(username)}</a>'
        return f'<a href="https://t.me/@id{uid}">id{uid}</a>'

    def _nft_link(slug_: str, num_: str) -> str:
        """Номер гифта как ссылка на t.me/nft/..."""
        return f'<a href="https://t.me/nft/{slug_}-{num_}">#{num_}</a>'

    for uid, nfts in unique_holders:
        checked += 1

        # Прогресс каждые 10 юзеров
        if checked % 10 == 0 or checked == len(unique_holders):
            try:
                await msg.edit_text(
                    f"{_E_SEARCH} <i>Проверяю... {checked}/{len(unique_holders)}</i>\n"
                    f"{_E_CHECK} держат: {still_holding_count} · "
                    f"{_E_CROSS} нет NFT: {len(no_nft_entries)} · "
                    f"{_E_DOOR} вышли: {left_group_count}",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass

        # ── Проверяем членство в группе ──────────────────────────────────────
        username_in_group: str | None = None
        try:
            member = await ctx.bot.get_chat_member(target_chat_id, uid)
            if member.status in ("left", "kicked", "banned"):
                left_group_count += 1
                await asyncio.sleep(0.05)
                continue
            # Пытаемся взять username из объекта member
            if hasattr(member, "user") and member.user:
                username_in_group = member.user.username or None
        except Exception:
            left_group_count += 1
            await asyncio.sleep(0.05)
            continue

        # ── Проверяем каждый NFT этого пользователя через API ────────────────
        valid_nfts:  list[str] = []   # номера-ссылки подтверждённых NFT
        invalid_nfts: list[str] = []  # "номер-ссылка → новый владелец"

        for nft_number, model_name, nft_url in nfts:
            m_url = re.match(r"https?://t\.me/nft/([A-Za-z]+)-(\d+)", nft_url)
            if not m_url:
                error_count += 1
                continue

            gift_slug = m_url.group(1)
            gift_num  = int(m_url.group(2))

            try:
                gift_data = await seetg_get_gift(gift_slug, gift_num)
                await asyncio.sleep(0.25)
            except Exception as e:
                error_count += 1
                continue

            if not gift_data:
                error_count += 1
                continue

            current_owner = gift_data.get("current_owner") or {}
            owner_tg_id   = current_owner.get("telegram_id")

            num_link = _nft_link(gift_slug, str(gift_num))

            if owner_tg_id and int(owner_tg_id) == uid:
                valid_nfts.append(num_link)
            else:
                # Продан — показываем кому ушёл
                new_owner_uname = current_owner.get("username") or ""
                new_owner_name  = current_owner.get("name") or new_owner_uname or "?"
                if new_owner_uname:
                    new_owner_str = f'<a href="https://t.me/{new_owner_uname}">@{_html.escape(new_owner_uname)}</a>'
                else:
                    new_owner_tg = current_owner.get("telegram_id")
                    if new_owner_tg:
                        new_owner_str = f'<a href="https://t.me/@id{new_owner_tg}">{_html.escape(str(new_owner_name))}</a>'
                    else:
                        new_owner_str = _html.escape(str(new_owner_name))
                invalid_nfts.append(f"{num_link} → {new_owner_str}")

        # ── Классифицируем пользователя ──────────────────────────────────────
        if valid_nfts:
            still_holding_count += 1
        else:
            # В группе, но ни одного живого NFT — попадает в список «нет NFT»
            user_label = _user_link(uid, username_in_group)
            if invalid_nfts:
                detail = ", ".join(invalid_nfts)
                no_nft_entries.append(f"{user_label} — {detail}")
            else:
                no_nft_entries.append(user_label)

    # ── Финальный отчёт ──────────────────────────────────────────────────────
    summary = (
        f"{_E_CHART} <b>Итог проверки {_html.escape(slug)}</b>\n\n"
        f"✅ Держат NFT: <b>{still_holding_count}</b>\n"
        f"{_E_CROSS} Нет NFT (в группе): <b>{len(no_nft_entries)}</b>\n"
        f"{_E_DOOR} Вышли из группы: <b>{left_group_count}</b>\n"
        + (f"⚠️ Ошибки API: <b>{error_count}</b>\n" if error_count else "")
        + f"{_E_USERS} Проверено: <b>{len(unique_holders)}</b>"
    )

    if not no_nft_entries:
        try:
            await msg.edit_text(summary, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # Список «нет NFT» может быть длинным — разбиваем на части по 4000 символов
    header = f"{summary}\n\n{_E_CROSS} <b>Нет NFT — полный список ({len(no_nft_entries)}):</b>\n"
    chunk_lines: list[str] = []
    chunks: list[str] = []
    current_len = len(header)

    for entry in no_nft_entries:
        line = f"· {entry}"
        if current_len + len(line) + 1 > 4000:
            chunks.append(header + "\n".join(chunk_lines))
            chunk_lines = [line]
            current_len = len(line) + 1
            header = ""  # заголовок только в первом чанке
        else:
            chunk_lines.append(line)
            current_len += len(line) + 1

    if chunk_lines:
        chunks.append(header + "\n".join(chunk_lines))

    # Первый чанк — редактируем прогресс-сообщение
    try:
        await msg.edit_text(chunks[0], parse_mode=ParseMode.HTML, disable_web_page_preview=True)
    except Exception:
        await update.message.reply_text(chunks[0], parse_mode=ParseMode.HTML, disable_web_page_preview=True)

    # Остальные части — новые сообщения
    for chunk in chunks[1:]:
        await asyncio.sleep(0.3)
        await update.message.reply_text(chunk, parse_mode=ParseMode.HTML, disable_web_page_preview=True)



# ══════════════════════════════════════════════════════════════════════════════
# 🏆 РЕФЕРАЛЬНЫЙ КОНКУРС
# ══════════════════════════════════════════════════════════════════════════════
# Логика:
#   - Админ запускает /contest_start [название]
#   - Все новые рефералы записываются в contest_referrals с ticket_valid=0
#   - Тикет становится валидным когда реферал достигает 2-го уровня И собирает 10+ скинов
#   - Один реферал = 20 билетов (рефер должен выполнить условия, иначе 0)
#   - За каждый УНИКАЛЬНЫЙ скин с гачи (с момента старта конкурса) — 1 билет (макс. 50)
#   - Счётчик скинов для конкурса у всех начинается с нуля при старте
#   - Победителей выбирает /contest_winners N
#   - Антинакрутка: повторный IP/device, burst-паттерны, свежие аккаунты
# ══════════════════════════════════════════════════════════════════════════════

async def _get_active_contest() -> dict | None:
    """Возвращает текущий активный конкурс или None."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM ref_contests WHERE active=1 ORDER BY id DESC LIMIT 1"
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def _record_contest_referral(referrer_id: int, referred_id: int, contest_id: int, fraud_flag: int = 0) -> None:
    """Записывает новый реферал в таблицу конкурса. Дубли игнорируются."""
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT OR IGNORE INTO contest_referrals"
            "(contest_id, referrer_id, referred_id, joined_at, ticket_valid, fraud_flag)"
            " VALUES (?,?,?,?,0,?)",
            (contest_id, referrer_id, referred_id, time.time(), fraud_flag),
        )
        await db.commit()


async def _try_validate_contest_ticket(referred_id: int) -> None:
    """
    Вызывается при достижении реферала 2-го уровня.
    Активирует тикет в текущем конкурсе и начисляет 20 билетов рефереру,
    если реферал также собрал 10+ уникальных скинов.
    """
    # Считаем уникальные скины реферала
    coll = await db_coll(referred_id)
    if len(coll) < 10:
        return  # Недостаточно скинов — ещё не время валидировать

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT cr.id, cr.contest_id, cr.fraud_flag "
            "FROM contest_referrals cr "
            "JOIN ref_contests rc ON rc.id = cr.contest_id "
            "WHERE cr.referred_id=? AND cr.ticket_valid=0 AND rc.active=1 "
            "ORDER BY cr.id DESC LIMIT 1",
            (referred_id,),
        ) as c:
            row = await c.fetchone()
        if not row:
            return
        cr_id, contest_id, fraud_flag = row
        if fraud_flag:
            return  # помечен как фрод — не валидируем
        await db.execute(
            "UPDATE contest_referrals SET ticket_valid=1, validated_at=?, tickets_awarded=20 WHERE id=?",
            (time.time(), cr_id),
        )
        await db.commit()


# ══════════════════════════════════════════════════════════════════════════════
# 🎟  СКИН-БИЛЕТЫ КОНКУРСА
#   За каждые 10 уникальных скинов (с момента старта конкурса) — 1 билет.
#   Счётчик у всех с нуля, чтобы старые игроки тоже крутили гачу.
# ══════════════════════════════════════════════════════════════════════════════

async def _award_skin_contest_tickets(uid: int) -> int:
    """
    Вызывается после каждого гача-пулла (после log_gacha_pull).
    Считает кол-во DISTINCT скинов из gacha_log с момента старта конкурса —
    так все игроки стартуют на равных, независимо от старой коллекции.
    Возвращает количество НОВЫХ выданных скин-билетов (0 или больше).
    """
    contest = await _get_active_contest()
    if not contest:
        return 0

    c_id = contest["id"]
    start_time = contest["start_time"]

    async with aiosqlite.connect(DB_PATH) as db:
        # Сколько уникальных скинов получено из гачи с момента старта конкурса
        async with db.execute(
            "SELECT COUNT(DISTINCT skin) FROM gacha_log WHERE user_id=? AND ts >= ?",
            (uid, start_time),
        ) as cur:
            row_gl = await cur.fetchone()
        skins_collected = row_gl[0] if row_gl else 0

        # Текущий прогресс игрока
        async with db.execute(
            "SELECT tickets_issued FROM contest_skin_progress WHERE contest_id=? AND user_id=?",
            (c_id, uid),
        ) as cur:
            row = await cur.fetchone()
        tickets_before = row[0] if row else 0

        tickets_should_be = min(skins_collected, 50)
        new_tickets = max(0, tickets_should_be - tickets_before)

        if row:
            await db.execute(
                "UPDATE contest_skin_progress SET skins_collected=?, tickets_issued=? "
                "WHERE contest_id=? AND user_id=?",
                (skins_collected, tickets_before + new_tickets, c_id, uid),
            )
        else:
            await db.execute(
                "INSERT OR IGNORE INTO contest_skin_progress(contest_id, user_id, skins_collected, tickets_issued) "
                "VALUES(?,?,?,?)",
                (c_id, uid, skins_collected, tickets_before + new_tickets),
            )
        await db.commit()

    return new_tickets


# ══════════════════════════════════════════════════════════════════════════════
# 🏆  NFT-КОНКУРС ПО ЛИГАМ
#
#  Конкурс среди топ-игроков лиг Икринка / Головастик / Лягушонок (id 0,1,2).
#  Призы — 3 Telegram NFT (задаются при запуске).
#
#  Админ-команды:
#    /nft_contest_start [название] — запустить ивент
#    /nft_contest_end              — завершить ивент
#    /nft_contest_status           — прогресс (топ по каждой лиге)
#    /nft_contest_broadcast        — рассылка только игрокам лиг 0-2
#
#  Игроки лиг 0/1/2 видят кнопку «🏆 NFT-конкурс» в главном меню.
# ══════════════════════════════════════════════════════════════════════════════

# Лиги, участвующие в конкурсе
NFT_CONTEST_TARGET_LEAGUES = [0, 1, 2]

# Сколько топ-мест выигрывают приз в каждой лиге
NFT_CONTEST_WINNERS_PER_LEAGUE = 1


async def _get_active_nft_contest() -> dict | None:
    """Возвращает активный NFT-конкурс или None."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM nft_league_contests WHERE active=1 ORDER BY id DESC LIMIT 1"
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def _nft_contest_top_combined(n: int = 10) -> list[dict]:
    """Возвращает единый топ-N среди всех игроков лиг NFT_CONTEST_TARGET_LEAGUES по xp_week."""
    placeholders = ",".join("?" * len(NFT_CONTEST_TARGET_LEAGUES))
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            f"SELECT user_id, first_name, frog_name, xp_week, level, league, "
            f"subscription_until, subscription_type "
            f"FROM frogs "
            f"WHERE league IN ({placeholders}) AND xp_week > 0 AND is_bot=0 AND banned=0 "
            f"ORDER BY xp_week DESC LIMIT ?",
            (*NFT_CONTEST_TARGET_LEAGUES, n),
        ) as c:
            rows = await c.fetchall()
    return [dict(r) for r in rows]


async def _nft_contest_rank_combined(uid: int) -> tuple[int, int]:
    """Возвращает (место, всего участников) игрока в объединённом конкурсном топе."""
    placeholders = ",".join("?" * len(NFT_CONTEST_TARGET_LEAGUES))
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT xp_week FROM frogs WHERE user_id=?", (uid,)
        ) as c:
            row = await c.fetchone()
        user_xp = row[0] if row else 0
        async with db.execute(
            f"SELECT COUNT(*)+1 FROM frogs "
            f"WHERE league IN ({placeholders}) AND xp_week > ? AND is_bot=0 AND banned=0",
            (*NFT_CONTEST_TARGET_LEAGUES, user_xp),
        ) as c:
            rank = (await c.fetchone())[0]
        async with db.execute(
            f"SELECT COUNT(*) FROM frogs "
            f"WHERE league IN ({placeholders}) AND is_bot=0 AND banned=0",
            (*NFT_CONTEST_TARGET_LEAGUES,),
        ) as c:
            total = (await c.fetchone())[0]
    return rank, total


def _nft_prize_link(prize_slug: str) -> str:
    """Превращает 'TimelessBook-17327' в кликабельную ссылку для HTML."""
    slug = prize_slug.strip()
    return f'<a href="https://t.me/nft/{slug}">{_html.escape(slug)}</a>'


async def _nft_contest_menu_text(uid: int) -> tuple[str, InlineKeyboardMarkup]:
    """Текст и клавиатура для страницы NFT-конкурса (единый топ лиг Икринка+Головастик+Лягушонок)."""
    contest = await _get_active_nft_contest()
    f = await db_get(uid)
    user_league = f.get("league", 0) if f else 0

    if not contest:
        text = (
            "🏆 <b>NFT-лига</b>\n\n"
            "Конкурс сейчас не активен.\n"
            "Следи за анонсами в чате!"
        )
        kb = InlineKeyboardMarkup([[btn("◀️ Назад", callback_data="refresh")]])
        return text, kb

    prizes_raw = contest.get("prizes", "[]")
    try:
        prizes = json.loads(prizes_raw) if isinstance(prizes_raw, str) else prizes_raw
    except Exception:
        prizes = []

    top_rows = await _nft_contest_top_combined(10)
    rank, total = await _nft_contest_rank_combined(uid)

    # Заголовок — без эмодзи лиг, только названия
    league_names = " + ".join(
        league_info(lid)[1] for lid in NFT_CONTEST_TARGET_LEAGUES
    )

    lines = [
        "🏆 <b>NFT-лига</b>",
        "",
        "Конкурсная лига:",
        f"{league_names}",
        "",
        "<b>🎁 Призы (топ-3 общего зачёта):</b>",
    ]
    medals = ["🥇", "🥈", "🥉"]
    if prizes:
        for i, p in enumerate(prizes, 1):
            medal = medals[i - 1] if i <= 3 else f"{i}."
            lines.append(f"  {medal} {_nft_prize_link(str(p))}")
    else:
        lines.append("  🥇🥈🥉 3 Telegram NFT")

    lines += ["", "<b>Таблица лидеров:</b>"]

    if top_rows:
        for i, row in enumerate(top_rows, 1):
            name = row.get("frog_name") or row.get("first_name") or "—"
            xp = row.get("xp_week", 0)
            l_badge = league_badge(row.get("league", 0))
            prefix = medals[i - 1] if i <= 3 else f"{i}."
            is_me = row.get("user_id") == uid
            marker = " ← ты" if is_me else ""
            lines.append(f"  {prefix} {_html.escape(str(name))} {l_badge} — {xp:,} XP{marker}")
    else:
        lines.append("  (пока нет участников)")

    lines.append("")
    if user_league in NFT_CONTEST_TARGET_LEAGUES:
        if rank <= 3:
            lines.append(f"🎉 <b>Ты на #{rank} месте — призовая зона!</b>")
        else:
            lines.append(f"Твоя позиция: #{rank} из {total}")
            lines.append(f"До призовой тройки: ещё {rank - 3} позиций")

    kb = InlineKeyboardMarkup([[btn("◀️ Назад", callback_data="refresh")]])
    return "\n".join(lines), kb


