async def cmd_nft_contest_broadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/nft_contest_broadcast <текст> — рассылка только игрокам лиг Икринка/Головастик/Лягушонок."""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return

    raw = update.message.text or ""
    prefix_end = raw.find(" ")
    if prefix_end == -1:
        text = ""
    else:
        text = raw[prefix_end + 1:].strip()

    if not text and update.message.reply_to_message:
        text = update.message.reply_to_message.text or update.message.reply_to_message.caption or ""

    if not text:
        await update.message.reply_text(
            "Использование: /nft_contest_broadcast <текст>\n\n"
            "Рассылает сообщение только игрокам лиг:\n"
            f"🥚 Икринка / 🐛 Головастик / {_E_FROG} Лягушонок\n\n"
            "Поддерживается HTML: <b>жирный</b>, <i>курсив</i>.\n"
            "Или ответь на сообщение: /nft_contest_broadcast",
            parse_mode=ParseMode.HTML,
        )
        return

    async with aiosqlite.connect(DB_PATH) as db:
        placeholders = ",".join("?" * len(NFT_CONTEST_TARGET_LEAGUES))
        async with db.execute(
            f"SELECT user_id FROM frogs WHERE league IN ({placeholders}) AND alive=1 AND is_bot=0 AND banned=0",
            NFT_CONTEST_TARGET_LEAGUES,
        ) as c:
            users = [r[0] for r in await c.fetchall()]

    sent = 0
    failed = 0
    status_msg = await update.message.reply_text(
        f"📢 Рассылка {len(users)} игрокам лиг Икринка/Головастик/Лягушонок..."
    )
    sem_bc = asyncio.Semaphore(20)

    async def _send_one(target_uid):
        nonlocal sent, failed
        async with sem_bc:
            try:
                await ctx.bot.send_message(target_uid, text, parse_mode=ParseMode.HTML)
                sent += 1
            except Exception:
                failed += 1

    await asyncio.gather(*[_send_one(u) for u in users])
    try:
        await status_msg.edit_text(
            f"{_E_CHECK} Рассылка завершена!\n"
            f"🥚🐛{_E_FROG} Лиги: Икринка, Головастик, Лягушонок\n"
            f"📨 Доставлено: {he(sent)}\n{_E_CROSS} Не доставлено: {he(failed)}", parse_mode=ParseMode.HTML
        )
    except (BadRequest, Forbidden, TimedOut):
        pass


