async def cmd_contest_end(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/contest_end — завершить текущий конкурс (только админ)."""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("⛔ Только для администраторов.")
        return

    contest = await _get_active_contest()
    if not contest:
        await update.message.reply_text("Нет активного конкурса.")
        return

    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE ref_contests SET active=0, end_time=? WHERE id=?",
            (time.time(), contest["id"]),
        )
        await db.commit()

    # Финальная статистика
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COALESCE(SUM(COALESCE(tickets_awarded,1)),0) FROM contest_referrals WHERE contest_id=? AND ticket_valid=1",
            (contest["id"],),
        ) as c:
            valid_ref_tickets = (await c.fetchone())[0]
        async with db.execute(
            "SELECT COALESCE(SUM(tickets_issued),0) FROM contest_skin_progress WHERE contest_id=?",
            (contest["id"],),
        ) as c:
            valid_skin_tickets = (await c.fetchone())[0]
        async with db.execute(
            "SELECT COUNT(DISTINCT referrer_id) FROM contest_referrals WHERE contest_id=? AND ticket_valid=1",
            (contest["id"],),
        ) as c:
            unique_referrers = (await c.fetchone())[0]

    await update.message.reply_text(
        f"<b>Конкурс #{contest['id']} завершён.</b>\n\n"
        f"Название: {_html.escape(contest['title'])}\n"
        f"🤝 Реферальных билетов: <b>{valid_ref_tickets}</b>\n"
        f"🎴 Скин-билетов: <b>{valid_skin_tickets}</b>\n"
        f"{_E_TICKET} Итого: <b>{valid_ref_tickets + valid_skin_tickets}</b>\n"
        f"Участников-рефереров: <b>{unique_referrers}</b>\n\n"
        f"Выбрать победителей: /contest_winners N",
        parse_mode=ParseMode.HTML,
    )


async def cmd_contest_status(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/contest_status — статус текущего конкурса."""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("⛔ Только для администраторов.")
        return

    contest = await _get_active_contest()
    if not contest:
        await update.message.reply_text("Нет активного конкурса. Запустить: /contest_start [название]")
        return

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(*) FROM contest_referrals WHERE contest_id=?",
            (contest["id"],),
        ) as c:
            total_refs = (await c.fetchone())[0]
        async with db.execute(
            "SELECT COUNT(*) FROM contest_referrals WHERE contest_id=? AND ticket_valid=1",
            (contest["id"],),
        ) as c:
            valid_ref_tickets_count = (await c.fetchone())[0]
        async with db.execute(
            "SELECT COALESCE(SUM(tickets_issued), 0) FROM contest_skin_progress WHERE contest_id=?",
            (contest["id"],),
        ) as c:
            total_skin_tickets = (await c.fetchone())[0]
        async with db.execute(
            "SELECT COUNT(*) FROM contest_referrals WHERE contest_id=? AND fraud_flag=1",
            (contest["id"],),
        ) as c:
            fraud_count = (await c.fetchone())[0]
        async with db.execute(
            "SELECT COUNT(*) FROM contest_referrals WHERE contest_id=? AND ticket_valid=0 AND fraud_flag=0",
            (contest["id"],),
        ) as c:
            pending_count = (await c.fetchone())[0]
        # Топ-5 по суммарным билетам
        async with db.execute(
            "SELECT referrer_id, SUM(COALESCE(tickets_awarded,1)) as t "
            "FROM contest_referrals WHERE contest_id=? AND ticket_valid=1 GROUP BY referrer_id",
            (contest["id"],),
        ) as c:
            ref_top = {r[0]: r[1] for r in await c.fetchall()}
        async with db.execute(
            "SELECT user_id, tickets_issued FROM contest_skin_progress WHERE contest_id=?",
            (contest["id"],),
        ) as c:
            skin_top = {r[0]: r[1] for r in await c.fetchall()}
        all_uids = set(ref_top) | set(skin_top)
        top5_data = sorted(
            [(u, ref_top.get(u, 0) + skin_top.get(u, 0)) for u in all_uids],
            key=lambda x: -x[1]
        )[:5]

    started = datetime.fromtimestamp(contest["start_time"], tz=timezone.utc).strftime("%d.%m.%Y %H:%M")

    total_tickets = valid_ref_tickets_count * 15 + total_skin_tickets
    lines = [
        f"<b>Конкурс #{contest['id']}: {_html.escape(contest['title'])}</b>",
        f"Запущен: {started} UTC",
        "",
        f"Всего рефералов зарегистрировано: {total_refs}",
        f"🤝 Реферальных билетов: <b>{valid_ref_tickets_count * 20}</b> (×20 за каждого)",
        f"🎴 Скин-билетов: <b>{total_skin_tickets}</b> (1 за каждый уник. скин, макс. 50)",
        f"🎟 Итого билетов в конкурсе: <b>{total_tickets}</b>",
        f"Ожидают уровня 2 + 10 скинов: {pending_count}",
        f"Заблокировано (фрод): {fraud_count}",
    ]
    if top5_data:
        lines.append("")
        lines.append("<b>Топ участников по билетам:</b>")
        for i, (rid, total_t) in enumerate(top5_data, 1):
            rf = await db_get(rid)
            name = rf.get("frog_name") or rf.get("first_name") or str(rid) if rf else str(rid)
            r_t = ref_top.get(rid, 0)
            s_t = skin_top.get(rid, 0)
            lines.append(f"  {i}. {_html.escape(str(name))} — {total_t} тик. (рефер: {r_t}, скин: {s_t})")
    lines.append("")
    lines.append("Завершить: /contest_end · Победители: /contest_winners N")

    await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


async def cmd_contest_export(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /contest_export [contest_id] — выгрузить участников конкурса в файл для рандомайзера.
    Форматы:
      • tickets.txt  — каждая строка = один билет (имя повторяется N раз)
      • tickets.csv  — таблица: имя, @username, id, реф.билеты, скин.билеты, всего
    Оба файла отправляются одним сообщением.
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("⛔ Только для администраторов.")
        return

    # Определяем конкурс
    target_id = None
    if ctx.args:
        for arg in ctx.args:
            if arg.isdigit():
                target_id = int(arg)
                break

    async with aiosqlite.connect(DB_PATH) as db:
        if target_id:
            async with db.execute("SELECT * FROM ref_contests WHERE id=?", (target_id,)) as c:
                c_row = await c.fetchone()
        else:
            async with db.execute("SELECT * FROM ref_contests ORDER BY id DESC LIMIT 1") as c:
                c_row = await c.fetchone()

    if not c_row:
        await update.message.reply_text("Конкурс не найден.")
        return

    c_id    = c_row[0]
    c_title = c_row[1]

    # Реферальные билеты
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT referrer_id, SUM(COALESCE(tickets_awarded, 1)) "
            "FROM contest_referrals "
            "WHERE contest_id=? AND ticket_valid=1 AND fraud_flag=0 "
            "GROUP BY referrer_id",
            (c_id,),
        ) as c:
            ref_tickets = {r[0]: int(r[1]) for r in await c.fetchall()}

        # Скин-билеты
        async with db.execute(
            "SELECT user_id, tickets_issued FROM contest_skin_progress "
            "WHERE contest_id=? AND tickets_issued > 0",
            (c_id,),
        ) as c:
            skin_tickets = {r[0]: int(r[1]) for r in await c.fetchall()}

    all_uids = set(ref_tickets) | set(skin_tickets)
    if not all_uids:
        await update.message.reply_text(f"В конкурсе #{c_id} пока нет участников с билетами.")
        return

    # Собираем данные по каждому участнику
    participants = []
    for uid_p in all_uids:
        f_p = await db_get(uid_p)
        name = (f_p.get("frog_name") or f_p.get("first_name") or str(uid_p)) if f_p else str(uid_p)
        username = ""
        try:
            tg = await update.get_bot().get_chat(uid_p)
            if tg.username:
                username = f"@{tg.username}"
            if not name or name == str(uid_p):
                name = tg.full_name or str(uid_p)
        except (BadRequest, Forbidden, TimedOut):
            pass
        ref_t  = ref_tickets.get(uid_p, 0)
        skin_t = skin_tickets.get(uid_p, 0)
        total  = ref_t + skin_t
        participants.append({
            "uid": uid_p,
            "name": name,
            "username": username,
            "ref": ref_t,
            "skin": skin_t,
            "total": total,
        })

    # Сортируем по убыванию билетов
    participants.sort(key=lambda x: -x["total"])

    # ── tickets.txt — каждая строка = один билет ─────────────────────────────
    txt_lines = [
        f"# Конкурс #{c_id}: {c_title}",
        f"# Всего строк = всего билетов. Каждая строка — один шанс на победу.",
        f"# Формат: Имя (@username) [тип билета]",
        "",
    ]
    for p in participants:
        label = p["username"] or p["name"]
        safe  = label.replace('"', "'")
        # Реферальные билеты
        for i in range(p["ref"]):
            txt_lines.append(f"{safe} [реф #{i+1}]")
        # Скин-билеты
        for i in range(p["skin"]):
            txt_lines.append(f"{safe} [скин #{i+1}]")
    txt_lines.append("")
    txt_lines.append(f"# Итого строк-билетов: {sum(p['total'] for p in participants)}")
    txt_lines.append(f"# Участников: {len(participants)}")
    txt_content = "\n".join(txt_lines)

    # ── tickets.csv — сводная таблица ─────────────────────────────────────────
    import io, csv
    csv_buf = io.StringIO()
    writer = csv.writer(csv_buf)
    writer.writerow(["Имя", "Username", "User ID", "Реф. билеты", "Скин-билеты", "Всего билетов"])
    for p in participants:
        writer.writerow([p["name"], p["username"], p["uid"], p["ref"], p["skin"], p["total"]])
    csv_content = csv_buf.getvalue()

    # Отправляем оба файла
    from telegram import InputFile
    total_tickets = sum(p["total"] for p in participants)

    await update.message.reply_text(
        f"📦 <b>Экспорт конкурса #{c_id}</b>\n\n"
        f"Название: {_html.escape(c_title)}\n"
        f"Участников: <b>{len(participants)}</b>\n"
        f"Всего билетов: <b>{total_tickets}</b>\n\n"
        f"<b>tickets.txt</b> — каждая строка = один билет → вставь в рандомайзер\n"
        f"<b>tickets.csv</b> — сводная таблица для просмотра",
        parse_mode=ParseMode.HTML,
    )
    await update.message.reply_document(
        document=InputFile(io.BytesIO(txt_content.encode("utf-8")), filename=f"contest_{c_id}_tickets.txt"),
        caption=f"🎟 {total_tickets} билетов · {len(participants)} участников",
    )
    await update.message.reply_document(
        document=InputFile(io.BytesIO(csv_content.encode("utf-8-sig")), filename=f"contest_{c_id}_tickets.csv"),
        caption="📊 Сводная таблица (открыть в Excel / Google Sheets)",
    )


async def cmd_contest_winners(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /contest_winners [N] [contest_id] — выбрать N случайных победителей среди валидных тикетов.
    Каждый тикет = один шанс (у кого больше рефералов — больше шансов).
    По умолчанию N=1, берёт последний завершённый или активный конкурс.
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("⛔ Только для администраторов.")
        return

    n_winners = 1
    target_contest_id = None
    for arg in (ctx.args or []):
        if arg.isdigit():
            if n_winners == 1 and target_contest_id is None:
                n_winners = int(arg)
            else:
                target_contest_id = int(arg)

    async with aiosqlite.connect(DB_PATH) as db:
        if target_contest_id:
            async with db.execute(
                "SELECT * FROM ref_contests WHERE id=?", (target_contest_id,)
            ) as c:
                row = await c.fetchone()
        else:
            async with db.execute(
                "SELECT * FROM ref_contests ORDER BY id DESC LIMIT 1"
            ) as c:
                row = await c.fetchone()

    if not row:
        await update.message.reply_text("Конкурс не найден.")
        return

    c_id    = row[0]
    c_title = row[1]

    async with aiosqlite.connect(DB_PATH) as db:
        # Реферальные билеты (15 за каждого валидного реферала)
        async with db.execute(
            "SELECT referrer_id, SUM(COALESCE(tickets_awarded, 1)) "
            "FROM contest_referrals "
            "WHERE contest_id=? AND ticket_valid=1 AND fraud_flag=0 "
            "GROUP BY referrer_id",
            (c_id,),
        ) as c:
            ref_tickets = {r[0]: r[1] for r in await c.fetchall()}

        # Скин-билеты (1 за каждые 10 уникальных скинов с начала конкурса)
        async with db.execute(
            "SELECT user_id, tickets_issued FROM contest_skin_progress "
            "WHERE contest_id=? AND tickets_issued > 0",
            (c_id,),
        ) as c:
            skin_tickets = {r[0]: r[1] for r in await c.fetchall()}

    # Объединяем оба типа билетов
    all_users = set(ref_tickets) | set(skin_tickets)
    ticket_totals = {u: ref_tickets.get(u, 0) + skin_tickets.get(u, 0) for u in all_users}

    # Строим пул: каждый билет = одна запись uid в списке
    tickets = []
    for uid_t, cnt in ticket_totals.items():
        tickets.extend([uid_t] * cnt)

    if not tickets:
        await update.message.reply_text(f"Нет валидных тикетов в конкурсе #{c_id}.")
        return

    # Выбираем без возврата (один человек не может выиграть дважды)
    import random
    unique_participants = list(set(tickets))
    # Веса — количество тикетов каждого
    weights = [tickets.count(u) for u in unique_participants]

    winners = []
    pool = list(zip(unique_participants, weights))
    for _ in range(min(n_winners, len(unique_participants))):
        if not pool:
            break
        ids_pool, w_pool = zip(*pool)
        chosen = random.choices(ids_pool, weights=w_pool, k=1)[0]
        winners.append(chosen)
        pool = [(u, w) for u, w in pool if u != chosen]

    lines = [
        f"<b>Победители конкурса #{c_id}: {_html.escape(c_title)}</b>",
        f"Всего тикетов: {len(tickets)} от {len(unique_participants)} участников",
        "",
    ]
    for i, wid in enumerate(winners, 1):
        rf = await db_get(wid)
        tg_user = None
        try:
            tg_user = await update.get_bot().get_chat(wid)
        except (BadRequest, Forbidden, TimedOut):
            pass
        uname = (tg_user.username if tg_user and tg_user.username else None)
        name = (rf.get("frog_name") or rf.get("first_name") or str(wid)) if rf else str(wid)
        total_t = ticket_totals.get(wid, 0)
        ref_t = ref_tickets.get(wid, 0)
        skin_t = skin_tickets.get(wid, 0)
        breakdown = f"рефер: {ref_t}, скин: {skin_t}"
        if uname:
            user_ref = f'<a href="https://t.me/{uname}">@{_html.escape(uname)}</a>'
        else:
            user_ref = f'<a href="https://t.me/@id{wid}">{_html.escape(str(name))}</a>'
        lines.append(f"{i}. {user_ref} — {total_t} тик. ({breakdown}) (id: {wid})")

    await update.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


async def cmd_contest_refs(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /contest_refs — показать своих рефералов в текущем конкурсе с username.
    """
    if not await group_cmd_guard(update, "contest_refs", ctx):
        return

    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return

    # Берём активный конкурс; если нет — последний
    contest = await _get_active_contest()
    if not contest:
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT * FROM ref_contests ORDER BY id DESC LIMIT 1"
            ) as c:
                row = await c.fetchone()
        if not row:
            await update.message.reply_text("Конкурс ещё не запускался.")
            return
        contest = {"id": row[0], "title": row[1], "active": row[5]}

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT referred_id, ticket_valid, fraud_flag, joined_at "
            "FROM contest_referrals WHERE contest_id=? AND referrer_id=? ORDER BY joined_at",
            (contest["id"], user.id),
        ) as c:
            rows = await c.fetchall()

    valid   = [r for r in rows if r[1] == 1 and r[2] == 0]
    pending = [r for r in rows if r[1] == 0 and r[2] == 0]

    # Скин-билеты пользователя в этом конкурсе
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT skins_collected, tickets_issued FROM contest_skin_progress "
            "WHERE contest_id=? AND user_id=?",
            (contest["id"], user.id),
        ) as c:
            sp_row = await c.fetchone()
    skins_collected = sp_row[0] if sp_row else 0
    skin_tix = sp_row[1] if sp_row else 0
    ref_tix = len(valid) * 20
    total_my_tix = ref_tix + skin_tix
    skins_to_max = max(0, 50 - skins_collected)

    lines = [
        f"<b>Конкурс: {_html.escape(contest['title'])}</b>",
        f"🎟 Твои билеты: <b>{total_my_tix}</b> (🤝 рефер: {ref_tix} · 🎴 скины: {skin_tix})",
        f"🎴 Уникальных скинов с начала конкурса: <b>{skins_collected}/50</b>"
        + (f"  (осталось до макс: {skins_to_max})" if skins_to_max > 0 else "  ✅ макс!"),
        f"Валидных рефералов: <b>{len(valid)}</b> · Ждут уровня 2 + 10 скинов: {len(pending)}",
        "",
    ]

    async def _ref_label(rid: int) -> str:
        """username если есть, иначе ник из БД."""
        rf = await db_get(rid)
        try:
            tg = await update.get_bot().get_chat(rid)
            if tg.username:
                return f'@{tg.username}'
            tg_name = tg.full_name or ""
            if tg_name:
                return _html.escape(tg_name)
        except (BadRequest, Forbidden, TimedOut):
            pass
        if rf:
            return _html.escape(rf.get("frog_name") or rf.get("first_name") or str(rid))
        return str(rid)

    if valid:
        lines.append("<b>Засчитанные рефералы:</b>")
        for rid, _, _, jat in valid[:40]:
            label = await _ref_label(rid)
            lines.append(f"  {label}")
        if len(valid) > 40:
            lines.append(f"  <i>...и ещё {len(valid)-40}</i>")

    if pending:
        lines.append("")
        lines.append("<b>Ждут 2-го уровня:</b>")
        for rid, _, _, jat in pending[:20]:
            label = await _ref_label(rid)
            lines.append(f"  {label}")
        if len(pending) > 20:
            lines.append(f"  <i>...и ещё {len(pending)-20}</i>")

    if not rows:
        lines.append("У тебя пока нет рефералов в этом конкурсе.")
        bot_me = await update.get_bot().get_me()
        ref_link = f"https://t.me/{bot_me.username}?start=ref_{user.id}"
        lines.append(f"\nПригласительная ссылка:\n<code>{ref_link}</code>")

    await update.message.reply_text(
        "\n".join(lines),
        parse_mode=ParseMode.HTML,
        link_preview_options=LinkPreviewOptions(is_disabled=True),
    )


