def _memo_shuffle_pool(pool: list, correct: str, size: int = 8) -> list:
    """Перемешать пул эмодзи для игры память — правильный ответ всегда включён."""
    others = [e for e in pool if e != correct]
    chosen = random.sample(others, min(size - 1, len(others)))
    result = chosen + [correct]
    random.shuffle(result)
    return result


