# 🖱  INLINE-КНОПКИ
# ══════════════════════════════════════════
async def build_feed_kb(uid: int, f: dict) -> InlineKeyboardMarkup:
    """Строит клавиатуру меню кормления."""
    inv = await inv_get(uid)
    now = time.time()
    fly_cd = 86400
    fly_ready = now - f.get("last_fly_feed", 0) >= fly_cd
    remaining_fly = int((fly_cd - (now - f.get("last_fly_feed", 0))) / 3600)
    fly_label = (
        "🪰 Муха (бесплатно, 1×/день)"
        if fly_ready
        else f"🪰 Муха (через {remaining_fly} ч)"
    )
    rows = [[btn(fly_label, callback_data="feed_fly")]]
    for fid, food in FOOD.items():
        if fid == "fly":
            continue
        qty = inv.get(fid, 0)
        if qty > 0:
            rows.append(
                [
                    btn(
                        f"{food['emoji']} {food['name']} ×{qty}",
                        callback_data=f"feed_inv_{fid}",
                    )
                ]
            )
    rows.append(
        [
            btn("🍽 Скормить всё", callback_data="feed_all"),
            btn("🛒 Купить еду", callback_data="shop_food"),
        ]
    )
    rows.append([
        btn("🧹 Ухаживать", callback_data="menu_care"),
        btn(t("btn_back_main", f), callback_data="refresh"),
    ])
    return InlineKeyboardMarkup(rows)


