        total_available = sum(qty for _, qty in owned_by_rarity)
        if total_available < recipe["needs"]:
            await q.answer((f"Нужно {recipe['needs']} обликов {R_NAME[rar]}")[:200], show_alert=True)
            return
        extra = recipe.get("price_coins", 0)
