    # Поле 5×5, 5 мин, награда зависит от числа открытых клеток
    SAPPER_ROWS, SAPPER_COLS, SAPPER_MINES = 5, 5, 3

    def _sapper_new_board():
        """Создаёт новое поле: расставляет мины и считает соседей."""
        total = SAPPER_ROWS * SAPPER_COLS
        positions = list(range(total))
        random.shuffle(positions)
        mine_set = set(positions[:SAPPER_MINES])
        cells = []
        for i in range(total):
            r, c = divmod(i, SAPPER_COLS)
            if i in mine_set:
                cells.append(-1)
            else:
                cnt = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < SAPPER_ROWS and 0 <= nc < SAPPER_COLS:
                            if nr * SAPPER_COLS + nc in mine_set:
                                cnt += 1
                cells.append(cnt)
        return cells

    SAPPER_NUM = ["0️⃣","1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣"]

    def _sapper_render(cells, revealed: set, game_over: bool = False, won: bool = False):
        rows = []
        for r in range(SAPPER_ROWS):
            btns = []
            for c in range(SAPPER_COLS):
                i = r * SAPPER_COLS + c
                if i in revealed or game_over:
                    v = cells[i]
                    if v == -1:
                        label = "💥" if not won else "🚩"
                    elif v == 0:
                        label = "⬜"
                    else:
                        label = SAPPER_NUM[v]
                else:
                    label = "🟩"
                if game_over:
                    btns.append(btn(label, callback_data="noop"))
                else:
                    btns.append(btn(label, callback_data=f"sapper_pick_{r}_{c}"))
            rows.append(btns)
        return rows

