    # ── 5×5 СОЛО vs БОТ ────────────────────────────────────────────
    def _ttt5_render(board, game_id=None):
        """Рендерит поле 5×5."""
        EMPTY = "⬜"
        SYMBOLS = {"X": "❌", "O": "⭕"}
        rows = []
        for r in range(5):
            row = []
            for c in range(5):
                idx = r * 5 + c
                val = board[idx]
                if val:
                    btn_text = SYMBOLS.get(val, val)
                    cb = "noop"
                else:
                    btn_text = EMPTY
                    cb = f"ttt5_move_{game_id}_{idx}" if game_id else "noop"
                row.append(btn(btn_text, callback_data=cb))
            rows.append(row)
        return rows

    def _ttt5_check_winner(board):
        """Проверяет победителя — 4 в ряд на поле 5×5."""
        size = 5
        win_len = 4
        for r in range(size):
            for c in range(size):
                sym = board[r * size + c]
                if not sym:
                    continue
                # горизонталь
                if c + win_len <= size:
                    if all(board[r * size + c + k] == sym for k in range(win_len)):
                        return sym
                # вертикаль
                if r + win_len <= size:
                    if all(board[(r + k) * size + c] == sym for k in range(win_len)):
                        return sym
                # диагональ →↓
                if c + win_len <= size and r + win_len <= size:
                    if all(board[(r + k) * size + (c + k)] == sym for k in range(win_len)):
                        return sym
                # диагональ ←↓
                if c - win_len + 1 >= 0 and r + win_len <= size:
                    if all(board[(r + k) * size + (c - k)] == sym for k in range(win_len)):
                        return sym
        return None

    def _ttt5_bot_move(board, bot_sym="O", player_sym="X", aggressive=False):
        """Умный бот для 5×5 (4 в ряд).
        aggressive=True — бот за ❌, играет первым, атакует жёстко."""
        empty = [i for i, v in enumerate(board) if not v]
        if not empty:
            return None

        def count_line(sym, positions):
            return sum(1 for p in positions if board[p] == sym)

        def get_lines(idx):
            r, c = divmod(idx, 5)
            lines = []
            for dc in range(-3, 1):
                cols = list(range(c + dc, c + dc + 4))
                if 0 <= cols[0] and cols[-1] < 5:
                    lines.append([r * 5 + cc for cc in cols])
            for dr in range(-3, 1):
                rows = list(range(r + dr, r + dr + 4))
                if 0 <= rows[0] and rows[-1] < 5:
                    lines.append([rr * 5 + c for rr in rows])
            for d4 in range(-3, 1):
                cells_d = [(r + d4 + k) * 5 + (c + d4 + k) for k in range(4)]
                if all(0 <= x // 5 < 5 and 0 <= x % 5 < 5 for x in cells_d):
                    lines.append(cells_d)
            for d4 in range(-3, 1):
                cells_d = [(r + d4 + k) * 5 + (c - d4 - k) for k in range(4)]
                if all(0 <= x // 5 < 5 and 0 <= x % 5 < 5 for x in cells_d):
                    lines.append(cells_d)
            return lines

        def score_move(idx, sym):
            s = 0
            for line in get_lines(idx):
                cnt = count_line(sym, line)
                empty_cnt = sum(1 for p in line if not board[p])
                opp_cnt = sum(1 for p in line if board[p] not in ("", sym))
                if opp_cnt > 0:
                    continue  # линия заблокирована противником
                if cnt == 3 and empty_cnt == 1:
                    s += 10000
                elif cnt == 2 and empty_cnt == 2:
                    s += 200
                elif cnt == 1 and empty_cnt == 3:
                    s += 20
                elif empty_cnt == 4:
                    s += 3
            return s

        def center_bonus(idx):
            """Бонус за близость к центру поля."""
            r, c = divmod(idx, 5)
            return max(0, 3 - abs(r - 2) - abs(c - 2))

        # Немедленная победа бота
        for i in empty:
            board[i] = bot_sym
            if _ttt5_check_winner(board):
                board[i] = ""
                return i
            board[i] = ""

        # Блокировка немедленной победы игрока
        for i in empty:
            board[i] = player_sym
            if _ttt5_check_winner(board):
                board[i] = ""
                return i
            board[i] = ""

        if aggressive:
            # Агрессивный режим: ищем двойную угрозу (форк) — ход создающий 2+ линии из 3
            def threat_count(idx, sym):
                """Количество незаблокированных линий из 3 своих, создаваемых ходом."""
                board[idx] = sym
                cnt = 0
                for line in get_lines(idx):
                    c3 = count_line(sym, line)
                    emp = sum(1 for p in line if not board[p])
                    opp = sum(1 for p in line if board[p] not in ("", sym))
                    if c3 == 3 and emp == 1 and opp == 0:
                        cnt += 1
                board[idx] = ""
                return cnt

            # Ищем ход создающий двойную угрозу (вилку) для бота
            for i in empty:
                if threat_count(i, bot_sym) >= 2:
                    return i

            # Блокируем вилку противника
            for i in empty:
                if threat_count(i, player_sym) >= 2:
                    return i

            # Оценка с агрессивным весом: атака >> защита
            best, best_score = empty[0], -1
            for i in empty:
                atk = score_move(i, bot_sym)
                dfn = score_move(i, player_sym)
                cb = center_bonus(i)
                s = atk * 4 + dfn * 1 + cb * 5
                if s > best_score:
                    best_score, best = s, i
        else:
            # Обычный режим (бот за O): баланс атаки и защиты
            best, best_score = empty[0], -1
            for i in empty:
                s = score_move(i, bot_sym) * 2 + score_move(i, player_sym) + center_bonus(i)
                if s > best_score:
                    best_score, best = s, i

        return best

