    def player_mark_emoji(mark):
        return "❌" if mark == "X" else "⭕"

    def _ttt_render(board, game_id=None, mode="solo"):
        """Рендер доски 3×3. board — list[9] ('X','O','')."""
        symbols = {"X": "❌", "O": "⭕", "": "⬜"}
        rows = []
        for r in range(3):
            row = []
            for c in range(3):
                idx = r * 3 + c
                cell = board[idx]
                if cell == "":
                    if game_id:
                        cb = f"ttt_move_{game_id}_{idx}"
                    else:
                        cb = f"ttt_solo_move_{idx}"
                    row.append(btn(symbols[""], callback_data=cb))
                else:
                    row.append(btn(symbols[cell], callback_data="noop"))
            rows.append(row)
        return rows

    def _ttt_check_winner(board):
        """Возвращает 'X', 'O' или None."""
        wins = [
            (0,1,2),(3,4,5),(6,7,8),
            (0,3,6),(1,4,7),(2,5,8),
            (0,4,8),(2,4,6),
        ]
        for a,b,c in wins:
            if board[a] and board[a] == board[b] == board[c]:
                return board[a]
        return None

    def _ttt_minimax(board, is_maximizing, bot_mark, player_mark, depth=0):
        """Minimax для непобедимого бота."""
        winner = _ttt_check_winner(board)
        if winner == bot_mark:
            return 10 - depth
        if winner == player_mark:
            return depth - 10
        if all(c != "" for c in board):
            return 0
        if is_maximizing:
            best = -100
            for i in range(9):
                if board[i] == "":
                    board[i] = bot_mark
                    score = _ttt_minimax(board, False, bot_mark, player_mark, depth + 1)
                    board[i] = ""
                    best = max(best, score)
            return best
        else:
            best = 100
            for i in range(9):
                if board[i] == "":
                    board[i] = player_mark
                    score = _ttt_minimax(board, True, bot_mark, player_mark, depth + 1)
                    board[i] = ""
                    best = min(best, score)
            return best

    def _ttt_bot_move(board, bot_mark="O", player_mark="X"):
        """Агрессивный бот на основе minimax — невозможно победить."""
        empty = [i for i, v in enumerate(board) if v == ""]
        if not empty:
            return None
        best_score = -100
        best_move = empty[0]
        for i in empty:
            board[i] = bot_mark
            score = _ttt_minimax(board, False, bot_mark, player_mark)
            board[i] = ""
            if score > best_score:
                best_score = score
                best_move = i
        return best_move

