    if d.startswith("sapper_pick_"):
        gdata = ctx.user_data.get(f"sapper_{uid}")
        if not gdata:
            await q.answer("Игра не найдена. Начни заново.", show_alert=True)
            return
        parts_s = d.split("_")
        r_s, c_s = int(parts_s[2]), int(parts_s[3])
        i_s = r_s * SAPPER_COLS + c_s
        cells_s = gdata["cells"]
        revealed_s = set(gdata["revealed"])
        if i_s in revealed_s:
            await q.answer("Уже открыто", show_alert=True)
            return
        # ── Первый клик: гарантируем что не мина — перегенерируем если нужно ──
        if not revealed_s and cells_s[i_s] == -1:
            for _attempt in range(50):
                new_cells = _sapper_new_board()
                if new_cells[i_s] != -1:
                    cells_s = new_cells
                    gdata["cells"] = new_cells
                    break

        def _sapper_flood(cells, revealed, idx):
            """BFS flood fill для 0-клеток."""
            if idx in revealed or cells[idx] != 0:
                revealed.add(idx)
                return
            stack = [idx]
            while stack:
                cur = stack.pop()
                if cur in revealed:
                    continue
                revealed.add(cur)
                if cells[cur] == 0:
                    rr, cc = divmod(cur, SAPPER_COLS)
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr2, nc2 = rr + dr, cc + dc
                            if 0 <= nr2 < SAPPER_ROWS and 0 <= nc2 < SAPPER_COLS:
                                nidx = nr2 * SAPPER_COLS + nc2
                                if nidx not in revealed:
                                    stack.append(nidx)

        if cells_s[i_s] == -1:
            # Мина!
            revealed_s.add(i_s)
            board_rows = _sapper_render(cells_s, revealed_s, game_over=True, won=False)
            board_rows.append([btn(t("btn_play_again", f), callback_data="sapper_start"),
                               btn("◀️ Назад", callback_data="menu_games")])
            is_on_cd_s = gdata.get("on_cd", False)
            f["last_sapper"] = time.time()  # Всегда обновляем КД
            add_xp(f, 0)
            await db_save(f)
            del ctx.user_data[f"sapper_{uid}"]
            try:
                await q.message.edit_text(
                    f"💥 <b>БУМ! Мина!</b>\n\nТы открыл {len(gdata['revealed'])} клеток.\n{_E_XP} +5 XP за попытку",
                    parse_mode=ParseMode.HTML,
                    reply_markup=InlineKeyboardMarkup(board_rows),
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
        else:
            _sapper_flood(cells_s, revealed_s, i_s)
            total_safe = sum(1 for v in cells_s if v != -1)
            gdata["revealed"] = list(revealed_s)
            is_on_cd_s = gdata.get("on_cd", False)
            if len(revealed_s) == total_safe:
                # Победа!
                prize = total_safe * 1 if not is_on_cd_s else 0
                if prize:
                    f["coins"] += prize
                f["last_sapper"] = time.time()  # Всегда обновляем КД
