    if payload == "revive_stars_instant":
        f["alive"]   = 1
        f["health"]  = 100
        f["hunger"]  = 100
        f["happiness"] = 100
        f["death_reason"] = ""
        f["trial_active"] = 0
        f["stars_spent"] = f.get("stars_spent", 0) + stars_paid
        await db_save(f)
        await _pay_ref_commission(user.id, stars_paid)
        await purchase_log(user.id, "revive_instant", stars_paid)
