    if payload.startswith("subscription_"):
        # payload = "subscription_nanny_30" or "subscription_worker_30"
        parts = payload.split("_")
        sub_type_str = parts[1] if len(parts) > 1 else "nanny"
        days = int(parts[2]) if len(parts) > 2 else 30
        sub_type = 1 if sub_type_str == "nanny" else 2
        # Продление: складываем дни если подписка ещё активна
        now_sp = time.time()
        current_until = f.get("subscription_until", 0)
        base = max(now_sp, current_until)
        f["subscription_until"] = base + days * 86400
        # Трудяга включает Няню
        if sub_type == 2 or f.get("subscription_type", 0) < sub_type:
            f["subscription_type"] = sub_type
        f["subscription_auto"] = 1
        # Сбрасываем таймер отчёта — первый придёт вечером следующего дня
        if sub_type == 2 and f.get("last_worker_report", 0) == 0:
            f["last_worker_report"] = time.time()
        f["stars_spent"] = f.get("stars_spent", 0) + stars_paid
        await db_save(f)
        await _pay_ref_commission(user.id, stars_paid)
