# Маппинг типа казино → эмодзи и название (для режима "брошу сам")
CASINO_EMOJI_MAP = {
    "dice": "🎲",
    "dart": "🎯",
    "basketball": "🏀",
}
CASINO_EMOJI_MAP_NAMES = {
    "dice": "Кубик",
    "dart": "Дартс",
    "basketball": "Баскетбол",
}

async def _sync_user_info(user) -> bool:
    """Обновляет username и first_name в БД если изменились. Возвращает True если было изменение."""
    if not user:
        return False
    f = await db_get(user.id)
    if not f:
        return False
    new_un  = user.username   or ""
    new_fn  = user.first_name or f.get("first_name", "")
    if f.get("username") != new_un or f.get("first_name") != new_fn:
        f["username"]   = new_un
        f["first_name"] = new_fn
        await db_save(f)
        return True
    return False


async def cmd_report(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Позвать администраторов чата — /report [причина], лучше ответом на сообщение.

    Раньше этот разбор лежал внутри on_message, куда команды не доходят:
    хендлер сообщений стоит с фильтром ~filters.COMMAND. На месте команды
    была заглушка `lambda u, c: None`, а PTB результат хендлера ожидает —
    поэтому каждый /report заканчивался TypeError и молчанием.
    """
    user = update.effective_user
    if not user or not update.message:
        return
    if not is_group(update):
        await update.message.reply_text("Команда работает в групповом чате.")
        return

    gid = update.effective_chat.id
    reason = (update.message.text or "")[len("/report"):].strip() or "нарушение"
    reported_user = None
    if update.message.reply_to_message:
        reported_user = update.message.reply_to_message.from_user
    reporter_name = user.first_name or "Игрок"
    chat_title = update.effective_chat.title or str(gid)
    # Находим всех администраторов чата
    try:
        admins = await ctx.bot.get_chat_administrators(gid)
        admin_ids = [a.user.id for a in admins if not a.user.is_bot]
    except Exception:
        admin_ids = []
    report_txt = (
        f"🚨 <b>Репорт из чата {he(chat_title)}</b>\n\n"
        f"От: {he(reporter_name)}"
        + (f" (@{user.username})" if user.username else "") + "\n"
        + (f"На: <b>{he(reported_user.first_name)}</b>" if reported_user else "")
        + f"\nПричина: {he(reason)}"
    )
    sent = False
    for aid in admin_ids:
        try:
            await ctx.bot.send_message(aid, report_txt, parse_mode=ParseMode.HTML)
            sent = True
        except (BadRequest, Forbidden, TimedOut):
            pass
    try:
        resp = await update.message.reply_text(
            "Позвал администраторов." if sent else
            "Некого позвать — администраторы чата не найдены.",
        )
        await asyncio.sleep(5)
        await resp.delete()
        await update.message.delete()
    except (BadRequest, Forbidden, TimedOut):
        pass


async def on_message(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    user = update.effective_user
    text = (update.message.text or "").strip()
    # Определяем ключ ввода желания заранее — используется в нескольких местах функции
    _wish_key = f"casino_wish_input_{user.id}" if user else None

    if user and not is_group(update):
        bet_pending = ctx.bot_data.get("bet_pending", {}).get(user.id)
        if bet_pending and time.time() - bet_pending.get("ts", 0) < 120:
            if text.isdigit() and int(text) > 0:
                ctx.bot_data["bet_pending"].pop(user.id, None)
                amount   = int(text)
                duel_id  = bet_pending["duel_id"]
                side     = bet_pending["side"]
                sk_id_bp = 0
                async with aiosqlite.connect(DB_PATH) as _bpdb:
                    async with _bpdb.execute(
                        "SELECT skirmish_id FROM skirmish_duels WHERE id=?", (duel_id,)
                    ) as _bpc:
                        _bpr = await _bpc.fetchone()
                    if _bpr:
                        sk_id_bp = _bpr[0]
                result = await _bet_place(duel_id, sk_id_bp, user.id, side, amount)
                if result == "ok":
                    pool    = await _bet_get_pool(duel_id)
                    odds    = _bet_calc_odds(pool, side)
                    win_est = int(amount * odds)
                    side_ru = "⚔️ нападение" if side == "attacker" else "🛡️ защиту"
                    f_bal   = await db_get(user.id)
                    bal     = f_bal.get("coins", 0) if f_bal else 0
                    await update.message.reply_text(
                        f"{_E_CHECK} <b>Ставка принята!</b>\n"
                        f"{amount}{_E_COIN} на {side_ru} ×{odds}\n"
                        f"Потенциальный выигрыш: <b>{win_est}{_E_COIN}</b>\n"
                        f"Баланс: <b>{bal}{_E_COIN}</b>",
                        parse_mode=ParseMode.HTML,
                    )
                elif result == "no_coins":
                    f_bal = await db_get(user.id)
                    bal   = f_bal.get("coins", 0) if f_bal else 0
                    await update.message.reply_text(
                        f"{_E_CROSS} Недостаточно монет. У тебя <b>{bal}{_E_COIN}</b>.", parse_mode=ParseMode.HTML,
                    )
                elif result == "closed":
                    await update.message.reply_text("⏰ Ставки уже закрыты!")
                else:
                    await update.message.reply_text("Ты уже поставил на этот бой")
                return
            elif text and not text.isdigit():
                await update.message.reply_text("Введи число — сумму ставки в монетах 🪙")
                return

    # ── Обработка ответа на капчу (только в ЛС) ─────────────────────────────
    if user and not is_group(update) and is_captcha_pending(user.id):
        entry = _captcha_pending.get(user.id, {})
        if text.isdigit() and int(text) == entry.get("answer"):
            _captcha_pending.pop(user.id, None)
            _action_log.pop(user.id, None)
            await update.message.reply_text(f"{_E_CHECK} Отлично! Проверка пройдена. Можешь играть дальше {_E_FROG}", parse_mode=ParseMode.HTML)
            if ADMIN_IDS:
                try:
                    await ctx.bot.send_message(
                        ADMIN_IDS[0],
                        f"✅ uid <code>{user.id}</code> (@{user.username or '—'}) прошёл капчу.",
                        parse_mode=ParseMode.HTML,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass
        else:
            await update.message.reply_text(
                f"{_E_CROSS} Неверно. Попробуй ещё раз:\n\n"
                f"<b>{entry.get('a', '?')} + {entry.get('b', '?')} = ?</b>",
                parse_mode=ParseMode.HTML,
            )
        return

    # ── Ответ на капчу комара (только в ЛС) ──────────────────────────────────
    if user and not is_group(update) and user.id in _MOSQUITO_CAPTCHA:
        mc = _MOSQUITO_CAPTCHA.get(user.id, {})
        if time.time() > mc.get("expires", 0):
            _MOSQUITO_CAPTCHA.pop(user.id, None)
            await update.message.reply_text("⏰ Время на ответ истекло, результат комара не засчитан.")
            return
        if text.isdigit() and int(text) == mc.get("answer"):
            _MOSQUITO_CAPTCHA.pop(user.id, None)
            # Засчитываем поимку — начисляем награду
            uid_mc = user.id
            f_mc = await db_get(uid_mc)
            if f_mc:
                f_mc["coins"] += mc["reward"]
                add_xp(f_mc, 30)
                f_mc["total_mosquitoes"] = f_mc.get("total_mosquitoes", 0) + 1
                await levelup(f_mc, ctx.bot)
                await db_save(f_mc)
                await ach_check(f_mc, ctx.bot)
            pos_emoji = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣"][min(mc["pos"], 4)]
            await update.message.reply_text(
                f"{_E_CHECK} Правильно! {pos_emoji} Поимка засчитана — <b>+{mc['reward']}{_E_COIN} +30XP</b>",
                parse_mode=ParseMode.HTML,
            )
        else:
            await update.message.reply_text(
                f"{_E_CROSS} Неверно. Попробуй ещё раз:\n\n"
                f"<b>{mc.get('a', '?')} + {mc.get('b', '?')} = ?</b>",
                parse_mode=ParseMode.HTML,
            )
        return
    if user and is_group(update):
        _gid_track = update.effective_chat.id
        asyncio.create_task(update_chat_activity(_gid_track))

    # ── Проверка локального чат-бана ─────────────────────
    if user and is_group(update):
        gid = update.effective_chat.id
        if await is_chat_banned(gid, user.id):
            return  # заблокирован в этом чате — игнорируем
        # ── Проверка мута ──────────────────────────────
        if await is_chat_muted(gid, user.id):
            # Мьют: команды /help и /frog разрешены, остальные блокируем
            if text.startswith("/") and not any(text.startswith(f"/{c}") for c in ("help", "frog", "start")):
                try:
                    await update.message.reply_text("🔇 Вы заморожены в этом чате и не можете использовать команды бота.")
                except (BadRequest, Forbidden, TimedOut):
                    pass
                return

    # ── Проверка чёрного списка команд чата ──────────────
    if user and is_group(update) and text.startswith("/"):
        gid = update.effective_chat.id
        s_check = await get_chat_settings(gid)
        bl = json.loads(s_check.get("commands_blacklist", "[]") or "[]")
        if bl:
            cmd = text.split()[0].split("@")[0].lstrip("/").lower()
            if cmd in bl:
                try:
                    await update.message.delete()
                except Exception as _e:
                    logger.exception("подавлено исключение: %s", _e)
                return

    # ── Фильтр мата ──────────────────────────────────────
    _msg_text_for_filter = (update.message.text or update.message.caption or "").strip()
    if user and is_group(update) and _msg_text_for_filter:
        gid = update.effective_chat.id
        _s_prof = await get_chat_settings(gid)
        if _s_prof.get("profanity_filter", 0):
            # ── Нормализация текста для обхода фильтров ──────────────────
            def _normalize_ru(s: str) -> str:
                """Приводим латиницу → кириллицу, цифры → буквы, убираем пробелы."""
                # Латиница → кириллица
                lat2cyr = {
                    'a': 'а', 'e': 'е', 'o': 'о', 'p': 'р', 'c': 'с',
                    'x': 'х', 'y': 'у', 'k': 'к', 'h': 'н', 'm': 'м',
                    'b': 'б', 't': 'т', 'i': 'и',
                    'A': 'а', 'E': 'е', 'O': 'о', 'P': 'р', 'C': 'с',
                    'X': 'х', 'Y': 'у', 'K': 'к', 'H': 'н', 'M': 'м',
                    'B': 'б', 'T': 'т', 'I': 'и',
                }
                # Цифры → похожие буквы
                dig2cyr = {'0': 'о', '3': 'з', '4': 'ч', '1': 'и', '6': 'б'}
                out = []
                for ch in s.lower():
                    if ch in lat2cyr:
                        out.append(lat2cyr[ch])
                    elif ch in dig2cyr:
                        out.append(dig2cyr[ch])
                    elif ch.isalpha() or ch in ('ё',):
                        out.append(ch)
                    # пробелы и спецсимволы между буквами — убираем
                return ''.join(out)

            _BAD_ROOTS = [
                # х*й и формы
                "хуй","хуя","хуе","хуи","хуё","хуем","хуев","хуйн","хуйл",
                "нахуй","нахуе","нахуя","похуй","похуе","захуй","ёхуй",
                "охуен","охуел","охуеть","ёбаный","ёбан","ебан",
                # хер и формы (мягкие, но часто используются матерно)
                "хера","хером","хере","нахер","похер","захер",
                # п*зда
                "пизда","пизде","пизды","пиздец","пиздит","пиздят","пиздёж",
                "пиздюк","пиздатый","распизд","отпизд","запизд","пиздобол",
                # е*ать и формы
                "ебать","ебёт","ебут","ебал","ебла","ёбать","ёбут","ёбал",
                "ебись","ебитесь","заебал","заебать","заебало","заебись",
                "выебать","выёбывать","уебать","уёбывать","отъебись","отебись",
                "проёбать","проебать","доебать","поебать","наебать",
                "выёб","залупа","елда",
                # б*ядь
                "блядь","блядей","блядин","бляди","блядс","бляд","шлюха","шлюхи",
                # «бля» — усечённые формы (самый частый обход)
                "бля","блять","блятина","блянах",
                # с*ка
                "сука","суки","сукам","сученыш","сучк","сучара",
                # м*дак и похожие
                "мудак","мудаки","мудило","мудила","мудозвон",
                # п*дор и похожие
                "пидор","пидар","пидорас","педик","пидорок",
                # д*рак и грубые
                "ублюдок","ублюдки","выродок","тварь","твари",
                # матерные частицы
                "хуесос","ёбтвоюмать","ёптвою","ёпрст","ёпт","ёп ",
                # дополнительные обходы
                "еблан","ебло","ёблан","заебло","залупин","залупу",
                "пиздануть","пиздануло","пиздун","пиздунья",
                "ёбнуть","ёбнул","ёбнулся","ёбнутый",
                "еботня","еботня","разъеб","разъёб",
            ]

            _tl_orig = _msg_text_for_filter.lower()
            _tl_norm = _normalize_ru(_msg_text_for_filter)

            # Дополнительно — проверяем с удалением повторяющихся символов
            def _collapse(s: str) -> str:
                res = []
                for ch in s:
                    if not res or res[-1] != ch:
                        res.append(ch)
                return ''.join(res)

            _tl_collapsed = _collapse(_tl_norm)

            _is_bad = any(
                w in _tl_orig or w in _tl_norm or w in _tl_collapsed
                for w in _BAD_ROOTS
            )
            if _is_bad:
                try:
                    await update.message.delete()
                except Exception as _e:
                    logger.exception("подавлено исключение: %s", _e)
                if _s_prof.get("profanity_warn", 1):
                    # Прямая запись предупреждения без fake update
                    WARN_LIMIT_PROF = 3
                    async with aiosqlite.connect(DB_PATH) as _wdb:
                        await _wdb.execute(
                            "INSERT INTO chat_warnings(chat_id, user_id, reason, warned_at, warned_by) VALUES(?,?,?,?,?)",
                            (gid, user.id, "нецензурная лексика", time.time(), 0),
                        )
                        await _wdb.commit()
                        async with _wdb.execute(
                            "SELECT COUNT(*) FROM chat_warnings WHERE chat_id=? AND user_id=?",
                            (gid, user.id),
                        ) as _wc:
                            warn_count_prof = (await _wc.fetchone())[0]
                    _prof_name = he(user.first_name)
                    if warn_count_prof >= WARN_LIMIT_PROF:
                        async with aiosqlite.connect(DB_PATH) as _bdb:
                            await _bdb.execute(
                                """INSERT INTO chat_bans(chat_id, user_id, reason, banned_at, expires_at, banned_by)
                                   VALUES(?,?,?,?,0,?)
                                   ON CONFLICT(chat_id, user_id) DO UPDATE SET reason=excluded.reason,
                                   banned_at=excluded.banned_at, expires_at=0, banned_by=excluded.banned_by""",
                                (gid, user.id, f"3 предупреждения (нецензурная лексика)", time.time(), 0),
                            )
                            await _bdb.commit()
                        try:
                            await ctx.bot.send_message(
                                gid,
                                f"⚠️ <b>{_prof_name}</b> получил предупреждение {warn_count_prof}/{WARN_LIMIT_PROF}.\n"
                                f"{_E_BAN} <b>Автоматический бан</b> — превышен лимит предупреждений!",
                                parse_mode=ParseMode.HTML,
                            )
                        except (BadRequest, Forbidden, TimedOut):
                            pass
                    else:
                        try:
                            await ctx.bot.send_message(
                                gid,
                                f"⚠️ <b>{_prof_name}</b> получил предупреждение "
                                f"<b>{warn_count_prof}/{WARN_LIMIT_PROF}</b>.\n"
                                f"Причина: нецензурная лексика",
                                parse_mode=ParseMode.HTML,
                            )
                        except (BadRequest, Forbidden, TimedOut):
                            pass

    # ── Обновляем last_seen ──────────────────────────
    if user:
        _f_seen = await db_get(user.id)
        if _f_seen:
            _now_s = time.time()
            if _now_s - _f_seen.get("last_seen", 0) > 60:
                _f_seen["last_seen"] = _now_s
                await db_save(_f_seen)

    # ── Обработка ввода желаемой суммы для режима желания казино ─────────
    # ── Рынок: ввод цены ─────────────────────────────────────────────────────
    _market_sell_key = f"market_sell_{user.id}" if user else None
    if _market_sell_key and _market_sell_key in ctx.user_data and not is_group(update):
        _ms = ctx.user_data.get(_market_sell_key, {})
        try:
            _price_m = int(text.strip())
            if _price_m < 10 or _price_m > 50000:
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ Цена от 10 до 50 000🪙. Введи число:")
            return
        _skin_m = _ms.get("skin", "")
        # Проверяем что облик ещё есть
        _coll_m = await db_coll(user.id)
        _f_m = await db_get(user.id)
        _equipped_m = _f_m.get("skin", "") if _f_m else ""
        _qty_m = await db_coll_qty(user.id)
        _skin_qty = _qty_m.get(_skin_m, 0)
        if _skin_qty == 0 or (_skin_qty == 1 and _skin_m == _equipped_m):
            await update.message.reply_text("❌ Этот облик недоступен для продажи (экипирован или отсутствует).")
            ctx.user_data.pop(_market_sell_key, None)
            return
        # Снимаем облик из коллекции и создаём листинг
        await db_remove_skin(user.id, _skin_m)
        _lid = await market_list_skin(user.id, _skin_m, _price_m)
        ctx.user_data.pop(_market_sell_key, None)
        _commission_show = max(1, int(_price_m * 0.10))
        await update.message.reply_text(
            f"{_E_CHECK} <b>Лот #{_lid} создан!</b>\n\n"
            f"{pemoji(_skin_m)} <b>{_skin_m}</b>\n"
            f"Цена: <b>{_price_m}{_E_COIN}</b>\n"
            f"При продаже получишь: <b>{_price_m - _commission_show}{_E_COIN}</b> (комиссия {_commission_show}{_E_COIN})\n\n"
            f"<i>Облик снят из твоей коллекции до продажи или отмены.</i>",
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                btn("📋 Мои лоты", callback_data="market_my"),
                btn("🏪 Рынок", callback_data="market_main"),
            ]]),
        )
        return
    # Проверяем режим «желание»
    if _wish_key and _wish_key in ctx.user_data and not is_group(update):
        _wish_data = ctx.user_data.get(_wish_key)
        raw_wish = text.strip()
        try:
            wish_target_input = int(raw_wish)
            if wish_target_input < 1:
                raise ValueError
        except ValueError:
            await update.message.reply_text(f"{_E_CROSS} Введи целое число больше 0. Например: <code>500</code>", parse_mode=ParseMode.HTML)
            return
        _wish_stake = _wish_data["stake"]
        # Желаемая сумма — это ИТОГОВЫЙ возврат при победе (ставка + прибыль)
        # Минимум: target > stake (иначе нет смысла рисковать)
        if wish_target_input <= _wish_stake:
            await update.message.reply_text(
                f"{_E_CROSS} Желаемая сумма должна быть больше ставки ({_wish_stake}{_E_COIN}).\n"
                f"Например: <code>{_wish_stake * 2}</code> — получишь ×2 от ставки.",
                parse_mode=ParseMode.HTML,
            )
            return
        MAX_WISH = 1_000_000
        if wish_target_input > MAX_WISH:
            await update.message.reply_text(f"{_E_CROSS} Максимально допустимая сумма: {MAX_WISH:,}{_E_COIN}", parse_mode=ParseMode.HTML)
            return
        ctx.user_data.pop(_wish_key, None)
        _fw = await db_get(user.id)
        if not _fw:
            return
        if _fw["coins"] < _wish_stake:
            await update.message.reply_text(f"{_E_CROSS} Не хватает монет! У тебя {he(_fw['coins'])}{_E_COIN}", parse_mode=ParseMode.HTML)
            return
        # Расчёт шанса: честный шанс = stake / target (например 50→100: 50%)
        # Фактический шанс с учётом RTP 80%: P_actual = (stake / target) × 0.80
        _fair_pct_wi = _wish_stake / wish_target_input * 100
        actual_chance_wi = (_wish_stake / wish_target_input) * 0.80
        profit_wi = wish_target_input - _wish_stake
        # Списываем ставку
        _fw["coins"] -= _wish_stake
        _fw["coins_spent"] = _fw.get("coins_spent", 0) + _wish_stake
        _fw["total_casino"] = _fw.get("total_casino", 0) + 1
        won_wi = random.random() < actual_chance_wi
        if won_wi:
            _fw["coins"] += wish_target_input  # получаем target (включая ставку)
            _fw["total_casino_wins"] = _fw.get("total_casino_wins", 0) + 1
            _fw["casino_win_streak"] = _fw.get("casino_win_streak", 0) + 1
        else:
            _fw["casino_win_streak"] = 0
            asyncio.create_task(jackpot_add(max(1, _wish_stake // 10)))
        await db_save(_fw)
        asyncio.create_task(log_game(
            user.id, "casino_wish", _wish_stake,
            wish_target_input if won_wi else 0,
            "win" if won_wi else "loss",
            {"target": wish_target_input, "profit": profit_wi, "displayed_pct": round(_fair_pct_wi, 1)},
        ))
        await quest_update(user.id, "casino")
        asyncio.create_task(update_trial_progress(user.id, "casino", bot=ctx.bot))
        if won_wi:
            await quest_update(user.id, "casino_win")
