    # ── Обработка пароля /adminsecretgift ────────────────────────────────
    _agp_key = f"admingift_pass_pending_{user.id}" if user else None
    if _agp_key and ctx.user_data.get(_agp_key) and not is_group(update):
        ctx.user_data.pop(_agp_key, None)
        if text.strip() == SECRET_GIFT_ADMIN_PASS:
            if not SECRET_GIFTS:
                await update.message.reply_text(
                    "😔 <b>Секретный магазин пуст.</b>\n<i>Подарки пока не добавлены.</i>",
                    parse_mode=ParseMode.HTML,
                )
                return
            lines = "\n".join(
                f"{g['emoji']} <b>{g['name']}</b> — 🆓 БЕСПЛАТНО"
                for g in SECRET_GIFTS
            )
