# ⏰ ФОНОВЫЕ ЗАДАЧИ
# ══════════════════════════════════════════
async def job_events(ctx: ContextTypes.DEFAULT_TYPE):
    """
    Случайные интерактивные события для живых лягушек.
    Каждый запуск (раз в 4ч) — событие получают ВСЕ у кого прошёл кулдаун (8ч).
    Кулдаун на повтор у одного игрока — 6ч (INTERACTIVE_EVENT_COOLDOWN).
    """
    frogs = await db_all_alive()
    random.shuffle(frogs)
    updated_frogs = []

    for f in frogs:
        # Базовый кулдаун — 8 часов
        if time.time() - f.get("last_event", 0) < 8 * 3600:
            continue

        # Любопытная: +10% шанс получить событие (обычно 100%, но меняет кулдаун)
        # Туман: события приходят чаще (event_chance_mult) — уменьшаем кулдаун
        pers_ev  = PERSONALITIES.get(f.get("personality", ""), {})
        weather_ev = _get_today_weather()
        ev_bonus = pers_ev.get("event_chance_bonus", 0.0)
        ev_weather_mult = weather_ev.get("event_chance_mult", 1.0)

        # При тумане и Любопытной — дополнительные события с шансом
        extra_chance = ev_bonus + (ev_weather_mult - 1.0) * 0.5
        if extra_chance > 0 and random.random() < extra_chance:
            # Бонусное событие раньше обычного (игнорируем кулдаун)
            pass  # уже прошли проверку выше — просто отправляем

        sent = await send_random_interactive_event(f, ctx.bot)
        if sent:
            f["last_event"] = time.time()
            f["last_interactive_event"] = time.time()
            updated_frogs.append(f)

        await asyncio.sleep(0.05)

    if updated_frogs:
        async with aiosqlite.connect(DB_PATH) as db:
            for f in updated_frogs:
                f_clean = {k: v for k, v in f.items() if not k.startswith("_")}
                keys = list(f_clean.keys())
                ph  = ",".join(["?"] * len(keys))
                upd = ",".join([f"{k}=excluded.{k}" for k in keys])
                await db.execute(
                    f"INSERT INTO frogs ({','.join(keys)}) VALUES ({ph}) "
                    f"ON CONFLICT(user_id) DO UPDATE SET {upd}",
                    list(f_clean.values()),
                )
            await db.commit()
    logger.info("job_events: отправлено %d событий", len(updated_frogs))


