# ── Хелперы ───────────────────────────────────────────────────────────────────

async def legend_active() -> dict | None:
    """Возвращает активную легенду или None."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM legend_events WHERE finished=0 ORDER BY id DESC LIMIT 1"
        ) as c:
            row = await c.fetchone()
    if not row:
        return None
    d = dict(row)
    d["goals"]    = json.loads(d["goals"])
    d["progress"] = json.loads(d["progress"])
    return d


async def legend_track(uid: int, action: str, amount: int = 1, bot=None):
    """
    Добавляет вклад игрока в активную легенду.
    Если после обновления все цели выполнены — сразу финишируем.
    """
    leg = await legend_active()
    if not leg:
        return
    if action not in leg["goals"]:
        return
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT INTO legend_contributions(legend_id, user_id, action, amount) "
            "VALUES(?,?,?,?) ON CONFLICT(legend_id,user_id,action) "
            "DO UPDATE SET amount=amount+?",
            (leg["id"], uid, action, amount, amount),
        )
        prog = leg["progress"]
        prog[action] = prog.get(action, 0) + amount
        await db.execute(
            "UPDATE legend_events SET progress=? WHERE id=?",
            (json.dumps(prog), leg["id"]),
        )
        await db.commit()

    # Проверяем — если все цели выполнены, завершаем немедленно
    goals = leg["goals"]
    all_done = all(prog.get(a, 0) >= g for a, g in goals.items())
    if all_done and bot is not None:
        # Перечитываем актуальные данные и финишируем
        leg_fresh = await legend_active()
        if leg_fresh:
            asyncio.create_task(_legend_finish(bot, leg_fresh))


def _legend_progress_bar(current: int, goal: int, width: int = 10) -> str:
    pct   = min(current / goal, 1.0)
    filled = int(pct * width)
    bar   = "<code>" + "█" * filled + "░" * (width - filled) + "</code>"
    return f"{bar} {current}/{goal} ({int(pct*100)}%)"


def _legend_build_text(leg: dict) -> str:
    """Формирует текст анонса/обновления легенды."""
    goals    = leg["goals"]
    progress = leg["progress"]
    ends_dt  = datetime.fromtimestamp(leg["ends_at"] + 3*3600, timezone.utc).strftime("%d.%m в %H:%M")

    lines = [
        f"{leg['emoji']} <b>Болотная Легенда</b>\n",
        f"<b>{leg['title']}</b>\n",
        f"{leg['story']}\n",
        f"<b>Прогресс болота:</b>",
    ]
    all_done = True
    for action, goal in goals.items():
        cur  = progress.get(action, 0)
        icon, label = _LEGEND_ACTION_LABELS.get(action, ("▫️", action))
        bar  = _legend_progress_bar(cur, goal)
        lines.append(f"{icon} {label}: {bar}")
        if cur < goal:
            all_done = False

    if all_done:
        lines.append(f"\n{_E_CHECK} <b>Все цели выполнены!</b> Ждём финала...")
    else:
        lines.append(f"\n⏳ <b>До финала:</b> {ends_dt} МСК")

    return "\n".join(lines)


async def _legend_announce(bot, leg: dict, text: str = None) -> int | None:
    """Публикует или редактирует анонс легенды в CHAT_ID. Возвращает msg_id."""
    msg_text = text or _legend_build_text(leg)
    try:
        if leg.get("announce_msg_id"):
            await bot.edit_message_text(
                chat_id=CHAT_ID, message_id=leg["announce_msg_id"],
                text=msg_text, parse_mode=ParseMode.HTML,
            )
            return leg["announce_msg_id"]
        else:
            msg = await bot.send_message(CHAT_ID, msg_text, parse_mode=ParseMode.HTML)
            return msg.message_id
    except Exception as _e:
        logger.warning("legend_announce: %s", _e)
        return None


async def _legend_start(bot, legend_data: dict | None = None) -> dict | None:
    """
    Запускает новую легенду. Если legend_data=None — берёт случайную из LEGEND_POOL.
    Постит анонс в чат и рассылает ЛС всем живым игрокам.
    """
    # Закрываем незавершённые
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("UPDATE legend_events SET finished=1 WHERE finished=0")
        await db.commit()

    now    = time.time()
    dt_now = datetime.fromtimestamp(now, timezone.utc)
    days_to_sunday = (6 - dt_now.weekday()) % 7 or 7
    ends_dt = dt_now.replace(hour=18, minute=0, second=0, microsecond=0)
    ends_dt = ends_dt + __import__("datetime").timedelta(days=days_to_sunday)
    ends_at = ends_dt.timestamp()

    if legend_data is None:
        legend_data = random.choice(LEGEND_POOL)

    async with aiosqlite.connect(DB_PATH) as db:
        cur = await db.execute(
            "INSERT INTO legend_events(title,story,emoji,goals,progress,started_at,ends_at) "
            "VALUES(?,?,?,?,?,?,?)",
            (
                legend_data["title"], legend_data["story"], legend_data["emoji"],
                json.dumps(legend_data["goals"]), json.dumps({}), now, ends_at,
            ),
        )
        leg_id = cur.lastrowid
        await db.commit()

    leg = await legend_active()
    if not leg:
        return None

    # Анонс в общий чат
    msg_id = await _legend_announce(bot, leg)
    if msg_id:
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE legend_events SET announce_msg_id=? WHERE id=?",
                (msg_id, leg_id),
            )
            await db.commit()

    # ── ЛС рассылка всем живым игрокам ───────────────────────────────────────
    ends_dt_msk = datetime.fromtimestamp(ends_at + 3*3600, timezone.utc).strftime("%d.%m в %H:%M")
    goals_lines = []
    for action, goal in legend_data["goals"].items():
        icon, label = _LEGEND_ACTION_LABELS.get(action, ("▫️", action))
        goals_lines.append(f"{icon} {label}: <b>{goal}</b>")

    dm_text = (
        f"{legend_data['emoji']} <b>Болотная Легенда началась!</b>\n\n"
        f"<b>{legend_data['title']}</b>\n\n"
        f"{legend_data['story']}\n\n"
        f"<b>Цели болота:</b>\n" + "\n".join(goals_lines) + "\n\n"
        f"⏳ Дедлайн: <b>{ends_dt_msk} МСК</b>\n\n"
        f"<i>Каждое кормление, купание, игра — вклад в общую победу!\n"
        f"Смотри прогресс: /frog → 📜 Легенда</i>"
    )

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT user_id FROM frogs WHERE alive=1") as c:
            all_uids = [r[0] for r in await c.fetchall()]

    for uid_dm in all_uids:
        try:
            await bot.send_message(uid_dm, dm_text, parse_mode=ParseMode.HTML)
        except (Forbidden, BadRequest):
            pass
        except (BadRequest, Forbidden, TimedOut):
            pass
        await asyncio.sleep(0.05)

    logger.info("legend_start: id=%s title=%s players_notified=%s", leg_id, legend_data["title"], len(all_uids))
    return leg


async def _legend_finish(bot, leg: dict):
    """Завершает легенду, считает результат, рассылает награды с тиерами топ-участников."""
    goals    = leg["goals"]
    progress = leg["progress"]
    win      = all(progress.get(a, 0) >= g for a, g in goals.items())
    leg_data = next((l for l in LEGEND_POOL if l["title"] == leg["title"]), None)

    win_coins  = (leg_data or {}).get("win_coins", 150)
    win_xp     = (leg_data or {}).get("win_xp",    80)
    lose_coins = max(win_coins // 5, 30)

    # Помечаем как завершённую
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE legend_events SET finished=1, win=? WHERE id=?",
            (1 if win else 0, leg["id"]),
        )
        await db.commit()

    # Все участники с их вкладом, отсортированные по убыванию
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT user_id, SUM(amount) as total FROM legend_contributions "
            "WHERE legend_id=? GROUP BY user_id ORDER BY total DESC",
            (leg["id"],),
        ) as c:
            contrib_rows = await c.fetchall()

    all_uids   = [r[0] for r in contrib_rows]
    participants = len(all_uids)

    # Тиеры наград при победе (от базовой суммы win_coins)
    # Топ-1: 1000, топ-2: 600, топ-3: 400, топ-4..10: 200, остальные: base
    TOP_REWARDS = {0: 1000, 1: 600, 2: 400}
    TOP_RUNNER_UP = 200   # места 4–10
    TOP_RUNNER_UP_MAX = 10

    # Начисляем награды
    top_lines = []
    medals    = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]

    for i, (uid_r, total) in enumerate(contrib_rows):
        try:
            f = await db_get(uid_r)
            if not f:
                continue

            if win:
                if i in TOP_REWARDS:
                    coins_r = TOP_REWARDS[i]
                elif i < TOP_RUNNER_UP_MAX:
                    coins_r = TOP_RUNNER_UP
                else:
                    coins_r = win_coins
                f["coins"] = f.get("coins", 0) + coins_r
                add_xp(f, win_xp)
            else:
                coins_r = lose_coins
                f["coins"] = f.get("coins", 0) + coins_r

            await db_save(f)

            # Строка для топ-10
            if i < 10:
                name = fname(f)
                if win:
                    top_lines.append(
                        f"{medals[i]} <b>{he(name)}</b> — {total} действий → <b>+{coins_r}{_E_COIN}</b>"
                    )
                else:
                    top_lines.append(f"{medals[i]} {he(name)} — {total} действий")

        except Exception as _e:
            logger.warning("legend_reward uid=%s: %s", uid_r, _e)

    result_txt = (leg_data or {}).get("win_text" if win else "lose_text", "")

    reward_desc = (
        f"🥇 +1000🪙 🥈 +600🪙 🥉 +400🪙\n"
        f"4–10 место: +200🪙 Остальные: +{win_coins}🪙"
        if win else f"Утешительная: +{lose_coins}🪙"
    )

    final_text = (
        f"{leg['emoji']} <b>Болотная Легенда завершена!</b>\n\n"
        f"<b>{leg['title']}</b>\n\n"
        f"{'🎉' if win else '😔'} {result_txt}\n\n"
        f"{_E_USERS} Участников: <b>{participants}</b>\n"
        f"{_E_XP} XP победителям: +{win_xp}\n"
        f"{reward_desc}\n\n"
        + ("<b>Топ участников:</b>\n" + "\n".join(top_lines) if top_lines else "")
    )

    await _legend_announce(bot, leg, text=final_text)

    # ЛС рассылка всем участникам о финале с персональной наградой
    for i, (uid_r, _) in enumerate(contrib_rows):
        try:
            if win:
                personal_reward = TOP_REWARDS.get(i, TOP_RUNNER_UP if i < TOP_RUNNER_UP_MAX else win_coins)
            else:
                personal_reward = lose_coins
            place_str = f"Место: {medals[i]}" if i < 10 else f"Место: {i+1}"
            personal_text = (
                final_text +
                f"\n\n{place_str}\n💰 Твоя награда: <b>+{personal_reward}{_E_COIN}</b>"
            )
            await bot.send_message(uid_r, personal_text, parse_mode=ParseMode.HTML)
        except (Forbidden, BadRequest):
            pass
        except (BadRequest, Forbidden, TimedOut):
            pass
        # Достижения: все участники победившей легенды + топ-1 вкладчик
        if win:
            try:
                frog_r = await db_get(uid_r)
                if frog_r:
                    frog_r["total_legend_wins"] = frog_r.get("total_legend_wins", 0) + 1
                    await db_save(frog_r)
                    await ach_check(frog_r, bot)
            except Exception as _e:
                logger.exception("подавлено исключение: %s", _e)
            if i == 0:
                await ach_grant(uid_r, "legend_top1", bot)
        await asyncio.sleep(0.05)

    logger.info("legend_finish: id=%s win=%s participants=%s", leg["id"], win, participants)



# ── Джобы легенды ─────────────────────────────────────────────────────────────

async def job_legend_start(ctx: ContextTypes.DEFAULT_TYPE):
    """Запуск легенды каждый четверг в 15:00 МСК (12:00 UTC)."""
    leg = await legend_active()
    if leg:
        return  # уже есть активная
    await _legend_start(ctx.bot)


async def job_legend_update(ctx: ContextTypes.DEFAULT_TYPE):
    """Обновление прогресс-бара каждые 2 часа. Завершает при 100% или по дедлайну."""
    leg = await legend_active()
    if not leg:
        return
    now = time.time()

    # Проверяем достигнуты ли все цели
    goals    = leg["goals"]
    progress = leg["progress"]
    all_done = all(progress.get(a, 0) >= g for a, g in goals.items())

    if now >= leg["ends_at"] or all_done:
        await _legend_finish(ctx.bot, leg)
        return

    await _legend_announce(ctx.bot, leg)


async def job_staya_events(ctx: ContextTypes.DEFAULT_TYPE):
    """Каждые 48 часов запускает событие для каждой активной стаи."""
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM stayas WHERE last_event_at < ?",
            (now - 48 * 3600,),
        ) as c:
            stayas = [dict(r) for r in await c.fetchall()]

    for staya in stayas:
        try:
            # Проверяем нет ли уже активного события
            async with aiosqlite.connect(DB_PATH) as db:
                async with db.execute(
                    "SELECT id FROM staya_events WHERE staya_id=? AND finished=0",
                    (staya["id"],),
                ) as c:
                    if await c.fetchone():
                        continue

            ev_data = random.choice(STAYA_EVENT_POOL)
            ends_at = now + 24 * 3600  # 24 часа на голосование

            async with aiosqlite.connect(DB_PATH) as db:
                cur = await db.execute(
                    "INSERT INTO staya_events(staya_id,event_json,started_at,ends_at) VALUES(?,?,?,?)",
                    (staya["id"], json.dumps(ev_data, ensure_ascii=False), now, ends_at),
                )
                ev_id = cur.lastrowid
                await db.execute(
                    "UPDATE stayas SET last_event_at=? WHERE id=?",
                    (now, staya["id"]),
                )
                await db.commit()

            # Рассылаем всем участникам — с кнопками выбора прямо в сообщении
            members = await staya_get_members(staya["id"])
            choice_buttons = [
                [btn(ch["label"], callback_data=f"staya_vote_{ev_id}_{ch['key']}")]
                for ch in ev_data["choices"]
            ]
            event_kb = InlineKeyboardMarkup(choice_buttons)
            event_text = (
                f"{ev_data['emoji']} <b>Событие стаи «{he(staya['name'])}»!</b>\n\n"
                f"{ev_data['text']}\n\n"
                f"<i>Проголосуй прямо здесь или в меню Площадь → {_E_LEAF} Стая → Событие</i>"
            )
            for m in members:
                try:
                    await _work_send_safe(
                        ctx.bot, m["user_id"],
                        event_text,
                        parse_mode=ParseMode.HTML,
                        reply_markup=event_kb,
                    )
                    await asyncio.sleep(0.3)
                except Exception as _e:
                    logger.exception("подавлено исключение: %s", _e)

            logger.info("staya_event: staya_id=%s event=%s", staya["id"], ev_data["id"])
        except Exception as _e:
            logger.warning("job_staya_events staya_id=%s: %s", staya["id"], _e)


async def job_staya_resolve_single(ev_id: int, bot):
    """Завершает конкретное событие стаи немедленно (когда все проголосовали)."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM staya_events WHERE id=? AND finished=0", (ev_id,)) as c:
            ev = await c.fetchone()
    if not ev:
        return
    ev = dict(ev)
    try:
        ev_data = json.loads(ev["event_json"])
        staya = await staya_get(ev["staya_id"])
        if not staya:
            return
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            async with db.execute(
                "SELECT choice, COUNT(*) as cnt FROM staya_votes WHERE event_id=? GROUP BY choice ORDER BY cnt DESC",
                (ev_id,),
            ) as c:
                rows = [dict(r) for r in await c.fetchall()]
        winner_choice = (
            next((c for c in ev_data["choices"] if c["key"] == rows[0]["choice"]), ev_data["choices"][0])
            if rows else random.choice(ev_data["choices"])
        )
        coins_delta = winner_choice.get("coins", 0)
        if coins_delta < 0:
            bonuses_ev = staya_get_level_bonus(staya.get("level", 0))
            if bonuses_ev.get("event_penalty_reduce"):
                coins_delta = coins_delta // 2
        if coins_delta != 0:
            await staya_add_cauldron(ev["staya_id"], coins_delta)
        result_text = winner_choice.get("win_text" if winner_choice.get("win") else "lose_text", "")
        outcome = (
            f"{ev_data['emoji']} <b>Событие стаи завершено!</b>\n\n"
            f"<b>Большинство выбрало:</b> {winner_choice['label']}\n\n"
            f"{result_text}\n\n"
            f"Котёл: {'+' if coins_delta >= 0 else ''}{coins_delta}🪙"
        )
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute("UPDATE staya_events SET finished=1, result=? WHERE id=?",
                             (result_text, ev_id))
            await db.commit()
        await staya_add_xp(ev["staya_id"], 20)
        members = await staya_get_members(ev["staya_id"])
        for m in members:
            try:
                await bot.send_message(m["user_id"], outcome, parse_mode=ParseMode.HTML)
                await asyncio.sleep(0.2)
            except (BadRequest, Forbidden, TimedOut):
                pass
        if winner_choice.get("win"):
            await letopis_add(staya["creator_id"], "staya_win",
                              f"{_E_TROPHY} Стая «{staya['name']}» победила в событии!")
    except Exception as _e:
        logger.warning("staya_resolve_single ev_id=%s: %s", ev_id, _e)


async def job_staya_resolve(ctx: ContextTypes.DEFAULT_TYPE):
    """Завершает события стаи у которых вышло время — объявляет результат.
    Также обновляет кэш бонусов стаи и проверяет автоапгрейды."""
    now = time.time()

    # Обновляем кэш бонусов всех стай
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT id, level FROM stayas") as c:
            all_stayas = await c.fetchall()
    for sid, slvl in all_stayas:
        _STAYA_BONUS_CACHE[sid] = staya_get_level_bonus(slvl)
        # Проверяем автоапгрейд
        await staya_check_upgrade(sid, bot=ctx.bot)
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            # Завершаем: у которых вышло время ИЛИ ends_at=0 (зависшие старые)
            "SELECT * FROM staya_events WHERE finished=0 AND (ends_at<? OR ends_at=0 OR ends_at IS NULL)",
            (now,),
        ) as c:
            events = [dict(r) for r in await c.fetchall()]

    for ev in events:
        try:
            ev_data = json.loads(ev["event_json"])
            staya = await staya_get(ev["staya_id"])
            if not staya:
                continue

            # Считаем голоса
            async with aiosqlite.connect(DB_PATH) as db:
                db.row_factory = aiosqlite.Row
                async with db.execute(
                    "SELECT choice, COUNT(*) as cnt FROM staya_votes WHERE event_id=? GROUP BY choice ORDER BY cnt DESC",
                    (ev["id"],),
                ) as c:
                    rows = [dict(r) for r in await c.fetchall()]

            if not rows:
                # Никто не голосовал — случайный выбор
                winner_choice = random.choice(ev_data["choices"])
            else:
                top_key = rows[0]["choice"]
                winner_choice = next(
                    (c for c in ev_data["choices"] if c["key"] == top_key),
                    ev_data["choices"][0],
                )

            # Применяем результат к котлу
            coins_delta = winner_choice.get("coins", 0)
            # Уровень 5: снижаем штрафы событий на 50%
            if coins_delta < 0:
                bonuses_ev = staya_get_level_bonus(staya.get("level", 0))
                if bonuses_ev.get("event_penalty_reduce"):
                    coins_delta = coins_delta // 2
            if coins_delta != 0:
                await staya_add_cauldron(ev["staya_id"], coins_delta)

            result_text = winner_choice["win_text"] if winner_choice.get("win") else winner_choice["lose_text"]
            outcome = (
                f"{ev_data['emoji']} <b>Событие стаи завершено!</b>\n\n"
                f"<b>Большинство выбрало:</b> {winner_choice['label']}\n\n"
                f"{result_text}\n\n"
                f"Котёл: {'+' if coins_delta >= 0 else ''}{coins_delta}🪙"
            )

            # Обновляем запись
            async with aiosqlite.connect(DB_PATH) as db:
                await db.execute(
                    "UPDATE staya_events SET finished=1, result=? WHERE id=?",
                    (result_text, ev["id"]),
                )
                await db.commit()

            # Рассылаем результат
            await staya_add_xp(ev["staya_id"], 20)
            members = await staya_get_members(ev["staya_id"])
            for m in members:
                try:
                    await _work_send_safe(ctx.bot, m["user_id"], outcome, parse_mode=ParseMode.HTML)
                    await asyncio.sleep(0.3)
                except Exception as _e:
                    logger.exception("подавлено исключение: %s", _e)

            # Летопись
            if winner_choice.get("win"):
                await letopis_add(
                    staya["creator_id"], "staya_win",
                    f"{_E_TROPHY} Стая «{staya['name']}» победила в событии — {result_text[:50]}"
                )

        except Exception as _e:
            logger.warning("job_staya_resolve ev_id=%s: %s", ev["id"], _e)


async def job_friend_check(ctx: ContextTypes.DEFAULT_TYPE):
    """Раз в день проверяет неактивных соседей и напоминает о них."""
    now = time.time()
    cutoff = now - 3 * 86400  # 3 дня неактивности
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        # Берём пары друзей где один неактивен
        async with db.execute(
            "SELECT fr.user_id, fr.friend_id, f2.frog_name, f2.first_name, f2.last_seen "
            "FROM friendships fr JOIN frogs f2 ON f2.user_id=fr.friend_id "
            "WHERE fr.pending=0 AND f2.alive=1 AND f2.last_seen < ? "
            "AND f2.last_seen > ?",
            (cutoff, now - 14 * 86400),  # пропали 3-14 дней
        ) as c:
            rows = [dict(r) for r in await c.fetchall()]

    notified = set()
    for row in rows:
        uid_notify = row["user_id"]
        if uid_notify in notified:
            continue
        notified.add(uid_notify)
        friend_name = row.get("frog_name") or row.get("first_name") or "Сосед"
        try:
            await ctx.bot.send_message(
                uid_notify,
                f"😟 Твоя лягушка волнуется о <b>{he(friend_name)}</b>...\n"
                f"Сосед не появлялся на болоте уже несколько дней.\n"
                f"<i>Может напомнить о болоте? <tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji></i>",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        await asyncio.sleep(0.5)


