# ── Лорные resolve-функции для особых развилок ───────────────────────────────

async def resolve_cave_depths(adv_id: int, u1_name: str, u2_name: str) -> tuple[str, int]:
    """
    Рандомит между двумя лор-исходами: скелет Реквили или руины Нижнего Города.
    Возвращает (текст_результата, бонус_монет).
    Сохраняет флаги found_requil / found_cave в adventures.notes.
    """
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE adventures SET notes=json_set(COALESCE(notes,'{}'), '$.found_cave', 1) WHERE id=?",
            (adv_id,)
        )
        await db.commit()

    if random.random() < 0.5:
        # Исход 1: Скелет и дневник Реквили
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE adventures SET notes=json_set(COALESCE(notes,'{}'), '$.found_requil', 1) WHERE id=?",
                (adv_id,)
            )
            await db.commit()
        diary = random.choice(REQUIL_LORE["diary_entries"])
        text = (
            f"🦴 Грот в глубине. На полу — скелет лягушки в истлевшем дорожном плаще.\n\n"
            f"Рядом — дневник, почти рассыпавшийся. {u1_name} бережно перелистала страницы.\n\n"
            f"<i>{diary}</i>\n\n"
            f"Последняя страница: <i>«Они есть. Нижний Город — настоящий. Я нашла ворота»</i>.\n\n"
            f"На обложке — имя: <b>Реквиль Тёмная Лапка</b>.\n\n"
            f"{u2_name} тихо положила рядом болотный цветок. "
            f"Иногда важнее не сокровище, а имя."
        )
        return text, 180
    else:
        # Исход 2: Руины Нижнего Города
        text = (
            f"🏛️ Коридор расширился. Перед лягушками — каменные стены с резьбой.\n\n"
            f"{u1_name} разобрала несколько символов: «место покоя», «до воды», «мы вернёмся».\n\n"
            f"Посреди руин — засохший фонтан. Но красивый.\n\n"
            f"Когда-то здесь был целый город. Жабы-Подземляне ушли под землю "
            f"от <b>Великой Засухи</b> — и построили тут всё заново.\n\n"
            f"{u2_name} подняла маленькую каменную табличку: «Добро пожаловать в Нижний Город».\n\n"
            f"<i>Табличка тёплая на ощупь. Как будто её держали совсем недавно.</i>"
        )
        return text, 200


async def resolve_tavern(adv_id: int, u1_name: str, u2_name: str) -> tuple[str, int]:
    """
    Лор таверны. Если ранее нашли дневник Реквили — трактирщик скажет другое.
    Возвращает (текст_результата, бонус_монет).
    """
    notes = {}
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT notes FROM adventures WHERE id=?", (adv_id,)) as c:
            row = await c.fetchone()
    if row and row[0]:
        try:
            notes = json.loads(row[0])
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)

    found_requil = notes.get("found_requil", False)

    if found_requil:
        keeper_line = REQUIL_LORE["tavern_keeper_after_found"]
        bonus_note = (
            "\n\n🪙 Хозяин протянул старую монетку Реквили. Особая — <b>+50 к награде</b>."
        )
        bonus = 200
    else:
        keeper_line = REQUIL_LORE["tavern_keeper"]
        bonus_note = ""
        bonus = 120

    text = (
        f"🍺 {u1_name} и {u2_name} зашли в «Болотную Нору».\n\n"
        f"За стойкой — пожилой жаб с мохнатыми бровями. "
        f"Поставил две кружки болотного чая без вопросов.\n\n"
        f"<i>«{keeper_line}»</i>"
        f"{bonus_note}\n\n"
        f"Путешественники у соседнего стола кивнули: "
        f"<i>«Нижний Город — это не легенда. Мой дед туда ходил».</i>"
    )
    return text, bonus


async def job_adventure_tick(ctx: ContextTypes.DEFAULT_TYPE):
    """
    Каждые 15 минут: отправляет лог-сообщения активным походам,
    проверяет развилки и завершает походы время которых вышло.
    """
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute("SELECT * FROM adventures WHERE finished=0") as c:
            active = [dict(r) for r in await c.fetchall()]

    for adv in active:
        adv_id = adv["id"]
        try:
            # ── Хард-таймаут: поход завис > 9 часов (макс 8ч + 1ч буфер) ──
            adv_age_s = now - adv.get("started_at", now)
            if adv_age_s > 9 * 3600:
                logger.warning(
                    "job_adventure_tick: поход id=%s завис (%.1fч) — принудительное завершение",
                    adv_id, adv_age_s / 3600,
                )
                try:
                    async with aiosqlite.connect(DB_PATH) as _tdb:
                        await _tdb.execute("UPDATE adventures SET finished=1 WHERE id=?", (adv_id,))
                        await _tdb.execute(
                            "UPDATE frogs SET adventure_id=0, adventure_locked_until=0 "
                            "WHERE user_id IN (?,?)",
                            (adv["user1_id"], adv["user2_id"]),
                        )
                        await _tdb.commit()
                    _t_reward = 20 + adv.get("duration_h", 2) * 10
                    _t_xp = 20 + adv.get("duration_h", 2) * 5
                    for _t_uid in (adv["user1_id"], adv["user2_id"]):
                        _t_f = await db_get(_t_uid)
                        if _t_f:
                            _t_f["coins"] = _t_f.get("coins", 0) + _t_reward
                            add_xp(_t_f, _t_xp)
                            _t_f["adventure_id"] = 0
                            _t_f["adventure_locked_until"] = 0
                            await db_save(_t_f)
                            try:
                                await ctx.bot.send_message(
                                    _t_uid,
                                    f"{_E_SWORDS} <b>Поход завершён!</b>\n\n"
                                    f"Твоя лягушка вернулась из похода.\n"
                                    f"<b>+{_t_reward}{_E_COIN}</b> ⭐ <b>+{_t_xp} XP</b>\n"
                                    f"<i>(Автозавершение — превышено максимальное время)</i>",
                                    parse_mode=ParseMode.HTML,
                                )
                            except (BadRequest, Forbidden, TimedOut):
                                pass
                    logger.info("Хард-таймаут похода id=%s: завершён, reward=%s", adv_id, _t_reward)
                except Exception as _te:
                    logger.error("Хард-таймаут похода id=%s: ошибка: %s", adv_id, _te)
                continue

            u1 = await db_get(adv["user1_id"])
            u2 = await db_get(adv["user2_id"])
            if not u1 or not u2:
                continue
            n1 = u1.get("frog_name") or u1.get("first_name") or "Лягушка"
            n2 = u2.get("frog_name") or u2.get("first_name") or "Лягушка"

            # ── Завершение похода ────────────────────────────
            if now >= adv["ends_at"]:
                u1_choices = json.loads(adv.get("u1_choices") or "{}")
                u2_choices = json.loads(adv.get("u2_choices") or "{}")
                choice_plan = json.loads(adv.get("choices_json") or "[]")

                # Считаем награду
                base_reward = 20 + adv["duration_h"] * 10  # 2ч=40, 4ч=60, 8ч=100
                bonus = 0
                agree_count = 0
                # Учитываем бонусы лорных развилок (пещера, таверна)
                _adv_notes = {}
                try:
                    _adv_notes = json.loads(adv.get("notes") or "{}")
                except Exception as _e:
                    logger.exception("подавлено исключение: %s", _e)
                bonus += _adv_notes.get("extra_bonus", 0)
                result_lines = []
                for cp in choice_plan:
                    cid = cp["choice_id"]
                    c1 = u1_choices.get(cid)
                    c2 = u2_choices.get(cid)
                    ch_data = next((c for c in ADV_CHOICES if c["id"] == cid), None)
                    if not ch_data:
                        continue
                    # Берём выбор — если один не ответил берём выбор другого
                    effective = c1 or c2
                    if not effective:
                        effective = random.choice([o["key"] for o in ch_data["options"]])
                    opt = next((o for o in ch_data["options"] if o["key"] == effective), ch_data["options"][0])
                    bonus += opt.get("bonus", 0)
                    result_lines.append(f"• {opt['text']}")
                    if c1 and c2 and c1 == c2:
                        agree_count += 1
                        bonus += ch_data.get("agree_bonus", 0)

                total_reward = base_reward + bonus
                xp_reward = 20 + adv["duration_h"] * 5  # 2ч=30, 4ч=40, 8ч=60

                ending = random.choice(ADV_ENDINGS).format(u1=n1, u2=n2)
                result_text = "\n".join(result_lines) if result_lines else "Всё прошло гладко!"
                agree_note = f"\n🤝 Согласованность: {agree_count}/{len(choice_plan)} — бонус!" if agree_count else ""

                final_msg = (
                    f"{_E_TROPHY} <b>Поход завершён!</b>\n\n"
                    f"{ending}\n\n"
                    f"<b>Итоги решений:</b>\n{result_text}"
                    f"{agree_note}\n\n"
                    f"Каждый получает: <b>+{total_reward}{_E_COIN}</b>\n"
                    f"{_E_XP} <b>+{xp_reward} XP</b>"
                )

                for frog, frog_id in [(u1, adv["user1_id"]), (u2, adv["user2_id"])]:
                    frog["coins"] = frog.get("coins", 0) + total_reward
                    asyncio.create_task(plog(
                        frog["user_id"], "adventure_end",
                        f"reward={total_reward}",
                        coins_delta=total_reward,
                    ))
                    add_xp(frog, xp_reward)
                    frog["adventure_id"] = 0
                    frog["adventure_locked_until"] = 0
                    await levelup(frog, ctx.bot)
                    await db_save(frog)
                    await friend_add_xp(frog_id,
                        adv["user2_id"] if frog_id == adv["user1_id"] else adv["user1_id"],
                        10)
                    try:
                        await ctx.bot.send_message(frog_id, final_msg, parse_mode=ParseMode.HTML)
                    except (BadRequest, Forbidden, TimedOut):
                        pass

                async with aiosqlite.connect(DB_PATH) as db:
                    await db.execute("UPDATE adventures SET finished=1 WHERE id=?", (adv_id,))
                    await db.commit()

                await letopis_add(adv["user1_id"], "staya_win",
                    f"{_E_SWORDS} {n1} и {n2} вернулись из похода с {total_reward}🪙!")
                logger.info("adv finished id=%s reward=%s", adv_id, total_reward)
                continue

            # ── Проверка развилок ────────────────────────────
            choice_plan = json.loads(adv.get("choices_json") or "[]")
            for i, cp in enumerate(choice_plan):
                if not cp.get("sent") and now >= cp["at"]:
                    ch_data = next((c for c in ADV_CHOICES if c["id"] == cp["choice_id"]), None)
                    if not ch_data:
                        continue
                    cp["sent"] = True
                    choice_plan[i] = cp
                    async with aiosqlite.connect(DB_PATH) as db:
                        await db.execute(
                            "UPDATE adventures SET choices_json=? WHERE id=?",
                            (json.dumps(choice_plan, ensure_ascii=False), adv_id),
                        )
                        await db.commit()
                    kb = InlineKeyboardMarkup([[
                        btn(o["label"],
                            callback_data=f"adv_choice_{adv_id}_{o['key']}")
                        for o in ch_data["options"]
                    ]])
                    choice_msg = (
                        f"{ch_data['text']}\n\n"
                        f"<i>⏰ У вас 10 минут чтобы выбрать</i>"
                    )
                    for frog_id in (adv["user1_id"], adv["user2_id"]):
                        try:
                            await ctx.bot.send_message(
                                frog_id, choice_msg,
                                parse_mode=ParseMode.HTML, reply_markup=kb,
                            )
                        except (BadRequest, Forbidden, TimedOut):
                            pass
                    await adv_add_log(adv_id, f"🎲 Развилка: {ch_data['id']}")
                    break  # одна развилка за тик

            # ── Отправка нарративного лога ───────────────────
            last_log = adv.get("last_log_at", adv["started_at"])
            log_interval = random.randint(12, 18) * 60  # 12–18 мин

            if now - last_log >= log_interval:
                elapsed_pct = (now - adv["started_at"]) / (adv["ends_at"] - adv["started_at"])
                if elapsed_pct < 0.25:
                    pool_keys = ["forest", "river", "friendship"]
                elif elapsed_pct < 0.5:
                    pool_keys = ["mountain", "cave", "danger", "discovery"]
                elif elapsed_pct < 0.75:
                    pool_keys = ["village", "rest", "friendship", "danger"]
                else:
                    pool_keys = ["near_end", "discovery", "rest"]

                # Редкое событие — 10% шанс раз за поход
                logs = json.loads(adv.get("log_json") or "[]")
                has_rare = any("rare" in l.get("text", "") for l in logs)
                if not has_rare and random.random() < 0.10:
                    pool_key = "rare"
                else:
                    pool_key = random.choice(pool_keys)
                log_text = random.choice(ADV_LOG_POOL[pool_key]).format(u1=n1, u2=n2)
                await adv_add_log(adv_id, log_text)

                left_min = int((adv["ends_at"] - now) / 60)
                log_msg = (
                    f"📜 <b>Из похода</b> ⏱ осталось ~{left_min} мин\n\n"
                    f"{log_text}"
                )
                for frog_id in (adv["user1_id"], adv["user2_id"]):
                    try:
                        await ctx.bot.send_message(frog_id, log_msg, parse_mode=ParseMode.HTML,
                            reply_markup=InlineKeyboardMarkup([[
                                btn("📜 Все события", callback_data="adv_status"),
                            ]]))
                    except (BadRequest, Forbidden, TimedOut):
                        pass

        except Exception as _e:
            logger.warning("adv tick id=%s: %s", adv_id, _e)


async def job_sub_expiry_offer(ctx: ContextTypes.DEFAULT_TYPE):
    """
    Каждый час ищет подписки которые истекли 0–2 часа назад
    и шлёт персональный оффер со скидкой на 1 час.
    """
    now = time.time()
    # Ловим истёкшие в последние 7 дней (чтобы при деплое тоже срабатывало)
    window_start = now - 7 * 86400
    window_end   = now

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT user_id, subscription_type, last_sub_offer FROM frogs "
            "WHERE alive=1 AND subscription_type > 0 "
            "AND subscription_until BETWEEN ? AND ? "
            "AND (last_sub_offer IS NULL OR last_sub_offer = 0 OR last_sub_offer < subscription_until)",
            (window_start, window_end),
        ) as c:
            rows = await c.fetchall()

    for row in rows:
        uid_exp, sub_type, _ = row
        try:
            f = await db_get(uid_exp)
            if not f:
                continue

            frog_name = f.get("frog_name") or f.get("first_name") or "Квакуся"
            is_worker = sub_type >= 2
            offer_ends = now + 3600  # оффер живёт 1 час

            if is_worker:
                orig_price  = 800   # обычная цена Трудяги
                sale_price  = 640   # скидка 20%
                sub_name    = "🏪 Трудяга"
                benefit     = "400–700🪙 каждый вечер + автоуход"
                cb_buy      = "sub_renewal_offer_worker"
            else:
                orig_price  = 200   # обычная цена Няни (как в STAR_PACKAGES)
                sale_price  = 160   # скидка 20%
                sub_name    = "🧑‍🍼 Болотная Няня"
                benefit     = "автоматический уход пока ты занят"
                cb_buy      = "sub_renewal_offer_nanny"

            save = orig_price - sale_price
            pct  = int(save / orig_price * 100)

            # Сохраняем время оффера и его дедлайн в bot_data
            ctx.bot_data[f"sub_offer_{uid_exp}"] = {
                "ends": offer_ends,
                "type": "worker" if is_worker else "nanny",
                "price": sale_price,
            }

            # Обновляем last_sub_offer
            f["last_sub_offer"] = now
            await db_save(f)

            text = (
                f"⏰ <b>Подписка {sub_name} закончилась!</b>\n\n"
                f"🐸 <b>{he(frog_name)}</b> скучает без заботы...\n\n"
                f"🔥 <b>Специальное предложение — только 1 час!</b>\n"
                f"<s>{orig_price}</s>{_E_STARS} → <b>{sale_price}{_E_STARS}</b> "
                f"<i>(скидка {pct}%, экономия {save}{_E_STARS})</i>\n\n"
                f"✅ {benefit}\n\n"
                f"⏱ Предложение истекает через <b>60 минут</b>!"
            )
            kb = InlineKeyboardMarkup([
                [btn(
                    f"🔥 Продлить за {sale_price}⭐ (скидка {pct}%)",
                    callback_data=cb_buy,
                )],
                [btn(
                    f"💸 Обычная цена ({orig_price}{_E_STARS})",
                    callback_data="sub_buy_worker" if is_worker else "sub_buy_nanny",
                )],
            ])
            await ctx.bot.send_message(uid_exp, text,
                                       parse_mode=ParseMode.HTML, reply_markup=kb)
            logger.info("sub_expiry_offer uid=%s type=%s price=%s",
                        uid_exp, sub_type, sale_price)
        except Exception as _e:
            logger.warning("sub_expiry_offer uid=%s: %s", uid_exp, _e)
        await asyncio.sleep(0.3)


async def job_swamp_weather(ctx: ContextTypes.DEFAULT_TYPE):
    """Утренняя сводка погоды в общий чат. Запускается каждый день в 07:00 МСК."""
    weather = _get_today_weather()

    # Авто-эффект дождя — чистота +10 всем живым
    if weather.get("auto_clean"):
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE frogs SET cleanliness = MIN(100, cleanliness + ?) WHERE alive=1",
                (weather["auto_clean"],),
            )
            await db.commit()

    # Авто-эффект снега — счастье +5
    if weather.get("auto_happy"):
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE frogs SET happiness = MIN(100, happiness + ?) WHERE alive=1",
                (weather["auto_happy"],),
            )
            await db.commit()

    # Сводка идёт в главный игровой чат. Без настроенного CHAT_ID Telegram
    # отвечает «Chat not found», и в логе каждый раз висит невнятная ошибка
    # вместо понятной причины.
    if not CHAT_ID:
        logger.info("job_swamp_weather: CHAT_ID не задан в .env — сводка не отправлена")
        return
    try:
        await ctx.bot.send_message(
            CHAT_ID,
            f"{weather['emoji']} <b>Болотная сводка погоды</b>\n\n"
            f"<b>{weather['title']}</b>\n"
            f"{weather['desc']}\n\n"
            f"<i>{weather['effect']}</i>",
            parse_mode=ParseMode.HTML,
        )
    except Exception as _e:
        logger.warning(
            "job_swamp_weather: не отправить в CHAT_ID=%s (%s). "
            "Проверь ID главного чата в .env — узнать его можно командой /chatid",
            CHAT_ID, _e,
        )


async def job_birthday_check(ctx: ContextTypes.DEFAULT_TYPE):
    """Проверяет дни рождения лягушек раз в день."""
    now = time.time()
    one_year = 365 * 86400
    # Окно: born_at ровно год назад ±12 часов
    window_start = now - one_year - 43200
    window_end   = now - one_year + 43200
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT user_id FROM frogs WHERE alive=1 AND born_at BETWEEN ? AND ?",
            (window_start, window_end),
        ) as c:
            uids = [r[0] for r in await c.fetchall()]

    for uid in uids:
        try:
            f = await db_get(uid)
            if not f:
                continue
            name = fname(f)
            feeds  = f.get("total_feeds",  0)
            sleeps = f.get("total_sleeps", 0)
            text   = random.choice(BIRTHDAY_TEXTS).format(
                name=name, feeds=feeds, sleeps=sleeps
            )
            # Бонус имениннице
            f["coins"]     = f.get("coins", 0) + 100
            f["happiness"] = min(100, f.get("happiness", 50) + 30)
            await db_save(f)
            await letopis_add(uid, 'birthday', f"🎂 {name} — год на болоте!")
            await ctx.bot.send_message(
                uid,
                f"🎂 <b>День рождения!</b>\n\n{text}\n\n"
                f"{_E_GIFT} Подарок: <b>+100{_E_COIN}</b> и <b>+30 настроения</b>!",
                parse_mode=ParseMode.HTML,
            )
            # Анонс в чат
            await announce(
                ctx.bot,
                f"🎂 <b>День рождения!</b>\n{name} — ровно год на болоте! 🐸",
                delete_after=3600,
            )
        except Exception as _e:
            logger.warning("birthday uid=%s: %s", uid, _e)
        await asyncio.sleep(0.3)


async def job_tutorial_nudge(ctx: ContextTypes.DEFAULT_TYPE):
    """
    Туториал первых 3 дней. Запускается раз в час.
    День 1 (через ~2ч после регистрации): объяснить ква и ежедневный бонус.
    День 2: рассказать о гаче и дуэлях.
    День 3: рассказать о болотной связи и комаре.
    Каждое сообщение с маленькой наградой чтобы создать момент радости.
    """
    now = time.time()
    # Берём игроков зарегистрированных ≤4 дней назад, живых
    cutoff_min = now - 4 * 86400
    cutoff_max = now - 2 * 3600  # минимум 2ч с момента регистрации
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT user_id, born_at, last_tutorial_day FROM frogs "
            "WHERE alive=1 AND born_at > ? AND born_at < ? AND is_bot=0 AND banned=0",
            (cutoff_min, cutoff_max),
        ) as c:
            candidates = [dict(r) for r in await c.fetchall()]

    for row in candidates:
        uid_t = row["user_id"]
        born  = row["born_at"] or now
        last_day = row.get("last_tutorial_day", 0) or 0
        days_old = (now - born) / 86400  # дробные дни

        # Определяем какой день отправить
        target_day = 0
        if days_old >= 3 and last_day < 3:
            target_day = 3
        elif days_old >= 1 and last_day < 2:
            target_day = 2
        elif days_old >= 0.08 and last_day < 1:  # ~2ч
            target_day = 1

        if not target_day:
            continue

        f_t = await db_get(uid_t)
        if not f_t or not f_t.get("alive"):
            continue

        # Начисляем маленький бонус за каждый день туториала
        reward_coins = {1: 30, 2: 50, 3: 75}.get(target_day, 0)
        f_t["coins"] += reward_coins
        f_t["last_tutorial_day"] = target_day
        await db_save(f_t)

        name_t = fname(f_t)

        if target_day == 1:
            text_t = (
                f"🐸 <b>Привет, {name_t}!</b>\n\n"
                f"Твоя лягушка живёт и развивается — вот несколько советов:\n\n"
                f"• Напиши <b>ква</b> в чате — лягушка расскажет чем занята и получит монеты\n"
                f"• Каждый день нажимай <b>📅 Ежедневный бонус</b> — строй стрик!\n"
                f"• Следи за голодом и здоровьем — упадут до нуля и лягушка умрёт\n\n"
                f"{_E_GIFT} Держи <b>+{reward_coins}🪙</b> на старт!"
            )
        elif target_day == 2:
            text_t = (
                f"{_E_CASINO} <b>День второй, {name_t}!</b>\n\n"
                f"Ты уже знаешь основы — теперь про заработок:\n\n"
                f"• <b>Гача</b> — крути и получай редкие облики. Каждые 50 круток — гарантированная легенда!\n"
                f"• <b>Дуэли</b> — сражайся с другими лягушками и забирай монеты\n"
                f"• <b>Казино</b> и мини-игры — рискуй и зарабатывай\n"
                f"• <b>Комар</b> — появляется в чате случайно, успей поймать первым!\n\n"
                f"{_E_GIFT} Заряжаю тебя <b>+{reward_coins}🪙</b>!"
            )
        else:  # день 3
            text_t = (
                f"{_E_LEAF} <b>Третий день — {name_t} освоилась!</b>\n\n"
                f"Теперь про социальное:\n\n"
                f"• <b>Болотная Связь</b> — найди напарника и заходите оба каждый день. "
                f"Стрик растёт → вехи 3/7/14/30/100 дней → монеты обоим\n"
                f"• <b>Площадь</b> — смотри других лягушек, подружись с соседями\n"
                f"• <b>Болотный Рынок</b> — покупай и продавай облики за монеты\n\n"
                f"{_E_GIFT} Приятного болотного дня — <b>+{reward_coins}🪙</b>!"
            )

        try:
            await ctx.bot.send_message(
                uid_t, text_t, parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[
                    btn("🐸 Открыть лягушку", callback_data="refresh"),
                ]]),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        await asyncio.sleep(0.05)



