def _frog_reaction(action: str) -> str:
    """Возвращает случайную реакцию лягушки на действие ухода."""
    pools = {
        "feed":  _FROG_FEED_REACTIONS,
        "wash":  _FROG_WASH_REACTIONS,
        "sleep": _FROG_SLEEP_REACTIONS,
        "play":  _FROG_PLAY_REACTIONS,
    }
    pool = pools.get(action, [])
    return random.choice(pool) if pool else ""

async def job_reminders(ctx: ContextTypes.DEFAULT_TYPE):
    """Предупреждения о состоянии лягушки — три уровня тревоги."""
    frogs = await db_all_alive()
    now = time.time()
    to_remind = []

    for f in frogs:
        # Пропускаем анабиоз
        if f.get("hibernation_until", 0) > now:
            continue
        f = decay(f)
        if not f.get("alive"):
            continue

        hp     = f.get("health", 100)
        hunger = f.get("hunger", 100)
        name   = fname(f)
        uid_r  = f["user_id"]
        last_r = f.get("last_remind", 0)

        # Кнопка быстрого доступа.
        # Раньше здесь была url-кнопка на https://t.me/<бот>. Такая ссылка
        # только открывает переписку и ничего не отправляет: /start Telegram
        # шлёт сам лишь в пустом чате, а у получателя напоминания переписка
        # заведомо не пустая. Игрок жал кнопку и оказывался в чате без экрана.
        # Сообщение приходит в личку от самого бота, поэтому здесь работает
        # обычный callback — экран ухода открывается прямо на месте.
        frog_kb = InlineKeyboardMarkup([[
            btn("Покормить и вылечить", callback_data="menu_care",
                style="primary", icon_id=ICON_CARE)
        ]])

        # ── Критично: HP < 10% или голод = 0 → предупреждаем раз в 1ч ──
        if (hp < 10 or hunger == 0) and now - last_r > 3600:
            # Кнопка теперь делает всё на месте, поэтому «срочно зайди» из
            # текстов убрано: указание никуда не идти уже неверно, а гнать
            # человека паникой ради возврата — ровно то, чего гайд не велит.
            if hp < 10:
                text = (
                    f"{_E_HEART} <b>{name} при смерти</b>\n\n"
                    f"Здоровье: <b>{hp}%</b>. На нуле — умрёт."
                )
            else:
                text = (
                    f"{_E_FOOD} <b>{name} голодает</b>\n\n"
                    f"Голод: <b>0%</b>. Пока пусто — здоровье тает каждый час."
                )
            to_remind.append((f, text, frog_kb))

        # ── Плохо: HP 10–25% или голод < 20% → раз в 4ч ──
        elif (10 <= hp < 25 or hunger < 20) and now - last_r > 4 * 3600:
            text = (
                f"{_E_HEART} <b>{name} расклеилась</b>\n\n"
                f"{_E_HEART} {hp}% {_E_FOOD} {hunger}%"
            )
            to_remind.append((f, text, frog_kb))

        # ── Грустит: голод/настроение < 40% → раз в 6ч ──
        elif (hunger < 40 or f.get("happiness", 100) < 30) and now - last_r > 6 * 3600:
            m = get_mood(f)
            if m in ("sad", "sick"):
                text = (
                    f"{_E_FOOD} <b>{name} заскучала</b>\n\n"
                    f"{_E_FOOD} {hunger}% {_E_HAPPY} {f.get('happiness',100)}%"
                )
                to_remind.append((f, text, frog_kb))

    if not to_remind:
        return

    updated_frogs = []
    for f, text, kb in to_remind:
        try:
            await ctx.bot.send_message(
                f["user_id"], text,
                parse_mode=ParseMode.HTML,
                reply_markup=kb,
            )
            f["last_remind"] = now
            updated_frogs.append(f)
        except (Forbidden, Exception):
            pass
        await asyncio.sleep(0.05)

    if updated_frogs:
        for f in updated_frogs:
            await db_save(f)


async def job_mosquito(ctx: ContextTypes.DEFAULT_TYPE):
    """
    Охота на комара.
    1. Публикует событие в игровой чат.
    2. Рассылает ЛС активным игрокам — сортировка случайная (RANDOM()),
       чтобы никто не получал преимущество из-за позиции в БД.
    """
    active_cutoff = time.time() - MOSQUITO_ACTIVE_HOURS * 3600
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            # ORDER BY RANDOM() — честный случайный порядок доставки,
            # никто не получает ЛС раньше других по техническим причинам
            "SELECT user_id FROM frogs WHERE alive=1 AND mosquito_notify=1 AND last_seen >= ? ORDER BY RANDOM()",
            (active_cutoff,),
        ) as c:
            users = [r[0] for r in await c.fetchall()]
        if not users:
            return
        reward = random.randint(20, 200)
        # Название комара по размеру награды
        if reward >= 120:
            mosq_label = "огромный"
            mosq_size  = "Огромный"
        elif reward >= 60:
            mosq_label = "жирный"
            mosq_size  = "Жирный"
        else:
            mosq_label = "мелкий"
            mosq_size  = "Мелкий"
        now = time.time()
        await db.execute(
            "INSERT INTO mosquito_events(caught_by,created_at,reward,catchers,recipient_msgs) VALUES(?,?,?,?,?)",
            (None, now, reward, "[]", "{}"),
        )
        await db.commit()
        async with db.execute("SELECT last_insert_rowid()") as c:
            eid = (await c.fetchone())[0]

    kb = InlineKeyboardMarkup(
        [[btn("🦟 Поймать комара! (5 мест)", callback_data=f"mosquito_{eid}")]]
    )
    text = (
        f"🦟 <b>В воздухе летает {mosq_label} комар!</b>\n\n"
        f"Первые <b>пятеро</b> поймавших получат:\n"
        f"🥇 {reward}{coin_emoji()} · 🥈 {int(reward*0.75)}{coin_emoji()} · 🥉 {int(reward*0.5)}{coin_emoji()}\n"
        f"4️⃣ {int(reward*0.35)}{coin_emoji()} · 5️⃣ {int(reward*0.25)}{coin_emoji()}\n\n"
        f"<i>Не упусти! Пять мест свободно</i>"
    )

    # ── Шаг 1: сначала публикуем в чат ──────────────────────────────────────
    try:
        await ctx.bot.send_message(CHAT_ID, text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as _e:
        logger.warning("job_mosquito: ошибка отправки в чат: %s", _e)

    # ── Шаг 2: рассылаем ЛС — параллельно с семафором 30 msg/s ─────────────
    BULK_SEND_LIMIT = int(os.getenv("BULK_SEND_LIMIT", "30"))
    sem = asyncio.Semaphore(BULK_SEND_LIMIT)

    async def send_one(r_uid: int):
        async with sem:
            try:
                msg = await ctx.bot.send_message(
                    r_uid, text, parse_mode=ParseMode.HTML, reply_markup=kb
                )
                return r_uid, msg.message_id
            except Exception:
                return r_uid, None

    tasks = [send_one(r_uid) for r_uid in users]
    results = await asyncio.gather(*tasks)
    recipient_msgs: dict[str, int] = {str(r_uid): mid for r_uid, mid in results if mid is not None}
    failed_count = sum(1 for _, mid in results if mid is None)
    sent_count = len(recipient_msgs)

    # ── Шаг 3: сохраняем ID сообщений ───────────────────────────────────────
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE mosquito_events SET recipient_msgs=? WHERE id=?",
            (json.dumps(recipient_msgs), eid),
        )
        await db.commit()

    # ── Шаг 4: отчёт в ADMIN_CHAT_ID ────────────────────────────────────────
    _bulk_elapsed = time.time() - now
    if ADMIN_CHAT_ID:
        try:
            await ctx.bot.send_message(
                ADMIN_CHAT_ID,
                f"🦟 <b>Событие «Комар» #{eid}</b>\n"
                f"🐛 Размер: <b>{mosq_size}</b>\n"
                f"📤 Уведомлено игроков в ЛС: <b>{sent_count}</b>\n"
                f"{_E_CROSS} Не доставлено: <b>{failed_count}</b>\n"
                f"{_E_USERS} Всего активных: <b>{len(users)}</b>\n"
                f"⏱ Рассылка заняла: <b>{_bulk_elapsed:.1f} сек</b>\n"
                f"{_E_GIFT} Награда 1-го места: <b>{reward}{_E_COIN}</b>\n"
                f"🛡 Антибот: мин. реакция {MOSQUITO_MIN_REACT_MS}ms, лимит {MOSQUITO_DAILY_LIMIT}/день",
                parse_mode=ParseMode.HTML,
            )
        except Exception as _e:
            logger.warning("job_mosquito: не удалось отправить отчёт в ADMIN_CHAT_ID: %s", _e)

    await asyncio.sleep(298)  # ~5 минут с учётом задержки выше

    # Шаг 3: проверяем и закрываем
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT catchers FROM mosquito_events WHERE id=?", (eid,)
        ) as c:
            row = await c.fetchone()
        catchers_final = json.loads(row[0]) if row and row[0] else []
        if not catchers_final:
            await db.execute(
                "UPDATE mosquito_events SET caught_by=-1 WHERE id=?", (eid,)
            )
            await db.commit()
            expired = True
        else:
            expired = False

    if expired:
        # Утешительный приз: даём 10 монет всем, кто получил сообщение, но не успел поймать
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT recipient_msgs FROM mosquito_events WHERE id=?", (eid,)
            ) as c:
                row2 = await c.fetchone()
        actual_msgs = json.loads(row2[0]) if row2 and row2[0] else recipient_msgs
        consolation_ids = list(actual_msgs.keys())

        async def _consolation_one(r_uid_str: str):
            try:
                cf = await db_get(int(r_uid_str))
                if cf:
                    cf["coins"] += 10
                    await db_save(cf)
            except Exception as _e:
                logger.exception("подавлено исключение: %s", _e)

        await asyncio.gather(*[_consolation_one(r) for r in consolation_ids])

        expired_text = f"{_E_MOSQUITO} <b>Комар улетел!</b> Никто не поймал 😢\n+10🪙 утешительный приз для всех участников"
        # Обновляем личные сообщения
        sem = asyncio.Semaphore(10)

        async def _expire_one(r_uid_str: str, msg_id: int):
            async with sem:
                try:
                    await ctx.bot.edit_message_text(
                        text=expired_text,
                        chat_id=int(r_uid_str),
                        message_id=msg_id,
                        parse_mode=ParseMode.HTML,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass

        await asyncio.gather(*[_expire_one(r, m) for r, m in actual_msgs.items()])
        _MOSQUITO_LOCKS.pop(eid, None)
        # Анонс в общий чат — никто не поймал
        try:
            await ctx.bot.send_message(
                CHAT_ID,
                f"{_E_MOSQUITO} <b>Комар улетел — никто не поймал! 😢</b>\n<i>Все уведомлённые игроки получили по +10<tg-emoji emoji-id='5341524176039615767'>🪙</tg-emoji> утешительный приз</i>",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
    else:
        # Анонс результатов в общий чат ТОЛЬКО если не все были пойманы в течение игры
        # (если все поймали до таймаута — callback уже отправил итог)
        MAX_CATCHERS_JOB = 5
        caught_lines = "\n".join(
            f"{['🥇','🥈','🥉','4️⃣','5️⃣'][i]} {c['name']} — +{c['reward']} {_E_COIN}"
            for i, c in enumerate(catchers_final)
        )
        if len(catchers_final) < MAX_CATCHERS_JOB:
            try:
                await ctx.bot.send_message(
                    CHAT_ID,
                    f"🦟 <b>Комара поймали!</b>\n\n{caught_lines}",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass

        # Синхронно обновляем все личные сообщения финальным результатом
        final_text_caught = f"🦟 <b>Комара поймали!</b>\n\n{caught_lines}"
        sem_update = asyncio.Semaphore(30)

        async def _update_final_caught(uid_str: str, msg_id: int):
            async with sem_update:
                try:
                    await ctx.bot.edit_message_text(
                        text=final_text_caught,
                        chat_id=int(uid_str),
                        message_id=msg_id,
                        parse_mode=ParseMode.HTML,
                        reply_markup=None,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass

        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT recipient_msgs FROM mosquito_events WHERE id=?", (eid,)
            ) as c:
                row_rm = await c.fetchone()
        final_recipient_msgs = json.loads(row_rm[0]) if row_rm and row_rm[0] else recipient_msgs
        await asyncio.gather(*[_update_final_caught(u, m) for u, m in final_recipient_msgs.items()])
        _MOSQUITO_LOCKS.pop(eid, None)

    # Планируем следующего комара: случайный интервал от 9 до 15 часов (avg ~12h = 2/день)
    next_in = random.randint(32400, 54000)  # 9–15 часов в секундах
    ctx.job_queue.run_once(job_mosquito, when=next_in, name="mosquito_once")


async def job_background_decay(ctx: ContextTypes.DEFAULT_TYPE):
    """
    Фоновый распад параметров лягушек (каждые 3 часа).
    Применяет decay() ко всем живым игрокам — это устраняет баг «максимальные
    параметры навсегда» когда за лягушкой не ухаживают, но её подкармливают другие.
    Так же отправляет предупреждение о низком здоровье и помечает мёртвых.
    """
    now = time.time()
    # Выбираем только живых игроков, которых не трогали более 1 часа
    stale_cutoff = now - 3600
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT user_id FROM frogs WHERE alive=1 AND last_decay < ?",
            (stale_cutoff,),
        ) as c:
            user_ids = [r[0] for r in await c.fetchall()]

    processed = 0
    died = 0
    warned = 0

    for uid_dec in user_ids:
        try:
            f = await db_get(uid_dec)
            if not f or not f.get("alive"):
                continue
            f_before = f.copy()
            f = decay(f)
            # Если decay что-то изменил — сохраняем
            if f != f_before:
                await db_save(f)
                processed += 1
            # Уведомление о низком здоровье
            if f.get("_need_warning"):
                f.pop("_need_warning", None)
                try:
                    await ctx.bot.send_message(
                        uid_dec,
                        f"⚠️ <b>Твоя лягушка совсем слаба!</b>\n"
                        f"{_E_HEART} Здоровье: {f['health']}%\n"
                        f"<i>Срочно покорми и позаботься — иначе она умрёт</i>",
                        parse_mode=ParseMode.HTML,
                    )
                    warned += 1
                except (BadRequest, Forbidden, TimedOut):
                    pass
            # Мягкий намёк на Няню при низком голоде (<20%) — не чаще раза в сутки
            _hunger_nudge_key = f"last_nanny_nudge_{uid_dec}"
            _has_sub = f.get("subscription_until", 0) > now and f.get("subscription_type", 0) >= 1
            if (
                not _has_sub
                and f.get("hunger", 100) < 20
                and now - ctx.bot_data.get(_hunger_nudge_key, 0) > 86400
            ):
                ctx.bot_data[_hunger_nudge_key] = now
                try:
                    await ctx.bot.send_message(
                        uid_dec,
                        f"🍖 <b>Твоя лягушка голодна!</b>\n\n"
                        f"Голод: <b>{f.get('hunger', 0)}%</b>\n\n"
                        f"<i>Если некогда следить — Болотная Няня покормит её пока ты занят.</i>",
                        parse_mode=ParseMode.HTML,
                        reply_markup=InlineKeyboardMarkup([[
                            btn("🧑‍🍼 Няня · 7 дней · 75⭐", callback_data="sub_buy_nanny_7"),
                        ]])
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass
            # Уведомление о смерти
            if f.get("_just_died"):
                f.pop("_just_died", None)
                died += 1
                _has_sub_death = f.get("subscription_until", 0) > now and f.get("subscription_type", 0) >= 1
                try:
                    # Биография для уведомления о смерти
                    _days = max(0, int((now - f.get("born_at", now)) / 86400))
                    _hist = []
                    if _days: _hist.append(f"{_days} дн. жизни")
                    if f.get("total_feeds"):      _hist.append(f"{f['total_feeds']} кормлений")
                    if f.get("total_mosquitoes"): _hist.append(f"{f['total_mosquitoes']} комаров")
                    if f.get("total_duel_wins"):  _hist.append(f"{f['total_duel_wins']} побед в дуэлях")
                    _hist_line = " · ".join(_hist) if _hist else "Только начинала жить"

                    death_msg = (
                        f"💀 <b>{fname(f)} погибла.</b>\n\n"
                        f"<i>{_hist_line}</i>\n\n"
                        f"Воскреси её — /revive"
                    )
                    death_kb = None
                    if not _has_sub_death:
                        death_msg += "\n\n<i>Болотная Няня следила бы за ней пока ты был занят.</i>"
                        death_kb = InlineKeyboardMarkup([[
                            btn("🧑‍🍼 Няня · 7 дней · 75⭐", callback_data="sub_buy_nanny_7"),
                        ]])
                    await ctx.bot.send_message(
                        uid_dec,
                        death_msg,
                        parse_mode=ParseMode.HTML,
                        reply_markup=death_kb,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass
        except Exception as _e:
            logger.warning("job_background_decay uid=%s: %s", uid_dec, _e)

    if processed:
        logger.info(
            "job_background_decay: обработано %d игроков, умерло %d, предупреждено %d",
            processed, died, warned,
        )


async def grant_trial(uid: int, sub_type: int, days: int, bot=None, reason: str = "") -> bool:
    """
    Выдаёт пробный период подписки.
    sub_type: 1=Болотная Няня, 2=Трудяга.
    Возвращает True если выдано, False если уже использовано.
    """
    f = await db_get(uid)
    if not f:
        return False
    field = "trial_nanny_used" if sub_type == 1 else "trial_worker_used"
    if f.get(field, 0):
        return False  # уже получал
    now_t = time.time()
    base = max(now_t, f.get("subscription_until", 0))
    f["subscription_until"] = base + days * 86400
    if sub_type == 2 or f.get("subscription_type", 0) < sub_type:
        f["subscription_type"] = sub_type
    f["subscription_auto"] = 1
    f[field] = 1
    # Сбрасываем таймер чтобы первый отчёт пришёл не сразу, а через сутки
    if sub_type == 2:
        f["last_worker_report"] = time.time()
    await db_save(f)
    sub_name = "🧑‍🍼 Болотная Няня" if sub_type == 1 else "🏪 Трудяга"
    if bot:
        try:
            msg = (
                f"{_E_GIFT} <b>Пробный период!</b>\n\n"
                f"{sub_name} активирована на <b>{days} дней</b> бесплатно!\n"
            )
            if reason:
                msg += f"<i>{reason}</i>\n"
            if sub_type == 1:
                msg += f"\n{_E_NANNY} <i>Тётя Жаба уже спешит к твоей лягушке</i>"
            else:
                msg += "\n🏪 <i>Квакуся собирает корзинку — первый выход на рынок уже сегодня!</i>"
            await bot.send_message(uid, msg, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass
    return True


# ── Caps для автоухода — показатели никогда не доводятся до 100% ──
# Игрок всегда может сам покормить/поиграть и получить удовольствие от ухода
AUTO_CARE_CAP = 85   # максимум до которого доводит Няня


async def job_auto_care(ctx: ContextTypes.DEFAULT_TYPE):
    """
    Болотная Няня 🧑‍🍼 — автоматический уход за лягушкой каждые 15 минут.
    Работает для subscription_type >= 1 (Няня и Трудяга).
    НЕ начисляет монеты и XP — только поддерживает параметры.
    Параметры никогда не превышают AUTO_CARE_CAP (85%) — остаётся место для ручного ухода.
    """
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT user_id FROM frogs WHERE alive=1 AND subscription_type >= 1 "
            "AND subscription_until > ? AND subscription_auto = 1",
            (now,),
        ) as c:
            uids = [r[0] for r in await c.fetchall()]

    for uid_ac in uids:
        try:
            f = await db_get(uid_ac)
            if not f or not f.get("alive"):
                continue
            f = decay(f)
            changed = False

            # Кормление: кулдаун 20 минут
            # Используем last_auto_feed — не трогаем last_feed (он для ручного ухода и квестов)
            if now - f.get("last_auto_feed", 0) >= 20 * 60:
                if f["hunger"] < AUTO_CARE_CAP:
                    f["hunger"] = min(AUTO_CARE_CAP, f["hunger"] + 20)
                    f["last_auto_feed"] = now
                    changed = True

            # Игра: кулдаун 20 минут
            # Используем last_auto_play — не трогаем last_play (он для ручного ухода и квестов)
            if now - f.get("last_auto_play", 0) >= 20 * 60:
                if f["happiness"] < AUTO_CARE_CAP:
                    f["happiness"] = min(AUTO_CARE_CAP, f["happiness"] + random.randint(18, 25))
                    f["last_auto_play"] = now
                    changed = True

            # Купание: кулдаун 2 часа
            # Используем last_auto_wash — не трогаем last_wash (он для ручного ухода и квестов)
            if now - f.get("last_auto_wash", 0) >= 2 * 3600:
                if f.get("cleanliness", 100) < AUTO_CARE_CAP:
                    f["cleanliness"] = AUTO_CARE_CAP
                    f["last_auto_wash"] = now
                    changed = True

            # Сон: кулдаун 3 часа
            # Используем last_auto_sleep — не трогаем last_sleep (он для ручного ухода и квестов)
            if now - f.get("last_auto_sleep", 0) >= 3 * 3600:
                if f.get("energy", 100) < AUTO_CARE_CAP:
                    f["energy"] = min(AUTO_CARE_CAP, f.get("energy", 100) + random.randint(30, 45))
                    f["last_auto_sleep"] = now
                    changed = True

            # Лечение: кулдаун 1 час, только до AUTO_CARE_CAP
            # Используем last_auto_heal — не трогаем last_heal (он для ручного ухода и квестов)
            if now - f.get("last_auto_heal", 0) >= 3600 and f["health"] < 60:
                f["health"] = min(AUTO_CARE_CAP, f["health"] + 35)
                f["last_auto_heal"] = now
                changed = True

            if changed:
                await db_save(f)
        except Exception as _e:
            logger.warning("job_auto_care uid=%s: %s", uid_ac, _e)


# ── Трудяга: трёхэтапный рабочий день ────────────────────────────────────────
#
#  Фаза 1 — УТРО  (07:00–09:00 UTC): лягушка уходит на работу.
#    Сообщение: профессия + завязка сцены. Сцена сохраняется в worker_scene_json.
#
#  Фаза 2 — ДЕНЬ  (12:00–14:00 UTC): что-то происходит по ходу работы.
#    Сообщение: событие из сохранённой сцены.
#
#  Фаза 3 — ВЕЧЕР (18:00–20:00 UTC): лягушка возвращается с результатом.
#    Сообщение: итог + начисление монет/статов. Сцена очищается.
#
#  КД: следующий цикл стартует не раньше чем через 20 ч после фазы 3.
# ─────────────────────────────────────────────────────────────────────────────

WORKER_DAILY_BASE_MIN = 300
WORKER_DAILY_BASE_MAX = 400

# Утренние фразы «ушла на работу»
_WORK_MORNING_INTROS = [
    "☀️ Новый день — новые дела!",
    "🌅 Солнце ещё не встало, а {name} уже собирается.",
    "🎒 Портфель собран, термос с болотным чаем налит.",
    "🐸 Рабочий настрой включён. Болото, жди!",
    "💪 Сегодня будет хороший день. {name} чувствует это.",
]

# Дневные фразы «всё ещё на работе»
_WORK_MIDDAY_INTROS = [
    "🕛 Обеденный перерыв. {name} жуёт бутерброд прямо на рабочем месте.",
    "📱 Быстрое сообщение с работы...",
    "🏃 День в самом разгаре!",
    "☕ Кофе-пауза. {name} делится новостями.",
]


def _work_build_scene() -> dict:
    """
    Генерирует полную сцену рабочего дня и возвращает dict со всеми
    компонентами, готовыми для поэтапной отправки.
    Сохраняется в frog["worker_scene_json"].
    """
    prof  = _pick_profession()
    scene = random.choice(prof["scenes"])
    base  = random.randint(
        prof.get("base_coins_min", WORKER_DAILY_BASE_MIN),
        prof.get("base_coins_max", WORKER_DAILY_BASE_MAX),
    )
    earned = int(base * scene.get("mult", 1.0))
    earned = max(200, min(earned, 1200))
    earned += scene.get("bonus_coins", 0)
    return {
        "prof_emoji":   prof["emoji"],
        "prof_name":    prof["profession"],
        "story":        scene["story"],
        "event":        scene["event"],
        "outcome":      scene["outcome"],
        "earned":       earned,
        "bonus_xp":     scene.get("bonus_xp",        0),
        "bonus_hunger": scene.get("bonus_hunger",     0),
        "bonus_happiness": scene.get("bonus_happiness", 0),
        "bonus_health": scene.get("bonus_health",     0),
    }


async def _worker_get_eligible(now: float) -> list[int]:
    """Возвращает user_id всех активных трудяг."""
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT user_id FROM frogs WHERE alive=1 AND subscription_type >= 2 "
            "AND subscription_until > ? AND subscription_auto = 1",
            (now,),
        ) as c:
            return [r[0] for r in await c.fetchall()]


async def job_auto_farm(ctx: ContextTypes.DEFAULT_TYPE):
    """
    Диспетчер трёхфазного рабочего дня. Запускается каждый час.
    Время по Москве (UTC+3).

    07:00–09:00 → фаза 1 (нормальный выход)
    09:00–12:00 → фаза 1 catch-up (проспавшие)
    12:00–14:00 → фаза 2 нормальная + фаза 1 catch-up одновременно
    14:00–18:00 → фаза 1 catch-up (очень поздно вышедшие)
    18:00–20:00 → фаза 3 (возврат с деньгами)
    """
    now      = time.time()
    hour_msk = (datetime.fromtimestamp(now, tz=timezone.utc).hour + 3) % 24

    logger.info("job_auto_farm tick: %02d:xx МСК", hour_msk)

    if 18 <= hour_msk < 20:
        # Вечер — возврат домой
        await _work_phase_evening(now, ctx.bot)

    elif 12 <= hour_msk < 14:
        # Обед — нормальная фаза 2 для тех кто ушёл утром (phase=1)
        await _work_phase_midday(now, ctx.bot)
        # И catch-up для тех кто ещё не выходил (phase=0)
        sent_uids = await _work_phase_morning(now, ctx.bot, catch_up=True)
        if sent_uids:
            ctx.job_queue.run_once(
                lambda c: _work_phase_catchup_midday(now + 1800, c.bot, sent_uids),
                when=1800,
                name="work_catchup_midday",
            )

    elif 7 <= hour_msk < 9:
        # Нормальное утро
        await _work_phase_morning(now, ctx.bot, catch_up=False)

    elif 9 <= hour_msk < 18:
        # Catch-up: вышли позже утреннего окна (phase=0)
        sent_uids = await _work_phase_morning(now, ctx.bot, catch_up=True)
        if sent_uids:
            ctx.job_queue.run_once(
                lambda c: _work_phase_catchup_midday(now + 1800, c.bot, sent_uids),
                when=1800,
                name="work_catchup_midday",
            )


async def _work_send_safe(bot, uid: int, text: str, **kwargs) -> bool:
    """Отправка с retry при TimedOut. Возвращает True если успешно."""
    for attempt in range(3):
        try:
            await bot.send_message(uid, text, **kwargs)
            return True
        except TimedOut:
            wait = 2 ** attempt  # 1, 2, 4 сек
            logger.warning("work send TimedOut uid=%s attempt=%d wait=%ds", uid, attempt+1, wait)
            await asyncio.sleep(wait)
        except (Forbidden, BadRequest):
            return False  # пользователь заблокировал или чат не найден
        except Exception as _e:
            logger.warning("work send uid=%s: %s", uid, _e)
            return False
    return False


async def _work_phase_morning(now: float, bot, catch_up: bool = False) -> list[int]:
    """
    Фаза 1: лягушка уходит на работу.
    catch_up=True — ускоренный режим, другой текст.
    Возвращает список uid которым отправили (для планирования фазы 2 в catch-up).
    """
    sent = []
    for uid in await _worker_get_eligible(now):
        try:
            f = await db_get(uid)
            if not f or not f.get("alive"):
                continue
            if f.get("worker_phase", 0) >= 1:
                continue
            last_report = f.get("last_worker_report", 0)
            if last_report > 0:
                today_msk = datetime.fromtimestamp(now + 3*3600, timezone.utc).strftime("%Y-%m-%d")
                last_msk  = datetime.fromtimestamp(last_report + 3*3600, timezone.utc).strftime("%Y-%m-%d")
                if today_msk == last_msk:
                    continue

            scene = _work_build_scene()
            f["worker_scene_json"] = json.dumps(scene, ensure_ascii=False)
            f["worker_phase"] = 1
            await db_save(f)

            name  = fname(f)
            story = scene["story"].format(name=name)

            if catch_up:
                intro = random.choice([
                    "⏰ Проспала чуть-чуть, но решила всё равно идти!",
                    "🏃 Опоздала — пришлось бежать на работу вприпрыжку.",
                    "😅 Будильник подвёл. Но лягушка не сдаётся!",
                    "🌤️ Поздний старт, зато бодрая.",
                ]).format(name=name)
                footer = "<i>День сжатый — обед придёт скоро, вечером как обычно вернётся 🐸</i>"
            else:
                intro = random.choice(_WORK_MORNING_INTROS).format(name=name)
                footer = "<i>Что-то произойдёт по пути... <tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji></i>"

            ok = await _work_send_safe(
                bot, uid,
                f"🌅 <b>{name} отправляется на работу!</b>\n"
                f"<i>Профессия: {scene['prof_emoji']} {scene['prof_name']}</i>\n\n"
                f"{intro}\n\n"
                f"{story}\n\n"
                f"{footer}",
                parse_mode=ParseMode.HTML,
            )
            if ok:
                sent.append(uid)
                logger.info("work_morning uid=%s catch_up=%s prof=%s", uid, catch_up, scene['prof_name'])
        except Exception as _e:
            logger.warning("work_morning uid=%s: %s", uid, _e)
        await asyncio.sleep(0.3)
    logger.info("work_morning done: sent=%d catch_up=%s", len(sent), catch_up)
    return sent


async def _work_phase_catchup_midday(now: float, bot, uid_list: list[int]):
    """Ускоренная фаза 2: отправляем только конкретным uid через 30 мин после catch-up утра."""
    for uid in uid_list:
        try:
            f = await db_get(uid)
            if not f or not f.get("alive"):
                continue
            if f.get("worker_phase", 0) != 1:
                continue
            scene_raw = f.get("worker_scene_json")
            if not scene_raw:
                continue
            scene = json.loads(scene_raw)
            f["worker_phase"] = 2
            await db_save(f)

            name  = fname(f)
            event = scene["event"].format(name=name)
            await _work_send_safe(
                bot, uid,
                f"{_E_BOLT} <b>Рабочий день в разгаре</b>\n\n"
                f"{event}\n\n"
                f"<i>Вечером в 18:00 МСК вернётся домой <tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji></i>",
                parse_mode=ParseMode.HTML,
            )
        except Exception as _e:
            logger.warning("work_catchup_midday uid=%s: %s", uid, _e)
        await asyncio.sleep(0.3)


async def _work_phase_midday(now: float, bot):
    """Фаза 2 нормального режима: событие в середине рабочего дня."""
    sent = 0
    for uid in await _worker_get_eligible(now):
        try:
            f = await db_get(uid)
            if not f or not f.get("alive"):
                continue
            if f.get("worker_phase", 0) != 1:
                continue
            scene_raw = f.get("worker_scene_json")
            if not scene_raw:
                continue
            scene = json.loads(scene_raw)
            f["worker_phase"] = 2
            await db_save(f)

            name  = fname(f)
            intro = random.choice(_WORK_MIDDAY_INTROS).format(name=name)
            event = scene["event"].format(name=name)
            await _work_send_safe(
                bot, uid,
                f"🕛 <b>Рабочий день в разгаре</b>\n\n"
                f"{intro}\n\n"
                f"{event}\n\n"
                f"<i>Вечером узнаешь, чем всё закончилось <tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji></i>",
                parse_mode=ParseMode.HTML,
            )
            sent += 1
            logger.info("work_midday uid=%s", uid)
        except Exception as _e:
            logger.warning("work_midday uid=%s: %s", uid, _e)
        await asyncio.sleep(0.3)
    logger.info("work_midday done: sent=%d", sent)


async def _work_phase_evening(now: float, bot):
    """Фаза 3: лягушка возвращается, начисляем награду."""
    sent = 0
    for uid in await _worker_get_eligible(now):
        try:
            f = await db_get(uid)
            if not f or not f.get("alive"):
                continue
            if f.get("worker_phase", 0) != 2:
                continue

            scene_raw = f.get("worker_scene_json")
            if not scene_raw:
                continue
            scene = json.loads(scene_raw)

            earned = scene["earned"]
            # Бонус стаи уровень 3: +10% монет с работы
            if f.get("staya_id") and f["staya_id"] in _STAYA_BONUS_CACHE:
                _worker_mult = _STAYA_BONUS_CACHE[f["staya_id"]].get("worker_coins_mult", 1.0)
                if _worker_mult != 1.0:
                    earned = int(earned * _worker_mult)
            f["coins"]     = max(0, f.get("coins",     0)   + earned)
            f["xp"]        = max(0, f.get("xp",        0)   + scene["bonus_xp"])
            f["hunger"]    = max(0, min(100, f.get("hunger",    50) + scene["bonus_hunger"]))
            f["happiness"] = max(0, min(100, f.get("happiness", 50) + scene["bonus_happiness"]))
            f["health"]    = max(0, min(100, f.get("health",   100) + scene["bonus_health"]))
            # Трекинг рабочих дней подряд для достижений worker_week/worker_streak_30
            _prev_report = f.get("last_worker_report", 0)
            _days_gap = (now - _prev_report) / 86400 if _prev_report > 0 else 0
            if _prev_report == 0 or _days_gap <= 2.0:
                # первый отчёт или пришёл вовремя (≤2 дней) — стрик растёт
                f["worker_consec_days"] = f.get("worker_consec_days", 0) + 1
            else:
                # пропуск — сбрасываем стрик
                f["worker_consec_days"] = 1
            # Всего отчётов за всё время — для worker_30days / worker_100days.
            # Стрик для них не годится: он обнуляется при пропуске.
            f["total_worker_days"] = f.get("total_worker_days", 0) + 1
            f["last_worker_report"] = now
            f["worker_phase"]       = 0
            f["worker_scene_json"]  = ""
            await levelup(f, bot)
            # Взнос в котёл стаи — 5% от заработка трудяги
            if f.get("staya_id"):
                cauldron_contrib = max(1, int(earned * STAYA_CAULDRON_PCT))
                asyncio.create_task(staya_add_cauldron(f["staya_id"], cauldron_contrib))
                asyncio.create_task(staya_add_xp(f["staya_id"], 3))
            await db_save(f)

            name    = fname(f)
            outcome = scene["outcome"].format(name=name, earned=earned)

            bonus_parts = []
            if scene["bonus_hunger"]    != 0: bonus_parts.append(f"{_E_FOOD}{scene['bonus_hunger']:+d}")
            if scene["bonus_happiness"] != 0: bonus_parts.append(f"😄{scene['bonus_happiness']:+d}")
            if scene["bonus_health"]    != 0: bonus_parts.append(f"{_E_HEART}{scene['bonus_health']:+d}")
            if scene["bonus_xp"]        != 0: bonus_parts.append(f"{_E_XP}{scene['bonus_xp']:+d}")
            bonus_line = ("  " + "  ".join(bonus_parts)) if bonus_parts else ""

            await _work_send_safe(
                bot, uid,
                f"{scene['prof_emoji']} <b>{name} вернулась с работы!</b>\n\n"
                f"{outcome}\n\n"
                f"{_E_COIN} Принесла домой: <b>+{earned}{_E_COIN}</b>{bonus_line}\n\n"
                f"<i>«Ква! Устала, но довольна!» <tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji></i>",
                parse_mode=ParseMode.HTML,
            )
            sent += 1
            logger.info("work_evening uid=%s earned=%s", uid, earned)
        except Exception as _e:
            logger.warning("work_evening uid=%s: %s", uid, _e)
        await asyncio.sleep(0.3)
    logger.info("work_evening done: sent=%d", sent)


