async def cmd_ttt_group(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/ttt [ставка] — крестики-нолики с другим игроком (только в группе)"""
    if not await group_cmd_guard(update, "ttt", ctx):
        return
    if update.effective_chat.type == "private":
        await update.message.reply_text("❌ Групповые крестики-нолики доступны только в чате!\nИспользуй кнопку ❌ Крестики-нолики → 🤖 Соло vs бот")
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return
    if not f["alive"]:
        await update.message.reply_text("💀 Твоя лягушка мертва! Используй /revive")
        return
    stake = 50
    if ctx.args:
        try:
            stake = int(ctx.args[0])
            if stake < 10 or stake > 500:
                await update.message.reply_text(f"{_E_CROSS} Ставка должна быть от 10 до 500 {_E_COIN}", parse_mode=ParseMode.HTML)
                return
        except ValueError:
            await update.message.reply_text("❌ Укажи число: /ttt 100")
            return
    if f["coins"] < stake:
        await update.message.reply_text(f"💸 Нужно {stake}{coin_emoji()}, у тебя {f['coins']}!", parse_mode=ParseMode.HTML)
        return
    f["coins"] -= stake
    f["coins_spent"] = f.get("coins_spent", 0) + stake
    await db_save(f)
    game_id = f"ttt_{user.id}_{int(time.time())}"
    ctx.bot_data[f"ttt_group_{game_id}"] = {
        "creator": user.id,
        "creator_name": user.first_name,
        "stake": stake,
        "chat_id": update.effective_chat.id,
        "board": [""] * 9,
        "turn": user.id,
        "opponent": None,
        "opponent_name": None,
        "msg_id": None,
    }
    pub_kb = InlineKeyboardMarkup([
        [btn(f"🎮 Принять вызов ({stake}{coin_plain()})", callback_data=f"ttt_join_{game_id}", style="success")],
        [btn("🚫 Отменить вызов", callback_data=f"ttt_cancel_{game_id}", style="danger")],
    ])
    pub_msg = await update.message.reply_text(
        f"{_E_CROSS} <b>{he(user.first_name)}</b> вызывает на крестики-нолики!\n"
        f"Ставка: <b>{stake}{coin_emoji()}</b> с каждого\n"
        f"Победитель заберёт <b>{stake*2}{coin_emoji()}</b>!\n\n"
        f"",
        parse_mode=ParseMode.HTML,
        reply_markup=pub_kb,
    )
    if pub_msg:
        ctx.bot_data[f"ttt_group_{game_id}"]["msg_id"] = pub_msg.message_id


