async def _sacrifice_active_event():
    """Возвращает текущий активный ивент или None."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM events WHERE name=? AND status='active' ORDER BY id DESC LIMIT 1",
            (SACRIFICE_EVENT_NAME,),
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def _sacrifice_participants(event_id: int):
    """Возвращает список {user_id, burned_count} участников ивента."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT user_id, burned_count FROM event_participants WHERE event_id=?",
            (event_id,),
        ) as c:
            return [dict(r) for r in await c.fetchall()]


async def _funnel_active_event():
    """Возвращает текущий активный ивент Воронка или None."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM events WHERE name=? AND status='active' ORDER BY id DESC LIMIT 1",
            (FUNNEL_NAME,),
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def _funnel_participants(event_id: int):
    """Возвращает список участников ивента {user_id, burned_count}."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT user_id, burned_count FROM event_participants WHERE event_id=?",
            (event_id,),
        ) as c:
            return [dict(r) for r in await c.fetchall()]


async def _sacrifice_finish(event_id: int, bot, chat_id: int):
    """Финализирует ивент: выбирает победителя, начисляет награды, публикует итоги."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM events WHERE id=?", (event_id,)
        ) as c:
            ev = await c.fetchone()
        if not ev or ev["status"] != "active":
            return
        # Помечаем как finished сразу (защита от повторного вызова)
        await db.execute(
            "UPDATE events SET status='finished' WHERE id=?", (event_id,)
        )
        await db.commit()

    participants = await _sacrifice_participants(event_id)
    if not participants:
        try:
            await bot.send_message(
                chat_id,
                f"{_E_FIRE} <b>Ивент «{SACRIFICE_EVENT_NAME}» завершён</b>\n\n"
                f"<i>Никто не принёс жертву. Болото молчит…</i>",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    total_bank = ev["total_bank"]

    # Выбор победителя с учётом весов
    weights = [p["burned_count"] for p in participants]
    winner = random.choices(participants, weights=weights, k=1)[0]
    winner_uid = winner["user_id"]

    # Начисляем
    winner_prize = int(total_bank * SACRIFICE_WINNER_PCT)
    others = [p for p in participants if p["user_id"] != winner_uid]
    other_share = 0
    if others:
        remaining = total_bank - winner_prize
        other_share = remaining // len(others)
    elif not others:
        # единственный участник забирает всё
        winner_prize = total_bank

    # Победитель
    wf = await db_get(winner_uid)
    if wf:
        wf["coins"] += winner_prize
        await db_save(wf)
    # Остальные
    for p in others:
        pf = await db_get(p["user_id"])
        if pf:
            pf["coins"] += other_share
            await db_save(pf)

    # Обновляем winner в БД
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE events SET winner_id=? WHERE id=?", (winner_uid, event_id)
        )
        await db.commit()

    # Имя победителя
    winner_name = "Неизвестный"
    winner_tag = ""
    if wf:
        winner_name = wf.get("frog_name") or wf.get("first_name") or "Неизвестный"
        if wf.get("username"):
            winner_tag = f" (@{wf['username']})"

    total_burned = sum(p["burned_count"] for p in participants)

    # Публикуем итоги в чат
    others_line = (
        f"Остальные <b>{len(others)}</b> уч. получили по <b>{other_share}{coin_emoji()}</b>"
        if others else "Единственный участник забрал весь банк."
    )
    try:
        await bot.send_message(
            chat_id,
            f"{_E_TROPHY} <b>Итоги «{SACRIFICE_EVENT_NAME}»!</b>\n\n"
            f"{_E_FIRE} Всего сожжено: <b>{total_burned}</b> эпиков\n"
            f"💰 Общий банк: <b>{total_bank}{coin_emoji()}</b>\n\n"
            f"🎉 Победитель: <b>{he(winner_name)}</b>{winner_tag}\n"
            f"   Получает 30% — <b>{winner_prize}{coin_emoji()}</b>\n\n"
            f"{others_line}\n\n"
            f"<i>Болото благодарит всех участников! <tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji>🔥</i>",
            parse_mode=ParseMode.HTML,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass

    # ЛС победителю
    try:
        await bot.send_message(
            winner_uid,
            f"{_E_TROPHY} <b>Ты выиграл ивент «{SACRIFICE_EVENT_NAME}»!</b>\n\n"
            f"На твой счёт зачислено <b>{winner_prize}{coin_emoji()}</b>\n"
            f"<i>Болото запомнит твою жертву.</i> {_E_FIRE}",
            parse_mode=ParseMode.HTML,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass
    # Анонс крупного выигрыша ивента
    if winner_prize > BIG_WIN_THRESHOLD:
        asyncio.create_task(maybe_big_win_announce(
            bot, he(winner_name), winner_prize,
            f"Ивент «{SACRIFICE_EVENT_NAME}»",
            source_chat_id=wf.get("source_chat_id", 0) if wf else 0,
            uid=wf.get("user_id", 0) if wf else 0,
        ))

    # ЛС остальным
    for p in others:
        try:
            await bot.send_message(
                p["user_id"],
                f"{_E_FIRE} <b>Ивент «{SACRIFICE_EVENT_NAME}» завершён!</b>\n\n"
                f"Победитель: <b>{he(winner_name)}</b>\n"
                f"Твоя доля: <b>+{other_share}{coin_emoji()}</b>\n"
                f"<i>В следующий раз удача улыбнётся тебе</i>",
                parse_mode=ParseMode.HTML,
            )
            await asyncio.sleep(0.05)
        except (BadRequest, Forbidden, TimedOut):
            pass


async def _sacrifice_reminder_job(ctx: ContextTypes.DEFAULT_TYPE):
    """Напоминание за 1 час до конца."""
    data = ctx.job.data
    event_id = data["event_id"]
    chat_id   = data["chat_id"]
    ev = await _sacrifice_active_event()
    if not ev or ev["id"] != event_id:
        return
    parts = await _sacrifice_participants(event_id)
    total_bank = ev["total_bank"]
    try:
        await ctx.bot.send_message(
            chat_id,
            f"⏰ <b>До конца «{SACRIFICE_EVENT_NAME}» остался 1 час!</b>\n\n"
            f"💰 Банк: <b>{total_bank}{coin_emoji()}</b>\n"
            f"{_E_USERS} Участников: <b>{len(parts)}</b>\n\n"
            f"<i>Жги эпики — используй кнопку в сообщении ивента</i>",
            parse_mode=ParseMode.HTML,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass


async def _sacrifice_finish_job(ctx: ContextTypes.DEFAULT_TYPE):
    """Джоб: финализация ивента по таймеру."""
    data = ctx.job.data
    await _sacrifice_finish(data["event_id"], ctx.bot, data["chat_id"])


# ── КОМАНДА /sacrifice_start ──────────────────────────────────────────────
async def cmd_sacrifice_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/sacrifice_start [часов] — запустить ивент (только для админов)."""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("⛔ Только для администраторов.")
        return

    # Проверяем: нет ли уже активного ивента
    existing = await _sacrifice_active_event()
    if existing:
        remaining = int(existing["end_time"] - time.time())
        h, m = divmod(remaining // 60, 60)
        await update.message.reply_text(
            f"⚠️ Ивент уже активен! Заканчивается через {h}ч {m}м.",
        )
        return

    # Длительность
    hours = 24
    if ctx.args:
        try:
            hours = max(1, min(72, int(ctx.args[0])))
        except ValueError:
            pass

    now = time.time()
    end_time = now + hours * 3600
    chat_id = update.effective_chat.id

    async with aiosqlite.connect(DB_PATH) as db:
        cur = await db.execute(
            "INSERT INTO events(name, start_time, end_time, total_bank, status, chat_id, created_at) "
            "VALUES (?,?,?,0,'active',?,?)",
            (SACRIFICE_EVENT_NAME, now, end_time, chat_id, now),
        )
        event_id = cur.lastrowid
        await db.commit()

    kb = InlineKeyboardMarkup([
        [btn("🔥 Участвовать", callback_data=f"sacrifice_join_{event_id}", style="success")],
    ])

    msg = await update.message.reply_text(
        f"{_E_FIRE} <b>Ивент «{SACRIFICE_EVENT_NAME}» начался!</b>\n\n"
        f"⏳ Длительность: <b>{hours} ч</b>\n"
        f"{_E_MONEYBAG} За каждый сожжённый эпик в банк идёт <b>{SACRIFICE_COINS_PER_EPIC}{coin_emoji()}</b>\n"
        f"🎯 30% банка достанется случайному победителю (чем больше сжёг — тем выше шанс)\n"
        f"🤝 60% делится поровну между остальными участниками\n"
        f"🔒 Лимит: до {SACRIFICE_MAX_BURN} эпиков на одного игрока\n\n"
        f"<i>Нажми кнопку чтобы начать жертвоприношение</i>",
        parse_mode=ParseMode.HTML,
        reply_markup=kb,
    )

    # Планируем напоминание за 1 час до конца и финализацию
    reminder_when = hours * 3600 - 3600
    if reminder_when > 60:
        ctx.job_queue.run_once(
            _sacrifice_reminder_job,
            when=reminder_when,
            data={"event_id": event_id, "chat_id": chat_id},
            name=f"sacrifice_remind_{event_id}",
        )
    ctx.job_queue.run_once(
        _sacrifice_finish_job,
        when=hours * 3600,
        data={"event_id": event_id, "chat_id": chat_id},
        name=f"sacrifice_finish_{event_id}",
    )

    # Массовая рассылка уведомлений
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT user_id FROM frogs WHERE alive=1") as c:
            all_uids = [r[0] for r in await c.fetchall()]

    bot_me = await ctx.bot.get_me()
    deep_link = f"https://t.me/{bot_me.username}?start=sacrifice"
    notif_kb = InlineKeyboardMarkup([
        [btn("🔥 Принять участие", url=deep_link, style="success")],
    ])
    sent = 0
    for uid in all_uids:
        try:
            await ctx.bot.send_message(
                uid,
                f"{_E_FIRE} <b>Новый ивент: «{SACRIFICE_EVENT_NAME}»!</b>\n\n"
                f"Сожги эпические облики, пополни общий банк и побори за главный приз!\n\n"
                f"💰 За каждый эпик в банк → <b>{SACRIFICE_COINS_PER_EPIC}{coin_emoji()}</b>\n"
                f"{_E_TROPHY} 30% банка — победителю (рандом по весам)\n"
                f"🤝 60% — поровну всем остальным участникам\n\n"
                f"⏳ Ивент идёт <b>{hours} ч</b>. Не пропусти!",
                parse_mode=ParseMode.HTML,
                reply_markup=notif_kb,
            )
            sent += 1
        except (BadRequest, Forbidden, TimedOut):
            pass
        await asyncio.sleep(0.05)

    await update.message.reply_text(f"📢 Уведомление отправлено {sent} игрокам.")


# ── КОМАНДА /sacrifice_end ────────────────────────────────────────────────
async def cmd_sacrifice_end(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/sacrifice_end — принудительно завершить ивент (только для админов)."""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("⛔ Только для администраторов.")
        return

    ev = await _sacrifice_active_event()
    if not ev:
        await update.message.reply_text("❌ Нет активного ивента.")
        return

    await update.message.reply_text("⏳ Подвожу итоги...")
    # Отменяем запланированные джобы финализации, чтобы не выполнились повторно
    for job_name in (f"sacrifice_finish_{ev['id']}", f"sacrifice_reminder_{ev['id']}"):
        for job in ctx.job_queue.get_jobs_by_name(job_name):
            job.schedule_removal()
    await _sacrifice_finish(ev["id"], ctx.bot, ev["chat_id"] or update.effective_chat.id)


