async def cmd_pgiveaway(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/pgiveaway [kva] <приз текстом> — розыгрыш с текстовым призом.
    Создаёт розыгрыш без списания монет. Приз — произвольный текст (NFT, подарок, Stars и т.д.)
    Ключевое слово "kva" в начале (после команды) включает режим только для квакавших.
    Примеры:
      /pgiveaway NFT Chill Flame
      /pgiveaway kva 100 Stars победителю
    """
    user = update.effective_user
    if update.effective_chat.type == "private":
        await update.message.reply_text("🎁 Розыгрыш можно запустить только в чате!")
        return
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return
    if f.get("banned", 0):
        return
    # Только админы и владельцы чата могут создавать текстовые розыгрыши
    chat_settings = await get_chat_settings(update.effective_chat.id)
    _is_chat_admin = False
    try:
        _cm = await ctx.bot.get_chat_member(update.effective_chat.id, user.id)
        _is_chat_admin = _cm.status in ("administrator", "creator")
    except (BadRequest, Forbidden, TimedOut):
        pass
    if user.id not in ADMIN_IDS and not _is_chat_admin:
        await update.message.reply_text(
            "❌ Текстовые розыгрыши могут создавать только администраторы чата."
        )
        return
    if not ctx.args:
        await update.message.reply_text(
            "Использование:\n"
            "<code>/pgiveaway NFT Chill Flame</code>\n"
            "<code>/pgiveaway kva 100 Stars победителю</code>\n\n"
            "<i>kva в начале — участие только для квакавших</i>",
            parse_mode=ParseMode.HTML,
        )
    kva_only = 0
    args = list(ctx.args)
    if args[0].lower() == "kva":
        kva_only = 1
        args = args[1:]
    if not args:
        await update.message.reply_text("❌ Укажи текст приза после команды.")
        return
    prize_text = " ".join(args)
    chat_id = update.effective_chat.id
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT INTO giveaways(chat_id, creator_id, total_amount, winners_count, "
            "participants, status, created_at, prize_text, kva_only) "
            "VALUES(?,?,?,?,?,?,?,?,?)",
            (chat_id, user.id, 0, 1, "[]", "active", time.time(), prize_text, kva_only),
        )
        await db.commit()
        async with db.execute("SELECT last_insert_rowid()") as c:
            gid = (await c.fetchone())[0]
    kva_note = "\n<i>🐸 Участие только для квакавших в этом чате</i>" if kva_only else ""
    kb = InlineKeyboardMarkup([
        [btn("🎁 Участвовать (0 участников)", callback_data=f"giveaway_join_{gid}", style="success")],
        [btn("⏩ Завершить сейчас", callback_data=f"giveaway_force_{gid}", style="danger")],
    ])
    msg = await update.message.reply_text(
        f"{_E_GIFT} <b>Розыгрыш от {he(user.first_name)}!</b>\n\n"
        f"{_E_GIFT} Приз: <b>{_html.escape(prize_text)}</b>\n"
        f"{_E_USERS} Участников: <b>0</b>"
        f"{kva_note}\n\n"
        f"Нажми кнопку чтобы участвовать!\n"
        f"<i>⏱ Розыгрыш завершится через 5 минут.</i>",
        parse_mode=ParseMode.HTML,
        reply_markup=kb,
    )
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("UPDATE giveaways SET message_id=? WHERE id=?", (msg.message_id, gid))
        await db.commit()
    async def _end_pgiveaway(ct):
        await finalize_giveaway(gid, ct)
    ctx.job_queue.run_once(_end_pgiveaway, 300, name=f"giveaway_{gid}")


async def cmd_giveaway(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/giveaway <сумма> [победителей] — розыгрыш монет в чате"""
    if not await group_cmd_guard(update, "giveaway", ctx):
        return
    if update.effective_chat.type == "private":
        await update.message.reply_text("🎁 Розыгрыш можно запустить только в чате!")
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text(f"Сначала /start {_E_FROG}", parse_mode=ParseMode.HTML)
        return
    if f.get("banned", 0):
        await update.message.reply_text("🚫 Ваш аккаунт заблокирован администрацией.")
        return
    _gw_blocked, _gw_msg = await risk_block_check(user.id, "giveaway")
    if _gw_blocked:
        await update.message.reply_text(_gw_msg)
        return
    _gw_ok, _gw_reason = await check_rate_limit(user.id, "giveaway_create")
    if not _gw_ok:
        await update.message.reply_text(f"{_E_CROSS} Суточный лимит розыгрышей исчерпан.\n{he(_gw_reason)}", parse_mode=ParseMode.HTML)
        return
    if not ctx.args:
        await update.message.reply_text(
            "Пример: <code>/giveaway 100</code> или <code>/giveaway 500 3</code>\n"
            "<i>Второй аргумент — количество победителей (максимум 10)</i>",
            parse_mode=ParseMode.HTML,
        )
        return
    try:
        total = int(ctx.args[0])
        winners_count = int(ctx.args[1]) if len(ctx.args) > 1 else 1
    except ValueError:
        await update.message.reply_text("❌ Сумма и количество победителей должны быть числами!")
        return
    if total < 10:
        await update.message.reply_text(f"{_E_CROSS} Минимальная сумма розыгрыша — 10 {_E_COIN}", parse_mode=ParseMode.HTML)
        return
    if winners_count < 1 or winners_count > 10:
        await update.message.reply_text("❌ Количество победителей: от 1 до 10")
        return
    if f["coins"] < total:
        await update.message.reply_text(
            f"💸 Недостаточно монет!\nУ тебя {f['coins']}{coin_emoji()}, нужно {total}{coin_emoji()}",
            parse_mode=ParseMode.HTML,
        )
        return
    f["coins"] -= total
    f["coins_spent"] = f.get("coins_spent", 0) + total
    f["chat_sponsor_coins"] = f.get("chat_sponsor_coins", 0) + total  # трекинг спонсора
    await db_save(f)
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT INTO giveaways(chat_id, creator_id, total_amount, winners_count, participants, status, created_at) "
            "VALUES(?,?,?,?,?,?,?)",
            (update.effective_chat.id, user.id, total, winners_count, "[]", "active", time.time()),
        )
        await db.commit()
        async with db.execute("SELECT last_insert_rowid()") as c:
            gid = (await c.fetchone())[0]
    kb = InlineKeyboardMarkup([
        [btn("🎁 Участвовать (0 участников)", callback_data=f"giveaway_join_{gid}", style="success")],
        [btn("⏩ Завершить сейчас", callback_data=f"giveaway_force_{gid}", style="danger")],
    ])
    msg = await update.message.reply_text(
        f"{_E_GIFT} <b>Розыгрыш от {he(user.first_name)}!</b>\n\n"
        f"{_E_MONEYBAG} Приз: <b>{total}{coin_emoji()}</b>\n"
        f"{_E_TROPHY} Победителей: <b>{winners_count}</b>\n"
        f"{_E_USERS} Участников: <b>0</b>\n\n"
        f"Нажми кнопку, чтобы участвовать!\n"
        f"<i>⏱ Розыгрыш завершится через 5 минут.</i>",
        parse_mode=ParseMode.HTML,
        reply_markup=kb,
    )
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("UPDATE giveaways SET message_id=? WHERE id=?", (msg.message_id, gid))
        await db.commit()

    async def _finalize(_ctx):
        await finalize_giveaway(gid, _ctx)

    ctx.job_queue.run_once(_finalize, when=300, name=f"giveaway_{gid}")


