FAREWELL_MEMORY_WINDOW = 3600   # 60 мин сбор воспоминаний
FAREWELL_CANDLE_WINDOW = 1800   # 30 мин зажжение свечей


async def farewell_phase2(ctx: ContextTypes.DEFAULT_TYPE):
    """Переход в фазу 2 — ритуал зажжения свечей."""
    fw = ctx.bot_data.get("farewell")
    if not fw or fw.get("phase") != 1:
        return

    fw["phase"] = 2
    fw["revived_uids"] = []   # кто уже использовал бесплатное воскрешение
    chat_id = fw["chat_id"]
    name = fw["frog_name"]

    kb = InlineKeyboardMarkup([
        [btn("🕯️ Зажечь свечу", callback_data=f"farewell_candle_{fw['uid']}")],
        [btn("🌿 Воскресить бесплатно", callback_data=f"farewell_revive_{fw['uid']}", style="success")],
    ])
    try:
        msg = await ctx.bot.send_message(
            chat_id,
            f"🕯️ <b>Церемония прощания начинается!</b>\n\n"
            f"Час воспоминаний завершён. Теперь каждый может зажечь свечу в память о "
            f"<b>{name}</b>.\n\n"
            f"{_E_LEAF} <b>В честь этого события</b> каждый игрок может бесплатно воскресить "
            f"свою лягушку — один раз, пока идёт церемония.\n\n"
            f"<i>Нажми кнопку ниже — огонь будет гореть вечно в болотной книге памяти.</i>",
            parse_mode=ParseMode.HTML,
            reply_markup=kb,
        )
        fw["candle_msg_id"] = msg.message_id
    except (BadRequest, Forbidden, TimedOut):
        pass

    ctx.job_queue.run_once(
        farewell_phase3,
        when=FAREWELL_CANDLE_WINDOW,
        name=f"farewell_phase3_{fw['uid']}",
    )


async def farewell_phase3(ctx: ContextTypes.DEFAULT_TYPE):
    """Финал: книга памяти + выдача наград."""
    fw = ctx.bot_data.get("farewell")
    if not fw or fw.get("phase") != 2:
        return

    fw["phase"] = 3
    chat_id = fw["chat_id"]
    name = fw["frog_name"]
    memories: list[dict] = fw.get("memories", [])
    candles: dict[int, str] = fw.get("candles", {})

    # ── Книга памяти ──────────────────────────────
    memory_lines = ""
    if memories:
        sample = random.sample(memories, min(len(memories), 7))
        memory_lines = "\n".join(f"  — <i>{m['text']}</i> ({m['author']})" for m in sample)
    else:
        memory_lines = "  <i>Болото молчит… но помнит.</i>"

    candle_count = len(candles)
    candle_names = ", ".join(list(candles.values())[:10])
    if len(candles) > 10:
        candle_names += f" и ещё {len(candles) - 10}"

    book_text = (
        f"📖 <b>Книга памяти: {name}</b>\n\n"
        f"{memory_lines}\n\n"
        f"🕯️ Свечи зажгли <b>{candle_count}</b> жителей болота"
        + (f": {candle_names}." if candle_names else ".")
        + "\n\n"
        f"🕊️ <i>Пусть болото помнит своих героев.</i>"
    )

    try:
        await ctx.bot.send_message(chat_id, book_text, parse_mode=ParseMode.HTML)
    except (BadRequest, Forbidden, TimedOut):
        pass

    # ── Награды участникам ────────────────────────
    rewarded_uids: set[int] = set()
    for m in memories:
        rewarded_uids.add(m["uid"])
    rewarded_uids.update(candles.keys())

    for ruid in rewarded_uids:
        try:
            await inv_add(ruid, "tear_of_swamp", 1)
            await ach_grant(ruid, "farewell_witness", ctx.bot)
        except Exception as _e:
            logger.exception("подавлено исключение: %s", _e)

    if rewarded_uids:
        try:
            await ctx.bot.send_message(
                chat_id,
                f"{_E_GIFT} <b>{len(rewarded_uids)}</b> участников церемонии получили памятный предмет "
                f"<b>«Слеза болота»</b> 🫧 и достижение «Хранитель памяти» 🕯️",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass

    # Очищаем состояние
    ctx.bot_data.pop("farewell", None)


async def cmd_farewell(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/farewell @username — запустить прощальную церемонию (только для админов)."""
    if not await group_cmd_guard(update, "farewell", ctx):
        return
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("⛔ Только для администраторов.")
        return

    # Найти цель — ответ на сообщение или @username в аргументе
    target_f = None
    if update.message.reply_to_message:
        tuser = update.message.reply_to_message.from_user
        if tuser:
            target_f = await db_get(tuser.id)
    elif ctx.args:
        uname = ctx.args[0].lstrip("@")
        async with aiosqlite.connect(DB_PATH) as db:
            async with db.execute(
                "SELECT * FROM frogs WHERE username=?", (uname,)
            ) as c:
                row = await c.fetchone()
                if row:
                    target_f = dict(row)

    if not target_f:
        await update.message.reply_text(
            f"{_E_CROSS} Не нашёл лягушку. Ответь на сообщение игрока или укажи: "
            "<code>/farewell @username</code>",
            parse_mode=ParseMode.HTML,
        )
        return

    # Уже идёт церемония?
    if ctx.bot_data.get("farewell") and ctx.bot_data["farewell"].get("phase", 0) < 3:
        await update.message.reply_text("⚠️ Сейчас уже идёт другая церемония. Дождись её завершения.")
        return

    uid = target_f["user_id"]
    frog_name = target_f.get("frog_name") or f"Лягушка {target_f['first_name']}"
    skin = target_f.get("skin", "?")
    level = target_f.get("level", 1)
    born_at = target_f.get("born_at", 0)
    days_lived = int((time.time() - born_at) / 86400) if born_at else 0

    chat_id = update.effective_chat.id

    # Публикуем объявление
    msg = await update.message.reply_text(
        f"🕯️ <b>Сегодня мы прощаемся с легендарной лягушкой</b>\n\n"
        f"{_E_FROG} <b>{he(frog_name)}</b> · облик: {skin}\n"
        f"{_E_XP} Уровень: <b>{level}</b> · прожила <b>{days_lived}</b> дней\n\n"
        f"Она оставила след в нашем болоте. Напишите <b>в ответ на это сообщение</b> "
        f"своё воспоминание — бот соберёт их в книгу памяти.\n\n"
        f"<i>⏳ Через час начнётся церемония прощания.</i>",
        parse_mode=ParseMode.HTML,
    )

    ctx.bot_data["farewell"] = {
        "uid": uid,
        "frog_name": he(frog_name),
        "skin": skin,
        "level": level,
        "days": days_lived,
        "chat_id": chat_id,
        "msg_id": msg.message_id,
        "phase": 1,
        "memories": [],
        "candles": {},
    }

    ctx.job_queue.run_once(
        farewell_phase2,
        when=FAREWELL_MEMORY_WINDOW,
        name=f"farewell_phase2_{uid}",
    )


async def _error_handler(update: object, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Глобальный обработчик ошибок: тихо игнорирует протухшие callback-запросы, все остальные пишет в лог."""
    err = context.error
    if isinstance(err, BadRequest):
        msg = str(err).lower()
        if "query is too old" in msg or "query id is invalid" in msg:
            return  # Пользователь нажал старую кнопку — игнорируем
        if "message is not modified" in msg:
            return  # Двойное нажатие без изменений — игнорируем
    if isinstance(err, Forbidden):
        logger.warning("Bot forbidden (пользователь заблокировал бота): %s", err)
        return
    # Всё остальное — полный traceback в лог
    import traceback as _tb
    import sqlite3 as _sqlite3
    tb_str = "".join(_tb.format_exception(type(err), err, err.__traceback__))
    update_info = ""
    if hasattr(update, "effective_user") and update.effective_user:
        update_info = f" | user={update.effective_user.id}"
    if hasattr(update, "effective_chat") and update.effective_chat:
        update_info += f" | chat={update.effective_chat.id}"
    # Для ошибок БД — подсказка как чинить
    if isinstance(err, _sqlite3.OperationalError):
        err_msg = str(err)
        if "no such table" in err_msg:
            table = err_msg.replace("no such table: ", "").strip()
            logger.error(
                "❌ UNHANDLED EXCEPTION%s\n"
                "🗄️ БД: таблица '%s' не существует. "
                "Проверь миграции в run_sync_migration().\n%s",
                update_info, table, tb_str
            )
            return
        if "no such column" in err_msg:
            col = err_msg.replace("no such column: ", "").strip()
            logger.error(
                "❌ UNHANDLED EXCEPTION%s\n"
                "🗄️ БД: колонка '%s' не существует. "
                "Возможно, БД создана старой версией кода — нужна миграция.\n%s",
                update_info, col, tb_str
            )
            return
    logger.error("❌ UNHANDLED EXCEPTION%s\n%s", update_info, tb_str)




async def cmd_online(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/online — показать количество онлайн-игроков."""
    global _peak_last_save
    now = time.time()
    cutoff_10 = now - 10 * 60
    cutoff_60 = now - 60 * 60

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT COUNT(*) FROM frogs WHERE last_seen >= ? AND alive=1", (cutoff_10,)
        ) as c:
            online_10 = (await c.fetchone())[0] or 0
        async with db.execute(
            "SELECT COUNT(*) FROM frogs WHERE last_seen >= ? AND alive=1", (cutoff_60,)
        ) as c:
            online_60 = (await c.fetchone())[0] or 0
        async with db.execute("SELECT COUNT(*) FROM frogs WHERE alive=1") as c:
            total = (await c.fetchone())[0] or 0

    # Обновляем пиковый онлайн
    _update_peak_online(online_10)
    if now - _peak_last_save > _PEAK_SAVE_INTERVAL:
        await _save_peak_online()

    msg = await update.message.reply_text(
        f"{_E_DOT_GREEN} <b>Онлайн игроков</b>\n\n"
        f"{_E_DOT_GREEN} За 10 мин: <b>{online_10}</b>\n"
        f"{_E_DOT_YELLOW} За час: <b>{online_60}</b>\n"
        f"{_E_FROG} Всего живых: <b>{total}</b>",
        parse_mode=ParseMode.HTML,
    )
    if msg and is_group(update):
        asyncio.create_task(schedule_delete(update.get_bot(), msg.chat.id, msg.message_id))



