    rarity = SKINS.get(skin, {}).get("rarity", "common")
    skin_bonus = 1.0 if rarity == "secret" else (0.5 if rarity == "mythic" else (0.25 if rarity == "legendary" else 0.0))
    nft_bonus = mult - 1.0 - skin_bonus
    rarity_label = R_NAME.get(rarity, rarity)
