# ── /staya — меню стаи ────────────────────────────────────────────────────────
async def cmd_staya(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not await group_cmd_guard(update, "staya", ctx):
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return

    staya = await staya_of_user(user.id)
    if staya:
        members = await staya_get_members(staya["id"])
        lvl = staya["level"]
        upgrade = STAYA_UPGRADES.get(lvl + 1)
        upgrade_line = f"\n⬆️ Следующее улучшение: {upgrade['name']} — {upgrade['cost']}🪙 из котла" if upgrade else "\n🏆 Максимальный уровень болота!"
        role_map = {"chief": "🐸 Вожак", "elder": "🦎 Старейшина", "member": "🐟 Житель"}
        my_role = next((m["role"] for m in members if m["user_id"] == user.id), "member")
        member_lines = "\n".join(
            f"{role_map.get(m['role'],'🐟')} {he(m.get('frog_name') or m.get('first_name','?'))} — ур.{m.get('level',1)}"
            for m in members[:10]
        )
        text = (
            f"{staya['emoji']} <b>Стая «{he(staya['name'])}»</b>\n"
            f"Уровень болота: <b>{lvl}</b> · Котёл: <b>{staya['cauldron']}🪙</b>\n"
            f"Участников: <b>{len(members)}/{staya.get('max_members') or STAYA_MAX_MEMBERS}</b> · Твоя роль: {role_map.get(my_role,'🐟')}\n"
            f"{upgrade_line}\n\n"
            f"<b>Участники:</b>\n{member_lines}"
        )
        kb_rows = [[btn("🎭 События стаи", callback_data="staya_events_view")],
                   [btn("🪙 Пополнить котёл", callback_data="staya_cauldron")]]
        # Война и Столовая — прямо на главном экране если разблокированы
        _main_war_btns = []
        if staya.get("level", 1) >= 5:
            _main_war_btns.append(btn("⚔️ Война", callback_data="war_menu"))
        if staya.get("level", 1) >= 6:
            _main_war_btns.append(btn("🍲 Столовая", callback_data="canteen_menu"))
        if _main_war_btns:
            kb_rows.append(_main_war_btns)
        if my_role in ("chief", "elder"):
            kb_rows.append([btn("⚙️ Управление", callback_data="staya_manage")])
        if my_role == "chief":
            kb_rows.append([btn("🚪 Распустить стаю", callback_data="staya_disband")])
        else:
            kb_rows.append([btn("🚪 Покинуть стаю", callback_data="staya_leave")])
    else:
        text = (
            f"{_E_LEAF} <b>Болотные Стаи</b>\n\n"
            f"Ты не состоишь ни в одной стае.\n\n"
            f"Создай свою за <b>{STAYA_CREATE_COST}{_E_COIN}</b> или вступи по приглашению.\n"
            f"Стая — это болото до 15 лягушек с общим котлом и событиями!\n\n"
            f"У тебя: <b>{f['coins']}{_E_COIN}</b>"
        )
        kb_rows = [
            [btn(f"🌿 Создать стаю ({STAYA_CREATE_COST}🪙)", callback_data="staya_create_start")],
        ]
    await update.message.reply_text(text, parse_mode=ParseMode.HTML,
                                    reply_markup=InlineKeyboardMarkup(kb_rows))


# ── /sosedi — меню соседей ────────────────────────────────────────────────────
async def cmd_sosedi(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not await group_cmd_guard(update, "sosedi", ctx):
        return
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        await update.message.reply_text("Сначала /start 🐸")
        return

    friends = await friend_list(user.id, accepted_only=True)
    pending_in = []
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT fr.*, f2.frog_name, f2.first_name FROM friendships fr "
            "JOIN frogs f2 ON f2.user_id=fr.user_id "
            "WHERE fr.friend_id=? AND fr.pending=1",
            (user.id,),
        ) as c:
            pending_in = [dict(r) for r in await c.fetchall()]

    lines = [f"🐸 <b>Болотные Соседи</b> — {len(friends)} друзей\n"]
    for fr in friends[:15]:
        icon, label = FRIEND_LEVELS.get(fr.get("fr_level", 0), ("🌱", "Знакомые"))
        name = fr.get("frog_name") or fr.get("first_name", "?")
        lines.append(f"{icon} {he(name)} — {label}")

    if pending_in:
        lines.append(f"\n{_E_MAIL} Входящие заявки: {len(pending_in)}")

    lines.append("\n<i>Добавить соседа: /add_soseda @username</i>")
    lines.append("<i>Подарить монеты: /gift @username сумма</i>")
    lines.append("<i>Рыбалка с другом: /fish @username</i>")

    kb = InlineKeyboardMarkup([
        [btn("📬 Заявки", callback_data="sosedi_pending")] if pending_in else [],
        [btn("📖 Летопись", callback_data="letopis_view")],
    ])
    await update.message.reply_text(
        "\n".join(lines), parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([
            *([[btn("📬 Заявки", callback_data="sosedi_pending")]] if pending_in else []),
            [btn("📖 Летопись болота", callback_data="letopis_view")],
        ])
    )


async def cmd_add_soseda(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        return
    args = ctx.args
    if not args:
        await update.message.reply_text("Использование: /add_soseda @username")
        return
    uname = args[0].lstrip("@")
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT user_id, frog_name, first_name FROM frogs WHERE username=?", (uname,)) as c:
            row = await c.fetchone()
    if not row:
        await update.message.reply_text("Лягушка не найдена. Возможно игрок не задал username.")
        return
    target_id, tname, tfirst = row
    if target_id == user.id:
        await update.message.reply_text("Нельзя добавить себя 🐸")
        return
    existing = await friend_get(user.id, target_id)
    if existing:
        await update.message.reply_text("Уже в списке соседей")
        return
    now = time.time()
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "INSERT OR IGNORE INTO friendships(user_id,friend_id,level,xp,created_at,pending) VALUES(?,?,0,0,?,1)",
            (user.id, target_id, now),
        )
        await db.commit()
    tname_disp = tname or tfirst or uname
    await update.message.reply_text(
        f"{_E_CHECK} Заявка отправлена {he(tname_disp)}!\nКак только они примут — станете соседями {_E_LEAF}", parse_mode=ParseMode.HTML
    )
    try:
        my_name = f.get("frog_name") or f.get("first_name") or "Кто-то"
        kb = InlineKeyboardMarkup([[
            btn("✅ Принять", callback_data=f"friend_accept_{user.id}"),
            btn("❌ Отклонить", callback_data=f"friend_decline_{user.id}"),
        ]])
        await ctx.bot.send_message(
            target_id,
            f"🌱 <b>{he(my_name)}</b> хочет стать твоим болотным соседом!\n\n"
            f"Примешь заявку?",
            parse_mode=ParseMode.HTML,
            reply_markup=kb,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass


async def cmd_fish(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Совместная рыбалка с другом."""
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        return
    args = ctx.args
    if not args:
        await update.message.reply_text("Использование: /fish @username\nСовместная рыбалка — ставка 50🪙 каждый.")
        return
    uname = args[0].lstrip("@")
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT user_id, frog_name, first_name FROM frogs WHERE username=?", (uname,)) as c:
            row = await c.fetchone()
    if not row:
        await update.message.reply_text("Лягушка не найдена.")
        return
    target_id, tname, tfirst = row
    fr = await friend_get(user.id, target_id)
    if not fr or fr.get("pending"):
        await update.message.reply_text("Рыбачить можно только с соседями!")
        return
    now = time.time()
    if now - f.get("last_fish", 0) < FISH_COOLDOWN:
        await update.message.reply_text("Уже рыбачили сегодня! Возвращайся завтра 🎣")
        return
    if f["coins"] < FISH_COST:
        await update.message.reply_text(f"Нужно {FISH_COST}🪙 на ставку.")
        return

    my_name = f.get("frog_name") or f.get("first_name") or "Кто-то"
    tname_disp = tname or tfirst or uname
    try:
        kb = InlineKeyboardMarkup([[
            btn("🎣 Принять рыбалку", callback_data=f"fish_accept_{user.id}_{FISH_COST}"),
            btn("❌ Отказать", callback_data=f"fish_decline_{user.id}"),
        ]])
        await ctx.bot.send_message(
            target_id,
            f"🎣 <b>{he(my_name)}</b> зовёт на совместную рыбалку!\n\n"
            f"Ставка: <b>{FISH_COST}{_E_COIN}</b> каждый.\n"
            f"Победитель забирает всё — или выловите что-то вместе!\n\n"
            f"Согласен?",
            parse_mode=ParseMode.HTML,
            reply_markup=kb,
        )
        await update.message.reply_text(
            f"🎣 Приглашение отправлено {he(tname_disp)}!\nЖдём ответа...",
            parse_mode=ParseMode.HTML,
        )
        ctx.bot_data[f"fish_invite_{user.id}"] = {
            "inviter": user.id, "target": target_id,
            "cost": FISH_COST, "created": now,
        }
    except Exception as _e:
        await update.message.reply_text("Не удалось отправить приглашение.")


# ── /letopis — лента событий ──────────────────────────────────────────────────
async def cmd_letopis(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not await group_cmd_guard(update, "letopis", ctx):
        return
    events = await letopis_recent(20)
    if not events:
        await update.message.reply_text("📖 Летопись пуста — болото молчит 🌿")
        return
    lines = [f"{_E_BOOK} <b>Болотная Летопись</b>\n"]
    for ev in events:
        dt = datetime.fromtimestamp(ev["created_at"] + 3*3600, timezone.utc).strftime("%d.%m %H:%M")
        likes = ev.get("like_count", 0)
        like_str = f"  {_E_HEART}{likes}" if likes else ""
        lines.append(f"<i>{dt}</i> {ev['text']}{like_str}")
    await update.message.reply_text(
        "\n".join(lines), parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[
            btn("🔄 Обновить", callback_data="letopis_view"),
        ]]),
    )


# ── Вспомогательная: профиль другой лягушки ──────────────────────────────────
async def _show_frog_profile(bot, requester_uid: int, target_uid: int, send_fn):
    """Показывает профиль лягушки target_uid для пользователя requester_uid."""
    tf = await db_get(target_uid)
    if not tf:
        await send_fn("Лягушка не найдена 🐸")
        return
    name = tf.get("frog_name") or tf.get("first_name") or "Лягушка"
    days = int((time.time() - tf.get("born_at", time.time())) / 86400)
    fr = await friend_get(requester_uid, target_uid)
    fr_level = fr.get("level", 0) if fr and not fr.get("pending") else -1
    fr_icon, fr_label = FRIEND_LEVELS.get(fr_level, ("", "")) if fr_level >= 0 else ("", "")

    pers_key = tf.get("personality", "")
    pers_line = f"\n{PERSONALITIES[pers_key]['emoji']} {PERSONALITIES[pers_key]['name']}" if pers_key in PERSONALITIES else ""
    zodiac = _get_zodiac(tf.get("born_at", time.time()))

    alive_icon = "🐸" if tf.get("alive") else "💀"
    text = (
        f"{alive_icon} <b>{he(name)}</b> ур.{tf.get('level',1)}\n"
        f"{_E_XP} {tf.get('xp',0)} XP · 🪙 {tf.get('coins',0)}\n"
        f"❤️ {tf.get('health',100)}% 🍖 {tf.get('hunger',50)}% 😄 {tf.get('happiness',50)}%\n"
        f"📅 {days} дней на болоте\n"
        f"{zodiac['name']}{pers_line}"
    )
    if fr_level >= 0:
        text += f"\n{fr_icon} {fr_label}"

    buttons = []
    if fr is None:
        buttons.append([btn("🌱 Добавить соседом", callback_data=f"add_friend_{target_uid}")])
    elif fr.get("pending"):
        buttons.append([btn("⏳ Заявка отправлена", callback_data="noop")])
    else:
        # Социальные действия
        soc_row1 = [
            btn("🤗 Обнять",   callback_data=f"social_hug_{target_uid}"),
            btn("✋ Почесать",  callback_data=f"social_scratch_{target_uid}"),
        ]
        soc_row2 = [
            btn("🌟 Похвалить", callback_data=f"social_praise_{target_uid}"),
            btn("🍎 Угостить",  callback_data=f"social_treat_{target_uid}"),
        ]
        soc_row3 = [
            btn("🛁 Помыть",    callback_data=f"social_wash_{target_uid}"),
            btn("💤 Убаюкать",  callback_data=f"social_lullaby_{target_uid}"),
        ]
        buttons += [soc_row1, soc_row2, soc_row3]
        buttons.append([btn("⚔️ Поход вместе", callback_data=f"adv_invite_{target_uid}")])
    buttons.append([btn("🍎 Покормить", callback_data=f"feed_other_{target_uid}")])
    await send_fn(text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(buttons))


