# ── /pohod @username — приглашение в поход ────────────────────────────────────
async def cmd_pohod(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    f = await db_get(user.id)
    if not f or not f.get("alive"):
        await update.message.reply_text("Лягушка мертва или не существует.")
        return
    if f.get("adventure_locked_until", 0) > time.time():
        left = int((f["adventure_locked_until"] - time.time()) / 60)
        await update.message.reply_text(f"{_E_SWORDS} Лягушка уже в походе. До конца: {he(left)} мин.", parse_mode=ParseMode.HTML)
        return
    args = ctx.args
    if not args:
        await update.message.reply_text("Использование: /pohod @username\nОтправляет лягушек в совместный поход!")
        return
    uname = args[0].lstrip("@")
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT user_id, frog_name, first_name FROM frogs WHERE username=?", (uname,)) as c:
            row = await c.fetchone()
    if not row:
        await update.message.reply_text("Лягушка не найдена.")
        return
    target_id, tname, tfirst = row
    if target_id == user.id:
        await update.message.reply_text("Нельзя идти в поход с собой 🐸")
        return
    fr = await friend_get(user.id, target_id)
    if not fr or fr.get("pending") or fr.get("level", 0) < 1:
        await update.message.reply_text("В поход можно ходить только с приятелями и выше\nСначала подружитесь 🌱")
        return
    # Проверяем, нет ли у отправителя уже активного pending-приглашения
    existing_invite = ctx.bot_data.get(f"adv_invite_{user.id}")
    if existing_invite and time.time() - existing_invite.get("created", 0) < 120:
        await update.message.reply_text(
            "⏳ Уже есть активное приглашение в поход\nПодожди ответа или отмены (2 мин)."
        )
        return
    # Проверяем adventure_locked_until у target прямо из БД
    _now_pohod = time.time()
    async with aiosqlite.connect(DB_PATH) as _pdb:
        async with _pdb.execute(
            "SELECT adventure_locked_until, adventure_id FROM frogs WHERE user_id=?",
            (target_id,)
        ) as _pc:
            _trow = await _pc.fetchone()
    if _trow and (_trow[0] and _trow[0] > _now_pohod or _trow[1]):
        tname_disp_early = tname or tfirst or uname
        await update.message.reply_text(
            f"{_E_SWORDS} Лягушка <b>{he(tname_disp_early)}</b> уже в походе — пригласить нельзя.",
            parse_mode=ParseMode.HTML,
        )
        return
    my_name = f.get("frog_name") or f.get("first_name") or "Кто-то"
    tname_disp = tname or tfirst or uname
    ctx.bot_data[f"adv_invite_{user.id}"] = {
        "inviter": user.id, "target": target_id, "created": time.time(),
    }
    try:
        kb = InlineKeyboardMarkup([
            [btn("⚔️ 2 часа", callback_data=f"adv_accept_{user.id}_2"),
             btn("⚔️ 4 часа", callback_data=f"adv_accept_{user.id}_4"),
             btn("⚔️ 8 часов", callback_data=f"adv_accept_{user.id}_8")],
            [btn("❌ Отказать", callback_data=f"adv_decline_{user.id}")],
        ])
        await ctx.bot.send_message(
            target_id,
            f"{_E_SWORDS} <b>{he(my_name)}</b> зовёт в совместный поход!\n\n"
            f"<tg-emoji emoji-id='5341367834935075028'>🐸</tg-emoji> Во время похода лягушки недоступны — ни кормить, ни играть.\n"
            f"📜 Каждые 15–20 мин вы получаете логи о приключениях.\n"
            f"🎲 Будут развилки — нужно принять решение.\n"
            f"{_E_TROPHY} В конце — монеты и XP по итогам!\n\n"
            f"<b>Выбери длительность:</b>",
            parse_mode=ParseMode.HTML,
            reply_markup=kb,
        )
        await update.message.reply_text(
            f"{_E_SWORDS} Приглашение отправлено <b>{he(tname_disp)}</b>!\n"
            f"Ждём ответа... {_E_FROG}",
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        await update.message.reply_text("Не удалось отправить приглашение.")


# ── /bond @username — активировать/показать болотную связь ───────────────────
async def cmd_bond(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    f = await db_get(user.id)
    if not f:
        return
    args = ctx.args
    if not args:
        # Показываем текущую связь
        bonds = await get_user_bonds(user.id)
        if bonds:
            lines = []
            for b in bonds:
                partner = await db_get(b["partner_id"])
                pname = (partner.get("frog_name") or partner.get("first_name") or "?") if partner else "?"
                streak = b.get("streak", 0)
                lines.append(f"💚 <b>{he(pname)}</b> — {_E_FIRE} {streak} дн.")
            await update.message.reply_text(
                f"💚 <b>Болотная Связь</b>\n\n"
                + "\n".join(lines) +
                "\n\n<i>Заходи каждый день чтобы не прервать связь</i>",
                parse_mode=ParseMode.HTML,
            )
        else:
            await update.message.reply_text(
                f"{_E_GREENHEART} <b>Болотная Связь</b>\n\n"
                "У тебя нет активной связи.\n"
                "Используй /bond @username чтобы предложить другу!",
                parse_mode=ParseMode.HTML,
            )
        return
    uname = args[0].lstrip("@")
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute("SELECT user_id, frog_name, first_name FROM frogs WHERE username=?", (uname,)) as c:
            row = await c.fetchone()
    if not row:
        await update.message.reply_text("Лягушка не найдена.")
        return
    target_id, tname, tfirst = row
    fr = await friend_get(user.id, target_id)
    if not fr or fr.get("pending") or fr.get("level", 0) < 2:
        await update.message.reply_text("Болотную Связь можно активировать только с Друзьями (уровень 2)!")
        return
    if f.get("bond_with") == target_id:
        await update.message.reply_text("Вы уже связаны! 💚")
        return
    # Проверяем, что отправитель не в другой активной связи
    if f.get("bond_with") and f.get("bond_with") != target_id:
        await update.message.reply_text(
            "💔 У тебя уже есть активная Болотная Связь\n"
            "Сначала разорви её через меню /plaza → Связь → 💔 Разорвать."
        )
        return
    # Читаем получателя через кеш и проверяем, свободен ли он
    tf = await db_get(target_id)
    if tf and tf.get("bond_with") and tf.get("bond_with") != user.id:
        tf_name = tf.get("frog_name") or tf.get("first_name") or uname
        await update.message.reply_text(
            f"😕 У <b>{he(tf_name)}</b> уже есть активная Болотная Связь.",
            parse_mode=ParseMode.HTML,
        )
        return
    tname_disp = tname or tfirst or uname
    my_name = f.get("frog_name") or f.get("first_name") or "?"
    try:
        kb = InlineKeyboardMarkup([[
            btn("💚 Принять Связь", callback_data=f"bond_accept_{user.id}"),
            btn("❌ Отказать", callback_data=f"bond_decline_{user.id}"),
        ]])
        await ctx.bot.send_message(
            target_id,
            f"💚 <b>{he(my_name)}</b> предлагает Болотную Связь!\n\n"
            f"Заходите вместе каждый день — стрик растёт.\n"
            f"Вехи 7/14/30/100 дней — особые награды обоим! 🌟",
            parse_mode=ParseMode.HTML,
            reply_markup=kb,
        )
        await update.message.reply_text(
            f"💚 Предложение отправлено <b>{he(tname_disp)}</b>!",
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        await update.message.reply_text("Не удалось отправить.")



async def cmd_broadcast_return(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    /broadcast_return — рассылка мёртвым игрокам. Показывает превью и ждёт подтверждения.
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return

    now_br = time.time()
    cutoff  = now_br - 30 * 86400

    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            """SELECT user_id, first_name, frog_name, last_seen
               FROM frogs
               WHERE alive = 0
                 AND banned = 0
                 AND is_bot = 0
                 AND (return_revival_used IS NULL OR return_revival_used = 0)
                 AND last_seen >= ?
                 AND total_feeds > 0
               ORDER BY last_seen DESC""",
            (cutoff,),
        ) as c:
            targets = [dict(r) for r in await c.fetchall()]

    total = len(targets)
    if total == 0:
        await update.message.reply_text("Нет подходящих игроков для рассылки.")
        return

    day7  = sum(1 for r in targets if r["last_seen"] >= now_br - 7  * 86400)
    day14 = sum(1 for r in targets if r["last_seen"] >= now_br - 14 * 86400)

    preview = (
        "🐸 <b>Привет! Твоя лягушка скучает по тебе...</b>\n\n"
        "Она ждёт на болоте уже несколько дней.\n\n"
        "Мы хотим предложить тебе вернуться:\n"
        "🌿 <b>Бесплатное воскрешение</b> — одна кнопка\n"
        "🧑\u200d🍼 <b>3 дня Болотной Няни</b> в подарок — она сама позаботится о лягушке, "
        "пока ты будешь обживаться заново\n\n"
        "<i>Предложение одноразовое.</i>"
    )

    confirm_text = (
        f"📋 <b>Превью рассылки</b>\n"
        "\n"
        f"{preview}\n"
        "\n"
        f"{_E_USERS} <b>Получателей: {total}</b>\n"
        f"  └ умерли ≤7д: <b>{day7}</b>\n"
        f"  └ умерли ≤14д: <b>{day14}</b>\n"
        f"  └ умерли ≤30д: <b>{total}</b>\n\n"
        f"🧑\u200d🍼 3 дня Болотной Няни при нажатии кнопки.\n\n"
        f"Запустить рассылку?"
    )

    ctx.bot_data["broadcast_return_targets"]   = targets
    ctx.bot_data["broadcast_return_requester"] = user.id

    await update.message.reply_text(
        confirm_text,
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[
            btn("\u2705 Запустить", callback_data="broadcast_return_confirm", style="success"),
            btn("\u274c Отмена",    callback_data="broadcast_return_cancel",  style="danger"),
        ]]),
    )


async def _run_broadcast_return(bot, targets: list, status_msg):
    """Внутренняя функция: выполняет саму рассылку после подтверждения."""
    sent   = 0
    failed = 0
    total  = len(targets)

    text_br = (
        f"{_E_FROG} <b>Пока тебя не было, на болоте кое-что поменялось</b>\n\n"
        f"Твоя лягушка на месте. Вернуть её — одна кнопка, бесплатно.\n"
        f"И три дня Няни сверху: она присмотрит, пока ты осваиваешься.\n\n"
        f"<i>Предложение одноразовое.</i>"
    )
    kb_br = InlineKeyboardMarkup([[
        btn("🌿 Воскресить бесплатно", callback_data="return_revive", style="success")
    ]])

    for i, row in enumerate(targets):
        uid_br = row["user_id"]
        sent_ok = False
        for attempt in range(3):
            try:
                await bot.send_message(
                    uid_br, text_br,
                    parse_mode=ParseMode.HTML,
                    reply_markup=kb_br,
                    disable_web_page_preview=True,
                )
                sent_ok = True
                sent += 1
                break
            except Exception as _ex:
                _err = str(_ex)
                if "retry after" in _err.lower() or "flood" in _err.lower():
                    try:
                        import re as _re2
                        _wait = int(_re2.search(r"retry after (\d+)", _err, _re2.I).group(1)) + 1
                    except Exception:
                        _wait = 10
                    logger.warning("broadcast_return: flood %ss (%d/%d)", _wait, i+1, total)
                    await asyncio.sleep(_wait)
                else:
                    failed += 1
                    break

        if (i + 1) % 50 == 0:
            try:
                await status_msg.edit_text(
                    f"📨 Прогресс: {i+1}/{total}\n{_E_CHECK} {sent} {_E_CROSS} {failed}",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass

        await asyncio.sleep(1.5 if (i + 1) % 20 == 0 else 0.35)

    try:
        await status_msg.edit_text(
            f"{_E_CHECK} <b>Рассылка завершена</b>\n\n"
            f"{_E_CHART} Целевых: <b>{total}</b>\n"
            f"📨 Доставлено: <b>{sent}</b>\n"
            f"{_E_BAN} Не доставлено: <b>{failed}</b>",
            parse_mode=ParseMode.HTML,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass


async def cmd_broadcast_nft(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/broadcast_nft — рассылка только держателям NFT (только для админов)."""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return
    text = ""
    if ctx.args:
        text = update.message.text.split(maxsplit=1)[1]
    elif update.message.reply_to_message:
        text = (
            update.message.reply_to_message.text
            or update.message.reply_to_message.caption
            or ""
        )
    if not text:
        await update.message.reply_text(
            "Использование: /broadcast_nft <текст>\nИли ответь на сообщение: /broadcast_nft"
        )
        return

    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
            "SELECT DISTINCT user_id FROM nft_frogs WHERE verified=1"
        ) as c:
            nft_users = [r[0] for r in await c.fetchall()]

    if not nft_users:
        await update.message.reply_text("Нет пользователей с NFT.")
        return

    sent = 0
    failed = 0
    status_msg = await update.message.reply_text(
        f"📢 Рассылка {len(nft_users)} холдерам NFT..."
    )
    sem = asyncio.Semaphore(20)

    async def send_one(uid):
        nonlocal sent, failed
        async with sem:
            try:
                await ctx.bot.send_message(uid, text, parse_mode=ParseMode.HTML)
                sent += 1
            except Exception:
                failed += 1

    await asyncio.gather(*[send_one(u) for u in nft_users])
    try:
        await status_msg.edit_text(
            f"{_E_CHECK} Рассылка NFT-холдерам завершена!\n"
            f"📨 Доставлено: {he(sent)}\n{_E_CROSS} Не доставлено: {he(failed)}", parse_mode=ParseMode.HTML
        )
    except (BadRequest, Forbidden, TimedOut):
        pass



# ══════════════════════════════════════════════════════════════════════════════
# 🎮 ГРУППОВЫЕ МИНИ-ИГРЫ
# ══════════════════════════════════════════════════════════════════════════════
# Принципы:
#   • Игры с двумя игроками: оба ставят монеты, победитель берёт банк целиком.
#   • game_id — HEX-строка без подчёркиваний внутри → callback_data безопасен.
#   • Парсинг callback: prefix(4 символа) + gid, параметры через "|".
# ══════════════════════════════════════════════════════════════════════════════

import copy as _copy


def _new_gid(uid: int) -> str:
    """8-символьный hex ID без подчёркиваний внутри."""
    return format((uid * 1000003 + int(time.time())) & 0xFFFFFFFF, "08x")


# ══════════════════════════════════════════════════════════════════════════════
# ♟️  ШАШКИ (CHECKERS)  — /checkers
#   Режим 1: vs БОТ — выбираешь сторону, без ставок
#   Режим 2: vs ИГРОК — ставка обязательна, вызов в чат
#
#   Доска 8×8 целиком в инлайн-кнопках. Нет текстового рендера.
#   ⚫🔵 = чёрные/дамка  ⚪🟡 = белые/дамка
#   🔲 = выбранная фигура  ✅ = доступный ход
#   🟫 = светлая клетка (недоступна)  . = тёмная пустая / ход недоступен
# ══════════════════════════════════════════════════════════════════════════════

def _chk_board():
    b = [[0] * 8 for _ in range(8)]
    for r in range(3):
        for c in range(8):
            if (r + c) % 2 == 1:
                b[r][c] = 1   # чёрные — ходят вниз
    for r in range(5, 8):
        for c in range(8):
            if (r + c) % 2 == 1:
                b[r][c] = 2   # белые — ходят вверх
    return b


# Emoji для клеток
_CK_P = {1: "⚫", 2: "⚪", 3: "🔵", 4: "🟡"}


def _chk_moves(board, player):
    """
    Полные русские правила шашек:
    - Взятие ОБЯЗАТЕЛЬНО (если есть хоть одно — только взятия)
    - Обычная шашка ходит только ВПЕРЁД, но БЬЁТ в любую сторону (вперёд и назад)
    - Дамка ходит по диагонали на ЛЮБОЕ расстояние
    - Дамка бьёт через любое расстояние и может встать на любую клетку за сбитой
    """
    opp = 2 if player == 1 else 1
    all_dirs = [(1,-1),(1,1),(-1,-1),(-1,1)]
    caps, moves = [], []

    for r in range(8):
        for c in range(8):
            v = board[r][c]
            if player == 1 and v not in (1, 3): continue
            if player == 2 and v not in (2, 4): continue
            king = v in (3, 4)

            if king:
                # Дамка: летит по диагонали на любое расстояние
                for dr, dc in all_dirs:
                    found_opp = None  # координаты первого встреченного противника
                    dist = 1
                    while True:
                        nr, nc = r + dr * dist, c + dc * dist
                        if not (0 <= nr < 8 and 0 <= nc < 8):
                            break
                        cv = board[nr][nc]
                        if cv == 0:
                            if found_opp:
                                # За противником — можно встать (взятие)
                                caps.append((r, c, nr, nc, found_opp))
                            else:
                                # Свободная клетка до противника — обычный ход
                                moves.append((r, c, nr, nc, None))
                        elif cv in (opp, opp + 2):
                            if found_opp is not None:
                                break  # два противника на одной диагонали — стоп
                            found_opp = (nr, nc)
                        else:
                            break  # своя шашка — стоп
                        dist += 1
            else:
                # Обычная шашка: ходит только вперёд
                fwd = [(1,-1),(1,1)] if player == 1 else [(-1,-1),(-1,1)]
                for dr, dc in fwd:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 8 and board[nr][nc] == 0:
                        moves.append((r, c, nr, nc, None))
                # Бьёт во ВСЕ 4 стороны
                for dr, dc in all_dirs:
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < 8 and 0 <= nc < 8): continue
                    if board[nr][nc] in (opp, opp + 2):
                        jr, jc = nr + dr, nc + dc
                        if 0 <= jr < 8 and 0 <= jc < 8 and board[jr][jc] == 0:
                            caps.append((r, c, jr, jc, (nr, nc)))

    # ОБЯЗАТЕЛЬНОЕ ВЗЯТИЕ: если есть хоть одно взятие — только взятия
    return caps if caps else moves


def _chk_caps_from(board, player, r, c):
    """Только взятия с конкретной клетки (для цепного боя)."""
    v = board[r][c]
    opp = 2 if player == 1 else 1
    all_dirs = [(1,-1),(1,1),(-1,-1),(-1,1)]
    caps = []

    if v in (3, 4):  # дамка
        for dr, dc in all_dirs:
            found_opp = None
            dist = 1
            while True:
                nr, nc = r + dr * dist, c + dc * dist
                if not (0 <= nr < 8 and 0 <= nc < 8): break
                cv = board[nr][nc]
                if cv == 0:
                    if found_opp:
                        caps.append((r, c, nr, nc, found_opp))
                elif cv in (opp, opp + 2):
                    if found_opp is not None: break
                    found_opp = (nr, nc)
                else:
                    break
                dist += 1
    else:  # обычная шашка бьёт в любую сторону
        for dr, dc in all_dirs:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < 8 and 0 <= nc < 8): continue
            if board[nr][nc] in (opp, opp + 2):
                jr, jc = nr + dr, nc + dc
                if 0 <= jr < 8 and 0 <= jc < 8 and board[jr][jc] == 0:
                    caps.append((r, c, jr, jc, (nr, nc)))
    return caps


def _chk_apply(board, fr, fc, tr, tc, cap):
    """Применяет ход. cap = (r,c) сбитой шашки или None."""
    b = _copy.deepcopy(board)
    v = b[fr][fc]
    b[tr][tc] = v
    b[fr][fc] = 0
    if cap:
        b[cap[0]][cap[1]] = 0
    # Превращение в дамку (только обычные шашки)
    if v == 1 and tr == 7: b[tr][tc] = 3   # чёрная дамка
    if v == 2 and tr == 0: b[tr][tc] = 4   # белая дамка
    # Дамки (v=3,4) остаются дамками — уже записаны как v
    return b


def _chk_count(board):
    p1 = sum(1 for r in board for v in r if v in (1, 3))
    p2 = sum(1 for r in board for v in r if v in (2, 4))
    return p1, p2


def _chk_score(board, player):
    """
    Улучшенная оценка позиции для минимакса.
    Учитывает: материал, дамки, продвижение, центр, защиту краёв, угрозы взятия.
    """
    opp = 2 if player == 1 else 1
    score = 0
    opp_caps = {(m[2], m[3]) for m in _chk_moves(board, opp) if m[4]}  # клетки под ударом

    for r in range(8):
        for c in range(8):
            v = board[r][c]
            if v == 0:
                continue
            is_mine = (v in (1, 3) and player == 1) or (v in (2, 4) and player == 2)
            is_king = v in (3, 4)
            sign = 1 if is_mine else -1

            # Базовая стоимость
            piece_val = 5 if is_king else 3
            score += sign * piece_val

            # Продвижение к дамке
            if not is_king:
                adv = r if player == 1 else (7 - r)
                score += sign * adv * 0.15

            # Центральные клетки (3,3),(3,4),(4,3),(4,4) — стратегически важны
            if (r in (3, 4)) and (c in (3, 4)):
                score += sign * 0.4
            elif (r in (2, 5)) and (c in (2, 3, 4, 5)):
                score += sign * 0.2

            # Защищённость края (с == 0 или с == 7 — безопаснее от срубания)
            if c in (0, 7):
                score += sign * 0.3

            # Штраф за нахождение под ударом
            if is_mine and (r, c) in opp_caps:
                score -= 2.5

    # Бонус за количество доступных ходов (мобильность)
    my_moves = len(_chk_moves(board, player))
    opp_moves = len(_chk_moves(board, opp))
    score += (my_moves - opp_moves) * 0.1

    return score


def _chk_minimax(board, player, depth, alpha, beta, maximizing):
    """Минимакс глубиной 7 с улучшенной альфа-бета отсечкой."""
    moves = _chk_moves(board, player)
    p1, p2 = _chk_count(board)
    if not moves or p1 == 0 or p2 == 0 or depth == 0:
        base_player = player if maximizing else (2 if player == 1 else 1)
        return _chk_score(board, base_player), None

    opp = 2 if player == 1 else 1
    best_move = None

    # Сортировка: взятия сначала (улучшает отсечку)
    moves_sorted = sorted(moves, key=lambda m: (0 if m[4] else 1))

    if maximizing:
        best = -float('inf')
        for m in moves_sorted:
            nb = _chk_apply(board, *m)
            # Цепное взятие: если после хода ещё можно рубить той же шашкой — продолжаем
            if m[4]:
                chain = _chk_caps_from(nb, player, m[2], m[3])
                if chain:
                    val, _ = _chk_minimax(nb, player, depth - 1, alpha, beta, True)
                else:
                    val, _ = _chk_minimax(nb, opp, depth - 1, alpha, beta, False)
            else:
                val, _ = _chk_minimax(nb, opp, depth - 1, alpha, beta, False)
            if val > best:
                best = val
                best_move = m
            alpha = max(alpha, best)
            if beta <= alpha:
                break
        return best, best_move
    else:
        best = float('inf')
        for m in moves_sorted:
            nb = _chk_apply(board, *m)
            if m[4]:
                chain = _chk_caps_from(nb, player, m[2], m[3])
                if chain:
                    val, _ = _chk_minimax(nb, player, depth - 1, alpha, beta, False)
                else:
                    val, _ = _chk_minimax(nb, opp, depth - 1, alpha, beta, True)
            else:
                val, _ = _chk_minimax(nb, opp, depth - 1, alpha, beta, True)
            if val < best:
                best = val
                best_move = m
            beta = min(beta, best)
            if beta <= alpha:
                break
        return best, best_move


def _chk_bot_move(board, bot_player):
    """Выбирает лучший ход для бота через минимакс глубиной 7.
    СИНХРОННАЯ функция — вызывать через run_in_executor чтобы не блокировать event loop."""
    _, move = _chk_minimax(board, bot_player, 7, -float('inf'), float('inf'), True)
    if move is None:
        moves = _chk_moves(board, bot_player)
        move = random.choice(moves) if moves else None
    return move


async def _chk_bot_move_async(board, bot_player):
    """Асинхронная обёртка — запускает тяжёлый minimax в thread pool."""
    loop = asyncio.get_event_loop()
    import functools
    return await loop.run_in_executor(None, functools.partial(_chk_bot_move, board, bot_player))


def _chk_board_kb(gid, board, player, phase, sel=None, locked=False, lang="ru"):
    """
    Доска 8×8 как инлайн-кнопки.
    locked=True — все кнопки noop (ход бота, ждём).
    """
    if not locked:
        all_moves = _chk_moves(board, player)
        moveable = {(m[0], m[1]) for m in all_moves}
        targets = set()
        if sel and phase == "move":
            targets = {(m[2], m[3]) for m in all_moves if m[0] == sel[0] and m[1] == sel[1]}
        # Тёмные пустые клетки куда есть хоть один ход (точки-подсказки)
        reachable_empty = {(m[2], m[3]) for m in all_moves if m[4] is None}
        # При взятии точки показываем только цели взятия
        if any(m[4] for m in all_moves):
            reachable_empty = set()  # при обязательном взятии не показываем обычные ходы
    else:
        moveable = targets = reachable_empty = set()

    rows = []
    for r in range(8):
        row = []
        for c in range(8):
            v = board[r][c]
            is_dark = (r + c) % 2 == 1
            cell = (r, c)

            if not locked and sel and cell == sel:
                lbl, cb = "🔲", f"ckc|{gid}"
            elif not locked and is_dark and cell in targets:
                lbl, cb = "✅", f"ckm|{gid}|{r}|{c}"
            elif not locked and is_dark and phase == "select" and cell in moveable:
                lbl = _CK_P.get(v, "·")
                cb = f"cks|{gid}|{r}|{c}"
            elif not is_dark:
                lbl, cb = " ", "noop"
            elif v != 0:
                lbl, cb = _CK_P.get(v, "·"), "noop"
            elif not locked and phase == "select" and cell in reachable_empty:
                lbl, cb = "·", "noop"
            else:
                lbl, cb = " ", "noop"

            row.append(btn(lbl, callback_data=cb))
        rows.append(row)

    rows.append([
        btn(t("chk_offer_draw", lang), callback_data=f"ckd|{gid}", style="success"),
        btn("🏳️", callback_data=f"ckg|{gid}", style="danger"),
    ])
    return InlineKeyboardMarkup(rows)


def _chk_header(gd):
    """Заголовок сообщения с состоянием игры."""
    t = gd["turn"]
    mode = gd.get("mode", "pvp")
    human_name = _html.escape(gd["p1n"])

    if mode == "bot":
        human_p = gd.get("human_player", 1)
        # Определяем кто за какой цвет
        if human_p == 1:
            black_name, white_name = human_name, "🤖 Бот"
        else:
            black_name, white_name = "🤖 Бот", human_name

        players_line = f"Играют: {black_name} ⚫ vs {white_name} ⚪"

        # Чей сейчас ход?
        if t == human_p:
            cur_name = human_name
        else:
            cur_name = "🤖 Бот"
        icon = "⚫" if t == 1 else "⚪"
        turn_line = f"Ходит: <b>{cur_name} {icon}</b>"
    else:
        # PvP: p1 всегда ⚫, p2 всегда ⚪
        p1n = human_name
        p2n = _html.escape(gd.get("p2n") or "?")
        players_line = f"Играют: {p1n} ⚫ vs {p2n} ⚪"
        cur_name = p1n if t == 1 else p2n
        icon = "⚫" if t == 1 else "⚪"
        turn_line = f"Ходит: <b>{cur_name} {icon}</b>"

    return f"<b>♟️ Шашки</b>\n\n{players_line}\n\n{turn_line}"


async def cmd_games(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/games — тот же экран игр, что и по кнопке."""
    f = await db_get(update.effective_user.id)
    if not f:
        await update.message.reply_text(f"Сначала /start {_E_FROG}", parse_mode=ParseMode.HTML)
        return
    text, kb = await games_screen(f, update.effective_chat.type == "private")
    await update.message.reply_text(
        text,
        parse_mode=ParseMode.HTML,
        reply_markup=kb,
        link_preview_options=LinkPreviewOptions(is_disabled=True),
    )


async def cmd_checkers(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/checkers — шашки: против бота или против игрока со ставкой"""
    if update.effective_chat.type == "private":
        # В личке — только vs бот
        user = update.effective_user
        f = await db_get(user.id)
        if not f: await update.message.reply_text(f"Сначала /start {_E_FROG}", parse_mode=ParseMode.HTML); return
        if not f.get("alive", 1): await update.message.reply_text(f"{_E_SKULL} Лягушка мертва! /revive", parse_mode=ParseMode.HTML); return
        kb = InlineKeyboardMarkup([
            [btn(t("chk_play_black", f), callback_data="ck_side|black", style="primary"),
             btn(t("chk_play_white", f), callback_data="ck_side|white", style="primary")],
        ])
        msg = await update.message.reply_text(
            f"{_E_CHESS} <b>Шашки vs Бот</b>",
            parse_mode=ParseMode.HTML, reply_markup=kb,
        )
        ctx.bot_data.setdefault("msg_owner", {})[f"{update.effective_chat.id}_{msg.message_id}"] = user.id
        return

    # В группе — показываем меню режима
    user = update.effective_user
    f = await db_get(user.id)
    if not f: await update.message.reply_text(f"Сначала /start {_E_FROG}", parse_mode=ParseMode.HTML); return
    if not f.get("alive", 1): await update.message.reply_text(f"{_E_SKULL} Лягушка мертва! /revive", parse_mode=ParseMode.HTML); return

    kb = InlineKeyboardMarkup([
        [btn(t("btn_chk_solo", f), callback_data="ck_mode|bot", style="primary"),
         btn(t("btn_chk_pvp", f), callback_data="ck_mode|pvp", style="success")],
        [btn(t("btn_back_games", f), callback_data="menu_games")],
    ])
    msg = await update.message.reply_text(
        f"{_E_CHESS} <b>Шашки</b>",
        parse_mode=ParseMode.HTML, reply_markup=kb,
    )
    ctx.bot_data.setdefault("msg_owner", {})[f"{update.effective_chat.id}_{msg.message_id}"] = user.id


def _chk_new_game(gid, user, mode, human_player=1, stake=0, chat_id=None):
    return {
        "board": _chk_board(),
        "p1": user.id, "p1n": user.first_name,
        "p2": None, "p2n": None,
        # По правилам русских шашек первыми ходят БЕЛЫЕ (player=2)
        "turn": 2, "phase": "select", "sel": None,
        "mode": mode,
        "human_player": human_player,
        "stake": stake,
        "chat_id": chat_id,
    }


async def _chk_do_bot_move(gid, gd, q, ctx):
    """Выполняет ход бота и обновляет сообщение."""
    bot_p = gd.get("bot_player", 2)
    move = await _chk_bot_move_async(gd["board"], bot_p)
    if not move:
        # Бот не может ходить — игрок победил
        human_p = gd.get("human_player", 1)
        h_name = _html.escape(gd["p1n"])
        ctx.bot_data.pop(f"chk|{gid}", None)
        try:
            await q.message.edit_text(
                f"♟️ <b>Шашки vs Бот</b>\n\n{_E_TROPHY} <b>{h_name}</b> победил(а)!\nБот не может ходить.",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # Выполняем ход (с поддержкой цепного взятия)
    while True:
        gd["board"] = _chk_apply(gd["board"], *move)
        p1, p2 = _chk_count(gd["board"])
        if p1 == 0 or p2 == 0:
            break
        if move[4]:  # было взятие — проверяем цепное
            chain = _chk_caps_from(gd["board"], bot_p, move[2], move[3])
            if chain:
                move = chain[0]
                continue
        break

    # Проверяем победу
    p1, p2 = _chk_count(gd["board"])
    next_m = _chk_moves(gd["board"], gd.get("human_player", 1))
    finished = not next_m or p1 == 0 or p2 == 0

    if finished:
        # Кто победил
        human_p = gd.get("human_player", 1)
        if (human_p == 1 and p1 == 0) or (human_p == 2 and p2 == 0) or not next_m:
            result = "🤖 <b>Бот победил!</b> Попробуй ещё раз."
        else:
            result = f"{_E_TROPHY} <b>{_html.escape(gd['p1n'])}</b> победил(а)!"
        ctx.bot_data.pop(f"chk|{gid}", None)
        try:
            await q.message.edit_text(
                f"♟️ <b>Шашки vs Бот завершены!</b>\n\n{result}",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # Возвращаем ход игроку
    gd["turn"] = gd.get("human_player", 1)
    gd["phase"] = "select"
    gd["sel"] = None
    kb = _chk_board_kb(gid, gd["board"], gd["turn"], "select")
    try:
        await q.message.edit_text(
            _chk_header(gd),
            parse_mode=ParseMode.HTML, reply_markup=kb,
        )
    except (BadRequest, Forbidden, TimedOut):
        pass


async def handle_checkers_callback(q, d, uid, ctx):
    parts = d.split("|")
    action = parts[0]

    # ── Выбор режима (в группе) ──────────────────────────────────────────────
    if action == "ck_mode":
        mode = parts[1]
        user = q.from_user
        f = await db_get(uid)
        if not f: await q.answer("Сначала /start 🐸", show_alert=True); return
        if not f.get("alive", 1): await q.answer("💀 Лягушка мертва! /revive", show_alert=True); return

        if mode == "bot":
            await q.answer()
            kb = InlineKeyboardMarkup([
                [btn(t("chk_play_black", f), callback_data="ck_side|black", style="primary"),
                 btn(t("chk_play_white", f), callback_data="ck_side|white", style="primary")],
                [btn("◀️ Назад", callback_data="ck_mode|back")],
            ])
            try:
                await q.message.edit_text(
                    f"{_E_CHESS} <b>Шашки vs Бот</b>",
                    parse_mode=ParseMode.HTML, reply_markup=kb,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
        elif mode == "pvp":
            await q.answer()
            stakes = [25, 50, 100, 200]
            kb = InlineKeyboardMarkup([
                [btn(f"💰 {s}🪙", callback_data=f"ck_stake|{s}") for s in stakes],
                [btn("◀️ Назад", callback_data="ck_mode|back")],
            ])
            try:
                await q.message.edit_text(
                    f"{_E_CHESS} <b>Шашки vs Игрок</b>\n\nВыбери ставку (с каждого):",
                    parse_mode=ParseMode.HTML, reply_markup=kb,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
        elif mode == "back":
            await q.answer()
            kb = InlineKeyboardMarkup([
                [btn(t("btn_chk_solo", f), callback_data="ck_mode|bot", style="primary"),
                 btn(t("btn_chk_pvp", f), callback_data="ck_mode|pvp", style="success")],
                [btn(t("btn_back_games", f), callback_data="menu_games")],
            ])
            try:
                await q.message.edit_text(
                    f"{_E_CHESS} <b>Шашки</b>",
                    parse_mode=ParseMode.HTML, reply_markup=kb,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
        return

    # ── Выбор ставки PvP ────────────────────────────────────────────────────
    if action == "ck_stake":
        stake = int(parts[1])
        user = q.from_user
        f = await db_get(uid)
        if not f: await q.answer("Сначала /start 🐸", show_alert=True); return
        if f["coins"] < stake:
            await q.answer((f"Нужно {stake}🪙, у тебя {f['coins']}🪙")[:200], show_alert=True); return
        f["coins"] -= stake
        f["coins_spent"] = f.get("coins_spent", 0) + stake
        await db_save(f)
        gid = _new_gid(uid)
        gd = _chk_new_game(gid, user, "pvp", stake=stake, chat_id=q.message.chat.id)
        ctx.bot_data[f"chk|{gid}"] = gd
        await q.answer(f"✅ Ставка {stake}🪙 внесена")
        kb = InlineKeyboardMarkup([
            [btn(f"♟️ Принять вызов ({stake}🪙)", callback_data=f"ckj|{gid}", style="success")],
            [btn("🚫 Отменить вызов", callback_data=f"ckg|{gid}", style="danger")],
        ])
        try:
            await q.message.edit_text(
                f"♟️ <b>{_html.escape(user.first_name)}</b> вызывает на шашки!\n"
                f"Ставка: <b>{stake}{_E_COIN}</b> с каждого · банк: <b>{stake * 2}{_E_COIN}</b>\n\n"
                f"{_E_DOT_BLACK} чёрные · {_E_DOT_WHITE} белые\n{_E_DOT_BLUE}{_E_DOT_YELLOW} дамки · {_E_CHECK} ход",
                parse_mode=ParseMode.HTML, reply_markup=kb,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Выбор стороны (vs бот) ───────────────────────────────────────────────
    if action == "ck_side":
        side = parts[1]  # "black" or "white"
        user = q.from_user
        f = await db_get(uid)
        if not f: await q.answer("Сначала /start 🐸", show_alert=True); return
        if not f.get("alive", 1): await q.answer("💀 Лягушка мертва! /revive", show_alert=True); return
        human_player = 1 if side == "black" else 2
        bot_player = 2 if side == "black" else 1
        gid = _new_gid(uid)
        gd = _chk_new_game(gid, user, "bot", human_player=human_player,
                           chat_id=q.message.chat.id)
        gd["bot_player"] = bot_player
        gd["p2n"] = "🤖 Бот"
        # Белые ходят первыми. Если человек за чёрных — бот (белые) делает первый ход
        gd["turn"] = 2  # белые всегда первые
        if bot_player == 2:  # бот = белые → сразу делаем ход бота
            move = await _chk_bot_move_async(gd["board"], 2)
            if move:
                gd["board"] = _chk_apply(gd["board"], *move)
            gd["turn"] = 1  # теперь ход человека (чёрные)
        ctx.bot_data[f"chk|{gid}"] = gd
        gd["phase"] = "select"
        kb = _chk_board_kb(gid, gd["board"], gd["turn"], "select")
        await q.answer("✅ Игра начата")
        try:
            await q.message.edit_text(
                _chk_header(gd),
                parse_mode=ParseMode.HTML, reply_markup=kb,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Вступление в игру PvP ────────────────────────────────────────────────
    if action == "ckj":
        gid = parts[1]
        gd = ctx.bot_data.get(f"chk|{gid}")
        if not gd: await q.answer("Игра не найдена", show_alert=True); return
        if gd["phase"] != "join" or gd.get("p2") is not None:
            await q.answer("Игра уже началась", show_alert=True); return
        if uid == gd["p1"]: await q.answer("Нельзя играть с собой", show_alert=True); return
        f2 = await db_get(uid)
        if not f2: await q.answer("Сначала /start 🐸", show_alert=True); return
        if not f2.get("alive", 1): await q.answer("💀 Лягушка мертва! /revive", show_alert=True); return
        stake = gd["stake"]
        if f2["coins"] < stake:
            await q.answer((f"Нужно {stake}🪙 для принятия вызова")[:200], show_alert=True); return
        f2["coins"] -= stake
        f2["coins_spent"] = f2.get("coins_spent", 0) + stake
        await db_save(f2)
        gd["p2"] = uid
        gd["p2n"] = f2.get("first_name", "?")
        gd["phase"] = "select"
        # Белые (p2) ходят первыми по правилам русских шашек (turn: 1=чёрные/p1, 2=белые/p2)
        gd["turn"] = 2
        await q.answer(f"✅ Принято. Ставка {stake}🪙 внесена.")
        kb = _chk_board_kb(gid, gd["board"], gd["turn"], "select")
        try:
            await q.message.edit_text(
                _chk_header(gd),
                parse_mode=ParseMode.HTML, reply_markup=kb,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Выбор шашки ──────────────────────────────────────────────────────────
    if action == "cks":
        gid, fr, fc = parts[1], int(parts[2]), int(parts[3])
        gd = ctx.bot_data.get(f"chk|{gid}")
        if not gd: await q.answer("Игра не найдена", show_alert=True); return
        # Проверка прав
        if gd["mode"] == "pvp":
            cur_p = gd["p1"] if gd["turn"] == 1 else gd["p2"]
            if uid != cur_p: await q.answer("Сейчас не твой ход!", show_alert=True); return
        else:
            if uid != gd["p1"]: await q.answer("Это не твоя игра!", show_alert=True); return
            if gd["turn"] != gd.get("human_player", 1):
                await q.answer("Сейчас ходит бот", show_alert=True); return
        moves = _chk_moves(gd["board"], gd["turn"])
        my_moves = [m for m in moves if m[0] == fr and m[1] == fc]
        if not my_moves: await q.answer("Эта шашка не может ходить", show_alert=True); return
        gd["phase"] = "move"
        gd["sel"] = (fr, fc)
        kb = _chk_board_kb(gid, gd["board"], gd["turn"], "move", sel=(fr, fc))
        await q.answer()
        try:
            await q.message.edit_text(
                _chk_header(gd),
                parse_mode=ParseMode.HTML, reply_markup=kb,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Отмена выбора ────────────────────────────────────────────────────────
    if action == "ckc":
        gid = parts[1]
        gd = ctx.bot_data.get(f"chk|{gid}")
        if not gd: await q.answer("Игра не найдена", show_alert=True); return
        if gd["mode"] == "pvp":
            cur_p = gd["p1"] if gd["turn"] == 1 else gd["p2"]
            if uid != cur_p: await q.answer("Не твой ход!", show_alert=True); return
        else:
            if uid != gd["p1"]: await q.answer("Это не твоя игра!", show_alert=True); return
        gd["phase"] = "select"
        gd["sel"] = None
        kb = _chk_board_kb(gid, gd["board"], gd["turn"], "select")
        await q.answer()
        try:
            await q.message.edit_text(
                _chk_header(gd),
                parse_mode=ParseMode.HTML, reply_markup=kb,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Ход ──────────────────────────────────────────────────────────────────
    if action == "ckm":
        gid, tr, tc = parts[1], int(parts[2]), int(parts[3])
        gd = ctx.bot_data.get(f"chk|{gid}")
        if not gd: await q.answer("Игра не найдена", show_alert=True); return
        if gd["mode"] == "pvp":
            cur_p = gd["p1"] if gd["turn"] == 1 else gd["p2"]
            if uid != cur_p: await q.answer("Не твой ход!", show_alert=True); return
        else:
            if uid != gd["p1"]: await q.answer("Это не твоя игра!", show_alert=True); return
            if gd["turn"] != gd.get("human_player", 1):
                await q.answer("Сейчас ходит бот", show_alert=True); return
        fr, fc = gd["sel"] if gd.get("sel") else (None, None)
        if fr is None:
            await q.answer("Сначала выбери шашку", show_alert=True)
            return
        moves = _chk_moves(gd["board"], gd["turn"])
        matched = [m for m in moves if m[0] == fr and m[1] == fc and m[2] == tr and m[3] == tc]
        if not matched: await q.answer("Недопустимый ход", show_alert=True); return
        m = matched[0]
        gd["board"] = _chk_apply(gd["board"], *m)

        # Цепное взятие: если после рубки та же шашка может бить снова — обязательно продолжаем
        chain_mode = False
        if m[4]:
            chain = _chk_caps_from(gd["board"], gd["turn"], tr, tc)
            if chain:
                chain_mode = True
                gd["sel"] = (tr, tc)
                gd["phase"] = "move"

        if not chain_mode:
            gd["sel"] = None
            gd["phase"] = "select"
            gd["turn"] = 2 if gd["turn"] == 1 else 1

        # Проверка победы
        p1, p2 = _chk_count(gd["board"])
        next_m = _chk_moves(gd["board"], gd["turn"])
        finished = not next_m or p1 == 0 or p2 == 0

        await q.answer("💥 Бьёт" if chain_mode else "✅")

        if finished:
            # Определяем победителя
            if gd["mode"] == "pvp":
                stake = gd["stake"]
                # Проигравший — тот чья очередь и не может ходить
                # Или у кого не осталось шашек
                if gd["turn"] == 1 and (p1 == 0 or not next_m):
                    w_id, w_name = gd["p2"], gd["p2n"]
                    l_name = gd["p1n"]
                else:
                    w_id, w_name = gd["p1"], gd["p1n"]
                    l_name = gd.get("p2n", "?")
                prize = stake * 2
                _chat_id_tax = gd.get("chat_id") or 0
                prize = await apply_chat_tax(_chat_id_tax, w_id, prize, ctx)
                w_f = await db_get(w_id)
                if w_f: w_f["coins"] += prize; await db_save(w_f)
                await log_chat_activity(_chat_id_tax, w_id, w_name, "шашки победа", prize)
                ctx.bot_data.pop(f"chk|{gid}", None)
                try:
                    await q.message.edit_text(
                        f"♟️ <b>Шашки завершены!</b>\n"
                        f"{_E_DOT_BLACK} {_html.escape(gd['p1n'])} vs {_E_DOT_WHITE} {_html.escape(gd['p2n'])}\n\n"
                        f"{_E_TROPHY} <b>{_html.escape(w_name)}</b> победил(а)! +{prize}{_E_COIN}",
                        parse_mode=ParseMode.HTML,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass
            else:
                # vs bot
                human_p = gd.get("human_player", 1)
                human_lost = (human_p == 1 and (p1 == 0 or (not next_m and gd["turn"] == human_p))) or \
                             (human_p == 2 and (p2 == 0 or (not next_m and gd["turn"] == human_p)))
                result = "🤖 <b>Бот победил!</b>" if human_lost else f"{_E_TROPHY} <b>{_html.escape(gd['p1n'])}</b> победил(а)!"
                ctx.bot_data.pop(f"chk|{gid}", None)
                try:
                    await q.message.edit_text(
                        f"♟️ <b>Шашки vs Бот завершены!</b>\n\n{result}",
                        parse_mode=ParseMode.HTML,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass
            return

        if chain_mode:
            # Показываем доску с возможностью продолжить бить
            kb = _chk_board_kb(gid, gd["board"], gd["turn"], "move", sel=gd.get("sel"))
            try:
                await q.message.edit_text(
                    _chk_header(gd),
                    parse_mode=ParseMode.HTML, reply_markup=kb,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
            return

        # Ход бота (если режим bot и сейчас очередь бота)
        if gd["mode"] == "bot" and gd["turn"] == gd.get("bot_player", 2):
            # Показываем заблокированную доску пока бот думает
            kb = _chk_board_kb(gid, gd["board"], gd["turn"], "select", locked=True)
            try:
                await q.message.edit_text(
                    _chk_header(gd) + f"\n\n<i>{_E_BOT} Бот думает...</i>",
                    parse_mode=ParseMode.HTML, reply_markup=kb,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
            await asyncio.sleep(0.6)
            await _chk_do_bot_move(gid, gd, q, ctx)
            return

        # PvP — следующий ход
        kb = _chk_board_kb(gid, gd["board"], gd["turn"], "select")
        try:
            await q.message.edit_text(
                _chk_header(gd),
                parse_mode=ParseMode.HTML, reply_markup=kb,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Предложить ничью ─────────────────────────────────────────────────────
    if action == "ckd":
        gid = parts[1]
        gd = ctx.bot_data.get(f"chk|{gid}")
        if not gd: await q.answer("Игра не найдена", show_alert=True); return
        if uid != gd["p1"] and uid != gd.get("p2"):
            await q.answer("Ты не участвуешь в этой игре", show_alert=True); return
        mode = gd.get("mode", "pvp")
        if mode == "bot":
            # Бот принимает ничью если у него плохая позиция (меньше шашек)
            board = gd["board"]
            bot_p = gd.get("bot_player", 2)
            human_p = gd.get("human_player", 1)
            bot_pieces = sum(1 for r in range(8) for c in range(8) if board[r][c] in (bot_p, bot_p+2))
            human_pieces = sum(1 for r in range(8) for c in range(8) if board[r][c] in (human_p, human_p+2))
            # Принимает ничью если у бота ≤ человека по шашкам, иначе отказывает
            if bot_pieces <= human_pieces:
                stake = gd.get("stake", 0)
                hf = await db_get(uid)
                if hf:
                    hf["coins"] += stake
                    await db_save(hf)
                ctx.bot_data.pop(f"chk|{gid}", None)
                await q.answer("🤖 Бот принял ничью — позиция равная.")
                try:
                    await q.message.edit_text(
                        f"<b>Шашки vs Бот</b>\n\n🤝 Бот согласился на ничью.\n"
                        f"{'Ставка возвращена.' if stake else ''}",
                        parse_mode=ParseMode.HTML,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass
            else:
                await q.answer("🤖 Бот отказывает в ничьей — он в лучшей позиции", show_alert=True)
            return
        existing = gd.get("draw_offer")
        if existing == uid:
            await q.answer("Ты уже предложил ничью", show_alert=True); return
        if existing is not None and existing != uid:
            # Соперник уже предложил — принимаем ничью
            stake = gd.get("stake", 0)
            p1f = await db_get(gd["p1"])
            p2f = await db_get(gd["p2"])
            if p1f: p1f["coins"] += stake; await db_save(p1f)
            if p2f: p2f["coins"] += stake; await db_save(p2f)
            ctx.bot_data.pop(f"chk|{gid}", None)
            await q.answer("🤝 Ничья принята")
            try:
                await q.message.edit_text(
                    f"<b>Шашки</b>\n\n"
                    f"Играли: {_html.escape(gd['p1n'])} {_E_DOT_BLACK}, {_html.escape(gd['p2n'])} {_E_DOT_WHITE}\n\n"
                    f"🤝 Ничья по соглашению сторон!",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
            return
        gd["draw_offer"] = uid
        offerer_name = gd["p1n"] if uid == gd["p1"] else gd["p2n"]
        await q.answer("🤝 Предложение отправлено")
        try:
            await q.message.edit_text(
                _chk_header(gd) + f"\n\n🤝 <b>{_html.escape(offerer_name)}</b> предлагает ничью",
                parse_mode=ParseMode.HTML,
                reply_markup=_chk_board_kb(gid, gd["board"], gd["turn"], gd.get("phase", "select"), sel=gd.get("sel")),
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return

    # ── Сдаться / Отменить вызов ─────────────────────────────────────────────
    if action == "ckg":
        gid = parts[1]
        gd = ctx.bot_data.get(f"chk|{gid}")
        if not gd: await q.answer("Игра не найдена", show_alert=True); return
        if uid != gd["p1"] and uid != gd.get("p2"):
            await q.answer("Ты не участвуешь в этой игре", show_alert=True); return

        mode = gd.get("mode", "pvp")
        stake = gd.get("stake", 0)

        if mode == "bot":
            # vs бот — просто завершаем
            ctx.bot_data.pop(f"chk|{gid}", None)
            await q.answer("Игра завершена.")
            try:
                await q.message.edit_text(
                    f"♟️ <b>Шашки vs Бот</b>\n🏳 <b>{_html.escape(gd['p1n'])}</b> сдался.",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
            return

        # PvP
        if gd.get("p2") is None:
            # Ещё нет соперника — отмена с возвратом ставки
            if uid != gd["p1"]: await q.answer("Только создатель может отменить!", show_alert=True); return
            ctx.bot_data.pop(f"chk|{gid}", None)
            p1f = await db_get(gd["p1"])
            if p1f: p1f["coins"] += stake; await db_save(p1f)
            await q.answer(f"Вызов отменён, {stake}🪙 возвращено.")
            try:
                await q.message.edit_text(
                    f"♟️ Вызов отменён. +{stake}{_E_COIN} возвращено.",
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass
            return

        # Сдача во время игры
        ctx.bot_data.pop(f"chk|{gid}", None)
        w_id = gd["p2"] if uid == gd["p1"] else gd["p1"]
        w_name = gd["p2n"] if uid == gd["p1"] else gd["p1n"]
        l_name = gd["p1n"] if uid == gd["p1"] else gd["p2n"]
        prize = stake * 2
        w_f = await db_get(w_id)
        if w_f: w_f["coins"] += prize; await db_save(w_f)
        await q.answer()
        try:
            await q.message.edit_text(
                f"♟️ <b>Шашки</b>\n"
                f"🏳 <b>{_html.escape(l_name)}</b> сдался!\n"
                f"{_E_TROPHY} Победа <b>{_html.escape(w_name)}</b>! +{prize}{_E_COIN}",
                parse_mode=ParseMode.HTML,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass
        return


