# ── ХЕЛПЕРЫ БД ───────────────────────────────────────────────────────────────

def _gift_log_migration(conn):
    """Добавить колонку ts в gift_log если её нет (старые БД)."""
    try:
        cur = conn.cursor()
        cur.execute("PRAGMA table_info(gift_log)")
        cols = {row[1] for row in cur.fetchall()}
        if "ts" not in cols:
            cur.execute("ALTER TABLE gift_log ADD COLUMN ts REAL NOT NULL DEFAULT 0")
            conn.commit()
            print("✅ Миграция gift_log: добавлена колонка ts")
    except Exception as e:
        print(f"⚠️ gift_log migration: {e}")


def exp_sync_migration(conn):
    """
    Вызывается из run_sync_migration(). Добавляет колонку last_expedition в frogs
    и создаёт таблицы expeditions / expedition_members.
    """
    try:
        cur = conn.cursor()
        # Колонка last_expedition во frogs
        cur.execute("PRAGMA table_info(frogs)")
        existing = {row[1] for row in cur.fetchall()}
        if "last_expedition" not in existing:
            cur.execute("ALTER TABLE frogs ADD COLUMN last_expedition REAL DEFAULT 0")
            conn.commit()
            print("✅ Миграция frogs: добавлена last_expedition")
        # Таблица expeditions
        cur.execute("""
            CREATE TABLE IF NOT EXISTS expeditions (
                id              INTEGER PRIMARY KEY AUTOINCREMENT,
                biome           TEXT    NOT NULL,
                status          TEXT    DEFAULT 'lobby',
                creator_id      INTEGER NOT NULL,
                max_players     INTEGER NOT NULL,
                gather_until    REAL    NOT NULL,
                started_at      REAL    DEFAULT 0,
                ends_at         REAL    DEFAULT 0,
                event_json      TEXT    DEFAULT '[]',
                last_event_idx  INTEGER DEFAULT -1,
                last_event_at   REAL    DEFAULT 0,
                finished_at     REAL    DEFAULT 0,
                announce_msg_id INTEGER DEFAULT 0,
                announce_chat   INTEGER DEFAULT 0,
                stats_json      TEXT    DEFAULT '{}'
            )
        """)
        cur.execute(
            "CREATE INDEX IF NOT EXISTS idx_exp_status ON expeditions(status)"
        )
        # Таблица expedition_members
        cur.execute("""
            CREATE TABLE IF NOT EXISTS expedition_members (
                expedition_id   INTEGER NOT NULL,
                user_id         INTEGER NOT NULL,
                coins_taken     INTEGER DEFAULT 0,
                supplies_json   TEXT    DEFAULT '{"food":0,"potion":0,"torch":0,"amulet":0}',
                status          TEXT    DEFAULT 'active',
                hp_current      INTEGER DEFAULT 100,
                coins_gained    INTEGER DEFAULT 0,
                coins_lost      INTEGER DEFAULT 0,
                contribution    INTEGER DEFAULT 0,
                betrayal_done   INTEGER DEFAULT 0,
                betrayal_count  INTEGER DEFAULT 0,
                votes_json      TEXT    DEFAULT '{}',
                personal_json   TEXT    DEFAULT '{}',
                joined_at       REAL    DEFAULT 0,
                PRIMARY KEY (expedition_id, user_id)
            )
        """)
        cur.execute(
            "CREATE INDEX IF NOT EXISTS idx_expm_user ON expedition_members(user_id)"
        )
        conn.commit()
        print("✅ Миграция: таблицы expeditions / expedition_members созданы")
    except Exception as e:
        print(f"⚠️ exp_sync_migration: {e}")


async def _exp_get(exp_id: int) -> dict | None:
    """Получить экспедицию по id."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM expeditions WHERE id=?", (exp_id,)
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def _exp_save(exp: dict):
    """Сохранить экспедицию (UPDATE по id)."""
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            """UPDATE expeditions SET
               status=?, started_at=?, ends_at=?, event_json=?,
               last_event_idx=?, last_event_at=?, finished_at=?,
               announce_msg_id=?, announce_chat=?, stats_json=?
               WHERE id=?""",
            (
                exp["status"], exp.get("started_at", 0), exp.get("ends_at", 0),
                exp.get("event_json", "[]"),
                exp.get("last_event_idx", -1), exp.get("last_event_at", 0),
                exp.get("finished_at", 0),
                exp.get("announce_msg_id", 0), exp.get("announce_chat", 0),
                exp.get("stats_json", "{}"),
                exp["id"],
            ),
        )
        await db.commit()


async def _expm_get(exp_id: int, user_id: int) -> dict | None:
    """Получить запись участника экспедиции."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM expedition_members WHERE expedition_id=? AND user_id=?",
            (exp_id, user_id),
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def _expm_save(m: dict):
    """Сохранить запись участника (UPDATE)."""
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            """UPDATE expedition_members SET
               coins_taken=?, supplies_json=?, status=?, hp_current=?,
               coins_gained=?, coins_lost=?, contribution=?,
               betrayal_done=?, betrayal_count=?,
               votes_json=?, personal_json=?
               WHERE expedition_id=? AND user_id=?""",
            (
                m["coins_taken"], m["supplies_json"], m["status"],
                m["hp_current"], m["coins_gained"], m["coins_lost"],
                m["contribution"], m["betrayal_done"], m["betrayal_count"],
                m["votes_json"], m["personal_json"],
                m["expedition_id"], m["user_id"],
            ),
        )
        await db.commit()


async def _exp_get_members(exp_id: int) -> list[dict]:
    """Получить всех участников экспедиции."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            "SELECT * FROM expedition_members WHERE expedition_id=? ORDER BY joined_at",
            (exp_id,),
        ) as c:
            rows = await c.fetchall()
    return [dict(r) for r in rows]


async def _exp_get_active_members(exp_id: int) -> list[dict]:
    """Только живые участники."""
    all_m = await _exp_get_members(exp_id)
    return [m for m in all_m if m["status"] == "active"]


async def _exp_get_user_active(user_id: int) -> dict | None:
    """Найти активную экспедицию пользователя (только если участник ещё в ней)."""
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(
            """SELECT e.* FROM expeditions e
               JOIN expedition_members em ON e.id = em.expedition_id
               WHERE em.user_id=? AND e.status IN ('lobby','active')
               AND em.status IN ('active','joined')""",
            (user_id,),
        ) as c:
            row = await c.fetchone()
    return dict(row) if row else None


async def _exp_broadcast(bot, exp_id: int, text: str, reply_markup=None,
                         only_alive: bool = True, exclude_uid: int = 0,
                         delete_after: int = 0):
    """Разослать сообщение всем (живым) участникам экспедиции."""
    members = await _exp_get_members(exp_id)
    for m in members:
        if only_alive and m["status"] != "active":
            continue
        if exclude_uid and m["user_id"] == exclude_uid:
            continue
        try:
            await bot.send_message(
                m["user_id"], text,
                parse_mode=ParseMode.HTML,
                reply_markup=reply_markup,
            )
        except (BadRequest, Forbidden, TimedOut):
            pass


def _sup(m: dict) -> dict:
    """Десериализовать supplies_json из строки."""
    try:
        return json.loads(m.get("supplies_json") or "{}")
    except Exception:
        return {"food": 0, "potion": 0, "torch": 0, "amulet": 0}


def _votes(m: dict) -> dict:
    try:
        return json.loads(m.get("votes_json") or "{}")
    except Exception:
        return {}


def _personal(m: dict) -> dict:
    try:
        return json.loads(m.get("personal_json") or "{}")
    except Exception:
        return {}


def _exp_events(exp: dict) -> list:
    try:
        return json.loads(exp.get("event_json") or "[]")
    except Exception:
        return []


def _exp_stats(exp: dict) -> dict:
    try:
        return json.loads(exp.get("stats_json") or "{}")
    except Exception:
        return {}


def _supply_text(sup: dict) -> str:
    """Строка инвентаря припасов."""
    parts = []
    for k, info in SUPPLY_TYPES.items():
        if "emoji" not in info:
            continue
        n = sup.get(k, 0)
        if n > 0:
            parts.append(f"{info['emoji']}{n}")
    return " ".join(parts) if parts else "—"


def _hp_bar_pct(hp: int) -> str:
    """HP-бар для систем где HP в процентах (0–100). Используется в дуэлях вне стычки."""
    hp = max(0, min(100, hp))
    filled = round(hp / 10)
    color = "🟩" if hp > 60 else ("🟨" if hp > 30 else "🟥")
    return color * filled + "⬜" * (10 - filled) + f" {hp}HP"


# ── ГЕНЕРАЦИЯ РАСПИСАНИЯ СОБЫТИЙ ─────────────────────────────────────────────

def _generate_event_schedule(biome: str) -> list[dict]:
    """
    Генерирует список событий для экспедиции.
    Каждое событие — dict с полями:
        idx, key, type, at (timestamp), sent, resolved, votes, result
    """
    cfg = EXP_BIOMES[biome]
    n_events = cfg["events_count"]
    duration_s = cfg["duration_h"] * 3600
    now = time.time()
    # Стартуем события: первое через 15 мин, последнее за 10 мин до конца
    start_offset = 15 * 60
    end_offset = 10 * 60
    usable = duration_s - start_offset - end_offset
    if n_events <= 1:
        slots = [now + start_offset]
    else:
        step = usable / (n_events - 1)
        slots = [now + start_offset + i * step for i in range(n_events)]

    # Разбиваем на фазы
    phases = []
    for i, ts in enumerate(slots):
        pct = i / max(n_events - 1, 1)
        if pct < 0.30:
            phases.append("early")
        elif pct < 0.65:
            phases.append("mid")
        elif pct < 0.90:
            phases.append("late")
        else:
            phases.append("final")

    # Финальный босс для руин — всегда последний слот
    events = []
    doom_used = False
    personal_used = False  # флаг: предательство уже было недавно (кулдаун)
    for i, (ts, phase) in enumerate(zip(slots, phases)):

        # Финальный слот в руинах — всегда босс
        if phase == "final" and cfg.get("final_boss"):
            events.append({
                "idx": i, "key": "c_ruins_boss", "type": "combat",
                "at": ts, "sent": False, "resolved": False,
                "votes": {}, "result": None,
            })
            continue

        # Выбираем пул событий по фазе и биому
        pool = _build_event_pool(biome, phase, doom_used, personal_used, cfg)
        if not pool:
            continue

        # Взвешенный случайный выбор — антиповтор ВСЕЙ экспедиции
        used_in_exp = {e["key"] for e in events}  # все ключи уже выбранных событий
        # По типу тоже не повторяем подряд (например, 2 doom подряд)
        last_type = events[-1]["type"] if events else None
        filtered_pool = [
            (k, w) for k, w in pool
            if k not in used_in_exp  # никаких повторов ключа в одной экспедиции
        ]
        # Дополнительно снижаем вес типа который был последним
        if last_type and filtered_pool:
            filtered_pool = [
                (k, w // 2 if EXP_EVENT_CATALOG[k]["type"] == last_type else w)
                for k, w in filtered_pool
            ]
            # Убираем нули
            filtered_pool = [(k, max(1, w)) for k, w in filtered_pool]
        if not filtered_pool:
            # Fallback: берём только то что не повторяет тип
            filtered_pool = [(k, w) for k, w in pool if EXP_EVENT_CATALOG[k]["type"] != last_type]
        if not filtered_pool:
            filtered_pool = pool  # совсем нечего — берём без ограничений
        keys = [k for k, w in filtered_pool]
        weights = [w for k, w in filtered_pool]
        chosen_key = random.choices(keys, weights=weights, k=1)[0]
        ev_data = EXP_EVENT_CATALOG[chosen_key]

        if ev_data["type"] == "collective_doom":
            doom_used = True
        if ev_data.get("is_betrayal"):
            personal_used = True  # не повторять предательство подряд
        elif personal_used and i > 0 and (i % 2 == 0):
            personal_used = False  # через 2 события снова можно

        events.append({
            "idx": i, "key": chosen_key, "type": ev_data["type"],
            "at": ts, "sent": False, "resolved": False,
            "votes": {}, "result": None,
        })
    return events


def _build_event_pool(biome: str, phase: str, doom_used: bool,
                      personal_used: bool, cfg: dict) -> list[tuple]:
    """Собрать взвешенный пул событий для данной фазы."""
    pool = []
    doom_chance = cfg["doom_chance"]

    for key, ev in EXP_EVENT_CATALOG.items():
        if biome not in ev.get("biomes", []):
            continue
        ev_phase = ev.get("phase", "any")
        if ev_phase != "any" and ev_phase != phase:
            # early-события могут появляться в mid, но не поздно
            if not (ev_phase == "early" and phase == "mid"):
                continue
        if ev["type"] == "collective_doom":
            if doom_used:
                continue
            if random.random() > doom_chance:
                continue
        # scout_vote требует минимум 2 живых участника (иначе бессмысленно)
        if ev["type"] == "scout_vote":
            pass  # проверка на количество участников происходит при fire
        # riddle — разрешён всегда
        if ev.get("is_betrayal") and personal_used:
            continue
        # Финальный босс только в "final"
        if ev.get("is_boss") and phase != "final":
            continue
        pool.append((key, ev.get("weight", 1)))
    return pool


# ── ЛОББИ: СОЗДАНИЕ КОМНАТЫ ───────────────────────────────────────────────────

async def _exp_lobby_text(exp: dict, members: list[dict], bot) -> str:
    """Текст карточки лобби."""
    biome = EXP_BIOMES[exp["biome"]]
    gather_left = max(0, int(exp["gather_until"] - time.time()))
    mm, ss = divmod(gather_left, 60)
    time_str = f"{mm}:{ss:02d}"
    # Время старта по МСК
    start_msk_h = (datetime.fromtimestamp(exp["gather_until"], tz=timezone.utc).hour + 3) % 24
    start_msk_m = datetime.fromtimestamp(exp["gather_until"], tz=timezone.utc).minute
    start_msk_str = f"{start_msk_h:02d}:{start_msk_m:02d}"

    names = []
    for m in members:
        f = await db_get(m["user_id"])
        if f:
            names.append(f"• {fname(f)}")
    names_str = "\n".join(names) if names else "— пусто —"

    return (
        f"<b>{biome['name']}</b>\n"          # эмодзи уже внутри name
        f"<i>{biome['desc']}</i>\n\n"
        f"{_E_USERS} <b>Команда</b> {len(members)}/{exp['max_players']}:\n"
        f"{names_str}\n\n"
        f"⏳ Сбор закроется через: <b>{time_str}</b> (в {start_msk_str} МСК)\n"
        f"{_E_SWORDS} Длительность: <b>{EXP_BIOMES[exp['biome']]['duration_h']} ч</b>  "        f"🪙 До <b>{biome['max_coins']}🪙</b>"
    )


def _exp_lobby_kb(exp: dict, members: list[dict], user_id: int) -> InlineKeyboardMarkup:
    """Клавиатура лобби."""
    in_lobby = any(m["user_id"] == user_id for m in members)
    eid = exp["id"]
    buttons = []
    if not in_lobby and len(members) < exp["max_players"]:
        buttons.append([
            btn("✅ Вступить в экспедицию", callback_data=f"exp_join_{eid}",
                style="success")
        ])
    buttons.append([
        btn("🔄 Обновить", callback_data=f"exp_lobby_refresh_{eid}"),
        btn("🎒 Снаряжение", callback_data=f"exp_gear_{eid}"),
    ])
    if in_lobby:
        buttons.append([
            btn("📢 Анонс в чат", callback_data=f"exp_announce_{eid}"),
            btn("💌 Позвать соседей", callback_data=f"exp_invite_{eid}"),
        ])
        buttons.append([
            btn("❌ Покинуть", callback_data=f"exp_leave_{eid}", style="danger"),
        ])
    return InlineKeyboardMarkup(buttons)


# ── СТАРТ ЭКСПЕДИЦИИ ──────────────────────────────────────────────────────────

async def _exp_start(exp_id: int, bot):
    """Запустить экспедицию — сгенерировать расписание, разослать старт."""
    exp = await _exp_get(exp_id)
    if not exp or exp["status"] != "lobby":
        return
    members = await _exp_get_members(exp_id)
    if len(members) < EXP_MIN_PLAYERS:
        # Отменяем — мало игроков
        async with aiosqlite.connect(DB_PATH) as db:
            await db.execute(
                "UPDATE expeditions SET status='cancelled' WHERE id=?", (exp_id,)
            )
            await db.commit()
        await _exp_broadcast(
            bot, exp_id,
            "❌ <b>Экспедиция отменена</b>\n\nНедостаточно участников собралось. "
            "Монеты и припасы возвращены.",
            only_alive=False,
        )
        # Вернуть монеты
        for m in members:
            f = await db_get(m["user_id"])
            if f:
                f["coins"] = f.get("coins", 0) + m["coins_taken"]
                # Вернуть припасы
                sup = _sup(m)
                inv = (json.loads(f["inventory"]) if isinstance(f.get("inventory"), str) else f.get("inventory")) or {}
                for k, n in sup.items():
                    inv[k] = inv.get(k, 0) + n
                f["inventory"] = json.dumps(inv)
                await db_save(f)
        return

    biome = exp["biome"]
    now = time.time()
    duration_s = EXP_BIOMES[biome]["duration_h"] * 3600
    ends_at = now + duration_s

    schedule = _generate_event_schedule(biome)

    exp["status"] = "active"
    exp["started_at"] = now
    exp["ends_at"] = ends_at
    exp["event_json"] = json.dumps(schedule, ensure_ascii=False)
    exp["last_event_idx"] = -1
    exp["last_event_at"] = now
    await _exp_save(exp)

    # Заблокировать лягушек
    for m in members:
        f = await db_get(m["user_id"])
        if f:
            f["adventure_locked_until"] = ends_at
            await db_save(f)

    biome_cfg = EXP_BIOMES[biome]
    names_list = []
    for m in members:
        f = await db_get(m["user_id"])
        if f:
            names_list.append(fname(f))

    start_text = (
        f"🗺️ <b>Экспедиция начинается!</b>\n\n"
        f"{biome_cfg['emoji']} <b>{biome_cfg['name']}</b>\n"
        "\n"
        f"{_E_USERS} Команда: {', '.join(names_list)}\n\n"
        f"⏱ Длительность: <b>{biome_cfg['duration_h']} ч</b>\n"
        f"📅 Возвращение: <b>{datetime.fromtimestamp(ends_at).strftime('%H:%M')}</b>\n\n"
        f"<i>События будут приходить тебе в личку по ходу экспедиции. "
        f"Используй /m текст чтобы написать команде.</i>\n\n"
        f"💪 Удачи, {he(names_list[0] if names_list else 'лягушка')}!"
    )
    await _exp_broadcast(
        bot, exp_id, start_text,
        reply_markup=InlineKeyboardMarkup([[
            btn("📊 Мой статус", callback_data=f"exp_status_{exp_id}"),
        ]]),
    )

    # Публичный анонс
    await announce(
        bot,
        f"🗺️ <b>Экспедиция стартовала!</b>\n"
        f"{biome_cfg['emoji']} {biome_cfg['name']} — "
        f"{len(members)} участников\n"
        f"Команда: {', '.join(names_list)}",
        delete_after=300,
    )
    logger.info("expedition started id=%s biome=%s members=%s", exp_id, biome, len(members))


# ── ОБРАБОТКА СОБЫТИЯ ─────────────────────────────────────────────────────────

# Глобальный словарь ожидания ответов на загадки: {uid: {exp_id, ev_idx, deadline}}
EXP_RIDDLE_PENDING: dict[int, dict] = {}


async def _restore_riddle_pending(bot) -> None:
    """
    БАГ 1 FIX: восстанавливаем EXP_RIDDLE_PENDING из БД после рестарта.

    Ищем все активные экспедиции у которых в event_json есть загадка
    (type='riddle') с answered=False и deadline ещё не истёк.
    Для каждой такой загадки заново заполняем словарь и запускаем таймаут,
    чтобы ответы игроков снова корректно обрабатывались.
    """
    try:
        async with aiosqlite.connect(DB_PATH) as _rdb:
            _rdb.row_factory = aiosqlite.Row
            async with _rdb.execute(
                "SELECT * FROM expeditions WHERE status='active'"
            ) as _rcur:
                active_exps = [dict(r) for r in await _rcur.fetchall()]

        restored = 0
        for _rexp in active_exps:
            _rev_list = json.loads(_rexp.get("event_json") or "[]")
            for _rev in _rev_list:
                _rev_data = EXP_EVENT_CATALOG.get(_rev.get("key", ""), {})
                if _rev_data.get("type") != "riddle":
                    continue
                if _rev.get("answered"):
                    continue

                _rdeadline = _rev.get("deadline", 0)
                _rmembers = await _exp_get_active_members(_rexp["id"])
                if not _rmembers:
                    continue

                if _rdeadline and time.time() >= _rdeadline:
                    # Дедлайн уже прошёл пока бот был выключен — запускаем штраф немедленно
                    asyncio.create_task(
                        _exp_riddle_timeout(bot, _rexp, _rev, _rev_data, _rmembers)
                    )
                    continue

                # Дедлайн ещё не истёк — восстанавливаем ожидание
                for _rm in _rmembers:
                    EXP_RIDDLE_PENDING[_rm["user_id"]] = {
                        "exp_id": _rexp["id"],
                        "ev_idx": _rev["idx"],
                        "deadline": _rdeadline or (time.time() + 5 * 60),
                    }
                    restored += 1

                # Перезапускаем таймаут с оставшимся временем
                _remaining = max(5, _rdeadline - time.time() + 5)

                async def _make_delayed(b, e, ev_, evd, ms, r):
                    await asyncio.sleep(r)
                    await _exp_riddle_timeout(b, e, ev_, evd, ms)

                asyncio.create_task(
                    _make_delayed(bot, _rexp, _rev, _rev_data, _rmembers, _remaining)
                )

        if restored:
            logger.info(
                "_restore_riddle_pending: восстановлено %d записей из %d экспедиций",
                restored, len(active_exps),
            )
    except Exception as _rre:
        logger.error("_restore_riddle_pending failed: %s", _rre)


async def _exp_riddle_timeout(bot, exp: dict, ev: dict, ev_data: dict, members: list):
    """Таймаут загадки — если никто не ответил за 5 минут."""
    await asyncio.sleep(5 * 60 + 5)  # чуть больше дедлайна

    # БАГ 2 FIX: не доверяем переданному объекту ev — он мог устареть.
    # Перечитываем событие из БД, чтобы увидеть актуальный флаг answered.
    _exp_fresh = await _exp_get(exp["id"])
    if _exp_fresh:
        _events_fresh = json.loads(_exp_fresh.get("event_json") or "[]")
        _ev_fresh = next((e for e in _events_fresh if e.get("idx") == ev.get("idx")), None)
        if _ev_fresh and _ev_fresh.get("answered"):
            return  # правильный ответ уже засчитан — штраф не нужен
        # Помечаем в БД
        if _ev_fresh:
            _ev_fresh["answered"] = True
            _exp_fresh["event_json"] = json.dumps(_events_fresh, ensure_ascii=False)
            await _exp_save(_exp_fresh)
    else:
        # Экспедиция уже завершена
        return

    # Убираем ожидание
    for m in members:
        EXP_RIDDLE_PENDING.pop(m["user_id"], None)
    # Штраф за таймаут
    hp_delta = ev_data.get("timeout_hp", -20)
    dur_add = ev_data.get("timeout_duration", 0)
    result_parts = [f"⏰ <b>Время вышло</b>\n{ev_data['flavor_timeout']}"]
    if hp_delta < 0:
        result_parts.append(f"💔 <b>{hp_delta} HP</b> каждому")
    if dur_add:
        result_parts.append(f"⏱ <b>+{dur_add} мин</b> к маршруту")
    await _exp_broadcast(bot, exp["id"], "\n".join(result_parts))
    # Применяем штраф
    fresh_members = await _exp_get_active_members(exp["id"])
    for m in fresh_members:
        if hp_delta:
            m["hp_current"] = max(0, m["hp_current"] + hp_delta)
        if dur_add:
            exp_row = await _exp_get(exp["id"])
            if exp_row:
                import aiosqlite as _aiosl
                async with _aiosl.connect(DB_PATH) as _db:
                    await _db.execute(
                        "UPDATE expeditions SET ends_at=ends_at+? WHERE id=?",
                        (dur_add * 60, exp["id"])
                    )
                    await _db.commit()
        if m["hp_current"] <= 0:
            f = await db_get(m["user_id"])
            if f:
                await _handle_member_death(bot, exp, m, f, "загадка")
        else:
            await _expm_save(m)


async def _exp_fire_event(bot, exp: dict, ev: dict):
    """Отправить/обработать одно событие."""
    ev_data = EXP_EVENT_CATALOG.get(ev["key"])
    if not ev_data:
        return
    exp_id = exp["id"]
    members = await _exp_get_active_members(exp_id)
    if not members:
        return

    t = ev_data["type"]

    # ── Пассивное ────────────────────────────────────────────────
    if t == "passive":
        for m in members:
            f = await db_get(m["user_id"])
            if not f:
                continue
            name = fname(f)
            text = ev_data["text"].format(name=name, names="команда")

            # Определяем исход
            outcome = ev_data["outcome"]
            bad_chance = ev_data.get("bad_chance", 0.0)
            use_bad = random.random() < bad_chance
            if use_bad and ev_data.get("outcome_bad"):
                outcome = ev_data["outcome_bad"]

            result_lines = [text, ""]
            coins_delta, hp_delta = 0, 0

            if "coins" in outcome:
                lo, hi = outcome["coins"]
                lo, hi = min(lo, hi), max(lo, hi)  # гарантируем правильный порядок
                if lo == 0 and hi == 0:
                    coins_delta = 0
                else:
                    coins_delta = random.randint(lo, hi)
                if coins_delta > 0:
                    result_lines.append(f"{_E_MONEYBAG} <b>+{coins_delta}{_E_COIN}</b>")
                elif coins_delta < 0:
                    result_lines.append(f"💸 <b>{coins_delta}{_E_COIN}</b>")

            if "hp" in outcome:
                lo, hi = outcome["hp"]
                hp_delta = random.randint(min(lo, hi), max(lo, hi))
                # Факел снижает урон от ловушек
                if hp_delta < 0 and ev_data.get("torch_reduces"):
                    sup = _sup(m)
                    if sup.get("torch", 0) > 0:
                        hp_delta = hp_delta // 2
                        result_lines.append("🔦 <i>Факел помог смягчить удар</i>")
                if hp_delta > 0:
                    result_lines.append(f"{_E_HEART} <b>+{hp_delta} HP</b>")
                elif hp_delta < 0:
                    result_lines.append(f"💔 <b>{hp_delta} HP</b>")

            if outcome.get("luck_next") is True:
                result_lines.append(f"{_E_STARS} <i>Следующее испытание пройдёт с бонусом к удаче</i>")
            if outcome.get("luck_next") is False:
                result_lines.append("🌑 <i>Проклятье! Следующее испытание пройдёт с штрафом.</i>")

            # Припасы
            for key_s in ("supply_add", "supply_add2"):
                if key_s in outcome:
                    stype, scount, schance = outcome[key_s]
                    if random.random() < schance:
                        sup = _sup(m)
                        sup[stype] = sup.get(stype, 0) + scount
                        m["supplies_json"] = json.dumps(sup)
                        result_lines.append(
                            f"{SUPPLY_TYPES[stype]['emoji']} Нашла <b>{scount} {SUPPLY_TYPES[stype]['name']}</b>"
                        )

            # Применяем изменения
            m["hp_current"] = max(0, min(100, m["hp_current"] + hp_delta))
            m["coins_gained"] = m.get("coins_gained", 0) + max(0, coins_delta)
            if coins_delta < 0:
                m["coins_lost"] = m.get("coins_lost", 0) + abs(coins_delta)
            m["contribution"] = m.get("contribution", 0) + 1

            # Смерть от урона?
            if m["hp_current"] <= 0:
                await _handle_member_death(bot, exp, m, f, "ловушка")
            else:
                await _expm_save(m)
                # Обновить монеты лягушки в реальном времени
                f["coins"] = f.get("coins", 0) + coins_delta
                await db_save(f)

                await bot.send_message(
                    m["user_id"],
                    "\n".join(result_lines),
                    parse_mode=ParseMode.HTML,
                )

    # ── Боевое ───────────────────────────────────────────────────
    elif t == "combat":
        for m in members:
            f = await db_get(m["user_id"])
            if not f:
                continue
            name = fname(f)
            text = ev_data["text"].format(name=name, names="команда")
            sup = _sup(m)

            win_chance = ev_data["win_chance"]
            # Факел-бонус
            if sup.get("torch", 0) > 0 and ev_data.get("torch_bonus", 0) > 0:
                win_chance = min(0.90, win_chance + ev_data["torch_bonus"])
                torch_note = "🔦 <i>Факел освещает слабые места врага! +шанс победы</i>\n"
            else:
                torch_note = ""
            # Зелье-бонус
            if sup.get("potion", 0) > 0:
                win_chance = min(0.90, win_chance + 0.10)

            # Luck from previous event
            pers = _personal(m)
            if pers.get("luck_next"):
                win_chance = min(0.90, win_chance + 0.20)
                pers.pop("luck_next", None)
                m["personal_json"] = json.dumps(pers)
            elif pers.get("curse_next"):
                win_chance = max(0.10, win_chance - 0.20)
                pers.pop("curse_next", None)
                m["personal_json"] = json.dumps(pers)

            won = random.random() < win_chance

            if won:
                coins = random.randint(*ev_data["reward_coins"])
                result_text = (
                    f"{text}\n\n"
                    f"{torch_note}"
                    f"{_E_SWORDS} <b>Победа над {he(ev_data['enemy'])}!</b>\n"
                    f"💰 <b>+{coins}🪙</b>\n"
                    f"{_E_XP} <b>+5 XP</b>"
                )
                m["coins_gained"] = m.get("coins_gained", 0) + coins
                f["coins"] = f.get("coins", 0) + coins
                add_xp(f, 5)
                m["contribution"] = m.get("contribution", 0) + 2
                await _expm_save(m)
                await db_save(f)
                await bot.send_message(m["user_id"], result_text, parse_mode=ParseMode.HTML)
            else:
                dmg = random.randint(*ev_data["dmg_lose"])
                # Зелье снижает урон
                if sup.get("potion", 0) > 0:
                    dmg = int(dmg * 0.5)
                    sup["potion"] -= 1
                    m["supplies_json"] = json.dumps(sup)
                    potion_note = "🧪 <i>Зелье смягчило удар</i>\n"
                else:
                    potion_note = ""

                m["hp_current"] = max(0, m["hp_current"] - dmg)
                m["coins_lost"] = m.get("coins_lost", 0) + 0  # урон без потери монет при поражении в бою

                # Смерть?
                death_chance = ev_data.get("death_chance", 0)
                if sup.get("amulet", 0) > 0:
                    death_chance *= 0.5
                died = m["hp_current"] <= 0 and random.random() < death_chance
                if m["hp_current"] <= 0:
                    died = True

                if died:
                    result_text = (
                        f"{text}\n\n"
                        f"{potion_note}"
                        f"💀 <b>{he(ev_data['enemy'])} одолел {name}...</b>\n"
                        f"<i>Лягушка выбыла из экспедиции.</i>"
                    )
                    await bot.send_message(m["user_id"], result_text, parse_mode=ParseMode.HTML)
                    await _handle_member_death(bot, exp, m, f, "бой")
                else:
                    result_text = (
                        f"{text}\n\n"
                        f"{potion_note}"
                        f"💔 <b>Поражение от {he(ev_data['enemy'])}!</b>\n"
                        f"💔 <b>-{dmg} HP</b> | Осталось: {m['hp_current']} HP\n"
                        f"<i>Держись! Ещё не конец.</i>"
                    )
                    await _expm_save(m)
                    await bot.send_message(m["user_id"], result_text, parse_mode=ParseMode.HTML)

    # ── Командное голосование ─────────────────────────────────────
    elif t == "team_vote":
        deadline = time.time() + EXP_VOTE_TIMEOUT_S
        ev["deadline"] = deadline

        # Считаем суммарный запас ресурсов по всей команде
        # (нужно для скрытия кнопок с supply_cost если ресурса нет ни у кого)
        team_supply_totals: dict = {}
        for _m in members:
            for k, v in _sup(_m).items():
                team_supply_totals[k] = team_supply_totals.get(k, 0) + v

        kb_buttons = []
        supply_warning_lines = []
        for opt in ev_data["options"]:
            sc = opt.get("supply_cost")
            if sc:
                stype, scount = sc
                sname = SUPPLY_TYPES.get(stype, {}).get("name", stype)
                semoji = SUPPLY_TYPES.get(stype, {}).get("emoji", "📦")
                has_enough = team_supply_totals.get(stype, 0) >= scount
                if not has_enough:
                    # Кнопку показываем серой с пометкой, но не прячем —
                    # чтобы игроки видели что вариант есть, просто недоступен
                    kb_buttons.append(
                        btn(f"🚫 {opt['label']} (нет {semoji}{sname})",
                            callback_data=f"exp_vote_{exp_id}_{ev['idx']}_no_supply_{stype}")
                    )
                    supply_warning_lines.append(
                        f"⚠️ <i>У команды нет {semoji}<b>{sname}</b> — этот вариант недоступен.</i>"
                    )
                    continue
            kb_buttons.append(
                btn(opt["label"],
                    callback_data=f"exp_vote_{exp_id}_{ev['idx']}_{opt['key']}")
            )
        kb = InlineKeyboardMarkup([kb_buttons])

        warning_block = ("\n\n" + "\n".join(supply_warning_lines)) if supply_warning_lines else ""
        vote_text = (
            f"{ev_data['text']}{warning_block}\n\n"
            f"<i>⏰ Голосование закрывается через 15 минут. "
            f"Если не ответишь — засчитается безопасный вариант.</i>"
        )
        await _exp_broadcast(bot, exp_id, vote_text, reply_markup=kb)

    # ── Личное тайное событие ─────────────────────────────────────
    elif t == "personal_secret":
        deadline = time.time() + EXP_SECRET_TIMEOUT_S
        ev["deadline"] = deadline

        for m in members:
            f = await db_get(m["user_id"])
            if not f:
                continue
            name = fname(f)
            text = ev_data["text"].format(name=name)

            # Предательство — нужен хотя бы 1 другой живой участник
            if ev_data.get("is_betrayal") and len(members) < 2:
                continue

            kb_buttons = []
            for opt in ev_data["options"]:
                kb_buttons.append(
                    btn(opt["label"],
                        callback_data=f"exp_secret_{exp_id}_{ev['idx']}_{m['user_id']}_{opt['key']}")
                )
            kb = InlineKeyboardMarkup([kb_buttons])

            await bot.send_message(
                m["user_id"], text,
                parse_mode=ParseMode.HTML, reply_markup=kb,
            )

    # ── Загадка — текстовый ввод ─────────────────────────────────
    elif t == "riddle":
        deadline = time.time() + 5 * 60
        ev["deadline"] = deadline
        ev["answered"] = False
        members_snap = await _exp_get_active_members(exp["id"])
        for m in members_snap:
            EXP_RIDDLE_PENDING[m["user_id"]] = {
                "exp_id": exp["id"],
                "ev_idx": ev["idx"],
                "deadline": deadline,
            }
        await _exp_broadcast(
            bot, exp["id"],
            ev_data["riddle_text"] + "\n\n<i>Команды (/.s и подобные) не засчитываются как ответ.</i>",
        )
        asyncio.create_task(_exp_riddle_timeout(bot, exp, ev, ev_data, members_snap))

    # ── Коллективная катастрофа ────────────────────────────────────
    elif t == "collective_doom":
        await _handle_collective_doom(bot, exp, ev, ev_data, members)

    # ── Голосование за разведчика ───────────────────────────────────
    elif t == "scout_vote":
        deadline = time.time() + EXP_VOTE_TIMEOUT_S
        ev["deadline"] = deadline

        # Кнопка для каждого участника — «Отправить ИМЯРЕК»
        kb_buttons = []
        for m in members:
            f_sc = await db_get(m["user_id"])
            if not f_sc:
                continue
            sc_name = fname(f_sc)
            kb_buttons.append(
                btn(f"🔦 {sc_name}",
                    callback_data=f"exp_scout_{exp_id}_{ev['idx']}_{m['user_id']}")
            )
        kb = InlineKeyboardMarkup([[b] for b in kb_buttons])

        scout_text = (
            f"{ev_data['text']}\n\n"
            f"<i>⏰ Голосование закрывается через 15 минут. "
            f"Если никто не проголосует — событие пропускается.</i>"
        )
        await _exp_broadcast(bot, exp_id, scout_text, reply_markup=kb)


async def _handle_collective_doom(bot, exp: dict, ev: dict, ev_data: dict,
                                  members: list[dict]):
    """Обработать коллективную катастрофу."""
    exp_id = exp["id"]
    doom_text = ev_data["doom_text"]
    # Сначала объявляем катастрофу всем
    await _exp_broadcast(bot, exp_id, f"⚠️ {doom_text}")
    await asyncio.sleep(2)

    dead_names = []
    for m in members:
        f = await db_get(m["user_id"])
        if not f:
            continue
        sup = _sup(m)
        name = fname(f)
        result_lines = []

        # HP урон
        hp_delta = ev_data.get("hp_delta", 0)
        if ev_data.get("torch_reduces_hp") and sup.get("torch", 0) > 0:
            hp_delta = int(hp_delta * 0.5)
            result_lines.append("🔦 <i>Факел помог укрыться — меньше урона</i>")
        m["hp_current"] = max(0, m["hp_current"] + hp_delta)
        if hp_delta < 0:
            result_lines.append(f"💔 <b>{hp_delta} HP</b>")

        # Потеря монет
        coins_pct = ev_data.get("coins_pct", 0.0)
        if coins_pct > 0:
            # Зелье: защита от кражи
            if ev_data.get("can_resist") and ev_data.get("resist_item") == "potion" \
                    and sup.get("potion", 0) > 0:
                coins_pct *= 0.5
                sup["potion"] -= 1
                m["supplies_json"] = json.dumps(sup)
                result_lines.append("🧪 <i>Зелье скрыло часть монет от разбойников</i>")
            lost = int(m["coins_taken"] * coins_pct)
            lost = max(0, min(lost, m["coins_taken"]))
            m["coins_lost"] = m.get("coins_lost", 0) + lost
            f["coins"] = max(0, f.get("coins", 0) - lost)
            if lost > 0:
                result_lines.append(f"💸 <b>-{lost}{_E_COIN}</b> (ограблен)")

        # Сжигание припасов
        supply_burn = ev_data.get("supply_burn", 0)
        for _ in range(supply_burn):
            available = [k for k, v in sup.items() if v > 0]
            if available:
                chosen_s = random.choice(available)
                sup[chosen_s] = max(0, sup[chosen_s] - 1)
                m["supplies_json"] = json.dumps(sup)
                result_lines.append(
                    f"{SUPPLY_TYPES[chosen_s]['emoji']} "
                    f"<i>Потерян 1 {SUPPLY_TYPES[chosen_s]['name']}</i>"
                )

        # Шанс смерти
        death_chance = ev_data.get("death_chance", 0.0)
        if ev_data.get("amulet_protects") and sup.get("amulet", 0) > 0:
            death_chance *= 0.5
            result_lines.append("🧿 <i>Амулет защитил от гибели</i>")

        died = False
        if death_chance > 0 and random.random() < death_chance:
            died = True
        if m["hp_current"] <= 0:
            died = True

        personal_result = "\n".join(result_lines) if result_lines else "<i>Ты выжил</i>"

        if died:
            full_text = (
                f"☠️ <b>Катастрофа тебя настигла, {name}!</b>\n\n"
                f"{personal_result}\n\n"
                f"💀 <i>Лягушка выбыла из экспедиции.</i>"
            )
            dead_names.append(name)
            await bot.send_message(m["user_id"], full_text, parse_mode=ParseMode.HTML)
            await _handle_member_death(bot, exp, m, f, "катастрофа")
        else:
            full_text = (
                f"😰 <b>Катастрофа! Ты пережил её, {name}.</b>\n\n"
                f"{personal_result}\n\n"
                f"❤️ Осталось: <b>{m['hp_current']} HP</b>"
            )
            await _expm_save(m)
            await db_save(f)
            await bot.send_message(m["user_id"], full_text, parse_mode=ParseMode.HTML)

    # Объявить погибших всем
    if dead_names:
        await _exp_broadcast(
            bot, exp_id,
            f"💀 <b>В катастрофе погибли:</b> {', '.join(he(n) for n in dead_names)}\n"
            f"<i>Выжившие продолжают путь...</i>",
        )

    # Если все погибли — завершаем экспедицию
    survivors = await _exp_get_active_members(exp_id)
    if not survivors:
        await _exp_finish(bot, exp, force_wipe=True)


async def _handle_member_death(bot, exp: dict, m: dict, f: dict, cause: str):
    """Обработать гибель участника."""
    exp_id = exp["id"]
    m["status"] = "dead"
    m["hp_current"] = 0
    await _expm_save(m)

    # Разблокировать лягушку
    f["adventure_locked_until"] = 0
    await db_save(f)

    # Монеты погибшего уходят выжившим
    lost_coins = int(m["coins_taken"] * 0.35)
    survivors = await _exp_get_active_members(exp_id)
    if survivors and lost_coins > 0:
        share = lost_coins // len(survivors)
        if share > 0:
            for sm in survivors:
                sf = await db_get(sm["user_id"])
                if sf:
                    sf["coins"] = sf.get("coins", 0) + share
                    sm["coins_gained"] = sm.get("coins_gained", 0) + share
                    await _expm_save(sm)
                    await db_save(sf)
            await _exp_broadcast(
                bot, exp_id,
                f"💸 <i>Монеты павшего товарища распределены: каждый получил +{share}🪙</i>",
            )
    # Уведомить выживших о гибели товарища
    # ВАЖНО: статус уже "dead", поэтому _exp_broadcast(only_alive=True) пропустит погибшего,
    # но и ВСЕМ остальным не дойдёт — потому что only_alive читает из БД заново.
    # Отправляем вручную только участникам со статусом "active".
    name = fname(f)
    death_msg = (
        f"💀 <b>{he(name)} пал{'а' if f.get('gender') == 'f' else ''} в экспедиции!</b>\n"
        f"<i>Причина: {he(cause)}</i>"
    )
    all_exp_members = await _exp_get_members(exp_id)
    for sm in all_exp_members:
        if sm["user_id"] == m["user_id"]:
            continue  # погибший уже получил личное сообщение
        if sm["status"] != "active":
            continue
        try:
            await bot.send_message(sm["user_id"], death_msg, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass
    logger.info("expedition member dead: exp=%s user=%s cause=%s", exp_id, m["user_id"], cause)



# ── РАЗВЕДКА: РАЗРЕШЕНИЕ ──────────────────────────────────────────────────────

async def _exp_resolve_scout(bot, exp: dict, ev: dict, scout_uid: int):
    """
    Подвести итог события-разведки.
    scout_uid — user_id выбранного разведчика.
    Итог случайный, взвешенный по outcomes.
    """
    ev_data = EXP_EVENT_CATALOG.get(ev["key"])
    if not ev_data:
        return
    exp_id = exp["id"]

    scout_m = await _expm_get(exp_id, scout_uid)
    scout_f = await db_get(scout_uid) if scout_m else None
    if not scout_m or not scout_f:
        return

    scout_name = fname(scout_f)

    # Выбор исхода по весам
    outcomes = ev_data.get("outcomes", [])
    if not outcomes:
        return
    weights = [o.get("weight", 1) for o in outcomes]
    outcome = random.choices(outcomes, weights=weights, k=1)[0]

    # ── Сообщение разведчику ──
    await bot.send_message(
        scout_uid,
        outcome["text_scout"],
        parse_mode=ParseMode.HTML,
    )

    # ── Применяем монеты разведчику ──
    coins_range = outcome.get("coins_scout", (0, 0))
    if isinstance(coins_range, tuple):
        lo, hi = coins_range
        coins_delta = random.randint(min(lo, hi), max(lo, hi))
    else:
        coins_delta = int(coins_range)

    # ── Применяем HP разведчику ──
    hp_range = outcome.get("hp_scout", 0)
    if isinstance(hp_range, tuple):
        lo, hi = hp_range
        hp_delta = random.randint(min(lo, hi), max(lo, hi))
    else:
        hp_delta = int(hp_range)

    scout_m["hp_current"] = max(0, min(100, scout_m["hp_current"] + hp_delta))
    scout_m["coins_gained"] = scout_m.get("coins_gained", 0) + max(0, coins_delta)
    if coins_delta < 0:
        scout_m["coins_lost"] = scout_m.get("coins_lost", 0) + abs(coins_delta)
    scout_m["contribution"] = scout_m.get("contribution", 0) + 1

    # Припас разведчику
    sup_info = outcome.get("supply_scout")
    if sup_info:
        stype, scount, schance = sup_info
        if random.random() < schance:
            sup = _sup(scout_m)
            sup[stype] = sup.get(stype, 0) + scount
            scout_m["supplies_json"] = json.dumps(sup)
            await bot.send_message(
                scout_uid,
                f"{SUPPLY_TYPES[stype]['emoji']} Нашёл <b>{scount} {SUPPLY_TYPES[stype]['name']}</b>!",
                parse_mode=ParseMode.HTML,
            )

    # Монеты scout_f
    scout_f["coins"] = scout_f.get("coins", 0) + coins_delta

    # Проверка смерти
    if scout_m["hp_current"] <= 0:
        await _handle_member_death(bot, exp, scout_m, scout_f, "разведка")
    else:
        await _expm_save(scout_m)
        await db_save(scout_f)

    # plog
    asyncio.create_task(plog(
        scout_uid, "scout",
        f"event={ev['key']} coins={coins_delta:+d} hp={hp_delta:+d}",
        coins_delta=coins_delta,
        hp_delta=hp_delta,
    ))

    # ── Сообщение команде ──
    team_text = outcome["text_team"].format(scout=he(scout_name))
    coins_line = f"\n💰 <b>{'+' if coins_delta >= 0 else ''}{coins_delta}🪙</b>" if coins_delta != 0 else ""
    hp_line = f"\n{'❤️' if hp_delta > 0 else '💔'} <b>{'+' if hp_delta >= 0 else ''}{hp_delta} HP</b>" if hp_delta != 0 else ""
    await _exp_broadcast(
        bot, exp_id,
        f"{team_text}{coins_line}{hp_line}",
        exclude_uid=scout_uid,
    )


# ── ГОЛОСОВАНИЕ: РАЗРЕШЕНИЕ ────────────────────────────────────────────────────

async def _exp_resolve_vote(bot, exp: dict, ev: dict):
    """Подвести итог командного голосования."""
    ev_data = EXP_EVENT_CATALOG[ev["key"]]
    exp_id = exp["id"]
    members = await _exp_get_active_members(exp_id)

    # Подсчёт голосов
    vote_counts: dict[str, int] = {}
    timeout_key = ev_data.get("timeout_key", ev_data["options"][0]["key"])
    for m in members:
        votes = _votes(m)
        v = votes.get(str(ev["idx"]))
        if v:
            vote_counts[v] = vote_counts.get(v, 0) + 1

    if not vote_counts:
        winner_key = timeout_key
        vote_info = "<i>Никто не проголосовал — выбран безопасный вариант.</i>"
    else:
        winner_key = max(vote_counts, key=vote_counts.get)
        total_v = sum(vote_counts.values())
        parts = []
        for opt in ev_data["options"]:
            n = vote_counts.get(opt["key"], 0)
            bar_v = "█" * n + "░" * (len(members) - n)
            parts.append(f"{opt['label']}: {bar_v} ({n}/{total_v})")
        vote_info = "\n".join(parts)

    chosen_opt = next(
        (o for o in ev_data["options"] if o["key"] == winner_key),
        ev_data["options"][0],
    )

    # Применяем результат к каждому участнику
    result_text = chosen_opt.get("text_result", "Решение принято.")
    bad = "bad_chance" in chosen_opt and random.random() < chosen_opt["bad_chance"]
    if bad:
        result_text = chosen_opt.get("text_bad", result_text)

    # ── Жертва: если команда выбрала «отдать одного» — голосуем кого именно ──
    sacrifice_victim_m = None
    if chosen_opt.get("sacrifice_random") and len(members) > 1:
        # Собираем голоса за жертву из personal_json (ключ "sacrifice_<ev_idx>")
        sac_votes: dict[int, int] = {}
        for mb in members:
            pers_mb = _personal(mb)
            sac_uid = pers_mb.get(f"sacrifice_{ev['idx']}")
            if sac_uid is not None:
                sac_votes[int(sac_uid)] = sac_votes.get(int(sac_uid), 0) + 1

        # Если голосов за жертву ещё нет — отправить второй раунд кнопок
        if not sac_votes:
            name_buttons = []
            for mb in members:
                f_mb = await db_get(mb["user_id"])
                if not f_mb:
                    continue
                name_buttons.append(
                    btn(f"🩸 {fname(f_mb)}",
                        callback_data=f"exp_sac_{exp['id']}_{ev['idx']}_{mb['user_id']}")
                )
            if name_buttons:
                kb_sac = InlineKeyboardMarkup([[b] for b in name_buttons])
                sac_text = (
                    "🩸 <b>Кого отдать племени?</b>\n\n"
                    "<i>Голосуй. Кто наберёт больше голосов — тот жертва.\n"
                    "При ничьей выбор случаен. У вас 5 минут.</i>"
                )
                await _exp_broadcast(bot, exp["id"], sac_text, reply_markup=kb_sac)
                # Помечаем событие как ожидающее выбора жертвы и выходим
                ev["awaiting_sacrifice"] = True
                return

        if sac_votes:
            victim_uid = max(sac_votes, key=sac_votes.get)
        else:
            victim_uid = random.choice(members)["user_id"]
        sacrifice_victim_m = next((mb for mb in members if mb["user_id"] == victim_uid), None)
        if sacrifice_victim_m is None:
            sacrifice_victim_m = random.choice(members)

    announce_lines = [
        f"🗳️ <b>Голосование завершено!</b>",
        f"\n{vote_info}\n",
        f"<b>Результат:</b> {he(result_text)}",
        "",
    ]

    # ── После основного цикла применяем урон жертве (sacrifice_random) ──
    # Сначала стандартный цикл по всем участникам (без урона жертве),
    # затем отдельно обрабатываем sacrifice_victim_m
    for m in members:
        f = await db_get(m["user_id"])
        if not f:
            continue

        result_lines: list[str] = []

        # Если этот участник — жертва sacrifice, пропускаем стандартный урон;
        # он получит свой урон после цикла
        is_sacrifice_victim = (
            sacrifice_victim_m is not None
            and m["user_id"] == sacrifice_victim_m["user_id"]
        )

        hp_delta = (0 if is_sacrifice_victim else
                    chosen_opt.get("hp_delta", 0) if not bad
                    else chosen_opt.get("bad_hp_delta", chosen_opt.get("hp_delta", 0)))
        coins_delta = (0 if is_sacrifice_victim else
                       chosen_opt.get("coins_delta", 0) if not bad
                       else chosen_opt.get("bad_coins_delta", chosen_opt.get("coins_delta", 0)))

        # Штраф за ресурс
        supply_cost = chosen_opt.get("supply_cost")
        if supply_cost and not bad:
            stype, scount = supply_cost
            sup = _sup(m)
            sname = SUPPLY_TYPES.get(stype, {}).get("name", stype)
            semoji = SUPPLY_TYPES.get(stype, {}).get("emoji", "📦")
            if sup.get(stype, 0) >= scount:
                sup[stype] -= scount
                m["supplies_json"] = json.dumps(sup)
                result_lines.append(
                    f"{semoji} <i>Использован 1 {sname}.</i>"
                )
            else:
                # Ресурса не хватило — засчитываем безопасный вариант
                timeout_key = ev_data.get("timeout_key")
                fallback_opt = next(
                    (o for o in ev_data.get("options", []) if o["key"] == timeout_key),
                    None,
                )
                result_lines.append(
                    f"⚠️ <i>Нет {semoji}{sname}! Команда автоматически выбрала безопасный вариант.</i>"
                )
                if fallback_opt:
                    hp_delta   = fallback_opt.get("hp_delta", 0)
                    coins_delta = fallback_opt.get("coins_delta", 0)
                    if fallback_opt.get("duration_add_m"):
                        result_lines.append(f"⏱ <i>+{fallback_opt['duration_add_m']} мин к экспедиции</i>")

        # Бонус монеты
        if not bad and "bonus_coins" in chosen_opt:
            coins_delta += random.randint(*chosen_opt["bonus_coins"])
        elif bad and "bad_supply_remove" in chosen_opt:
            stype, scount = chosen_opt["bad_supply_remove"]
            sup = _sup(m)
            sup[stype] = max(0, sup.get(stype, 0) - scount)
            m["supplies_json"] = json.dumps(sup)

        # luck_next
        if chosen_opt.get("luck_next") and not bad:
            pers = _personal(m)
            pers["luck_next"] = True
            m["personal_json"] = json.dumps(pers)

        m["hp_current"] = max(0, min(100, m["hp_current"] + hp_delta))
        m["coins_gained"] = m.get("coins_gained", 0) + max(0, coins_delta)
        if coins_delta < 0:
            m["coins_lost"] = m.get("coins_lost", 0) + abs(coins_delta)
        m["contribution"] = m.get("contribution", 0) + 1

        f["coins"] = f.get("coins", 0) + coins_delta
        await db_save(f)

        hp_note = f"💔 <b>{hp_delta} HP</b>" if hp_delta < 0 else (f"❤️ <b>+{hp_delta} HP</b>" if hp_delta > 0 else "")
        coins_note = f"💰 <b>+{coins_delta}🪙</b>" if coins_delta > 0 else (f"💸 <b>{coins_delta}🪙</b>" if coins_delta < 0 else "")
        personal_note = "\n".join(filter(None, [*result_lines, hp_note, coins_note]))
        if personal_note:
            announce_lines_personal = announce_lines + [personal_note]
        else:
            announce_lines_personal = announce_lines[:]

        # Всегда сохраняем участника
        if m["hp_current"] <= 0:
            await _handle_member_death(bot, exp, m, f, "голосование")
        else:
            await _expm_save(m)
            try:
                await bot.send_message(
                    m["user_id"],
                    "\n".join(announce_lines_personal),
                    parse_mode=ParseMode.HTML,
                )
            except (BadRequest, Forbidden, TimedOut):
                pass

    # ── Обработка sacrifice_victim: урон выбранной жертве ────────────────
    if sacrifice_victim_m is not None:
        f_vic = await db_get(sacrifice_victim_m["user_id"])
        if f_vic:
            sac_hp = chosen_opt.get("sacrifice_hp", 0)
            sac_coins = chosen_opt.get("sacrifice_coins", 0)

            sacrifice_victim_m["hp_current"] = max(
                0, min(100, sacrifice_victim_m["hp_current"] + sac_hp)
            )
            if sac_coins < 0:
                loss = min(abs(sac_coins), sacrifice_victim_m["coins_taken"])
                sacrifice_victim_m["coins_lost"] = sacrifice_victim_m.get("coins_lost", 0) + loss
                f_vic["coins"] = max(0, f_vic.get("coins", 0) - loss)
                sac_coins = -loss
            sacrifice_victim_m["contribution"] = sacrifice_victim_m.get("contribution", 0) + 1

            vic_name = fname(f_vic)
            sac_hp_note = f"💔 <b>{sac_hp} HP</b>" if sac_hp < 0 else ""
            sac_coins_note = f"💸 <b>{sac_coins}🪙</b>" if sac_coins < 0 else ""
            vic_personal = "\n".join(filter(None, [
                f"🩸 <b>Команда выбрала тебя в качестве жертвы.</b>",
                sac_hp_note, sac_coins_note,
                f"❤️ Осталось: <b>{sacrifice_victim_m['hp_current']} HP</b>",
            ]))

            if sacrifice_victim_m["hp_current"] <= 0:
                await _handle_member_death(bot, exp, sacrifice_victim_m, f_vic, "жертвоприношение")
            else:
                await _expm_save(sacrifice_victim_m)
                await db_save(f_vic)
                try:
                    await bot.send_message(
                        sacrifice_victim_m["user_id"], vic_personal,
                        parse_mode=ParseMode.HTML,
                    )
                except (BadRequest, Forbidden, TimedOut):
                    pass

            # Анонс всем кто пожертвован
            await _exp_broadcast(
                bot, exp["id"],
                f"🩸 <b>{he(vic_name)}</b> выбрана жертвой командой."
                + (f" {sac_hp_note}" if sac_hp_note else "")
                + " Остальные прошли без потерь.",
            )

    # Общий итог в чат экспедиции (групповой анонс)
    group_result = "\n".join(announce_lines[:4])  # заголовок + результат
    await _exp_broadcast(bot, exp["id"], group_result)
    ev["resolved"] = True


# ── ФИНАЛ ЭКСПЕДИЦИИ ──────────────────────────────────────────────────────────

async def _exp_finish(bot, exp: dict, force_wipe: bool = False):
    """Завершить экспедицию, разослать итоги, начислить награды."""
    exp_id = exp["id"]
    all_members = await _exp_get_members(exp_id)
    survivors = [m for m in all_members if m["status"] == "active"]
    dead = [m for m in all_members if m["status"] == "dead"]
    biome_cfg = EXP_BIOMES[exp["biome"]]
    now = time.time()

    exp["status"] = "finished"
    exp["finished_at"] = now

    # Бонус за чистое прохождение (все выжили)
    clean_bonus = 0
    if len(dead) == 0 and len(survivors) >= EXP_MIN_PLAYERS:
        clean_bonus = int(50 * biome_cfg["coin_mult"])

    # Бонус за командность (разослан позже в персональном итоге)
    xp_base = biome_cfg["xp_reward"]

    # ── Разблокировать тех, кто покинул экспедицию досрочно ─────────
    for m in all_members:
        if m["status"] == "left":
            f_left = await db_get(m["user_id"])
            if f_left:
                f_left["adventure_locked_until"] = 0
                f_left["last_expedition"] = 0
                await db_save(f_left)

    # ── Персональный итог каждому ────────────────────────────────
    stats_list = []
    for m in all_members:
        # Пропускаем тех, кто добровольно покинул экспедицию — они уже получили разблокировку
        if m["status"] == "left":
            continue
        f = await db_get(m["user_id"])
        if not f:
            continue
        name = fname(f)
        is_alive = m["status"] == "active"

        coins_net = m["coins_gained"] - m["coins_lost"]
        total_coins = m["coins_taken"] + coins_net

        # XP только выжившим
        xp_earned = xp_base if is_alive else (xp_base // 3)
        # Предатель получает -10% XP (но монеты уже украдены)
        if m.get("betrayal_done"):
            xp_earned = int(xp_earned * 0.9)

        # Бонус за чистое прохождение — только выжившим
        if is_alive and clean_bonus:
            total_coins += clean_bonus
            f["coins"] = f.get("coins", 0) + clean_bonus

        add_xp(f, xp_earned)
        # Убираем блокировку
        f["adventure_locked_until"] = 0
        await levelup(f, bot)
        await db_save(f)
        asyncio.create_task(plog(
            m["user_id"], "expedition_end",
            f"biome={exp['biome']} alive={is_alive} coins_net={coins_net} xp={xp_earned} contrib={m['contribution']}",
            coins_delta=coins_net,
        ))

        contribution_emoji = (
            "🥇" if m["contribution"] >= 8 else
            "🥈" if m["contribution"] >= 5 else
            "🥉" if m["contribution"] >= 3 else "🌱"
        )

        outcome_line = (
            "✅ <b>Выжила!</b>" if is_alive else
            "💀 <b>Погибла в экспедиции</b>"
        )

        betrayal_line = ""
        if m.get("betrayal_done"):
            betrayal_line = "\n🗡️ <i>Ты предал(а) союзника в темноте.</i>"
        if m.get("betrayal_count", 0) > 0:
            betrayal_line += f"\n😤 <i>Тебя предали {m['betrayal_count']} раз(а).</i>"

        clean_line = f"\n✨ <b>Бонус чистого прохождения: +{clean_bonus}🪙</b>" if (is_alive and clean_bonus) else ""

        # Разбивка источников монет
        pers_final = _personal(m)
        earned_events   = pers_final.get("earned_events", 0)
        stolen_by_me    = pers_final.get("stolen_by_me", 0)
        survival_bonus  = clean_bonus if is_alive else 0
        # Если детали не трекаются отдельно — просто показываем сумму
        coins_breakdown = ""
        if stolen_by_me > 0:
            coins_breakdown += f"\n   ├ события: +{m['coins_gained'] - stolen_by_me}🪙"
            coins_breakdown += f"\n   └ украдено у союзника: +{stolen_by_me}🪙 🗡️"
        if survival_bonus > 0:
            coins_breakdown += f"\n   └ бонус выживания: +{survival_bonus}🪙 ✨"

        # Источники потерь
        lost_breakdown = ""
        betrayal_lost = pers_final.get("betrayal_lost", 0)
        if betrayal_lost > 0:
            lost_breakdown += f"\n   └ украли у тебя: -{betrayal_lost}🪙 😤"

        personal_text = (
            f"🏁 <b>Экспедиция завершена!</b>\n"
            "\n"
            f"{outcome_line}\n\n"
            f"{_E_CHART} <b>Личная статистика:</b>\n"
            f"💰 Взял(а) с собой: {m['coins_taken']}🪙\n"
            f"💎 Заработано: +{m['coins_gained']}🪙{coins_breakdown}\n"
            f"💸 Потеряно: -{m['coins_lost']}🪙{lost_breakdown}\n"
            "\n"
            f"🪙 Итого монет: <b>{max(0, total_coins)}🪙</b>\n"
            f"{_E_XP} Получено XP: <b>+{xp_earned}</b>\n"
            f"{contribution_emoji} Вклад: <b>{m['contribution']} действий</b>"
            f"{clean_line}"
            f"{betrayal_line}"
        )
        try:
            await bot.send_message(m["user_id"], personal_text, parse_mode=ParseMode.HTML)
        except (BadRequest, Forbidden, TimedOut):
            pass

        stats_list.append({
            "user_id": m["user_id"],
            "name": name,
            "alive": is_alive,
            "coins_net": coins_net,
            "contribution": m["contribution"],
            "betrayal": bool(m.get("betrayal_done")),
        })

    # ── Публичный анонс итогов ───────────────────────────────────
    total_betrayals = sum(1 for m in all_members if m.get("betrayal_done"))
    survivor_names = [s["name"] for s in stats_list if s["alive"]]
    dead_names = [s["name"] for s in stats_list if not s["alive"]]

    if force_wipe or not survivors:
        ending = random.choice(EXP_DEFEAT_TEXTS)
    elif dead:
        ending = random.choice(EXP_PARTIAL_TEXTS)
    else:
        ending = random.choice(EXP_VICTORY_TEXTS)

    pub_lines = [
        f"🗺️ <b>Экспедиция завершена!</b>\n"
        f"{biome_cfg['emoji']} {biome_cfg['name']}\n\n"
        f"{ending}\n\n"
    ]
    if survivor_names:
        pub_lines.append(f"{_E_CHECK} <b>Выжили:</b> {', '.join(he(n) for n in survivor_names)}")
    if dead_names:
        pub_lines.append(f"{_E_SKULL} <b>Погибли:</b> {', '.join(he(n) for n in dead_names)}")
    if total_betrayals > 0:
        pub_lines.append(f"\n🗡️ <i>В этой экспедиции произошло {total_betrayals} предательств...</i>")

    await announce(bot, "\n".join(pub_lines), delete_after=0)

    # Сохранить финальную статистику
    exp["stats_json"] = json.dumps({"members": stats_list}, ensure_ascii=False)
    await _exp_save(exp)

    # Летопись
    if survivor_names:
        await letopis_add(
            exp["creator_id"], "staya_win",
            f"🗺️ Экспедиция «{biome_cfg['name']}» завершена: "
            f"{len(survivors)}/{len(all_members)} выжили!"
        )
    logger.info("expedition finished id=%s survivors=%s/%s", exp_id, len(survivors), len(all_members))


